import * as THREE from 'three';
import { N, type World } from '../../world/tiles';
import type { LandDef } from '../vehicles';
import { landRoute } from '../traffic';
import { KIND_OF } from './kinds';
import type { Happening } from './calendar';
import { mid, type Place, type Pt } from './venues';
import { Crowd, Rig, Way, block, dressed, flat, waterY } from './props';
import { HOUR_S, Show, clamp01, toWorld, u01, type ShowCtx } from './shows';

/**
 * The races of phase 3 (docs/events.html): a rally across open country, powerboats round the buoys, a night
 * drift meet, dragon boats and gondolas. The field races on the clock everyone shares; a player who wants a go
 * takes the entry offered at the start's diamond (game/missions/eventTemplates.ts) and races a rival of their own.
 */

const TEAM = [0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf2c14e, 0xf28c38, 0x8e5cc7, 0xf4f2ec, 0x2a2a2e];

/** A banner over a way: two poles and a cloth across, turned to face along `yaw`. */
function banner(g: THREE.Object3D, ctx: ShowCtx, p: Pt, yaw: number, colour: number, wide = 1.4): void {
  const sx = Math.cos(yaw), sz = -Math.sin(yaw);
  for (const s of [-1, 1]) {
    const x = p.x + sx * s * wide / 2, z = p.z + sz * s * wide / 2;
    block(g, x, ctx.ground(x, z), z, 0.03, 0.55, 0.03, 0xdddddd);
  }
  const y = ctx.ground(p.x, p.z);
  block(g, p.x, y + 0.42, p.z, wide, 0.13, 0.02, colour, yaw);
  block(g, p.x, y + 0.455, p.z, wide * 0.98, 0.03, 0.025, 0xffffff, yaw);
}

/** A checkpoint's flag: a pole with a pennant. */
function flag(g: THREE.Object3D, ctx: ShowCtx, p: Pt, colour: number): void {
  const y = ctx.ground(p.x, p.z);
  block(g, p.x, y, p.z, 0.02, 0.5, 0.02, 0xdddddd);
  block(g, p.x + 0.07, y + 0.4, p.z, 0.14, 0.09, 0.01, colour);
}

// ---- the rally ---------------------------------------------------------------------------------------------------

/**
 * Eight racers in team colours line up at a banner on a country road, launch together and fan out across the
 * land, each on its own terrain-fastest line through the flagged checkpoints to the finish, trailing dust, a news
 * helicopter over the leader; the first three park at the podium.
 */
export class RallyShow extends Show {
  private racers: { rig: Rig; way: Way | null; time: number; done: boolean }[] = [];
  private course: Pt[];
  private planned = 0;
  private crowd: Crowd;
  private heli: Rig;
  private heliPos = new THREE.Vector3(NaN, 0, 0);

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    this.course = place.course!.map((p) => toWorld(w, p));
    const ids = ['atv', 'humvee', 'sandy', 'stomper', 'mule', 'atv', 'sandy', 'humvee'];
    ids.forEach((id, i) => this.racers.push({ rig: new Rig(this.g, dressed(id, TEAM[i], TEAM[(i + 3) % TEAM.length])), way: null, time: 1.25 * (0.88 + u01(e.h, 60 + i) * 0.26), done: false }));
    const [a, b] = this.course;
    const yaw = Math.atan2(b.x - a.x, b.z - a.z);
    banner(this.g, ctx, a, yaw, 0xe2412f);
    banner(this.g, ctx, this.course[this.course.length - 1], yaw, 0x2a2a2e);
    for (const p of this.course.slice(1, -1)) { flag(this.g, ctx, { x: p.x - 0.4, z: p.z }, 0xe2412f); flag(this.g, ctx, { x: p.x + 0.4, z: p.z }, 0xf2c14e); }
    // the podium beside the finish
    const f = this.course[this.course.length - 1], px = f.x + Math.cos(yaw) * 2.2, pz = f.z - Math.sin(yaw) * 2.2, gy = ctx.ground(px, pz);
    [[0, 0.16, 0xd9b34a], [-0.45, 0.11, 0xc0c4c8], [0.45, 0.07, 0xb07a4a]].forEach(([u, h, c]) => block(this.g, px + Math.cos(yaw) * u, gy, pz - Math.sin(yaw) * u, 0.4, h, 0.4, c, yaw));
    // the crowd: at the start, and at the finish
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (let i = 0; i < 48; i++) {
      const at = i < 20 ? a : f, ang = u01(e.h, 200 + i) * Math.PI * 2, r = 1.6 + u01(e.h, 300 + i) * 1.6;
      this.crowd.add(at.x + Math.cos(ang) * r, at.z + Math.sin(ang) * r);
    }
    this.heli = new Rig(this.g, dressed('dragonfly', 0xf4f2ec));
    this.heli.hide();
  }

  centre(): Pt | null { return this.course[Math.floor(this.course.length / 2)]; }

  /** One racer's line a frame: its own way between the checkpoints, the start staggered across the road. */
  private plan(): void {
    if (this.planned >= this.racers.length) return;
    const i = this.planned++, r = this.racers[i];
    const def = r.rig.def as LandDef;
    const pts: Pt[] = [];
    const C = this.course;
    for (let k = 1; k < C.length; k++) {
      const a = k === 1 ? { x: C[0].x + ((i % 4) - 1.5) * 0.4, z: C[0].z + ((i % 4) - 1.5) * 0.4 } : C[k - 1], b = C[k];
      const w = this.ctx.worldAt(Math.floor(a.x / N), Math.floor(a.z / N));
      const leg = w && w === this.ctx.worldAt(Math.floor(b.x / N), Math.floor(b.z / N)) ? landRoute(w, def, a.x - w.ox, a.z - w.oz, b.x - w.ox, b.z - w.oz, new Set(), false, 40000) : null;
      if (leg) pts.push(...(k === 1 ? [a] : []), ...leg.map((p) => ({ x: w!.ox + p.x, z: w!.oz + p.z })));
      else pts.push(a, b);
    }
    r.way = new Way(pts);
  }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.offroadRace;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    this.plan();
    const t = now - e.start;
    const atStart = clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((t - 0.3) / 0.3));
    const atFinish = clamp01((t - 0.6) / 0.4) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.crowd.shown = Math.round(20 * atStart) + (atFinish > 0 ? 20 + Math.round(28 * atFinish) : 0);
    this.crowd.cheer = t > 0 && t < 0.15 ? 1 : t > 1 && t < 1.6 ? 0.8 : 0;
    this.crowd.update(dt);
    let lead: Pt | null = null, best = -1;
    const yaw = Math.atan2(this.course[1].x - this.course[0].x, this.course[1].z - this.course[0].z);
    const finished = this.racers.filter((r) => t >= r.time).sort((a, b) => a.time - b.time);
    this.racers.forEach((r, i) => {
      if (!r.way) { r.rig.hide(); return; }
      if (t < 0) {
        // on the grid: two rows behind the banner
        const back = 0.9 + Math.floor(i / 4) * 1.3, across = ((i % 4) - 1.5) * 0.55;
        const s = this.course[0];
        r.rig.place(this.ctx.worldAt, s.x - Math.sin(yaw) * back + Math.cos(yaw) * across, s.z - Math.cos(yaw) * back - Math.sin(yaw) * across, yaw, 0, dt);
        return;
      }
      const f = clamp01(t / r.time);
      if (f >= 1) {
        // home: the first three parked behind the podium in their order, the rest along from it
        const k = finished.indexOf(r), fin = this.course[this.course.length - 1];
        const u = 2.2 + (k < 3 ? [0, -0.45, 0.45][k] : 1.1 + (k - 3) * 0.7);
        r.rig.place(this.ctx.worldAt, fin.x + Math.cos(yaw) * u + Math.sin(yaw) * 1.1, fin.z - Math.sin(yaw) * u + Math.cos(yaw) * 1.1, yaw + Math.PI, 0, dt);
        return;
      }
      // a little faster in the middle of a leg, easing into the checkpoints
      const p = r.way.at(f * r.way.length);
      const v = r.way.length / (r.time * HOUR_S);
      r.rig.place(this.ctx.worldAt, p.x, p.z, p.heading, v, dt);
      if (Math.random() < dt * 10) this.ctx.particles.puff({ x: p.x - Math.sin(p.heading) * 0.4, y: r.rig.state.y + 0.05, z: p.z - Math.cos(p.heading) * 0.4, vx: 0, vy: 0.15, vz: 0, life: 2.5, colour: 0xc9b48a, size: 0.32, alpha: 0.55 });
      if (f > best) { best = f; lead = p; }
    });
    // the news helicopter over the leader
    if (lead) {
      const L = lead as Pt, gy = this.ctx.ground(L.x, L.z) + 5;
      if (Number.isNaN(this.heliPos.x)) this.heliPos.set(L.x, gy, L.z - 4);
      const k = Math.min(1, dt * 0.9), dx = L.x - this.heliPos.x, dz = L.z - 3 - this.heliPos.z;
      this.heliPos.x += dx * k; this.heliPos.z += dz * k; this.heliPos.y += (gy - this.heliPos.y) * k;
      this.heli.fly(this.heliPos.x, this.heliPos.y, this.heliPos.z, Math.atan2(dx, dz + 3), -0.08, 0, dt);
    } else this.heli.hide();
  }

  dispose(): void { for (const r of this.racers) r.rig.dispose(); this.heli.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- the powerboats ---------------------------------------------------------------------------------------------------

/** Speedboats racing laps of a buoy course, rooster tails of spray behind them, the shore lined with people. */
export class PowerboatShow extends Show {
  private loop: Way;
  private boats: { rig: Rig; time: number }[] = [];
  private crowd: Crowd;
  private static readonly LAPS = 4;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const marks = place.course!.map((p) => toWorld(w, p));
    const c = marks.reduce((s, p) => ({ x: s.x + p.x / marks.length, z: s.z + p.z / marks.length }), { x: 0, z: 0 });
    // the line round the marks, wide of each by a tile and a half
    const pts = marks.map((p) => { const d = Math.hypot(p.x - c.x, p.z - c.z) || 1; return new THREE.Vector3(p.x + ((p.x - c.x) / d) * 1.5, 0, p.z + ((p.z - c.z) / d) * 1.5); });
    const curve = new THREE.CatmullRomCurve3(pts, true, 'centripetal');
    const way = curve.getSpacedPoints(90).map((v) => ({ x: v.x, z: v.z }));
    this.loop = new Way(way);
    for (const m of marks) { const y = waterY(ctx, m.x, m.z); const b = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.11, 0.26, 8), flat(0xff6a13, 0.25)); b.position.set(m.x, y + 0.09, m.z); this.g.add(b); }
    ['splash', 'defender', 'splash', 'defender', 'splash', 'defender'].forEach((id, i) => this.boats.push({ rig: new Rig(this.g, dressed(id, TEAM[i])), time: 1.5 * (0.9 + u01(e.h, 40 + i) * 0.2) }));
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { const r = this.place.water!; return { x: this.w.ox + (r.x0 + r.x1) / 2, z: this.w.oz + (r.z0 + r.z1) / 2 }; }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.powerboatRace;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const t = now - e.start, L = this.loop.length, laps = PowerboatShow.LAPS;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.2)) / 0.2));
    this.crowd.cheer = t > 0 && t < 1.6 ? 0.6 : 0;
    this.crowd.update(dt);
    this.boats.forEach((b, i) => {
      const f = t < 0 ? 0 : clamp01(t / b.time);
      // in the start's line abreast, then round and round, then idling at the line
      const s = (f * laps * L + (t < 0 || f >= 1 ? -i * 0.9 : 0)) % L;
      const p = this.loop.at((s + L) % L);
      const v = f > 0 && f < 1 ? (laps * L) / (b.time * HOUR_S) : 0;
      const nx = Math.cos(p.heading), nz = -Math.sin(p.heading), lane = ((i % 3) - 1) * 0.35;
      b.rig.float(this.ctx.worldAt, p.x + nx * lane, p.z + nz * lane, p.heading, v, dt);
      if (v > 0 && Math.random() < dt * 30) {
        const fx = Math.sin(p.heading), fz = Math.cos(p.heading);
        this.ctx.particles.spark({ x: p.x + nx * lane - fx * 0.5, y: b.rig.state.y + 0.1, z: p.z + nz * lane - fz * 0.5, vx: -fx * 1.4 + (Math.random() - 0.5) * 0.3, vy: 1.6 + Math.random() * 0.5, vz: -fz * 1.4 + (Math.random() - 0.5) * 0.3, life: 0.7, colour: 0xa9c9de, size: 0.08, gravity: 3.2, drag: 0.6 });
      }
    });
  }

  dispose(): void { for (const b of this.boats) b.rig.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- the drift meet ---------------------------------------------------------------------------------------------------

/** Drifters sliding a figure of eight round two cone marks on a city's lot after dark, tyre smoke under the floodlights, a crowd round the edge. */
export class DriftShow extends Show {
  private cars: Rig[] = [];
  private crowd: Crowd;
  private c: Pt;
  private a: number;
  private yaw: number;

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    const lot = place.lot!;
    this.c = toWorld(w, mid(lot));
    const long = lot.w >= lot.d;
    this.a = Math.max(1.2, (long ? lot.w : lot.d) / 2 - 0.7);
    this.yaw = long ? 0 : Math.PI / 2;
    ['wasabi', 'sunny', 'zippy', 'marquee'].forEach((id, i) => this.cars.push(new Rig(this.g, dressed(id, TEAM[(i * 3) % TEAM.length]))));
    // the marks: a cone at the heart of each loop, and floodlights at the lot's corners
    const gy = ctx.ground(this.c.x, this.c.z);
    for (const s of [-1, 1]) {
      const p = this.at(s > 0 ? Math.PI / 2 : -Math.PI / 2, 0.45);
      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.16, 8), flat(0xff6a13));
      cone.position.set(p.x, gy + 0.08, p.z);
      this.g.add(cone);
    }
    for (const [u, v] of [[0, 0], [1, 0], [0, 1], [1, 1]]) {
      const x = w.ox + lot.x + u * lot.w, z = w.oz + lot.z + v * lot.d, y = ctx.ground(x, z);
      block(this.g, x, y, z, 0.03, 0.9, 0.03, 0x5a5f66);
      block(this.g, x, y + 0.88, z, 0.14, 0.06, 0.1, 0xffffff, 0, 3);
    }
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (let i = 0; i < 44; i++) {
      // round the edge of the lot, just off it
      const k = u01(e.h, 500 + i) * 4, side = Math.floor(k), f = k - side;
      const x = lot.x + (side === 0 ? f * lot.w : side === 1 ? lot.w + 0.3 : side === 2 ? f * lot.w : -0.3);
      const z = lot.z + (side === 0 ? -0.3 : side === 1 ? f * lot.d : side === 2 ? lot.d + 0.3 : f * lot.d);
      this.crowd.add(w.ox + x, w.oz + z);
    }
  }

  /** A point on the figure of eight at angle `t` (Gerono's lemniscate), scaled by `k`. */
  private at(t: number, k = 1): Pt {
    const u = this.a * Math.sin(t) * k, v = this.a * 0.55 * Math.sin(t) * Math.cos(t) * k;
    const c = Math.cos(this.yaw), s = Math.sin(this.yaw);
    return { x: this.c.x + u * c - v * s, z: this.c.z + u * s + v * c };
  }

  centre(): Pt | null { return this.c; }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.driftMeet;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const running = now >= e.start && now < e.end - 0.2;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead);
    this.crowd.cheer = running ? 0.5 : 0;
    this.crowd.update(dt);
    const t = performance.now() / 1000;
    this.cars.forEach((r, i) => {
      if (!running) {
        // lined up along the lot's edge, waiting their turn
        const p = this.at(-Math.PI / 2 + i * 0.12, 1.15);
        r.place(this.ctx.worldAt, p.x, p.z, this.yaw, 0, dt);
        return;
      }
      const th = t * 0.9 + (i * Math.PI) / 2;
      const p = this.at(th), q = this.at(th + 0.02);
      const head = Math.atan2(q.x - p.x, q.z - p.z);
      // into the turn: the tail hung out the way the loop bends
      const bend = Math.sign(Math.sin(th) * Math.cos(th) || 1) * Math.sign(Math.cos(th));
      r.place(this.ctx.worldAt, p.x, p.z, head + bend * 0.55, 2.4, dt);
      if (Math.random() < dt * 14) this.ctx.particles.puff({ x: p.x - Math.sin(head) * 0.35, y: r.state.y + 0.06, z: p.z - Math.cos(head) * 0.35, vx: 0, vy: 0.2, vz: 0, life: 2.2, colour: 0xb4b4bc, size: 0.34, alpha: 0.32 });
    });
  }

  dispose(): void { for (const r of this.cars) r.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- dragon boats ---------------------------------------------------------------------------------------------------

const DRAGON = [0xd52b1e, 0x1f8a4c, 0xf2b632, 0x1f4e9e];
const PADDLERS = 10;

/** A dragon boat: a long hull in its colour with a gilded dragon's head at the bow and a tail at the stern. */
class DragonBoat {
  readonly root = new THREE.Group();
  constructor(parent: THREE.Object3D, colour: number) {
    const hull = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.06, 1.3), flat(colour));
    hull.position.y = 0.03;
    const neck = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.14, 0.06), flat(0xd9b34a));
    neck.position.set(0, 0.1, 0.66);
    neck.rotation.x = -0.4;
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.16, 6), flat(0xd9b34a));
    head.rotation.x = Math.PI / 2;
    head.position.set(0, 0.17, 0.74);
    const tail = new THREE.Mesh(new THREE.ConeGeometry(0.04, 0.18, 5), flat(colour));
    tail.rotation.x = -Math.PI / 3;
    tail.position.set(0, 0.1, -0.7);
    this.root.add(hull, neck, head, tail);
    parent.add(this.root);
  }
  set visible(v: boolean) { this.root.visible = v; }
}

/**
 * Dragon boat heats on a straight course by a Chinese, Southeast Asian or Japanese town: four boats abreast, ten
 * paddlers each digging in time, a drummer at the bow; three heats one after another, the crowd on the shore.
 */
export class DragonBoatsShow extends Show {
  private boats: DragonBoat[] = [];
  private lanes: [Pt, Pt][] = [];
  private paddlers: THREE.InstancedMesh;
  private crowd: Crowd;
  private m = new THREE.Matrix4();
  private static readonly HEAT = 0.55;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const c = place.course!.map((p) => toWorld(w, p));
    for (let k = 0; k < 4; k++) this.lanes.push([c[k * 2], c[k * 2 + 1]]);
    for (let k = 0; k < 4; k++) this.boats.push(new DragonBoat(this.g, DRAGON[k]));
    this.paddlers = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.035, 1), flat(0xf4f2ec), 4 * (PADDLERS + 1));
    this.paddlers.frustumCulled = false;
    const col = new THREE.Color();
    for (let i = 0; i < 4 * (PADDLERS + 1); i++) this.paddlers.setColorAt(i, col.setHex(i % (PADDLERS + 1) === PADDLERS ? 0xd52b1e : DRAGON[Math.floor(i / (PADDLERS + 1))]).offsetHSL(0, -0.2, 0.25));
    this.g.add(this.paddlers);
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { const r = this.place.water!; return { x: this.w.ox + (r.x0 + r.x1) / 2, z: this.w.oz + (r.z0 + r.z1) / 2 }; }

  update(now: number, dt: number): void {
    void dt;
    const e = this.e, spec = KIND_OF.dragonBoats;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const t = now - e.start, H = DragonBoatsShow.HEAT;
    const heat = Math.max(0, Math.min(2, Math.floor(t / (H + 0.15))));
    const into = t - heat * (H + 0.15);
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.2)) / 0.2));
    this.crowd.cheer = into > 0 && into < H ? 0.8 : 0.1;
    this.crowd.update(dt);
    const beat = performance.now() / 1000 * 5.5;
    let n = 0;
    this.boats.forEach((b, k) => {
      const [a, z] = this.lanes[k];
      const pace = 0.85 + u01(e.h, heat * 10 + k) * 0.25;
      const f = t < 0 ? 0 : clamp01((into / H) * pace * 1.12);
      const x = a.x + (z.x - a.x) * f, zz = a.z + (z.z - a.z) * f, y = waterY(this.ctx, x, zz);
      const head = Math.atan2(z.x - a.x, z.z - a.z);
      b.root.position.set(x, y, zz);
      b.root.rotation.set(0, head, Math.sin(beat + k) * 0.02);
      // the paddlers in two rows, leaning in time with the drum; the drummer at the bow
      const fx = Math.sin(head), fz = Math.cos(head), sx = Math.cos(head), sz = -Math.sin(head);
      const dig = f > 0 && f < 1 ? Math.sin(beat) * 0.03 : 0;
      for (let i = 0; i < PADDLERS; i++) {
        const along = -0.45 + (Math.floor(i / 2) / (PADDLERS / 2 - 1)) * 0.9 + dig, side = (i % 2 ? 1 : -1) * 0.055;
        this.m.makeTranslation(x + fx * along + sx * side, y + 0.08, zz + fz * along + sz * side);
        this.paddlers.setMatrixAt(n++, this.m);
      }
      this.m.makeTranslation(x + fx * 0.56, y + 0.1 + Math.abs(Math.sin(beat * 2)) * 0.02, zz + fz * 0.56);
      this.paddlers.setMatrixAt(n++, this.m);
    });
    this.paddlers.count = n;
    this.paddlers.instanceMatrix.needsUpdate = true;
  }

  dispose(): void { this.crowd.dispose(); super.dispose(); }
}

// ---- the gondola regatta ---------------------------------------------------------------------------------------------------

/** A gondola: a long black hull curling up at both ends, a gondolier in stripes at the stern with the oar. */
class Gondola {
  readonly root = new THREE.Group();
  private oar = new THREE.Group();
  constructor(parent: THREE.Object3D, trim: number) {
    const hull = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.05, 0.85), flat(0x15161a));
    hull.position.y = 0.025;
    const bow = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.16, 0.05), flat(0xd9d2b0));
    bow.position.set(0, 0.1, 0.43);
    const stern = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.1, 0.05), flat(0x15161a));
    stern.position.set(0, 0.07, -0.43);
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.1, 0.04), flat(trim));
    body.position.set(0, 0.1, -0.3);
    const head = new THREE.Mesh(new THREE.IcosahedronGeometry(0.03, 1), flat(0xe8c3a0));
    head.position.set(0, 0.18, -0.3);
    const oarStick = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.012, 0.42), flat(0x8a5a2b));
    oarStick.position.set(0.04, 0, -0.1);
    this.oar.add(oarStick);
    this.oar.position.set(0.04, 0.13, -0.3);
    this.oar.rotation.x = 0.6;
    this.root.add(hull, bow, stern, body, head, this.oar);
    parent.add(this.root);
  }
  row(t: number): void { this.oar.rotation.y = Math.sin(t) * 0.35; }
}

/** Gondolas racing the canals of a Venice, rowed hard, the banks and the bridges full of people. */
export class GondolaShow extends Show {
  private way: Way;
  private boats: { g: Gondola; time: number }[] = [];
  private crowd: Crowd;

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    this.way = new Way(place.path!.map((p) => toWorld(w, p)));
    for (let i = 0; i < 6; i++) this.boats.push({ g: new Gondola(this.g, i % 2 ? 0xd52b1e : 0x1f4e9e), time: 1.3 * (0.88 + u01(e.h, 70 + i) * 0.24) });
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { return this.way.at(this.way.length / 2); }

  update(now: number, dt: number): void {
    void dt;
    const e = this.e, spec = KIND_OF.gondolaRegatta;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const t = now - e.start, L = this.way.length;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.2)) / 0.2));
    this.crowd.cheer = t > 0 && t < 1.4 ? 0.7 : 0;
    this.crowd.update(dt);
    const clock = performance.now() / 1000;
    this.boats.forEach((b, i) => {
      const f = t < 0 ? 0 : clamp01(t / b.time);
      // one behind another in the narrow canal, a boat's length apart, until they spread out
      const s = Math.max(0, f * L - (f < 0.15 ? (5 - i) * 0 : 0) - i * 1.1 * (1 - f));
      const p = this.way.at(Math.min(L, s));
      const y = waterY(this.ctx, p.x, p.z);
      b.g.root.position.set(p.x, y, p.z);
      b.g.root.rotation.set(0, p.heading, 0);
      b.g.row(f > 0 && f < 1 ? clock * 4 + i : 0);
    });
  }

  dispose(): void { this.crowd.dispose(); super.dispose(); }
}

