import * as THREE from 'three';
import { N, CHUNK, World, RoadType, DIRS, heightAt, type Bridge, type Road } from '../world/tiles';
import { blockHalf, deckHeightAt, dirBetween, nodeCenter, shapeOf } from '../world/roads';
import { hex, scale, type RGB } from '../world/biomes';
import { designOf, type BridgeDesign } from '../world/bridgeDesigns';
import { SolidBuf } from './lamps';

type P3 = [number, number, number];

/**
 * One look per road type: a wooden trestle for dirt lanes, stone for paved lanes, a concrete girder
 * bridge with steel railings for two lanes, and a twin-pier viaduct (cable-stayed on long spans)
 * for highways. Those are the "standard" design; the famous ones (world/bridgeDesigns.ts) are drawn
 * over the same deck and railings by their own functions further down.
 */
interface Style { width: number; thick: number; deck: RGB; rail: RGB; railH: number; railT: number; pier: 'timber' | 'stone' | 'column' | 'twin' }
const STYLES: Record<Exclude<RoadType, RoadType.None>, Style> = {
  [RoadType.Dirt]: { width: 0.72, thick: 0.07, deck: hex(0x8a6440), rail: hex(0x6e4f33), railH: 0.14, railT: 0.035, pier: 'timber' },
  [RoadType.Brick]: { width: 0.76, thick: 0.16, deck: hex(0xa8604a), rail: hex(0xcfc0a8), railH: 0.11, railT: 0.06, pier: 'stone' },
  [RoadType.Paved]: { width: 0.76, thick: 0.18, deck: hex(0xb9ae98), rail: hex(0xcbc1ab), railH: 0.1, railT: 0.07, pier: 'stone' },
  [RoadType.TwoLane]: { width: 1.06, thick: 0.14, deck: hex(0xbdb8ae), rail: hex(0x8d949b), railH: 0.1, railT: 0.025, pier: 'column' },
  [RoadType.FourLane]: { width: 2.08, thick: 0.2, deck: hex(0xb3aea4), rail: hex(0xc9c4b8), railH: 0.12, railT: 0.07, pier: 'twin' },
  [RoadType.Gravel]: { width: 0.7, thick: 0.07, deck: hex(0x9b8b72), rail: hex(0x6e4f33), railH: 0.14, railT: 0.035, pier: 'timber' },
  [RoadType.Cobble]: { width: 0.78, thick: 0.17, deck: hex(0x8f8577), rail: hex(0xcfc0a8), railH: 0.11, railT: 0.06, pier: 'stone' },
  [RoadType.Interstate]: { width: 3.06, thick: 0.24, deck: hex(0xb3aea4), rail: hex(0xc9c4b8), railH: 0.13, railT: 0.08, pier: 'twin' },
  [RoadType.Ramp]: { width: 0.62, thick: 0.16, deck: hex(0xbdb8ae), rail: hex(0x8d949b), railH: 0.1, railT: 0.025, pier: 'column' },
};
const TIMBER = hex(0x5e4630), CONCRETE = hex(0xc4bfb5), STONE = hex(0xa89e8a), PYLON = hex(0xe8e6e0), CABLE = hex(0x6b7178);
// the famous bridges' own colours: Sydney's grey steel and granite, Tower Bridge's Portland stone and
// pale blue, Millau's white, the Forth's red oxide, the Pont du Gard's honey limestone
const STEEL = hex(0x7d878e), GRANITE = hex(0xc2b59b), PORTLAND = hex(0xd3c7ab), SLATE = hex(0x4d5862), TOWER_BLUE = hex(0x7aa7cc);
const MILLAU = hex(0xf0eee8), STAY = hex(0xb4b9bd), FORTH = hex(0xb4402d), LIMESTONE = hex(0xd1b98c);
/** A Venice canal bridge's white Istrian stone and the brick between its rings. */
const ISTRIA = hex(0xeeeae0), BRICK_RED = hex(0xa85a44);

const ground = (w: World, x: number, z: number) => heightAt(w, Math.min(N - 0.001, Math.max(0, x)), Math.min(N - 0.001, Math.max(0, z)));

/** Deck slabs, railings, abutments and supports of every bridge whose pieces fall in this chunk. */
export function buildBridgeChunk(w: World, cx: number, cz: number): THREE.Mesh | null {
  const buf = new SolidBuf();
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  const inChunk = (x: number, z: number) => x >= x0 && x < x0 + CHUNK && z >= z0 && z < z0 + CHUNK;
  for (const r of w.roads) for (const br of r.bridges ?? []) drawBridge(buf, w, r, br, inChunk);
  const mesh = buf.mesh();
  if (mesh) mesh.receiveShadow = true;
  return mesh;
}

/** Everything a design's drawing needs of the bridge it is drawing: its frame, its deck, and the buffer. */
interface Frame {
  buf: SolidBuf; w: World; st: Style;
  s0: number; s1: number; sign: number; tiles: number; across: number; W2: number;
  /** (along, across, height) to world. */
  at: (s: number, c: number, y: number) => P3;
  deckY: (s: number) => number;
  block: (s: number, c: number, y: number, along: number, acrossW: number, h: number, col: RGB) => void;
  prism: (sa: number, sb: number, c0: number, c1: number, ba: number, bb: number, ta: number, tb: number, col: RGB) => void;
  inChunk: (x: number, z: number) => boolean;
}

function drawBridge(buf: SolidBuf, w: World, r: Road, br: Bridge, inChunk: (x: number, z: number) => boolean): void {
  if (r.type === RoadType.None) return;
  if (br.tunnel) { drawTunnel(buf, w, r, br, inChunk); return; }
  if (br.level) { drawPlatform(buf, w, r, br, inChunk); return; }
  const st = STYLES[r.type], wide = shapeOf(r.type);
  const a = r.nodes[br.from], b = r.nodes[br.to];
  const d = dirBetween(a, r.nodes[br.from + 1]);
  const alongX = DIRS[d][0] !== 0, sign = DIRS[d][0] + DIRS[d][1];
  const [acx, acz] = nodeCenter(a, wide), [bcx, bcz] = nodeCenter(b, wide);
  const across = alongX ? acz : acx;
  const half = blockHalf(wide);
  const s0 = (alongX ? acx : acz) + sign * half, s1 = (alongX ? bcx : bcz) - sign * half;
  const tiles = Math.round(Math.abs(s1 - s0));
  const W2 = st.width / 2;
  // an end that meets a raised road's platform rather than the ground has no abutment: the platform's pier holds it
  const onPlatform = (k: number) => !!r.bridges?.some((o) => o.level && o.from === k);
  // (along, across, height) to world
  const at = (s: number, c: number, y: number): P3 => (alongX ? [s, y, c] : [c, y, s]);
  // a flyover ramps up to its crest and down again; an ordinary bridge runs straight
  const deckY = (s: number) => deckHeightAt(br, tiles, Math.abs(s - s0));
  const prism = (sa: number, sb: number, c0: number, c1: number, ba: number, bb: number, ta: number, tb: number, col: RGB) =>
    buf.hull([at(sa, c0, ba), at(sb, c0, bb), at(sb, c1, bb), at(sa, c1, ba), at(sa, c0, ta), at(sb, c0, tb), at(sb, c1, tb), at(sa, c1, ta)], col);
  // an axis-aligned box given along/across sizes
  const block = (s: number, c: number, y: number, along: number, acrossW: number, h: number, col: RGB) => {
    const [x, , z] = at(s, c, 0);
    buf.box(x, y, z, alongX ? along : acrossW, h, alongX ? acrossW : along, col);
  };
  const design: BridgeDesign = designOf(w, r, br);
  // the arcade and Tower Bridge carry a solid stone parapet whatever road runs over them
  const solidRail = design === 'arcade' || design === 'towerBridge' || design === 'venetian';
  // a covered bridge wears timber walls instead of railings: they go up with its roof, below
  const noRail = design === 'covered';
  const railCol = design === 'arcade' ? LIMESTONE : design === 'towerBridge' ? PORTLAND : design === 'venetian' ? ISTRIA : st.rail;

  for (let j = 0; j < tiles; j++) {
    const sa = s0 + sign * j, sb = s0 + sign * (j + 1), mid = (sa + sb) / 2;
    const [mx, , mz] = at(mid, across, 0);
    if (!inChunk(mx, mz)) continue;
    const ya = deckY(sa), yb = deckY(sb);
    prism(sa, sb, across - W2, across + W2, ya - st.thick, yb - st.thick, ya - 0.004, yb - 0.004, st.deck);

    for (const side of [-1, 1]) {
      if (noRail) break;
      const edge = across + side * W2, inner = across + side * (W2 - st.railT);
      const c0 = Math.min(edge, inner), c1 = Math.max(edge, inner);
      if (!solidRail && (st.pier === 'timber' || st.pier === 'column')) {
        // posts and a top rail (two rails on steel)
        for (const f of [0.25, 0.75]) {
          const s = sa + (sb - sa) * f;
          block(s, (c0 + c1) / 2, deckY(s) - 0.004, 0.035, st.railT, st.railH, st.pier === 'timber' ? TIMBER : st.rail);
        }
        const rails = st.pier === 'column' ? [st.railH - 0.015, st.railH * 0.5] : [st.railH - 0.02];
        for (const h of rails) prism(sa, sb, c0, c1, ya + h, yb + h, ya + h + 0.02, yb + h + 0.02, st.rail);
      } else {
        const h = solidRail ? Math.max(st.railH, 0.11) : st.railH;
        const cc0 = solidRail ? Math.min(edge, across + side * (W2 - 0.06)) : c0, cc1 = solidRail ? Math.max(edge, across + side * (W2 - 0.06)) : c1;
        prism(sa, sb, cc0, cc1, ya - 0.004, yb - 0.004, ya + h, yb + h, railCol);
      }
    }

    // piers: the ordinary designs stand on the road type's own; the rest carry their own supports
    if (design === 'standard' || design === 'suspension' || design === 'covered') {
      if (j % 2 === 1 || tiles === 1) support(w, st, block, at, mid, across, deckY(mid) - st.thick, W2);
    } else if (design === 'cableStayed') {
      if (j % 2 === 1 || tiles === 1) support(w, { ...st, pier: wide ? 'twin' : 'column' }, block, at, mid, across, deckY(mid) - st.thick, W2);
    }
  }

  // abutments where the deck meets the ground at each end
  for (const [s, inward, k] of [[s0, sign, br.from], [s1, -sign, br.to]] as [number, number, number][]) {
    if (onPlatform(k)) continue;
    const [ex, , ez] = at(s, across, 0);
    if (!inChunk(ex - (alongX ? inward * 0.01 : 0), ez - (alongX ? 0 : inward * 0.01)) && !inChunk(ex + (alongX ? inward * 0.2 : 0), ez + (alongX ? 0 : inward * 0.2))) continue;
    const top = deckY(s) - st.thick, base = Math.min(top, ground(w, ex, ez)) - 0.3;
    const sb = s + inward * 0.18;
    const col = design === 'arcade' ? LIMESTONE : design === 'towerBridge' ? PORTLAND : design === 'venetian' ? ISTRIA : design === 'harbourArch' || design === 'cantilever' ? GRANITE
      : st.pier === 'timber' ? TIMBER : st.pier === 'stone' ? STONE : CONCRETE;
    prism(s, sb, across - W2 - 0.04, across + W2 + 0.04, base, base, top, deckY(sb) - st.thick, col);
  }

  const f: Frame = { buf, w, st, s0, s1, sign, tiles, across, W2, at, deckY, block, prism, inChunk };
  switch (design) {
    case 'harbourArch': harbourArch(f); return;
    case 'towerBridge': towerBridge(f); return;
    case 'cableStayed': cableStayed(f); return;
    case 'cantilever': cantilever(f); return;
    case 'arcade': arcade(f); return;
    case 'covered': covered(f); return;
    case 'venetian': venetian(f); return;
    default: break;
  }

  // the Golden Gate: two towers in the city's colour, a main cable slung between them in a shallow
  // curve, and a hanger down to the deck every few feet
  if (design === 'suspension' && tiles >= 5) {
    const col = br.accent !== undefined ? hex(br.accent) : PYLON;
    const cable = scale(col, 0.55);
    const inset = Math.max(1.5, Math.round(tiles * 0.22));
    const tA = s0 + sign * inset, tB = s1 - sign * inset;
    const deckA = deckY(tA), deckB = deckY(tB);
    const TOWER = 2.6, SAG = 0.85;
    const topA = deckA + TOWER, topB = deckB + TOWER;
    /** Height of the main cable at s, between the towers and on the back stays outside them. */
    const cableAt = (s: number) => {
      const t = (s - tA) / (tB - tA);
      if (t >= 0 && t <= 1) return topA + (topB - topA) * t - 4 * SAG * t * (1 - t);
      const [anchor, top, from] = t < 0 ? [s0, topA, tA] : [s1, topB, tB];
      const k = (s - anchor) / (from - anchor);
      return deckY(anchor) + 0.1 + (top - deckY(anchor) - 0.1) * k;
    };
    // towers
    for (const [s, deck, top] of [[tA, deckA, topA], [tB, deckB, topB]] as [number, number, number][]) {
      const [gx, , gz] = at(s, across, 0);
      if (!inChunk(gx, gz)) continue;
      for (const side of [-1, 1]) {
        const c = across + side * (W2 + 0.12);
        const [lx, , lz] = at(s, c, 0);
        const foot = Math.min(deck - st.thick, ground(w, lx, lz)) - 0.25;
        block(s, c, foot, 0.22, 0.22, top - foot, col);
      }
      // cross beams: one just over the deck, one near the top
      for (const y of [deck + 0.55, top - 0.42]) {
        prism(s - sign * 0.09, s + sign * 0.09, across - W2 - 0.16, across + W2 + 0.16, y, y, y + 0.14, y + 0.14, scale(col, 0.86));
      }
    }
    // cable and hangers, drawn a step at a time so each chunk draws only its own share
    const STEP_S = 0.5;
    for (let s = Math.min(s0, s1); s < Math.max(s0, s1); s += STEP_S) {
      const sa = s, sb = Math.min(s + STEP_S, Math.max(s0, s1));
      const [mx2, , mz2] = at((sa + sb) / 2, across, 0);
      if (!inChunk(mx2, mz2)) continue;
      const ya = cableAt(sa), yb = cableAt(sb);
      for (const side of [-1, 1]) {
        const c = across + side * (W2 + 0.12);
        prism(sa, sb, c - 0.025, c + 0.025, ya, yb, ya + 0.05, yb + 0.05, cable);
        const sm = (sa + sb) / 2, top = cableAt(sm), dk = deckY(sm);
        if (top - dk > 0.35 && (sm - tA) * (sm - tB) < 0) prism(sm, sm, c - 0.015, c + 0.015, dk, dk, top, top, cable);
      }
    }
  } else if (design === 'standard' && st.pier === 'twin' && tiles >= 8) {
    const sm = (s0 + s1) / 2;
    const [px, , pz] = at(sm, across, 0);
    if (inChunk(px, pz)) {
      const deckMid = deckY(sm), topY = deckMid + 1.8;
      for (const side of [-1, 1]) {
        const c = across + side * (W2 + 0.1);
        const [gx, , gz] = at(sm, c, 0);
        const g = ground(w, gx, gz);
        block(sm, c, g, 0.14, 0.14, topY - g, PYLON);
        for (const off of [-3.5, -2, 2, 3.5]) {
          const s = sm + off;
          if ((s - s0) * (s - s1) > 0) continue;
          prism(sm, s, c - 0.012, c + 0.012, topY - 0.05, deckY(s) + 0.1, topY - 0.02, deckY(s) + 0.13, CABLE);
        }
      }
    }
  }
}

// ---- the famous designs ----------------------------------------------------------------------

/** The ground (or the bed under water) at a point of the bridge's frame. */
function groundOn(f: Frame, s: number, c: number): number {
  const [x, , z] = f.at(s, c, 0);
  return ground(f.w, x, z);
}

/** Is this point of the frame in the chunk being drawn? Each piece is drawn by the chunk its middle is in. */
function mine(f: Frame, s: number, c: number): boolean {
  const [x, , z] = f.at(s, c, 0);
  return f.inChunk(x, z);
}

/** A straight bar of square section t from P to Q, whichever way it runs: a chord, a stay, a strut. */
function bar(buf: SolidBuf, P: P3, Q: P3, t: number, col: RGB): void {
  const dx = Q[0] - P[0], dy = Q[1] - P[1], dz = Q[2] - P[2];
  const l = Math.hypot(dx, dy, dz);
  if (l < 1e-5) return;
  // u: level and square to the bar (along x for a vertical one); v: square to both
  let ux = -dz, uz = dx;
  const ul = Math.hypot(ux, uz);
  if (ul < 1e-6) { ux = 1; uz = 0; } else { ux /= ul; uz /= ul; }
  let vx = dy * uz, vy = dz * ux - dx * uz, vz = -dy * ux;
  const vl = Math.hypot(vx, vy, vz) || 1;
  vx /= vl; vy /= vl; vz /= vl;
  const h = t / 2;
  const corner = (p: P3, a: number, b: number): P3 => [p[0] + (ux * a + vx * b) * h, p[1] + vy * b * h, p[2] + (uz * a + vz * b) * h];
  buf.hull([corner(P, -1, -1), corner(P, 1, -1), corner(P, 1, 1), corner(P, -1, 1), corner(Q, -1, -1), corner(Q, 1, -1), corner(Q, 1, 1), corner(Q, -1, 1)], col);
}

/** A square roof rising to a point: a turret's cap, a tower's spire. */
function pyramid(f: Frame, s: number, c: number, y: number, along: number, acrossW: number, h: number, col: RGB): void {
  const a = along / 2, b = acrossW / 2;
  const top = f.at(s, c, y + h);
  f.buf.hull([f.at(s - a, c - b, y), f.at(s + a, c - b, y), f.at(s + a, c + b, y), f.at(s - a, c + b, y), top, top, top, top], col);
}

/**
 * Sydney Harbour: a steel arch either side of the deck, deep at its ends and slim at the crown, braced
 * across overhead only where the traffic is clear of it, the deck hung from its lower chord, and a pair
 * of granite pylons standing at each end.
 */
function harbourArch(f: Frame): void {
  const { s0, s1, sign, across, W2, deckY, buf, at } = f;
  const sa = s0 + sign * 0.35, sb = s1 - sign * 0.35;
  const span = Math.abs(sb - sa);
  const deckMid = deckY((s0 + s1) / 2);
  const spring = Math.min(deckY(sa), deckY(sb)) - 0.9;
  const crown = deckMid + THREE.MathUtils.clamp(span * 0.17, 1.3, 3.4);
  const low = (t: number) => spring + (crown - spring) * 4 * t * (1 - t);
  const depth = (t: number) => 0.62 - 0.4 * 4 * t * (1 - t);
  const n = Math.max(6, Math.round(span * 2));
  const sAt = (t: number) => sa + (sb - sa) * t;
  const edge = W2 + 0.09;
  for (const side of [-1, 1]) {
    const c = across + side * edge;
    for (let k = 0; k < n; k++) {
      const t0 = k / n, t1 = (k + 1) / n;
      const A = sAt(t0), B = sAt(t1);
      if (!mine(f, (A + B) / 2, c)) continue;
      bar(buf, at(A, c, low(t0)), at(B, c, low(t1)), 0.09, STEEL);
      bar(buf, at(A, c, low(t0) + depth(t0)), at(B, c, low(t1) + depth(t1)), 0.08, STEEL);
      // the web: a post at each panel point and a diagonal across each panel
      bar(buf, at(A, c, low(t0)), at(A, c, low(t0) + depth(t0)), 0.05, STEEL);
      bar(buf, at(A, c, low(t0) + (k % 2 ? depth(t0) : 0)), at(B, c, low(t1) + (k % 2 ? 0 : depth(t1))), 0.04, STEEL);
      // a hanger down to the deck wherever the arch is over it
      const dk = deckY(A);
      if (low(t0) > dk + 0.15) bar(buf, at(A, c, dk), at(A, c, low(t0)), 0.025, STEEL);
      // wind bracing across the top, only where a lorry would pass under it
      if (side === 1 && low(t0) > dk + 1.05) bar(buf, at(A, across - edge, low(t0) + depth(t0) * 0.5), at(A, across + edge, low(t0) + depth(t0) * 0.5), 0.05, STEEL);
    }
  }
  // the pylons: granite, one either side at each end, a little taller than the deck
  for (const s of [s0 + sign * 0.2, s1 - sign * 0.2]) {
    for (const side of [-1, 1]) {
      const c = across + side * (W2 + 0.2);
      if (!mine(f, s, c)) continue;
      const foot = Math.min(deckY(s), groundOn(f, s, c)) - 0.3, top = deckY(s) + 1.25;
      f.block(s, c, foot, 0.5, 0.36, top - foot, GRANITE);
      f.block(s, c, top, 0.56, 0.42, 0.1, scale(GRANITE, 0.9));
    }
  }
}

/**
 * Tower Bridge: two tall towers of pale stone standing in the river, their legs either side of the
 * road, joined up top by walkways; chains in the old blue sweep from each tower out to its bank.
 */
function towerBridge(f: Frame): void {
  const { s0, s1, sign, tiles, across, W2, deckY, buf, at, block, st } = f;
  const inset = Math.max(1.4, tiles * 0.27);
  const tA = s0 + sign * inset, tB = s1 - sign * inset;
  const outer = W2 + 0.3;
  for (const t of [tA, tB]) {
    if (!mine(f, t, across)) continue;
    const dk = deckY(t);
    const foot = Math.min(dk - st.thick, groundOn(f, t, across)) - 0.3;
    // the pier the tower stands on, wider than the road, below the deck
    block(t, across, foot, 1.05, outer * 2 + 0.3, dk - st.thick - foot, PORTLAND);
    // legs either side of the carriageway, then the body over it with the arch the road runs through
    for (const side of [-1, 1]) block(t, across + side * (W2 + 0.17), dk - st.thick, 0.82, 0.3, 1.2 + st.thick, PORTLAND);
    block(t, across, dk + 1.2, 0.82, outer * 2, 1.35, PORTLAND);
    block(t, across, dk + 1.2, 0.86, outer * 2 + 0.04, 0.08, scale(PORTLAND, 0.86));
    // a turret at each corner and a pointed roof in the middle
    const top = dk + 2.55;
    for (const a of [-1, 1]) for (const c of [-1, 1]) {
      const ts = t + a * 0.33, tc = across + c * (outer - 0.1);
      block(ts, tc, top, 0.2, 0.2, 0.32, PORTLAND);
      pyramid(f, ts, tc, top + 0.32, 0.24, 0.24, 0.32, SLATE);
    }
    pyramid(f, t, across, top, 0.7, outer * 2 - 0.3, 0.75, SLATE);
  }
  // the high walkways, one along each side between the towers
  const wy = deckY((tA + tB) / 2) + 2.05;
  const lo = Math.min(tA, tB), hi = Math.max(tA, tB);
  for (let s = lo; s < hi; s += 0.5) {
    const e = Math.min(hi, s + 0.5);
    if (!mine(f, (s + e) / 2, across)) continue;
    for (const side of [-1, 1]) {
      const c = across + side * (outer - 0.16);
      f.prism(s, e, c - 0.14, c + 0.14, wy, wy, wy + 0.22, wy + 0.22, TOWER_BLUE);
    }
  }
  // chains from each tower to its bank, sagging a little, with hangers down to the deck
  for (const [t, end] of [[tA, s0], [tB, s1]] as [number, number][]) {
    const y0 = deckY(t) + 1.9, y1 = deckY(end) + 0.25;
    const steps = Math.max(3, Math.ceil(Math.abs(t - end) * 2));
    for (const side of [-1, 1]) {
      const c = across + side * (W2 + 0.17);
      for (let k = 0; k < steps; k++) {
        const u0 = k / steps, u1 = (k + 1) / steps;
        const sa = t + (end - t) * u0, sb = t + (end - t) * u1;
        if (!mine(f, (sa + sb) / 2, c)) continue;
        const ya = y0 + (y1 - y0) * u0 - 0.35 * 4 * u0 * (1 - u0), yb = y0 + (y1 - y0) * u1 - 0.35 * 4 * u1 * (1 - u1);
        bar(buf, at(sa, c, ya), at(sb, c, yb), 0.07, TOWER_BLUE);
        const dk = deckY(sa);
        if (ya - dk > 0.3) bar(buf, at(sa, c, dk), at(sa, c, ya), 0.022, TOWER_BLUE);
      }
    }
  }
}

/**
 * Millau and Øresund: white pylons like tall inverted Vs straddling the deck, one to every seven
 * tiles or so, each fanning stays out to both edges of the deck either way.
 */
function cableStayed(f: Frame): void {
  const { s0, sign, tiles, across, W2, deckY, buf, at, st } = f;
  const np = Math.max(1, Math.round(tiles / 7));
  const bay = tiles / np;
  const edge = W2 + 0.1;
  for (let i = 0; i < np; i++) {
    const sp = s0 + sign * bay * (i + 0.5);
    const dk = deckY(sp), top = dk + THREE.MathUtils.clamp(bay * 0.42, 2.2, 3.6);
    if (mine(f, sp, across)) {
      for (const side of [-1, 1]) {
        const c = across + side * edge;
        // the leg below the deck, then leaning in to meet its twin over the middle of the road
        const foot = Math.min(dk - st.thick, groundOn(f, sp, c)) - 0.2;
        bar(buf, at(sp, c, foot), at(sp, c, dk), 0.18, MILLAU);
        bar(buf, at(sp, c, dk), at(sp, across + side * 0.08, top), 0.14, MILLAU);
      }
      bar(buf, at(sp, across, top - 0.05), at(sp, across, top + 0.55), 0.13, MILLAU);
      bar(buf, at(sp, across - edge, dk - st.thick - 0.05), at(sp, across + edge, dk - st.thick - 0.05), 0.1, MILLAU);
    }
    // the fans: stays from high on the pylon down to the deck's edges, either way along
    const reach = bay / 2 - 0.25;
    for (let off = 0.55; off <= reach; off += 0.55) {
      for (const dir of [-1, 1]) {
        const s = sp + dir * off;
        if (!mine(f, (s + sp) / 2, across)) continue;
        const yk = top - 0.1 - (off / reach) * 0.9;
        for (const side of [-1, 1]) bar(buf, at(sp, across + side * 0.1, yk), at(s, across + side * edge, deckY(s) + 0.05), 0.02, STAY);
      }
    }
  }
}

/**
 * The Forth Bridge: great red steel diamonds, each standing on its granite pier with a lens of truss
 * above the deck and another below it, the suspended spans between them resting on their tips.
 */
function cantilever(f: Frame): void {
  const { s0, sign, tiles, across, W2, deckY, buf, at, block } = f;
  const nd = Math.max(1, Math.round(tiles / 9));
  const bay = tiles / nd;
  const half = Math.max(1.4, Math.min(3.8, bay / 2 - 0.6));
  const edge = W2 + 0.07;
  for (let i = 0; i < nd; i++) {
    const sc = s0 + sign * bay * (i + 0.5);
    const dk = deckY(sc);
    const top = dk + 1.6 + half * 0.22;
    const g = groundOn(f, sc, across);
    const bot = Math.max(dk - 0.9 - half * 0.18, g + 0.35);
    // chords over and under the deck, narrowing to the tips; the deck chord; posts and diagonals
    const up = (s: number) => deckY(s) + 0.08 + (top - dk - 0.08) * (1 - Math.abs(s - sc) / half);
    const dn = (s: number) => deckY(s) - 0.05 - Math.max(0, dk - 0.05 - bot) * (1 - Math.abs(s - sc) / half);
    const P = 6;
    for (const side of [-1, 1]) {
      const c = across + side * edge;
      for (const e of [sc - sign * half, sc + sign * half]) {
        for (let k = 0; k < P; k++) {
          const sa = e + (sc - e) * (k / P), sb = e + (sc - e) * ((k + 1) / P);
          if (!mine(f, (sa + sb) / 2, c)) continue;
          bar(buf, at(sa, c, up(sa)), at(sb, c, up(sb)), 0.1, FORTH);
          bar(buf, at(sa, c, dn(sa)), at(sb, c, dn(sb)), 0.1, FORTH);
          bar(buf, at(sa, c, deckY(sa) - 0.02), at(sb, c, deckY(sb) - 0.02), 0.06, FORTH);
          bar(buf, at(sb, c, dn(sb)), at(sb, c, up(sb)), 0.06, FORTH);
          bar(buf, at(sa, c, k % 2 ? dn(sa) : up(sa)), at(sb, c, k % 2 ? up(sb) : dn(sb)), 0.045, FORTH);
        }
      }
    }
    if (!mine(f, sc, across)) continue;
    // cross-bracing over the road at the crown, clear of the traffic, and under it at the foot
    bar(buf, at(sc, across - edge, top), at(sc, across + edge, top), 0.1, FORTH);
    bar(buf, at(sc, across - edge, top - 0.5), at(sc, across + edge, dk + 1.1), 0.05, FORTH);
    bar(buf, at(sc, across + edge, top - 0.5), at(sc, across - edge, dk + 1.1), 0.05, FORTH);
    bar(buf, at(sc, across - edge, bot), at(sc, across + edge, bot), 0.1, FORTH);
    // the granite pier under each diamond
    if (bot > g) block(sc, across, g - 0.3, 1.0, W2 * 2 + 0.5, bot - g + 0.3, GRANITE);
  }
}

/**
 * The Pont du Gard: a round stone arch between every pair of piers, a tile apart, and where the valley
 * is deep a second, smaller tier of arches above a string course, two to each arch below.
 */
/**
 * A covered bridge: the deck runs through a timber barn — boarded walls with the truss showing above
 * them, a shingled gable roof over the lot, and a portal board at each end. The trestles under it are
 * whatever the road's own bridge would stand on.
 */
function covered(f: Frame): void {
  const { s0, s1, sign, tiles, across, W2, deckY, prism, block } = f;
  const half = W2 + 0.02;
  const WALL = 0.34, ROOF = 0.16;
  const shingle = scale(TIMBER, 0.72);
  for (let j = 0; j < tiles; j++) {
    const sa = s0 + sign * j, sb = s0 + sign * (j + 1), sm = (sa + sb) / 2;
    if (!mine(f, sm, across)) continue;
    const ya = deckY(sa), yb = deckY(sb);
    for (const side of [-1, 1]) {
      const c = across + side * half;
      // the boarded wall, the lighter rail over it, and the posts of the truss between them
      prism(sa, sb, c - 0.035, c + 0.035, ya, yb, ya + WALL * 0.62, yb + WALL * 0.62, TIMBER);
      prism(sa, sb, c - 0.02, c + 0.02, ya + WALL - 0.03, yb + WALL - 0.03, ya + WALL, yb + WALL, scale(TIMBER, 1.15));
      for (const t of [0.25, 0.75]) {
        const s = sa + (sb - sa) * t;
        block(s, c, deckY(s) + WALL * 0.6, 0.04, 0.05, WALL * 0.42, scale(TIMBER, 0.9));
      }
    }
    // the roof: a low pitch each side, meeting over the middle
    for (const side of [-1, 1]) {
      const cOut = across + side * (half + 0.07), cMid = across;
      prism(sa, sb, Math.min(cOut, cMid), Math.max(cOut, cMid), ya + WALL, yb + WALL, ya + WALL + 0.03, yb + WALL + 0.03, shingle);
      prism(sa, sb, Math.min(across, across + side * half * 0.55), Math.max(across, across + side * half * 0.55),
        ya + WALL + ROOF * 0.5, yb + WALL + ROOF * 0.5, ya + WALL + ROOF * 0.53, yb + WALL + ROOF * 0.53, shingle);
    }
    prism(sa, sb, across - half * 0.22, across + half * 0.22, ya + WALL + ROOF, yb + WALL + ROOF, ya + WALL + ROOF + 0.03, yb + WALL + ROOF + 0.03, scale(shingle, 0.9));
  }
  // the portals: a board across each end, painted white, under the gable
  for (const s of [s0, s1]) {
    if (!mine(f, s, across)) continue;
    const y = deckY(s);
    prism(s - 0.05, s + 0.05, across - half - 0.08, across + half + 0.08, y + WALL, y + WALL, y + WALL + ROOF, y + WALL + ROOF, TIMBER);
    prism(s - 0.07, s + 0.07, across - half * 0.7, across + half * 0.7, y + WALL + ROOF * 0.3, y + WALL + ROOF * 0.3, y + WALL + ROOF * 0.7, y + WALL + ROOF * 0.7, PORTLAND);
  }
}

/**
 * A Venice canal bridge: the whole span is one low arch, its ring of white Istrian stone springing from
 * the quay walls at the water and the brick over it filled up to the deck; a white stone band runs along
 * each face under the balustrade. (The balustrade is the solid rail drawn with the deck.)
 */
function venetian(f: Frame): void {
  const { s0, s1, sign, tiles, across, W2, deckY, st, prism } = f;
  const half = W2 + 0.05;
  const under = (s: number) => deckY(s) - st.thick;
  const lo = Math.min(s0, s1), hi = Math.max(s0, s1), sm = (lo + hi) / 2, r = (hi - lo) / 2;
  const water = Math.min(groundOn(f, s0, across), groundOn(f, s1, across));
  const K = Math.max(6, tiles * 4);
  for (let q = 0; q < K; q++) {
    const a = lo + ((hi - lo) * q) / K, b = lo + ((hi - lo) * (q + 1)) / K;
    if (!mine(f, (a + b) / 2, across)) continue;
    // the arch's soffit: a flattened half-circle from the water at the quays up under the deck
    const rise = Math.max(0.12, under(sm) - water - 0.06);
    const y = (s: number) => water + rise * Math.sqrt(Math.max(0, 1 - ((s - sm) / r) ** 2));
    const ya = y(a), yb = y(b), ta = under(a), tb = under(b);
    // the brick spandrel over the arch, and the stone ring along its edge on both faces
    if (ta > ya || tb > yb) prism(a, b, across - half + 0.04, across + half - 0.04, Math.min(ya, ta), Math.min(yb, tb), ta, tb, BRICK_RED);
    for (const side of [-1, 1]) {
      const c = across + side * (half - 0.02);
      prism(a, b, c - 0.03, c + 0.03, ya - 0.05, yb - 0.05, Math.min(ta, ya + 0.04), Math.min(tb, yb + 0.04), ISTRIA);
      prism(a, b, c - 0.035, c + 0.035, ta - 0.035, tb - 0.035, ta, tb, ISTRIA);
    }
  }
}

function arcade(f: Frame): void {
  const { s0, sign, tiles, across, W2, deckY, st, prism } = f;
  const half = W2 + 0.06;
  const PIER = 0.24;
  const under = (s: number) => deckY(s) - st.thick;
  // a round vault from sa to sb with its crown at `crown`, the stone over it filled up to `to`
  const vault = (sa: number, sb: number, crown: number, to: (s: number) => number) => {
    const sm = (sa + sb) / 2, r = Math.abs(sb - sa) / 2, K = 6;
    for (let q = 0; q < K; q++) {
      const u0 = -1 + (2 * q) / K, u1 = -1 + (2 * (q + 1)) / K;
      const a = sm + u0 * (sb - sm), b = sm + u1 * (sb - sm);
      const y0 = crown - r + r * Math.sqrt(Math.max(0, 1 - u0 * u0)), y1 = crown - r + r * Math.sqrt(Math.max(0, 1 - u1 * u1));
      const t0 = to(a), t1 = to(b);
      if (t0 > y0 || t1 > y1) prism(a, b, across - half, across + half, Math.min(y0, t0), Math.min(y1, t1), t0, t1, LIMESTONE);
    }
  };
  for (let j = 0; j < tiles; j++) {
    const sa = s0 + sign * j, sb = s0 + sign * (j + 1), sm = (sa + sb) / 2;
    if (!mine(f, sm, across)) continue;
    const g = Math.min(groundOn(f, sa, across), groundOn(f, sb, across), groundOn(f, sm, across));
    const H = under(sm) - g;
    // hardly any air under it: a solid causeway of the same stone
    if (H < 0.3) { prism(sa, sb, across - half, across + half, g - 0.2, g - 0.2, under(sa), under(sb), LIMESTONE); continue; }
    // the pier at the start of the bay, full height (the abutment stands in for the first)
    if (j > 0) {
      const gs = groundOn(f, sa, across);
      f.block(sa, across, gs - 0.3, PIER, half * 2 + 0.06, under(sa) - gs + 0.3, scale(LIMESTONE, 0.94));
    }
    const inA = sa + sign * (j > 0 ? PIER / 2 : 0), inB = sb - sign * (j < tiles - 1 ? PIER / 2 : 0);
    if (H < 2.2) { vault(inA, inB, under(sm) - 0.1, under); continue; }
    // two tiers: a big arch below a string course, and two small ones above it
    const course = g + H * 0.6;
    vault(inA, inB, course - 0.05, () => course);
    prism(sa, sb, across - half - 0.05, across + half + 0.05, course, course, course + 0.12, course + 0.12, scale(LIMESTONE, 0.86));
    f.block(sm, across, course + 0.12, PIER * 0.8, half * 2, under(sm) - course - 0.12, scale(LIMESTONE, 0.94));
    vault(inA, sm - sign * PIER * 0.4, under(sm) - 0.08, under);
    vault(sm + sign * PIER * 0.4, inB, under(sm) - 0.08, under);
  }
}

/**
 * A tunnel: nothing between the portals, since the road is inside the hill. Each portal is a stone
 * arch set into the hillside — a lintel over two jambs, with the rock face cut back around it.
 */
function drawTunnel(buf: SolidBuf, w: World, r: Road, br: Bridge, inChunk: (x: number, z: number) => boolean): void {
  if (r.type === RoadType.None) return;
  const st = STYLES[r.type], wide = shapeOf(r.type);
  const a = r.nodes[br.from], b = r.nodes[br.to];
  const d = dirBetween(a, r.nodes[br.from + 1]);
  const alongX = DIRS[d][0] !== 0, sign = DIRS[d][0] + DIRS[d][1];
  const [acx, acz] = nodeCenter(a, wide), [bcx, bcz] = nodeCenter(b, wide);
  const across = alongX ? acz : acx;
  const half = blockHalf(wide);
  const s0 = (alongX ? acx : acz) + sign * half, s1 = (alongX ? bcx : bcz) - sign * half;
  const W2 = st.width / 2 + 0.12, HEAD = 0.5 + st.thick;
  const at = (s: number, c: number, y: number): P3 => (alongX ? [s, y, c] : [c, y, s]);
  const block = (s: number, c: number, y: number, along: number, acrossW: number, h: number, col: RGB) => {
    const [x, , z] = at(s, c, 0);
    buf.box(x, y, z, alongX ? along : acrossW, h, alongX ? acrossW : along, col);
  };
  for (const [s, y, inward] of [[s0, br.h0, sign], [s1, br.h1, -sign]] as [number, number, number][]) {
    const [px, , pz] = at(s, across, 0);
    if (!inChunk(px + (alongX ? inward * 0.1 : 0), pz + (alongX ? 0 : inward * 0.1))) continue;
    const face = s + inward * 0.12;
    // jambs either side of the mouth, and the lintel over it
    for (const side of [-1, 1]) block(face, across + side * (W2 - 0.1), y + HEAD / 2, 0.3, 0.22, HEAD, STONE);
    block(face, across, y + HEAD + 0.14, 0.34, W2 * 2 + 0.22, 0.28, STONE);
    // the dark of the bore, set back a little so it reads as a hole
    block(s - inward * 0.1, across, y + HEAD / 2, 0.06, W2 * 1.7, HEAD, hex(0x2b2722));
    // the road running in at the mouth
    block(face, across, y - st.thick / 2, 0.36, W2 * 1.7, st.thick, st.deck);
  }
}

/**
 * A raised road's platform (Bridge.level): a square slab over its node at the deck's height, a pier (or
 * two) under it, and a railing along every side the road doesn't run on from — so a raised road that
 * stops in mid-air, waiting to be carried on, ends at a barrier rather than a drop.
 */
function drawPlatform(buf: SolidBuf, w: World, r: Road, br: Bridge, inChunk: (x: number, z: number) => boolean): void {
  const st = STYLES[r.type as Exclude<RoadType, RoadType.None>], wide = shapeOf(r.type);
  const n = r.nodes[br.from];
  const [cx, cz] = nodeCenter(n, wide);
  if (!inChunk(cx, cz)) return;
  const y = br.h0, W2 = st.width / 2, H = st.thick;
  buf.box(cx, y - H - 0.004, cz, st.width, H, st.width, st.deck);
  // the road runs on from it toward its neighbours along the road; the other sides get a railing
  const open = new Set<number>();
  for (const k of [br.from - 1, br.from + 1]) if (k >= 0 && k < r.nodes.length) open.add(dirBetween(n, r.nodes[k]));
  for (let d = 0; d < 4; d++) {
    if (open.has(d)) continue;
    const ex = cx + DIRS[d][0] * (W2 - st.railT / 2), ez = cz + DIRS[d][1] * (W2 - st.railT / 2);
    const alongX = DIRS[d][0] === 0;
    buf.box(ex, y - 0.004, ez, alongX ? st.width : st.railT, st.railH, alongX ? st.railT : st.width, st.rail);
  }
  const g = ground(w, cx, cz) - 0.05;
  if (y - H - g < 0.12) return;
  if (st.pier === 'twin') for (const side of [-1, 1]) buf.box(cx + side * W2 * 0.45, g, cz, 0.22, y - H - g, 0.22, CONCRETE), buf.box(cx, g, cz + side * W2 * 0.45, 0.22, y - H - g, 0.22, CONCRETE);
  else buf.box(cx, g, cz, st.pier === 'timber' ? 0.1 : 0.2, y - H - g, st.pier === 'timber' ? 0.1 : 0.2, st.pier === 'timber' ? TIMBER : st.pier === 'stone' ? STONE : CONCRETE);
}

function support(
  w: World, st: Style,
  block: (s: number, c: number, y: number, along: number, acrossW: number, h: number, col: RGB) => void,
  at: (s: number, c: number, y: number) => P3,
  s: number, c: number, top: number, W2: number,
): void {
  const [x, , z] = at(s, c, 0);
  const g = ground(w, x, z) - 0.05;
  if (top - g < 0.12) return;
  switch (st.pier) {
    case 'timber':
      for (const side of [-1, 1]) block(s, c + side * W2 * 0.7, g, 0.07, 0.07, top - g, TIMBER);
      block(s, c, g + (top - g) * 0.55, 0.05, W2 * 1.5, 0.05, TIMBER);
      break;
    case 'stone':
      block(s, c, g, 0.42, W2 * 2 + 0.08, 0.12, STONE);
      block(s, c, g, 0.34, W2 * 1.7, top - g, STONE);
      break;
    case 'column':
      block(s, c, g, 0.16, 0.16, top - g, CONCRETE);
      block(s, c, top - 0.08, 0.2, W2 * 1.8, 0.08, CONCRETE);
      break;
    case 'twin':
      for (const side of [-1, 1]) block(s, c + side * 0.55, g, 0.2, 0.2, top - g, CONCRETE);
      block(s, c, top - 0.12, 0.24, W2 * 1.9, 0.12, CONCRETE);
      break;
  }
}
