import { hex, scale, type RGB } from '../../world/biomes';
import type { VenueKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import { Vis } from '../nightLights';
import {
  BRICK, BRIGHT, CARS, COOL_GLOW, DARK, GLASS_LIGHT, LEAF, METAL, ROOF_GREY, SHOP_GLOW, STONE, TAU, TRUNK, WARM_GLOW,
  WATER, WHITE, WOOD, car, curArch, pick, row, styleGlass, styleRoof, styleTrim, styleWall, tower, tree, win,
  type Draw, type Kit,
} from './kit';
import { chainFence } from './civic';
import { SHOWBIZ_DRAW } from './showbiz';
import { Sec, Train, buildTrack, drawCar, drawTrack, lightsFor, placeCars, rideOpen, type CP } from './coaster';
import { TANK, seaTank } from './sealife';
import type { Sched } from '../nightLights';

/** Places to be entertained: they carry the night with marquees, neon and crowds. */

const GOLD = hex(0xd9a441), NEON = [0xff4fa0, 0x4fe0ff, 0xffe14f, 0x8cff4f, 0xb06bff];
const DRAINED = hex(0xcfd0cc);

/** A row of bulbs chasing along an edge: each on its own offset schedule. */
function bulbs(k: Kit, x0: number, x1: number, y: number, z: number, n: number, col: RGB, start = 17): void {
  for (let i = 0; i < n; i++) {
    const on = start + (i % 3) * 0.02;
    k.glowBox(x0 + ((x1 - x0) * i) / (n - 1), y, z, 0.025, 0.025, 0.025, WHITE, [on, 23.5 + (i % 2) * 0.05, 2.4], col);
  }
}

/** A palm tree, whatever the biome. */
export function palm(k: Kit, x: number, z: number, h = 0.6): void {
  k.bar([x, 0, z], [x + 0.04, h, z + 0.02], 0.025, TRUNK);
  for (let f = 0; f < 6; f++) {
    const a = (f / 6) * TAU;
    k.bar([x + 0.04, h, z + 0.02], [x + 0.04 + Math.cos(a) * 0.24, h - 0.1, z + 0.02 + Math.sin(a) * 0.24], 0.022, hex(0x3f9b4a));
  }
}

// ---- 61. cinema --------------------------------------------------------------------------------

const cinema: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), h = b.floors * FLOOR + 0.1;
  const bd = D - 0.5, bz = -0.2, fz = bz + bd / 2;
  k.box(0, 0, bz, W - 0.2, h, bd, scale(wall, 0.95), ROOF_GREY);
  k.box(0, h, bz, W - 0.16, 0.05, bd + 0.04, styleTrim());
  // poster panels
  for (let i = 0; i < 4; i++) k.box(-W / 2 + 0.4 + (i * (W - 0.8)) / 3, 0.08, fz + 0.01, 0.18, 0.26, 0.02, pick(r, BRIGHT));
  // the marquee over the pavement
  const mz = fz + 0.2;
  k.box(0, 0.36, mz, W * 0.6, 0.16, 0.4, DARK);
  k.glowBox(0, 0.38, mz + 0.205, W * 0.56, 0.12, 0.01, WHITE, [17, 23.5, 2.2], SHOP_GLOW);
  bulbs(k, -W * 0.3, W * 0.3, 0.33, mz + 0.21, 12, hex(0xffe8a0));
  bulbs(k, -W * 0.3, W * 0.3, 0.53, mz + 0.21, 12, hex(0xffe8a0), 17.01);
  k.glowBox(0, 0.04, fz + 0.01, 0.6, 0.26, 0.02, GLASS_LIGHT, [17, 23.5, 1.6], WARM_GLOW);
  // the vertical fin sign
  const fin = pick(r, NEON);
  k.glowBox(W / 2 - 0.3, 0.6, fz + 0.12, 0.05, h - 0.3, 0.24, fin, [17, 23.5, 2.4], fin);
};

// ---- 62. theatre -------------------------------------------------------------------------------

const theatre: Draw = (k, W, D, b, r) => {
  const stone = pick(r, STONE), wall = styleWall(r), h = b.floors * FLOOR;
  const fd = 0.8, fz = D / 2 - 0.2 - fd / 2;
  // the ornate front with a loggia
  k.box(0, 0, fz, W - 0.2, h * 0.75, fd, stone);
  for (let i = 0; i < 6; i++) k.cyl(-W / 2 + 0.3 + (i * (W - 0.6)) / 5, FLOOR, fz + fd / 2 + 0.05, 0.035, h * 0.75 - FLOOR - 0.08, WHITE, 6);
  k.box(0, h * 0.75 - 0.08, fz + fd / 2 + 0.05, W - 0.3, 0.08, 0.12, stone);
  if (curArch === 'victorian' || curArch === 'gothic' || curArch === 'deco') {
    k.hip(0, h * 0.75, fz, W - 0.16, 0.34, fd + 0.04, hex(0x6fa89a));
  } else {
    k.cyl(0, h * 0.75, fz, 0.3, 0.12, stone, 12);
    k.dome(0, h * 0.75 + 0.12, fz, 0.3, hex(0x6fa89a), 12, 3);
  }
  k.glowBox(0, 0.03, fz + fd / 2 + 0.005, W - 0.6, FLOOR * 0.8, 0.01, GLASS_LIGHT, [17.5, 23, 1.6], WARM_GLOW);
  k.tagged(Vis.Weekend, () => k.glowBox(0, FLOOR, fz + fd / 2 + 0.005, W - 0.6, h * 0.5, 0.01, GLASS_LIGHT, [17.5, 23.5, 2], WARM_GLOW));
  // the auditorium and the tall plain fly tower behind
  const az = -D / 2 + 0.1 + (D - fd - 0.4) / 2;
  k.box(0, 0, az, W - 0.4, h * 0.7, D - fd - 0.4, wall, ROOF_GREY);
  k.box(0, 0, -D / 2 + 0.45, W * 0.55, h * 1.5, 0.7, scale(wall, 0.9), ROOF_GREY);
  win(k, b, r, 0, 0.2, -D / 2 + 0.1, 0.2, 0.2, 3);
};

// ---- 63. arena ---------------------------------------------------------------------------------

const arena: Draw = (k, W, D, _b, r, t) => {
  const accent = t?.accent !== undefined ? hex(t.accent) : pick(r, BRIGHT);
  const R = Math.min(W, D) / 2 - 0.45, h = 0.75, seg = 24, wall = hex(0xd8d4cc);
  k.cyl(0, 0, 0, R, h, wall, seg);
  // a ring of lit glass at concourse level
  k.cyl(0, 0.12, 0, R + 0.01, 0.2, GLASS_LIGHT, seg);
  k.glowBox(0, 0.12, 0, R * 1.4, 0.2, R * 1.4, GLASS_LIGHT, [17, 23.5, 1.2], COOL_GLOW);
  // the shallow dome
  const I = [0, -2, 0] as [number, number, number];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    k.quad([Math.cos(a0) * R, h, Math.sin(a0) * R], [Math.cos(a1) * R, h, Math.sin(a1) * R],
      [Math.cos(a1) * R * 0.55, h + 0.28, Math.sin(a1) * R * 0.55], [Math.cos(a0) * R * 0.55, h + 0.28, Math.sin(a0) * R * 0.55], s % 2 ? WHITE : scale(WHITE, 0.95), I);
    k.tri([0, h + 0.36, 0], [Math.cos(a0) * R * 0.55, h + 0.28, Math.sin(a0) * R * 0.55], [Math.cos(a1) * R * 0.55, h + 0.28, Math.sin(a1) * R * 0.55], WHITE, I);
  }
  // the banner in the city's colour
  k.box(0, 0.4, R + 0.01, 0.9, 0.24, 0.02, accent);
  k.glowBox(0, 0.64, R - 0.02, 0.6, 0.08, 0.04, accent, [17, 23.5, 2.2], accent);
};

// ---- 64. concert hall --------------------------------------------------------------------------

const concertHall: Draw = (k, W, D, _b, r, t) => {
  const shell = t?.accent !== undefined && r() < 0.4 ? hex(t.accent) : WHITE, stone = pick(r, STONE);
  k.box(0, 0, 0, W - 0.2, 0.18, D - 0.2, stone);
  // the glass foyer on the podium
  k.box(0, 0.18, 0.5, W - 0.9, 0.34, 0.6, GLASS_LIGHT);
  k.glowBox(0, 0.2, 0.5, W - 0.96, 0.3, 0.54, GLASS_LIGHT, [16.5, 23.5, 1.6], WARM_GLOW);
  // three overlapping shells: half domes tilted forward
  const shells: [number, number, number, number][] = [[-0.55, -0.35, 0.9, 1.3], [0.2, -0.1, 0.75, 1.05], [0.75, 0.25, 0.55, 0.8]];
  for (const [x, z, rad, hgt] of shells) {
    const seg = 10, rings = 4;
    for (let j = 0; j < rings; j++) {
      const p0 = (j / rings) * Math.PI / 2, p1 = ((j + 1) / rings) * Math.PI / 2;
      for (let s = 0; s < seg; s++) {
        // only the back half of the dome, so the open face looks forward and up
        const a0 = Math.PI + (s / seg) * Math.PI, a1 = Math.PI + ((s + 1) / seg) * Math.PI;
        const P = (a: number, p: number): [number, number, number] => [x + Math.cos(a) * Math.cos(p) * rad, 0.18 + Math.sin(p) * hgt, z + Math.sin(a) * Math.cos(p) * rad * 0.8 + p * 0.15];
        k.quad(P(a0, p0), P(a1, p0), P(a1, p1), P(a0, p1), scale(shell, 1 - j * 0.03), [x, 0.18, z + 0.5]);
        k.quad(P(a0, p0), P(a1, p0), P(a1, p1), P(a0, p1), scale(shell, 0.85), [x, 0.18, z - 3]);
      }
    }
  }
};

// ---- 65. bowling alley -------------------------------------------------------------------------

const bowlingAlley: Draw = (k, W, D, _b, r) => {
  const wall = pick(r, [0xe8d3b0, 0xcfe0e8, 0xf4d6c6]), neon = pick(r, NEON);
  const bw = W - 0.2, bd = D - 0.35, bz = -0.1;
  k.box(0, 0, bz, bw, 0.4, bd, wall);
  // barrel roof in three courses
  for (let i = 0; i < 3; i++) k.box(0, 0.4 + i * 0.05, bz, bw + 0.02, 0.05, bd * (1 - i * 0.25), ROOF_GREY);
  k.glowBox(0, 0.3, bz + bd / 2 + 0.01, bw - 0.1, 0.03, 0.02, neon, [12, 24, 2.4], neon);
  k.box(0, 0, bz + bd / 2 + 0.01, 0.2, 0.22, 0.02, GLASS_LIGHT);
  // the giant pin and ball on the roof are its roof icon (roofIcons.ts)
};

// ---- 66. casino --------------------------------------------------------------------------------

const casino: Draw = (k, W, D, b, r) => {
  const wall = pick(r, [0xf6efdf, 0xe8dcc2, 0xf4d6c6]);
  const bd = D - 1.0, bz = -D / 2 + 0.1 + bd / 2, fz = bz + bd / 2;
  const top = tower(k, b, r, 0, 0, bz, W - 0.3, bd, b.floors, wall, hex(0xd9a441), 0.12);
  k.box(0, top, bz, W - 0.2, 0.08, bd + 0.1, GOLD);
  // porte-cochère on gold columns
  k.box(0, 0.36, fz + 0.3, 1.2, 0.06, 0.6, GOLD);
  for (const sx of [-0.55, 0.55]) for (const sz of [0.05, 0.55]) k.cyl(sx, 0, fz + sz, 0.03, 0.36, GOLD, 6);
  k.glowBox(0, 0.34, fz + 0.3, 1.1, 0.02, 0.5, WHITE, [0, 30, 1.8], WARM_GLOW);
  // a huge lit sign in three colours cycling through schedules
  const cols = [0xff4fa0, 0xffe14f, 0x4fe0ff];
  for (let i = 0; i < 3; i++) {
    for (let c = 0; c < 3; c++) {
      // each panel changes colour through the night: three spells, one colour each
      const on = 16 + c * 4.5;
      k.glowBox(-0.6 + i * 0.6, top + 0.12 + c * 0.002, bz + bd / 2 - 0.1 - c * 0.002, 0.5, 0.26, 0.04, DARK, [on, on + 4.5, 2.6], hex(cols[(i + c) % 3]));
    }
  }
  // a fountain in front and a row of palms
  k.cyl(-W / 2 + 0.5, 0, D / 2 - 0.35, 0.28, 0.08, WHITE, 10);
  k.cyl(-W / 2 + 0.5, 0.02, D / 2 - 0.35, 0.24, 0.07, WATER, 10);
  k.cone(-W / 2 + 0.5, 0.08, D / 2 - 0.35, 0.06, 0.2, hex(0xcfeaf6), 6);
  for (let i = 0; i < 4; i++) palm(k, W / 2 - 0.2 - i * 0.35, D / 2 - 0.15, 0.55);
};

// ---- 67. zoo -----------------------------------------------------------------------------------

function elephant(k: Kit, x: number, z: number): void {
  const g = hex(0x9a9c9e);
  k.box(x, 0.08, z, 0.1, 0.1, 0.2, g);
  for (const sx of [-0.03, 0.03]) for (const sz of [-0.07, 0.07]) k.box(x + sx, 0, z + sz, 0.03, 0.08, 0.03, g);
  k.box(x, 0.12, z + 0.12, 0.08, 0.08, 0.06, g);
  k.bar([x, 0.12, z + 0.15], [x, 0.02, z + 0.17], 0.012, g);
}

function giraffe(k: Kit, x: number, z: number): void {
  const y = hex(0xe0b050), s = hex(0x9a6a2a);
  k.box(x, 0.12, z, 0.06, 0.07, 0.14, y);
  for (const sx of [-0.02, 0.02]) for (const sz of [-0.05, 0.05]) k.box(x + sx, 0, z + sz, 0.015, 0.12, 0.015, y);
  k.bar([x, 0.18, z + 0.06], [x, 0.36, z + 0.1], 0.015, y);
  k.box(x, 0.35, z + 0.12, 0.03, 0.03, 0.06, s);
}

function penguin(k: Kit, x: number, z: number): void {
  k.cyl(x, 0, z, 0.02, 0.05, DARK, 6);
  k.box(x, 0.01, z + 0.015, 0.02, 0.03, 0.01, WHITE);
}

const zoo: Draw = (k, W, D, _b, r) => {
  // the gatehouse with its arch
  const gz = D / 2 - 0.35, wall = styleWall(r), roof = styleRoof(r);
  for (const sx of [-1, 1]) {
    k.box(sx * 0.35, 0, gz, 0.3, 0.42, 0.34, wall);
    k.hip(sx * 0.35, 0.42, gz, 0.34, 0.16, 0.38, roof);
  }
  k.box(0, 0.36, gz, 0.4, 0.1, 0.2, wall);
  k.hoop(0, 0.3, gz + 0.1, 0.2, 0.02, pick(r, BRIGHT), 8);
  // a winding path
  const pts: [number, number][] = [[0, gz], [0.6, 0.8], [-0.8, 0], [0.7, -0.9], [-0.3, -1.8]];
  for (let i = 1; i < pts.length; i++) k.bar([pts[i - 1][0], 0.006, pts[i - 1][1]], [pts[i][0], 0.006, pts[i][1]], 0.1, hex(0xd9c9a3));
  // five enclosures with a shelter each and their animals
  const pens: [number, number, number][] = [[-W / 2 + 0.9, D / 2 - 1.5, 0], [W / 2 - 0.9, D / 2 - 1.6, 1], [-W / 2 + 0.9, -0.3, 2], [W / 2 - 0.9, -0.5, 0], [0, -D / 2 + 0.8, 1]];
  for (const [x, z, kind] of pens) {
    chainFence(k, x, z, 1.3, 1.0, 0.12, 0);
    k.box(x - 0.45, 0, z - 0.3, 0.3, 0.2, 0.26, WOOD, ROOF_GREY);
    if (kind === 0) { elephant(k, x + 0.1, z); elephant(k, x + 0.35, z + 0.2); }
    else if (kind === 1) { giraffe(k, x, z); giraffe(k, x + 0.3, z - 0.15); tree(k, x + 0.4, 0, z + 0.25, 0.7, false); }
    else {
      k.disc(x + 0.1, 0.006, z + 0.1, 0.35, WATER, 10, 0.25);
      for (let p = 0; p < 6; p++) penguin(k, x - 0.2 + (p % 3) * 0.1, z - 0.2 + (p > 2 ? 0.1 : 0));
    }
  }
  // the pond
  k.disc(-0.2, 0.006, 0.4, 0.4, WATER, 12, 0.3);
  for (let i = 0; i < 5; i++) tree(k, (r() - 0.5) * (W - 1), 0, (r() - 0.5) * (D - 1), 0.8, false);
};

// ---- 68. aquarium ------------------------------------------------------------------------------

/**
 * An aquarium: a hall under a wave roof whose front is one long tank behind three panes of glass, with life
 * swimming past in it (sealife.ts), an entrance at one end and portholes at the other.
 */
const aquarium: Draw = (k, W, D, _b, r) => {
  const stone = pick(r, STONE), blue = hex(0x4f8fc0), frame = hex(0x2b3846);
  const bw = W - 0.3, bd = D - 0.5, bz = -0.1, H = 0.48;
  // the tank fills the front of the hall: its glass FT thick, its inside T - FT deep, running past the window to both ends
  const fz = bz + bd / 2, FT = 0.04, T = 0.24, zb = fz - T, zg = fz - FT, zf = fz - FT / 2;
  const TH = bw / 2 - 0.05, WX = Math.min(0.7, TH - 0.6), WY0 = 0.08, WY1 = 0.4;
  const back = bz - bd / 2, backBlue = bz - (bd - 0.1) / 2;
  k.box(0, 0, (back + zb) / 2, bw, 0.2, zb - back, stone);
  k.box(0, 0.2, (backBlue + zb) / 2, bw - 0.1, H - 0.2, zb - backBlue, blue);
  for (const s of [-1, 1]) {
    // the tank's end walls, then the piers either side of the window
    const ex = s * (TH + bw / 2) / 2, px = s * (WX + bw / 2) / 2, pw = bw / 2 - WX;
    k.box(ex, 0, (zb + zg) / 2, bw / 2 - TH, 0.2, zg - zb, stone);
    k.box(ex, 0.2, (zb + zg) / 2, bw / 2 - TH, H - 0.2, zg - zb, blue);
    k.box(px, WY0, zf, pw, 0.2 - WY0, FT, stone);
    k.box(px, 0.2, zf, pw, H - 0.2, FT, blue);
  }
  k.box(0, 0, zf, bw, WY0, FT, stone);
  k.box(0, WY1, zf, WX * 2, H - WY1, FT, blue);
  k.box(0, 0.45, (zb + zg) / 2, TH * 2, H - 0.45, zg - zb, blue);
  // the glass in its dark frame, in three panes
  for (const x of [-WX / 3, WX / 3]) k.box(x, WY0, zf, 0.022, WY1 - WY0, FT - 0.004, frame);
  k.detail(() => {
    k.box(0, WY1 - 0.01, fz + 0.006, WX * 2 + 0.04, 0.02, 0.012, frame);
    k.box(0, WY0 - 0.012, fz + 0.006, WX * 2 + 0.04, 0.02, 0.012, frame);
    for (const s of [-1, 1]) k.box(s * (WX + 0.01), WY0 - 0.002, fz + 0.006, 0.02, WY1 - WY0 - 0.006, 0.012, frame);
  });
  seaTank(k, { x0: -TH, x1: TH, wx: WX, fl: 0.035, wy0: WY0, wy1: WY1, ce: 0.45, zb, zg }, r, k.mode === 'derelict');
  // the entrance under a canopy at one end, portholes onto the tank at the other
  const dx = (WX + bw / 2) / 2;
  k.glowBox(dx, 0, fz + 0.005, 0.22, 0.24, 0.01, GLASS_LIGHT, [9, 22.5, 1.6], WARM_GLOW);
  k.box(dx, 0.26, fz + 0.08, 0.32, 0.025, 0.16, scale(blue, 0.8));
  for (const px of [-dx - 0.14, -dx + 0.14]) {
    const py = 0.28, pr = 0.055, pz = fz + 0.004;
    for (let i = 0; i < 10; i++) {
      const a0 = (i / 10) * TAU, a1 = ((i + 1) / 10) * TAU;
      k.glowTri([px, py, pz], [px + Math.cos(a0) * pr, py + Math.sin(a0) * pr, pz], [px + Math.cos(a1) * pr, py + Math.sin(a1) * pr, pz], [px, py, pz - 0.05], hex(0x2984ae), TANK, hex(0x2fc2da));
    }
    k.hoop(px, py, fz + 0.006, pr, 0.007, frame, 10);
  }
  // a wave roof: a run of half-cylinders across the hall
  const n = 5, cell = (bw - 0.1) / n;
  for (let i = 0; i < n; i++) {
    const x = -(bw - 0.1) / 2 + cell * (i + 0.5), seg = 6, R = cell / 2;
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * Math.PI, a1 = ((s + 1) / seg) * Math.PI;
      k.quad([x + Math.cos(a0) * R, 0.48 + Math.sin(a0) * R * 0.8, bz - (bd - 0.1) / 2], [x + Math.cos(a1) * R, 0.48 + Math.sin(a1) * R * 0.8, bz - (bd - 0.1) / 2],
        [x + Math.cos(a1) * R, 0.48 + Math.sin(a1) * R * 0.8, bz + (bd - 0.1) / 2], [x + Math.cos(a0) * R, 0.48 + Math.sin(a0) * R * 0.8, bz + (bd - 0.1) / 2], hex(0x6fb0d8), [x, 0.3, bz]);
    }
  }
  // the whale sign
  k.box(-bw / 3, 0.62, bz + bd / 2 - 0.05, 0.36, 0.1, 0.03, hex(0x2f4d7a));
  k.wedge(-bw / 3 - 0.22, 0.62, bz + bd / 2 - 0.05, 0.1, 0.12, 0.03, hex(0x2f4d7a));
};

// ---- 69. lido ----------------------------------------------------------------------------------

const lido: Draw = (k, W, D, _b, r) => {
  const tiles = hex(0xeaf2f2), stripe = pick(r, BRIGHT);
  const pw = W - 0.9, pd = D - 0.6, pz = 0.1;
  k.box(-0.25, 0, pz, pw + 0.12, 0.05, pd + 0.12, tiles);
  // the water is in from spring to autumn (game/pools.ts has bathers in it then), drained for the winter
  k.tagged(Vis.NotWinter, () => {
    k.box(-0.25, 0.02, pz, pw, 0.035, pd, WATER);
    // lane lines along its length (five lanes: game/pools.ts and a swim meet swim them)
    for (let i = 1; i < 5; i++) k.box(-0.25, 0.056, pz - pd / 2 + (i * pd) / 5, pw - 0.1, 0.005, 0.01, WHITE);
  });
  k.tagged(Vis.Winter, () => k.box(-0.25, 0.002, pz, pw, 0.03, pd, DRAINED));
  // diving platform at the deep end
  k.box(-0.25 - pw / 2 + 0.1, 0, pz, 0.08, 0.5, 0.08, WHITE);
  k.box(-0.25 - pw / 2 + 0.2, 0.46, pz, 0.26, 0.03, 0.1, stripe);
  // the changing block with a striped roof
  const cx = W / 2 - 0.3;
  k.box(cx, 0, pz, 0.44, 0.3, pd, WHITE);
  for (let i = 0; i < 5; i++) k.box(cx, 0.3, pz - pd / 2 + (i + 0.5) * (pd / 5), 0.48, 0.03, pd / 5, i % 2 ? WHITE : stripe);
  // the slide
  k.bar([W / 2 - 0.55, 0.36, pz - 0.2], [-0.25 + pw / 2 - 0.1, 0.05, pz + 0.3], 0.03, pick(r, BRIGHT));
  // six loungers
  for (let i = 0; i < 6; i++) k.box(-W / 2 + 0.3 + i * 0.3, 0.02, D / 2 - 0.12, 0.08, 0.02, 0.18, WHITE);
};

// ---- 70. water park ----------------------------------------------------------------------------

/**
 * A water park, the water first: a big wave pool with a beach end and whitecaps, a lazy river round a palm
 * island with rubber rings on it, a splash pool under the slide tower's three coiled tubes, and a kids'
 * splash pad of fountains; umbrellas, loungers and palms round them. Full from spring to autumn (the user,
 * 15 Oct 2026: it was only full in summer, and looked like a car park the rest of the year); drained grey
 * in winter.
 */
const waterPark: Draw = (k, W, D, _b, r) => {
  const slides = [0xe2412f, 0xf2c14e, 0x2bb3a3, 0x8e5cc7].map(hex);
  const DEEP = hex(0x2fb6dd), SHALLOW = hex(0x7fdcec), FOAM = hex(0xf4fbfc), RIM = hex(0xf2f0ea), DECK = hex(0xe8dcc0), LAWN = hex(0x7fbf5a);
  const PALM = hex(0x3f9a4a), TRUNK = hex(0x8a6a44);
  // the deck, with lawn along the back
  k.box(0, 0, 0, W - 0.1, 0.006, D - 0.1, DECK);
  k.box(0, 0.006, -D / 2 + 0.22, W - 0.3, 0.004, 0.28, LAWN);
  /** A pool: rim, then water (or a drained floor in winter); `shallow` is a beach edge on the +x side. */
  const pool = (x: number, z: number, rx: number, rz: number, shallow = false) => {
    k.cyl(x, 0, z, rx + 0.06, 0.04, RIM, 18, RIM, rz + 0.06);
    k.tagged(Vis.NotWinter, () => {
      k.cyl(x, 0.006, z, rx, 0.04, DEEP, 18, DEEP, rz);
      if (shallow) k.disc(x + rx * 0.42, 0.05, z, rx * 0.5, SHALLOW, 14, rz * 0.8);
    });
    k.tagged(Vis.Winter, () => k.cyl(x, 0.002, z, rx, 0.03, DRAINED, 18, DRAINED, rz));
  };
  const palm = (x: number, z: number, h: number) => {
    k.bar([x, 0, z], [x + 0.04, h, z + 0.02], 0.025, TRUNK);
    for (let a = 0; a < 5; a++) {
      const ang = (a / 5) * TAU + x;
      k.bar([x + 0.04, h, z + 0.02], [x + 0.04 + Math.cos(ang) * 0.2, h - 0.07, z + 0.02 + Math.sin(ang) * 0.2], 0.03, PALM);
    }
  };
  const umbrella = (x: number, z: number, col: RGB) => {
    k.bar([x, 0, z], [x, 0.24, z], 0.008, WHITE);
    k.cone(x, 0.2, z, 0.13, 0.07, col, 8);
  };

  // the wave pool: the biggest water in the park, deep at the back, a beach at the front, whitecaps rolling in
  const wx = W * 0.2, wz = D * 0.06, wrx = W * 0.24, wrz = D * 0.3;
  pool(wx, wz, wrx, wrz, true);
  k.tagged(Vis.NotWinter, () => {
    for (let i = 0; i < 3; i++) {
      const fx = wx - wrx * 0.45 + i * wrx * 0.32;
      k.disc(fx, 0.052, wz, 0.035, FOAM, 6, wrz * (0.75 - i * 0.12));
    }
  });
  // the lazy river: a ring of water round an island with a palm, rubber rings drifting on it
  const lx = -W * 0.27, lz = D * 0.18, lr = Math.min(W, D) * 0.22;
  pool(lx, lz, lr, lr);
  k.cyl(lx, 0, lz, lr * 0.5, 0.07, LAWN, 14, LAWN);
  palm(lx, lz, 0.42);
  k.tagged(Vis.NotWinter, () => {
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + r() * 0.6, rr = lr * 0.76;
      k.hoop(lx + Math.cos(a) * rr, 0.06, lz + Math.sin(a) * rr, 0.045, 0.018, slides[i], 10, 'xz');
    }
  });

  // the slide tower at the back and its splash pool
  const splash = [-W / 2 + 0.75, -D / 2 + 0.95] as const;
  pool(splash[0], splash[1], 0.38, 0.32);
  const tx = -W / 2 + 0.38, tz = -D / 2 + 0.38, th = 1.25;
  k.box(tx, 0, tz, 0.3, th, 0.3, hex(0xcfd6d4));
  for (let y = 0.25; y < th; y += 0.25) k.box(tx, y, tz, 0.32, 0.02, 0.32, slides[0]);
  k.box(tx, th, tz, 0.4, 0.04, 0.4, slides[0]);
  k.cone(tx, th + 0.04, tz, 0.26, 0.18, slides[1], 4);
  for (let s = 0; s < 3; s++) {
    let prev: [number, number, number] = [tx + 0.15, th - s * 0.12, tz];
    const turns = 14;
    for (let i = 1; i <= turns; i++) {
      const f = i / turns, a = f * TAU * (1.1 + s * 0.3) + s * 2;
      const rr = 0.32 + s * 0.12;
      const p: [number, number, number] = [
        tx + (splash[0] - tx) * f + Math.cos(a) * rr * (1 - f),
        (th - s * 0.12) * (1 - f) + 0.06,
        tz + (splash[1] - tz) * f + Math.sin(a) * rr * (1 - f),
      ];
      k.bar(prev, p, 0.045, slides[s + 1]);
      prev = p;
    }
  }
  // an open body slide, straight down from the tower into the wave pool's deep end
  k.bar([tx + 0.15, th * 0.7, tz + 0.1], [wx - wrx * 0.7, 0.07, wz - wrz * 0.4], 0.055, slides[3]);

  // the kids' splash pad: shallow water, a mushroom fountain and jets
  const px = W / 2 - 0.55, pz = -D / 2 + 0.6;
  k.box(px, 0, pz, 0.7, 0.03, 0.6, RIM);
  k.tagged(Vis.NotWinter, () => {
    k.box(px, 0.03, pz, 0.62, 0.012, 0.52, SHALLOW);
    for (const [jx, jz] of [[-0.2, -0.15], [0.18, -0.12], [-0.15, 0.17], [0.2, 0.15]] as const) k.cone(px + jx, 0.04, pz + jz, 0.03, 0.14, FOAM, 6);
  });
  k.bar([px, 0.03, pz], [px, 0.22, pz], 0.02, slides[2]);
  k.dome(px, 0.22, pz, 0.12, slides[1], 10, 3);

  // a lifeguard's chair by the wave pool
  const gx = wx + wrx + 0.12, gz = wz - 0.1;
  for (const sx of [-1, 1]) k.bar([gx + sx * 0.05, 0, gz], [gx + sx * 0.04, 0.3, gz], 0.012, WHITE);
  k.box(gx, 0.3, gz, 0.14, 0.03, 0.12, slides[0]);
  k.box(gx, 0.33, gz - 0.05, 0.14, 0.1, 0.02, slides[0]);

  // umbrellas and loungers along the front of the wave pool, palms at the corners
  for (let i = 0; i < 4; i++) {
    const ux = wx - wrx * 0.8 + i * wrx * 0.55, uz = wz + wrz + 0.2;
    if (Math.abs(ux) > W / 2 - 0.2) continue;
    umbrella(ux, uz, slides[i % 4]);
    k.box(ux + 0.12, 0.02, uz, 0.08, 0.02, 0.18, WHITE);
  }
  palm(W / 2 - 0.2, D / 2 - 0.25, 0.5);
  palm(-W / 2 + 0.2, D / 2 - 0.3, 0.46);
  palm(W / 2 - 0.25, -D / 2 + 0.2, 0.52);

  // ticket huts at the gate
  for (const sx of [0.35, 0.85]) {
    k.box(W / 2 - sx, 0, D / 2 - 0.2, 0.26, 0.22, 0.2, pick(r, BRIGHT));
    k.gable(W / 2 - sx, 0.22, D / 2 - 0.2, 0.3, 0.08, 0.24, WHITE, WHITE);
  }
  // shuttered in winter
  k.tagged(Vis.Winter, () => k.box(0, 0, D / 2 - 0.08, W * 0.4, 0.2, 0.03, hex(0x9aa0a6)));
};

// ---- 71. mini golf -----------------------------------------------------------------------------

const miniGolf: Draw = (k, W, D, _b, r) => {
  const green = hex(0x4fb04a), edge = hex(0xd8d2c6);
  for (let i = 0; i < 9; i++) {
    const x = -W / 2 + 0.35 + (i % 3) * ((W - 0.7) / 2), z = -D / 2 + 0.35 + Math.floor(i / 3) * ((D - 0.7) / 2);
    k.box(x, 0, z, 0.46, 0.03, 0.34, edge, green);
    k.disc(x + 0.15, 0.032, z, 0.02, DARK, 6);
    const kind = i % 5;
    if (kind === 0) {
      // a windmill with turning sails
      k.cyl(x - 0.1, 0.03, z, 0.06, 0.2, WHITE, 6);
      k.cone(x - 0.1, 0.23, z, 0.07, 0.06, hex(0xe2412f), 6);
      k.spin(x - 0.1, 0.18, z + 0.07, 'z', 1.2, (s) => { s.box(0, -0.1, 0, 0.02, 0.2, 0.004, WOOD); s.box(-0.1, 0, 0, 0.2, 0.02, 0.004, WOOD); });
    } else if (kind === 1) {
      k.cyl(x - 0.1, 0.03, z, 0.04, 0.24, WHITE, 6);
      k.cyl(x - 0.1, 0.12, z, 0.042, 0.05, hex(0xe2412f), 6);
    } else if (kind === 2) {
      k.hoop(x, 0.1, z, 0.08, 0.012, hex(0x2f7fb5), 8, 'zy');
    } else if (kind === 3) {
      for (const sx of [-1, 1]) k.box(x - 0.1 + sx * 0.05, 0.03, z, 0.04, 0.14, 0.04, pick(r, STONE));
      k.box(x - 0.1, 0.12, z, 0.14, 0.04, 0.05, pick(r, STONE));
    } else {
      k.dome(x - 0.08, 0.03, z, 0.09, hex(0x2f4d7a), 8, 3);
    }
  }
  // the kiosk
  k.box(W / 2 - 0.2, 0, D / 2 - 0.15, 0.24, 0.22, 0.2, pick(r, BRIGHT));
  k.gable(W / 2 - 0.2, 0.22, D / 2 - 0.15, 0.28, 0.06, 0.24, WHITE, WHITE);
};

// ---- 72. fairground: the theme park ------------------------------------------------------------

/** The family coaster's circuit: out of the station along the front, up the left, the lift along the back, the drop down the right. */
export function familyCircuit(W: number, D: number): CP[] {
  const zf = D / 2 - 0.35, zb = 0.25, xl = -W / 2 + 0.95, xr = W / 2 - 0.3, zm = (zf + zb) / 2;
  return [
    { p: [xr - 0.75, 0.2, zf], sec: Sec.Station },
    { p: [xr - 1.3, 0.2, zf], sec: Sec.Station },
    { p: [xr - 1.85, 0.2, zf], sec: Sec.Brake },
    { p: [xl + 0.3, 0.22, zf - 0.05], sec: Sec.Brake },
    { p: [xl, 0.25, zf - 0.4], sec: Sec.Brake },
    { p: [xl, 0.3, zm], sec: Sec.Brake },
    { p: [xl + 0.1, 0.33, zb + 0.15], sec: Sec.Lift },
    { p: [xl + 0.5, 0.4, zb], sec: Sec.Lift },
    { p: [xr - 0.6, 1.0, zb] },
    { p: [xr - 0.08, 1.0, zb + 0.28] },
    { p: [xr, 0.5, zm - 0.05] },
    { p: [xr, 0.26, zm + 0.35], sec: Sec.Brake },
    { p: [xr - 0.3, 0.22, zf], sec: Sec.Brake },
  ];
}

const FAIR_LIGHTS: Sched = [17.5, 24, 2.4];
/** The bulbs of the park being drawn: all white, or rainbow (set by fairground). */
let FAIR_BULBS: RGB[] = [];
let BULB_LIT: Sched = FAIR_LIGHTS;
const SKINS = [0xf1c7a1, 0xd9a07a, 0x9a6a48, 0x6a4632].map(hex);

/** A ride's speed easing towards what it wants, at `rate` per second. */
const ease = (v: number, want: number, rate: number, dt: number) => v + Math.max(-rate * dt, Math.min(rate * dt, want - v));

/** The ferris wheel: two lit rims on their spokes turning between A-frames, the gondolas hanging level. */
function ferrisWheel(k: Kit, wx: number, wz: number, R: number, r: () => number): void {
  const hub = R + 0.22, n = 10;
  const cols = [0xe2412f, 0xf2c14e, 0x2f7fb5, 0x3f9b4a, 0x8e5cc7].map(hex);
  for (const sz of [-0.15, 0.15]) {
    k.bar([wx - 0.5, 0, wz + sz], [wx, hub, wz + sz], 0.03, WHITE);
    k.bar([wx + 0.5, 0, wz + sz], [wx, hub, wz + sz], 0.03, WHITE);
    k.bar([wx - 0.25, hub / 2, wz + sz], [wx + 0.25, hub / 2, wz + sz], 0.015, WHITE);
  }
  k.bar([wx, hub, wz - 0.17], [wx, hub, wz + 0.17], 0.03, METAL);
  // the boarding platform and its booth, lit at night
  k.box(wx, 0, wz + 0.05, 0.5, 0.06, 0.4, hex(0xcfc6b0));
  k.box(wx + 0.38, 0, wz + 0.28, 0.18, 0.2, 0.16, hex(0xe2412f));
  k.glowBox(wx + 0.38, 0.12, wz + 0.365, 0.12, 0.06, 0.01, WHITE, FAIR_LIGHTS, SHOP_GLOW);
  const wheel = (s: Kit) => {
    s.hoop(0, 0, -0.1, R, 0.018, WHITE, 24);
    s.hoop(0, 0, 0.1, R, 0.018, WHITE, 24);
    s.hoop(0, 0, -0.1, R * 0.55, 0.012, WHITE, 16);
    s.hoop(0, 0, 0.1, R * 0.55, 0.012, WHITE, 16);
    s.bar([0, 0, -0.14], [0, 0, 0.14], 0.06, hex(0xe2412f));
    for (let i = 0; i < n; i++) {
      const a = (i / n) * TAU, c = Math.cos(a) * R, sn = Math.sin(a) * R;
      for (const z of [-0.1, 0.1]) s.bar([0, 0, z], [c, sn, z], 0.009, WHITE);
      s.bar([c, sn, -0.1], [c, sn, 0.1], 0.012, WHITE);
      // bulbs along each spoke and round both rims
      for (let j = 1; j <= 3; j++) {
        s.glowBox((c * j) / 4, (sn * j) / 4, 0.11, 0.022, 0.022, 0.012, FAIR_BULBS[(i + j) % FAIR_BULBS.length], BULB_LIT, FAIR_BULBS[(i + j) % FAIR_BULBS.length]);
      }
    }
    for (let i = 0; i < 40; i++) {
      const a = (i / 40) * TAU;
      for (const z of [-0.115, 0.115]) s.glowBox(Math.cos(a) * R, Math.sin(a) * R, z, 0.026, 0.026, 0.012, FAIR_BULBS[i % FAIR_BULBS.length], BULB_LIT, FAIR_BULBS[i % FAIR_BULBS.length]);
    }
    s.glowBox(0, -0.03, 0.145, 0.1, 0.06, 0.012, WHITE, FAIR_LIGHTS, hex(0xffe06a));
  };
  const gondola = (i: number) => (s: Kit) => {
    const c = cols[i % cols.length];
    s.bar([0, 0.01, 0], [0, -0.07, 0], 0.008, DARK);
    s.box(0, -0.22, 0, 0.15, 0.1, 0.14, c, scale(c, 1.1));
    s.box(0, -0.12, 0, 0.13, 0.04, 0.12, hex(0x9cc6d9));
    s.box(0, -0.08, 0, 0.17, 0.02, 0.16, scale(c, 0.8));
    s.box(0, -0.13, 0.055, 0.03, 0.03, 0.03, SKINS[Math.floor(r() * SKINS.length)]);
  };
  let theta = r() * TAU, w = 0, clock = 0;
  k.rig(wx, hub, wz, [wheel, ...Array.from({ length: n }, (_, i) => gondola(i))], (objs, dt, hour) => {
    clock += dt;
    // turns slowly, pausing now and then to let a gondola off at the bottom
    const want = rideOpen(hour) && clock % 45 < 37 ? 0.22 : 0;
    w = ease(w, want, 0.08, dt);
    theta += w * dt;
    objs[0].rotation.z = theta;
    for (let i = 1; i < objs.length; i++) {
      const a = theta + ((i - 1) / n) * TAU;
      objs[i].position.set(Math.cos(a) * R, Math.sin(a) * R, 0);
      objs[i].rotation.z = Math.sin(clock * 1.6 + i) * 0.05 * (w / 0.22);
    }
  });
}

/** One carousel horse on its pole at (x, z), facing `yaw` about +x. */
function horse(s: Kit, x: number, z: number, yaw: number, col: RGB, saddle: RGB): void {
  const c = Math.cos(yaw), sn = Math.sin(yaw);
  const at = (u: number, y: number, v: number): [number, number, number] => [x + u * c + v * sn, y, z - u * sn + v * c];
  s.bar(at(-0.05, 0.14, 0), at(0.05, 0.14, 0), 0.025, col);
  s.bar(at(0.05, 0.15, 0), at(0.085, 0.21, 0), 0.016, col);
  s.bar(at(0.085, 0.21, 0), at(0.11, 0.2, 0), 0.013, col);
  for (const [u, v] of [[-0.04, -0.012], [-0.04, 0.012], [0.04, -0.012], [0.04, 0.012]]) s.bar(at(u, 0.13, v), at(u + (u > 0 ? 0.02 : -0.02), 0.07, v), 0.007, col);
  s.bar(at(-0.055, 0.15, 0), at(-0.08, 0.1, 0), 0.008, DARK);
  s.bar(at(-0.01, 0.17, 0), at(0.02, 0.17, 0), 0.02, saddle);
}

/** The merry-go-round: a turning deck of rising and falling horses under a striped, bulb-lit canopy. */
function carousel(k: Kit, cx: number, cz: number, R: number, r: () => number): void {
  const n = 12, ring = R * 0.75, inner = R * 0.45;
  const radius = (i: number) => (i % 3 === 2 ? inner : ring);
  k.cyl(cx, 0, cz, R + 0.04, 0.05, GOLD, 16);
  // the turning part: deck, poles, centre drum, canopy and its lights
  const deck = (s: Kit) => {
    s.cyl(0, 0, 0, R, 0.04, hex(0x8a5a3a), 16, hex(0xb07a4a));
    s.cyl(0, 0.04, 0, R * 0.25, 0.5, hex(0xf2c14e), 12, WHITE);
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU;
      s.glowBox(Math.cos(a) * R * 0.255, 0.3, Math.sin(a) * R * 0.255, 0.04, 0.04, 0.02, hex(0xf4e3b0), FAIR_LIGHTS, hex(0xffe06a));
    }
    for (let i = 0; i < n; i++) {
      const a = (i / n) * TAU, rr = radius(i);
      s.bar([Math.cos(a) * rr, 0.04, Math.sin(a) * rr], [Math.cos(a) * rr, 0.6, Math.sin(a) * rr], 0.006, GOLD);
    }
    const stripes = 16, top = 0.86, eave = 0.58;
    for (let i = 0; i < stripes; i++) {
      const a0 = (i / stripes) * TAU, a1 = ((i + 1) / stripes) * TAU;
      const p0: [number, number, number] = [Math.cos(a0) * (R + 0.06), eave, Math.sin(a0) * (R + 0.06)];
      const p1: [number, number, number] = [Math.cos(a1) * (R + 0.06), eave, Math.sin(a1) * (R + 0.06)];
      s.tri([0, top, 0], p0, p1, i % 2 ? WHITE : hex(0xe2412f), [0, eave - 0.2, 0]);
      s.tri([0, eave - 0.01, 0], p1, p0, hex(0xf4e3b0), [0, top, 0]);
      // the valance hanging round the eave
      s.quad(p0, p1, [p1[0], eave - 0.07, p1[2]], [p0[0], eave - 0.07, p0[2]], i % 2 ? hex(0xf2c14e) : hex(0x2f7fb5), [0, eave, 0]);
    }
    for (let i = 0; i < 32; i++) {
      const a = (i / 32) * TAU;
      s.glowBox(Math.cos(a) * (R + 0.075), eave - 0.08, Math.sin(a) * (R + 0.075), 0.024, 0.024, 0.024, FAIR_BULBS[i % FAIR_BULBS.length], BULB_LIT, FAIR_BULBS[i % FAIR_BULBS.length]);
    }
    for (let i = 0; i < 16; i++) {
      const a = (i / 16) * TAU, f = 0.55;
      s.glowBox(Math.cos(a) * (R + 0.06) * f, eave + (top - eave) * (1 - f), Math.sin(a) * (R + 0.06) * f, 0.022, 0.022, 0.022, WHITE, FAIR_LIGHTS, hex(0xffe06a));
    }
    s.cyl(0, top, 0, 0.02, 0.1, GOLD, 6);
    s.glowBox(0, top + 0.1, 0, 0.05, 0.05, 0.05, GOLD, FAIR_LIGHTS, hex(0xffe06a));
  };
  const horses = (odd: number) => (s: Kit) => {
    for (let i = 0; i < n; i++) {
      if (i % 2 !== odd) continue;
      const a = (i / n) * TAU, rr = radius(i);
      // nose along the way the deck turns
      horse(s, Math.cos(a) * rr, Math.sin(a) * rr, -a - Math.PI / 2, pick(r, [0xf4f2ec, 0xf4f2ec, 0x3a3f45, 0xc08a5a]), pick(r, [0xe2412f, 0x2f7fb5, 0xd9a441, 0x3f9b4a]));
      if (r() < 0.6) s.box(Math.cos(a) * rr, 0.19, Math.sin(a) * rr, 0.035, 0.07, 0.035, SKINS[Math.floor(r() * SKINS.length)]);
    }
  };
  let theta = r() * TAU, w = 0, clock = r() * 40;
  k.rig(cx, 0.05, cz, [deck, horses(0), horses(1)], (objs, dt, hour) => {
    clock += dt;
    // a ride of half a minute, then a pause to change riders
    const want = rideOpen(hour) && clock % 42 < 32 ? 0.75 : 0;
    w = ease(w, want, 0.25, dt);
    theta += w * dt;
    for (const o of objs) o.rotation.y = theta;
    const bob = (w / 0.75) * 0.05;
    objs[1].position.y = 0.04 + Math.sin(theta * 4) * bob;
    objs[2].position.y = 0.04 - Math.sin(theta * 4) * bob;
  });
}

/**
 * A theme park: a ferris wheel turning at the back with its gondolas hanging level, a merry-go-round
 * whose horses rise and fall, a family coaster that runs on gravity (coaster.ts), a helter-skelter,
 * food stalls and an entrance arch. It opens at nine and closes at midnight; after dark every ride
 * is strung with bulbs, warm white in some parks and rainbow in others, and the paths are lamp-lit.
 */
const fairground: Draw = (k, W, D, b, r) => {
  ({ bulbs: FAIR_BULBS, lit: BULB_LIT } = lightsFor(b.seed));
  k.box(0, 0.003, 0, W - 0.1, 0.006, D - 0.1, hex(0xd9cfb4));
  ferrisWheel(k, -W / 2 + 1.1, -D / 2 + 0.45, Math.min(0.95, D * 0.24), r);
  carousel(k, W / 2 - 0.8, -D / 2 + 0.85, 0.55, r);
  // the family coaster and its little station
  const track = buildTrack(familyCircuit(W, D));
  drawTrack(k, track, { rail: hex(0xe8eef2), spine: hex(0xe2412f), legs: hex(0xf2c14e), bulbs: FAIR_BULBS, lit: FAIR_LIGHTS, bulbLit: BULB_LIT, bulbGap: 0.2 });
  const train = new Train(track, 3, 0.2, Math.floor(r() * 7));
  const tcols = [0x2bb3a3, 0xf2c14e, 0x2bb3a3].map(hex);
  k.rig(0, 0, 0, tcols.map((c, i) => (s: Kit) => drawCar(s, c, i === 0, r, 0.9, FAIR_LIGHTS)), (objs, dt, hour) => {
    train.step(dt, rideOpen(hour));
    placeCars(train, objs);
  });
  const zf = D / 2 - 0.35, xr = W / 2 - 0.3, sx0 = xr - 1.95, sx1 = xr - 0.7, smx = (sx0 + sx1) / 2;
  k.box(smx, 0, zf - 0.2, sx1 - sx0, 0.16, 0.22, hex(0xcfc6b0));
  for (const px of [sx0 + 0.05, sx1 - 0.05]) k.box(px, 0.16, zf - 0.27, 0.03, 0.3, 0.03, hex(0xe2412f));
  k.box(smx, 0.46, zf - 0.05, sx1 - sx0 + 0.05, 0.03, 0.46, hex(0xe2412f), hex(0xf4f2ec));
  k.glowBox(smx, 0.43, zf - 0.33, sx1 - sx0, 0.02, 0.02, WHITE, FAIR_LIGHTS, SHOP_GLOW);
  // the helter-skelter in the middle of the coaster's oval
  const hx = 0.25, hz = (zf + 0.25) / 2 + 0.05;
  k.cyl(hx, 0, hz, 0.14, 0.9, hex(0xf2c14e), 8);
  k.cone(hx, 0.9, hz, 0.19, 0.25, hex(0xe2412f), 8);
  k.glowBox(hx, 1.15, hz, 0.04, 0.04, 0.04, WHITE, FAIR_LIGHTS, hex(0xffe06a));
  let prev: [number, number, number] = [hx + 0.23, 0.86, hz];
  for (let i = 1; i <= 18; i++) {
    const a = (i / 18) * TAU * 2.5, y = 0.86 * (1 - i / 18) + 0.03;
    const p: [number, number, number] = [hx + Math.cos(a) * 0.23, y, hz + Math.sin(a) * 0.23];
    k.bar(prev, p, 0.03, i % 2 ? hex(0x2f7fb5) : WHITE);
    if (i % 2 === 0) k.glowBox(p[0], p[1] + 0.035, p[2], 0.02, 0.02, 0.02, FAIR_BULBS[i % FAIR_BULBS.length], BULB_LIT, FAIR_BULBS[i % FAIR_BULBS.length]);
    prev = p;
  }
  // food stalls down the left side, their counters lit
  for (let i = 0; i < 3; i++) {
    const z = -0.35 + i * 0.5, c = pick(r, BRIGHT), x = -W / 2 + 0.28;
    k.box(x, 0, z, 0.3, 0.24, 0.36, WHITE);
    k.gable(x, 0.24, z, 0.34, 0.1, 0.4, c, c, true);
    k.glowBox(x + 0.155, 0.1, z, 0.01, 0.07, 0.26, scale(c, 1.2), FAIR_LIGHTS, SHOP_GLOW);
  }
  // the entrance arch at the road, its sign in neon
  const gx = -W / 2 + 0.55, gz = D / 2 - 0.15;
  for (const sx of [-0.28, 0.28]) {
    k.box(gx + sx, 0, gz, 0.07, 0.6, 0.07, hex(0xe2412f));
    k.glowBox(gx + sx, 0.6, gz, 0.09, 0.06, 0.09, WHITE, FAIR_LIGHTS, hex(0xffe06a));
  }
  k.box(gx, 0.52, gz, 0.64, 0.14, 0.05, hex(0x2f4a6a));
  k.glowBox(gx, 0.54, gz + 0.03, 0.56, 0.1, 0.015, hex(0xf4f2ec), FAIR_LIGHTS, hex(0xff6fc0));
  // lamp posts along the paths, with strings of bulbs between them
  const lamps: [number, number][] = [[-W / 2 + 0.6, -0.15], [0.05, -0.2], [W / 2 - 0.2, 0.0], [-W / 2 + 0.6, 0.95]];
  for (const [lx, lz] of lamps) {
    k.cyl(lx, 0, lz, 0.016, 0.5, DARK, 5);
    k.glowBox(lx, 0.5, lz, 0.07, 0.06, 0.07, WHITE, FAIR_LIGHTS, WARM_GLOW);
  }
  for (let i = 0; i < 2; i++) {
    const [ax, az] = lamps[i], [bx, bz] = lamps[i + 1];
    for (let j = 1; j < 8; j++) {
      const f = j / 8, sag = Math.sin(f * Math.PI) * 0.07;
      k.glowBox(ax + (bx - ax) * f, 0.48 - sag, az + (bz - az) * f, 0.02, 0.02, 0.02, FAIR_BULBS[(i + j) % FAIR_BULBS.length], BULB_LIT, FAIR_BULBS[(i + j) % FAIR_BULBS.length]);
    }
  }
};

// ---- 73. racetrack -----------------------------------------------------------------------------

const racetrack: Draw = (k, W, D, _b, r, t) => {
  const asphalt = hex(0x55595d), ax = W / 2 - 0.55, az = D / 2 - 0.55, width = 0.5, seg = 32;
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    const P = (a: number, f: number): [number, number, number] => [Math.cos(a) * (ax - f), 0.008, Math.sin(a) * (az - f)];
    k.quad(P(a0, 0), P(a1, 0), P(a1, width), P(a0, width), asphalt, [0, -1, 0]);
    // kerbs in red and white
    k.quad(P(a0, -0.03), P(a1, -0.03), P(a1, 0), P(a0, 0), s % 2 ? WHITE : hex(0xe2412f), [0, -1, 0]);
    // tyre walls on the bends
    if (Math.abs(Math.cos(a0)) > 0.8 && s % 2 === 0) k.cyl(Math.cos(a0) * (ax + 0.12), 0, Math.sin(a0) * (az + 0.12), 0.05, 0.08, DARK, 6);
  }
  // pit lane and the start line
  k.box(0, 0.006, az - width - 0.3, W * 0.5, 0.01, 0.2, hex(0x6d7176));
  k.box(0, 0.012, az - width / 2, 0.06, 0.004, width, WHITE);
  // the grandstand along the far straight
  const accent = t?.accent !== undefined ? hex(t.accent) : pick(r, BRIGHT);
  k.wedge(0, 0, -az - 0.2, W * 0.45, 0.4, 0.34, accent);
  k.box(0, 0.5, -az - 0.28, W * 0.45 + 0.1, 0.03, 0.4, WHITE);
  for (const sx of [-1, 1]) k.box(sx * W * 0.22, 0, -az - 0.4, 0.03, 0.5, 0.03, METAL);
  k.tagged(Vis.Weekend, () => {
    for (let i = 0; i < 24; i++) k.box(-W * 0.2 + (i % 12) * (W * 0.4 / 11), 0.14 + (i >= 12 ? 0.14 : 0), -az - 0.2 - (i >= 12 ? 0.08 : -0.04), 0.03, 0.05, 0.03, pick(r, BRIGHT));
  });
  // control tower
  k.box(W / 2 - 0.35, 0, 0, 0.3, 0.7, 0.3, WHITE);
  k.box(W / 2 - 0.35, 0.7, 0, 0.4, 0.16, 0.4, GLASS_LIGHT);
  k.box(W / 2 - 0.35, 0.86, 0, 0.44, 0.03, 0.44, DARK);
  // cars on the grid
  for (let i = 0; i < 3; i++) car(k, -0.4 + i * 0.4, az - width / 2, true, pick(r, CARS));
};

// ---- 74. ice rink ------------------------------------------------------------------------------

const iceRink: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), ice = hex(0xdff2fa);
  const bw = W - 0.2, bd = D - 0.5, bz = -0.12;
  k.box(0, 0, bz, bw, 0.46, bd, wall);
  for (let i = 0; i < 4; i++) k.box(0, 0.46 + i * 0.05, bz, bw * (1 - i * 0.2), 0.05, bd + 0.02, ROOF_GREY);
  // the glass end wall with the pale blue floor behind it
  k.box(0, 0, bz + bd / 2 + 0.005, bw - 0.2, 0.4, 0.01, GLASS_LIGHT);
  k.box(0, 0.01, bz + bd / 2 - 0.2, bw - 0.3, 0.01, 0.36, ice);
  k.glowBox(0, 0.02, bz + bd / 2, bw - 0.3, 0.36, 0.01, GLASS_LIGHT, [16.5, 22.5, 1.4], hex(0xbfe8ff));
  // the resurfacer by the side door
  k.box(bw / 2 + 0.08, 0, bz, 0.12, 0.1, 0.2, hex(0x2f7fb5));
  // the snowflake sign
  for (let i = 0; i < 3; i++) k.box(0, 0.62, bz + bd / 2 - 0.02, 0.02, 0.16, 0.02, WHITE);
  for (const a of [0, TAU / 6, -TAU / 6]) k.bar([Math.sin(a) * -0.08, 0.72 - Math.cos(a) * 0.08, bz + bd / 2 + 0.01], [Math.sin(a) * 0.08, 0.72 + Math.cos(a) * 0.08, bz + bd / 2 + 0.01], 0.008, hex(0x9fd8ff));
  // an outdoor rink out front in winter
  k.tagged(Vis.Winter, () => {
    k.box(0, 0, D / 2 - 0.15, bw * 0.7, 0.03, 0.2, ice);
    for (const sx of [-1, 1]) k.box(sx * bw * 0.35, 0, D / 2 - 0.15, 0.02, 0.06, 0.22, WHITE);
  });
  void b;
};

// ---- 75. nightclub -----------------------------------------------------------------------------

const nightclub: Draw = (k, _W, _D, b, r) => {
  const neon = pick(r, NEON), h = b.floors * FLOOR + 0.06;
  k.box(0, 0, -0.1, 0.86, h, 0.66, hex(0x2f3136), hex(0x3a3f45));
  k.box(0, 0, 0.235, 0.12, 0.2, 0.02, hex(0x1a1a1a));
  // the neon name, and the sweep of light on the pavement after ten
  k.glowBox(0, h - 0.16, 0.24, 0.6, 0.08, 0.02, neon, [22, 28, 2.8], neon);
  k.glowBox(0, 0.002, 0.38, 0.7, 0.004, 0.2, DARK, [22, 28, 2.4], pick(r, NEON));
  // rope and posts
  for (let i = 0; i < 4; i++) k.cyl(-0.4 + i * 0.12, 0, 0.36, 0.012, 0.1, GOLD, 5);
  k.bar([-0.4, 0.08, 0.36], [-0.04, 0.08, 0.36], 0.006, hex(0xb73e36));
  void b;
};

// ---- 76. sports hall ---------------------------------------------------------------------------

const sportsHall: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), bw = W - 0.2, bd = D - 0.6, bz = -0.2;
  k.box(0, 0, bz, bw, 0.5, bd, wall);
  // a curved roof in courses
  for (let i = 0; i < 4; i++) k.box(0, 0.5 + i * 0.05, bz, bw + 0.02, 0.05, bd * (1 - i * 0.2), styleRoof(r));
  // glazed front
  k.box(0, 0, bz + bd / 2 + 0.005, bw - 0.2, 0.4, 0.01, GLASS_LIGHT);
  k.glowBox(0, 0.02, bz + bd / 2 + 0.0135, bw - 0.3, 0.36, 0.005, GLASS_LIGHT, [7, 22, 1.4], COOL_GLOW);
  // the climbing wall on one end
  for (let i = 0; i < 14; i++) k.box(bw / 2 + 0.01, 0.05 + (i % 5) * 0.08, bz - bd / 2 + 0.15 + ((i * 7) % 13) * (bd - 0.3) / 13, 0.02, 0.025, 0.025, pick(r, BRIGHT));
  // a row of bicycles
  for (let i = 0; i < 5; i++) {
    const x = -bw / 2 + 0.2 + i * 0.12;
    k.hoop(x, 0.04, D / 2 - 0.2 - 0.04, 0.035, 0.005, DARK, 6, 'zy');
    k.hoop(x, 0.04, D / 2 - 0.2 + 0.04, 0.035, 0.005, DARK, 6, 'zy');
  }
  void b;
};

export const VENUE_DRAW: Record<VenueKind, Draw> = {
  cinema, theatre, arena, concertHall, bowlingAlley, casino, zoo, aquarium, lido, waterPark, miniGolf, fairground,
  racetrack, iceRink, nightclub, sportsHall, ...SHOWBIZ_DRAW,
};

void [BRICK, LEAF, row, styleGlass, win];
