import { retextMission } from '../missions/textEdits';
import * as THREE from 'three';
import { press } from '../press/desk';
import { firstSentence, keyOf, townAt } from '../press/hooks';
import { N, idx, inB, heightAt, REGION_KINDS, type Building, type RegionKind, type Town, type World } from '../../world/tiles';
import { hashString, mulberry32 } from '../../world/rng';
import { storefronts, tavernName, tavernSort } from '../../world/storefronts';
import { runwaysOf } from '../../world/runways';
import { padOf } from '../../world/helipads';
import { mayorOf, personName } from '../mayor';
import { SITE_LABEL } from '../cargoTypes';
import { VEHICLES, isHelicopter, type VehicleDef } from '../vehicles';
import { buildCargoMarker, disposeCargoMarker, poseCargoMarker, type CargoMarker } from '../../render/cargoMarkers';
import { esc, money } from '../cargoHud';
import { HOUR_SECONDS } from '../nightRules';
import { surfaceY, type Door } from '../cargo';
import type { HeroSpec, Kind, Mission, Obj, PlaceRef, Reward, Thread, TownRef } from '../missions/model';
import { standNear, vehicleNoun, type Stash } from '../stash';
import { defOf } from '../fleet';
import { STORIES, type BoundJob, type JobSpec, type Story, type TaleCtx } from './stories';

/**
 * Taverns: one in every county with a town, of the town's own sort (world/storefronts.ts), with a
 * lamplit ring at its door. Stop in it, press Space, and somebody local tells you what's going on: one of
 * sixty-four stories (./stories.ts), told about this town. Half end in a job paying over $1,000 that is
 * hard in its own way, taken there and then:
 *
 * - **treasure**: a hidden place, no marker until you are within 4 tiles; stop in the ring there.
 * - **smuggle**: contraband in the hold now, a buyer in another town, the police out for it at any hour.
 * - **explore**: a wonder, a megalopolis, a biome or a far landmark you have never seen.
 * - **timed**: a named place inside a limit; **fetch**: there and back to this door inside one.
 * - **ride**: come back in a particular vehicle (a tow truck for the mayor's car, an ambulance, a bus).
 *
 * Some stories, and some jobs' pay, are tips about a vehicle nobody has claimed (game/stash.ts); every tip
 * goes in the notebook. A tavern has two stories a night (TIPS): one on the way in and one more for a
 * round. Walking out and back in finds the same face telling the same story until midnight.
 */

/** Tiles within which a hidden place's ring shows. */
const HIDDEN_REVEAL = 4;
/** A round for the house: hear another story tonight. */
const ROUND = 50;
/** Stories a tavern has in a night: the one told on the way in, and one more for a round. */
const TIPS = 2;
/** A job's reach: stopped inside this, like a drop-off ring. */
const RING = 1.6;
/** How far a job may send the player, as the crow flies. */
const NEAR = 30, FAR = 260;
/** Green, like a drop-off's ring. */
const RING_COLOUR = 0x2fbf5a;

export interface Tavern {
  /** "cx,cz#tavern". */
  key: string;
  name: string;
  word: string;
  icon: string;
  w: World; t: Town; b: Building;
  /** The ring, in the cell's tiles and in world tiles. */
  lx: number; lz: number; x: number; z: number; y: number;
}

interface TavernHost {
  seed(): string;
  hours(): number;
  /** Islands in memory, the player's first. */
  worlds(): World[];
  /** The player in world tiles, the island they are on, and what they drive. */
  player(): { w: World; x: number; z: number; v: number; def: VehicleDef } | null;
  /** Has the map been uncovered at (gx, gz)? */
  seen(gx: number, gz: number): boolean;
  cash(): number;
  spend(n: number): boolean;
  firms(): { name: string; units: number; town: string }[];
  /** Hidden vehicles not yet claimed on the islands in memory. */
  stashes(): Stash[];
  /** Missions under way. */
  active(): Mission[];
  adopt(m: Mission): string | null;
  /** The tutorial is running (Missions.learning): stories are told, but nobody offers a job. */
  learning?(): boolean;
  smuggling(): boolean;
  hotRun(w: World, from: { name: string; key: string }, pay: (tiles: number) => number, tiles: [number, number]): { to: string; tiles: number; pay: number } | string;
  announce(title: string, body: string): void;
}

/** A tip written down: what was said, by whom, on which day. */
export interface Note { line: string; from: string; day: number }
/** `told`: the stories each tavern has told each night, "tavern|day" → ids in order, "!" after one whose job was taken. `rounds` is older saves' and no longer read. */
export interface TavernSave { heard: string[]; notes: Note[]; told?: [string, string[]][]; rounds?: [string, number][] }

interface Job { view: BoundJob; title: string; take(): string | null }
interface Visit {
  t: Tavern; story: Story; ctx: TaleCtx; job: Job | null; teller: { name: string; role: string; face: string }; done?: string;
  /** "tavern|day": the night it was told on. */
  key?: string;
  /** Its job has been taken: not offered again tonight. */
  taken?: boolean;
}

const ROLES: [string, string][] = [
  ['the barkeep, polishing the same glass', '🧔'], ['a retired ferry pilot', '👴'], ['a lorry driver with a limp', '🧑‍🔧'],
  ['the landlady', '👩‍🦰'], ['a woman in a wet oilskin', '👵'], ['a farmer in town for the market', '🧑‍🌾'], ['a nervous accountant', '🧑‍💼'],
  ['an old mechanic with one glove', '🧓'], ['the cook, on her break', '👩‍🍳'], ['a postman off his round', '📮'], ['a pilot between flights', '🧑‍✈️'],
  ['a fisherman who smells of it', '🎣'],
];
const SHADY = '🕵️';

const REGION_LABEL: Record<RegionKind, string> = {
  sands: 'the Sands', icefield: 'the Icefield', shallows: 'the Shallows', green: 'the Green', heights: 'the Heights', moors: 'the Moors',
  veldt: 'the Veldt', fens: 'the Fens', terraces: 'the Terraces', whitewash: 'the Whitewash', goldhills: 'the Golden Hills',
  firecoast: 'the Fire Coast', fjords: 'the Fjordlands', bigtimber: 'the Big Timber', redrock: 'the Red Rock', dragonbay: 'Dragon Bay',
  steppe: 'the Steppe', saltpan: 'the Salt Pan', mangrove: 'the Mangroves', lavender: 'the Lavender Plateau',
};
/** What a story may call a business in town. */
const BIZ = ['bakery', 'bank', 'cafe', 'diner', 'grocery', 'hotel', 'cinema', 'brewery', 'garage', 'store', 'shop', 'fastFood', 'marketHall',
  'departmentStore', 'postOffice', 'motel', 'theatre', 'bowlingAlley', 'pub', 'library', 'museum', 'gas', 'generalStore', 'farmShop'];

const COMPASS = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
/** "north-east", from (ax, az) toward (bx, bz); screen north is −z. */
const way = (ax: number, az: number, bx: number, bz: number): string =>
  COMPASS[((Math.round(Math.atan2(bx - ax, -(bz - az)) / (Math.PI / 4)) % 8) + 8) % 8];
const r50 = (n: number): number => Math.round(n / 50) * 50;
const minutes = (secs: number): string => { const m = Math.max(1, Math.round(secs / 30) / 2); return `${m % 1 ? m.toFixed(1) : m} minute${m === 1 ? '' : 's'}`; };
const lower = (s: string): string => s[0].toLowerCase() + s.slice(1);

export class Taverns {
  private cells = new Map<string, Tavern | null>();
  readonly heard = new Set<string>();
  notes: Note[] = [];
  /** The stories told at each tavern each night, by "tavern|day": ids in order, "!" after one whose job was taken. */
  private told = new Map<string, string[]>();
  /** The last story told at each tavern tonight, by "tavern|day": walking back in finds it again. */
  private last = new Map<string, Visit>();
  private visit: Visit | null = null;
  private el = document.createElement('div');
  private notebook = false;
  /** Drop-off rings over the tavern jobs' places, by mission id. */
  private rings = new Map<number, CargoMarker>();
  private group = new THREE.Group();
  /** What it draws in the world, for the camera's clean shot to leave out. */
  get root(): THREE.Group { return this.group; }
  private time = 0;

  constructor(private host: TavernHost, scene: THREE.Scene) {
    this.el.id = 'tavern-card';
    this.el.hidden = true;
    document.body.append(this.el);
    scene.add(this.group);
    this.el.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest('button');
      if (!b) { if (e.target === this.el) this.close(); return; }
      const act = b.dataset.act;
      if (act === 'take') this.take();
      else if (act === 'leave') this.close();
      else if (act === 'round') this.round();
      else if (act === 'notes') { this.notebook = !this.notebook; this.render(); }
    });
  }

  get isOpen(): boolean { return !this.el.hidden; }

  /** The county's tavern, if it has a town. */
  of(w: World): Tavern | null {
    const k = `${w.cx},${w.cz}`;
    // a county gone from memory and come back is a new World: find its tavern in that one
    if (!this.cells.has(k) || (this.cells.get(k) && this.cells.get(k)!.w !== w)) {
      const s = storefronts(w, 'tavern')[0];
      let tv: Tavern | null = null;
      if (s) {
        const sort = tavernSort(s.t);
        tv = {
          key: `${k}#tavern`, name: tavernName(w.seed, w, s.b, s.t), word: sort.word, icon: sort.icon, w, t: s.t, b: s.b,
          lx: s.at.x, lz: s.at.z, x: s.at.x + w.ox, z: s.at.z + w.oz, y: surfaceY(w, s.at.x, s.at.z),
        };
      }
      this.cells.set(k, tv);
      // a tavern holds its whole World: let go of every county that has left memory, or each one
      // ever visited stays (about 3 MB a county; the page ran out after a few hundred)
      const resident = new Set(this.host.worlds());
      for (const [key, q] of this.cells) if (q && !resident.has(q.w) && q.w !== w) this.cells.delete(key);
      // the same for the stories held to be told again: they would keep their county's World too
      for (const [key, v] of this.last) if (!resident.has(v.t.w) && v.t.w !== w) this.last.delete(key);
    }
    const tv = this.cells.get(k) ?? null;
    return tv && !tv.b.gone ? tv : null;
  }

  byKey(key: string): Tavern | null {
    const [cx, cz] = key.split('#')[0].split(',').map(Number);
    const w = this.host.worlds().find((q) => q.cx === cx && q.cz === cz);
    return w ? this.of(w) : null;
  }

  /** The entrance rings of every tavern on the islands in memory. */
  doors(worlds: Iterable<World>): Door[] {
    const out: Door[] = [];
    for (const w of worlds) {
      const tv = this.of(w);
      if (tv) out.push({ key: `tavern:${tv.key}`, x: tv.x, z: tv.z, y: tv.y, name: tv.name, icon: tv.icon, fade: true, look: 'tavern', spent: () => this.heardTonight(tv.key) });
    }
    return out;
  }

  /** A new world: forget every county's tavern. */
  clear(): void {
    this.cells.clear();
    this.last.clear();
    this.close();
    for (const m of this.rings.values()) disposeCargoMarker(m);
    this.rings.clear();
  }

  reset(): void { this.clear(); this.heard.clear(); this.notes = []; this.told.clear(); }

  // ---- going in --------------------------------------------------------------------------------

  /** Space in the ring: someone has something to say. */
  open(key: string): void {
    const t = this.byKey(key);
    if (!t) return;
    const day = Math.floor(this.host.hours() / 24);
    const k = `${t.key}|${day}`;
    const told = this.told.get(k) ?? [];
    this.notebook = false;
    if (told.length) {
      // back in the same night: the same face, the same story, until midnight or a round
      const entry = told[told.length - 1];
      this.visit = this.last.get(k) ?? this.retell(t, day, told.length - 1, entry);
      if (this.visit) {
        this.visit.done = undefined;
        this.visit.key = k;
        this.visit.taken ||= entry.endsWith('!');
        this.last.set(k, this.visit);
      }
    } else this.hear(t, day);
    this.render();
    this.el.hidden = false;
  }

  /** The next story tonight at this tavern: told, written down, and kept to be told again. */
  private hear(t: Tavern, day: number): void {
    const k = `${t.key}|${day}`;
    const told = this.told.get(k) ?? [];
    const v = this.tell(t, day, told.length);
    this.visit = v;
    if (!v) return;
    v.key = k;
    this.told.set(k, [...told, v.story.id]);
    this.last.set(k, v);
    // last night's are done with
    for (const key of this.last.keys()) if (Number(key.split('|')[1]) < day) this.last.delete(key);
    // what is said in the tavern is what the paper hears (docs/newspaper.html): the story's first line, if it is short
    const line = firstSentence(v.story.text(v.ctx));
    if (line) press.write({ k: 'rumour', town: keyOf(t.w, t.t), at: townAt(t.w, t.t), f: { town: t.t.name, line } });
    if (v.story.tip && v.ctx.stash) this.note(`${cap(v.ctx.stash.noun)} nobody has claimed, ${v.ctx.stash.hint}.`, v.teller.name);
  }

  /**
   * Has this tavern told you its story tonight? Then its door shows faint until midnight, when someone there
   * has something new (walking back in before then only finds the same story again).
   */
  heardTonight(key: string): boolean {
    const day = Math.floor(this.host.hours() / 24);
    return (this.told.get(`${key}|${day}`)?.length ?? 0) > 0;
  }

  /** Stories this tavern has left to tell tonight. */
  private tipsLeft(key: string | undefined): number {
    return key ? TIPS - (this.told.get(key)?.length ?? 0) : 0;
  }

  close(): void {
    this.el.hidden = true;
    this.visit = null;
  }

  /** A round for the house: somebody else pipes up, once a night. */
  private round(): void {
    const v = this.visit;
    if (!v) return;
    const day = Math.floor(this.host.hours() / 24);
    const k = `${v.t.key}|${day}`;
    // past midnight with the card open: the new night's first story, on the house
    if (v.key === k && this.tipsLeft(k) <= 0) { v.done = 'That’s all the talk tonight'; this.render(); return; }
    if (v.key === k && !this.host.spend(ROUND)) { v.done = `A round is ${money(ROUND)}: not enough cash`; this.render(); return; }
    this.notebook = false;
    this.hear(v.t, day);
    this.render();
  }

  private take(): void {
    const v = this.visit;
    if (!v?.job || v.done) return;
    const why = this.whyNot(v);
    if (why) { v.done = why; this.render(); return; }
    const err = v.job.take();
    if (err) { v.done = err; this.render(); return; }
    this.heard.add(v.story.id);
    // taken: walking back in tonight finds the story told, and the job no longer on offer
    v.taken = true;
    const told = v.key ? this.told.get(v.key) : undefined;
    const i = told?.lastIndexOf(v.story.id) ?? -1;
    if (told && i >= 0) told[i] = `${v.story.id}!`;
    this.close();
  }

  private whyNot(v: Visit): string | null {
    if (!v.job) return null;
    if (v.taken) return 'You took this one';
    if (this.host.learning?.()) return 'Finish (or skip) the tutorial first';
    if (v.story.job?.k === 'smuggle') return this.host.smuggling() ? 'There’s already something in the back' : null;
    if (this.host.active().length >= 3) return 'Three jobs under way already';
    if (this.host.active().some((m) => m.tpl === `tavern:${v.story.id}`)) return 'You’re already on this one';
    return null;
  }

  /** Who says what today: a story that fits this town, not yet heard if there is one, and its job found. */
  private tell(t: Tavern, day: number, round: number): Visit | null {
    const seed = this.host.seed();
    const rnd = mulberry32(hashString(`tale|${seed}|${t.key}|${day}|${round}`));
    const base = this.context(t, rnd);
    const order = STORIES.map((s) => ({ s, k: rnd() + (this.heard.has(s.id) ? 1 : 0) })).sort((a, b) => a.k - b.k).map((q) => q.s);
    const learning = !!this.host.learning?.();
    for (const s of order) {
      // no jobs while the tutorial runs: only the stories without one are told
      if (s.job && learning) continue;
      if (s.job && this.host.active().some((m) => m.tpl === `tavern:${s.id}`)) continue;
      let job: Job | null = null;
      if (s.job) {
        job = this.bind(s, t, rnd);
        if (!job) continue;
      }
      const ctx: TaleCtx = { ...base, job: job?.view ?? null };
      if (s.needs && !s.needs(ctx)) continue;
      if (!s.job) this.heard.add(s.id);
      return { t, story: s, ctx, job, teller: this.teller(s, t, day, round) };
    }
    return null;
  }

  private teller(s: Story, t: Tavern, day: number, round: number): Visit['teller'] {
    const h = hashString(`teller|${this.host.seed()}|${t.key}|${day}|${round}`);
    const [role, face] = ROLES[h % ROLES.length];
    return { name: personName(`${t.key}|${day}|${round}`), role: s.who ?? role, face: s.who ? SHADY : face };
  }

  /**
   * A story told earlier tonight, told again after the game was reloaded (in play the visit itself is
   * kept): the same story and teller, its job found afresh. Null when the job no longer fits.
   */
  private retell(t: Tavern, day: number, round: number, entry: string): Visit | null {
    const s = STORIES.find((q) => q.id === entry.replace('!', ''));
    if (!s) return null;
    const rnd = mulberry32(hashString(`tale|${this.host.seed()}|${t.key}|${day}|${round}`));
    const base = this.context(t, rnd);
    const job = s.job ? this.bind(s, t, rnd) : null;
    if (s.job && !job) return null;
    return { t, story: s, ctx: { ...base, job: job?.view ?? null }, job, teller: this.teller(s, t, day, round) };
  }

  /** What the town has to talk about. */
  private context(t: Tavern, rnd: () => number): TaleCtx {
    const w = t.w, town = t.t;
    const kinds = town.buildings.filter((b) => !b.gone && BIZ.includes(b.kind)).map((b) => b.kind);
    const label = (k: string) => `the ${lower(SITE_LABEL[k as keyof typeof SITE_LABEL] ?? k)}`;
    const uniq = [...new Set(kinds)];
    const biz = uniq.length ? label(uniq[Math.floor(rnd() * uniq.length)]) : 'the corner shop';
    const rest = uniq.filter((k) => label(k) !== biz);
    const biz2 = rest.length ? label(rest[Math.floor(rnd() * rest.length)]) : 'the post office';
    const others = this.host.worlds().flatMap((q) => q.towns.filter((o) => o !== town && o.buildings.length)
      .map((o) => ({ o, d: Math.hypot(q.ox + o.x0 + o.size / 2 - t.x, q.oz + o.z0 + o.size / 2 - t.z) })))
      .filter((q) => q.d < 220).sort((a, b) => a.d - b.d);
    const firms = this.host.firms();
    const firm = firms.length ? firms[Math.floor(rnd() * firms.length)] : null;
    const st = w.stations.find((s) => s.town === w.towns.indexOf(town)) ?? w.stations[0];
    const port = [...w.ports].sort((a, b) => Math.hypot(a.x - t.lx, a.z - t.lz) - Math.hypot(b.x - t.lx, b.z - t.lz))[0];
    const rw = runwaysOf(w)[0];
    const wonder = w.works.find((k) => k.kind === 'wonder');
    const lm = w.landmarks.filter((l) => l.name);
    const hours = this.host.hours();
    const fresh = town.buildings.filter((b) => b.grownAt !== undefined && hours - b.grownAt! < 72 && !b.gone);
    const nb = fresh.length ? fresh[Math.floor(rnd() * fresh.length)] : null;
    const stash = this.nearestStash(t);
    return {
      town: town.name, townKind: town.kind, county: w.name || 'these parts', mayor: mayorOf(town.name).name,
      tavern: t.name, word: t.word, biz, biz2, other: others[0]?.o.name ?? null, firm,
      station: st?.name ?? null, port: port?.name ?? null, airfield: rw?.name ?? null, wonder: wonder?.name ?? null,
      landmark: lm.length ? lm[Math.floor(rnd() * lm.length)].name : null,
      newBuild: nb ? `a new ${lower(SITE_LABEL[nb.kind as keyof typeof SITE_LABEL] ?? nb.kind)}` : null,
      stash: stash ? { noun: vehicleNoun(defOf(stash.model)), hint: stash.hint } : null,
      job: null,
    };
  }

  private nearestStash(t: Tavern): Stash | null {
    let best: Stash | null = null, bestD = Infinity;
    for (const s of this.host.stashes()) {
      const w = this.host.worlds().find((q) => q.cx === s.cx && q.cz === s.cz);
      if (!w) continue;
      const d = Math.hypot(w.ox + s.x - t.x, w.oz + s.z - t.z);
      if (d < bestD) { bestD = d; best = s; }
    }
    return best;
  }

  // ---- finding a job's places --------------------------------------------------------------------

  private place(w: World, lx: number, lz: number, name: string): PlaceRef {
    return { x: w.ox + lx, z: w.oz + lz, cell: [w.cx, w.cz], name };
  }

  /** Every building of these kinds on the islands in memory, with its island, between NEAR and FAR of the tavern. */
  private buildings(t: Tavern, kinds: string[], near = NEAR): { w: World; b: Building; d: number }[] {
    const out: { w: World; b: Building; d: number }[] = [];
    for (const w of this.host.worlds()) {
      for (const b of [...w.allBuildings, ...w.countryside]) {
        if (b.gone || !kinds.includes(b.kind)) continue;
        const d = Math.hypot(w.ox + b.x + b.w / 2 - t.x, w.oz + b.z + b.d / 2 - t.z);
        if (d >= near && d <= FAR) out.push({ w, b, d });
      }
    }
    return out.sort((a, b) => a.d - b.d);
  }

  /** A kerb (or a place to stand) by a building, as a PlaceRef. */
  private atBuilding(w: World, b: Building, name: string): PlaceRef | null {
    const at = standNear(w, b.x + b.w / 2, b.z + b.d / 2, Math.max(b.w, b.d) / 2 + 2, false);
    return at ? this.place(w, at.x, at.z, name) : null;
  }

  private townOfB(w: World, b: Building): Town | null { return w.towns.find((q) => q.buildings.includes(b)) ?? null; }

  /** How long a timed job gives to cover `tiles` crow-flight: brisk, not generous. */
  private limitFor(tiles: number): number {
    const def = this.host.player()?.def;
    const top = Math.max(2.2, def?.topSpeed ?? 2.6);
    return tiles * 1.35 / (top * 0.62) + 20;
  }

  /** The job a story ends in, found in this town now, or null when the world has nothing that fits. */
  private bind(s: Story, t: Tavern, rnd: () => number): Job | null {
    const spec = s.job!;
    const stash = spec.clue ? this.nearestStash(t) : null;
    const clueLine = stash ? `${cap(vehicleNoun(defOf(stash.model)))} nobody has claimed, ${stash.hint}.` : null;
    const view = (pay: string, place: string, limit: string | null, ride: string | null, far: number | null): BoundJob =>
      ({ pay, place, limit, ride, far, clue: !!clueLine });
    const townRef: TownRef = { cell: [t.w.cx, t.w.cz], id: t.t.id, name: t.t.name };
    const door: PlaceRef = this.place(t.w, t.lx, t.lz, t.name);
    const mission = (o: { title: string; why: string; details: string; thread: Thread; kind: Kind; hero: HeroSpec; caption: string; objs: Obj[]; cash: number; secs: number | null }): Mission => {
      const hours = this.host.hours();
      const reward: Reward[] = [{ r: 'cash', n: o.cash }];
      if (clueLine) reward.push({ r: 'clue', line: clueLine });
      return retextMission({
        id: 0, tpl: `tavern:${s.id}`, seed: hashString(`${t.key}|${s.id}|${hours}`), thread: o.thread, kind: o.kind,
        title: o.title, why: o.why, details: o.details,
        giver: { who: 'tavern', name: `${this.visit?.teller.name ?? 'A stranger'} at ${t.name}`, at: door, town: townRef },
        hero: o.hero, caption: o.caption, objs: o.objs, step: 0, count: 0, reward, state: 'offered', posted: hours,
        due: o.secs !== null ? hours + o.secs / HOUR_SECONDS : null,
      });
    };
    const adopt = (m: Mission): string | null => {
      const why = this.host.adopt(m);
      if (!why && clueLine) this.host.announce(m.title, 'The tip comes when it’s done');
      return why;
    };
    const far = (p: PlaceRef) => Math.hypot(p.x - t.x, p.z - t.z);

    switch (spec.k) {
      case 'treasure': {
        const spot = this.hiddenSpot(spec.at, t, rnd);
        if (!spot) return null;
        const pay = r50(1500 + rnd() * 1500 + far(spot.at) * 6);
        const title = TITLE[s.id] ?? 'Hidden Treasure';
        return {
          title, view: view(money(pay), spot.say, null, null, null),
          take: () => adopt(mission({
            title, why: `Find it from the clue alone. No marker until you’re within ${HIDDEN_REVEAL} tiles; then stop in the ring.`,
            details: `${this.visit?.teller.name ?? 'Someone'} at ${t.name} in ${t.t.name} says it’s ${spot.say}. Nobody will point the way: not the map, not the tracker.`,
            thread: 'car', kind: 'trip', hero: { kind: 'crate', colour: 0xc89a3a }, caption: 'A chest, if it’s there',
            objs: [{ t: 'reach', label: 'Find the spot', icon: '❓', at: spot.at, r: RING, stop: true, hidden: HIDDEN_REVEAL }],
            cash: pay, secs: null,
          })),
        };
      }
      case 'smuggle': {
        const pay = (tiles: number) => r50(1100 + tiles * 14);
        return {
          title: 'A Quiet Load', view: view(`${money(pay(60))}–${money(pay(160))}`, '', null, null, null),
          take: () => {
            const r = this.host.hotRun(t.w, { name: t.name, key: `tavern:${t.key}` }, pay, [60, 160]);
            if (typeof r === 'string') return r;
            if (clueLine) this.note(clueLine, this.visit?.teller.name ?? t.name);
            return null;
          },
        };
      }
      case 'explore': {
        const spot = this.unseen(spec.what, t, rnd);
        if (!spot) return null;
        const d = far(spot.at);
        const pay = r50(Math.min(6000, 1200 + d * 9));
        const title = spec.what === 'wonder' ? `See ${spot.at.name}` : spec.what === 'mega' ? `The Big City` : spec.what === 'biome' ? `Another Country` : 'Off the Map';
        return {
          title, view: view(money(pay), spot.say, null, null, d),
          take: () => adopt(mission({
            title, why: `Somewhere you’ve never been: ${spot.at.name}, ${Math.round(d)} tiles ${way(t.x, t.z, spot.at.x, spot.at.z)}. Get there and look.`,
            details: `Told at ${t.name} in ${t.t.name}. Your map is dark over it: go and see it for yourself.`,
            thread: 'car', kind: 'trip', hero: { kind: 'stamp', region: spot.region }, caption: spot.at.name,
            objs: [{ t: 'reach', label: `Reach ${short(spot.at.name)}`, icon: '🧭', at: spot.at, r: 6 }], cash: pay, secs: null,
          })),
        };
      }
      case 'timed': {
        const to = this.named(spec.to, t, rnd);
        if (!to) return null;
        const d = far(to);
        const secs = this.limitFor(d);
        const pay = r50(1100 + d * 10);
        const title = TITLE[s.id] ?? 'Against the Clock';
        return {
          title, view: view(money(pay), to.name, minutes(secs), null, d),
          take: () => adopt(mission({
            title, why: `${to.name}, ${Math.round(d)} tiles ${way(t.x, t.z, to.x, to.z)}, inside ${minutes(secs)}. Stop in the ring there.`,
            details: `Asked at ${t.name} in ${t.t.name}. The clock started when you said yes.`,
            thread: 'town', kind: 'job', hero: { kind: 'crate', colour: 0x3f8fd0 }, caption: 'An envelope that can’t be late',
            objs: [{ t: 'reach', label: `Reach ${short(to.name)}`, icon: '⏱️', at: to, r: RING, stop: true }], cash: pay, secs,
          })),
        };
      }
      case 'fetch': {
        const from = this.named(spec.from, t, rnd);
        if (!from) return null;
        const d = far(from);
        const secs = this.limitFor(d * 2) + 10;
        const pay = r50(1300 + d * 16);
        const title = TITLE[s.id] ?? 'There and Back';
        return {
          title, view: view(money(pay), from.name, minutes(secs), null, d),
          take: () => adopt(mission({
            title, why: `Collect it at ${from.name} and bring it back to ${t.name}’s door, all inside ${minutes(secs)}.`,
            details: `Asked at ${t.name} in ${t.t.name}. Stop in the ring at ${from.name}, then in the tavern’s ring and press Space.`,
            thread: 'town', kind: 'job', hero: { kind: 'crate', colour: 0xd9b34a }, caption: 'Handle with care',
            objs: [
              { t: 'reach', label: `Collect at ${short(from.name)}`, icon: '📦', at: from, r: RING, stop: true },
              { t: 'reach', label: `Back to ${short(t.name)}`, icon: t.icon, at: door, r: RING, door: true },
            ], cash: pay, secs,
          })),
        };
      }
      case 'ride': return this.rideJob(spec.ride, s, t, rnd, view, mission, adopt, door);
    }
  }

  /** A ride job: two stops, both made in the vehicle asked for. */
  private rideJob(ride: Extract<JobSpec, { k: 'ride' }>['ride'], s: Story, t: Tavern, rnd: () => number,
    view: (pay: string, place: string, limit: string | null, ride: string | null, far: number | null) => BoundJob,
    mission: (o: { title: string; why: string; details: string; thread: Thread; kind: Kind; hero: HeroSpec; caption: string; objs: Obj[]; cash: number; secs: number | null }) => Mission,
    adopt: (m: Mission) => string | null, door: PlaceRef): Job | null {
    const heli = VEHICLES.filter((d) => isHelicopter(d)).map((d) => d.id);
    const boats = VEHICLES.filter((d) => d.kind === 'water').map((d) => d.id);
    const want: Record<typeof ride, { ids: string[]; label: string; model: string }> = {
      wrecker: { ids: ['wrecker'], label: 'a tow truck', model: 'wrecker' },
      ambulance: { ids: ['ambulance'], label: 'an ambulance', model: 'ambulance' },
      bus: { ids: ['bus'], label: 'a bus', model: 'bus' },
      limo: { ids: ['limo'], label: 'a limousine', model: 'limo' },
      heli: { ids: heli, label: 'a helicopter', model: heli[0] ?? 'dragonfly' },
      boat: { ids: boats, label: 'a boat', model: 'splash' },
      quad: { ids: ['atv'], label: 'a quad bike', model: 'atv' },
    };
    const r = want[ride];
    const own = (label: string, at: PlaceRef, icon: string): Obj => ({ t: 'reach', label, icon, at, r: RING, stop: true, ride: { ids: r.ids, label: r.label } });
    const pick = <T,>(l: T[]): T | null => (l.length ? l[Math.floor(rnd() * Math.min(l.length, 4))] : null);
    let a: PlaceRef | null = null, b: PlaceRef | null = null, say = '', labels: [string, string] = ['', ''], icons: [string, string] = ['🚗', '🏁'];
    switch (ride) {
      case 'wrecker': {
        const hall = t.t.buildings.find((q) => q.kind === 'cityHall' && !q.gone);
        a = hall ? this.atBuilding(t.w, hall, `${t.t.name} town hall`) : this.place(t.w, t.lx, t.lz, `${t.t.name} town hall`);
        const pound = pick(this.buildings(t, ['scrapyard', 'police', 'recyclingCentre'], 8));
        b = pound ? this.atBuilding(pound.w, pound.b, pound.b.kind === 'police' ? 'the police pound' : 'the scrapyard') : null;
        labels = ['Hook the mayor’s car', 'Drop it at the pound']; icons = ['🪝', '🚓'];
        break;
      }
      case 'ambulance': {
        const spot = this.hiddenSpot(rnd() < 0.5 ? 'cabin' : 'landmark', t, rnd);
        a = spot ? { ...spot.at, name: 'the injured man' } : null;
        say = spot?.say ?? '';
        const hosp = pick(this.buildings(t, ['hospital', 'clinic'], 0));
        b = hosp ? this.atBuilding(hosp.w, hosp.b, hosp.b.kind === 'hospital' ? 'the hospital' : 'the clinic') : null;
        labels = ['Pick up the patient', 'To the doctor']; icons = ['🩹', '🏥'];
        break;
      }
      case 'bus': {
        const o = this.named('town', t, rnd);
        a = o ? { ...o, name: `the choir outside ${o.name}` } : null;
        say = o ? `the crossroads outside ${o.name}` : '';
        b = door;
        labels = ['Collect the choir', `Back to ${short(t.name)}`]; icons = ['🎶', t.icon];
        break;
      }
      case 'limo': {
        const hotel = pick(this.buildings(t, ['hotel', 'motel'], 8));
        a = hotel ? this.atBuilding(hotel.w, hotel.b, `the ${hotel.b.kind} in ${this.townOfB(hotel.w, hotel.b)?.name ?? 'town'}`) : null;
        say = a?.name ?? '';
        const venue = pick(this.buildings(t, ['casino', 'theatre', 'cinema', 'concertHall', 'arena', 'nightclub'], 8)
          .filter((q) => !hotel || Math.hypot(q.w.ox + q.b.x - (hotel.w.ox + hotel.b.x), q.w.oz + q.b.z - (hotel.w.oz + hotel.b.z)) > 20));
        b = venue ? this.atBuilding(venue.w, venue.b, `the ${lower(SITE_LABEL[venue.b.kind as keyof typeof SITE_LABEL] ?? venue.b.kind)}`) : null;
        labels = ['Collect the star', 'To the premiere']; icons = ['⭐', '🎬'];
        break;
      }
      case 'heli': case 'quad': {
        const spot = this.hiddenSpot(rnd() < 0.5 ? 'summit' : 'landmark', t, rnd, true);
        if (!spot) return null;
        a = { ...spot.at, name: ride === 'heli' ? 'the stranded climber' : 'the shepherd' };
        say = spot.say.startsWith('up') ? spot.say : `up ${spot.say}`;
        const hosp = pick(this.buildings(t, ['hospital'], 0));
        const pad = hosp ? padOf(hosp.b) : null;
        b = ride === 'heli' && hosp && pad ? this.place(hosp.w, pad.x, pad.z, 'the hospital pad')
          : hosp ? this.atBuilding(hosp.w, hosp.b, 'the hospital') : door;
        labels = [ride === 'heli' ? 'Land by the climber' : 'Reach the shepherd', ride === 'heli' ? 'Fly to the hospital' : 'Down to the doctor'];
        icons = ['🧗', '🏥'];
        break;
      }
      case 'boat': {
        const spot = this.waterSpot(t, rnd);
        if (!spot) return null;
        a = { ...spot.at, name: 'the old skipper' };
        say = spot.say;
        b = null;
        labels = ['Take him his mail', ''];
        icons = ['✉️', ''];
        break;
      }
    }
    if (!a) return null;
    const fa = Math.hypot(a.x - t.x, a.z - t.z), fb = b ? Math.hypot(b.x - a.x, b.z - a.z) : 0;
    const pay = r50(2000 + rnd() * 1500 + (fa + fb) * 8);
    const title = TITLE[s.id] ?? 'A Particular Job';
    const objs: Obj[] = [own(labels[0], a, icons[0])];
    if (b) objs.push(b === door ? { t: 'reach', label: labels[1], icon: icons[1], at: door, r: RING, door: true, ride: { ids: r.ids, label: r.label } } : own(labels[1], b, icons[1]));
    return {
      title, view: view(money(pay), say || a.name, null, r.label, fa),
      take: () => adopt(mission({
        title, why: `It has to be done in ${r.label}: ${a!.name}${b ? `, then ${b.name}` : ''}. Stop in the ring each time.`,
        details: `Asked at ${t.name} in ${t.t.name}. Arriving in anything but ${r.label} doesn’t count, so fetch one first if you have to.`,
        thread: 'town', kind: 'job', hero: { kind: 'vehicle', model: r.model }, caption: `Only ${r.label} will do`,
        objs, cash: pay, secs: null,
      })),
    };
  }

  /** Somewhere hidden of a kind, as a place and what a story may say of it. */
  private hiddenSpot(at: Extract<JobSpec, { k: 'treasure' }>['at'], t: Tavern, rnd: () => number, rough = false): { at: PlaceRef; say: string } | null {
    const worlds = this.host.worlds();
    const ok = (w: World, x: number, z: number) => inB(x, z) && w.water[idx(x, z)] < 0 && !w.blocked[idx(x, z)] && (rough || !!w.edges[idx(x, z)]);
    const near = (w: World, px: number, pz: number, r: number): { x: number; z: number } | null => {
      let best: { x: number; z: number } | null = null, bestD = Infinity;
      for (let z = Math.floor(pz - r); z <= pz + r; z++) for (let x = Math.floor(px - r); x <= px + r; x++) {
        if (!ok(w, x, z)) continue;
        const d = Math.hypot(x + 0.5 - px, z + 0.5 - pz);
        if (d < bestD) { bestD = d; best = { x: x + 0.5, z: z + 0.5 }; }
      }
      return best;
    };
    const inReach = (w: World, lx: number, lz: number) => { const d = Math.hypot(w.ox + lx - t.x, w.oz + lz - t.z); return d >= NEAR && d <= FAR; };
    const dir = (w: World, lx: number, lz: number) => way(t.x, t.z, w.ox + lx, w.oz + lz);
    switch (at) {
      case 'summit': {
        const w = t.w;
        let best: { x: number; z: number } | null = null, top = -Infinity;
        for (let z = 4; z < N - 4; z++) for (let x = 4; x < N - 4; x++) {
          if (!ok(w, x, z)) continue;
          const h = heightAt(w, x + 0.5, z + 0.5);
          if (h > top) { top = h; best = { x: x + 0.5, z: z + 0.5 }; }
        }
        return best ? { at: this.place(w, best.x, best.z, 'the highest point'), say: `at the highest point in ${w.name || 'the county'}` } : null;
      }
      case 'landmark': {
        const ls = worlds.flatMap((w) => w.landmarks.filter((l) => l.name && inReach(w, l.x, l.z)).map((l) => ({ w, l })));
        const q = ls.length ? ls[Math.floor(rnd() * ls.length)] : null;
        if (!q) return null;
        // somewhere about it, not its middle: a few tiles off in some direction
        const a = rnd() * Math.PI * 2, off = Math.min(q.l.r * 0.4, 6) * rnd();
        const p = near(q.w, q.l.x + Math.sin(a) * off, q.l.z + Math.cos(a) * off, 6);
        return p ? { at: this.place(q.w, p.x, p.z, q.l.name), say: `by ${q.l.name}` } : null;
      }
      case 'lighthouse': case 'cabin': {
        const ps = worlds.flatMap((w) => w.pois.filter((p) => p.type === at && inReach(w, p.x, p.z)).map((p) => ({ w, p })));
        const q = ps.length ? ps[Math.floor(rnd() * ps.length)] : null;
        if (!q) return null;
        const a = rnd() * Math.PI * 2;
        const p = near(q.w, q.p.x + Math.sin(a) * 2.5, q.p.z + Math.cos(a) * 2.5, 4);
        if (!p) return null;
        return at === 'lighthouse'
          ? { at: this.place(q.w, p.x, p.z, 'the lighthouse'), say: `by the old lighthouse on the ${dir(q.w, q.p.x, q.p.z)} coast` }
          : { at: this.place(q.w, p.x, p.z, 'the old hut'), say: `out ${dir(q.w, q.p.x, q.p.z)} of ${t.t.name}, where the old hut stood` };
      }
      case 'derelict': {
        const bs = worlds.flatMap((w) => [...w.allBuildings, ...w.countryside]
          .filter((b) => !b.gone && (b.derelict || b.kind === 'barn' || b.kind === 'shack') && inReach(w, b.x, b.z)).map((b) => ({ w, b })));
        const q = bs.length ? bs[Math.floor(rnd() * bs.length)] : null;
        if (!q) return null;
        const p = near(q.w, q.b.x + q.b.w / 2, q.b.z + q.b.d / 2, Math.max(q.b.w, q.b.d) / 2 + 2);
        const town = this.townOfB(q.w, q.b);
        return p ? { at: this.place(q.w, p.x, p.z, 'the old building'), say: town ? `somewhere by an old boarded-up place in ${town.name}` : `by an old barn ${dir(q.w, q.b.x, q.b.z)} of ${t.t.name}` } : null;
      }
      case 'beach': {
        const ss = worlds.flatMap((w) => w.spots.filter((s) => s.kind === 'beach' && inReach(w, s.x, s.z)).map((s) => ({ w, s })));
        const q = ss.length ? ss[Math.floor(rnd() * ss.length)] : null;
        if (!q) return null;
        const a = rnd() * Math.PI * 2, off = q.s.r * 0.7 * rnd();
        const p = near(q.w, q.s.x + Math.sin(a) * off, q.s.z + Math.cos(a) * off, 5);
        return p ? { at: this.place(q.w, p.x, p.z, q.s.name), say: `somewhere along ${q.s.name}` } : null;
      }
      case 'wonder': {
        const ws = worlds.flatMap((w) => w.works.filter((k) => k.kind === 'wonder' && inReach(w, k.x, k.z)).map((k) => ({ w, k })));
        const q = ws.length ? ws[Math.floor(rnd() * ws.length)] : null;
        if (!q) return null;
        const a = rnd() * Math.PI * 2;
        const p = near(q.w, q.k.x + Math.sin(a) * 9, q.k.z + Math.cos(a) * 9, 5);
        return p ? { at: this.place(q.w, p.x, p.z, q.k.name), say: q.k.name } : null;
      }
    }
  }

  /** Open water off a lighthouse or a harbour mouth, for a boat's errand. */
  private waterSpot(t: Tavern, rnd: () => number): { at: PlaceRef; say: string } | null {
    for (const w of this.host.worlds()) {
      const cands = [...w.pois.filter((p) => p.type === 'lighthouse').map((p) => ({ x: p.x, z: p.z, say: 'past the lighthouse' })),
        ...w.ports.map((p) => ({ x: p.x, z: p.z, say: `beyond the harbour mouth at ${p.name}` }))];
      for (const c of cands.sort(() => rnd() - 0.5)) {
        const d = Math.hypot(w.ox + c.x - t.x, w.oz + c.z - t.z);
        if (d > FAR) continue;
        for (let k = 0; k < 24; k++) {
          const a = (k / 24) * Math.PI * 2, rr = 7 + (k % 3) * 3;
          const x = Math.floor(c.x + Math.sin(a) * rr), z = Math.floor(c.z + Math.cos(a) * rr);
          if (!inB(x, z) || w.water[idx(x, z)] < 0) continue;
          return { at: this.place(w, x + 0.5, z + 0.5, 'the old skipper'), say: c.say };
        }
      }
    }
    return null;
  }

  /** A place never seen on the map: a wonder, a megalopolis, a biome, or any named far landmark. */
  private unseen(what: Extract<JobSpec, { k: 'explore' }>['what'], t: Tavern, rnd: () => number): { at: PlaceRef; say: string; region?: RegionKind } | null {
    const seen = (w: World, lx: number, lz: number) => this.host.seen(w.ox + lx, w.oz + lz);
    const dist = (w: World, lx: number, lz: number) => Math.hypot(w.ox + lx - t.x, w.oz + lz - t.z);
    const stand = (w: World, lx: number, lz: number, r: number) => standNear(w, lx, lz, r, false);
    const cands: { at: PlaceRef; say: string; region?: RegionKind; d: number }[] = [];
    for (const w of this.host.worlds()) {
      if (what === 'wonder') {
        for (const k of w.works) {
          if (k.kind !== 'wonder' || seen(w, k.x, k.z)) continue;
          const p = stand(w, k.x, k.z, 10);
          if (p) cands.push({ at: this.place(w, p.x, p.z, k.name), say: k.name, d: dist(w, k.x, k.z) });
        }
      } else if (what === 'mega') {
        for (const o of w.towns) {
          if (o.kind !== 'mega' && o.kind !== 'metro') continue;
          const cx = o.x0 + o.size / 2, cz = o.z0 + o.size / 2;
          if (seen(w, cx, cz)) continue;
          const p = stand(w, cx, cz, 8);
          if (p) cands.push({ at: this.place(w, p.x, p.z, o.name), say: o.name, d: dist(w, cx, cz) });
        }
      } else if (what === 'biome') {
        const mine = t.t.region ?? null;
        const found = new Set<RegionKind>();
        for (let z = 8; z < N; z += 12) for (let x = 8; x < N; x += 12) {
          const k = w.regionK[idx(x, z)];
          if (!k || w.regionW[idx(x, z)] < 200) continue;
          const region = REGION_KINDS[k - 1];
          if (region === mine || found.has(region) || seen(w, x, z)) continue;
          const p = stand(w, x + 0.5, z + 0.5, 6);
          if (!p) continue;
          found.add(region);
          cands.push({ at: this.place(w, p.x, p.z, REGION_LABEL[region]), say: `${way(t.x, t.z, w.ox + x, w.oz + z)} of here, in ${REGION_LABEL[region]}`, region, d: dist(w, x, z) });
        }
      } else {
        for (const l of w.landmarks) {
          if (!l.name || seen(w, l.x, l.z)) continue;
          const p = stand(w, l.x, l.z, 8);
          if (p) cands.push({ at: this.place(w, p.x, p.z, l.name), say: `past ${l.name}, to the ${way(t.x, t.z, w.ox + l.x, w.oz + l.z)}`, d: dist(w, l.x, l.z) });
        }
      }
    }
    const ok = cands.filter((c) => c.d >= 40 && c.d <= FAR * 1.5).sort((a, b) => a.d - b.d);
    return ok.length ? ok[Math.floor(rnd() * Math.min(3, ok.length))] : null;
  }

  /** A named place of a kind, in reach and not too close. */
  private named(kind: 'town' | 'port' | 'station' | 'airfield' | 'farm', t: Tavern, rnd: () => number): PlaceRef | null {
    const out: { p: PlaceRef; d: number }[] = [];
    for (const w of this.host.worlds()) {
      const add = (lx: number, lz: number, name: string) => {
        const p = standNear(w, lx, lz, 5, false);
        if (!p) return;
        const d = Math.hypot(w.ox + p.x - t.x, w.oz + p.z - t.z);
        if (d >= 45 && d <= FAR) out.push({ p: this.place(w, p.x, p.z, name), d });
      };
      if (kind === 'town') for (const o of w.towns) { if (o !== t.t && o.buildings.length) add(o.x0 + o.size / 2, o.z0 + o.size / 2, o.name); }
      if (kind === 'port') for (const p of w.ports) add(p.x, p.z, p.name);
      if (kind === 'station') for (const s of w.stations) { if (s.building) add(s.building.x + s.building.w / 2, s.building.z + s.building.d / 2, s.name); }
      if (kind === 'airfield') for (const r of runwaysOf(w)) { if (r.second) continue; const st = r.stands[0]; add(st.x - w.ox, st.z - w.oz, r.name); }
      if (kind === 'farm') for (const b of w.countryside) { if (b.kind === 'farmhouse' || b.kind === 'barn') add(b.x + b.w / 2, b.z + b.d / 2, `the farm ${way(t.x, t.z, w.ox + b.x, w.oz + b.z)} of ${t.t.name}`); }
    }
    if (!out.length) return null;
    out.sort((a, b) => a.d - b.d);
    return out[Math.floor(rnd() * Math.min(4, out.length))].p;
  }

  // ---- the card ----------------------------------------------------------------------------------

  private render(): void {
    const v = this.visit;
    const cash = this.host.cash();
    if (!v) {
      this.el.innerHTML = `<div class="panel"><p class="tale">The place is quiet. Nobody has anything more to say tonight.</p>
        <div class="acts"><button type="button" data-act="leave" class="later">Leave <kbd>Esc</kbd></button></div></div>`;
      return;
    }
    const t = v.t, j = v.job, why = j ? this.whyNot(v) : null;
    const spec = v.story.job;
    const needs = !spec ? '' : spec.k === 'treasure' ? `Hidden: no marker until you’re within ${HIDDEN_REVEAL} tiles`
      : spec.k === 'smuggle' ? 'Contraband, now: the police are out for it'
      : spec.k === 'explore' ? 'Somewhere your map has never shown'
      : spec.k === 'timed' ? `Against the clock: ${j?.view.limit}`
      : spec.k === 'fetch' ? `There and back to this door: ${j?.view.limit}`
      : `Only in ${j?.view.ride}`;
    const notes = this.notes.slice().reverse();
    this.el.innerHTML = `<div class="panel">
      <header><small>${esc(t.word)} · ${esc(t.t.name)}</small><b><span class="ic">${t.icon}</span> ${esc(t.name)}</b></header>
      <div class="teller"><span class="face">${v.teller.face}</span><span><b>${esc(v.teller.name)}</b><small>${esc(v.teller.role)}</small></span></div>
      <p class="tale">“${esc(v.story.text(v.ctx))}”</p>
      ${j ? `<div class="job"><div class="jhead"><b>${esc(j.title)}</b><em>${esc(j.view.pay)}</em></div>
        <small>${esc(needs)}${j.view.clue ? ' · plus a tip' : ''}</small></div>` : ''}
      ${v.done ? `<p class="whynot">${esc(v.done)}</p>` : why ? `<p class="whynot">${esc(why)}</p>` : ''}
      <div class="acts">
        ${j ? `<button type="button" data-act="take" class="take"${why ? ' disabled' : ''}>Take the job <kbd>Enter</kbd></button>` : ''}
        <button type="button" data-act="leave" class="later">${j ? 'Not for me' : 'Leave'} <kbd>Esc</kbd></button>
      </div>
      <div class="foot">
        ${this.tipsLeft(v.key) > 0
          ? `<button type="button" data-act="round" class="round${cash < ROUND ? ' short' : ''}">🍻 Buy a round · ${money(ROUND)} <small>one more story tonight</small></button>`
          : `<button type="button" class="round" disabled>🍻 That’s all the talk tonight <small>new faces in ${minutes((24 - (this.host.hours() % 24)) * HOUR_SECONDS)}</small></button>`}
        <button type="button" data-act="notes" class="notes">📓 Notebook · ${this.notes.length}</button>
      </div>
      ${this.notebook ? `<ul class="notebook">${notes.length ? notes.map((n) => `<li>${esc(n.line)}<small>${esc(n.from)} · day ${n.day + 1}</small></li>`).join('') : '<li class="none">Nothing yet. Tips about vehicles nobody has claimed go in here.</li>'}</ul>` : ''}
    </div>`;
  }

  /** Enter on the card. */
  enter(): void { if (this.visit?.job) this.take(); }

  /** A tip to keep: into the notebook, once. */
  note(line: string, from: string): void {
    if (this.notes.some((n) => n.line === line)) return;
    this.notes.push({ line, from, day: Math.floor(this.host.hours() / 24) });
    if (this.notes.length > 40) this.notes.shift();
    this.host.announce('In the notebook', line);
  }

  // ---- the rings over a job's places ---------------------------------------------------------------

  /** A drop-off ring over each tavern job's next place: a hidden one only once the player is within reach of it. */
  update(dt: number, groundY: (x: number, z: number) => number | null): void {
    this.time += dt;
    const p = this.host.player();
    const want = new Map<number, { x: number; z: number }>();
    for (const m of this.host.active()) {
      if (!m.tpl.startsWith('tavern:')) continue;
      const o = m.objs[m.step];
      if (!o || o.t !== 'reach' || o.door) continue;
      if (!p) continue;
      const d = Math.hypot(p.x - o.at.x, p.z - o.at.z);
      if (o.hidden ? d > o.hidden : d > 60) continue;
      want.set(m.id, o.at);
    }
    for (const [id, mk] of this.rings) if (!want.has(id)) { disposeCargoMarker(mk); this.rings.delete(id); }
    const reach = RING;
    for (const [id, at] of want) {
      let mk = this.rings.get(id);
      if (!mk) {
        const y = groundY(at.x, at.z);
        if (y === null) continue;
        mk = buildCargoMarker(RING_COLOUR, null);
        mk.group.position.set(at.x, y + 0.05, at.z);
        this.group.add(mk.group);
        this.rings.set(id, mk);
      }
      poseCargoMarker(mk, this.time, reach);
    }
  }

  // ---- saving ------------------------------------------------------------------------------------

  save(): TavernSave {
    return { heard: [...this.heard], notes: this.notes.slice(), told: [...this.told].slice(-20) };
  }

  load(s: TavernSave | undefined): void {
    this.heard.clear();
    for (const k of s?.heard ?? []) this.heard.add(k);
    this.notes = (s?.notes ?? []).slice();
    this.told = new Map(s?.told ?? []);
    this.last.clear();
  }

  /** For the console and the gate. */
  lines(): string[] { return STORIES.map((s) => `${s.id} ${s.topic}${s.job ? ` · job ${s.job.k}${s.job.clue ? ' + tip' : ''}` : ''}${this.heard.has(s.id) ? ' · heard' : ''}`); }
  /** pr.tavern.tell('t46'): the given story at the nearest tavern, if it can be told there. */
  force(id: string, key: string): string {
    const t = this.byKey(key);
    const s = STORIES.find((q) => q.id === id);
    if (!t || !s) return 'no such tavern or story';
    const rnd = mulberry32(hashString(`force|${id}|${this.host.hours()}`));
    const job = s.job ? this.bind(s, t, rnd) : null;
    if (s.job && !job) return `${id}: nothing in reach fits`;
    const ctx: TaleCtx = { ...this.context(t, rnd), job: job?.view ?? null };
    if (s.needs && !s.needs(ctx)) return `${id}: this town can’t tell it`;
    this.visit = { t, story: s, ctx, job, teller: { name: personName(`${t.key}|force`), role: s.who ?? 'a regular', face: s.who ? SHADY : '🧔' } };
    this.render();
    this.el.hidden = false;
    return `${id} told at ${t.name}`;
  }
}

/** A job's title, by story. */
const TITLE: Record<string, string> = {
  t02: 'The Mayor’s Car', t04: 'Twinned by Teatime', t08: 'Delicate Crate', t14: 'The Right Bolts', t16: 'The Builder’s Wages',
  t19: 'Star Treatment', t20: 'The Prize Marrow', t22: 'Forty-One Singers', t24: 'Beat Them to It', t25: 'Barnaby’s Strongbox',
  t30: 'The Captain’s Crate', t31: 'Return to Sender', t35: 'The Wedding Dress', t39: 'Stuck on Top', t41: 'Courier Drop',
  t43: 'Mail by Sea', t45: 'The Keeper’s Tin', t46: 'The Highwayman’s Chest', t48: 'The Family Silver', t50: 'Where the Goats Go',
  t55: 'The Builder’s Mark', t58: 'No Questions', t63: 'A Message Owed',
};

const cap = (s: string): string => s[0].toUpperCase() + s.slice(1);
/** A place's name cut for a tracker line (28 characters at most with the verb). */
const short = (s: string): string => (s.length > 18 ? `${s.slice(0, 17).replace(/\s+\S*$/, '')}…` : s);
