// one formatter for every figure: toLocaleString builds a new one on each call, and the tags, the cargo
// list and the prompt call this many times a frame
const WHOLE = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });

/** Dollars, whole, with thousands separators and a true minus sign: −$1,250. */
export const money = (n: number): string => `${n < 0 ? '−' : ''}$${WHOLE.format(Math.abs(Math.round(n)))}`;
