import { N, type World } from '../world/tiles';
import { DECKS, DECK_MODEL, deckLocal, deckRunway, deckStands, deckWorld, type Deck } from '../world/decks';
import type { VehicleState } from './vehicles';
import type { Fleet, Unit } from './fleet';

/**
 * The aircraft carrier's flight deck, kept true every frame (world/decks.ts has the geometry).
 *
 * Every carrier the fleet has out (the one the player is aboard, parked ones, and one a hired captain is
 * sailing) gets a deck where its hull is now. A jet flown onto a deck lands on it, rolls out on the wires
 * and is thrown off again by the catapult (game/air.ts); a jet or a helicopter sitting on a deck moves
 * with it (AirState.carry). A fleet aircraft left parked on a deck rides along too: this moves its unit
 * with the deck, and says so, so the parked meshes are re-posed.
 *
 * Deck and runway objects are kept per carrier and updated in place: the landing aid compares runways
 * by identity, and a new object every frame would read as a go-around every frame.
 */

/** A parked aircraft this close above (or below) the deck surface counts as standing on it. */
const ON_DECK = 0.35;

const kept = new Map<string, Deck>();

type WorldAt = (cx: number, cz: number) => World | null;

/** Where a carrier unit is now: its cell, its centre in world tiles, its heading and its waterline. */
function poseOf(u: Unit, worldAt: WorldAt, ridden: { w: World; state: VehicleState } | null): { w: World; x: number; z: number; heading: number; y: number } | null {
  if (u.where === 'ridden' && ridden) {
    const { w, state } = ridden;
    return { w, x: w.ox + state.x, z: w.oz + state.z, heading: state.heading, y: state.y };
  }
  if (u.agent) {
    const { w, state } = u.agent;
    return { w, x: w.ox + state.x, z: w.oz + state.z, heading: state.heading, y: state.y };
  }
  if (u.where !== 'parked') return null;
  const w = worldAt(u.cx, u.cz);
  if (!w) return null;
  return { w, x: w.ox + u.x, z: w.oz + u.z, heading: u.heading, y: u.y };
}

/**
 * Rebuild the decks from the fleet. `home` and `ridden` are the player's island and vehicle state (the
 * ridden unit's own record lags behind it). Returns true when a parked aircraft was carried, so the
 * caller re-poses the parked meshes.
 */
export function updateDecks(fleet: Fleet, worldAt: WorldAt, home: World | null, ridden: VehicleState | null): boolean {
  const live = new Set<string>();
  let moved = false;
  const riding = home && ridden ? { w: home, state: ridden } : null;
  const fresh: Deck[] = [];
  for (const u of fleet.units) {
    if (u.model !== 'carrier') continue;
    const def = fleet.defFor(u);
    if (def.kind !== 'water') continue;
    const p = poseOf(u, worldAt, riding);
    if (!p) continue;
    const key = String(u.uid);
    const scale = def.scale ?? 1;
    const y = p.y + DECK_MODEL.top * scale;
    live.add(key);
    let d = kept.get(key);
    if (d && (d.x !== p.x || d.z !== p.z || d.heading !== p.heading || Math.abs(d.y - y) > 1e-4)) {
      // carry the fleet's parked aircraft standing on it from the old pose to the new
      for (const a of fleet.units) {
        if (a.where !== 'parked' || a === u || fleet.defFor(a).kind !== 'air') continue;
        const aw = worldAt(a.cx, a.cz);
        const ox = aw ? aw.ox : a.cx * N, oz = aw ? aw.oz : a.cz * N;
        const gx = ox + a.x, gz = oz + a.z;
        if (Math.abs(a.y - d.y) > ON_DECK) continue;
        const f = deckLocal(d, gx, gz);
        const k = d.scale;
        if (Math.abs(f.along) > DECK_MODEL.halfLen * k || Math.abs(f.across) > DECK_MODEL.halfWid * k) continue;
        const n = deckWorld(p, f.along, f.across);
        const cx = Math.floor(n.x / N), cz = Math.floor(n.z / N);
        a.cx = cx; a.cz = cz;
        a.x = n.x - cx * N; a.z = n.z - cz * N;
        a.heading += Math.atan2(Math.sin(p.heading - d.heading), Math.cos(p.heading - d.heading));
        a.y = y;
        moved = true;
      }
    }
    if (!d) {
      const base = { key, name: u.name, w: p.w, x: p.x, z: p.z, heading: p.heading, y, scale };
      d = { ...base, runway: deckRunway(base) };
      kept.set(key, d);
    } else {
      d.name = u.name; d.w = p.w; d.x = p.x; d.z = p.z; d.heading = p.heading; d.y = y; d.scale = scale;
      Object.assign(d.runway, deckRunway(d));
    }
    fresh.push(d);
  }
  for (const k of [...kept.keys()]) if (!live.has(k)) kept.delete(k);
  DECKS.length = 0;
  DECKS.push(...fresh);
  return moved;
}

/** The parking spots on every deck, in world tiles (console and future use). */
function deckSpots(): { deck: string; x: number; z: number; heading: number }[] {
  return DECKS.flatMap((d) => deckStands(d).map((s) => ({ deck: d.name, ...s })));
}
