/**
 * The camera mode's recorder (docs/postcards.html, phase 1): stills and short clips of the game's own
 * canvas, cropped to the chosen frame and dressed as a postcard (game/postcardFrame.ts), with the fleet's
 * mark in one corner and the game's address in the other.
 *
 * The main renderer keeps no drawing buffer, so every frame is copied out straight after it is drawn
 * (main.ts calls `frame` after `post.render()`), into a 2D canvas whose stream a MediaRecorder encodes.
 * Nothing is uploaded: the file is the player's to post.
 */

import { drawOverlay, photoRect, type StampLook } from './postcardFrame';

/** Where the game is played, as the clip's corner says it. */
export const PLAY_ADDRESS = 'tinyfleet.up.railway.app/play';
export const PLAY_URL = `https://${PLAY_ADDRESS}/`;

/** The longest side of what is saved, in pixels. */
const MAX_SIDE = 1920;
const BITRATE = 8_000_000;
/** What to ask the browser for, best first: MP4 is what every site takes; WebM where MP4 can't be made. */
const TYPES = ['video/mp4;codecs=avc1.640028', 'video/mp4;codecs=avc1.4d002a', 'video/mp4;codecs=avc1', 'video/mp4',
  'video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm'];

/**
 * The fleet's mark: its badge (a data URL) and name, or null to leave the name off; the address in the other
 * corner (a postcard's link, or PLAY_ADDRESS); and the postage stamp for where it was taken.
 */
export interface Mark { badge: string | null; name: string | null; address?: string; stamp?: StampLook }

/** A crop of the screen, in CSS pixels. */
export interface Rect { x: number; y: number; w: number; h: number }

export interface Take { blob: Blob; url: string; type: string; ext: 'mp4' | 'webm' | 'png'; seconds: number; w: number; h: number }

export function recordType(): string | null {
  if (typeof MediaRecorder === 'undefined') return null;
  return TYPES.find((t) => MediaRecorder.isTypeSupported(t)) ?? null;
}

export class Recorder {
  private out = document.createElement('canvas');
  private g = this.out.getContext('2d')!;
  private badge: HTMLImageElement | null = null;
  /** The postcard dressing for the current size and mark, drawn once and laid over every frame. */
  private overlay: HTMLCanvasElement | null = null;
  private overlayKey = '';
  private badgeSrc = '';
  private rec: MediaRecorder | null = null;
  private track: (MediaStreamTrack & { requestFrame?: () => void }) | null = null;
  private chunks: Blob[] = [];
  private started = 0;
  private wantStill: ((t: Take | null) => void) | null = null;
  private done: ((t: Take | null) => void) | null = null;
  private type = '';
  /**
   * A clip asked for, waiting for the game's next frame to begin on. Started at once, the recorder's first frame
   * was copied from the game's canvas outside its frame, when WebGL hands back nothing: drawn over the last
   * take's frame still in the output, that left the previous clip's picture as this one's first frame, and its
   * thumbnail on Reddit.
   */
  private starting: Rect | null = null;
  /** Seconds recorded so far, or -1 when not recording. */
  get recording(): number { return this.rec ? (performance.now() - this.started) / 1000 : this.starting ? 0 : -1; }

  constructor(private source: HTMLCanvasElement) {}

  /** The mark for what is taken next. */
  private mark: Mark = { badge: null, name: null };
  setMark(m: Mark): void {
    this.mark = m;
    if (m.badge && m.badge !== this.badgeSrc) {
      this.badgeSrc = m.badge;
      const img = new Image();
      img.onload = () => { if (this.badgeSrc === m.badge) { this.badge = img; this.overlayKey = ''; } };
      img.src = m.badge;
    } else if (!m.badge) { this.badge = null; this.badgeSrc = ''; }
  }

  /** Size the output to a crop of the screen: the largest that fits MAX_SIDE, in even pixels (H.264 wants them even). */
  private size(r: Rect): { sx: number; sy: number; sw: number; sh: number } {
    const kx = this.source.width / Math.max(1, this.source.clientWidth || window.innerWidth);
    const ky = this.source.height / Math.max(1, this.source.clientHeight || window.innerHeight);
    const sx = Math.round(r.x * kx), sy = Math.round(r.y * ky), sw = Math.round(r.w * kx), sh = Math.round(r.h * ky);
    const k = Math.min(1, MAX_SIDE / Math.max(sw, sh));
    const w = Math.max(2, Math.round((sw * k) / 2) * 2), h = Math.max(2, Math.round((sh * k) / 2) * 2);
    if (this.out.width !== w || this.out.height !== h) { this.out.width = w; this.out.height = h; }
    return { sx, sy, sw, sh };
  }

  /** The frame just drawn, into the postcard's picture window, with the card, the stamp and the marks laid over it. */
  private draw(r: Rect): void {
    const { sx, sy, sw, sh } = this.size(r);
    const g = this.g, W = this.out.width, H = this.out.height;
    // the picture fills its window, cropped round its middle to the window's shape
    const p = photoRect(W, H);
    const k = Math.max(p.w / sw, p.h / sh), cw = p.w / k, ch = p.h / k;
    g.drawImage(this.source, sx + (sw - cw) / 2, sy + (sh - ch) / 2, cw, ch, p.x, p.y, p.w, p.h);
    const m = this.mark;
    // the wordmark is set in the title's Fredoka: asked for here, and the card drawn again once it has come
    const font = typeof document !== 'undefined' && !!document.fonts?.check('700 40px "Fredoka"');
    if (!font) void document.fonts?.load('700 40px "Fredoka"');
    const key = `${W}x${H}|${m.name}|${m.address}|${m.stamp?.label}|${m.stamp?.icon}|${!!this.badge}|${font}|${new Date().toDateString()}`;
    if (key !== this.overlayKey || !this.overlay) {
      this.overlayKey = key;
      this.overlay = drawOverlay(W, H, m.stamp ?? { icon: '🚗', label: 'TinyFleet', colour: '#2f7a5a' }, new Date(), (o, y, u, photo) => this.marks(o, y, u, photo));
    }
    g.drawImage(this.overlay, 0, 0);
  }

  /** The fleet's badge and name in a pill at the picture's bottom left, and where to play at its bottom right. */
  private marks(g: CanvasRenderingContext2D, y: number, u: number, p: { x: number; y: number; w: number; h: number }): void {
    const pad = Math.round(20 * u), ph = Math.round(52 * u), fs = Math.round(25 * u);
    g.font = `600 ${fs}px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif`;
    g.textBaseline = 'middle';
    g.textAlign = 'left';
    const pill = (x: number, w: number) => {
      g.fillStyle = 'rgba(20,28,34,0.55)';
      g.beginPath();
      g.roundRect(x, y, w, ph, ph / 2);
      g.fill();
    };
    const name = this.mark.name, bh = Math.round(ph * 0.8);
    const bw = this.badge ? Math.round((bh * this.badge.width) / Math.max(1, this.badge.height)) : 0;
    if (this.badge || name) {
      const tw = name ? g.measureText(name).width : 0;
      const w = Math.round((this.badge ? bw + 10 * u : 0) + tw + (name ? 32 * u : 14 * u));
      pill(p.x + pad, w);
      let x = p.x + pad + 12 * u;
      if (this.badge) { g.drawImage(this.badge, x, y + (ph - bh) / 2, bw, bh); x += bw + 10 * u; }
      if (name) { g.fillStyle = '#fff'; g.fillText(name, x, y + ph / 2 + 1); }
    }
    const addr = this.mark.address ?? PLAY_ADDRESS;
    const aw = g.measureText(addr).width + 32 * u;
    pill(p.x + p.w - pad - aw, aw);
    g.fillStyle = '#fff';
    g.fillText(addr, p.x + p.w - pad - aw + 16 * u, y + ph / 2 + 1);
  }

  /** Called by the game once a frame, straight after the frame is drawn, with the crop to take. */
  frame(r: Rect): void {
    if (!this.rec && !this.wantStill && !this.starting) return;
    // a window with nothing to show (minimised, or a hidden pane): nothing to copy this frame
    if (!this.source.width || !this.source.height || r.w < 2 || r.h < 2) return;
    this.draw(r);
    // a clip waiting to begin begins on this frame, drawn fresh just now
    if (this.starting) { this.starting = null; this.begin(); }
    if (this.wantStill) {
      const cb = this.wantStill;
      this.wantStill = null;
      const w = this.out.width, h = this.out.height;
      this.out.toBlob((blob) => cb(blob ? { blob, url: URL.createObjectURL(blob), type: 'image/png', ext: 'png', seconds: 0, w, h } : null), 'image/png');
    }
    if (this.rec) this.track?.requestFrame?.();
  }

  /**
   * The last frame taken, marks and all, as a small JPEG (base64, no prefix): a postcard's picture, its link's
   * preview. The longest side `side` pixels; null when nothing has been drawn.
   */
  thumb(side: number, quality = 0.72): string | null {
    const W = this.out.width, H = this.out.height;
    if (W < 4 || H < 4) return null;
    const k = Math.min(1, side / Math.max(W, H));
    const c = document.createElement('canvas');
    c.width = Math.round(W * k); c.height = Math.round(H * k);
    c.getContext('2d')!.drawImage(this.out, 0, 0, c.width, c.height);
    const url = c.toDataURL('image/jpeg', quality);
    return url.startsWith('data:image/jpeg;base64,') ? url.slice('data:image/jpeg;base64,'.length) : null;
  }

  /** A still of the next frame drawn. */
  still(): Promise<Take | null> {
    return new Promise((res) => { this.wantStill = res; });
  }

  /** A still asked for and not yet taken: given up (the camera closed first). */
  cancelStill(): void {
    const cb = this.wantStill;
    this.wantStill = null;
    cb?.(null);
  }

  /** Start a clip, on the game's next frame. False when this browser can't record one. */
  start(r: Rect): boolean {
    if (this.rec || this.starting) return true;
    const type = recordType();
    if (!type || !this.out.captureStream || !this.source.width || !this.source.height) return false;
    // nothing of the last take left in the output: the first frame recorded is the next one the game draws
    this.size(r);
    this.g.clearRect(0, 0, this.out.width, this.out.height);
    this.starting = r;
    return true;
  }

  /** The recorder itself, once the first frame of the clip is in the output. */
  private begin(): void {
    const type = recordType();
    if (!type) return;
    // frames are handed over one at a time as they are drawn, where the browser allows it, so the clip
    // runs at the game's own frame rate; otherwise the canvas is sampled at 30 a second
    let stream = this.out.captureStream(0);
    let track = stream.getVideoTracks()[0] as MediaStreamTrack & { requestFrame?: () => void };
    if (!track?.requestFrame) { stream = this.out.captureStream(30); track = stream.getVideoTracks()[0]; }
    let rec: MediaRecorder;
    try { rec = new MediaRecorder(stream, { mimeType: type, videoBitsPerSecond: BITRATE }); } catch { stream.getTracks().forEach((t) => t.stop()); this.done?.(null); this.done = null; return; }
    this.type = type;
    this.track = track;
    this.chunks = [];
    rec.ondataavailable = (e) => { if (e.data.size) this.chunks.push(e.data); };
    rec.onstop = () => {
      const seconds = (performance.now() - this.started) / 1000;
      const blob = new Blob(this.chunks, { type: this.type.split(';')[0] });
      this.chunks = [];
      stream.getTracks().forEach((t) => t.stop());
      const cb = this.done;
      this.done = null;
      cb?.(blob.size ? { blob, url: URL.createObjectURL(blob), type: blob.type, ext: this.type.startsWith('video/mp4') ? 'mp4' : 'webm', seconds, w: this.out.width, h: this.out.height } : null);
    };
    rec.start(1000);
    this.rec = rec;
    this.started = performance.now();
    track.requestFrame?.();
  }

  /** Stop the clip; the take comes back once the browser has finished the file. */
  stop(): Promise<Take | null> {
    // stopped before its first frame: nothing was recorded
    if (this.starting) { this.starting = null; return Promise.resolve(null); }
    const rec = this.rec;
    if (!rec) return Promise.resolve(null);
    this.rec = null;
    this.track = null;
    return new Promise((res) => { this.done = res; rec.stop(); });
  }
}
