import { hex, scale } from '../../world/biomes';
import type { Arch, BuildingKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import type { Sched } from '../nightLights';
import {
  BRICK, CARS, DARK, GLASS_LIGHT, METAL, WARM_GLOW, WHITE, car, curArch, offStrip, pick, row, styleWall, win, type Draw, type Kit,
} from './kit';
import { nameModels } from './kit';
import {
  BULB, ENAMEL_RED, SIGN_BACK, bladeName, bulbRow, frontText, marquee, marqueeBoards, roofName, tube, tubeRun, venueName, type BoardSpot,
} from './neon';

/**
 * The old-school places to go out: the opera house, and the second and third looks of the picture palace,
 * the playhouse, the diner and the bar (render/buildings/variants picks one per building by its seed).
 *
 * - **Opera house** (`operaHouse`, its own kind, on a big city's square): Garnier's gilded Paris front under
 *   its green dome (always so in Paris), Semper's rounded Dresden front, or the Met's five tall arches lit
 *   gold behind glass over a fountain.
 * - **Movie palace** (cinema): an Art Deco tower front, the name spelled down a tall blade sign crowned
 *   with a fan of neon, a marquee of chasing bulbs over the doors.
 * - **Streamline cinema** (cinema): white render, a rounded corner and speed lines, the name down a fin.
 * - **Vaudeville house** (theatre): brick and terracotta, three arched windows over a marquee, the name
 *   down a blade sign beside them.
 * - **Googie diner** (diner): glass under an upswept roof, a pylon sign with the name and a bulb arrow.
 * - **Neon diner** (diner): a stainless box with its name on a rack over the roof.
 * - **Neon bar** (pub): a brick corner bar, its name down a little blade sign, beer signs in the window.
 * - **Cocktail lounge** (pub): a black glass front, the name across it in script-bright neon and a martini glass.
 *
 * Letter boards on a marquee are lit cream panels; game/screens.ts lays what is playing over them, and
 * changes it every game day (marqueeSpots below says where they are). In towns of an older world than
 * neon (half-timbered, walled, Edo, the Shire...) the neon bar and diner draw the kind's own model instead.
 */

/** Styles with no business hanging neon on a pub or a diner: their old model stands instead. */
const NO_NEON = new Set<Arch>([
  'tudor', 'medieval', 'shire', 'norse', 'whitecity', 'spirit', 'japanese', 'chinese', 'seasia', 'eastern', 'maya', 'andean',
  'sahel', 'himalayan', 'mughal', 'moorish', 'ottoman', 'russian', 'roman', 'adobe', 'timber', 'chalet', 'granite', 'cycladic',
  'venice', 'steampunk', 'solarpunk', 'adriatic', 'onsen', 'como', 'leman',
]);
/** No neon here: a style older than neon, or a Las Vegas building off its Strip (kit.ts offStrip). */
export const neonless = (): boolean => NO_NEON.has(curArch) || offStrip;

const GOLD = hex(0xe0b040), COPPER = hex(0x5e9e86);
const STAINLESS = hex(0xd6dadf), CHROME = hex(0xeef0f2), RENDER = hex(0xf2efe8), BLACK_GLASS = hex(0x1c1e24);
/** Floodlit fronts: from dusk until the house lets out. */
const FLOOD: Sched = [17.5, 24, 1.15];

// ================================ the opera house ================================

/** The Paris opera: a gilded loggia front, paired columns, the green dome over the house, Apollo on the stage roof. */
function garnier(k: Kit, W: number, D: number): void {
  const stone = hex(0xe6dcc2), shade = scale(stone, 0.86);
  const fw = W - 0.4, fz = D / 2 - 0.5, fd = 0.8, fh = 0.98;
  // the steps up from the square
  k.box(0, 0, D / 2 - 0.12, fw, 0.04, 0.2, scale(stone, 0.9));
  k.box(0, 0, fz, fw, 0.07, fd + 0.04, shade);
  // the front block and its arcade of seven arches, lit within
  k.box(0, 0.07, fz, fw, fh, fd, stone);
  const n = 7, bay = fw / n, front = fz + fd / 2;
  for (let i = 0; i < n; i++) {
    const x = -fw / 2 + bay * (i + 0.5);
    k.box(x, 0.07, front + 0.004, bay * 0.56, 0.3, 0.01, hex(0x3a3028));
    k.glowBox(x, 0.08, front + 0.008, bay * 0.5, 0.26, 0.006, hex(0x6a5a44), FLOOD, WARM_GLOW);
  }
  // the loggia: paired columns between tall windows, a gilded statue group over each end
  for (let i = 0; i <= n; i++) {
    const x = -fw / 2 + bay * i;
    for (const s of [-0.025, 0.025]) k.cyl(x + s, 0.42, front + 0.04, 0.016, 0.42, WHITE, 6);
  }
  for (let i = 0; i < n; i++) {
    const x = -fw / 2 + bay * (i + 0.5);
    k.glowBox(x, 0.47, front + 0.006, bay * 0.42, 0.3, 0.008, hex(0x4a5a66), FLOOD, WARM_GLOW);
    k.face(x, 0.84, front + 0.012, 0.035, GOLD, 8);
  }
  k.box(0, 0.84, front + 0.03, fw + 0.04, 0.06, 0.08, shade);
  k.box(0, 0.9, fz, fw + 0.02, 0.15, fd + 0.02, stone);
  for (const s of [-1, 1]) {
    k.box(s * (fw / 2 - 0.12), 1.05, front - 0.1, 0.14, 0.14, 0.1, GOLD);
    k.cyl(s * (fw / 2 - 0.12), 1.05, front - 0.3, 0.12, 0.1, COPPER, 8);
    k.dome(s * (fw / 2 - 0.12), 1.15, front - 0.3, 0.12, COPPER, 8, 2);
  }
  // the house under its shallow green dome and gilded crown
  const hz = fz - fd / 2 - 0.55;
  k.cyl(0, 0, hz, 0.78, 1.15, stone, 16);
  k.cyl(0, 1.15, hz, 0.82, 0.06, shade, 16);
  k.cone(0, 1.21, hz, 0.8, 0.32, COPPER, 16);
  k.cyl(0, 1.5, hz, 0.12, 0.08, GOLD, 8);
  // the stage house behind, its pediment roof green, Apollo with his lyre on the peak
  const sz = -D / 2 + 0.42;
  k.box(0, 0, sz, fw * 0.82, 1.55, 0.7, scale(stone, 0.95));
  k.gable(0, 1.55, sz, fw * 0.82, 0.34, 0.7, COPPER, stone, false);
  k.box(0, 1.89, sz, 0.06, 0.16, 0.06, GOLD);
  k.box(0, 2.0, sz, 0.14, 0.04, 0.03, GOLD);
}

/** Semper's Dresden opera: a rounded front of two arcaded storeys round the house, the portal arch and its panther quadriga. */
function semper(k: Kit, W: number, D: number): void {
  const stone = hex(0xd8ccb2), shade = scale(stone, 0.85), R = Math.min(W, D) / 2 - 0.35, cz = -0.1;
  // the drum of the house and its two arcaded storeys
  k.cyl(0, 0, cz, R, 0.5, shade, 20);
  k.cyl(0, 0.5, cz, R * 0.97, 0.48, stone, 20);
  k.cyl(0, 0.98, cz, R, 0.06, shade, 20);
  for (let i = 0; i < 14; i++) {
    // the arcade's arches round the front half of the drum, lit within
    const a = Math.PI * 0.12 + (Math.PI * 0.76 * i) / 13, c = Math.cos(a), sn = Math.sin(a);
    k.glowBox(c * (R - 0.03), 0.08, cz + sn * (R - 0.03), 0.1, 0.3, 0.1, hex(0x4a3e30), FLOOD, WARM_GLOW);
    k.glowBox(c * (R * 0.97 - 0.03), 0.58, cz + sn * (R * 0.97 - 0.03), 0.09, 0.28, 0.09, hex(0x4a5864), FLOOD, WARM_GLOW);
  }
  // the hipped copper roof over the house
  k.cyl(0, 1.04, cz, R * 0.86, 0.3, scale(stone, 0.92), 16);
  k.cone(0, 1.34, cz, R * 0.9, 0.4, COPPER, 16);
  // the portal: a tall arched block on the front, the quadriga on top
  const pz = cz + R - 0.05;
  k.box(0, 0, pz, 0.7, 1.3, 0.34, stone);
  k.box(0, 0.06, pz + 0.17, 0.36, 0.84, 0.012, hex(0x3a3028));
  k.glowBox(0, 0.1, pz + 0.176, 0.3, 0.76, 0.006, hex(0x5a4a3a), FLOOD, WARM_GLOW);
  k.box(0, 1.3, pz, 0.76, 0.08, 0.4, shade);
  k.box(0, 1.38, pz, 0.34, 0.1, 0.16, hex(0x3e4a40));
  for (const s of [-1, 1]) k.box(s * 0.1, 1.48, pz + 0.04, 0.08, 0.12, 0.05, hex(0x3e4a40));
  // the stage house behind
  k.box(0, 0, -D / 2 + 0.4, W - 0.9, 1.5, 0.6, scale(stone, 0.93));
  k.hip(0, 1.5, -D / 2 + 0.4, W - 0.86, 0.3, 0.64, COPPER);
}

/** The Met: a travertine block with five tall arches of glass, the gold chandeliers lit behind them, a fountain in front. */
function metOpera(k: Kit, W: number, D: number): void {
  const trav = hex(0xf0ebe0), fw = W - 0.5, fd = 1.3, h = 1.45, bz = D / 2 - 0.85 - fd / 2;
  k.box(0, 0, bz, fw, h, fd, trav);
  k.box(0, h, bz, fw + 0.06, 0.06, fd + 0.06, scale(trav, 0.9));
  const front = bz + fd / 2, n = 5, bay = (fw - 0.2) / n;
  for (let i = 0; i < n; i++) {
    const x = -(fw - 0.2) / 2 + bay * (i + 0.5), aw = bay * 0.72;
    // the arch: a tall glass bay, its round head a disc, the chandeliers' glow behind
    k.glowBox(x, 0.02, front + 0.004, aw, h - 0.2 - aw / 2, 0.01, hex(0x5e6e78), FLOOD, hex(0xffd88a));
    k.face(x, h - 0.2 - aw / 2, front + 0.01, aw / 2, hex(0x5e6e78), 10);
    for (const y of [0.45, 0.85]) k.glowBox(x, y, front - 0.06, 0.08, 0.08, 0.04, GOLD, FLOOD, hex(0xfff0b0));
  }
  // the plaza and its fountain
  const pz = (front + D / 2 - 0.05) / 2;
  k.box(0, 0, pz, W - 0.3, 0.02, D / 2 - 0.05 - front, hex(0xe0d8c8));
  k.cyl(0, 0.02, pz, 0.24, 0.06, hex(0xe8e2d4), 14);
  k.glowBox(0, 0.08, pz, 0.3, 0.005, 0.3, hex(0x6fb8e0), FLOOD, hex(0xa8e0ff));
  k.cyl(0, 0.08, pz, 0.025, 0.16, hex(0xdff4ff), 6);
  // the wings and the stage house behind
  for (const s of [-1, 1]) k.box(s * (fw / 2 + 0.12), 0, bz - 0.1, 0.24, 0.9, fd - 0.3, scale(trav, 0.94));
  const back = bz - fd / 2;
  k.box(0, 0, (back - D / 2 + 0.1) / 2, fw * 0.8, 1.9, back + D / 2 - 0.1, scale(trav, 0.92));
}

const operaHouse: Draw = (k, W, D, _b, r) => {
  const pickDesign = curArch === 'paris' ? 0 : r();
  if (pickDesign < 0.4) garnier(k, W, D);
  else if (pickDesign < 0.7) semper(k, W, D);
  else metOpera(k, W, D);
};

// ================================ picture palaces ================================

/** Where the movie palace's marquee hangs: across the foot of the tower front. */
const palaceBoards = (W: number, D: number): BoardSpot[] => marqueeBoards(0, 0.36, D / 2 - 0.4, Math.min(1.5, W * 0.72), 0.17, 0.36);
/** And the streamline cinema's: a long flat canopy under the speed lines. */
const streamBoards = (W: number, D: number): BoardSpot[] => marqueeBoards(0.15, 0.34, D / 2 - 0.36, Math.min(1.3, W * 0.62), 0.15, 0.3);
/** And the vaudeville house's, over its doors. */
const vaudevilleBoards = (W: number, D: number): BoardSpot[] => marqueeBoards(0, 0.38, D / 2 - 0.4, Math.min(1.4, W * 0.7), 0.18, 0.34);
/** The board on the original cinema's marquee (buildings/venues.ts cinema): one long line. */
export const cinemaBoards = (W: number, D: number): BoardSpot[] => {
  const fz = -0.2 + (D - 0.5) / 2, mz = fz + 0.2;
  return [{ x: 0, y: 0.44, z: mz + 0.21, w: W * 0.56, h: 0.12, yaw: 0 }];
};

/** An Art Deco movie palace: a tower front with fins, its name down a tall blade crowned with a neon fan, a marquee of bulbs. */
const moviePalace: Draw = (k, W, D, b, r, t) => {
  const face = pick(r, [0xe8dcc0, 0xf0e2c8, 0xe2cfa8, 0xd8c8b0]), wall = scale(styleWall(r), 0.92), trim = pick(r, [0xc89a3a, 0x3a8a8a, 0xb8462e]);
  const h = Math.max(3, b.floors) * FLOOR, fz = D / 2 - 0.4;
  // the house behind and the tower front
  k.box(0, 0, -0.25, W - 0.24, h * 0.95, D - 0.9, wall);
  k.box(0, 0, fz - 0.15, W - 0.2, h + 0.25, 0.3, face, scale(face, 0.9));
  // the stepped top in the middle and the fins either side of it
  for (let i = 0; i < 3; i++) k.box(0, h + 0.25 + i * 0.08, fz - 0.15, 0.7 - i * 0.18, 0.08, 0.3 - i * 0.04, i % 2 ? trim : face);
  for (const s of [-1, 1]) for (let i = 0; i < 3; i++) k.box(s * (0.22 + i * 0.16), 0.55, fz + 0.005, 0.035, h - 0.25, 0.03, scale(face, 0.88));
  // the doors and the poster cases under the marquee, the ticket booth between
  k.box(0, 0, fz + 0.005, W * 0.5, 0.26, 0.01, hex(0x2a2420));
  for (const s of [-1, 1]) k.glowBox(s * (W * 0.36), 0.05, fz + 0.01, 0.14, 0.2, 0.012, pick(r, [0xe2412f, 0x2f7fb5, 0xf2a93b]), [17, 24, 1.3], WARM_GLOW);
  k.glowBox(0, 0, fz + 0.12, 0.16, 0.22, 0.12, GLASS_LIGHT, [16.5, 24, 1.5], WARM_GLOW);
  // the marquee
  const edge = tube(r), letter = tube(r);
  marquee(k, 0, 0.36, fz, Math.min(1.5, W * 0.72), 0.17, 0.36, pick(r, [0x2a2a30, 0xb8262e, 0x1e3a5a]));
  // the blade over it, the name in neon top to bottom
  const name = venueName(b, t, 'palace', 7);
  bladeName(k, name, 0, 0.58, fz, 0.32, 0.14, SIGN_BACK, letter, edge, { bulbs: true, crown: 'fan' });
};

/** A streamline moderne cinema: white render, a rounded corner tower, three speed lines, the name down a fin. */
const streamlineCinema: Draw = (k, W, D, b, r, t) => {
  const h = Math.max(3, b.floors) * FLOOR, fz = D / 2 - 0.36, bd = D - 0.6, bz = fz - bd / 2;
  const band = pick(r, [0x2f7fb5, 0xe2412f, 0x3f9b4a, 0x2bb3a3]);
  k.box(0.1, 0, bz, W - 0.4, h, bd, RENDER);
  // the rounded corner: a drum standing a storey proud
  const cx = -W / 2 + 0.42, cR = 0.26;
  k.cyl(cx, 0, fz - cR + 0.02, cR, h + 0.26, RENDER, 14);
  k.cyl(cx, h + 0.26, fz - cR + 0.02, cR + 0.02, 0.03, band, 14);
  // speed lines wrapping the front and the drum
  for (let i = 0; i < 3; i++) {
    const y = h - 0.12 - i * 0.07;
    k.box(0.1, y, fz + 0.004, W - 0.4, 0.02, 0.01, band);
    k.cyl(cx, y, fz - cR + 0.02, cR + 0.006, 0.02, band, 14);
  }
  // a ribbon of glass blocks up the drum, lit at night
  k.glowBox(cx, 0.4, fz + 0.02, 0.1, h - 0.6, 0.02, hex(0xcfe4ea), [17, 24, 1.4], hex(0xe8f4ff));
  // the doors and the canopy, its boards for the day's pictures
  k.box(0.15, 0, fz + 0.004, 0.6, 0.26, 0.01, hex(0x2a2420));
  marquee(k, 0.15, 0.34, fz, Math.min(1.3, W * 0.62), 0.15, 0.3, band);
  // the fin over the corner, the name in neon down it
  const edge = tube(r), letter = tube(r);
  const name = venueName(b, t, 'palace', 7);
  bladeName(k, name, cx, 0.62, fz + 0.02, 0.26, 0.13, RENDER, letter, edge, { crown: 'star', thick: 0.06 });
};

// ================================ the vaudeville house ================================

/** A vaudeville house: brick and terracotta, three arched windows over a bulb marquee, the name down a blade beside them. */
const vaudeville: Draw = (k, W, D, b, r, t) => {
  const brick = pick(r, BRICK), T = pick(r, [0xe8dcc0, 0xf0e6d2, 0xe0c8a0]);
  const h = Math.max(4, b.floors) * FLOOR, fz = D / 2 - 0.4;
  // the house and the fly tower behind
  k.box(0, 0, -0.2, W - 0.3, h * 0.85, D - 1.0, scale(brick, 0.95));
  k.box(0, 0, -D / 2 + 0.4, W * 0.62, h * 1.35, 0.6, scale(brick, 0.88));
  // the front: brick between terracotta piers, a cornice and a pediment-like parapet
  k.box(0, 0, fz - 0.15, W - 0.2, h, 0.3, brick);
  k.box(0, h - 0.04, fz - 0.15, W - 0.14, 0.08, 0.36, T);
  // three tall arched windows over the marquee, lit on show nights
  const wy = 0.66, wh = Math.max(0.16, h - 0.86);
  for (const x of [-0.36, 0, 0.36]) {
    k.box(x, wy - 0.04, fz + 0.005, 0.24, wh + 0.08, 0.01, T);
    win(k, b, r, x, wy, fz + 0.012, 0.18, wh, 1, GLASS_LIGHT);
    k.face(x, wy + wh, fz + 0.012, 0.09, scale(T, 0.9), 8);
  }
  k.box(0, 0, fz + 0.005, W * 0.46, 0.27, 0.01, hex(0x2a2420));
  marquee(k, 0, 0.38, fz, Math.min(1.4, W * 0.7), 0.18, 0.34, pick(r, [0x2a2a30, 0xb8262e, 0x6a2a5a]));
  // the blade on the corner of the front, the name in bulbs
  const edge = tube(r), name = venueName(b, t, 'palace', 8);
  bladeName(k, name, W / 2 - 0.3, 0.6, fz, 0.3, 0.13, ENAMEL_RED, BULB, edge, { crown: 'none' });
};

// ================================ diners ================================

/** A Googie diner: glass under a roof that sweeps up to the road, and the pylon with the name and a bulb arrow. */
const googieDiner: Draw = (k, _W, _D, b, r, t) => {
  const accent = pick(r, [0xf2a93b, 0x2bb3a3, 0xe2412f, 0xf29ab4]), body = pick(r, [0xf4f2ec, 0xe8e2d4]);
  const bz = -0.1, bd = 0.5, fz = bz + bd / 2;
  k.box(-0.08, 0, bz, 0.7, 0.26, bd, body);
  win(k, b, r, -0.08, 0.06, fz, 0.6, 0.16, 1, GLASS_LIGHT);
  // the roof: a slab tilted up toward the front
  k.wedge(-0.08, 0.26, bz, 0.84, 0.12, bd + 0.16, accent);
  // the pylon at the corner of the lot: a pole, the name board and the arrow
  const px = 0.36, pz = 0.3, letter = tube(r), edge = tube(r);
  k.box(px, 0, pz, 0.04, 0.62, 0.04, METAL);
  const name = venueName(b, t, 'diner', 6);
  k.box(px, 0.5, pz, 0.03, 0.18, 0.4, accent);
  if (k.mode !== 'derelict') {
    const n = [...name].length, size = Math.min(0.12, 0.34 / Math.max(1, n * 0.66));
    // both faces of the board, read from outside each
    for (const sx of [1, -1]) {
      const fx = px + sx * 0.018;
      const cw = size * 0.66, total = n * cw;
      [...name].forEach((ch, i) => {
        if (ch === ' ') return;
        const u0 = -total / 2 + i * cw, u1 = u0 + cw;
        const [za, zb] = sx > 0 ? [pz - u0, pz - u1] : [pz + u0, pz + u1];
        k.glyph(ch, [fx, 0.53, za], [fx, 0.53, zb], [fx, 0.53 + size, zb], [fx, 0.53 + size, za], letter);
      });
    }
    tubeRun(k, [px, 0.69, pz - 0.2], [px, 0.69, pz + 0.2], edge);
    // the arrow pointing in at the door: a shaft of bulbs and a head
    bulbRow(k, [px - 0.06, 0.42, pz - 0.02], [px - 0.3, 0.42, pz - 0.02], 4);
    k.glowBox(px - 0.33, 0.4, pz - 0.02, 0.05, 0.05, 0.03, edge, [16.5, 30, 1.6], edge);
  }
  car(k, -0.2, 0.36, true, pick(r, CARS));
};

/** A stainless diner with its name on a rack over the roof and OPEN lit in the window. */
const neonDiner: Draw = (k, _W, _D, b, r, t) => {
  const stripe = pick(r, [0x2f7fb5, 0xe2412f, 0x3f9b4a, 0x8e5cc7]);
  const bz = -0.08, bd = 0.46, fz = bz + bd / 2;
  k.box(0, 0, bz, 0.84, 0.28, bd, STAINLESS, scale(STAINLESS, 0.9));
  k.box(0, 0.04, bz, 0.852, 0.04, bd + 0.012, stripe);
  k.box(0, 0.22, bz, 0.852, 0.02, bd + 0.012, stripe);
  win(k, b, r, -0.08, 0.1, fz, 0.6, 0.1, 1, GLASS_LIGHT);
  // the vestibule at the end
  k.box(0.3, 0, fz + 0.06, 0.18, 0.26, 0.12, CHROME);
  const letter = tube(r), edge = tube(r);
  if (k.mode !== 'derelict') k.glowBox(-0.28, 0.13, fz + 0.012, 0.1, 0.04, 0.008, hex(0x3a2020), [6, 30, 1.6], hex(0xff4a3a));
  const name = venueName(b, t, 'diner', 7);
  roofName(k, name, -0.05, 0.28, bz + 0.05, Math.min(0.11, 0.7 / Math.max(1, [...name].length * 0.66 + 0.5)), letter, edge, 0.04);
  car(k, -0.2, 0.38, true, pick(r, CARS));
};

// ================================ bars ================================

/** A brick corner bar: glass block and a beer sign in the window, the name down a little blade sign. */
const neonBar: Draw = (k, _W, _D, b, r, t) => {
  const brick = scale(styleWall(r), 0.98), h = b.floors * FLOOR + 0.04, fz = 0.21;
  k.box(0, 0, -0.1, 0.8, h, 0.62, brick);
  k.box(0, h, -0.1, 0.84, 0.05, 0.66, scale(brick, 0.8));
  // the dark ground floor, glass blocks either side of the door and the beer signs lit in them
  k.box(0, 0, fz + 0.006, 0.8, 0.25, 0.012, hex(0x2a2226));
  for (const s of [-1, 1]) k.pane(s * 0.24, 0.06, fz + 0.014, 0.2, 0.14, 1, hex(0x8a6a4a), [16, 26, 1.6], WARM_GLOW);
  if (k.mode !== 'derelict') {
    k.glowBox(-0.24, 0.1, fz + 0.022, 0.1, 0.03, 0.006, hex(0x6a2a20), [16, 26, 1.4], hex(0xff6a3a));
    k.glowBox(0.24, 0.12, fz + 0.022, 0.06, 0.06, 0.006, hex(0x20406a), [16, 26, 1.4], hex(0x4ab0ff));
  }
  k.box(0, 0, fz + 0.016, 0.12, 0.2, 0.01, DARK);
  row(k, { ...b, kind: 'townhouse' }, r, 0, 0.34, fz, 0.6, 0.12, 3, 1);
  // the blade: the name down it in neon
  const name = venueName(b, t, 'bar', 5, k.world);
  bladeName(k, name.replace(/ /g, '').slice(0, 5), 0.32, 0.27, fz, 0.16, 0.075, SIGN_BACK, tube(r), tube(r), { thick: 0.035 });
};

/** A cocktail lounge: a black glass front, its name across the top in neon, a martini glass lit beside the door. */
const cocktailLounge: Draw = (k, _W, _D, b, r, t) => {
  const wall = styleWall(r), h = b.floors * FLOOR + 0.04, fz = 0.21;
  k.box(0, 0, -0.1, 0.8, h, 0.62, wall);
  k.box(0, h, -0.1, 0.84, 0.04, 0.66, scale(wall, 0.85));
  row(k, { ...b, kind: 'townhouse' }, r, 0, 0.34, fz, 0.6, 0.12, 3, 1);
  // the black glass front and the fascia over it
  k.box(0, 0, fz + 0.008, 0.8, 0.26, 0.016, BLACK_GLASS);
  const letter = tube(r), glass = tube(r);
  const name = venueName(b, t, 'bar', 8, k.world);
  k.box(0, 0.26, fz + 0.02, 0.8, 0.07, 0.02, SIGN_BACK);
  frontText(k, name, 0, 0.27, fz + 0.03, Math.min(0.05, 0.72 / Math.max(1, [...name].length * 0.66)), letter);
  if (k.mode !== 'derelict') {
    // the martini glass: a bowl, a stem, an olive
    const gx = 0.26, gy = 0.07;
    k.glowBox(gx, gy + 0.09, fz + 0.03, 0.09, 0.012, 0.006, scale(glass, 0.6), [16.5, 27, 1.6], glass);
    k.glowBox(gx - 0.025, gy + 0.06, fz + 0.03, 0.04, 0.03, 0.006, scale(glass, 0.6), [16.5, 27, 1.6], glass);
    k.glowBox(gx, gy + 0.01, fz + 0.03, 0.008, 0.05, 0.006, scale(glass, 0.6), [16.5, 27, 1.6], glass);
    k.glowBox(gx, gy, fz + 0.03, 0.05, 0.01, 0.006, scale(glass, 0.6), [16.5, 27, 1.6], glass);
    k.glowBox(gx + 0.015, gy + 0.075, fz + 0.034, 0.014, 0.014, 0.006, hex(0x3a6a2a), [16.5, 27, 1.6], hex(0x7aff5a));
    // a band of light round the door
    tubeRun(k, [-0.08, 0.22, fz + 0.03], [0.08, 0.22, fz + 0.03], letter);
  }
  k.box(0, 0, fz + 0.02, 0.1, 0.2, 0.01, hex(0x6a2a2a));
};

