/**
 * Whether the supply chains show (the user, 8 Nov 2026): every piece of their UI waits for a level 2 HQ (a Shopfront,
 * game/hqGrade.ts). Before that the plant bars over owned buildings, the plant block on a building's card, a vehicle's
 * Set a route, the estate tab's chains strip, Plants filter, Next load sort and plant pips, the town register's Industry
 * list, the plants' notifications and floats, the paper's plant stories and the chain deeds are all kept out of sight.
 * The plants themselves keep running and paying underneath.
 *
 * main.ts sets the gate from the fleet's HQ; anything that runs without the game (the gates in scripts/) sees it shown.
 */
let gate: () => boolean = () => true;

/** The supply chains' UI is on: the fleet has an HQ of grade 2 or more. */
export function chainsShown(): boolean { return gate(); }

/** Set what decides it (main.ts: the fleet's HQ grade). */
export function setChainsGate(f: () => boolean): void { gate = f; }

/** The deeds that are the supply chains' own (game/deeds.ts): out of the book, and not promoted, until the chains show. */
export const CHAIN_DEEDS: ReadonlySet<string> = new Set(['productionLine', 'madeByYou', 'coneZone', 'lapOfHonour', 'vertical']);
