import { hex, scale, type RGB } from '../../world/biomes';
import { DIRS, STEP, idx, inB, waterDepth, type Building } from '../../world/tiles';
import { DARK, TAU, type Draw, type Kit, type P3 } from './kit';
import { eastRoof, frustum, stoneLantern, torii } from './regions/terraces';
import {
  GRAVEL, HOT, KAWARA, KAWARA_DARK, LAMPS, PAPER_GLOW, ROCK, STONE, STONE_DARK, SULPHUR, TIMBER_DARK, TIMBER_OLD, VERMILION,
  signboard, sitter, steam, yukata,
} from './onsenKit';

/**
 * An onsen town's open landmarks (GEN 53, world/onsen.ts):
 *
 *   yubatake   Kusatsu's hot-water field in the middle of the square: seven long wooden troughs running down its
 *              length, the water in them jade and steaming, white sulphur flowers caked along their sides, falling
 *              off the end in a broad cascade into a turquoise pool; a stone kerb and a timber rail round it, the
 *              little source hut at its head, and green light on the water after dark
 *   jigoku     one of Beppu's hells: a boiling pool behind a rail, the Sea Hell's cobalt blue, the Blood Pond's red,
 *              the White Pond's milk or the shaven-monk mud, steam rolling off it, a red demon by the path
 *   ashiyu     a foot bath: a long stone trough of hot water under a little roof, guests along both sides with their
 *              feet in it
 *   ropeway    Hakone's ropeway over Ōwakudani: the valley's yellow sulphur ground and its smoking vents, the lower
 *              station, a lattice tower, the upper station on its crag, and the gondolas running up and down the rope
 *   lakeTorii  Hakone Shrine's Peace Torii standing out in the lake, stone steps down to the water, lanterns either side
 */

const JADE = hex(0x58c8a8), JADE_LIGHT = hex(0x8ae0c4), FLOWERS = hex(0xf0ecd8), CASCADE = hex(0xc8f0e4);
const YUBATAKE_NIGHT: [number, number, number] = [17.6, 29.5, 1.8];

// ---- the yubatake ---------------------------------------------------------------------------------

const yubatake: Draw = (k, W, D, b, r) => {
  const fw = W - 0.7, fd = D - 0.6, cz = -0.05;
  // the sunken field: a stone kerb round it, its floor a step below the square
  k.box(0, 0, cz, fw + 0.2, 0.06, fd + 0.2, STONE, STONE);
  k.box(0, 0.002, cz, fw, 0.062, fd, hex(0x8a8070));
  // seven troughs running from the head (back) down to the cascade (front), falling a little as they go: each a
  // timber box on trestles, the jade water in it, white sulphur flowers caked along the tops of its sides
  const n = 7, pitch = fw / n, tw = pitch * 0.8;
  const z0 = cz - fd / 2 + 0.28, z1 = cz + fd / 2 - 0.36, len = z1 - z0, y0 = 0.24, y1 = 0.13, wallW = 0.055;
  const slope = (a: number, b: number, h: number, col: RGB, x0: number, x1: number, I: P3) =>
    k.quad([x0, a + h, z0], [x1, a + h, z0], [x1, b + h, z1], [x0, b + h, z1], col, I);
  for (let i = 0; i < n; i++) {
    const x = -fw / 2 + pitch * (i + 0.5);
    // the trestles under it
    for (let t = 0; t <= 3; t++) {
      const z = z0 + (len * t) / 3, y = y0 + ((y1 - y0) * t) / 3;
      k.box(x, 0.06, z, tw, 0.03, 0.03, TIMBER_DARK);
      for (const sx of [-1, 1]) k.box(x + sx * (tw / 2 - 0.03), 0.06, z, 0.03, y - 0.1, 0.03, TIMBER_DARK);
    }
    // the floor and the two sides, each a sloping slab of timber, its outer and inner faces and its crusted top
    slope(y0 - 0.07, y1 - 0.07, 0, TIMBER_DARK, x - tw / 2, x + tw / 2, [x, -1, (z0 + z1) / 2]);
    for (const sx of [-1, 1]) {
      const o = x + sx * (tw / 2), m = x + sx * (tw / 2 - wallW);
      k.quad([o, y0 - 0.07, z0], [o, y1 - 0.07, z1], [o, y1 + 0.03, z1], [o, y0 + 0.03, z0], TIMBER_OLD, [o - sx, y0, (z0 + z1) / 2]);
      k.quad([o, y0 - 0.07, z0], [o, y0 + 0.03, z0], [o, y1 + 0.03, z1], [o, y1 - 0.07, z1], scale(TIMBER_OLD, 0.75), [o + sx, y0, (z0 + z1) / 2]);
      k.quad([m, y0 - 0.02, z0], [m, y0 + 0.03, z0], [m, y1 + 0.03, z1], [m, y1 - 0.02, z1], FLOWERS, [m + sx, y0, (z0 + z1) / 2]);
      slope(y0 + 0.03, y1 + 0.03, 0, FLOWERS, Math.min(o, m), Math.max(o, m), [x, y0 - 1, (z0 + z1) / 2]);
    }
    // the head of the trough, and the water in it: jade, a paler stripe where it runs fastest
    k.box(x, y0 - 0.07, z0 - 0.02, tw, 0.1, 0.04, TIMBER_OLD);
    slope(y0, y1, 0, i % 2 ? JADE : scale(JADE, 0.92), x - tw / 2 + wallW, x + tw / 2 - wallW, [x, -1, (z0 + z1) / 2]);
    slope(y0, y1, 0.002, JADE_LIGHT, x - 0.025, x + 0.025, [x, -1, (z0 + z1) / 2]);
    // and the green light on it after dark
    k.glowBox(x, y1 - 0.005, (z0 + z1) / 2, tw * 0.45, 0.004, len * 0.9, JADE, YUBATAKE_NIGHT, hex(0x6affc8));
  }
  // the cascade off the end of the troughs into the pool, and the pool
  const pz = cz + fd / 2 - 0.18;
  k.quad([-fw / 2 + 0.05, 0.13, pz - 0.18], [fw / 2 - 0.05, 0.13, pz - 0.18], [fw / 2 - 0.05, 0.03, pz - 0.08], [-fw / 2 + 0.05, 0.03, pz - 0.08], CASCADE, [0, 0.04, pz - 1]);
  for (let i = 0; i < 6; i++) k.box(-fw / 2 + 0.2 + i * ((fw - 0.4) / 5), 0.04, pz - 0.1, 0.04, 0.06, 0.03, hex(0xe8f8f2));
  k.box(0, 0.002, pz, fw, 0.06, 0.2, hex(0x4fc0c0));
  k.glowBox(0, 0.06, pz, fw - 0.1, 0.004, 0.16, hex(0x4fc0c0), YUBATAKE_NIGHT, hex(0x7ae8ff));
  // the source hut at the head: a little timber house on posts, its roof steaming
  const hz = cz - fd / 2 + 0.1;
  for (const sx of [-1, 1]) k.box(sx * 0.35, 0.06, hz, 0.04, 0.26, 0.04, TIMBER_DARK);
  k.box(0, 0.22, hz, 0.8, 0.12, 0.24, TIMBER_OLD);
  eastRoof(k, 0, 0.34, hz, 1.0, 0.42, 0.16, KAWARA_DARK, 0.04);
  // the rail round it, a gap at the front for the steps
  const rail = TIMBER_DARK, ry = 0.06, rh = 0.12;
  for (const [x0, z0, x1, z1] of [[-fw / 2 - 0.1, cz - fd / 2 - 0.1, fw / 2 + 0.1, cz - fd / 2 - 0.1], [-fw / 2 - 0.1, cz - fd / 2 - 0.1, -fw / 2 - 0.1, cz + fd / 2 + 0.1], [fw / 2 + 0.1, cz - fd / 2 - 0.1, fw / 2 + 0.1, cz + fd / 2 + 0.1], [-fw / 2 - 0.1, cz + fd / 2 + 0.1, -0.3, cz + fd / 2 + 0.1], [0.3, cz + fd / 2 + 0.1, fw / 2 + 0.1, cz + fd / 2 + 0.1]] as const) {
    k.bar([x0, ry + rh, z0], [x1, ry + rh, z1], 0.012, rail);
    const len = Math.hypot(x1 - x0, z1 - z0), m = Math.max(1, Math.round(len / 0.3));
    for (let j = 0; j <= m; j++) k.box(x0 + ((x1 - x0) * j) / m, ry, z0 + ((z1 - z0) * j) / m, 0.02, rh, 0.02, rail);
  }
  // the steam: three plumes along it, and the people at the rail, and a lantern at each front corner
  for (let i = 0; i < 4; i++) steam(k, -fw * 0.36 + (fw * 0.24) * i, 0.22, cz - 0.25 + (i % 2) * 0.45, 1.4, 3, 1.0, b.seed + i * 11);
  steam(k, 0, 0.05, pz, 1.2, 2, 0.8, b.seed + 77);
  for (let i = 0; i < 6; i++) {
    const side = i % 3;
    const [x, z] = side === 0 ? [-fw / 2 - 0.22, cz + (r() - 0.5) * fd] : side === 1 ? [fw / 2 + 0.22, cz + (r() - 0.5) * fd] : [(r() - 0.5) * fw, cz + fd / 2 + 0.24];
    yukata(k, r, x, 0, z);
  }
  for (const sx of [-1, 1]) stoneLantern(k, sx * (W / 2 - 0.15), 0, D / 2 - 0.15, 1.4);
  signboard(k, -fw / 2 + 0.35, 0.18, cz + fd / 2 + 0.14, '湯畑', 0.08);
};

// ---- a hell -------------------------------------------------------------------------------------

/** The hells' waters: the Sea Hell, the Blood Pond, the White Pond, the mud. */
const HELLS: { water: RGB; edge: RGB; rim: RGB; name: string }[] = [
  { water: hex(0x2a8ad8), edge: hex(0x5ab0e8), rim: hex(0xa8a296), name: '海地獄' },
  { water: hex(0xb8402a), edge: hex(0xd8603a), rim: hex(0xb87a5a), name: '血の池' },
  { water: hex(0xd8e8e4), edge: hex(0xb8d4d0), rim: hex(0xb0aaa0), name: '白池' },
  { water: hex(0x7a7468), edge: hex(0x9a9488), rim: hex(0x8a8274), name: '坊主' },
];

const jigoku: Draw = (k, W, D, b, r) => {
  const hell = HELLS[b.seed % HELLS.length];
  // the ground round it: bare, yellowed rock and gravel
  k.box(0, 0, 0, W - 0.1, 0.02, D - 0.1, hex(0xb8ac8c));
  // the pool: overlapping round basins, each a rim, its edge colour and the water
  const lobes: [number, number, number][] = [[-0.25, -0.15, 0.85], [0.35, -0.3, 0.6], [0.1, 0.35, 0.55]];
  for (const [x, z, rr] of lobes) k.disc(x, 0.022, z, rr + 0.1, hell.rim, 14, (rr + 0.1) * 0.85);
  for (const [x, z, rr] of lobes) k.disc(x, 0.03, z, rr, hell.edge, 14, rr * 0.85);
  for (const [x, z, rr] of lobes) k.disc(x, 0.036, z, rr * 0.82, hell.water, 14, rr * 0.7);
  // a mud hell's grey bubbles, the others' sulphur crust on the rocks
  // (only where no other lobe's water is: the pool's own edge)
  const wet = (px: number, pz: number) => lobes.some(([x, z, rr]) => Math.hypot(px - x, (pz - z) / 0.85) < rr * 0.95);
  for (let i = 0, n = 0; i < 40 && n < 10; i++) {
    const [x, z, rr] = lobes[i % 3], a = r() * TAU, d = rr * (1.0 + r() * 0.2), px = x + Math.cos(a) * d, pz = z + Math.sin(a) * d * 0.85;
    if (wet(px, pz)) continue;
    n++;
    k.box(px, 0.02, pz, 0.12, 0.05 + r() * 0.06, 0.1, n % 3 ? ROCK : SULPHUR);
  }
  if (b.seed % HELLS.length === 3) for (let i = 0; i < 6; i++) k.dome(-0.25 + (r() - 0.5) * 0.9, 0.035, -0.15 + (r() - 0.5) * 0.7, 0.04 + r() * 0.03, scale(hell.water, 1.15), 6, 2);
  // the steam: a great deal of it
  steam(k, -0.25, 0.04, -0.15, 1.6, 3, 1.1, b.seed);
  steam(k, 0.35, 0.04, -0.3, 1.2, 2, 0.9, b.seed + 5);
  // the path and its rail along the front, a demon by it, the shrine and torii at the back, a palm and a fence
  k.box(0, 0.02, D / 2 - 0.22, W - 0.3, 0.02, 0.26, GRAVEL);
  for (let i = 0; i <= 8; i++) k.box(-W / 2 + 0.2 + i * ((W - 0.4) / 8), 0.02, D / 2 - 0.38, 0.02, 0.12, 0.02, TIMBER_DARK);
  k.bar([-W / 2 + 0.2, 0.14, D / 2 - 0.38], [W / 2 - 0.2, 0.14, D / 2 - 0.38], 0.01, TIMBER_DARK);
  const ox = W / 2 - 0.35, oz = D / 2 - 0.55, oni = hex(0xc83a2a);
  k.box(ox, 0.02, oz, 0.12, 0.05, 0.1, STONE_DARK);
  k.box(ox, 0.07, oz, 0.09, 0.14, 0.07, oni);
  k.box(ox, 0.21, oz, 0.07, 0.07, 0.06, oni);
  for (const sx of [-1, 1]) k.cone(ox + sx * 0.022, 0.28, oz, 0.012, 0.04, hex(0xf2e8c8), 5);
  k.bar([ox + 0.05, 0.16, oz], [ox + 0.1, 0.26, oz], 0.012, oni);
  k.box(ox + 0.1, 0.07, oz, 0.012, 0.22, 0.012, hex(0xc9a040));
  k.turned(Math.PI, () => torii(k, -W / 2 + 0.45, D / 2 - 0.35, 0.22, 0.28));
  k.box(-W / 2 + 0.45, 0.02, -D / 2 + 0.25, 0.22, 0.16, 0.18, TIMBER_OLD);
  eastRoof(k, -W / 2 + 0.45, 0.18, -D / 2 + 0.25, 0.32, 0.28, 0.1, KAWARA, 0.03);
  signboard(k, -W / 2 + 0.55, 0.06, D / 2 - 0.08, hell.name, 0.065);
  for (let i = 0; i < 3; i++) yukata(k, r, -0.6 + i * 0.45 + r() * 0.1, 0.04, D / 2 - 0.22);
};

// ---- a foot bath --------------------------------------------------------------------------------

const ashiyu: Draw = (k, W, D, b, r) => {
  const tw = W - 0.4, td = 0.22;
  // the trough: a stone kerb, the hot water in it, a bench of boards along each side
  k.box(0, 0, 0, tw + 0.1, 0.07, td + 0.1, STONE);
  k.box(0, 0.002, 0, tw, 0.072, td, HOT);
  for (const sz of [-1, 1]) {
    k.box(0, 0.1, sz * (td / 2 + 0.11), tw, 0.025, 0.11, TIMBER_OLD);
    for (const sx of [-1, 0, 1]) k.box(sx * tw * 0.42, 0, sz * (td / 2 + 0.11), 0.03, 0.1, 0.06, TIMBER_DARK);
  }
  // the roof on four posts over it
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (tw / 2 + 0.02), 0, sz * (td / 2 + 0.2), 0.035, 0.44, 0.035, TIMBER_DARK);
  eastRoof(k, 0, 0.44, 0, tw + 0.16, td + 0.5, 0.12, KAWARA, 0.04);
  // guests sitting along it, feet in the water
  for (let i = 0; i < 5; i++) {
    if (r() < 0.25) continue;
    const sz = i % 2 ? 1 : -1;
    sitter(k, r, -tw / 2 + 0.12 + i * ((tw - 0.24) / 4), 0.125, sz * (td / 2 + 0.11), -sz as 1 | -1);
  }
  steam(k, 0, 0.08, 0, 0.7, 2, 0.45, b.seed);
  signboard(k, tw / 2 - 0.1, 0.4, D / 2 - 0.1, '足湯', 0.06);
};

// ---- the ropeway over Ōwakudani ---------------------------------------------------------------------

const ropeway: Draw = (k, W, D, b, r) => {
  // the valley: yellow-grey sulphur ground and rocks, vents smoking across it
  k.box(0, 0, 0, W - 0.1, 0.02, D - 0.1, hex(0xc8bc8c));
  for (let i = 0; i < 14; i++) {
    const x = (r() - 0.5) * (W - 0.6), z = (r() - 0.5) * (D - 0.6), s = 0.08 + r() * 0.14;
    k.box(x, 0.01, z, s * 1.3, s * 0.6, s, i % 3 ? ROCK : SULPHUR);
  }
  for (let i = 0; i < 4; i++) {
    const x = -W / 2 + 1.4 + i * ((W - 2.4) / 3), z = (r() - 0.5) * (D - 1);
    k.disc(x, 0.022, z, 0.16, SULPHUR, 8);
    steam(k, x, 0.03, z, 1.1, 2, 0.9, b.seed + i * 7);
  }
  // the lower station: a glass hall, its roof over the platform, the name
  const lx = -W / 2 + 0.75, ly = 0.02, lw = 1.1, ld = D - 0.8;
  k.box(lx, ly, 0, lw, 0.42, ld, hex(0xd8dcde));
  k.pane(lx + lw / 2 + 0.002, ly + 0.06, 0, ld * 0.8, 0.28, 0, hex(0x8fb0c0), LAMPS, PAPER_GLOW);
  k.pane(lx, ly + 0.06, ld / 2 + 0.002, lw * 0.8, 0.28, 1, hex(0x8fb0c0), LAMPS, PAPER_GLOW);
  k.box(lx, ly + 0.42, 0, lw + 0.12, 0.05, ld + 0.12, hex(0x6a7078));
  signboard(k, lx, ly + 0.47, ld / 2 + 0.06, 'ロープウェイ', 0.07, hex(0x2a5a9a));
  // the upper station on its crag at the far end
  const ux = W / 2 - 0.6, uy = 0.9;
  // (a battered crag of yellowed rock, boulders round its foot and pines along its top)
  frustum(k, ux, 0, 0, 1.1, D - 0.4, 0.78, D - 1.0, uy, hex(0x8a7e66), hex(0x7a8a52));
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * TAU, s2 = 0.1 + r() * 0.1;
    k.box(ux + Math.cos(a) * 0.62, 0.01, Math.sin(a) * (D / 2 - 0.25), s2 * 1.3, s2, s2, i % 2 ? ROCK : hex(0x9a8e72));
  }
  for (const z of [-(D / 2 - 0.65), D / 2 - 0.65]) {
    k.cyl(ux + 0.25, uy, z, 0.02, 0.08, hex(0x6a5038), 5);
    k.cone(ux + 0.25, uy + 0.06, z, 0.11, 0.32, hex(0x2f5a3a), 7);
  }
  k.box(ux - 0.05, uy, 0, 0.6, 0.3, D - 1.6, hex(0xd8dcde));
  k.pane(ux - 0.351, uy + 0.06, 0, D - 1.9, 0.18, 2, hex(0x8fb0c0), LAMPS, PAPER_GLOW);
  k.box(ux - 0.05, uy + 0.3, 0, 0.7, 0.05, D - 1.5, hex(0x6a7078));
  // the tower in the middle, a lattice of steel
  const tx = (lx + ux) / 2 + 0.1, th = 1.75, steel = hex(0x8a9098);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([tx + sx * 0.16, 0.02, sz * 0.16], [tx + sx * 0.06, th, sz * 0.08], 0.022, steel);
  for (let j = 1; j < 5; j++) {
    const y = (th * j) / 5, s = 0.16 - (0.1 * j) / 5;
    k.box(tx, y, 0, s * 2, 0.02, s * 2, steel);
  }
  k.box(tx, th, 0, 0.12, 0.05, 0.6, steel);
  // the rope, both ways: the lower station up over the tower to the crag
  const ropes: number[] = [-0.22, 0.22];
  const ya = ly + 0.36, yb = th + 0.02, yc = uy + 0.24;
  const ax = lx + lw / 2, cx = ux - 0.36;
  const at = (t: number): [number, number] => {
    // two straight runs with a little sag in each
    if (t < 0.5) { const u = t / 0.5; return [ax + (tx - ax) * u, ya + (yb - ya) * u - Math.sin(Math.PI * u) * 0.12]; }
    const u = (t - 0.5) / 0.5;
    return [tx + (cx - tx) * u, yb + (yc - yb) * u - Math.sin(Math.PI * u) * 0.1];
  };
  for (const z of ropes) {
    const pts: P3[] = [];
    for (let i = 0; i <= 12; i++) { const [x, y] = at(i / 12); pts.push([x, y, z]); }
    for (let i = 0; i < 12; i++) k.bar(pts[i], pts[i + 1], 0.008, DARK);
  }
  // the gondolas: four of them, two each way, gliding up and down the rope
  const CABINS = [0xd8402e, 0x2a6ab8, 0xf2f0ea, 0xe8b830];
  const parts = CABINS.map((c) => (sk: Kit) => {
    sk.box(0, -0.03, 0, 0.012, 0.05, 0.012, DARK);
    sk.box(0, -0.2, 0, 0.18, 0.17, 0.14, hex(c));
    sk.box(0, -0.15, 0, 0.185, 0.07, 0.145, hex(0x9ac4d8));
    sk.box(0, -0.03, 0, 0.06, 0.02, 0.03, DARK);
  });
  let t = (b.seed % 50) * 0.3;
  k.rig(0, 0, 0, parts, (ps, dt) => {
    t += dt * 0.035;
    ps.forEach((o, i) => {
      const up = i < 2, ph = (t + (i % 2) * 0.5) % 1, s = up ? ph : 1 - ph;
      const [x, y] = at(s);
      o.position.set(x, y, up ? ropes[0] : ropes[1]);
    });
  });
  // the black eggs' stall by the lower station, a queue in yukata and anoraks
  k.box(lx + 0.9, 0.02, D / 2 - 0.35, 0.36, 0.2, 0.22, TIMBER_OLD);
  k.box(lx + 0.9, 0.22, D / 2 - 0.35, 0.44, 0.03, 0.3, hex(0x2a2a2e));
  for (let i = 0; i < 4; i++) yukata(k, r, lx + 0.3 + i * 0.13, 0.02, D / 2 - 0.2);
};

// ---- the torii in the lake --------------------------------------------------------------------------

/** Which side of the lot the water lies on (a face: 1 front +z, 0 +x, 3 back, 2 -x) and its surface in the lot's frame. */
function waterSide(k: Kit, b: Building, W: number, D: number): { face: number; y: number; reach: number } {
  const w = k.world, yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]), c = Math.cos(yaw), s = Math.sin(yaw);
  const ox = b.x + b.w / 2, oz = b.z + b.d / 2;
  let best = 1, most = 0, level = 0, reach = 1;
  if (w?.water) {
    for (const f of [1, 0, 2, 3]) {
      const [nx, nz] = f === 1 ? [0, 1] : f === 0 ? [1, 0] : f === 2 ? [-1, 0] : [0, -1];
      const along = nx ? D : W, out = nx ? W / 2 : D / 2;
      let n = 0, lv = 0, far = 0;
      for (let u = -along / 2 + 0.5; u < along / 2; u += 1) {
        for (const o of [0.5, 1.5, 2.5]) {
          const lx = nx * (out + o) + nz * u, lz = nz * (out + o) - nx * u;
          const tx = Math.floor(ox + lx * c + lz * s), tz = Math.floor(oz - lx * s + lz * c);
          if (!inB(tx, tz)) continue;
          const i = idx(tx, tz);
          if (waterDepth(w, i) > 0) { n++; lv = w.water[i]; far = Math.max(far, o); }
        }
      }
      if (n > most) { most = n; best = f; level = lv; reach = far; }
    }
  }
  return { face: best, y: most ? Math.min(-0.1, (level - b.level) * STEP) : -0.12, reach };
}

const lakeTorii: Draw = (k, W, D, b, r) => {
  const ws = waterSide(k, b, W, D);
  const yaw = ws.face === 1 ? 0 : ws.face === 0 ? Math.PI / 2 : ws.face === 2 ? -Math.PI / 2 : Math.PI;
  const out = ws.face === 1 || ws.face === 3 ? D / 2 : W / 2, along = ws.face === 1 || ws.face === 3 ? W : D;
  k.turned(yaw, () => {
    // the stone landing and its steps down to the water
    k.box(0, 0, out - 0.3, along - 0.2, 0.04, 0.5, STONE, scale(STONE, 1.05));
    for (let i = 0; i < 4; i++) k.box(0, ws.y + (0.04 - ws.y) * (1 - i / 4) - 0.04, out + 0.02 + i * 0.06, 0.6, 0.04, 0.06, STONE_DARK);
    for (const sx of [-1, 1]) stoneLantern(k, sx * 0.55, 0.04, out - 0.3, 1.5);
    // the Peace Torii, out in the water a tile off the shore, its feet in the lake
    const tz = out + Math.min(1.1, Math.max(0.6, ws.reach - 0.6));
    toriiAt(k, 0, ws.y - 0.03, tz, 0.7, 1.0);
    // its reflection: a darker red smudge on the water under it
    k.box(0, ws.y + 0.004, tz, 0.9, 0.004, 0.08, scale(VERMILION, 0.55));
    // pilgrims at the rail
    for (let i = 0; i < 3; i++) yukata(k, r, -0.4 + i * 0.4, 0.04, out - 0.45);
  });
};

/** A vermilion torii standing on y (torii() in terraces.ts stands on the ground): two posts, the tie beam, the lintel. */
function toriiAt(k: Kit, x: number, y: number, z: number, w: number, h: number): void {
  const r = h * 0.055;
  for (const sx of [-1, 1]) {
    k.cyl(x + sx * w / 2, y, z, r, h, VERMILION, 6);
    k.cyl(x + sx * w / 2, y, z, r * 1.25, 0.05, DARK, 6);
  }
  k.box(x, y + h * 0.72, z, w + r * 5, h * 0.06, r * 1.6, VERMILION);
  k.box(x, y + h * 0.72 + h * 0.06, z, r * 1.6, h * 0.16, r * 1.4, VERMILION);
  k.box(x, y + h, z, w + r * 7, h * 0.07, r * 2.4, VERMILION, DARK);
  k.box(x, y + h + h * 0.07, z, w + r * 8, h * 0.035, r * 2.6, DARK);
  for (const sx of [-1, 1]) k.bar([x + sx * (w / 2 + r * 3), y + h + h * 0.08, z], [x + sx * (w / 2 + r * 5), y + h + h * 0.16, z], h * 0.025, DARK);
}

export const ONSEN_OPEN: Record<'yubatake' | 'jigoku' | 'ashiyu' | 'ropeway' | 'lakeTorii', Draw> = {
  yubatake, jigoku, ashiyu, ropeway, lakeTorii,
};
