/**
 * What a game has done, as the play reports carry it (net/report.ts) for the dev page's Analytics tab
 * (server/analyticsPage.ts), kept in the save so it adds up over a game's whole life (the user, 2 Nov 2026):
 *
 *   m    each mission template: offered, accepted, declined, let go (an offer left to lapse or dropped), done,
 *        failed, given up part way
 *   d    each model the player drove: seconds at the wheel, separate drives, and the play second first driven
 *   f    each model the fleet's drivers ran: seconds out on the road
 *   own  every vehicle that joined the fleet: its model, the play second it came, and the one it went (if it has)
 *   idle seconds at the wheel standing still, with a window or menu up, and with the page out of sight
 *   at   milestones, by the play second first reached: hq1–hq7, v2/v4/v10 (vehicles), d1/d3 (hired drivers),
 *        w10k/w100k/w1m (net worth)
 *
 * The missions are read off the mission list once a second (a declined one is told, as it leaves the list at
 * once); the fleet the same way.
 */

export const MISSION_COUNTS = ['offered', 'accepted', 'declined', 'lapsed', 'done', 'failed', 'abandoned'] as const;
type Count = (typeof MISSION_COUNTS)[number];

export interface StatsSave {
  m: Record<string, number[]>;
  d: Record<string, [number, number, number]>;
  f: Record<string, number>;
  own: { m: string; b: number; s?: number; u: number }[];
  idle: [number, number, number];
  at: Record<string, number>;
}

/** What the stats read each second: the mission list, the fleet, and the player. */
export interface StatsLook {
  played: number;
  missions: { id: number; tpl: string; state: string }[];
  units: { uid: number; model: string; onRoad: boolean }[];
  hq: number;
  drivers: number;
  worth: number;
}

const OWN_MAX = 200;
const MILESTONES: [string, (l: StatsLook) => boolean][] = [
  ...[1, 2, 3, 4, 5, 6, 7].map((g) => [`hq${g}`, (l: StatsLook) => l.hq >= g] as [string, (l: StatsLook) => boolean]),
  ['v2', (l) => l.units.length >= 2], ['v4', (l) => l.units.length >= 4], ['v10', (l) => l.units.length >= 10],
  ['d1', (l) => l.drivers >= 1], ['d3', (l) => l.drivers >= 3],
  ['w10k', (l) => l.worth >= 1e4], ['w100k', (l) => l.worth >= 1e5], ['w1m', (l) => l.worth >= 1e6],
];

const empty = (): StatsSave => ({ m: {}, d: {}, f: {}, own: [], idle: [0, 0, 0], at: {} });

export class PlayStats {
  private s: StatsSave = empty();
  /** The missions and units as last read: id → state, and uid → its row in `own`. */
  private seen = new Map<number, { tpl: string; state: string }>();
  private units = new Map<number, number>();
  private primed = false;
  private secT = 0;
  /** The model driven last frame, to count a new drive when it changes or after a break. */
  private lastModel = '';
  private offFor = 0;
  /** When the page went out of sight (performance.now ms), or null. */
  private hiddenAt: number | null = null;
  private live = false;

  constructor() {
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) { if (this.live) this.hiddenAt = performance.now(); return; }
      // away time, at most half a day a time (a laptop left closed)
      if (this.hiddenAt !== null && this.live) this.s.idle[2] += Math.min(43200, (performance.now() - this.hiddenAt) / 1000);
      this.hiddenAt = null;
    });
  }

  /** A new game (nothing), or a loaded one's stats; what is listed now is taken as already counted. */
  load(s: StatsSave | undefined): void {
    this.s = s && typeof s === 'object' ? { ...empty(), ...s, idle: [...(s.idle ?? [0, 0, 0])] as [number, number, number] } : empty();
    this.seen.clear();
    this.units.clear();
    this.primed = false;
    this.lastModel = '';
    this.live = true;
  }

  stop(): void { this.live = false; }

  toSave(): StatsSave {
    const r = (n: number) => Math.round(n);
    return {
      m: this.s.m,
      d: Object.fromEntries(Object.entries(this.s.d).map(([k, v]) => [k, [r(v[0]), v[1], r(v[2])]])) as StatsSave['d'],
      f: Object.fromEntries(Object.entries(this.s.f).map(([k, v]) => [k, r(v)])),
      own: this.s.own,
      idle: this.s.idle.map(r) as [number, number, number],
      at: this.s.at,
    };
  }

  /** A mission offer turned down (Missions.onReject): it leaves the list at once, so it is told. */
  declined(id: number, tpl: string): void {
    this.bump(tpl, 'declined');
    this.seen.delete(id);
  }

  /**
   * Every frame of play. `driving`: the model at the wheel and its speed, or null (watching another vehicle,
   * on foot); `menu`: a window or menu is up.
   */
  tick(dt: number, look: () => StatsLook, driving: { model: string; v: number } | null, menu: boolean): void {
    if (!this.live) return;
    if (menu) this.s.idle[1] += dt;
    if (driving && !menu) {
      const d = (this.s.d[driving.model] ??= [0, 0, -1]);
      if (driving.model !== this.lastModel || this.offFor > 60) { d[1]++; if (d[2] < 0) d[2] = -2; }
      d[0] += dt;
      this.lastModel = driving.model;
      this.offFor = 0;
      if (Math.abs(driving.v) < 0.2) this.s.idle[0] += dt;
    } else this.offFor += dt;
    this.secT -= dt;
    if (this.secT > 0) return;
    const secs = 1 - this.secT;
    this.secT = 1;
    const l = look();
    // the first drive of a model: stamped with the play second
    for (const v of Object.values(this.s.d)) if (v[2] === -2) v[2] = l.played;
    this.missions(l);
    this.fleet(l, secs);
    for (const [k, ok] of MILESTONES) if (this.s.at[k] === undefined && ok(l)) this.s.at[k] = Math.round(l.played);
  }

  private bump(tpl: string, what: Count): void {
    const row = (this.s.m[tpl] ??= MISSION_COUNTS.map(() => 0));
    row[MISSION_COUNTS.indexOf(what)]++;
  }

  private missions(l: StatsLook): void {
    const now = new Map(l.missions.map((m) => [m.id, m]));
    if (!this.primed) {
      // a loaded game: what is listed was counted in the game that saved it
      for (const m of l.missions) this.seen.set(m.id, { tpl: m.tpl, state: m.state });
      for (const u of l.units) this.units.set(u.uid, -1);
      this.primed = true;
      return;
    }
    for (const m of l.missions) {
      const was = this.seen.get(m.id);
      if (m.state === 'rejected') continue;
      if (!was) {
        this.bump(m.tpl, 'offered');
        if (m.state !== 'offered') this.bump(m.tpl, 'accepted');
        if (m.state === 'done' || m.state === 'failed') this.bump(m.tpl, m.state);
      } else if (was.state !== m.state) {
        if (was.state === 'offered' && m.state !== 'offered') this.bump(m.tpl, 'accepted');
        if (was.state === 'active' && m.state === 'offered') this.bump(m.tpl, 'abandoned');
        if (m.state === 'done' || m.state === 'failed') this.bump(m.tpl, m.state);
      }
      this.seen.set(m.id, { tpl: m.tpl, state: m.state });
    }
    // gone from the list while still an offer, and not declined: left to lapse (or dropped as stale)
    for (const [id, was] of this.seen) {
      if (now.has(id)) continue;
      if (was.state === 'offered') this.bump(was.tpl, 'lapsed');
      this.seen.delete(id);
    }
  }

  private fleet(l: StatsLook, secs: number): void {
    const now = new Set<number>();
    for (const u of l.units) {
      now.add(u.uid);
      if (u.onRoad) this.s.f[u.model] = (this.s.f[u.model] ?? 0) + secs;
      if (this.units.has(u.uid)) continue;
      this.s.own.push({ m: u.model, b: Math.round(l.played), u: u.uid });
      if (this.s.own.length > OWN_MAX) this.s.own.shift();
      this.units.set(u.uid, this.s.own.length - 1);
    }
    for (const uid of [...this.units.keys()]) {
      if (now.has(uid)) continue;
      this.units.delete(uid);
      const row = [...this.s.own].reverse().find((o) => o.u === uid && o.s === undefined);
      if (row) row.s = Math.round(l.played);
    }
  }

  /** As the play report carries it. */
  report(): StatsSave { return this.toSave(); }
}
