import type { Building, World } from '../world/tiles';
import { ESTATE, type Wallet } from './economy';
import type { Estate } from './estate';
import { kerbNear, type Fleet, type Unit } from './fleet';
import { unitWord, type Firm, type FirmUnit, type Firms } from './firms';
import { gradeOf } from './hqGrade';
import { money } from './cargoHud';
import { deeds } from './deeds';

/**
 * Buying out a rival (the user, 26 Oct 2026). Any door a CPU firm holds can be bought off it at four times
 * its market price, the money going into the firm's bank; or the whole firm — its doors, its vehicles and
 * its drivers — at three times what it is worth, the money going to its shareholders (out of the game).
 * A firm bought out is gone for good: its county slot never founds another (Firms.bought).
 *
 * Its depot and its HQ are not sold on their own (the firm runs from them): they come with the whole firm.
 * A railway is not for sale: its trains run on the county's line, which no driver of yours is licensed for.
 *
 * Online, firms are run by whichever game hosts their county and shared through the server; a buyout only
 * takes the firm out of the buyer's own world (it is never deleted from the county's shared state), and
 * its doors are claimed through the server like any other purchase, so no other player loses anything.
 */
export const BUYOUT = {
  /** A single door: this many times its market price. */
  door: 4,
  /** The whole firm: this many times its market cap. */
  firm: 3,
};

interface BuyoutHost {
  fleet: Fleet;
  estate: Estate;
  firms: Firms;
  wallet: Wallet;
  playing(): boolean;
  worldAt(cx: number, cz: number): World | null;
  /** The ground's height at a spot, for a vehicle left standing there. */
  groundAt(w: World, x: number, z: number): number;
  /** Make an owned building the fleet's HQ (game/hq.ts makeHq): why not, or null. */
  makeHq(w: World, b: Building): string | null;
  /** The cash chip, ticked. */
  cash(): void;
  announce(title: string, body: string): void;
}

/** A door of a firm's, as the deed card offers it. */
export interface DoorOffer {
  firm: Firm;
  /** What it costs the player, and its market price. */
  price: number; market: number;
  /** Its depot or HQ: only with the whole firm. */
  whole: boolean;
  why: string | null;
}

/** A whole firm, as its cards offer it: the price, and what the player would get. */
export interface FirmOffer {
  price: number;
  /** Its market cap: net worth, as Standings counts it, never below what its vehicles and doors would fetch. */
  cap: number;
  units: number; doors: number;
  /** Drivers who would join (the rest are paid off: no room for them), and vehicles that would go to the garage. */
  join: number; leave: number; garaged: number;
  /** Its HQ would be the player's (they have none). */
  hq: boolean;
  why: string | null;
}

/** What buying a whole rival brings, for its cards: doors, vehicles, drivers, and what won't fit. */
export function firmOfferLine(f: Firm, o: FirmOffer): string {
  const bits = [`${o.doors} door${o.doors === 1 ? '' : 's'}`, `${o.units} ${unitWord(f, o.units)}${o.garaged ? ` (${o.garaged} to the garage)` : ''}`,
    `${o.join} driver${o.join === 1 ? '' : 's'}${o.leave ? ` (${o.leave} paid off: no slots)` : ''}`];
  if (o.hq) bits.push('their HQ as yours');
  return `The whole fleet: ${bits.join(' · ')} · worth ${money(o.cap)}; the money goes to its shareholders`;
}

const r100 = (v: number): number => Math.round(v / 100) * 100;
/** A unit's earnings an hour, for which of a firm's vehicles go out first. */
const rate = (u: FirmUnit): number => (u.hours >= 0.5 ? u.paid / u.hours : 0);

export class Buyout {
  constructor(private host: BuyoutHost) {}

  say(title: string, body: string): void { this.host.announce(title, body); }

  /** The offer for a building a firm holds; null when no firm does. */
  doorOffer(w: World, b: Building): DoorOffer | null {
    const { estate, firms, wallet } = this.host;
    const key = estate.keyOf(w, b);
    const f = firms.ownerOf(key);
    if (!f) return null;
    const q = estate.quote(w, b);
    const price = r100(q.price * BUYOUT.door);
    const whole = key === f.depot || key === f.hq.key;
    const player = estate.remote?.heldBy(key) ?? null;
    let why: string | null = null;
    if (whole) why = `${key === f.hq.key ? 'Their HQ' : 'Their depot'}: it comes only with the whole fleet`;
    else if (player) why = player;
    else if (q.far > ESTATE.reach) why = `Drive within ${ESTATE.reach} tiles to buy · ${Math.round(q.far)} away`;
    else if (!wallet.canAfford(price)) why = `Not enough cash · it costs ${money(price)}, you have ${money(wallet.cash)}`;
    return { firm: f, price, market: q.price, whole, why };
  }

  /** Buy a firm's door at four times its market price: the money goes into the firm's bank. */
  buyDoor(w: World, b: Building): string | null {
    if (!this.host.playing()) return 'Not now';
    const o = this.doorOffer(w, b);
    if (!o) return 'Nobody holds it to sell';
    if (o.why) return o.why;
    const { estate, firms, wallet } = this.host;
    if (!wallet.spend(o.price, 'property')) return 'Not enough cash';
    this.host.cash();
    firms.sellDoor(o.firm, estate.keyOf(w, b), o.price);
    estate.boughtFrom(w, b, o.price, o.firm.name);
    return null;
  }

  /** The offer for a whole firm. */
  firmOffer(f: Firm): FirmOffer {
    const { fleet, estate, firms, wallet } = this.host;
    const v = firms.worth(f);
    const cap = Math.max(v.worth, v.assets);
    const price = Math.max(1000, r100(cap * BUYOUT.firm));
    const units = f.units.length;
    // the slots after: its HQ becomes the player's only if they have none
    const hqAt = !fleet.hq ? estate.resolve(f.hq.key) : null;
    const hq = !!hqAt && !estate.taken(f.hq.key) && gradeOf(hqAt.b, !!hqAt.port).grade > 0 && (!!hqAt.port || !hqAt.b.derelict);
    const slots = hq ? gradeOf(hqAt!.b, !!hqAt!.port).slots : fleet.slots;
    const join = Math.min(units, Math.max(0, slots - fleet.drivers.length));
    const out = Math.min(units, Math.max(0, slots - fleet.deployed.length));
    let why: string | null = null;
    if (!this.host.playing()) why = 'Not now';
    else if (f.trade === 'rail') why = 'A railway is not for sale: its trains run on the county’s line';
    else if (!this.host.worldAt(f.home[0], f.home[1])) why = `Drive to their county (${f.town}) to buy them`;
    else if ([...f.deeds.keys()].some((k) => !estate.resolve(k))) why = 'Some of their doors are out of reach: drive nearer to buy them';
    else if (!wallet.canAfford(price)) why = `Not enough cash · they cost ${money(price)}, you have ${money(wallet.cash)}`;
    return { price, cap, units, doors: f.deeds.size, join, leave: units - join, garaged: units - out, hq, why };
  }

  /**
   * Buy the whole firm at three times its market cap. The money is gone (back to its shareholders); the
   * player has its doors, its vehicles (parked at its depot, those past the fleet's slots in the garage)
   * and as many of its drivers as the HQ has slots for, in its best earners. Null when done.
   */
  buyFirm(f: Firm): string | null {
    const o = this.firmOffer(f);
    if (o.why) return o.why;
    const { fleet, estate, firms, wallet } = this.host;
    const w = this.host.worldAt(f.home[0], f.home[1])!;
    if (!wallet.spend(o.price, 'property')) return 'Not enough cash';
    this.host.cash();
    const name = f.name, hqKey = f.hq.key, dx = f.dx, dz = f.dz;
    const got = firms.sellOut(f);
    // its doors, at today's market price (what they are booked at and would sell from); one another player holds stays theirs
    let doors = 0;
    for (const key of got.deeds) {
      const r = estate.resolve(key);
      if (r && !estate.taken(key) && !estate.grant(r.w, r.b)) doors++;
    }
    // its HQ, if the player has none
    let hq = '';
    if (!fleet.hq && estate.deeds.has(hqKey)) {
      const r = estate.resolve(hqKey);
      if (r && gradeOf(r.b, !!r.port).grade > 0 && !this.host.makeHq(r.w, r.b)) hq = ` · ${(fleet.hq as { name: string } | null)?.name ?? 'their HQ'} is your HQ`;
    }
    // its vehicles at its depot, the best earners first: as many as there are free slots stay out, the rest to the garage
    const free = Math.max(0, fleet.slots - fleet.deployed.length);
    const taken: { x: number; z: number }[] = [];
    const made: { u: Unit; fu: FirmUnit }[] = [];
    for (const fu of [...got.units].sort((a, b) => rate(b) - rate(a))) {
      const k = kerbNear(w, dx, dz, 10, taken) ?? { x: dx, z: dz };
      taken.push(k);
      const u = fleet.make(fu.model, w.cx, w.cz, k.x, k.z, 0, this.host.groundAt(w, k.x, k.z));
      u.parts = { ...fu.parts, t: { ...fu.parts.t } };
      u.place = fleet.placeName(u);
      deeds.mark('models', fu.model);
      made.push({ u, fu });
    }
    deeds.best('motorPool', fleet.units.length);
    // its drivers, as many as the HQ's slots allow, the most seasoned first; the rest are paid off with the firm
    const room = Math.max(0, fleet.slots - fleet.drivers.length);
    const crew = got.units.map((u) => u.driver).sort((a, b) => b.deliveries - a.deliveries).slice(0, room).map((d) => fleet.enlist(d));
    let garaged = 0;
    made.forEach(({ u }, k) => {
      if (k >= free) { if (!fleet.store(u)) garaged++; return; }
      const d = crew.find((c) => !c.unit);
      if (d) fleet.put(d, u);
    });
    garaged += fleet.settle().length;
    const n = made.length, left = got.units.length - crew.length;
    this.host.announce(`${name} is yours`, `${money(o.price)} to their shareholders · ${doors} door${doors === 1 ? '' : 's'}`
      + ` · ${n} vehicle${n === 1 ? '' : 's'}${garaged ? ` (${garaged} to the garage)` : ''}`
      + ` · ${crew.length} driver${crew.length === 1 ? '' : 's'} joined${left ? ` (${left} paid off: no slots for them)` : ''}${hq}`);
    return null;
  }
}
