/**
 * The Passport (docs/missions.html, Travel): every biome, building style, wonder and town this save has
 * been to, and every ferry crossing it has made. It belongs to the save, not the player: the per-player
 * achievement sets (`deeds.biomes`, `deeds.wonders`) are left as they are.
 *
 * A travel objective asks for a stamp not yet in here, and the journal's Passport tab draws the blanks.
 */
import type { Arch, RegionKind } from '../../world/tiles';
import { NEXT_WORLD } from '../../world/nextWorld';

type StampKind = 'biome' | 'arch' | 'wonder' | 'town' | 'ferry';

export interface SavedPassport { b: string[]; a: string[]; w: string[]; t: string[]; f: string[] }

/** Every style a town can be built in, in the order the Passport draws them. */
export const ARCHES: Arch[] = [
  'classic', 'victorian', 'tudor', 'medieval', 'gothic', 'deco', 'modernist', 'brutalist', 'postmodern',
  'mediterranean', 'colonial', 'timber', 'chalet', 'granite', 'adobe', 'pastel', 'eastern', 'cycladic',
  'dutch', 'japanese', 'budapest', 'western', 'russian', 'ottoman', 'maya', 'roman', 'chinese', 'seasia', 'sanfran', 'tokyo', 'paris', 'newyork', 'capital',
  'mughal', 'moorish', 'andean', 'norse', 'sahel', 'himalayan', 'havana', 'venice', 'hongkong', 'vegas', 'neworleans', 'london', 'dubai', 'motherroad',
  'shire', 'whitecity', 'spirit', 'steampunk', 'solarpunk', 'cyberpunk', 'chicago', 'osaka',
  // (the Adriatic, the onsen and the lake towns only once a world can build one: GEN 53, world/nextWorld.ts)
  ...(NEXT_WORLD ? ['adriatic' as const, 'onsen' as const, 'lakeside' as const, 'leman' as const, 'como' as const] : []),
];
export const ARCH_LABEL: Record<Arch, string> = {
  classic: 'Classic', victorian: 'Victorian', tudor: 'Tudor', medieval: 'Walled', gothic: 'Gothic', deco: 'Art deco',
  modernist: 'Modernist', brutalist: 'Brutalist', postmodern: 'Postmodern', mediterranean: 'Mediterranean', colonial: 'Colonial',
  timber: 'Timber', chalet: 'Alpine', granite: 'Granite', adobe: 'Adobe', pastel: 'Pastel', eastern: 'Eastern', cycladic: 'Cycladic',
  dutch: 'Dutch', japanese: 'Japanese', budapest: 'Budapest', western: 'Frontier', russian: 'Russian', ottoman: 'Ottoman', maya: 'Mesoamerican', roman: 'Classical', chinese: 'Chinese', seasia: 'Southeast Asian', sanfran: 'Painted ladies', tokyo: 'Tokyo', paris: 'Parisian', newyork: 'New York', capital: 'Federal',
  mughal: 'Mughal', moorish: 'Moorish', andean: 'Andean', norse: 'Norse', sahel: 'Sahelian', himalayan: 'Himalayan', havana: 'Havana',
  venice: 'Venetian', hongkong: 'Hong Kong', vegas: 'The Strip', neworleans: 'French Quarter', london: 'London', dubai: 'Gulf',
  motherroad: 'Mother Road', shire: 'Hillside burrows', whitecity: 'White city', spirit: 'Spirit town', steampunk: 'Steampunk',
  solarpunk: 'Solarpunk', cyberpunk: 'Cyberpunk', chicago: 'Chicago', osaka: 'Osaka', adriatic: 'Adriatic',
  onsen: 'Onsen town', lakeside: 'Lake cottages', leman: 'Belle époque lakeside', como: 'Italian lakes',
};
export const BIOMES: RegionKind[] = ['green', 'sands', 'icefield', 'shallows', 'heights', 'moors', 'veldt', 'fens', 'terraces', 'whitewash', 'goldhills',
  'firecoast', 'fjords', 'bigtimber', 'redrock', 'dragonbay', 'steppe', 'saltpan', 'mangrove', 'lavender'];

export class Passport {
  private sets: Record<StampKind, Set<string>> = { biome: new Set(), arch: new Set(), wonder: new Set(), town: new Set(), ferry: new Set() };
  /** A stamp landed: the mission bus and the card are told. */
  onStamp: (kind: StampKind, key: string) => void = () => {};

  has(kind: StampKind, key: string): boolean { return this.sets[kind].has(key); }
  count(kind: StampKind): number { return this.sets[kind].size; }
  total(): number { return this.sets.biome.size + this.sets.arch.size + this.sets.wonder.size + this.sets.ferry.size; }
  list(kind: StampKind): string[] { return [...this.sets[kind]]; }

  /** Stamp it; true when it is new. */
  stamp(kind: StampKind, key: string): boolean {
    if (!key || this.sets[kind].has(key)) return false;
    this.sets[kind].add(key);
    this.onStamp(kind, key);
    return true;
  }

  /** Take a stamp in with no card: one the player's own book already holds (game/sights.ts). */
  adopt(kind: StampKind, key: string): void { if (key) this.sets[kind].add(key); }

  clear(): void { for (const s of Object.values(this.sets)) s.clear(); }

  toSave(): SavedPassport {
    return { b: this.list('biome'), a: this.list('arch'), w: this.list('wonder'), t: this.list('town'), f: this.list('ferry') };
  }

  fromSave(s: SavedPassport | undefined): void {
    this.clear();
    if (!s) return;
    for (const k of s.b ?? []) this.sets.biome.add(k);
    for (const k of s.a ?? []) this.sets.arch.add(k);
    for (const k of s.w ?? []) this.sets.wonder.add(k);
    for (const k of s.t ?? []) this.sets.town.add(k);
    for (const k of s.f ?? []) this.sets.ferry.add(k);
  }
}
