import type { CellDoc, ClientMsg, ServerMsg, Welcome } from '../../shared/protocol';
import type { LeagueBookMsg } from '../../shared/leagues';
import type { OnlineExtra } from './online';
import type { Stadiums } from '../game/stadiums';

/**
 * The stadium leagues online (server/leagues.ts): every game shows the same clubs, tables, results and history. Signed
 * in, the game asks for the world's whole league book and takes it in place of what it had learned by itself; from then
 * on it tells the world a watched game's score, each club as it meets it and the fixtures it is playing live, gathered
 * and sent at most every SEND_S seconds, and hears everyone's.
 */

const SEND_S = 1;

export interface LeagueNetHost { online(): boolean; post(m: ClientMsg): void }

export class LeagueNet implements OnlineExtra {
  private out: Required<Omit<LeagueBookMsg, 'full' | 'live'>> & { live?: string[] } = { done: [], clubs: [] };
  private wait = 0;

  constructor(private host: LeagueNetHost, private stadiums: Stadiums) {}

  welcome(_w: Welcome): void { this.out = { done: [], clubs: [] }; }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t !== 'league') return false;
    this.stadiums.fromWorld(m);
    return true;
  }
  ready(): void {
    if (!this.host.online()) return;
    // from now on the stadiums tell the world what they learn
    this.stadiums.share = (m) => {
      if (m.done) this.out.done.push(...m.done);
      if (m.clubs) this.out.clubs.push(...m.clubs);
      if (m.live) this.out.live = m.live;
    };
    this.host.post({ t: 'league' });
  }
  frame(dt: number): void {
    if (!this.host.online() || (this.wait -= dt) > 0) return;
    this.wait = SEND_S;
    const o = this.out;
    if (!o.done.length && !o.clubs.length && !o.live) return;
    this.host.post({ t: 'league', ...(o.done.length ? { done: o.done } : {}), ...(o.clubs.length ? { clubs: o.clubs } : {}), ...(o.live ? { live: o.live } : {}) });
    this.out = { done: [], clubs: [] };
  }
  forget(): void { /* nothing per cell */ }
  reset(): void { this.stadiums.leaveWorld(); this.out = { done: [], clubs: [] }; }
}
