import { N, idx, inB, waterDepth, type World } from '../world/tiles';
import { halfSize, type CargoClass, type VehicleDef } from './vehicles';
import type { Fleet, Unit } from './fleet';
import { routesSpent, runOf, type Traffic } from './traffic';

/**
 * Follow mode: the fleet drives with you.
 *
 * Every crewed vehicle is in one of two minds, set from the two buttons in the F window — the pair at
 * the top for the whole fleet, the pair on a driver's row for that one vehicle: Work, which
 * is everything the fleet has always done — take loads, run manifests, earn — and Follow, which drops
 * all of that and puts the vehicle in a line behind your own.
 *
 * How they hold station. The player's last hundred tiles are kept as a trail of crumbs, and on a road
 * each follower holds a point on that trail a set distance back: the car behind drives where you drove,
 * which is what keeps a line on the tarmac round bends and over bridges without routing anything. Off
 * the road there is no line worth keeping, so they spread into a V behind you instead, a row either
 * side, which is what a handful of vehicles crossing open country actually do.
 *
 * Catching up is the one case that routes: a follower more than CATCH_UP tiles off its station (it was
 * left across town, or a building stands between it and the trail) is sent there on the real roads by
 * traffic.ts, exactly as a working driver is sent to a load, and takes its station again when it is
 * near enough. One in another cell altogether is the convoy's business (game/convoy.ts): a follower
 * musters in the cell you are in, however wide its orders let it roam.
 *
 * The hold. A follower that has taken its station is close enough to hand things across, so its hold
 * counts as yours: the units and the classes of everything in formation are added to the vehicle you
 * drive, and a load too big for your own car rides with the formation. Nothing is ever thrown out if
 * the formation breaks up — you simply cannot pick anything else up until what is aboard fits again.
 */

/** Which mind a crewed vehicle is in. */
export type FleetMode = 'work' | 'follow';

/**
 * Tiles between one vehicle's tail and the next one's nose, in line and in the V, standing still; and
 * how much more room each gap takes per tile a second of the player's speed, so the line is tight in
 * town and at a stop but a follower still has room to pull up when you brake at speed.
 */
const SPACING = 0.45, SPEED_GAP = 0.35;
/**
 * The V off-road: how far back each row sits, and how far out to the side, at the least. A row is
 * pushed back further when the longest vehicle in the formation needs it, and out further when the
 * widest does, so a lorry in the V never sits on the car ahead of it.
 */
const ROW = 1.3, COL = 1;
/**
 * How far out a wing may sit round a bend, as a share of the bend's radius: the outside of a turn is
 * longer, and a follower has only so much pace in hand (traffic.ts ESCORT_TOP) to cover it.
 */
const WING_BEND = 0.3;
/** Tiles nearer another place must be before a follower gives up its own for it. */
const STICK = 1.5;
/** How quickly the shape swings round to the player's heading, per second (a share of what is left). */
const AIM_RATE = 2.2;
/**
 * A follower this far from its station is routed back to it on the roads rather than steered at it; a
 * flyer never needs routing round anything, so it only is when it is very far off.
 */
const CATCH_UP = 14, CATCH_UP_AIR = 40;
/** Tiles behind its station before a follower no longer counts toward the shape (and the shape closes up without it). */
const DROP = 12;
/** Tiles behind its place before a follower gives up on its place and chases along the wake instead. */
const WAKE_CHASE = 8;
/** Seconds a follower may sit stuck chasing the wake before it is routed instead, and for how long. */
const WAKE_STALL = 2, NO_WAKE = 10;
/** Seconds it must stay that far back before it counts as out. */
const DROP_HOLD = 3;
/** And it stops routing and takes the station itself again once it is this close to it. */
const FORMED = 5;
/** Tiles off its station a follower may be and still count as in formation, hold and all. */
const LEND = 6;
/** Tiles the player must move before another crumb is dropped, and how long a trail is kept. */
const CRUMB = 0.5, TRAIL_TILES = 120;
/** A jump bigger than this is a teleport, not driving: the trail starts again. */
const JUMP = 10;
/** Seconds the player must be off the road (or on it) before the shape changes. */
const SHAPE_HOLD = 1.5;
/** Seconds a follower may stand still while routing before it is sent again, and tries before it gives up. */
const STALL = 3, MAX_SENDS = 4;
/** How far the line must move on from where a catching-up vehicle was sent before it is sent again. */
const RESEND = 8;
/** Seconds a follower that can find no way to you waits before looking for one again. */
const LOST_AGAIN = 12;

/** One point of the player's wake, in world tiles. */
interface Crumb { x: number; z: number; d: number }

/** What the formation knows about one follower between frames. */
interface Station {
  /** Routing back to its station rather than holding it. */
  routing: boolean;
  /** Seconds it has stood still while routing, how many times it has been sent, and when to send it again. */
  still: number; sends: number; wait: number;
  /** No road from where it stands to your line: it waits where it is and tries again now and then. */
  lost: boolean; retry: number;
  /** It has its station: its hold is yours. */
  formed: boolean;
  /** How far it is from its station, for the window's line. */
  gap: number;
  /** Close enough to count toward the shape the formation takes (see `shapeOf`). */
  inShape: boolean;
  /** Seconds it has been too far back to count, before it is let go from the shape. */
  outFor?: number;
  /** Seconds it has sat still chasing the wake, and how long it is to be routed instead after that. */
  wakeStill?: number; noWake?: number;
}

interface FormationHost {
  /** The player: the cell they are in, where they are in it, and what they drive. Null with nobody out. */
  player(): { w: World; x: number; z: number; heading: number; v: number; def: VehicleDef } | null;
  trafficOf(w: World): Traffic | null;
}

export class Formation {
  /** The player's wake in world tiles, newest last. */
  private trail: Crumb[] = [];
  private states = new Map<number, Station>();
  /** Whether the formation is in line (on a road) or in the V, and how long the ground has disagreed. */
  private line = true;
  private shape = 0;

  /**
   * A tow's stations (game/tow/tow.ts): while one is set, a follower it names a station for takes that
   * one instead of its place in the line, and keeps the pace given with it.
   */
  harness: ((u: Unit) => { x: number; z: number; v: number; tow?: { heading: number; pedal: number; taut: boolean } } | null) | null = null;

  constructor(private fleet: Fleet, private host: FormationHost) {}

  /**
   * Every crewed vehicle told to follow that can follow what the player drives now: cars behind a car,
   * boats behind a boat, and flyers behind anything (over a car, over a boat, or in the air). The rest wait (in the player's cell: the convoy brings
   * them) until the player is in something of their kind again.
   */
  followers(): Unit[] {
    const lead = this.host.player()?.def ?? null;
    return this.fleet.units
      // one running a rush's loop on its own (game/rushes/crew.ts) is out of the line until the bell
      .filter((u) => u.mode === 'follow' && u.driver && u.where !== 'ridden' && !u.away && !u.rushing && canFollow(this.fleet.defFor(u), lead))
      .sort((a, b) => a.uid - b.uid);
  }

  /** Why this vehicle can't follow the player in what they drive now, or null. */
  whyNot(u: Unit): string | null { return whyNotFollow(this.fleet, u, this.host.player()?.def ?? null); }

  /**
   * Set one vehicle's mind, or the whole fleet's with no unit. Falling in behind the player gives up
   * the manifest at no cost to anybody, exactly as being called away after them does: goods it was on
   * its way for go back on the market, and what is already aboard rides with it, decaying in the hold,
   * until it is put back to work and delivers it.
   */
  setMode(mode: FleetMode, u?: Unit): void {
    const list = (u ? [u] : this.fleet.units.filter((q) => q.driver && q.where !== 'ridden')).filter((q) => !q.away);
    for (const q of list) {
      // only its own kind can be followed: a boat behind a boat, a car behind a car; a train never
      if (q.mode === mode || (mode === 'follow' && this.whyNot(q))) continue;
      q.mode = mode;
      this.states.delete(q.uid);
      const a = q.agent, tr = q.traffic;
      if (mode === 'follow') {
        if (a && tr) {
          if (a.run) q.run = a.run.aboard.length ? runOf(a.run.aboard) : null;
          tr.stopForConvoy(a);
        }
        continue;
      }
      // back to work: it takes up whatever it still had aboard, or asks for a load like any idle driver
      if (!a) continue;
      a.escort = null;
      a.lead = null;
      if (tr && q.run) { tr.resumeOwned(a, q.run); q.run = null; } else a.ask = 0.5;
    }
    this.fleet.onChange();
  }

  /** The mind the buttons show as on: the fleet's, when every crewed vehicle agrees. */
  mode(): FleetMode | 'mixed' {
    const crew = this.fleet.units.filter((u) => u.driver && u.where !== 'ridden' && !u.away);
    if (!crew.length) return 'work';
    const follow = crew.filter((u) => u.mode === 'follow').length;
    return follow === 0 ? 'work' : follow === crew.length ? 'follow' : 'mixed';
  }

  /** What a following unit is doing, for the fleet window and the garage line. */
  state(u: Unit): 'formed' | 'closing' | 'coming' | 'lost' | null {
    if (u.mode !== 'follow' || this.whyNot(u)) return null;
    if (u.where === 'enroute') return 'coming';
    const st = this.states.get(u.uid);
    if (!st) return u.where === 'working' ? 'closing' : 'coming';
    if (st.formed) return 'formed';
    return st.lost ? 'lost' : 'closing';
  }

  /**
   * The point `back` tiles behind the player along the way they came, world tiles: where a follower that has
   * lost the line is put back (the first drive's helping hand, game/tutorial.ts: a new player must never have
   * to wait out a lost follower). Null before the player is anywhere.
   */
  wakePoint(back: number): { x: number; z: number; heading: number } | null {
    const p = this.host.player();
    if (!p) return null;
    const w = this.wakeAt(back, p.w.ox + p.x, p.w.oz + p.z);
    return { x: w.x, z: w.z, heading: Math.atan2(-w.tx, -w.tz) };
  }

  /** Forget how a follower was doing (it has just been put back in line): it is judged afresh from here. */
  forget(u: Unit): void { this.states.delete(u.uid); }

  /** Tiles a follower still has to make up, or null when it is not following on screen. */
  gapOf(u: Unit): number | null {
    const st = this.states.get(u.uid);
    return st ? st.gap : null;
  }

  /** The hold lent by everything actually in formation: units, the classes they take, and their names. */
  lent(): { units: number; classes: CargoClass[]; names: string[] } {
    let units = 0;
    const classes: CargoClass[] = [];
    const names: string[] = [];
    for (const u of this.followers()) {
      if (!this.states.get(u.uid)?.formed) continue;
      const def = this.fleet.defFor(u);
      units += def.capacity;
      names.push(u.name);
      for (const c of def.holds) if (!classes.includes(c)) classes.push(c);
    }
    return { units, classes, names };
  }

  /** The hold of each vehicle actually in formation: import crates are counted a vehicle at a time (game/culture.ts). */
  holds(): number[] {
    return this.followers().filter((u) => this.states.get(u.uid)?.formed).map((u) => this.fleet.defFor(u).capacity);
  }

  /** The line over the fleet window while anything is following, or null. */
  header(): string | null {
    const list = this.followers();
    if (!list.length) return null;
    const formed = list.filter((u) => this.states.get(u.uid)?.formed).length;
    const lent = this.lent();
    const shape = this.line ? 'in line' : 'in a V';
    return `${formed} of ${list.length} ${shape} behind you${lent.units ? ` · ${lent.units} units of hold lent` : ''}`;
  }

  /** A new world, a teleport, or the player stepping into another vehicle: the wake starts again. */
  reset(): void {
    this.trail = [];
    this.states.clear();
    this.placeOf.clear();
    this.aim = null;
  }

  // ---- the frame ----

  /** The order stations were last handed out in, by unit uid. */
  private order: number[] = [];
  /** Which place in the shape each follower was given last, for as long as the shape keeps its size. */
  private placeOf = new Map<number, number>();
  private placesFor = 0;
  /** The way the shape points: the player's heading, eased, so it swings round a bend rather than whipping. */
  private aim: number | null = null;

  update(dt: number): void {
    const p = this.host.player();
    if (!p || dt <= 0) return;
    this.crumb(p);
    this.reshape(p, dt);
    {
      // at a standstill the shape keeps pointing where it was; on the move it comes round at a steady rate
      const d = this.aim === null ? 0 : Math.atan2(Math.sin(p.heading - this.aim), Math.cos(p.heading - this.aim));
      if (this.aim === null) this.aim = p.heading;
      else this.aim += d * Math.min(1, dt * AIM_RATE * Math.min(1, 0.25 + Math.abs(p.v) / 2));
    }
    const list = this.followers();
    // anything no longer following — put back to work, sold, or taken over by the player — is let go
    for (const uid of [...this.states.keys()]) {
      if (list.some((u) => u.uid === uid)) continue;
      const q = this.fleet.unit(uid);
      if (q?.agent) { q.agent.escort = null; q.agent.lead = null; }
      this.states.delete(uid);
    }
    if (!list.length) return;
    // stations go to whoever is nearest, not in hiring order: in a tight line nobody can pass the car
    // ahead of them, so a follower who arrived second would otherwise wait behind the one in its place
    // for ever. A follower keeps its place unless the one behind is a clear tile nearer, so two side by
    // side don't swap back and forth.
    const px = p.w.ox + p.x, pz = p.w.oz + p.z;
    const far = (u: Unit) => {
      const a = u.agent;
      return a ? Math.hypot(a.w.ox + a.state.x - px, a.w.oz + a.state.z - pz) : Infinity;
    };
    const was = new Map(this.order.map((uid, k) => [uid, k]));
    list.sort((a, b) => {
      const da = far(a), db = far(b);
      if (Math.abs(da - db) > 1) return da - db;
      return (was.get(a.uid) ?? 1e9) - (was.get(b.uid) ?? 1e9) || da - db;
    });
    this.order = list.map((u) => u.uid);
    const slots = this.slots(p, list);
    for (let k = 0; k < list.length; k++) {
      const h = this.harness?.(list[k]) ?? null;
      // where the player can drive, the line can follow: a ford, a ledge, a steep bank
      if (list[k].agent) list[k].agent!.lead = p.def;
      this.drive(list[k], h ?? slots[k], h ? { w: p.w, v: h.v } : p, dt, h?.tow, h ? undefined : slots[k].h, h ? undefined : slots[k], !!h);
    }
  }

  /** The player's wake: a crumb every CRUMB tiles, the oldest dropped once the trail is long enough. */
  private crumb(p: { w: World; x: number; z: number }): void {
    const x = p.w.ox + p.x, z = p.w.oz + p.z;
    const last = this.trail[this.trail.length - 1];
    if (!last) { this.trail.push({ x, z, d: 0 }); return; }
    const step = Math.hypot(x - last.x, z - last.z);
    if (step > JUMP) { this.trail = [{ x, z, d: 0 }]; return; }
    if (step < CRUMB) return;
    this.trail.push({ x, z, d: last.d + step });
    const end = this.trail[this.trail.length - 1].d;
    let cut = 0;
    while (cut < this.trail.length - 1 && end - this.trail[cut].d > TRAIL_TILES) cut++;
    if (cut) this.trail = this.trail.slice(cut);
  }

  /** In line on a road, in a V off it, and neither changes the moment a wheel touches the verge. */
  private reshape(p: { w: World; x: number; z: number; def: VehicleDef }, dt: number): void {
    const x = Math.floor(p.x), z = Math.floor(p.z);
    // only cars keep to a road in single file; at sea and in the air the formation always takes its shape
    const on = p.def.kind !== 'land' ? false : inB(x, z) ? p.w.road[idx(x, z)] > 0 : this.line;
    if (on === this.line) { this.shape = 0; return; }
    this.shape += dt;
    if (this.shape >= SHAPE_HOLD) { this.line = on; this.shape = 0; }
  }

  /**
   * How far out from (x, z) along (nx, nz) a follower may sit, up to `off` (signed), before the ground
   * beside the wake stops being somewhere a vehicle of the leader's kind can be: a building or deep
   * water for a car, land or a shoal for a boat. A flyer has the whole sky.
   */
  private clearOut(w: World, def: VehicleDef, x: number, z: number, nx: number, nz: number, off: number, half: number): number {
    if (def.kind === 'air') return off;
    const sign = Math.sign(off), far = Math.abs(off) + half;
    const ok = (gx: number, gz: number): boolean => {
      const tx = Math.floor(gx - w.ox), tz = Math.floor(gz - w.oz);
      if (!inB(tx, tz)) return true;
      const i = idx(tx, tz);
      if (def.kind === 'water') return w.water[i] >= 0 && waterDepth(w, i) >= ((def as { minDepth?: number }).minDepth ?? 1);
      return !w.blocked[i] && waterDepth(w, i) <= Math.max(1, (def as { wade?: number }).wade ?? 0);
    };
    for (let d = 0.5; d <= far + 1e-6; d += 0.5) {
      if (!ok(x + nx * sign * d, z + nz * sign * d)) return sign * Math.max(0, d - 0.5 - half);
    }
    return off;
  }

  /** Whether a vehicle of this kind could go straight from one point to the other (world tiles) over its own sort of ground. */
  private lineClear(w: World, def: VehicleDef, x0: number, z0: number, x1: number, z1: number): boolean {
    if (def.kind === 'air') return true;
    const L = Math.hypot(x1 - x0, z1 - z0), n = Math.max(1, Math.ceil(L * 2));
    for (let k = 1; k <= n; k++) {
      const x = x0 + ((x1 - x0) * k) / n, z = z0 + ((z1 - z0) * k) / n;
      const tx = Math.floor(x - w.ox), tz = Math.floor(z - w.oz);
      if (!inB(tx, tz)) continue;
      const i = idx(tx, tz);
      if (def.kind === 'water' ? !(w.water[i] >= 0 && waterDepth(w, i) >= ((def as { minDepth?: number }).minDepth ?? 1)) : w.blocked[i] || waterDepth(w, i) > Math.max(1, (def as { wade?: number }).wade ?? 0)) return false;
    }
    return true;
  }

  /** The index of the wake crumb nearest (x, z), if one is within `r` tiles; -1 if none is. */
  private nearWake(x: number, z: number, r: number): number {
    let best = -1, bd = r;
    for (let i = 0; i < this.trail.length; i++) {
      const c = this.trail[i], d = Math.hypot(c.x - x, c.z - z);
      if (d < bd) { bd = d; best = i; }
    }
    return best;
  }

  /** The point `ahead` tiles on from crumb i along the wake (toward the player), and the way it runs there. */
  private alongWake(i: number, ahead: number): { x: number; z: number; h: number } {
    let k = i, left = ahead;
    while (k + 1 < this.trail.length) {
      const a = this.trail[k], b = this.trail[k + 1], seg = Math.hypot(b.x - a.x, b.z - a.z);
      if (seg >= left) { const f = left / seg; return { x: a.x + (b.x - a.x) * f, z: a.z + (b.z - a.z) * f, h: Math.atan2(b.x - a.x, b.z - a.z) }; }
      left -= seg; k++;
    }
    const c = this.trail[this.trail.length - 1], pr = this.trail[Math.max(0, this.trail.length - 2)];
    return { x: c.x, z: c.z, h: Math.atan2(c.x - pr.x, c.z - pr.z) || 0 };
  }

  /**
   * The point `back` tiles behind the player along the way they came, and the way they were going there
   * (a unit vector). Where the wake is too short (just set off, or turned on the spot), the rest is laid
   * straight back along the way the shape points.
   */
  private wakeAt(back: number, px: number, pz: number): { x: number; z: number; tx: number; tz: number } {
    const hd = this.aim ?? 0;
    let x = px, z = pz, gone = 0, tx = Math.sin(hd), tz = Math.cos(hd);
    for (let i = this.trail.length - 1; i >= 0; i--) {
      const c = this.trail[i];
      const seg = Math.hypot(x - c.x, z - c.z);
      if (seg < 1e-6) continue;
      const sx = (x - c.x) / seg, sz = (z - c.z) / seg;
      if (gone + seg >= back) {
        const f = (back - gone) / seg;
        // the tangent blends toward the shape's own heading near the leader, so the first row is square to it
        return { x: x - sx * seg * f, z: z - sz * seg * f, tx: sx, tz: sz };
      }
      gone += seg; x = c.x; z = c.z; tx = sx; tz = sz;
    }
    return { x: x - tx * (back - gone), z: z - tz * (back - gone), tx, tz };
  }

  /**
   * Where each follower belongs, in world tiles. In line: a point back along the player's wake, each
   * vehicle's own length making room for the next. In the V: rows of two behind the player, the first
   * pair a row back and a column out, the next pair further back and further out.
   */
  private slots(p: { w: World; x: number; z: number; heading: number; v: number; def: VehicleDef }, list: Unit[]): { x: number; z: number; h?: number; ax?: number; az?: number }[] {
    const out: { x: number; z: number; h?: number; ax?: number; az?: number }[] = [];
    // room for braking grows with pace, but only pace a vehicle can shed: a plane never flies slower than
    // its stall, so its line opens up only for speed above that
    const spare = Math.max(0, Math.abs(p.v) - ((p.def as { minSpeed?: number }).minSpeed ?? 0));
    const fx = Math.sin(p.heading), fz = Math.cos(p.heading);
    const px = p.w.ox + p.x, pz = p.w.oz + p.z;
    // how far behind the player each of them belongs, each vehicle's own length making room for the next
    const backs: number[] = [];
    const gap = SPACING + SPEED_GAP * spare;
    let back = halfSize(p.def)[0] + gap;
    for (const u of list) {
      const half = halfSize(this.fleet.defFor(u))[0];
      back += half;
      backs.push(back);
      back += half + gap;
    }
    if (!this.line) {
      let len = halfSize(p.def)[0] * 2, wide = halfSize(p.def)[1] * 2;
      for (const u of list) { const [hl, hw] = halfSize(this.fleet.defFor(u)); len = Math.max(len, hl * 2); wide = Math.max(wide, hw * 2); }
      // side by side, a long vessel needs more than its beam: a ship swings its stern out as it turns
      const rowStep = Math.max(ROW, len + SPACING) + SPEED_GAP * spare, colStep = Math.max(COL, wide + 0.6, len * 0.45);
      // the shape is set by those actually with you: one still a way off neither counts nor takes a place
      // in it, but queues up behind the shape until it arrives
      const near = list.filter((u) => this.states.get(u.uid)?.inShape);
      const shape = shapeOf(near.length);
      const last = shape.reduce((m, q) => Math.max(m, q.row), 0);
      // each row sits on the player's own wake, so the shape bends through a turn as a convoy does rather
      // than swinging round the leader like a rigid frame; the wing of a row is out square to the wake there
      // how far ahead of its station a follower steers for, as traffic.ts's escort would pick it
      const lead = p.def.kind === 'air' ? 1.2 + Math.abs(p.v) * 0.6 : 0.7 + Math.abs(p.v) * 0.4;
      const at = (q: { row: number; col: number }, ahead = 0): { x: number; z: number; h: number; ax?: number; az?: number } => {
        const back = rowStep * q.row - ahead;
        const w0 = this.wakeAt(back, px, pz);
        // round a tight bend the wings close in toward the wake: a wing wider than the bend's radius would
        // sit on the far side of its centre, and have to cross the whole shape to get there
        const a1 = this.wakeAt(Math.max(0, back - 1.5), px, pz), a2 = this.wakeAt(back + 1.5, px, pz);
        const turn = Math.abs(Math.atan2(a1.tx * a2.tz - a1.tz * a2.tx, a1.tx * a2.tx + a1.tz * a2.tz));
        const radius = turn > 1e-3 ? (back + 1.5 - Math.max(0, back - 1.5)) / turn : Infinity;
        const lat = colStep * q.col, reach = Math.max(colStep, radius * WING_BEND);
        let off = Math.sign(lat) * Math.min(Math.abs(lat), reach);
        // and a wing never out across a building, a bank or a shoal: it closes in toward the wake as far
        // as the ground beside it is clear, so the shape narrows through a town or a channel
        if (off) off = this.clearOut(p.w, p.def, w0.x, w0.z, w0.tz, -w0.tx, off, wide / 2);
        const spot = { x: w0.x + w0.tz * off, z: w0.z - w0.tx * off, h: Math.atan2(w0.tx, w0.tz) };
        if (ahead) return spot;
        const aim = at(q, lead);
        return { ...spot, ax: aim.x, az: aim.z };
      };
      const spots = shape.map((q) => at(q));
      // each place goes to the follower nearest it, and a follower keeps its place unless another is
      // clearly nearer: handing places out in any fixed order sends the shape criss-crossing through itself
      if (this.placesFor !== near.length) { this.placeOf.clear(); this.placesFor = near.length; }
      const where = (u: Unit) => { const a = u.agent; return a ? { x: a.w.ox + a.state.x, z: a.w.oz + a.state.z } : { x: px, z: pz }; };
      // the cheapest way to hand every place out at once (never one follower cheap and the last one a
      // long way off), a follower's own place counting a little cheaper so the shape doesn't reshuffle
      const cost = near.map((u) => {
        const q = where(u);
        return spots.map((sp, k) => Math.hypot(sp.x - q.x, sp.z - q.z) - (this.placeOf.get(u.uid) === k ? STICK : 0));
      });
      const pick = assign(cost);
      const given = new Map<number, number>();
      near.forEach((u, i) => given.set(u.uid, pick[i]));
      this.placeOf = given;
      let late = 0;
      for (const u of list) {
        const k = given.get(u.uid);
        out.push(k !== undefined ? spots[k] : at({ row: last + 1 + late++, col: 0 }));

      }
      return out;
    }
    // in line: walk back down the wake from where the player is now, dropping a station at each distance
    let x = px, z = pz, gone = 0, k = 0;
    for (let i = this.trail.length - 1; i >= 0 && k < backs.length; i--) {
      const c = this.trail[i];
      const seg = Math.hypot(x - c.x, z - c.z);
      while (k < backs.length && backs[k] <= gone + seg) {
        const t = (backs[k] - gone) / Math.max(1e-6, seg);
        out.push({ x: x + (c.x - x) * t, z: z + (c.z - z) * t });
        k++;
      }
      gone += seg;
      x = c.x; z = c.z;
    }
    // the wake runs out (you have only just set off, or you have hardly moved): the rest of the line
    // stands off straight behind it, the way it was last going
    if (k < backs.length) {
      const first = this.trail[0], next = this.trail[1];
      let dx = -fx, dz = -fz;
      if (first && next) {
        const ax = first.x - next.x, az = first.z - next.z, len = Math.hypot(ax, az);
        if (len > 1e-3) { dx = ax / len; dz = az / len; }
      }
      for (; k < backs.length; k++) out.push({ x: x + dx * (backs[k] - gone), z: z + dz * (backs[k] - gone) });
    }
    return out;
  }

  /**
   * One follower: hold the station if it is near it, route back to it on the roads if it is not.
   * A vehicle whose cell is not in memory is the convoy's business and is left alone.
   */
  private drive(u: Unit, slot: { x: number; z: number }, p: { w: World; v: number }, dt: number, tow?: { heading: number; pedal: number; taut: boolean }, heading?: number, aim?: { ax?: number; az?: number }, harnessed = false): void {
    const a = u.agent, tr = u.traffic;
    let st = this.states.get(u.uid);
    if (!st) { st = { routing: false, still: 0, sends: 0, wait: 0, lost: false, retry: 0, formed: false, gap: 0, inShape: false }; this.states.set(u.uid, st); }
    if (!a || !tr || u.where === 'enroute') { st.formed = false; st.routing = false; return; }
    const s = a.state;
    // the station in this vehicle's own frame: it may be holding station over a border
    const sx = slot.x - a.w.ox, sz = slot.z - a.w.oz;
    const gap = Math.hypot(sx - s.x, sz - s.z);
    st.gap = gap;
    // counted in the shape once it is close, and let go of only when it is clearly left behind
    // it leaves the shape only after being well back for a moment: one hovering at the edge would
    // otherwise pop in and out, and every time it did the whole shape would reshuffle round it
    const behind = gap > DROP || st.routing || st.lost;
    st.outFor = behind ? (st.outFor ?? 0) + dt : 0;
    if (!st.inShape && (st.formed || gap < 4) && !st.routing && !st.lost) st.inShape = true;
    else if (st.inShape && behind && (st.outFor > DROP_HOLD || st.lost)) st.inShape = false;
    // no way through from where it stands: it waits where it is, and looks for one again now and then
    if (st.lost) {
      st.formed = false;
      a.escort = null;
      st.retry -= dt;
      if (st.retry > 0) return;
      st.lost = false;
      st.routing = true;
      st.sends = 0;
      st.wait = 0;
    }
    // fallen well back but still on (or by) the player's own wake: it chases along the wake, which the
    // player has just shown to be passable, rather than being sent round by the road planner after a
    // place that keeps moving on
    st.noWake = Math.max(0, (st.noWake ?? 0) - dt);
    // (sooner when something stands between it and its place: that is what the wake goes round)
    const cut = gap > FORMED && gap <= WAKE_CHASE && !this.lineClear(a.w, a.def, a.w.ox + s.x, a.w.oz + s.z, slot.x, slot.z);
    const onWake = (gap > WAKE_CHASE || cut) && !harnessed && !tow && !st.noWake ? this.nearWake(a.w.ox + s.x, a.w.oz + s.z, (a.def.kind === 'water' ? 4 : 3) + 1.5 * halfSize(a.def)[0]) : -1;
    // chasing the wake but getting nowhere (a corner of a building cut too close, a fence the leader
    // squeezed past): the planner takes it round properly for a while instead
    st.wakeStill = onWake >= 0 && Math.abs(s.v) < 0.08 ? (st.wakeStill ?? 0) + dt : 0;
    if (onWake >= 0 && st.wakeStill > WAKE_STALL) { st.wakeStill = 0; st.noWake = NO_WAKE; st.routing = true; st.wait = 0; st.sends = 0; }
    else if (onWake >= 0) {
      if (st.routing) { st.routing = false; st.sends = 0; }
      st.formed = false;
      const aim = this.alongWake(onWake, 1.5 + Math.abs(s.v) * 0.6);
      a.escort = { x: sx, z: sz, v: Math.abs(p.v), h: aim.h, ax: aim.x - a.w.ox, az: aim.z - a.w.oz, tow };
      return;
    }
    if (!st.routing && gap > (a.def.kind === 'air' ? CATCH_UP_AIR : CATCH_UP)) { st.routing = true; st.wait = 0; st.sends = 0; }
    if (st.routing && gap < FORMED) { st.routing = false; st.sends = 0; a.escort = null; }
    if (st.routing) {
      st.formed = false;
      a.escort = null;
      st.wait -= dt;
      st.still = Math.abs(s.v) < 0.08 ? st.still + dt : 0;
      // it is driven on the roads like any other trip: it is only sent again when it has arrived at
      // where it was sent, when the line has moved on well past that, or when it has stopped dead
      const drift = Math.hypot(a.to.x - sx, a.to.z - sz);
      const stalled = st.still > STALL;
      // with this frame's route-finding spent, sending waits a moment (nine followers can all fall
      // back at once, each send a search)
      const due = st.wait <= 0 && (a.phase === 'parked' || drift > RESEND || stalled);
      if (due && routesSpent()) st.wait = 0.1 + Math.random() * 0.3;
      else if (due) {
        st.wait = 1.5;
        // for the part of the wake nearest its place, not the place itself: the player has just been
        // there, so it is somewhere this vehicle can get to (a place in the shape may be on a bank or a shoal)
        const k = this.nearWake(slot.x, slot.z, 12);
        const to = k >= 0 ? this.trail[k] : slot;
        const sent = tr.driveOwned(a, clampCell(to.x - a.w.ox), clampCell(to.z - a.w.oz));
        // a send that changes nothing — no way through, or it is still standing where it was — counts
        // against it; a few of those in a row and it gives you up until it is worth looking again
        st.sends = !sent || stalled ? st.sends + 1 : 0;
        st.still = 0;
        if (st.sends >= MAX_SENDS) {
          st.lost = true;
          st.routing = false;
          st.retry = LOST_AGAIN;
        }
      }
      return;
    }
    // holding station: steer for the point and keep the player's pace
    // a shape (not a line down a road) says which way it points, so a follower can keep station alongside
    // only a place in the shape steers as one; a tow's harness station (with a rope or not yet) drives as before
    const shaped = !this.line && !tow && heading !== undefined;
    a.escort = {
      x: sx, z: sz, v: Math.abs(p.v), h: shaped ? heading : undefined, tow,
      ax: shaped && aim?.ax !== undefined ? aim.ax - a.w.ox : undefined, az: shaped && aim?.az !== undefined ? aim.az - a.w.oz : undefined,
    };
    st.formed = gap <= LEND;
  }
}

/**
 * Where each of n vehicles sits behind the player off the road, at sea or in the air: rows back
 * (1 = the first row) and columns out (in column steps, + to the right). One follows straight behind;
 * two and four make a V; three a diamond; from five on the rows of a set of bowling pins with the player
 * as the head pin — two, then three, then four, then five — the last row, if it is not full, centred.
 */
export function shapeOf(n: number): { row: number; col: number }[] {
  if (n <= 0) return [];
  if (n === 4) return [{ row: 1, col: -1 }, { row: 1, col: 1 }, { row: 2, col: -2 }, { row: 2, col: 2 }];
  const out: { row: number; col: number }[] = [];
  for (let row = 1, left = n; left > 0; row++) {
    // a full row of pins is one more than its number; a short last row closes up round the middle
    const k = n === 1 ? 1 : Math.min(row + 1, left);
    for (let i = 0; i < k; i++) out.push({ row, col: (i - (k - 1) / 2) * 2 });
    left -= k;
  }
  // the row nearest the player fills from the middle out, so a lone follower is straight behind
  return out;
}

/**
 * The assignment of rows to columns (a square cost matrix) with the least total cost: the Hungarian
 * method, O(n³), which for a formation of nine is nothing.
 */
export function assign(cost: number[][]): number[] {
  const n = cost.length;
  if (!n) return [];
  const INF = 1e18;
  const u = new Array(n + 1).fill(0), v = new Array(n + 1).fill(0), p = new Array(n + 1).fill(0), way = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    p[0] = i;
    let j0 = 0;
    const minv = new Array(n + 1).fill(INF), used = new Array(n + 1).fill(false);
    do {
      used[j0] = true;
      const i0 = p[j0];
      let delta = INF, j1 = 0;
      for (let j = 1; j <= n; j++) {
        if (used[j]) continue;
        const cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
        if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
        if (minv[j] < delta) { delta = minv[j]; j1 = j; }
      }
      for (let j = 0; j <= n; j++) {
        if (used[j]) { u[p[j]] += delta; v[j] -= delta; } else minv[j] -= delta;
      }
      j0 = j1;
    } while (p[j0] !== 0);
    do { const j1 = way[j0]; p[j0] = p[j1]; j0 = j1; } while (j0);
  }
  const out = new Array(n).fill(0);
  for (let j = 1; j <= n; j++) if (p[j]) out[p[j] - 1] = j - 1;
  return out;
}

/** A point a vehicle may be sent to: its own cell, or a little way over a border into the next. */
const clampCell = (v: number): number => Math.min(2 * N - 1, Math.max(-N + 1, v));

/** Is this load one the formation can take between them? */
function formationHolds(classes: CargoClass[], c: CargoClass): boolean {
  return classes.includes(c);
}

/** Where each kind of vehicle follows you, for the reason a button is off. */
const FOLLOWS_IN: Record<string, string> = { land: 'on the road', water: 'on the water', air: 'in the air' };

/**
 * A crewed vehicle can fall in behind you when you drive one of its own kind — a car behind a car, a
 * boat behind a boat — and a flyer whatever you drive (it flies over the road or the sea); a train never can; everything else is told why.
 * With no `lead` (nobody out), only the crew and the railway are asked about.
 */
function whyNotFollow(fleet: Fleet, u: Unit, lead: VehicleDef | null = null): string | null {
  const def = fleet.defFor(u);
  if (!u.driver) return 'nobody is driving it';
  if (def.kind === 'rail') return 'it never leaves its railway';
  if (def.kind === 'air' && def.jet) return 'a jet flies its own routes between airports';
  if (!canFollow(def, lead)) return `${def.name} only follows you ${FOLLOWS_IN[def.kind] ?? ''}: drive one of its kind`;
  return null;
}

/** Can a vehicle of this kind follow the player in that one? Its own kind always; a flyer follows anything but a train. */
export function canFollow(def: VehicleDef, lead: VehicleDef | null): boolean {
  if (def.kind === 'rail') return false;
  if (!lead || lead.kind === def.kind) return true;
  return def.kind === 'air' && lead.kind !== 'rail';
}
