/**
 * The HQ window's Home tab (docs/hqwindow.html, "Home"): the company at a glance. The HQ building itself
 * turning on the hero stage's plinth (the real one: its variant, facing, style and livery), the fleet's
 * shield, and the address; beside it the net worth with its last week, and eight stat tiles, each a link
 * into the tab that explains it. Without an HQ: an empty plinth and the nearest addresses to buy.
 */
import { esc, money } from './cargoHud';
import type { Fleet } from './fleet';
import type { Estate } from './estate';
import type { Books } from './books';
import { gradeName, gradePips } from './hqGrade';
import type { Address } from './hq';
import type { HeroSpec } from './missions/model';
import { hero } from '../render/heroStage';
import { DAYS_PER_YEAR } from '../render/season';
import { lotWorth } from './estateTab';
import type { World, Building } from '../world/tiles';

export type HqTab = 'home' | 'fleet' | 'estate' | 'tech' | 'books' | 'diamonds' | 'hearts' | 'factions' | 'treats' | 'toppers';

interface HomeHost {
  /** Net worth now (the metrics' basis), and its rank among the fleets met. */
  worth(): number;
  rank(): { place: number; of: number };
  towns(): { held: number; strong: number };
  /** The game day, and the day the company was founded. */
  day(): number;
  founded(): number;
  /** Loads delivered by you. */
  delivered(): number;
  /** The fleet's shield with its HQ stars, as an image. */
  shield(): string;
  /** The HQ building, while its island is in memory. */
  building(): { w: World; b: Building } | null;
  /** The town's style the HQ is drawn in. */
  styleOf(w: World, b: Building): string;
  addresses(): Address[];
  showAddress(a: Address): void;
  find(): void;
  /** The airlift home: what it costs, how many counties, and why not (null: no HQ). game/airlift.ts */
  airlift(): { cost: number; counties: number; why: string | null } | null;
  doAirlift(): void;
  tab(t: HqTab): void;
  standings(): void;
  /** The annual newspaper's kept issues, newest last (docs/newspaper.html, Press cuttings), and opening one. */
  papers?(): { n: number; name: string; year: number; read: boolean; face: string }[];
  openPaper?(n: number): void;
}

/** The HQ as the hero stage draws it: the real building (its variant, facing, style and livery). Also the dock's HQ square. */
export function hqHero(w: World, b: Building, style: string): HeroSpec {
  return {
    kind: 'building', b: b.kind, arch: style as never, w: b.w, d: b.d, floors: b.floors,
    real: { cx: w.cx, cz: w.cz, uid: b.uid, seed: b.seed, facing: b.facing, ...(b.style ? { style: b.style } : {}), ...(b.derelict ? { derelict: true } : {}) },
  };
}

export class HqHome {
  readonly el = document.createElement('div');
  private stage = document.createElement('div');
  private still = document.createElement('img');
  private side = document.createElement('div');
  private info = document.createElement('div');
  private shown = false;
  private moving = false;
  private addrs: Address[] = [];
  private stills = new Map<string, string>();
  private html = '';

  constructor(private fleet: Fleet, private estate: Estate, private books: Books, private host: HomeHost) {
    this.el.className = 'hq-home';
    const left = document.createElement('div');
    left.className = 'hq-hleft';
    this.stage.className = 'hq-stage bld';
    this.still.className = 'hq-still bld';
    this.still.alt = '';
    left.append(this.stage, this.still, this.side);
    this.side.className = 'hq-hside';
    this.info.className = 'hq-hinfo';
    this.el.append(left, this.info);
    this.el.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('button');
      if (!b) return;
      if (b.dataset.tab) this.host.tab(b.dataset.tab as HqTab);
      else if (b.dataset.act === 'find') this.host.find();
      else if (b.dataset.act === 'airlift') this.host.doAirlift();
      else if (b.dataset.act === 'standings') this.host.standings();
      else if (b.dataset.act === 'move') { this.moving = !this.moving; this.render(true); }
      else if (b.dataset.addr) { const a = this.addrs[Number(b.dataset.addr)]; if (a) this.host.showAddress(a); }
      else if (b.dataset.paper) this.host.openPaper?.(Number(b.dataset.paper));
    });
  }

  setVisible(on: boolean): void {
    this.shown = on;
    if (on) { this.moving = false; this.render(true); }
  }

  /** The HQ on the plinth, or its last still when its island has gone from memory. */
  private showHq(): void {
    const h = this.fleet.hq;
    const at = h ? this.host.building() : null;
    if (h && at) {
      const { w, b } = at;
      const spec = hqHero(w, b, this.host.styleOf(w, b));
      this.stage.hidden = false;
      this.still.hidden = true;
      hero.mount(this.stage);
      hero.show(spec, 0xd9b34a);
      // kept, for when this island has gone from memory
      if (!this.stills.has(h.key)) setTimeout(() => { if (this.fleet.hq?.key === h.key && this.shown) this.stills.set(h.key, hero.still(spec, 0xd9b34a, 420, 300)); }, 600);
      return;
    }
    const src = h ? this.stills.get(h.key) : undefined;
    this.stage.hidden = true;
    this.still.hidden = !src;
    if (src) this.still.src = src;
  }

  render(force = false): void {
    if (!this.shown) return;
    const f = this.fleet, h = f.hq;
    this.showHq();
    if (this.moving || !h) this.addrs = this.host.addresses();
    const addr = (this.moving || !h)
      ? (this.addrs.length
        ? `<div class="hq-addr"><small>${h ? 'Grander addresses near' : 'Make a building your HQ to open fleet slots. Nearest:'}</small>${this.addrs.map((a, i) => `<button type="button" data-addr="${i}"><span class="stars">${gradePips(a.grade)}</span> <b>${a.slots}</b> slot${a.slots === 1 ? '' : 's'} · ${esc(a.name)}${a.town ? `, ${esc(a.town)}` : ''} · ${Math.round(a.dist)} tiles · ${money(a.price)}</button>`).join('')}</div>`
        : '<p class="gsub">No grander building near that you could buy. Explore: every building you see can be checked by clicking it.</p>')
      : '';
    const far = h && !this.host.building() ? `<p class="gsub">${this.stills.has(h.key) ? 'As last seen: its island is far away.' : 'Far away: its island isn’t loaded. Find it to see it.'}</p>` : '';
    const shield = this.host.shield();
    // the airlift home: $100 a county, offered from two counties out (game/airlift.ts)
    const q = h ? this.host.airlift() : null;
    const lift = q ? `<button type="button" data-act="airlift" class="hq-lift"${q.why ? ` disabled title="${esc(q.why)}"` : ` title="A Bumblebee flies you and your vehicle to ${esc(h!.name)}: ${q.counties} counties at ${money(100)} each"`}>🚁 Airlift me home${q.counties >= 2 ? ` · ${money(q.cost)}` : ''}</button>` : '';
    const side = `<div class="hq-addrline">${shield ? `<img class="shield" alt="" src="${shield}">` : ''}${h
      ? `<span><b>${esc(h.name)}</b><small>${esc(h.town || 'the countryside')} · <span class="stars">${gradePips(h.grade)}</span> ${esc(gradeName(h))} · ${f.slots} fleet slot${f.slots === 1 ? '' : 's'}${f.hqDown ? ' · boarded up: one slot short' : ''}</small></span>`
      : '<span><b>No HQ yet</b><small>Only the vehicle you drive is out. Any building you own can be your HQ: a house opens one slot.</small></span>'}</div>${far}
      <div class="gacts">${h ? '<button type="button" data-act="find">Find it</button>' : ''}${lift}<button type="button" data-act="move" class="${this.moving ? 'on' : ''}">${h ? 'Move HQ…' : 'Where to buy one'}</button><button type="button" data-act="standings">Standings · ${this.rankWord()}</button></div>${q?.why ? `<p class="gsub hq-liftwhy">🚁 ${esc(q.why)}</p>` : ''}${addr}`;

    // the numbers
    const rows = this.books.rows;
    const sum = (fn: (r: typeof rows[number]) => number) => rows.reduce((t, r) => t + fn(r), 0);
    const cargoYou = sum((r) => r.inc.cargo[0]), cargoCrew = sum((r) => r.inc.cargo[1]);
    const rent = sum((r) => r.inc.rent[0] + r.inc.rent[1] + r.inc.rent[2]);
    const roads = sum((r) => r.out.roads);
    const worth = this.host.worth();
    const today = this.host.day(), founded = this.host.founded();
    const week = rows.filter((r) => r.day <= today - 7).pop()?.worth;
    const delta = week !== undefined ? worth - week : null;
    const spark = this.spark(today);
    const age = Math.max(0, today - founded), years = Math.floor(age / DAYS_PER_YEAR), days = age % DAYS_PER_YEAR;
    const units = f.units, garaged = f.garaged;
    const value = units.reduce((t, u) => t + f.resale(u), 0), shed = garaged.reduce((t, u) => t + f.resale(u), 0);
    const out = f.deployed.length + (f.ridden ? 1 : 0);
    const t = this.estate.totals();
    const deeds = [...this.estate.deeds.values()];
    const lotsValue = deeds.reduce((s, d) => s + lotWorth(this.estate, d), 0);
    const paying = deeds.filter((d) => this.estate.trailing(d).took > 0).length;
    const loads = this.host.delivered() + units.reduce((s, u) => s + u.log.deliveries, 0);
    const kept = f.drivers.reduce((s, d) => s + d.kept, 0);
    const rk = this.host.rank(), tw = this.host.towns();
    const b = this.books.built;
    const tile = (tab: HqTab | 'standings', label: string, value: string, sub: string) => `<button type="button" class="hq-tile" ${tab === 'standings' ? 'data-act="standings"' : `data-tab="${tab}"`}><small>${label}</small><b>${value}</b><span>${sub}</span></button>`;
    const info = `<div class="hq-hero"><small>Net worth</small><b>${money(worth)}</b>${delta !== null ? `<span class="${delta >= 0 ? 'up' : 'down'}">${delta >= 0 ? '+' : '−'}${money(Math.abs(delta))} last 7 days</span>` : ''}${spark}</div>
      <div class="hq-tiles">
        ${tile('books', 'Founded', `Day ${founded + 1}, year ${Math.floor(founded / DAYS_PER_YEAR) + 1}`, `${years ? `${years} year${years === 1 ? '' : 's'} ` : ''}${days} day${days === 1 ? '' : 's'} old`)}
        ${tile('fleet', 'Vehicles', `${out} out · ${garaged.length} in the garage`, `worth ${money(value)}${shed ? ` (${money(shed)} garaged)` : ''}`)}
        ${tile('estate', 'Buildings', `${t.lots} lot${t.lots === 1 ? '' : 's'}`, `paid ${money(t.paid)} · sell for ${money(lotsValue)}`)}
        ${tile('books', 'Roads & bridges', `${b.tiles.toLocaleString()} tiles · ${b.bridges} bridge${b.bridges === 1 ? '' : 's'} · ${b.tunnels} tunnel${b.tunnels === 1 ? '' : 's'}`, `${money(roads)} spent`)}
        ${tile('books', 'Deliveries', money(cargoYou + cargoCrew), `${loads.toLocaleString()} loads · you ${money(cargoYou)} · crew ${money(cargoCrew)}`)}
        ${tile('estate', 'Rent', money(rent), `${paying} of ${t.lots} lot${t.lots === 1 ? '' : 's'} paid this week`)}
        ${tile('fleet', 'Crew', `${f.drivers.length} driver${f.drivers.length === 1 ? '' : 's'}`, `${f.bench.length} on the bench · ${money(kept)} kept by drivers`)}
        ${tile('standings', 'Standing', rk.of > 1 ? `${ordinal(rk.place)} of ${rk.of}` : 'No rivals met', `${tw.held} town${tw.held === 1 ? '' : 's'} preferred · ${tw.strong} strong`)}
      </div>
      ${this.cuttings()}
      ${this.books.pre ? `<p class="gsub">Lifetime money from before the books opened (${money(this.books.pre)}) shows in Books, under All time.</p>` : ''}`;
    const html = side + '\u0000' + info;
    if (!force && html === this.html) return;
    this.html = html;
    this.side.innerHTML = side;
    this.info.innerHTML = info;
  }

  /** Press cuttings: the paper's kept issues, newest first, each opening its front page. */
  private cuttings(): string {
    const list = this.host.papers?.() ?? [];
    if (!list.length) return '';
    const esc2 = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));
    return `<div class="hq-cuttings"><small>Press cuttings</small><div>${[...list].reverse().map((p) => `<button type="button" class="hq-cut${p.read ? '' : ' new'}" data-paper="${p.n}" title="Open issue ${p.n}"><b class="face-${p.face}">${esc2(p.name)}</b><span>Year ${p.year}${p.read ? '' : ' · unread'}</span></button>`).join('')}</div></div>`;
  }

  private rankWord(): string {
    const r = this.host.rank();
    return r.of > 1 ? `${ordinal(r.place)} of ${r.of}` : 'just you';
  }

  /** The last 14 days' closing net worth as little bars. */
  private spark(today: number): string {
    const rows = this.books.rows;
    const vals: number[] = [];
    let last = rows.filter((r) => r.day < today - 13).pop()?.worth ?? 0;
    for (let d = today - 13; d <= today; d++) {
      const r = rows.find((q) => q.day === d);
      if (r) last = r.worth;
      vals.push(last);
    }
    const max = Math.max(1, ...vals), min = Math.min(...vals, 0);
    const bars = vals.map((v, k) => {
      const hh = Math.max(1, ((v - min) / Math.max(1, max - min)) * 22);
      return `<rect x="${k * 7}" y="${24 - hh}" width="5" height="${hh}" rx="1"/>`;
    }).join('');
    return `<svg class="spark" viewBox="0 0 98 24" width="98" height="24" aria-label="net worth, last 14 days">${bars}</svg>`;
  }
}

function ordinal(n: number): string {
  const s = n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] ?? 'th';
  return `${n}${s}`;
}
