import { STORY_MARKS, type StoryPlace } from '../render/storyProps';
import { press } from './press/desk';
import { sentence } from './press/hooks';
import { NEXT_WORLD } from '../world/nextWorld';

/**
 * The two long story chains (docs/storychains.html): Stargazers, which ends with the fleet at a launch pad
 * and a moon rocket on it, and Still Waters, which ends with the fleet at a dry dock and a submarine
 * slipping out of it. Their missions are ordinary arc steps (missions/story); this is what they leave
 * behind in the world between missions:
 *
 * - how many steps of each are done, and which launch pad and which dock each is bound to, for the
 *   drawings (render/storyProps.ts) to stack the rocket and build the submarine there;
 * - where each chain's places are (the observatory, the base, the fishing harbour, the lighthouse...),
 *   so every step of a chain goes back to the same ones;
 * - the morning's news: a finished step can post a headline, read out at 07:00 the next game morning and
 *   kept in the notification log, and a cinema title for the county's marquees;
 * - a "so far" line per finished step, for the journal; and the flags the twenty-first missions will read
 *   (`ready`), which nothing in the game offers yet.
 *
 * One of these for the game, like the deeds: the templates read it when they bind, the mission system
 * tells it when a step ends, main.ts saves it and plays its news.
 */

export type Chain = 'moon' | 'deep';
export const CHAINS: Chain[] = ['moon', 'deep'];

/** A place a chain has bound: where it is in world tiles, its kind, its cell, and the corner of its lot when it is a building (bx -1 when not). */
export interface Anchor { x: number; z: number; kind: string; cx: number; cz: number; bx: number; bz: number }

/** What a finished step puts out into the world. */
export interface Beat {
  /** A Channel 6 headline the next morning (uppercase, 60 characters at most) and the line under it. */
  headline?: string;
  line?: string;
  /** A title for the cinema marquees of the county, from now on. */
  marquee?: string;
}

interface Queued { at: number; title: string; body: string }

export interface SavedStory {
  steps: Record<Chain, number>;
  ended: Record<Chain, number>;
  anchors: Record<string, Anchor>;
  log: { c: Chain; i: number; line: string }[];
  news: Queued[];
  marquee: string[];
  ready: Chain[];
  rival?: Partial<Record<Chain, string>>;
  /** The harbour town whose lights flicker in sevens after the blackout, and until when (0.7.0). */
  flicker?: Flicker;
}

/** A town's lights stuttering in sevens: its middle in world tiles, how far it reaches, and the game hour it stops. */
interface Flicker { x: number; z: number; r: number; until: number }

/** How long the harbour town's lights flicker after Still Waters' Blackout, game hours, and how far round the harbour. */
const FLICKER_HOURS = 24, FLICKER_R = 45;

const placeOf = (a: Anchor): StoryPlace => ({ cx: a.cx, cz: a.cz, bx: a.bx, bz: a.bz });

/** Game hours a chain waits between one step ending and its next being offered: a day, about ten minutes of play. */
export const STORY_GAP = 24;

export class Story {
  /** Steps done in each chain. */
  readonly steps: Record<Chain, number> = { moon: 0, deep: 0 };
  /** The game hour each chain's last step ended. */
  readonly ended: Record<Chain, number> = { moon: -1e9, deep: -1e9 };
  /** Each chain's places, by key ("moon:obs", "deep:dock"). */
  readonly anchors = new Map<string, Anchor>();
  /** A line per finished step, oldest first. */
  readonly log: { c: Chain; i: number; line: string }[] = [];
  /** Headlines waiting for their morning. */
  private news: Queued[] = [];
  /** Titles the cinemas put up. */
  readonly marquee: string[] = [];
  /** Chains whose capstone is done: the next mission (not built) would read these. */
  readonly ready = new Set<Chain>();
  /** After Still Waters' Blackout (0.7.0): the harbour town's lights flicker in sevens for a day. */
  flicker: Flicker | null = null;
  /** Set by main.ts: a headline to show, and a structure to redraw. */
  say: ((title: string, body: string) => void) | null = null;
  redraw: ((at: StoryPlace) => void) | null = null;

  /** Where a chain's key place is, if it has been bound. */
  anchor(key: string): Anchor | null { return this.anchors.get(key) ?? null; }

  /** Remember a chain's place, so the next step goes back to it; the pad and the dock are what the drawings follow. */
  bind(key: string, a: Anchor): void {
    const was = this.anchors.get(key);
    this.anchors.set(key, a);
    if (key === 'moon:pad' || key === 'deep:yard') {
      this.syncMarks();
      if (was && was.bx >= 0 && (was.cx !== a.cx || was.cz !== a.cz || was.bx !== a.bx || was.bz !== a.bz)) this.redraw?.(placeOf(was));
      if (a.bx >= 0 && (!was || was.bx !== a.bx || was.bz !== a.bz)) this.redraw?.(placeOf(a));
    }
  }

  /**
   * A chain's step `i` is done: its line for the journal, its news for the morning, its mark on the world.
   * `hours` is the game hour now; `last` whether it was the chain's capstone.
   */
  finished(c: Chain, i: number, hours: number, line: string, beat: Beat | undefined, last: boolean): void {
    this.steps[c] = Math.max(this.steps[c], i + 1);
    this.ended[c] = hours;
    this.log.push({ c, i, line });
    if (this.log.length > 60) this.log.splice(0, this.log.length - 60);
    if (beat?.headline) {
      // the next 07:00 after now
      const day = Math.floor(hours / 24), at = (hours % 24) < 7 ? day * 24 + 7 : (day + 1) * 24 + 7;
      this.news.push({ at, title: `Channel 6 · ${beat.headline}`, body: beat.line ?? '' });
      // and the year's paper picks the story up (docs/newspaper.html)
      press.write({ k: 'storyBeat', f: { headline: sentence(beat.headline), line: beat.line ?? '' } });
    }
    if (beat?.marquee && !this.marquee.includes(beat.marquee)) this.marquee.push(beat.marquee);
    // the blackout: the harbour town's lamps come back flickering in sevens, for a day
    const dock = this.anchor('deep:dock');
    if (NEXT_WORLD && c === 'deep' && i === 8 && dock) this.flicker = { x: dock.x, z: dock.z, r: FLICKER_R, until: hours + FLICKER_HOURS };
    if (last) this.ready.add(c);
    // both chains done: one more headline, once
    if (last && this.ready.size === 2) {
      const day = Math.floor(hours / 24);
      this.news.push({ at: (day + 1) * 24 + 7, title: 'Channel 6 · TWO COUNTS, ONE RHYTHM', body: 'The moon and the trench are signalling in step, say scientists. Nobody knows what it means.' });
    }
    this.syncMarks();
    const at = this.anchor(c === 'moon' ? 'moon:pad' : 'deep:yard');
    if (at && at.bx >= 0) this.redraw?.(placeOf(at));
  }

  /** A step passed over because there was nowhere in reach for it: the chain moves on without waiting a day. */
  skipped(c: Chain, i: number, hours: number): void {
    this.steps[c] = Math.max(this.steps[c], i + 1);
    this.ended[c] = hours - STORY_GAP;
    this.log.push({ c, i, line: 'Passed over a step: nowhere near enough for it.' });
    this.syncMarks();
    const at = this.anchor(c === 'moon' ? 'moon:pad' : 'deep:yard');
    if (at && at.bx >= 0) this.redraw?.(placeOf(at));
  }

  /** Set a chain's steps outright (the debug console's jump): the drawings follow. */
  setSteps(c: Chain, n: number): void {
    this.steps[c] = Math.max(0, Math.min(20, n));
    this.syncMarks();
    const at = this.anchor(c === 'moon' ? 'moon:pad' : 'deep:yard');
    if (at && at.bx >= 0) this.redraw?.(placeOf(at));
  }

  /** The morning's news, when its hour has come. */
  update(hours: number): void {
    if (!this.news.length) return;
    const due = this.news.filter((q) => q.at <= hours);
    if (!due.length) return;
    this.news = this.news.filter((q) => q.at > hours);
    for (const q of due) this.say?.(q.title, q.body);
  }

  /** The journal's "so far" for a chain: its last few lines. */
  soFar(c: Chain, n = 4): string[] { return this.log.filter((q) => q.c === c).slice(-n).map((q) => q.line); }

  /** Push the steps and the bound pad and dock to the drawings. */
  private syncMarks(): void {
    STORY_MARKS.titles = [...this.marquee];
    STORY_MARKS.moon = this.steps.moon;
    STORY_MARKS.deep = this.steps.deep;
    const pad = this.anchor('moon:pad'), dock = this.anchor('deep:yard');
    STORY_MARKS.moonAt = pad && pad.bx >= 0 ? placeOf(pad) : null;
    STORY_MARKS.deepAt = dock && dock.bx >= 0 ? placeOf(dock) : null;
  }

  toSave(): SavedStory {
    return {
      steps: { ...this.steps }, ended: { ...this.ended }, anchors: Object.fromEntries(this.anchors),
      log: [...this.log], news: [...this.news], marquee: [...this.marquee], ready: [...this.ready],
      flicker: this.flicker ?? undefined,
    };
  }

  /** A save's story, or a fresh one; `arcs` (the missions' own arc progress) wins where the two disagree. */
  load(s: SavedStory | null | undefined, arcs?: Map<string, number>): void {
    this.reset();
    if (s) {
      for (const c of CHAINS) { this.steps[c] = s.steps?.[c] ?? 0; this.ended[c] = s.ended?.[c] ?? -1e9; }
      for (const [k, a] of Object.entries(s.anchors ?? {})) this.anchors.set(k, a);
      this.log.push(...(s.log ?? []));
      this.news = [...(s.news ?? [])];
      this.marquee.push(...(s.marquee ?? []));
      for (const c of s.ready ?? []) this.ready.add(c);
      this.flicker = s.flicker ?? null;
    }
    if (arcs) for (const c of CHAINS) this.steps[c] = Math.max(this.steps[c], arcs.get(c) ?? 0);
    this.syncMarks();
  }

  reset(): void {
    this.steps.moon = 0; this.steps.deep = 0;
    this.ended.moon = -1e9; this.ended.deep = -1e9;
    this.anchors.clear();
    this.log.length = 0;
    this.news = [];
    this.marquee.length = 0;
    this.ready.clear();
    this.flicker = null;
    this.syncMarks();
  }

  /** The flickering town now, if it is still flickering. */
  flickerAt(hours: number): Flicker | null { return this.flicker && hours < this.flicker.until ? this.flicker : null; }
}

export const story = new Story();
