import * as THREE from 'three';
import type { CarStats } from '../game/cars';

export interface CarMesh {
  root: THREE.Group;
  body: THREE.Group;
  wheels: THREE.Mesh[];
  steerGroups: THREE.Group[];
}

const WHEEL_R = 0.2;

export function createCarMesh(stats: CarStats): CarMesh {
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const paint = new THREE.MeshStandardMaterial({ color: stats.color, roughness: 0.55, metalness: 0.05, flatShading: true });
  const dark = new THREE.MeshStandardMaterial({ color: 0x2a2a2e, roughness: 0.9, flatShading: true });
  const hub = new THREE.MeshStandardMaterial({ color: 0xc9c9cd, roughness: 0.5, metalness: 0.3, flatShading: true });
  const glass = new THREE.MeshStandardMaterial({ color: 0xa8d8f0, roughness: 0.2, metalness: 0.1, flatShading: true });
  const lamp = new THREE.MeshStandardMaterial({ color: 0xfff2b0, emissive: 0xffe08a, emissiveIntensity: 0.6, flatShading: true });

  const chassis = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.26, 0.98), paint);
  chassis.position.y = 0.34;
  body.add(chassis);

  const cabin = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.22, 0.46), paint);
  cabin.position.set(0, 0.58, -0.06);
  body.add(cabin);

  const windshield = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.15, 0.03), glass);
  windshield.position.set(0, 0.6, 0.18);
  body.add(windshield);
  const rearGlass = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.13, 0.03), glass);
  rearGlass.position.set(0, 0.6, -0.3);
  body.add(rearGlass);
  for (const sx of [-1, 1]) {
    const side = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.12, 0.34), glass);
    side.position.set(sx * 0.255, 0.6, -0.06);
    body.add(side);
    const light = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.08, 0.03), lamp);
    light.position.set(sx * 0.2, 0.36, 0.5);
    body.add(light);
    const tail = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.06, 0.03), new THREE.MeshStandardMaterial({ color: 0xb02020, emissive: 0x801010, emissiveIntensity: 0.4, flatShading: true }));
    tail.position.set(sx * 0.2, 0.36, -0.5);
    body.add(tail);
  }
  const bumper = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.08, 0.06), dark);
  bumper.position.set(0, 0.24, 0.5);
  body.add(bumper);

  const wheelGeo = new THREE.CylinderGeometry(WHEEL_R, WHEEL_R, 0.18, 12);
  wheelGeo.rotateZ(Math.PI / 2);
  const hubGeo = new THREE.CylinderGeometry(0.09, 0.09, 0.19, 8);
  hubGeo.rotateZ(Math.PI / 2);

  const wheels: THREE.Mesh[] = [];
  const steerGroups: THREE.Group[] = [];
  for (const [sx, sz] of [[-1, 1], [1, 1], [-1, -1], [1, -1]]) {
    const g = new THREE.Group();
    g.position.set(sx * 0.37, WHEEL_R, sz * 0.32);
    const wheel = new THREE.Mesh(wheelGeo, dark);
    const h = new THREE.Mesh(hubGeo, hub);
    wheel.add(h);
    wheel.castShadow = true;
    g.add(wheel);
    body.add(g);
    wheels.push(wheel);
    if (sz > 0) steerGroups.push(g);
  }

  root.traverse((o) => { if ((o as THREE.Mesh).isMesh) { o.castShadow = true; o.receiveShadow = false; } });
  return { root, body, wheels, steerGroups };
}

export { WHEEL_R };
