import * as THREE from 'three';
import { N, STEP, heightAt, idx, type World } from '../world/tiles';
import { ROAD_INFO } from '../world/roads';

/**
 * Markings that lie on the ground (a mission's stopping circle, a search zone, a finish ring, a start line)
 * laid over it point by point, so they follow slopes, banks, road tops and the water rather than staying flat
 * at the height of their middle, where a rise hides part of them and a hollow leaves part floating.
 */

/**
 * Where markings that must read through a faded building sit in the draw order (the user, 27 Oct 2026: a drop's
 * ring or a mission's load hidden behind a see-through building). Buildings are one transparent material that
 * writes depth (render/xray.ts fades one by its alpha), at renderOrder 0: a marking drawn after one is lost behind
 * it however clear it has gone. Drawn before, at SEEN_THROUGH plus its own order, the faded building is laid over
 * it at its alpha, so the ring shows through a clear building and stays hidden by a solid one and by the ground.
 * Only what lies on the ground may: the ground behind it is opaque and already drawn, so nothing behind can paint
 * over it, where a sign standing up in front of a solid building would be painted out by it. The lakes and rivers
 * come before these (render/mesher.ts WATER_ORDER), so a ring on the water isn't dimmed by it.
 */
export const SEEN_THROUGH = -10;

/** A height in world units at a world point (in tiles), or null where nothing is in memory. */
export type Ground = (x: number, z: number) => number | null;

/** What a marking lies on at local point (x, z) of w: the ground, the top of a road on it, or the water's surface. */
export function laidY(w: World, x: number, z: number): number {
  const lx = Math.min(N - 0.001, Math.max(0, x)), lz = Math.min(N - 0.001, Math.max(0, z));
  const i = idx(Math.floor(lx), Math.floor(lz));
  const road = w.road[i];
  const y = heightAt(w, lx, lz) + (road ? ROAD_INFO[road].lift : 0);
  return w.water[i] >= 0 ? Math.max(y, w.water[i] * STEP) : y;
}

/** laidY over the worlds in memory, at world points. */
export function groundOf(worldAt: (cx: number, cz: number) => World | null | undefined): Ground {
  return (x, z) => {
    const w = worldAt(Math.floor(x / N), Math.floor(z / N));
    return w ? laidY(w, x - w.ox, z - w.oz) : null;
  };
}

/** The bare ground at world points, under any water (the seabed): what a marking on the bottom lies on. */
export function floorOf(worldAt: (cx: number, cz: number) => World | null | undefined): Ground {
  return (x, z) => {
    const w = worldAt(Math.floor(x / N), Math.floor(z / N));
    return w ? heightAt(w, x - w.ox, z - w.oz) : null;
  };
}

let shared: Ground | null = null, floor: Ground | null = null;
/**
 * The ground every marking without one of its own lies on (main.ts sets it to the worlds in memory), and the bare
 * ground under the water for one on the seabed (docs/underwater.html).
 */
export function setLaidGround(g: Ground | null, f: Ground | null = null): void { shared = g; floor = f; }
export function laidGround(): Ground | null { return shared; }
export function laidFloor(): Ground | null { return floor; }

/** How far along the ring one of its steps is, at most, in tiles: short enough that a step never cuts into a rise. */
const STEP_ALONG = 0.3;
/** How far past each edge of a band the ground is read too, in tiles: a ledge just beside it still lifts it. */
const PAD = 0.1;
/** How far over what it lies on a marking is laid: clear of the road paint and the water's ripple. */
export const DRAPE_LIFT = 0.07;

/**
 * A band between radii r0 and r1 round (x, z), in world coordinates, from angle `from` through `sweep`, laid
 * over the ground. Each step across the band takes the highest ground over a patch reaching to the next step
 * either side and a little past both edges, so the straight edge between two steps stays over anything between
 * them, a bump or a ledge's edge (a pond's wall, a terrace) alike.
 */
export function drapedBand(x: number, z: number, r0: number, r1: number, ground: Ground, lift = DRAPE_LIFT, sweep = Math.PI * 2, from = -Math.PI / 2): THREE.BufferGeometry {
  const seg = Math.max(8, Math.min(1024, Math.ceil((Math.abs(sweep) * Math.max(r1, 0.5)) / STEP_ALONG)));
  const half = sweep / seg / 2;
  const g0 = ground(x, z) ?? 0;
  const pos = new Float32Array((seg + 1) * 6), index: number[] = [];
  for (let k = 0; k <= seg; k++) {
    const a = from + (sweep * k) / seg;
    let y = -Infinity;
    for (let j = -2; j <= 2; j++) {
      const b = a + half * j, cb = Math.cos(b), sb = Math.sin(b);
      for (let q = 0; q < 5; q++) {
        const r = r0 - PAD + ((r1 - r0 + 2 * PAD) * q) / 4;
        y = Math.max(y, ground(x + cb * r, z + sb * r) ?? g0);
      }
    }
    const ca = Math.cos(a), sa = Math.sin(a);
    pos.set([x + ca * r0, y + lift, z + sa * r0, x + ca * r1, y + lift, z + sa * r1], k * 6);
    if (k < seg) { const i = k * 2; index.push(i, i + 1, i + 2, i + 1, i + 3, i + 2); }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setIndex(index);
  return geo;
}

/** A see-through material for a marking on the ground: drawn over the road it lies on, never into the depth buffer. */
export function drapeMat(colour: number, opacity: number): THREE.MeshBasicMaterial {
  return new THREE.MeshBasicMaterial({
    color: colour, transparent: true, opacity, depthWrite: false, side: THREE.DoubleSide,
    polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -4,
  });
}

/**
 * A ring lying on the ground round a point, `width` wide inside radius r: its band is laid again whenever it is
 * put somewhere new, or where the ground under it has come into memory since. The mesh holds world coordinates,
 * so its parent must sit at the origin.
 */
export class GroundRing {
  readonly mesh: THREE.Mesh;
  private key = '';

  constructor(public r: number, public width: number, material: THREE.Material, private lift = DRAPE_LIFT) {
    this.mesh = new THREE.Mesh(new THREE.BufferGeometry(), material);
    this.mesh.renderOrder = SEEN_THROUGH + 2;
  }

  /** Lay it round (x, z) over `ground`; false when the ground there isn't in memory (the ring is left as it was). */
  place(x: number, z: number, ground: Ground): boolean {
    const g = ground(x, z);
    if (g === null) return false;
    // the ground at the ring's edge too: a ring laid before its far side was in memory is laid again once it is
    const known = [0, 1, 2, 3].map((q) => ground(x + Math.cos(q * Math.PI / 2) * this.r, z + Math.sin(q * Math.PI / 2) * this.r) !== null).join('');
    const key = `${x.toFixed(2)},${z.toFixed(2)},${this.r},${known}`;
    if (key === this.key) return true;
    this.key = key;
    this.mesh.geometry.dispose();
    this.mesh.geometry = drapedBand(x, z, Math.max(0, this.r - this.width), this.r, ground, this.lift);
    return true;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
    this.mesh.removeFromParent();
  }
}

/**
 * Tilt a flat marking (lying in its parent's XZ plane at the parent's origin, `radius` across) to the slope under
 * it, and lift it clear of the highest ground within that radius. The parent stands at (x, y0, z), y0 being the
 * ground at its middle. Returns false, leaving it flat, where the middle isn't on the ground (a deck, a roof):
 * the ground under it is then not what it lies on.
 */
export function layFlat(o: THREE.Object3D, x: number, y0: number, z: number, radius: number, ground: Ground): boolean {
  const c = ground(x, z);
  if (c === null || Math.abs(c - y0) > 0.3) { o.quaternion.identity(); o.position.y = 0; return false; }
  // a plane through the ground round the ring (y = a + b·dx + c·dz), fitted to evenly spaced samples
  const pts: [number, number, number][] = [[0, 0, c]];
  for (const f of [0.5, 1]) {
    const n = f === 1 ? 16 : 8;
    for (let k = 0; k < n; k++) {
      const a = (k / n) * Math.PI * 2, dx = Math.cos(a) * radius * f, dz = Math.sin(a) * radius * f;
      pts.push([dx, dz, ground(x + dx, z + dz) ?? c]);
    }
  }
  let sy = 0, sxx = 0, szz = 0, sxy = 0, szy = 0;
  for (const [dx, dz, y] of pts) { sy += y; sxx += dx * dx; szz += dz * dz; sxy += dx * y; szy += dz * y; }
  const a = sy / pts.length;
  // no steeper than about 35°: past that it reads as a wall, and a cliff is no slope to lie along
  const lim = 0.7;
  const b = Math.max(-lim, Math.min(lim, sxx ? sxy / sxx : 0)), cz = Math.max(-lim, Math.min(lim, szz ? szy / szz : 0));
  let over = 0;
  for (const [dx, dz, y] of pts) over = Math.max(over, y - (a + b * dx + cz * dz));
  const n = new THREE.Vector3(-b, 1, -cz).normalize();
  o.quaternion.setFromUnitVectors(UP, n);
  // over a ledge's edge the plane would rise far off the ground: never more than a little
  o.position.y = a - y0 + Math.min(over, MAX_RISE);
  return true;
}
/** The most layFlat lifts a marking off the slope it is tilted to, in world units. */
const MAX_RISE = 0.4;

/** How far apart the ground is read round each point of a laid copy, in tiles: a 5 × 5 patch, 0.3 each way. */
const PATCH = 0.15;
/**
 * A copy of a flat geometry (lying in XZ, round its origin) laid over the ground, for a mesh scaled by `s` whose
 * parent stands at (x, y0, z): each point raised to the highest ground in a small patch round it, `lift` clear.
 * Dispose of it when done.
 */
export function drapeFlat(src: THREE.BufferGeometry, s: number, x: number, y0: number, z: number, ground: Ground, lift = 0.04): THREE.BufferGeometry {
  const g = src.clone();
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  for (let k = 0; k < p.count; k++) {
    const wx = x + p.getX(k) * s, wz = z + p.getZ(k) * s;
    let y = -Infinity;
    for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) y = Math.max(y, ground(wx + i * PATCH, wz + j * PATCH) ?? y0);
    p.setY(k, (y - y0 + lift) / s);
  }
  p.needsUpdate = true;
  g.computeBoundingSphere();
  return g;
}
const UP = new THREE.Vector3(0, 1, 0);
