import { hex, scale } from '../../../world/biomes';
import type { BuildingKind } from '../../../world/tiles';
import { FLOOR } from '../../../world/towns';
import {
  BRICK, BRIGHT, CARS, GABLES, GLASS, GLASS_LIGHT, METAL, ROOF_GREY, WARM_GLOW, WHITE, WOOD, car, cur, curArch,
  gableFace, pick, roofOver, styleRoof, styleTrim, styleWall, styledGable, win, windowGlow, windowSched,
  type Draw, type Kit,
} from '../kit';

/** Alternative models for the homes between a house and a tower (originals in buildings/homes.ts). */

type RGB = [number, number, number];
const DOORS = [0x5a3a28, 0x2f4d7a, 0x8a3a34, 0x3f5a3f, 0xe2b53a, 0x2bb3a3];
const THATCH = hex(0xc9a55a), SLATE = hex(0x4f4a52);
const doorCol = (r: () => number) => pick(r, cur.doors ?? DOORS);

/** Draw with the frame turned `a` about the lot centre, handing `draw` the turned coordinates of base point (X, Z). */
function turnedAt(k: Kit, X: number, Z: number, a: number, draw: (x: number, z: number) => void): void {
  const c = Math.cos(a), s = Math.sin(a);
  k.turned(a, () => draw(X * c - Z * s, X * s + Z * c));
}

/**
 * A gable end-on to the street over a block w×d: `styledGable` turned along z, except that a Dutch front
 * is put on the street end only (the back one is buried in the roof behind, or never seen).
 */
function frontGable(k: Kit, r: () => number, x: number, y: number, z: number, w: number, h: number, d: number, roof: RGB, wall: RGB): number {
  if (cur.form !== 'dutch') { styledGable(k, r, x, y, z, w, h, d, roof, wall, true); return h; }
  const H = Math.max(h, Math.min(w, d) * cur.pitch * 0.6);
  k.gable(x, y, z, w, H, d, roof, wall, true);
  gableFace(k, x, y, z + d / 2 + 0.012, w + 0.02, H * 1.12, wall, styleTrim(), GABLES[Math.floor(r() * GABLES.length)], true, 1);
  return H * 1.12;
}

// ---- duplex ------------------------------------------------------------------------------------

/** A semi-detached pair: two front-facing gables side by side, mirrored, each door under its own porch roof. */
const duplexTwinGables: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), h = 0.4, bd = 0.5, bz = -0.11, front = bz + bd / 2;
  const pitch = Math.max(0.16, cur.pitch * 0.9);
  for (const sx of [-1, 1]) {
    const hx = sx * 0.21;
    k.box(hx, 0, bz, 0.42, h, bd, wall);
    frontGable(k, r, hx, h, bz, 0.42 + cur.eaves * 0.5, pitch, bd + cur.eaves, roof, wall);
    // the doors side by side at the party wall, under a porch roof each
    const dx = sx * 0.08;
    k.box(dx, 0, front + 0.005, 0.08, 0.18, 0.02, doorCol(r));
    k.box(sx * 0.1, 0.21, front + 0.06, 0.16, 0.02, 0.12, scale(roof, 0.9));
    win(k, b, r, sx * 0.29, 0.08, front, 0.12, 0.1, 1);
    win(k, b, r, hx, h + 0.03, front + cur.eaves / 2, 0.1, 0.08, 1);
  }
  if (cur.chimney) k.box(0, h + pitch * 0.4, bz - 0.14, 0.08, cur.chimney[0], 0.08, hex(cur.chimney[1]));
  else k.box(0, h, bz - 0.14, 0.07, pitch + 0.08, 0.07, pick(r, BRICK));
};

/** Stacked flats: one home on each floor under a hipped roof, the upper door reached by an outside stair up the side. */
const duplexStacked: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), h = 2 * FLOOR - 0.04;
  const bx = -0.08, bw = 0.64, bz = -0.11, bd = 0.48, front = bz + bd / 2;
  k.box(bx, 0, bz, bw, h, bd, wall);
  if (cur.form === 'false') styledGable(k, r, bx, h, bz, bw + 0.02, 0.2, bd + 0.04, roof, wall);
  else if (cur.form) roofOver(k, r, bx, h, bz, bw - cur.eaves, bd - cur.eaves * 0.5, wall, roof);
  else k.hip(bx, h, bz, bw + cur.eaves, Math.max(0.14, cur.pitch * 0.75), bd + cur.eaves, roof);
  // the ground-floor flat: its door and a picture window
  k.box(bx - 0.18, 0, front + 0.005, 0.08, 0.18, 0.02, doorCol(r));
  win(k, b, r, bx + 0.06, 0.07, front, 0.22, 0.11, 1, GLASS_LIGHT);
  // the upper flat: windows, its door at the stair head, the landing and its rail
  win(k, b, r, bx - 0.14, FLOOR + 0.06, front, 0.16, 0.1, 1);
  win(k, b, r, bx - bw / 2, FLOOR + 0.06, bz, 0.14, 0.1, 2);
  k.box(bx + 0.2, FLOOR, front + 0.005, 0.08, 0.17, 0.02, doorCol(r));
  const sx = bx + bw / 2 + 0.07, rail = cur.balcony ? hex(cur.balcony.rail) : styleTrim();
  k.box(0.19, FLOOR - 0.02, front + 0.06, 0.4, 0.02, 0.12, WOOD);
  k.box(0.19, FLOOR, front + 0.115, 0.4, 0.07, 0.012, rail);
  // the stair: a ramp up the +x side from the back to the landing, a handrail over it and a post under the landing
  k.wedge(sx, 0, front - 0.19, 0.13, FLOOR - 0.02, 0.38, WOOD);
  k.bar([sx + 0.06, 0.08, front - 0.38], [sx + 0.06, FLOOR + 0.06, front], 0.008, rail);
  k.box(0.38, 0, front + 0.11, 0.02, FLOOR - 0.02, 0.02, rail);
};

// ---- bungalow ----------------------------------------------------------------------------------

/** A hipped bungalow with a veranda wrapping its front and one side under lean-to roofs on posts. */
const bungalowVeranda: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r);
  const x0 = -0.43, x1 = 0.19, z0 = -0.35, z1 = 0.15, bx = (x0 + x1) / 2, bz = (z0 + z1) / 2, bw = x1 - x0, bd = z1 - z0;
  k.box(bx, 0, bz, bw, 0.27, bd, wall);
  if (cur.form === 'flat' || cur.form === 'curved' || cur.form === 'low') roofOver(k, r, bx, 0.27, bz, bw, bd, wall, roof);
  else k.hip(bx, 0.27, bz, bw + 0.08, 0.24, bd + 0.08, roof);
  // the deck, under bumper height, and its lean-to roofs along the front and down the +x side
  const tin = scale(roof, 0.88), post = styleTrim();
  k.box(bx + 0.07, 0, z1 + 0.09, bw + 0.14, 0.04, 0.18, hex(cur.engawa ?? 0x9a7a56));
  turnedAt(k, bx + 0.07, z1 + 0.1, Math.PI, (x, z) => k.wedge(x, 0.25, z, bw + 0.14, 0.05, 0.2, tin));
  turnedAt(k, x1 + 0.1, bz, -Math.PI / 2, (x, z) => k.wedge(x, 0.25, z, bd, 0.05, 0.2, tin));
  for (const px of [x0 + 0.02, -0.1, x1 + 0.18]) k.box(px, 0.04, z1 + 0.17, 0.018, 0.21, 0.018, post);
  k.box(x1 + 0.18, 0, z0 + 0.04, 0.018, 0.25, 0.018, post);
  // the front door beside a picture window, and a window onto the side veranda
  k.box(-0.1, 0, z1 + 0.005, 0.08, 0.18, 0.02, doorCol(r));
  win(k, b, r, -0.29, 0.08, z1, 0.18, 0.11, 1, GLASS_LIGHT);
  win(k, b, r, x1, 0.08, bz - 0.04, 0.16, 0.11, 0);
  if (cur.chimney) k.box(x0 + 0.12, 0.27, z0 + 0.12, 0.07, cur.chimney[0] + 0.08, 0.07, hex(cur.chimney[1]));
};

/**
 * A mid-century split-level: a low wing and a raised wing a half-storey up, under a butterfly roof (two
 * slopes falling to a valley over the step) or flat roofs with deep fascias, a band of glass and a carport.
 */
const bungalowSplit: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), trim = styleTrim();
  const z0 = -0.35, z1 = 0.15, bz = (z0 + z1) / 2, bd = z1 - z0;
  const lx = -0.28, lw = 0.3, hx = 0.03, hw = 0.32, lh = 0.26, hh = 0.36;
  k.box(lx, 0, bz, lw, lh, bd, wall);
  k.box(hx, 0, bz, hw, hh, bd, scale(wall, 0.95));
  if (cur.form === 'curved' || cur.form === 'low' || cur.form === 'hip' || cur.form === 'dutch' || cur.form === 'false') {
    // the style's own eaves (or a plain hip) on the high wing, a lean-to off it over the low one
    if (cur.form === 'curved' || cur.form === 'low') roofOver(k, r, hx, hh, bz, hw, bd, wall, roof);
    else k.hip(hx, hh, bz, hw + 0.08, 0.18, bd + 0.08, roof);
    turnedAt(k, lx - 0.01, bz, Math.PI / 2, (x, z) => k.wedge(x, lh, z, bd + 0.08, hh - lh, lw + 0.06, roof));
  } else if (cur.form === 'flat' || r() < 0.35) {
    // flat roofs with a deep fascia, the upper one overhanging the lower
    k.box(lx - 0.02, lh, bz, lw + 0.06, 0.04, bd + 0.1, trim, roof);
    k.box(hx + 0.01, hh, bz, hw + 0.08, 0.04, bd + 0.12, trim, roof);
  } else {
    // the butterfly: each slope rises away from the valley over the step between the wings
    turnedAt(k, lx - 0.01, bz, -Math.PI / 2, (x, z) => k.wedge(x, lh, z, bd + 0.1, 0.07, lw + 0.08, roof));
    turnedAt(k, hx + 0.02, bz, Math.PI / 2, (x, z) => k.wedge(x, hh, z, bd + 0.12, 0.08, hw + 0.08, roof));
  }
  // a band of glass along the low wing, a clerestory high on the other, and the door between
  win(k, b, r, lx, 0.07, z1, lw - 0.06, 0.14, 1, GLASS_LIGHT);
  win(k, b, r, hx + 0.06, 0.22, z1, hw - 0.14, 0.08, 1);
  k.box(hx - 0.1, 0, z1 + 0.005, 0.08, 0.19, 0.02, doorCol(r));
  // the carport: a flat roof on slim posts, a car under it
  k.box(0.33, 0.24, -0.08, 0.26, 0.02, 0.56, trim, roof);
  for (const sz of [-0.34, 0.18]) k.box(0.45, 0, sz, 0.02, 0.24, 0.02, METAL);
  car(k, 0.33, -0.06, false, pick(r, CARS));
};

// ---- terrace row -------------------------------------------------------------------------------

/**
 * A terrace built in pairs, each pair a little taller or shorter than the next so the roofline steps,
 * its two doors side by side in the middle and a two-storey bay on one house of the pair.
 */
const terraceStepped: Draw = (k, W, _D, b, r) => {
  const roof = styleRoof(r), base = b.floors * FLOOR;
  const bw = W - 0.1, bd = 0.62, bz = -0.1, front = bz + bd / 2, pairs = 3, pw = bw / pairs, cell = pw / 2;
  const endOn = cur.form === 'dutch' || cur.form === 'false';
  const steps = [0, 0.07, -0.05, 0.12];
  let last = -1;
  for (let p = 0; p < pairs; p++) {
    const px = -bw / 2 + pw * (p + 0.5), wall = styleWall(r);
    let s = Math.floor(r() * steps.length);
    if (s === last) s = (s + 1) % steps.length;
    last = s;
    const h = base + steps[s];
    k.box(px, 0, bz, pw, h, bd, wall);
    if (endOn) frontGable(k, r, px, h, bz, pw + 0.005, Math.max(0.2, cur.pitch * 0.8), bd + 0.06, roof, wall);
    else styledGable(k, r, px, h, bz, pw + 0.005, Math.max(0.16, cur.pitch * 0.6), bd + 0.06, roof, wall);
    k.box(px, h + 0.06, bz, 0.08, 0.2, 0.1, pick(r, BRICK));
    for (const sd of [-1, 1]) {
      const x = px + sd * cell / 2;
      k.box(px + sd * 0.06, 0, front + 0.01, 0.08, 0.18, 0.02, doorCol(r));
      if (sd === (p % 2 ? 1 : -1)) {
        // the bay: two storeys of glass stood out from the front, capped in the roof colour
        const bh = Math.min(2, b.floors) * FLOOR - 0.03, bx = x + sd * cell * 0.12;
        k.box(bx, 0, front + 0.045, cell * 0.44, bh, 0.09, wall, roof);
        for (let f = 0; f < Math.min(2, b.floors); f++) {
          k.pane(bx, 0.06 + f * FLOOR, front + 0.09, cell * 0.36, 0.12, 1, GLASS, [17 + r() * 3, 20.5 + r() * 4, 1.3], WARM_GLOW);
        }
        for (let f = 2; f < b.floors; f++) win(k, b, r, bx, 0.07 + f * FLOOR, front, cell * 0.36, 0.12, 1);
      } else {
        for (let f = 0; f < b.floors; f++) win(k, b, r, x + sd * cell * 0.12, 0.07 + f * FLOOR, front, cell * 0.36, 0.12, 1);
      }
    }
  }
};

/** A mews row: one long roof broken by a gable over the front of every other house, and a dormer over each of the rest. */
const terraceMews: Draw = (k, W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), h = b.floors * FLOOR;
  const bw = W - 0.1, bd = 0.62, bz = -0.1, front = bz + bd / 2, n = 6, cell = bw / n;
  const P = Math.max(0.18, cur.pitch * 0.7);
  k.box(0, 0, bz, bw, h, bd, wall);
  styledGable(k, r, 0, h, bz, bw, P, bd + 0.06, roof, wall);
  const pitched = cur.form !== 'flat' && cur.form !== 'curved' && cur.form !== 'false';
  for (let i = 0; i < n; i++) {
    const x = -bw / 2 + cell * (i + 0.5);
    k.box(x - cell * 0.25, 0, front + 0.01, 0.08, 0.18, 0.02, doorCol(r));
    win(k, b, r, x + cell * 0.14, 0.07, front, cell * 0.34, 0.12, 1);
    for (let f = 1; f < b.floors; f++) win(k, b, r, x, 0.07 + f * FLOOR, front, cell * 0.44, 0.12, 1);
    if (!pitched) {
      // no pitch to break: a raised parapet over every other house instead
      if (i % 2 === 0) k.box(x, h, front - 0.03, cell * 0.7, 0.12, 0.06, wall);
      continue;
    }
    if (i % 2 === 0) {
      // the front gable, its ridge running back into the main roof
      const gd = bd / 2 + 0.04;
      frontGable(k, r, x, h, front - gd / 2 + 0.04, cell * 0.74, P * 0.8, gd, roof, wall);
    } else {
      // a dormer on the front slope
      const dz = bz + bd * 0.28, dy = h + P * 0.25;
      k.box(x, dy, dz, cell * 0.36, 0.12, 0.12, wall);
      k.gable(x, dy + 0.12, dz, cell * 0.36 + 0.03, 0.07, 0.15, roof, wall, true);
      k.pane(x, dy + 0.02, dz + 0.06, cell * 0.24, 0.08, 1, GLASS, [17 + r() * 3, 20.5 + r() * 4, 1.3], WARM_GLOW);
    }
  }
  for (let i = 1; i < n; i += 2) k.box(-bw / 2 + cell * i, h + P * 0.7, bz - 0.04, 0.06, 0.18, 0.1, pick(r, BRICK));
};

// ---- cottage -----------------------------------------------------------------------------------

/** A long low stone croft: a great chimney stack up one gable end, a lean-to on the other, a stone porch in front. */
const croft: Draw = (k, _W, _D, b, r) => {
  const stone = pick(r, [0xc9c1b0, 0xb8b0a2, 0xd6cfbf]), dark = scale(stone, 0.82);
  const slate = curArch === 'victorian', lean = slate ? SLATE : ROOF_GREY;
  const bw = 0.62, bd = 0.36, bz = -0.12, h = 0.24, front = bz + bd / 2;
  k.box(0, 0, bz, bw, h, bd, stone);
  if (slate) k.gable(0, h, bz, bw + 0.04, 0.28, bd + 0.08, SLATE, stone);
  else if (cur.form) styledGable(k, r, 0, h, bz, bw + 0.04, 0.28, bd + 0.08, styleRoof(r), stone);
  else {
    // thatch, roped down with weighted stones hung along the eaves
    k.gable(0, h - 0.02, bz, bw + 0.06, 0.3, bd + 0.14, THATCH, stone);
    for (let i = 0; i < 4; i++) k.box(-0.22 + i * 0.147, h - 0.05, front + 0.07, 0.035, 0.04, 0.035, dark);
  }
  // the great chimney: a stepped stack up the -x gable end
  k.box(-bw / 2 - 0.03, 0, bz, 0.12, 0.34, 0.2, dark);
  k.box(-bw / 2 - 0.02, 0.34, bz, 0.1, 0.24, 0.13, dark);
  k.box(-bw / 2 - 0.02, 0.58, bz, 0.12, 0.025, 0.15, scale(dark, 0.9));
  // the lean-to on the +x end, its roof sloping down away from the house
  const lx = bw / 2 + 0.08;
  k.box(lx, 0, bz - 0.02, 0.16, 0.16, 0.28, scale(stone, 0.94));
  turnedAt(k, lx, bz - 0.02, -Math.PI / 2, (x, z) => k.wedge(x, 0.16, z, 0.32, 0.08, 0.2, lean));
  k.box(lx + 0.081, 0, bz, 0.01, 0.13, 0.08, WOOD);
  // the porch: a little gabled stone box round the door
  k.box(0.06, 0, front + 0.05, 0.14, 0.17, 0.1, stone);
  k.gable(0.06, 0.17, front + 0.05, 0.17, 0.08, 0.12, lean, stone, true);
  k.box(0.06, 0, front + 0.102, 0.07, 0.14, 0.01, pick(r, DOORS));
  for (const sx of [-0.17, 0.22]) win(k, b, r, sx, 0.08, front, 0.08, 0.08, 1);
  win(k, b, r, 0, 0.08, bz - bd / 2, 0.08, 0.08, 3);
  // the peat stack and water butt, and a stone dyke with a gap for the gate
  k.box(-0.36, 0, 0.3, 0.16, 0.1, 0.1, hex(0x4a3a2c), hex(0x5a4a38));
  k.cyl(0.4, 0, 0.06, 0.04, 0.1, WOOD, 6);
  for (const [x, w] of [[-0.26, 0.48], [0.33, 0.26]] as [number, number][]) k.box(x, 0, 0.44, w, 0.07, 0.05, hex(0xa39a8c));
};

// ---- trailer park ------------------------------------------------------------------------------

/** A trailer park laid out in a ring: trailers and RVs nosed in round a laundry and office hut in the middle. */
const trailerRing: Draw = (k, W, D, b, r) => {
  const bodies = [0xf4f2ec, 0xe8e2d4, 0xcfe0e8, 0xdbe8c9, 0xf6e7a8, 0xf0d6c4];
  const rx = W / 2 - 0.44, rz = D / 2 - 0.42, hutCol = hex(0xd8d2c6);
  const pane = (x: number, y: number, z: number, w: number, h: number, face: number) =>
    k.pane(x, y, z, w, h, face, GLASS, windowSched(b.kind, r), windowGlow(b.kind, r));
  // the hut: laundry and site office under one roof, its sign lit after dark
  const wide = rx >= rz, hw = wide ? 0.46 : 0.3, hd = wide ? 0.3 : 0.46;
  k.box(0, 0, 0, hw, 0.24, hd, hutCol);
  k.gable(0, 0.24, 0, hw + 0.06, 0.1, hd + 0.06, ROOF_GREY, hutCol, !wide);
  pane(-hw / 4, 0.1, hd / 2, 0.1, 0.07, 1);
  pane(0, 0.1, -hd / 2, 0.14, 0.07, 3);
  k.box(hw / 4, 0, hd / 2 + 0.005, 0.07, 0.16, 0.01, pick(r, DOORS));
  k.glowBox(hw / 4, 0.18, hd / 2 + 0.015, 0.12, 0.04, 0.012, pick(r, BRIGHT), [17, 23.5, 1.5], WARM_GLOW);
  // eight homes round the ring, each nosed in toward the hut
  const n = 8;
  for (let i = 0; i < n; i++) {
    const a = ((i + 0.5) / n) * Math.PI * 2, X = Math.cos(a) * rx, Z = Math.sin(a) * rz;
    const rv = r() < 0.3, col = pick(r, bodies);
    turnedAt(k, X, Z, Math.atan2(X, Z), (x, z) => {
      // the long axis runs along this frame's z, out from the hut
      if (rv) {
        // an RV: a cab-over bump at the hut end, the windscreen under it and a stripe down the side
        k.box(x, 0.04, z + 0.03, 0.24, 0.21, 0.46, WHITE, hex(0xdadcdf));
        k.box(x, 0.13, z - 0.24, 0.22, 0.1, 0.08, WHITE);
        k.box(x, 0.04, z - 0.23, 0.2, 0.08, 0.06, GLASS);
        k.box(x, 0.1, z + 0.03, 0.245, 0.03, 0.46, pick(r, BRIGHT));
        pane(x + 0.12, 0.15, z + 0.1, 0.14, 0.05, 0);
      } else {
        k.box(x, 0.03, z, 0.26, 0.22, 0.54, col, hex(0xb9bdc2));
        pane(x + 0.13, 0.1, z + 0.1, 0.18, 0.06, 0);
        k.box(x + 0.134, 0.03, z - 0.12, 0.004, 0.15, 0.07, pick(r, DOORS));
        // the striped awning over the door side
        k.box(x + 0.2, 0.23, z - 0.04, 0.14, 0.01, 0.3, i % 2 ? pick(r, BRIGHT) : WHITE);
      }
      if (i % 3 === 1) car(k, x - 0.28, z + 0.04, false, pick(r, CARS));
    });
  }
  // the washing line behind the laundry
  const lz = -hd / 2 - 0.1;
  k.bar([-0.3, 0.2, lz], [0.3, 0.2, lz], 0.004, WHITE);
  for (let i = 0; i < 3; i++) k.box(-0.18 + i * 0.18, 0.14, lz, 0.08, 0.06, 0.004, pick(r, BRIGHT));
  for (const sx of [-0.3, 0.3]) k.box(sx, 0, lz, 0.015, 0.22, 0.015, METAL);
};

export const HOME_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  duplex: [duplexTwinGables, duplexStacked],
  bungalow: [bungalowVeranda, bungalowSplit],
  terraceRow: [terraceStepped, terraceMews],
  cottage: [croft],
  trailerPark: [trailerRing],
};
