/**
 * What the player's car is telling the world, beyond where it is: whether its headlamps are on, and when the
 * horn last sounded. main.ts writes both (N switches the lamps in a road car or a boat; K is the horn, once
 * one is bought at a Vehicle Shop); a tail's target reads them (game/tail), because a car in your mirror
 * with its lights blazing is easy to notice and one that leans on its horn is impossible to miss.
 *
 * Nothing else reads them: the police's cones see a car with its lights off exactly as well as one with them
 * on (the user's call, Oct 2026: running dark is a tailing trick, not a smuggler's cloak).
 */
export const DRIVER = {
  /** The headlamps switched off by hand (N). After dark the beam goes out and the lamps dim to a glimmer. */
  lightsOff: false,
  /** Times the horn has sounded this session: a reader keeps the count it last saw, and a rise is a honk. */
  horns: 0,
};

/** N: switch the lamps. Returns whether they are now on. */
export function toggleLamps(): boolean {
  DRIVER.lightsOff = !DRIVER.lightsOff;
  return !DRIVER.lightsOff;
}

/** The horn has just sounded. */
export function honked(): void { DRIVER.horns++; }
