import * as THREE from 'three';
import { N, type World } from '../../world/tiles';
import { EventParticles } from '../../render/eventParticles';
import { EVENT_LIGHTS, LIGHT_SLOTS, clearLights, setLight, type LightSpec } from '../../render/eventLights';
import { EVENT_OBSTACLES, type Traffic } from '../traffic';
import { KIND_OF, isMarket, type EventKind } from './kinds';
import { countyName, eventsNear, marketsNear, type Happening } from './calendar';
import { mid, placeOf, type Place, type Pt } from './venues';
import { EVENT_ENTRIES, type EventEntry } from '../missions/eventTemplates';
import { hashString } from '../../world/rng';
import { groundOf } from './props';
import { Closure, type Show, type ShowCtx } from './shows';
import { stageShow } from './cast';
import { marketMid } from './markets';

/**
 * The events' stage (docs/events.html): runs the events near the camera. Each moment it asks the calendar what is
 * on round the camera's county, puts on stage (shows.ts) the ones in the camera's 3 × 3 that are getting ready,
 * running or still glowing, at most MAX_STAGED of them nearest first, and lets go of the rest. A show is worked
 * out from the clock alone, so it is the same whenever it is put on or taken off.
 *
 * Meeting them, with no pop-ups: one line in the notification log when an event within two counties starts (with
 * a click that shows it), a pin on the maps for what's on today within reach, and a stamp on the Passport's
 * Events page for being within STAMP_TILES of one while it runs.
 */

/** Most events on stage at once (the camera's 3 × 3). */
const MAX_STAGED = 3;
/** Counties from the camera's that the log hears of. */
const LOG_REACH = 2;
/** Counties from the camera's that the maps pin. */
const PIN_REACH = 3;
/** Tiles from a running event that stamp it. */
const STAMP_TILES = 40;
/** Most markets on stage at once, nearest first (they come every week, so they keep their own count). */
const MAX_MARKETS = 4;

interface StageHost {
  scene: THREE.Object3D;
  seed(): string;
  /** Game hours: days × 24 + hour. */
  hours(): number;
  worldAt(cx: number, cz: number): World | null;
  /** Where the camera is looking, world tiles. */
  focus(): Pt;
  /** The player's vehicle, world tiles, or null on the title. */
  player(): Pt | null;
  trafficOf(w: World): Traffic | null;
  night(): number;
  /** False below quality Low: no particles. */
  particles(): boolean;
  /** A line in the notification log; `show` moves the camera there. */
  log(title: string, body: string, icon: string, show: () => void): void;
  /**
   * Look at a point (the log line's click), then keep asking `track` where the event is: undefined while its county
   * is out of memory, null once it turns out there is nowhere there to hold it.
   */
  look(x: number, z: number, name: string, track: () => Pt | null | undefined): void;
  /** Dim the day (an eclipse near the camera), 0..1. */
  dim(k: number): void;
  /** An event near has got under way: the Press writes it down (main.ts, docs/newspaper.html). */
  news?(e: Happening, place: Place | null): void;
  /** Snow falling where the camera is. */
  snowing?(): boolean;
  /** The Passport's Events page: a stamp for this kind, seen here. */
  stamp(kind: EventKind, at: { cx: number; cz: number; x: number; z: number; name: string }, id?: string): void;
}

/** An event on the maps: where, its icon, and a line saying what and when. */
interface EventPin { id: string; kind: EventKind; cx: number; cz: number; x: number; z: number; icon: string; label: string; now: boolean }

const clock = (h: number): string => {
  const t = ((h % 24) + 24) % 24, hh = Math.floor(t), mm = Math.floor((t - hh) * 60);
  return `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
};

export class EventStage {
  readonly group = new THREE.Group();
  readonly particles: EventParticles;
  private shows = new Map<string, Show>();
  /** Events that had nowhere to happen in their county as it stands: not asked again until it changes. */
  private quiet = new Set<string>();
  private logged = new Set<string>();
  private scanT = 0;
  private scannedAt = -Infinity;
  private near: Happening[] = [];
  private slots: boolean[] = new Array(LIGHT_SLOTS).fill(false);
  private places = new Map<string, Pt | null>();
  /** Where each event near is held, worked out once while its county is in memory. */
  private venues = new Map<string, Place | null>();
  private ctx: ShowCtx;
  /** Off: nothing staged (the title reel, a test). */
  enabled = true;
  /** How much the shows on stage this frame want the day dimmed (an eclipse). */
  private dimK = 0;
  /**
   * The markets (0.7.0): on stage apart from the rare events, and their roads shut by the stage itself for every
   * county in the camera's 3 × 3 while they're set up, staged or not, so nothing drives into a market off screen.
   */
  private marketShows = new Map<string, Show>();
  private closures = new Map<string, { w: World; c: Closure; tiles: number[] }>();

  constructor(private host: StageHost) {
    this.group.name = 'events';
    host.scene.add(this.group);
    this.particles = new EventParticles(host.scene);
    const worldAt = (cx: number, cz: number) => host.worldAt(cx, cz);
    const ground = groundOf(worldAt);
    this.particles.floor = ground;
    this.ctx = {
      group: this.group, particles: this.particles, worldAt, ground,
      trafficOf: (w) => host.trafficOf(w),
      light: (slot, spec) => this.light(slot, spec),
      obstacles: EVENT_OBSTACLES.list,
      night: () => host.night(),
      dim: (k) => { this.dimK = Math.max(this.dimK, k); },
      snowing: () => host.snowing?.() ?? false,
    };
  }

  private light(slot: number, spec: LightSpec | null): number {
    if (slot < 0) {
      slot = this.slots.indexOf(false);
      if (slot < 0) return -1;
    }
    this.slots[slot] = !!spec;
    setLight(slot, spec);
    return slot;
  }

  /** What's on near the camera today and tomorrow, as the calendar has it (refreshed each scan). */
  get nearby(): readonly Happening[] { return this.near; }

  update(dt: number, camera: THREE.PerspectiveCamera, heightPx: number): void {
    const now = this.host.hours();
    EVENT_LIGHTS.uEvTime.value += dt;
    this.particles.enabled = this.host.particles();
    EVENT_OBSTACLES.list.length = 0;
    // twice a second of real time, paused or not (a jump of the clock is picked up at once)
    const t = performance.now();
    if (t >= this.scanT || Math.abs(now - this.scannedAt) > 0.5) { this.scanT = t + 500; this.scannedAt = now; this.scan(now); }
    this.dimK = 0;
    for (const s of this.shows.values()) s.update(now, dt);
    for (const s of this.marketShows.values()) s.update(now, dt);
    this.host.dim(this.dimK);
    this.stamps(now);
    this.particles.update(dt, camera, heightPx);
  }

  /** Who is on stage: the events getting ready, running or glowing in the camera's 3 × 3, nearest first. */
  private scan(now: number): void {
    const seed = this.host.seed();
    const f = this.host.focus(), fcx = Math.floor(f.x / N), fcz = Math.floor(f.z / N);
    const day = Math.floor(now / 24);
    this.near = this.enabled && seed ? eventsNear(seed, fcx, fcz, PIN_REACH, day - 1, day + 1) : [];
    this.markets(now, seed, fcx, fcz, day, f);
    const want: { e: Happening; d: number }[] = [];
    for (const e of this.near) {
      if (isMarket(e.kind)) continue;
      const spec = KIND_OF[e.kind];
      const show = this.shows.get(e.id);
      const until = show ? show.until : e.end + (e.kind === 'parade' ? 9 : 0.3);
      if (now < e.start - spec.lead || now > until) continue;
      const cells = e.route ?? [[e.cx, e.cz]];
      const inView = cells.some(([x, z]) => Math.abs(x - fcx) <= 1 && Math.abs(z - fcz) <= 1 && !!this.host.worldAt(x, z));
      if (!inView) continue;
      const c = show?.centre() ?? { x: (e.cx + 0.5) * N, z: (e.cz + 0.5) * N };
      want.push({ e, d: Math.hypot(c.x - f.x, c.z - f.z) });
    }
    for (const e of this.near) this.announce(e, now, fcx, fcz);
    this.entries(now);
    want.sort((a, b) => a.d - b.d);
    const keep = new Set(want.slice(0, MAX_STAGED).map((q) => q.e.id));
    for (const [id, s] of [...this.shows]) {
      if (keep.has(id)) continue;
      s.dispose();
      this.shows.delete(id);
    }
    for (const { e } of want.slice(0, MAX_STAGED)) {
      if (this.shows.has(e.id) || this.quiet.has(e.id)) continue;
      const s = stageShow(e, this.ctx);
      if (s) this.shows.set(e.id, s); else this.quiet.add(e.id);
    }
    if (this.quiet.size > 500) this.quiet.clear();
  }

  /**
   * The markets round the camera (its 3 × 3): each with a place in a county in memory goes on the list (pins, the
   * log, entries); its road is shut from setting up to packed away; the nearest few go on stage.
   */
  private markets(now: number, seed: string, fcx: number, fcz: number, day: number, f: Pt): void {
    const all = this.enabled && seed ? marketsNear(seed, fcx, fcz, 1, day - 1, day + 1) : [];
    const shut = new Set<string>(), want: { e: Happening; d: number }[] = [];
    for (const e of all) {
      const p = this.venue(e);
      if (!p?.market) continue;
      this.near.push(e);
      const spec = KIND_OF[e.kind];
      if (now < e.start - spec.lead || now >= e.end + (spec.pack ?? 0.5)) continue;
      // its place is remembered, but the county may have gone from memory since
      const w = this.host.worldAt(e.cx, e.cz);
      if (!w) continue;
      let cl = this.closures.get(e.id);
      if (cl && cl.w !== w) { cl.c.set(false); cl = undefined; }
      if (!cl) { const tiles = p.closes ?? p.market.tiles; this.closures.set(e.id, (cl = { w, c: new Closure(w, tiles), tiles })); }
      cl.c.set(true);
      shut.add(e.id);
      const c = marketMid(p.market);
      want.push({ e, d: Math.hypot(w.ox + c.x - f.x, w.oz + c.z - f.z) });
    }
    for (const [id, cl] of [...this.closures]) if (!shut.has(id)) { cl.c.set(false); this.closures.delete(id); }
    want.sort((a, b) => a.d - b.d);
    const keep = new Set(want.slice(0, MAX_MARKETS).map((q) => q.e.id));
    for (const [id, s] of [...this.marketShows]) if (!keep.has(id)) { s.dispose(); this.marketShows.delete(id); }
    for (const { e } of want.slice(0, MAX_MARKETS)) {
      if (this.marketShows.has(e.id) || this.quiet.has(e.id)) continue;
      const s = stageShow(e, this.ctx);
      if (s) this.marketShows.set(e.id, s); else this.quiet.add(e.id);
    }
  }

  /** The markets' roads shut now, by county (the markets gate). */
  shut(): { id: string; w: World; tiles: number[] }[] { return [...this.closures].map(([id, c]) => ({ id, w: c.w, tiles: c.tiles })); }

  /** An event's place in its county (null for nowhere fit, undefined while the county is not in memory). */
  private venue(e: Happening): Place | null | undefined {
    if (this.venues.has(e.id)) return this.venues.get(e.id);
    const w = this.host.worldAt(e.cx, e.cz);
    if (!w) return undefined;
    const p = placeOf(w, e);
    // let go of what is no longer near (not everything: the markets round the camera would all be placed again at once)
    if (this.venues.size > 300) { const keep = new Set(this.near.map((q) => q.id)); for (const k of [...this.venues.keys()]) if (!keep.has(k)) this.venues.delete(k); }
    this.venues.set(e.id, p);
    return p;
  }

  /**
   * The events near taking entries (docs/events.html), written down for the missions to offer at their diamonds
   * (game/missions/eventTemplates.ts): a rally's start until a little after the off, a car show's lot and a drift
   * meet's course until near their end.
   */
  private entries(now: number): void {
    const out: EventEntry[] = [];
    for (const e of this.near) {
      const kind = e.kind === 'offroadRace' ? 'rally' : e.kind === 'carShow' ? 'show' : e.kind === 'driftMeet' ? 'drift'
        : e.kind === 'farmersMarket' ? 'produce' : e.kind === 'christmasMarket' ? 'xmas' : null;
      if (!kind || this.quiet.has(e.id)) continue;
      const closes = kind === 'rally' ? e.start + 0.4 : e.end - 0.4;
      if (now < e.start - KIND_OF[e.kind].lead || now > closes) continue;
      const p = this.venue(e), w = this.host.worldAt(e.cx, e.cz);
      if (!p || !w) continue;
      const ref = (q: Pt, name: string) => ({ x: w.ox + q.x, z: w.oz + q.z, cell: [w.cx, w.cz] as [number, number], name });
      if ((kind === 'produce' || kind === 'xmas') && p.market) {
        out.push({ id: e.id, key: hashString(e.id), kind, at: ref(marketMid(p.market), kind === 'xmas' ? 'the Christmas market' : 'the farmers’ market'), closes });
      } else if (kind === 'rally' && p.course) {
        out.push({ id: e.id, key: hashString(e.id), kind, at: ref(p.course[0], 'the rally start'), to: ref(p.course[p.course.length - 1], 'the rally finish'), closes });
      } else if (p.lot) {
        out.push({ id: e.id, key: hashString(e.id), kind, at: ref(mid(p.lot), kind === 'show' ? 'the car show' : 'the drift meet'), closes });
      }
    }
    EVENT_ENTRIES.list = out;
  }

  /** One line in the log as an event near gets under way: a procession within two counties, the rest once their place is known. */
  private announce(e: Happening, now: number, fcx: number, fcz: number): void {
    if (this.logged.has(e.id) || now < e.start || now > e.end || this.quiet.has(e.id)) return;
    const cells = e.route ?? [[e.cx, e.cz]];
    const reach = isMarket(e.kind) ? 0 : LOG_REACH;
    if (!cells.some(([x, z]) => Math.abs(x - fcx) <= reach && Math.abs(z - fcz) <= reach)) return;
    // its place first: a county in memory with nowhere fit for it isn't having it, and one out of memory can't say yet
    // (four in ten out there had nowhere, the user's 28 Oct 2026 click took the camera to an empty county), so the
    // line waits till the county comes in, while the event is still on
    if (!e.route) {
      const v = this.venue(e);
      if (v === undefined) return;
      if (v === null) { this.quiet.add(e.id); return; }
    }
    this.logged.add(e.id);
    if (this.logged.size > 400) this.logged.delete(this.logged.values().next().value!);
    const spec = KIND_OF[e.kind], seed = this.host.seed();
    const where = this.placeName(e);
    const body = e.kind === 'parade' && e.club ? `${e.club.team.name}, ${e.club.league} champions · ${where}`
      : isMarket(e.kind) ? `${where} · road closed`
      : e.kind === 'motorcade' ? `${countyName(seed, e.route![0][0], e.route![0][1])} to ${countyName(seed, e.route![e.route!.length - 1][0], e.route![e.route!.length - 1][1])} · ${e.route!.length} counties`
      : where;
    if (!isMarket(e.kind)) this.host.news?.(e, this.venue(e) ?? null);
    this.host.log(`${spec.name} ${isMarket(e.kind) ? 'open' : 'under way'}`, `${body} · click to see it`, spec.icon, () => {
      // two counties off, its county is seldom in memory yet: the camera heads for the county's middle, and moves
      // on to the place itself once the county comes in (the user, 28 Oct 2026: it went to the wrong places)
      const p = this.find(e) ?? this.where(e);
      this.host.look(p.x, p.z, spec.name, () => this.find(e));
    });
  }

  /** "Port Cassander, on the civic square", or the county's name when it isn't in memory. */
  private placeName(e: Happening): string {
    return this.venue(e)?.label ?? countyName(this.host.seed(), e.cx, e.cz);
  }

  /**
   * Where the camera should be for an event now: on stage, where it is; else its place once its county is in memory;
   * undefined till then; null for a county with nowhere fit for it (it isn't happening: off the maps from now on).
   */
  find(e: Happening): Pt | null | undefined {
    const live = (this.shows.get(e.id) ?? this.marketShows.get(e.id))?.centre();
    if (live) return live;
    if (!e.route) {
      const v = this.venue(e);
      if (v === undefined) return undefined;
      if (v === null) { this.quiet.add(e.id); return null; }
    } else if (!this.host.worldAt(e.cx, e.cz)) return undefined;
    return this.where(e);
  }

  /** Where an event is on the map: on stage, where it is; else its place if the county is in memory; else its county's middle. */
  where(e: Happening): Pt {
    const live = (this.shows.get(e.id) ?? this.marketShows.get(e.id))?.centre();
    if (live) return live;
    let p = this.places.get(e.id);
    if (p === undefined) {
      const w = this.host.worldAt(e.cx, e.cz);
      if (!w) return { x: (e.cx + 0.5) * N, z: (e.cz + 0.5) * N };
      const pl = this.venue(e);
      const r = pl?.water, rw = pl?.runway;
      const at = (pl?.market ? marketMid(pl.market) : null) ?? pl?.path?.[Math.floor(pl.path.length / 2)] ?? (pl?.lot ? mid(pl.lot) : null)
        ?? (r ? { x: (r.x0 + r.x1) / 2, z: (r.z0 + r.z1) / 2 } : null) ?? pl?.course?.[0] ?? pl?.berths?.[0]
        ?? (rw ? { x: rw.ax + rw.ux * rw.len / 2 - w.ox, z: rw.az + rw.uz * rw.len / 2 - w.oz } : null)
        ?? (pl?.tower ? mid(pl.tower) : null) ?? pl?.from ?? null;
      p = at ? { x: w.ox + at.x, z: w.oz + at.z } : null;
      if (this.places.size > 300) this.places.clear();
      this.places.set(e.id, p);
    }
    return p ?? { x: (e.cx + 0.5) * N, z: (e.cz + 0.5) * N };
  }

  /** Today's events within reach, for the maps: on now, or starting within the next twelve hours. */
  pins(): EventPin[] {
    const now = this.host.hours();
    const out: EventPin[] = [];
    for (const e of this.near) {
      if (this.quiet.has(e.id) || now > e.end || e.start - now > 12) continue;
      const spec = KIND_OF[e.kind], p = this.where(e), on = now >= e.start;
      out.push({ id: e.id, kind: e.kind, cx: Math.floor(p.x / N), cz: Math.floor(p.z / N), x: p.x - Math.floor(p.x / N) * N, z: p.z - Math.floor(p.z / N) * N, icon: spec.icon, label: on ? `${spec.name} · on now` : `${spec.name} · ${clock(e.start)}`, now: on });
    }
    return out;
  }

  /** The region map's Events view: what's on round the camera today and tomorrow, where, and when. */
  listing(): { id: string; icon: string; name: string; when: string; x: number; z: number; now: boolean; route?: [number, number][] }[] {
    const now = this.host.hours(), today = Math.floor(now / 24);
    const out: ReturnType<EventStage['listing']> = [];
    for (const e of this.near) {
      if (this.quiet.has(e.id) || now > e.end || e.start - now > 30) continue;
      const spec = KIND_OF[e.kind], p = this.where(e), on = now >= e.start;
      const day = Math.floor(e.start / 24);
      const when = on ? 'on now' : `${day === today ? 'today' : day === today + 1 ? 'tomorrow' : `day ${day + 1}`} ${clock(e.start)}`;
      out.push({ id: e.id, icon: spec.icon, name: spec.name, when, x: p.x, z: p.z, now: on, ...(e.route ? { route: e.route } : {}) });
    }
    return out;
  }

  /** A stamp for being near one while it runs. */
  private stamps(now: number): void {
    const me = this.host.player();
    if (!me) return;
    for (const s of [...this.shows.values(), ...this.marketShows.values()]) {
      const e = s.e;
      if (now < e.start || now > e.end) continue;
      const c = s.centre();
      if (!c || Math.hypot(c.x - me.x, c.z - me.z) > STAMP_TILES) continue;
      const cx = Math.floor(c.x / N), cz = Math.floor(c.z / N);
      this.host.stamp(e.kind, { cx, cz, x: c.x - cx * N, z: c.z - cz * N, name: this.placeName(e) }, e.id);
    }
  }

  /** Console: what's on near the camera, and what is on stage. */
  list(): string[] {
    const now = this.host.hours();
    return this.near.map((e) => {
      const st = this.shows.has(e.id) || this.marketShows.has(e.id) ? 'ON STAGE' : this.quiet.has(e.id) ? 'nowhere fit' : '';
      return `${KIND_OF[e.kind].icon} ${e.id} · ${clock(e.start)}–${clock(e.end)} day ${e.day + 1}${now >= e.start && now <= e.end ? ' · running' : ''} ${st}`;
    });
  }

  /** Take everything down (the world is going away, or a new game). */
  clear(): void {
    for (const s of this.shows.values()) s.dispose();
    this.shows.clear();
    for (const s of this.marketShows.values()) s.dispose();
    this.marketShows.clear();
    for (const cl of this.closures.values()) cl.c.set(false);
    this.closures.clear();
    this.quiet.clear();
    this.places.clear();
    this.venues.clear();
    EVENT_ENTRIES.list = [];
    this.near = [];
    this.slots.fill(false);
    clearLights();
    this.host.dim(0);
    EVENT_OBSTACLES.list.length = 0;
    this.particles.clear();
  }
}
