import * as THREE from 'three';

/**
 * The world bar (docs/supplychains.html, "The card and the bar"): over each of the fleet's plants near by, the icon of
 * what it is making and a small bar of the run, or of the loads waiting at its kerb. At most MAX on screen, only while
 * a run is under way or goods wait, and none when switched off. Plain DOM, placed over the roof each frame.
 */

export interface PlantBar {
  key: string;
  /** World point over the roof. */
  x: number; y: number; z: number;
  icon: string;
  /** Share of the run done, 0..1; or null with `stock` loads waiting. */
  done: number | null;
  stock: number;
}

const MAX = 24;
/** Tiles from the camera's ground point a plant shows its bar within. */
export const BAR_REACH = 48;

export class PlantBars {
  private root = document.createElement('div');
  private els: HTMLDivElement[] = [];
  private v = new THREE.Vector3();
  on = true;

  constructor() {
    this.root.id = 'plant-bars';
    document.body.append(this.root);
  }

  /** Draw these bars (already filtered to those near and busy), over their roofs as this camera sees them. */
  draw(bars: PlantBar[], camera: THREE.Camera, show: boolean): void {
    const list = show && this.on ? bars.slice(0, MAX) : [];
    while (this.els.length < list.length) {
      const el = document.createElement('div');
      el.className = 'pbar';
      el.innerHTML = '<span></span><i><b></b></i>';
      this.root.append(el);
      this.els.push(el);
    }
    const w = window.innerWidth, h = window.innerHeight;
    this.els.forEach((el, k) => {
      const b = list[k];
      if (!b) { el.hidden = true; return; }
      this.v.set(b.x, b.y, b.z).project(camera);
      if (this.v.z > 1 || this.v.x < -1.1 || this.v.x > 1.1 || this.v.y < -1.1 || this.v.y > 1.1) { el.hidden = true; return; }
      el.hidden = false;
      el.style.transform = `translate(${Math.round(((this.v.x + 1) / 2) * w)}px, ${Math.round(((1 - this.v.y) / 2) * h)}px) translate(-50%, -100%)`;
      const span = el.firstElementChild as HTMLSpanElement;
      const txt = b.done === null ? `${b.icon}×${b.stock}` : b.icon;
      if (span.textContent !== txt) span.textContent = txt;
      const fill = el.querySelector('b') as HTMLElement;
      const pct = `${Math.round((b.done ?? 1) * 100)}%`;
      if (fill.style.width !== pct) fill.style.width = pct;
      el.classList.toggle('ready', b.done === null);
    });
  }
}
