import type { FleetBrand } from './brand';
import { loadingShow } from '../render/loadingShow';
import { NotifyLog } from './notifyLog';
import { fpsLog } from './fpsLog';
import * as THREE from 'three';
import { N, STEP, heightAt, type World } from '../world/tiles';
import { LANDFORM_LABEL } from '../world/landforms';
import { TOWN_INFO } from '../world/towns';
import { money } from './cargoHud';
import type { VehicleDef, VehicleState } from './vehicles';
import { speedIn, speedUnit } from './units';

const SEASON_ICON: Record<string, string> = { spring: '🌱 ', summer: '🌻 ', autumn: '🍂 ', winter: '❄ ' };
/** Milliseconds an entered place's title stays up before it fades (Hud.zone; the fade itself is in index.html). */
const ZONE_HOLD = 3200;
/** The same place's title shows at most once in this long, ms. */
const ZONE_EVERY = 60_000;
/** Milliseconds a camera change's caption stays up before it fades (Hud.caption). */
const CAPTION_HOLD = 1400;
/** A biome's weather beside the season: a raindrop, a dust swirl, a snowflake, mist. */
const wxSvg = (body: string) => `<svg viewBox="-8 -8 16 16" width="11" height="11" style="vertical-align:-1px;margin-right:2px">${body}</svg>`;
const WEATHER_ICON: Record<string, string> = {
  rain: wxSvg('<path d="M0-7C2.5-3 5 0 5 2.5A5 5 0 0 1-5 2.5C-5 0-2.5-3 0-7Z" fill="#6fb3e8"/>'),
  dust: wxSvg('<g fill="none" stroke="#d2a060" stroke-width="1.8" stroke-linecap="round"><path d="M-6-3h8a2.5 2.5 0 1 0-2.5-2.5"/><path d="M-7 1h11a2.5 2.5 0 1 1-2.5 2.5"/><path d="M-5 5h4"/></g>'),
  snow: wxSvg('<g stroke="#6fa8d6" stroke-width="1.6" stroke-linecap="round"><path d="M0-7v14M-6-3.5l12 7M-6 3.5l12-7"/></g>'),
  mist: wxSvg('<g stroke="#8d9aa3" stroke-width="1.8" stroke-linecap="round"><path d="M-7-4h14M-5 0h12M-7 4h11"/></g>'),
};

/** A small moon: lit on the right while waxing, on the left while waning; phase 0 new, 0.5 full. */
function moonIcon(phase: number): string {
  const r = 7, waning = phase > 0.5, p = waning ? 1 - phase : phase;
  const k = Math.cos(p * Math.PI * 2); // 1 new … -1 full
  const rx = Math.abs(k) * r;
  const sweep = k > 0 ? 0 : 1; // crescent: the terminator bulges into the lit side
  const lit = p < 0.01 ? '' : `<path d="M0 ${-r} A${r} ${r} 0 0 1 0 ${r} A${rx.toFixed(2)} ${r} 0 0 ${sweep} 0 ${-r}Z" fill="#f4f1e2"${waning ? ' transform="scale(-1,1)"' : ''}/>`;
  return `<svg viewBox="-9 -9 18 18" width="14" height="14"><circle r="${r}" fill="#3a4560"/>${lit}</svg>`;
}

/** What a station is called on the map. */
const STATION_LABEL: Record<string, string> = {
  terminus: 'Terminus', cityStation: 'City station', townStation: 'Station', halt: 'Halt', goodsYard: 'Goods yard', harbourDepot: 'Harbour depot',
};

/** Seconds a notification may wait for the stage before it goes by unseen (it stays in the history). */
const STALE = 15;

export class Hud {
  private speed = document.getElementById('speed')!;
  private nos = document.getElementById('nos')!;
  private nosKey = '';

  constructor() {
    // a card at the top that opens nothing of its own opens the log (the user, 28 Oct 2026); the toast folds away for it
    // (one that does open something stops the click at its own handler)
    document.getElementById('notices')!.addEventListener('click', (e) => {
      const card = (e.target as HTMLElement).closest<HTMLElement>('.notice');
      if (!card) return;
      e.stopPropagation();
      if (card === this.toast) {
        clearTimeout(this.toastTimer);
        this.toast.classList.remove('show');
        this.toastUntil = performance.now() + 350;
      }
      this.log.openShelf();
    });
    // the controls chip folds down to a keyboard icon and back; the choice is remembered on this device
    const help = document.getElementById('br')!;
    const toggle = document.getElementById('br-toggle') as HTMLButtonElement;
    const KEY = 'pocket-roads-controls-collapsed';
    const set = (collapsed: boolean, save: boolean) => {
      help.classList.toggle('collapsed', collapsed);
      toggle.setAttribute('aria-expanded', String(!collapsed));
      toggle.title = collapsed ? 'Show the controls' : 'Hide the controls';
      if (save) { try { localStorage.setItem(KEY, collapsed ? '1' : '0'); } catch { /* storage blocked: it just won't be remembered */ } }
    };
    // with no choice made yet, folded on a smaller window: open, it covered half of a 960-wide screen and
    // pushed the build tools up over the money (Oct 2026 playtest); the first drive teaches the keys as they come
    let start = innerWidth < 1280 || innerHeight < 800;
    try { const saved = localStorage.getItem(KEY); if (saved !== null) start = saved === '1'; } catch { /* storage blocked */ }
    set(start, false);
    toggle.addEventListener('click', (e) => {
      set(!help.classList.contains('collapsed'), true);
      toggle.blur();
      e.stopPropagation();
    });
    // a press on it isn't a click on the world underneath
    toggle.addEventListener('mousedown', (e) => e.stopPropagation());
    // a town's name in the overview selects the whole town
    this.labelRoot.addEventListener('click', (e) => {
      const el = (e.target as HTMLElement).closest('[data-pick-town]') as HTMLElement | null;
      if (el?.dataset.pickTown) { this.onPickTown?.(el.dataset.pickTown); e.stopPropagation(); }
    });
  }

  /** Mark the selected town's name; '' for none. */
  setSelectedTown(key: string): void {
    if (key === this.selectedTown) return;
    this.selectedTown = key;
    for (const el of Array.from(this.labelRoot.querySelectorAll<HTMLElement>('.tlabel.town'))) el.classList.toggle('sel', el.dataset.pickTown === key);
  }
  private grade = document.getElementById('grade')!;
  private ends = document.getElementById('ends') as HTMLButtonElement | null;
  /** The Change ends button pressed (main.ts: the driven train's TrainState.changeEnds). */
  onEnds: (() => void) | null = null;
  private endsWired = false;
  /** Show the Change ends button: driving a train that stands still. */
  setEnds(show: boolean): void {
    const b = this.ends;
    if (!b) return;
    if (!this.endsWired) {
      this.endsWired = true;
      b.addEventListener('mousedown', (e) => e.preventDefault());
      b.addEventListener('click', () => { this.onEnds?.(); b.blur(); });
    }
    if (b.hidden === show) b.hidden = !show;
  }
  private seedEl = document.getElementById('seed')!;
  private statsEl = document.getElementById('stats')!;
  private clockEl = document.getElementById('clock')!;
  private clockKey = '';
  private bump = document.getElementById('bump')!;
  private vname = document.getElementById('vname');
  private speedUnit = document.querySelector<HTMLElement>('#bl .unit');
  private hint = document.getElementById('hint')!;
  private toast = document.getElementById('toast')!;
  private wind = document.getElementById('wind')!;
  private windArrow = document.getElementById('wind-arrow')!;
  private labelRoot = document.getElementById('town-labels')!;
  private labels: { el: HTMLElement; pos: THREE.Vector3; minor: boolean }[] = [];
  /** Which islands the tags were built for, so they are only built again when that changes. */
  private labelKey = '';
  /** The line under each town's name that counts up the work waiting in it. */
  private jobEls = new Map<string, HTMLElement>();
  /** Under that, how the town is doing and what it taxes; and the kind line above, which graduation changes. */
  private moodEls = new Map<string, { mood: HTMLElement; kind: HTMLElement }>();
  /** A town's name (or its harbour's) has been clicked in the overview: select the whole town. */
  onPickTown: ((key: string) => void) | null = null;
  /** The town selected, whose name wears the selection's colour. */
  private selectedTown = '';
  private v = new THREE.Vector3();
  private fwd = new THREE.Vector3();
  private rel = new THREE.Vector3();
  private toastTimer = 0;
  /** Every notification, folded into a pill at the top middle when its card has gone (game/notifyLog.ts). */
  readonly log = new NotifyLog(document.getElementById('notices')!);
  /** The clock as last shown, for stamping the log. */
  private clockText = '';

  /** The loading screen (render/loadingShow.ts) names the fleet whose world it is (never the seed); nothing when there is none yet. */
  showLoading(brand: FleetBrand | null, road = false): void { loadingShow.show(brand, road ? 'road' : 'show'); }
  /** The bar runs to the end and the screen fades. */
  hideLoading(): void { loadingShow.finish(); }

  /** The R line in the help chip says which way a press will switch the camera. */
  setCameraLock(on: boolean): void {
    const el = document.getElementById('camlock');
    if (el) el.textContent = on ? 'camera locked behind · R to free it' : 'lock camera behind car';
    el?.parentElement?.classList.toggle('on', on);
  }

  /**
   * Name tags for every island in memory, and the line under the seed describing where the player
   * is. Positions are in world tiles, so the tags follow the islands around the lattice.
   */
  setIslands(list: World[], home: World, found: number): void {
    // the seed stays out of the corner (it is on the title screen and in the saves)
    this.seedEl.textContent = home.seed;
    this.seedEl.hidden = true;
    // no town count (the user, 28 Oct 2026): only a megalopolis or the open sea is worth a word
    const kind = home.towns.some((t) => t.kind === 'mega') ? ' · megalopolis' : home.kind === 'sea' ? ' · open sea' : '';
    // on a continent the place has two names: the continent, and the county of it you are standing in
    const place = home.continent ? `${home.continent} · ${home.name}` : home.name;
    this.statsEl.textContent = `${place}${kind} · coords(${home.cx}, ${home.cz})`;

    // the neighbourhood is checked every second; rebuilding the tags each time made them flash
    const key = `${home.seed}|${home.cx},${home.cz}|${list.map((w) => `${w.cx},${w.cz}`).join(';')}`;
    if (key === this.labelKey) return;
    this.labelKey = key;

    this.labelRoot.replaceChildren();
    this.jobEls.clear();
    this.moodEls.clear();
    const label = (name: string, sub: string, pos: THREE.Vector3, minor: boolean, cls = '', jobKey = '', pick = '') => {
      const el = document.createElement('div');
      el.className = `tlabel${cls ? ` ${cls}` : ''}`;
      if (pick) {
        el.dataset.pickTown = pick;
        el.classList.add('town');
        if (pick === this.selectedTown) el.classList.add('sel');
        el.title = 'Select the whole town';
      }
      const b = document.createElement('b');
      b.textContent = name;
      el.append(b);
      const s = document.createElement('span');
      if (sub) {
        s.textContent = sub;
        el.append(s);
      }
      if (jobKey) {
        const j = document.createElement('small');
        j.hidden = true;
        el.append(j);
        this.jobEls.set(jobKey, j);
        const m = document.createElement('small');
        m.className = 'mood';
        m.hidden = true;
        el.append(m);
        this.moodEls.set(jobKey, { mood: m, kind: s });
      }
      if (minor) el.classList.add('minor');
      // stays out of sight until it has been given a place on screen
      el.hidden = true;
      this.labelRoot.append(el);
      return { el, pos, minor };
    };
    this.labels = [];
    for (const w of list) {
      // the island's own name, in capitals over the middle of it; a county carries the continent's
      // name above it instead, since the county line is what changes from one cell to the next
      if (w.kind !== 'sea') {
        this.labels.push(label((w.continent || w.name).toUpperCase(), w.continent ? w.name : '',
          new THREE.Vector3(w.ox + N / 2, 26, w.oz + N / 2), w !== home, 'isle'));
      }
      for (const t of w.towns) {
        this.labels.push(label(t.name, TOWN_INFO[t.kind].label,
          new THREE.Vector3(w.ox + t.x0 + t.size / 2, t.level * STEP + (t.kind === 'mega' ? 6 : 3), w.oz + t.z0 + t.size / 2),
          w !== home, '', `${w.cx},${w.cz}#${t.id}`, `${w.cx},${w.cz}#${t.id}`));
      }
      for (const p of w.ports) {
        this.labels.push(label(p.name, p.major ? 'Major port' : 'Minor dock', new THREE.Vector3(w.ox + p.x, p.level * STEP + 2, w.oz + p.z), w !== home, 'port', '',
          p.town >= 0 && w.towns[p.town] ? `${w.cx},${w.cz}#${p.town}` : ''));
      }
      // the railway's stations, with the line they are on
      for (const st of w.stations) {
        const b = st.building;
        if (!b) continue;
        const line = w.rails[st.path]?.name ?? '';
        const kind = STATION_LABEL[st.kind];
        this.labels.push(label(st.name, `${kind} · ${line}`, new THREE.Vector3(w.ox + b.x + b.w / 2, b.level * STEP + 2.5, w.oz + b.z + b.d / 2), w !== home, 'port'));
      }
      // the named landforms: a volcano, a salt pan, a glacier, a pass, a cave
      for (const l of w.landmarks) {
        const sub = LANDFORM_LABEL[l.kind];
        if (!sub) continue;
        const x = Math.min(N - 1, Math.max(0, l.x)), z = Math.min(N - 1, Math.max(0, l.z));
        this.labels.push(label(l.name, sub, new THREE.Vector3(w.ox + x, heightAt(w, x, z) + 2.5, w.oz + z), w !== home, 'land'));
      }
    }
  }

  /** Town names or kinds have changed: build the tags again next time the neighbourhood is checked. */
  relabel(): void { this.labelKey = ''; }

  /** Each town's mood and levy, and its kind (a town that graduates changes its line). */
  setEconomy(towns: Map<string, { kind: string; line: string; mood: string }>): void {
    for (const [key, els] of this.moodEls) {
      const e = towns.get(key);
      const text = e?.line ?? '';
      if (els.mood.textContent !== text) els.mood.textContent = text;
      els.mood.hidden = !text;
      const cls = `mood ${(e?.mood ?? '').toLowerCase()}`;
      if (els.mood.className !== cls) els.mood.className = cls;
      if (e && els.kind.textContent !== e.kind) els.kind.textContent = e.kind;
    }
  }

  /** The work waiting in each town, written under its name for the overview. */
  setJobs(jobs: Map<string, { n: number; value: number }>): void {
    for (const [key, el] of this.jobEls) {
      const j = jobs.get(key);
      const text = j ? `${j.n} job${j.n === 1 ? '' : 's'} · ${money(j.value)}` : '';
      if (el.textContent !== text) el.textContent = text;
      el.hidden = !text;
    }
  }

  setVehicle(d: VehicleDef, announce: boolean): void {
    if (this.vname) this.vname.textContent = d.name;
    this.hint.textContent = d.hint;
    this.hint.hidden = !d.hint;
    if (announce) this.announce(d.name, d.hint || d.blurb);
  }

  /** When the card on screen goes away (0 when none is showing), and whether it is a deed's. */
  private toastUntil = 0;
  private toastDeed = false;

  /** A card other than a deed's is on screen: an island, a town, a landform. A deed waits its turn. */
  get busy(): boolean { return !this.toastDeed && performance.now() < this.toastUntil; }
  /** Any card is on screen. */
  get showing(): boolean { return performance.now() < this.toastUntil; }

  /**
   * A deed's tier has landed: the tier's colour down the left edge, its pip and the deed's icon, and
   * two lines — "Odometer · Silver" over "1,000 tiles at the wheel · Gold at 10,000".
   */
  deed(icon: string, title: string, body: string, colour: string, tier: number): void {
    this.log.add(title, body, this.clockText);
    this.show(title, body, 4000);
    this.log.tagLast(icon, colour);
    this.toastDeed = true;
    this.toast.classList.add('deed');
    this.toast.style.setProperty('--tier', colour);
    const pip = document.createElement('i');
    pip.className = 'pip';
    pip.textContent = String(tier);
    const ic = document.createElement('em');
    ic.textContent = icon;
    this.toast.querySelector('b')?.prepend(pip, ic);
  }

  /**
   * A title card at the top of the screen for a few seconds. `keep` false: shown, but not kept in the log
   * (arriving somewhere, the camera's pitch). `group`: its source, to stack with the others from it in the log.
   */
  /** A notification shown somewhere else (the fleet ticker's cards): kept in the log, stacked with its `group`, with no card of its own here. */
  keep(title: string, body: string, icon: string, group?: string, img?: string | (() => string), open?: () => void, tip?: string): void {
    this.log.add(title, body, this.clockText, icon, '', group, img, open, false, tip);
    this.log.sync(this.toast.classList.contains('show'));
  }

  /**
   * Notifications wait their turn (one on screen at a time, across the toast, the stamp and achievement cards
   * and the fleet's earnings): kept in the history at once, shown when the stage is free. One that waited
   * longer than STALE goes by unseen; it is still in the history.
   */
  private waiting: { title: string; body: string; ms: number; at: number; open?: () => void; icon?: string | (() => HTMLElement); kind?: string }[] = [];
  /**
   * While true for a title, a notification only goes in the history, never on screen (main.ts: the tutorial's quiet,
   * until "Put her to Work" is done, the user, 7 Nov 2026; the tutorial's own lines are let through).
   */
  hush: ((title: string) => boolean) | null = null;

  announce(title: string, body: string, ms = 3200, keep = true, group?: string): void {
    if (keep) this.log.add(title, body, this.clockText, '', '', group);
    if (this.hush?.(title)) { this.log.sync(this.toast.classList.contains('show')); return; }
    // the same words already waiting, or on screen: once is enough
    if (this.waiting.some((w) => w.title === title && w.body === body) || (this.showing && this.shownKey === `${title}|${body}`)) return;
    this.waiting.push({ title, body, ms, at: performance.now() });
    if (this.waiting.length > 12) this.waiting.shift();
    this.log.sync(this.toast.classList.contains('show'));
  }

  /**
   * Entering a place (the user, 4 Nov 2026: in place of a notification, centred white text as when you enter a new
   * zone in WoW): a small "Entering" over the name, and under it what the place is ("County", "Desert island",
   * "City", "Major port"). It fades in, holds, and fades out; a newer place takes its place at once.
   * The same title shows at most once a minute (the user, 5 Nov 2026: driving along a town's border, "Entering
   * Starhaven" kept flashing up as the line was crossed back and forth).
   */
  zone(name: string, kind: string): void {
    const key = `${name}|${kind}`, now = performance.now();
    if (now - (this.zoneSeen.get(key) ?? -Infinity) < ZONE_EVERY) return;
    this.zoneSeen.set(key, now);
    const el = this.zoneEl ??= (() => {
      const d = document.createElement('div');
      d.id = 'zone-title';
      d.setAttribute('aria-live', 'polite');
      document.body.append(d);
      return d;
    })();
    const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
    el.innerHTML = `<span class="zt-pre">Entering</span><span class="zt-name">${esc(name)}</span>${kind ? `<span class="zt-kind">${esc(kind)}</span>` : ''}`;
    // replay the fade from the start for each new place
    el.classList.remove('on');
    void el.offsetWidth;
    el.classList.add('on');
    clearTimeout(this.zoneT);
    this.zoneT = window.setTimeout(() => el.classList.remove('on'), ZONE_HOLD);
  }
  private zoneEl: HTMLElement | null = null;
  /** When each title (name and kind) last showed, in ms (performance.now). */
  private zoneSeen = new Map<string, number>();
  private zoneT = 0;

  /**
   * A camera change (the user, 4 Nov 2026: in place of the camera pitch notification, quieter words like a place's
   * title): small translucent white words under the car, the setting's name and its detail, with a pip for each
   * step and the one in use lit. A short hold and a quick fade; a newer change replaces it at once, and a place's
   * title (zone) is left alone.
   */
  caption(name: string, detail: string, step: number, of: number): void {
    const el = this.capEl ??= (() => {
      const d = document.createElement('div');
      d.id = 'cam-caption';
      d.setAttribute('aria-live', 'polite');
      document.body.append(d);
      return d;
    })();
    const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
    const pips = Array.from({ length: of }, (_, i) => `<i${i === step ? ' class="on"' : ''}></i>`).join('');
    el.innerHTML = `<span class="cc-name">${esc(name)}</span><span class="cc-detail">${esc(detail)}</span><span class="cc-pips">${pips}</span>`;
    el.classList.remove('on');
    void el.offsetWidth;
    el.classList.add('on');
    clearTimeout(this.capT);
    this.capT = window.setTimeout(() => el.classList.remove('on'), CAPTION_HOLD);
  }
  private capEl: HTMLElement | null = null;
  private capT = 0;

  /**
   * A notification that opens something when clicked, on its card or in the log (the annual newspaper,
   * docs/newspaper.html). `quiet`: only put back in the log, no card and not counted as new (a saved one, on load).
   */
  openable(title: string, body: string, open: () => void, o: { ms?: number; icon?: string; img?: string | (() => string); quiet?: boolean; at?: string } = {}): void {
    this.log.add(title, body, o.at ?? this.clockText, o.icon ?? '', '', undefined, o.img, open, !!o.quiet);
    if (!o.quiet && !this.hush?.(title)) this.waiting.push({ title, body, ms: o.ms ?? 7000, at: performance.now(), open, icon: o.icon });
    this.log.sync(this.toast.classList.contains('show'));
  }

  /**
   * A passing card that isn't kept in the log, its icon an element of its own (the soundtrack's moving
   * soundwave). A newer one of the same `kind` takes the place of one still waiting, so skipping through
   * tracks doesn't stack up a card for each.
   */
  flash(title: string, body: string, kind: string, icon: () => HTMLElement, open?: () => void, ms = 3600): void {
    if (this.hush?.(title)) return;
    this.waiting = this.waiting.filter((w) => w.kind !== kind);
    this.waiting.push({ title, body, ms, at: performance.now(), open, icon, kind });
    this.log.sync(this.toast.classList.contains('show'));
  }

  /** Once a frame: the next waiting notification goes up if the stage is `free` (nothing else on it). */
  pump(free: boolean): void {
    if (this.showing || !free) return;
    const now = performance.now();
    while (this.waiting.length && now - this.waiting[0].at > STALE * 1000) this.waiting.shift();
    const w = this.waiting.shift();
    if (w) this.show(w.title, w.body, w.ms, w.open, w.icon, w.kind);
  }

  /** What the toast is showing, so the same words aren't queued behind themselves. */
  private shownKey = '';

  private show(title: string, body: string, ms: number, open?: () => void, icon?: string | (() => HTMLElement), kind?: string): void {
    this.toast.classList.remove('deed');
    this.toast.dataset.kind = kind ?? '';
    this.toastDeed = false;
    // a card that opens something takes clicks (the stack it sits in lets them through to the world otherwise)
    this.toast.classList.toggle('openable', !!open);
    this.toast.onclick = open ? (e) => {
      e.stopPropagation();
      clearTimeout(this.toastTimer);
      this.toast.classList.remove('show', 'openable');
      this.toast.onclick = null;
      this.toastUntil = performance.now() + 350;
      this.toastTimer = window.setTimeout(() => this.log.sync(false), 350);
      open();
    } : null;
    // up for `ms`, then a moment for the card to fold away before the next may come
    this.toastUntil = performance.now() + ms + 350;
    this.shownKey = `${title}|${body}`;
    this.toast.innerHTML = '';
    const b = document.createElement('b');
    b.textContent = title;
    const s = document.createElement('span');
    s.textContent = body;
    const text = document.createElement('div');
    text.className = 'n-body';
    text.append(b, s);
    if (icon) {
      const i = document.createElement('div');
      i.className = 'n-icon';
      if (typeof icon === 'string') i.textContent = icon;
      else i.append(icon());
      this.toast.append(i);
    }
    this.toast.append(text);
    this.toast.classList.add('show');
    this.log.sync(true);
    clearTimeout(this.toastTimer);
    this.toastTimer = window.setTimeout(() => {
      this.toast.classList.remove('show', 'openable');
      this.toast.onclick = null;
      // the card folds away (.3 s) and the pill comes up where it was
      this.toastTimer = window.setTimeout(() => this.log.sync(false), 350);
    }, ms);
  }

  /** Town name tags pinned over each town, for the overview. `seen`, when given, keeps back the names of places nobody has been near. */
  updateLabels(camera: THREE.Camera, show: boolean, far = false, seen?: (x: number, z: number) => boolean): void {
    this.labelRoot.hidden = !show;
    if (!show) return;
    camera.getWorldDirection(this.fwd);
    for (const l of this.labels) {
      if (far && l.minor) { l.el.hidden = true; continue; }
      if (seen && !seen(l.pos.x, l.pos.z)) { l.el.hidden = true; continue; }
      // A point behind the camera still projects, but mirrored: divide by a negative w and it lands
      // on the wrong side of the screen. That is what threw the tags across the view while turning.
      // Test which side of the camera it is on first, and only project what is genuinely in front.
      this.rel.copy(l.pos).sub(camera.position);
      if (this.rel.dot(this.fwd) <= 0.5) { l.el.hidden = true; continue; }
      this.v.copy(l.pos).project(camera);
      const x = ((this.v.x + 1) / 2) * window.innerWidth, y = ((1 - this.v.y) / 2) * window.innerHeight;
      l.el.hidden = this.v.z > 1 || x < 30 || y < 20 || x > window.innerWidth - 30 || y > window.innerHeight - 20;
      if (l.el.hidden) continue;
      l.el.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px) translate(-50%, -100%)`;
    }
  }

  /** Time of day, a sun or the current moon (drawn in its phase), and the phase's name at night. */
  setClock(time: string, night: number, moonPhase: number, moonName: string, season = '', snowing = 0, weather = ''): void {
    const phase = Math.round(moonPhase * 32) / 32;
    // a biome's weather names itself beside the season; ordinary winter snow as before
    const wx = weather && WEATHER_ICON[weather] ? weather : '';
    const snowy = snowing > 0.55 && wx !== 'snow';
    const key = `${time}|${night > 0.5}|${phase}|${season}|${snowy}|${wx}`;
    if (key === this.clockKey) return;
    this.clockKey = key;
    this.clockText = time;
    const icon = night > 0.5 ? moonIcon(phase) : '<svg viewBox="-10 -10 20 20" width="14" height="14"><circle r="4.5" fill="#f2a93b"/><g stroke="#f2a93b" stroke-width="1.6" stroke-linecap="round"><path d="M0-9v2M0 7v2M-9 0h2M7 0h2M-6.4-6.4l1.4 1.4M5 5l1.4 1.4M-6.4 6.4l1.4-1.4M5-5l1.4-1.4"/></g></svg>';
    const tail = night > 0.5 ? moonName : season;
    this.clockEl.innerHTML = `${icon}<b>${time}</b>${tail ? `<span>${SEASON_ICON[season] ?? ''}${tail}${snowy ? ' · snow' : ''}${wx ? ` · ${WEATHER_ICON[wx]}${wx}` : ''}</span>` : ''}`;
  }

  /** Show the wind arrow; angle is radians clockwise from screen-up. */
  /**
   * The compass beside the top-left card. `yaw` is the follow camera's: it looks along (−sin, −cos)
   * and north is −z, so north sits `yaw` round from the top of the screen.
   */
  setCompass(yaw: number): void {
    const deg = Math.round((yaw * 180) / Math.PI * 2) / 2;
    if (deg === this.compassDeg) return;
    this.compassDeg = deg;
    this.compassRing.style.transform = `rotate(${deg}deg)`;
    // each letter out on the ring at its bearing, turned back so it reads upright
    this.compassLetters.forEach((b, k) => { b.style.transform = `rotate(${k * 90}deg) translateY(-15px) rotate(${-k * 90 - deg}deg)`; });
  }
  private compassRing = document.querySelector<HTMLElement>('#compass .ring')!;
  private compassLetters = Array.from(document.querySelectorAll<HTMLElement>('#compass .ring b'));
  private compassDeg = NaN;

  setWind(visible: boolean, angle = 0): void {
    this.wind.hidden = !visible;
    if (visible) this.windArrow.style.transform = `rotate(${angle}rad)`;
  }

  /**
   * The nitrous gauge beside the speedo: a bottle outline per bottle, filling as it refills, with the
   * seconds to go while any is filling and Shift when one is ready. Null hides it (no bottle fitted).
   */
  setNitrous(fills: number[] | null, burning: boolean, wait: number): void {
    const key = fills ? `${fills.map((f) => Math.round(f * 20)).join(',')}|${burning}|${Math.ceil(wait)}` : '';
    this.speed.classList.toggle('nos', burning);
    if (key === this.nosKey) return;
    this.nosKey = key;
    this.nos.hidden = !fills;
    if (!fills) return;
    const ready = fills.some((f) => f >= 1);
    this.nos.classList.toggle('ready', ready && !burning);
    this.nos.innerHTML = fills.map((f) => `<i class="bottle${f >= 1 ? ' full' : ''}"><i style="height:${Math.round(Math.min(1, f) * 100)}%"></i></i>`).join('')
      + `<span>${burning ? 'nitrous' : ready ? '<kbd>Shift</kbd>' : `${Math.ceil(wait)} s`}</span>`;
  }

  /** Shift with nothing to fire: the gauge shakes. */
  nitrousRefused(): void {
    this.nos.classList.remove('shake');
    void this.nos.offsetWidth;
    this.nos.classList.add('shake');
  }

  update(s: VehicleState, dt: number): void {
    const kmh = Math.round(Math.abs(s.v) * 12);
    // written only when they change: a text write every frame dirties the page's layout for nothing
    const sp = String(speedIn(kmh));
    if (this.speed.textContent !== sp) this.speed.textContent = sp;
    const unit = speedUnit();
    if (this.speedUnit && this.speedUnit.textContent !== unit) this.speedUnit.textContent = unit;
    const st = s.status();
    if (this.grade.textContent !== st) this.grade.textContent = st;
    this.bump.classList.toggle('on', s.blocked > 0);

    // the frame rate is no longer shown up here (4 Nov 2026): kept minute by minute for Settings' chart (game/fpsLog.ts)
    void dt;
    fpsLog.tick();
  }
}
