import { httpUrl, type Online } from './online';
import { pendingInvite, setPendingInvite } from './crew';
import { inviteFrom } from '../../shared/fleets';
import type { CrewCard, OnlineMenu } from '../title/api';

/**
 * What the pause card's Fleet players and the sign-in card ask about shared fleets (docs/sharedfleets.html),
 * answered from the online session. `rejoin` signs out and opens the sign-in card, where signing in again asks
 * about the invite now held.
 */
export function crewMenu(online: Online, rejoin: (why: string) => void, refresh: () => void): Pick<OnlineMenu, 'crew' | 'invite' | 'boot' | 'leaveCrew' | 'joinWith' | 'pendingJoin' | 'canBrand' | 'renames'> {
  const linkOf = (code: string): string => `${httpUrl(online.serverAddress || online.defaultServer())}/join/${code}`;
  // the fleet an invite this browser holds is from, asked of the server once a code
  const names = new Map<string, string | null>();
  const nameOf = (code: string): string | null => {
    if (names.has(code)) return names.get(code) ?? null;
    names.set(code, null);
    const base = httpUrl(online.defaultServer());
    if (base) {
      void fetch(`${base}/api/invite/${code}`, { cache: 'no-store' })
        .then((r) => (r.ok ? r.json() as Promise<{ name?: string }> : null))
        .then((j) => { if (j?.name) { names.set(code, j.name); refresh(); } })
        .catch(() => { /* named once signed in */ });
    }
    return null;
  };
  return {
    crew(): CrewCard | null {
      if (!online.active || online.guest || !online.me) return null;
      const c = online.crew, me = online.me.id;
      const name = online.me.brand?.name ?? online.me.name;
      return {
        shared: c.on, founder: c.founder, name, code: c.code, link: c.code ? linkOf(c.code) : null,
        members: c.members.map((m) => ({ id: m.id, name: m.name, online: m.online || m.id === me, founder: m.id === c.creator, you: m.id === me })),
      };
    },
    async invite() {
      const r = await online.crew.invite(() => online.saveAndWait());
      return 'why' in r ? r : { code: r.code, link: linkOf(r.code) };
    },
    boot: (id) => online.crew.boot(id),
    leaveCrew: () => online.crew.leave(),
    joinWith(text) {
      const code = inviteFrom(text);
      if (!code) return 'That isn’t an invite code or link.';
      if (code === online.crew.code && online.crew.on) return 'That is this fleet’s own invite.';
      setPendingInvite(code);
      rejoin('Sign in again to join the fleet: you’ll be asked to confirm.');
      return null;
    },
    pendingJoin() {
      const code = pendingInvite();
      return code ? { code, name: nameOf(code) } : null;
    },
    canBrand: () => !online.active || online.crew.founder,
    renames: () => (online.active ? online.renames : null),
  };
}
