import * as THREE from 'three';
import { CLASS_LABEL, URGENCY } from './cargoTypes';
import type { CargoItem } from './cargo';
import type { VehicleDef } from './vehicles';

import { money } from '../util/format';
// money lives in util/format.ts; the game's many importers still find it here
export { money };
export const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
const byId = (id: string) => document.getElementById(id)!;

export type FloatKind = 'cash' | 'cpu' | 'info' | 'bad' | 'tax' | 'fine' | 'fleet' | 'rent';

interface Float { el: HTMLElement; pos: THREE.Vector3; t: number; life: number; rise: number }
/**
 * The hold's pointer to a load's destination, the same fat-tailed arrow as the mission tracker's
 * (game/missions/tracker.ts), so which end leads is plain at a glance. It points up and is turned
 * toward the drop-off.
 */
const POINTER = '<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M8 1.2 14.6 8.4H10.6V14.4H5.4V8.4H1.4Z" fill="currentColor" stroke="currentColor" stroke-width="0.8" stroke-linejoin="round"/></svg>';

interface Tag {
  el: HTMLElement; value: HTMLElement; arrow: HTMLElement; seen: boolean; phase: number; w: number; h: number;
  /** Its size for each text it has shown (its own, or a merged one), so swapping between them costs no layout. */
  sizes?: Map<string, [number, number]>;
  /** Off screen: the bubble drawn as one shape, the pill and its tail in a single path; and the path last drawn. */
  shape?: SVGPathElement; svg?: SVGSVGElement; d?: string;
}

/** A drop's place in the suggested order as a circled number (cargo.ts nth, kept here so the two don't import each other). */
const circled = (n: number): string => (n >= 1 && n <= 20 ? String.fromCodePoint(0x245f + n) : `#${n}`);

/** Screen angle (clockwise from up) of the ground direction (dx, dz) for a follow camera at `yaw`. */
function screenAngle(dx: number, dz: number, yaw: number): number {
  const right = dx * Math.cos(yaw) - dz * Math.sin(yaw);
  const ahead = -dx * Math.sin(yaw) - dz * Math.cos(yaw);
  return Math.atan2(right, ahead);
}

/**
 * Everything cargo puts on screen outside the 3D scene: the wallet, the hold gauge beside the
 * speedo, the hover card over goods, the "Space to load" prompt, the I panel, the green bounty
 * tags over destinations (pinned to the screen edge with an arrow when off screen) and the
 * floating "+$" text.
 */
/** Loads listed at once in the cargo list; past this a "more…" link lists the rest. */
const CARGO_SHOWN = 3;

/** A load the hold carries off the books: a night run's contraband (game/smuggling.ts), listed first. */
/** From a train: which way along the line a load goes (+1 ahead, -1 behind, 0 not on this line), how many stops, and the train's forward direction. */
export interface RailNote { way: 1 | -1 | 0; stops: number; fx: number; fz: number }

export interface ExtraRow {
  icon: string; name: string; units: number;
  /** Where it goes, in world tiles, and what it pays there. */
  to: string; x: number; z: number; pay: number;
  /** The line under it: when it is due, or the police on it. */
  note: string; late: boolean;
}

export class CargoHud {
  private cashEl = byId('cash');
  private holdEl = byId('hold');
  private holdFill = this.holdEl.querySelector('i i') as HTMLElement;
  private holdText = this.holdEl.querySelector('span') as HTMLElement;
  private tip = byId('cargo-tip');
  private prompt = byId('cargo-prompt');
  private inv = byId('inventory');
  private layer = byId('cargo-tags');
  private floats: Float[] = [];
  private tags = new Map<number, Tag>();
  private v = new THREE.Vector3();
  private shownCash = -1;
  private holdKey = '';
  private tipKey = '';
  private promptKey = '';
  invOpen = false;
  /** Called when the player confirms abandoning a load. */
  onAbandon: ((id: number) => void) | null = null;
  /** Called when the player throws the night run's contraband out. */
  onDitch: (() => void) | null = null;
  /** A load's card clicked (not its button): show where it is going (main.ts: its destination building's card). */
  onPick: ((id: number) => void) | null = null;
  /**
   * The card under the pointer, by its data-k: the list is redrawn several times a second, and a card
   * drawn new under a still pointer isn't :hover until it moves, so its abandon pill is shown by this.
   */
  private hoverK = '';

  constructor() {
    // The panel is redrawn a few times a second, so a click can land on a button that has just been
    // replaced: act on pointerdown, which fires before any redraw can come between press and release.
    this.inv.addEventListener('pointerdown', (e) => {
      const b = (e.target as HTMLElement).closest('button');
      if (!b) {
        // the card itself: where its load is going (the night run's contraband has no building to show)
        const k = (e.target as HTMLElement).closest<HTMLElement>('li[data-k]')?.dataset.k;
        if (k && /^\d+$/.test(k) && e.button === 0) { e.preventDefault(); e.stopPropagation(); this.onPick?.(Number(k)); }
        return;
      }
      e.preventDefault();
      e.stopPropagation();
      if (b.dataset.more) this.expanded = !this.expanded;
      else if (b.dataset.yes) this.onAbandon?.(Number(b.dataset.yes));
      else if (b.dataset.ditch) this.onDitch?.();
      this.dirty = true;
    });
    const hover = (k: string) => {
      if (k === this.hoverK) return;
      this.hoverK = k;
      this.inv.querySelectorAll<HTMLElement>('li[data-k]').forEach((li) => li.classList.toggle('hov', li.dataset.k === k));
    };
    this.inv.addEventListener('pointermove', (e) => hover((e.target as HTMLElement).closest<HTMLElement>('li[data-k]')?.dataset.k ?? ''));
    this.inv.addEventListener('pointerleave', () => hover(''));
  }
  /** Set when the panel must be redrawn before its next scheduled refresh. */
  dirty = false;

  setCash(n: number, source: 'you' | 'fleet' | 'rent' = 'you'): void {
    if (n === this.shownCash) return;
    this.cashEl.classList.toggle('fleet', source === 'fleet');
    this.cashEl.classList.toggle('rent', source === 'rent');
    this.cashEl.classList.toggle('debt', n < 0);
    const up = this.shownCash >= 0 && n > this.shownCash;
    this.shownCash = n;
    this.cashEl.textContent = money(n);
    if (up) {
      this.cashEl.classList.remove('bump');
      void this.cashEl.offsetWidth; // restart the animation
      this.cashEl.classList.add('bump');
    }
  }

  /** The gauge beside the speedo: grey and "Empty", blue with a count, orange and "Full". */
  setHold(used: number, cap: number): void {
    const key = `${used}/${cap}`;
    if (key === this.holdKey) return;
    this.holdKey = key;
    const state = used === 0 ? 'empty' : used >= cap ? 'full' : 'some';
    this.holdEl.className = `hold ${state}`;
    this.holdFill.style.width = `${Math.round((100 * used) / Math.max(1, cap))}%`;
    this.holdText.textContent = state === 'empty' ? 'Empty' : state === 'full' ? `Full ${used}/${cap}` : `${used}/${cap}`;
    this.holdEl.title = `Cargo hold: ${used} of ${cap} units (I to open)`;
  }

  showTip(key: string, html: string, mx: number, my: number): void {
    if (key !== this.tipKey) { this.tip.innerHTML = html; this.tipKey = key; }
    this.tip.hidden = false;
    const r = this.tip.getBoundingClientRect();
    let x = mx + 18, y = my + 18;
    if (x + r.width > window.innerWidth - 8) x = mx - 18 - r.width;
    if (y + r.height > window.innerHeight - 8) y = my - 18 - r.height;
    this.tip.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px)`;
  }

  hideTip(): void {
    this.tip.hidden = true;
    this.tipKey = '';
  }

  setPrompt(html: string | null): void {
    if (html === null) { this.prompt.hidden = true; this.promptKey = ''; return; }
    if (html !== this.promptKey) { this.prompt.innerHTML = html; this.promptKey = html; }
    this.prompt.hidden = false;
  }

  get inventoryOpen(): boolean { return this.invOpen; }

  /** The whole hold listed, not just the next few drops ("more…" under the list). */
  private expanded = false;

  /**
   * The cargo list is always up while driving (it used to be the I panel): hidden only while a window or
   * a tool has that side of the screen.
   */
  setInventoryShown(on: boolean): void {
    if (on === this.invOpen) return;
    this.invOpen = on;
    this.inv.hidden = !on;
    this.dirty = true;
  }

  /** What the cargo list was last drawn from. */
  private invHtml = '';

  renderInventory(
    def: VehicleDef, hold: CargoItem[], cash: number, delivered: number, from: { x: number; z: number }, yaw: number,
    net: (it: CargoItem) => number = (it) => it.value, fine: (it: CargoItem) => number = () => 0,
    order: Map<number, number> = new Map(),
    /** The hold lent by the vehicles in formation behind you (game/formation.ts). */
    lent: { units: number; names: string[] } = { units: 0, names: [] },
    extra: ExtraRow | null = null,
    /**
     * From a train (game/railWay.ts): a load's way along the line, ahead or behind and how many stops, or off this
     * line altogether, with the train's forward direction (world x, z) for the card's arrow. Null for the rest.
     */
    rail: ((it: CargoItem) => RailNote | null) | null = null,
  ): void {
    if (!this.invOpen) return;
    this.dirty = false;
    const used = hold.reduce((s, it) => s + it.type.units, 0) + (extra?.units ?? 0);
    const cap = def.capacity + lent.units;
    // the next drops first: the suggested order where there is one, then the nearest
    const far = (it: CargoItem) => Math.hypot(it.to.x - from.x, it.to.z - from.z);
    const sorted = [...hold].sort((a, b) => (order.get(a.id) ?? 99) - (order.get(b.id) ?? 99) || far(a) - far(b));
    const hidden = this.expanded ? 0 : Math.max(0, sorted.length - CARGO_SHOWN);
    const shown = hidden ? sorted.slice(0, CARGO_SHOWN) : sorted;
    const more = sorted.length > CARGO_SHOWN
      ? `<button type="button" class="trk-more" data-more="1">${this.expanded ? 'fewer' : `${hidden} more…`}</button>` : '';
    const rows = shown.map((it) => {
      const dx = it.to.x - from.x, dz = it.to.z - from.z;
      const dist = Math.round(Math.hypot(dx, dz));
      const falling = URGENCY[it.urgency].decay > 0;
      const lost = falling && it.value < it.value0 ? ` · ${Math.round((1 - it.value / it.value0) * 100)}% gone` : '';
      const penalty = fine(it);
      // from a train the arrow points along the line, the way to go (forward or back), and a cross off the line
      const rw = rail?.(it) ?? null;
      const arrow = rw && rw.way === 0
        ? '<span class="mt-arrow off" title="Not on this line">✕</span>'
        : rw && rw.way !== 0 && dist > 3
          ? `<span class="mt-arrow" style="transform:rotate(${screenAngle(rw.fx * rw.way, rw.fz * rw.way, yaw).toFixed(2)}rad)">${POINTER}</span>`
          : dist > 3
            ? `<span class="mt-arrow" style="transform:rotate(${screenAngle(dx, dz, yaw).toFixed(2)}rad)">${POINTER}</span>`
            : '<span class="mt-arrow here">●</span>';
      const railLine = rw
        ? rw.way === 0
          ? '<span class="rw off">Not on this line</span>'
          : `<span class="rw ${rw.way > 0 ? 'ahead' : 'behind'}">${rw.stops} stop${rw.stops === 1 ? '' : 's'} ${rw.way > 0 ? 'ahead' : 'behind · reverse'}</span>`
        : '';
      // its place in the suggested drop order, when there is more than one place to go
      const n = order.get(it.id);
      return `<li class="chip trk${this.hoverK === String(it.id) ? ' hov' : ''}" data-k="${it.id}">${arrow}
        <span class="mt-txt"><b>${n ? `<span class="ord" title="Drop ${n} in the suggested order">${n}</span>` : ''}${it.type.icon} ${esc(it.type.name)}</b>→ ${esc(it.to.name)}${railLine ? `<small>${it.longHaul ? '<span class="lh">Long haul</span> · ' : ''}${railLine}</small>` : it.longHaul ? `<small><span class="lh">Long haul · ${it.longHaul.cells} counties</span></small>` : ''}${it.type.ultra ? `<small><span class="ub">Ultra-Bulk · ${it.type.units} units</span></small>` : ''}${falling ? `<small><span class="u u-${it.urgency}">${URGENCY[it.urgency].label}${lost || ' · value falling'}</span></small>` : ''}</span>
        <span class="pay"><span class="mt-d">${dist} t</span><em title="${net(it) < it.value ? 'After tax' : ''}">${money(net(it))}</em></span>
        ${penalty > 0
          ? `<button type="button" class="abandon-pill" data-yes="${it.id}" title="Abandon ${esc(it.type.name)}: you lose the ${money(net(it))} and pay a ${money(penalty)} penalty">Abandon? −${money(penalty)}</button>`
          : `<button type="button" class="abandon-pill" data-yes="${it.id}" title="Set ${esc(it.type.name)} down: it goes back to where it was found, at no cost">Set down</button>`}</li>`;
    }).join('');
    // the night run's contraband first: it is the load the police are looking for
    let night = '';
    if (extra) {
      const dx = extra.x - from.x, dz = extra.z - from.z;
      const dist = Math.round(Math.hypot(dx, dz));
      const arrow = dist > 3
        ? `<span class="mt-arrow" style="transform:rotate(${screenAngle(dx, dz, yaw).toFixed(2)}rad)">${POINTER}</span>`
        : '<span class="mt-arrow here">●</span>';
      night = `<li class="chip trk night${this.hoverK === 'night' ? ' hov' : ''}" data-k="night">${arrow}
        <span class="mt-txt"><b>${extra.icon} ${esc(extra.name)}</b>→ ${esc(extra.to)}<small><span class="${extra.late ? 'late' : ''}">${esc(extra.note)}</span></small></span>
        <span class="pay"><span class="mt-d">${dist} t</span><em>${money(extra.pay)}</em></span>
        <button type="button" class="abandon-pill" data-ditch="1" title="Throw the load out: no pay, no fine">Ditch it</button></li>`;
    }
    const title = `${def.name} · carries ${def.holds.map((c) => CLASS_LABEL[c]).join(', ')} · ${cash < 0 ? 'in debt' : `${delivered} delivered`}`;
    if (this.inv.title !== title) this.inv.title = title;
    // the same list as last time (parked, or nothing aboard) is left as it is: no new nodes, no relayout
    const html = `<div class="trk-h">Cargo (${used}/${cap})${lent.units ? ` · +${lent.units} in formation` : ''}</div>
      <ul>${night}${rows || (night ? '' : '<li class="chip trk none"><span class="mt-arrow here">●</span><span class="mt-txt">Empty. Stop in a glowing ring and press <kbd>Space</kbd> to load.</span></li>')}</ul>${more}`;
    if (html === this.invHtml) return;
    this.invHtml = html;
    this.inv.innerHTML = html;
  }

  /**
   * Bounty tags: green over each destination of what's aboard (pinned to the screen edge with an
   * arrow when off screen), and in the goods' own colour over loads still waiting to be collected.
   */
  /** The UI panels on screen, measured a few times a second: what an edge bubble keeps clear of. */
  private ui: DOMRect[] = [];
  private uiAt = -1e9;
  private uiRects(W: number, H: number): DOMRect[] {
    const now = performance.now();
    if (now - this.uiAt < 250) return this.ui;
    this.uiAt = now;
    const out: DOMRect[] = [];
    // the panels, and the things on the screen that aren't panels: the compass, and the chat's lines, box and hint;
    // and the notifications at the top middle while one is up (each card, the earnings ticker's cards, the
    // bell pill), so a bubble pointing off the top edge is never hidden under one (the user, 15 Oct 2026). A
    // notification that has gone is folded to nothing and faded out, so it is passed over below
    document.querySelectorAll<HTMLElement>('.chip, #dock, #inventory, #build, #compass, #net-chat .hint, #net-chat .form, #net-chat .lines > *, #notices > .notice, #earnings > .notice, #n-pill').forEach((el) => {
      if (el.closest('#cargo-tags') || el.closest('[hidden]')) return;
      if (el.closest('#notices') && (el.classList.contains('out') || Number(getComputedStyle(el).opacity) < 0.1)) return;
      const r = el.getBoundingClientRect();
      // nothing empty, and nothing the size of the screen (a full-screen window has the whole view anyway)
      if (r.width < 4 || r.height < 4 || r.width * r.height > W * H * 0.45) return;
      out.push(r);
    });
    this.ui = out;
    return out;
  }

  /**
   * An off-screen tag's bubble as one shape: the pill and a tapering tail in a single SVG path, filled the
   * one white and shadowed together, so the tail grows out of the outline rather than sitting on it. The
   * tail leaves the outline 16 px wide and comes 10 px clear of it, whichever way it points; a little
   * square corner on a rounded end read as a notch, not a pointer.
   */
  private bubble(tag: Tag, ex: number, ey: number, reach: number): void {
    if (!tag.svg) {
      const ns = 'http://www.w3.org/2000/svg';
      tag.svg = document.createElementNS(ns, 'svg');
      tag.svg.setAttribute('class', 'bub');
      tag.shape = document.createElementNS(ns, 'path');
      tag.svg.append(tag.shape);
      tag.el.prepend(tag.svg);
    }
    // one outline, as a cartoon speech bubble has: the pill's edge walked round, a gap left where the tail
    // comes out, and the tail's two sides curving out of the edge to a point beyond it
    const w = tag.w, h = tag.h, r = h / 2, cx = w / 2, cy = h / 2;
    const f = (n: number) => n.toFixed(1);
    const pts: [number, number][] = [];
    const step = 2;
    for (let x = r; x < w - r; x += step) pts.push([x, 0]);
    for (let a = -Math.PI / 2; a < Math.PI / 2; a += step / r) pts.push([w - r + Math.cos(a) * r, r + Math.sin(a) * r]);
    for (let x = w - r; x > r; x -= step) pts.push([x, h]);
    for (let a = Math.PI / 2; a < Math.PI * 1.5; a += step / r) pts.push([r + Math.cos(a) * r, r + Math.sin(a) * r]);
    // where the line out of the middle crosses the edge, and the stretch of edge either side the tail's root takes
    const exX = cx + ex * reach, exY = cy + ey * reach;
    let at = 0, best = Infinity;
    pts.forEach(([x, y], k) => { const dd = (x - exX) ** 2 + (y - exY) ** 2; if (dd < best) { best = dd; at = k; } });
    const n = pts.length, root = Math.max(3, Math.round(9 / step));
    const i1 = (at - root + n) % n, i2 = (at + root) % n;
    const tipX = cx + ex * (reach + 12), tipY = cy + ey * (reach + 12);
    // the sides bow outward from the edge, so the tail grows out of the bubble rather than sitting on it
    const bow = 5;
    const [ax, ay] = pts[i2], [bx, by] = pts[i1];
    let path = `M${f(ax)},${f(ay)}`;
    for (let k = (i2 + 1) % n; k !== i1; k = (k + 1) % n) path += ` L${f(pts[k][0])},${f(pts[k][1])}`;
    path += ` L${f(bx)},${f(by)}`;
    path += ` Q${f(bx + ex * bow)},${f(by + ey * bow)} ${f(tipX)},${f(tipY)}`;
    path += ` Q${f(ax + ex * bow)},${f(ay + ey * bow)} ${f(ax)},${f(ay)} Z`;
    const d = path;
    if (d === tag.d) return;
    tag.d = d;
    tag.svg.setAttribute('width', String(w));
    tag.svg.setAttribute('height', String(h));
    tag.svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
    tag.shape!.setAttribute('d', d);
  }

  /** Show this text in a tag, its size measured once per text. */
  private setText(tag: Tag, text: string): void {
    if (tag.value.textContent === text && tag.w) return;
    tag.value.textContent = text;
    tag.sizes ??= new Map();
    const had = tag.sizes.get(text);
    if (had) { [tag.w, tag.h] = had; return; }
    tag.w = 0;
    if (tag.el.hidden || !tag.el.classList.contains('edge')) return;
    tag.w = tag.el.offsetWidth; tag.h = tag.el.offsetHeight;
    if (tag.sizes.size > 24) tag.sizes.clear();
    tag.sizes.set(text, [tag.w, tag.h]);
  }

  /**
   * An off-screen tag pinned inside the edge the way `ang` points, its tail pointing out, slid back toward
   * the middle off any panel it would cover. Returns where its middle landed.
   */
  private pin(tag: Tag, ang: number, W: number, H: number): [number, number] {
    const ex = Math.sin(ang), ey = -Math.cos(ang);
    const k = Math.min((W / 2 - 62) / Math.max(1e-3, Math.abs(ex)), (H / 2 - 72) / Math.max(1e-3, Math.abs(ey)));
    tag.el.hidden = false;
    if (!tag.el.classList.contains('edge')) { tag.el.classList.add('edge'); tag.w = 0; }
    if (!tag.w) {
      tag.w = tag.el.offsetWidth; tag.h = tag.el.offsetHeight;
      (tag.sizes ??= new Map()).set(tag.value.textContent ?? '', [tag.w, tag.h]);
    }
    // how far out the bubble's own outline lies in that direction (a pill: a box with round ends), so the
    // tail's square sits half inside it and its corner comes out of the outline as one shape with it
    const r = tag.h / 2, half = Math.max(0, tag.w / 2 - r);
    let reach = 0;
    while (reach < tag.w) {
      const px = ex * reach, py = ey * reach;
      if (Math.hypot(px - Math.max(-half, Math.min(half, px)), py) > r) break;
      reach += 0.5;
    }
    this.bubble(tag, ex, ey, reach);
    // clear of the panels on screen: slid back along the same line toward the middle until it doesn't
    // cover one, so it sits just in front of whatever is on that edge and still points the way
    const ui = this.uiRects(W, H);
    // with room round it for the tail, whichever way that points
    const pad = 16;
    const covers = (cx: number, cy: number) => ui.some((q) =>
      cx + tag.w / 2 + pad > q.left && cx - tag.w / 2 - pad < q.right && cy + tag.h / 2 + pad > q.top && cy - tag.h / 2 - pad < q.bottom);
    let kk = k;
    while (kk > 0 && covers(W / 2 + ex * kk, H / 2 + ey * kk)) kk -= 6;
    const x = Math.round(W / 2 + ex * Math.max(0, kk)), y = Math.round(H / 2 + ey * Math.max(0, kk));
    tag.el.style.transform = `translate(${x}px, ${y}px) translate(-50%, -50%)`;
    return [x, y];
  }

  updateTags(
    list: { key: number; text: string; pos: THREE.Vector3; goods?: boolean; color?: string; dim?: boolean; n?: number; value?: number }[],
    camera: THREE.Camera, yaw: number, from: THREE.Vector3, time: number,
  ): void {
    for (const t of this.tags.values()) t.seen = false;
    const W = window.innerWidth, H = window.innerHeight;
    /** The destinations pinned to the edge this frame, for merging the ones that land on each other. */
    const edge: { tag: Tag; ang: number; x: number; y: number; text: string; n?: number; value?: number }[] = [];
    for (const d of list) {
      let tag = this.tags.get(d.key);
      if (!tag) {
        const el = document.createElement('div');
        el.className = d.goods ? 'gtag' : 'dtag';
        if (d.color) el.style.color = d.color;
        const arrow = document.createElement('i');
        // off screen, the bubble's tail: a square of its own white, turned so a corner points the way
        const value = document.createElement('b');
        el.append(arrow, value);
        this.layer.append(el);
        tag = { el, value, arrow, seen: true, phase: Math.random() * 6, w: 0, h: 0 };
        this.tags.set(d.key, tag);
      }
      tag.seen = true;
      if (tag.el.classList.contains('dim') !== !!d.dim) tag.el.classList.toggle('dim', !!d.dim);
      this.setText(tag, d.text);
      this.v.copy(d.pos).project(camera);
      const sx = ((this.v.x + 1) / 2) * W, sy = ((1 - this.v.y) / 2) * H;
      const bob = Math.sin(time * 2.4 + tag.phase) * 4;
      if (this.v.z < 1 && sx > 40 && sx < W - 40 && sy > 50 && sy < H - 40) {
        tag.el.hidden = false;
        if (tag.el.classList.contains('edge')) { tag.el.classList.remove('edge'); tag.w = 0; }
        tag.el.style.transform = `translate(${Math.round(sx)}px, ${Math.round(sy + bob)}px) translate(-50%, -100%)`;
      } else if (d.goods) {
        tag.el.hidden = true; // waiting goods off screen stay quiet; only destinations point the way
      } else {
        // off screen: a speech bubble pinned inside the edge, its tail pointing the way out
        const ang = screenAngle(d.pos.x - from.x, d.pos.z - from.z, yaw);
        const [x, y] = this.pin(tag, ang, W, H);
        edge.push({ tag, ang, x, y, text: d.text, n: d.n, value: d.value });
      }
    }
    // bubbles that land on each other at the edge become one (the user, 21 Oct 2026): "① + ② $277", pointing
    // the way they point between them, and the others step aside until they come apart again
    if (edge.length > 1) {
      const groups: (typeof edge)[] = [];
      const near = (a: (typeof edge)[number], b: (typeof edge)[number]) =>
        Math.abs(a.x - b.x) < (a.tag.w + b.tag.w) / 2 + 6 && Math.abs(a.y - b.y) < (a.tag.h + b.tag.h) / 2 + 6;
      for (const e of edge) {
        const hit = groups.filter((g) => g.some((o) => near(o, e)));
        if (!hit.length) { groups.push([e]); continue; }
        // it joins every group it touches, and they become one
        const merged = hit.flat().concat(e);
        for (const g of hit) groups.splice(groups.indexOf(g), 1);
        groups.push(merged);
      }
      for (const g of groups) {
        if (g.length < 2) continue;
        g.sort((a, b) => (a.n ?? 99) - (b.n ?? 99));
        const lead = g[0];
        const sum = g.reduce((s, e) => s + (e.value ?? 0), 0);
        const numbered = g.every((e) => e.n);
        const label = numbered ? g.map((e) => circled(e.n!)).join(' + ') : `${g.length} drops`;
        this.setText(lead.tag, sum > 0 ? `${label} ${money(sum)}` : label);
        // between them: the mean of their directions
        const ang = Math.atan2(g.reduce((s, e) => s + Math.sin(e.ang), 0), g.reduce((s, e) => s + Math.cos(e.ang), 0));
        this.pin(lead.tag, ang, W, H);
        for (const e of g.slice(1)) e.tag.el.hidden = true;
      }
    }
    for (const [key, t] of this.tags) {
      if (t.seen) continue;
      t.el.remove();
      this.tags.delete(key);
    }
  }

  clearTags(): void {
    for (const t of this.tags.values()) t.el.remove();
    this.tags.clear();
  }

  /**
   * Text that rises from a point in the world and fades. None on the title or a guest's view: the world behind
   * them runs (rival firms paid at doors) but nothing moves the floats there, which piled up in the top-left
   * corner (the user, 23 Oct 2026).
   */
  float(text: string, pos: THREE.Vector3, kind: FloatKind): void {
    if (document.body.classList.contains('title-mode')) return;
    const el = document.createElement('div');
    el.className = `cfloat ${kind}`;
    el.textContent = text;
    this.layer.append(el);
    const life = kind === 'cash' || kind === 'fine' ? 2.2 : kind === 'cpu' || kind === 'fleet' || kind === 'rent' ? 2 : 1.6;
    // a tax float follows its payment half a second later, rising less far so it sits just beneath
    const t = kind === 'tax' ? -0.5 : 0;
    if (t < 0) el.style.opacity = '0';
    this.floats.push({ el, pos: pos.clone(), t, life, rise: kind === 'cash' || kind === 'fine' ? 90 : kind === 'fleet' || kind === 'rent' ? 70 : kind === 'tax' ? 62 : 50 });
  }

  /** Every float gone at once: leaving play for the title, where nothing would move them on. */
  clearFloats(): void {
    for (const f of this.floats) f.el.remove();
    this.floats.length = 0;
  }

  updateFloats(dt: number, camera: THREE.Camera): void {
    const W = window.innerWidth, H = window.innerHeight;
    for (const f of [...this.floats]) {
      f.t += dt;
      if (f.t < 0) continue;
      const k = f.t / f.life;
      if (k >= 1) { f.el.remove(); this.floats.splice(this.floats.indexOf(f), 1); continue; }
      this.v.copy(f.pos).project(camera);
      if (this.v.z > 1) { f.el.style.opacity = '0'; continue; }
      const ease = 1 - (1 - k) ** 3;
      const pop = k < 0.12 ? 0.6 + (k / 0.12) * 0.5 : k < 0.2 ? 1.1 - ((k - 0.12) / 0.08) * 0.1 : 1;
      f.el.style.opacity = String(k < 0.55 ? 1 : 1 - (k - 0.55) / 0.45);
      f.el.style.transform = `translate(${Math.round(((this.v.x + 1) / 2) * W)}px, ${Math.round(((1 - this.v.y) / 2) * H - ease * f.rise)}px) translate(-50%, -100%) scale(${pop.toFixed(3)})`;
    }
  }
}
