import type { VehicleDef } from '../vehicles';
import type { FactionId } from './factions';

/**
 * Paintjobs (docs/factions.html, "Paintjobs, not colours"): a named look on a vehicle, more than the
 * workshop's two colours — a bonnet in another colour, a cream roof, a chequered band down the sides, the
 * crest on the doors, a word along them, camouflage, and the bolt-ons the workshop doesn't sell (a lightbar,
 * wing flags, a beacon, a dish). The rules are written against the model's measured body, not by hand for
 * each model, so one paintjob goes on anything (render/paintjob.ts). Every faction vehicle on the road wears
 * its faction's; the player wears one once the faction counts them a Friend.
 */

type Bolt =
  | 'lightbar' | 'flags' | 'beacon' | 'amber' | 'ladder' | 'dish' | 'mast' | 'nets' | 'aerial' | 'searchlight'
  | 'whitewalls' | 'camera' | 'plate' | 'redlight' | 'pushbar' | 'crane' | 'rust' | 'gulls'
  // the Passport's Expedition livery (game/passportRewards.ts): a roof rack with a spare, jerrycans on the back, a snorkel
  | 'roofrack' | 'jerrycans' | 'snorkel';

export interface Job {
  id: string;
  name: string;
  /** The body colour (every panel painted in the model's own colour takes it). */
  body: number;
  /** Panels above about two-thirds of the body's height (the roof, a cab's top) take this. */
  upper?: number;
  /** Panels forward of the cabin, low and on top (the bonnet), take this. */
  bonnet?: number;
  /** A band along both sides: one colour, or two that chequer. `at` is its height as a share of the body. */
  band?: { colours: number[]; at: number; h: number };
  /** A thin line along both sides (a pinstripe). */
  pin?: number;
  /** A stripe down the middle over the bonnet and the roof. */
  racing?: number;
  /** The crest on both doors: a glyph on a disc, or (`rose`) a compass rose drawn in fg on bg. */
  roundel?: { glyph: string; bg: number; fg: number; rose?: boolean };
  /** A city's skyline in silhouette along both sides, from the sills up (the Passport's Skyline decals): fg the towers, lit their windows. */
  skyline?: { fg: number; lit: number; at: number; h: number };
  /** A map's contour lines over the lower sides, in this colour (the Expedition livery). */
  contours?: number;
  /** A word along both sides (POLICE, PRESS). */
  word?: { text: string; bg: number; fg: number };
  /** Camouflage patches in these colours over the body. */
  camo?: number[];
  /** Finish: a high gloss, a pearl, or flat. */
  finish?: 'gloss' | 'pearl' | 'matte';
  bolts: Bolt[];
}

const j = (id: string, name: string, spec: Omit<Job, 'id' | 'name'>): Job => ({ id, name, ...spec });

