/** A faction's house paintjob. */
const jobOf = (f: FactionId): Job => JOBS[`job:${f}`];

/** Big vehicles of a faction wear extra kit by kind (a press van a dish, the army's lorries no lightbar). */
const EXTRA: Partial<Record<FactionId, Partial<Record<string, Bolt[]>>>> = {
  press: { mule: ['dish', 'mast'], liveTruck: [], dragonfly: ['camera'], eyeInSky: [] },
  unions: { mule: ['amber', 'ladder'], dump: ['amber'], clod: ['amber'], bulldozer: ['amber'], mixer: ['amber'], bigHook: ['amber'] },
  police: { bramble: ['lightbar'], patrol: ['pushbar'], interceptor: [] },
  ministry: { limo: ['flags', 'plate'] },
  guild: { breeze: ['nets', 'rust', 'gulls'], mule: [] },
  army: { chinook: [], tank: [], deuce: ['aerial'] },
  visitors: { marshmallow: ['redlight'] },
};

/** A model in a faction's house paint: its own definition, so every one of them shares one body. */
export function paintFor(f: FactionId, base: VehicleDef): VehicleDef {
  const job = jobOf(f);
  // the patrol car is already the police's own paint, with its bar
  if (base.id === 'patrol') return base;
  const extra = EXTRA[f]?.[base.id];
  const id = extra ? `${job.id}|${base.id}` : job.id;
  if (extra && !JOBS[id]) JOBS[id] = { ...job, id, bolts: extra.length ? [...new Set([...job.bolts.filter((b) => b !== 'lightbar' && b !== 'ladder'), ...extra])] : [] };
  return { ...base, color: job.body, job: id } as VehicleDef;
}
