import { STEP, World, heightAt, idx, inB, tileAt, waterDepth } from '../world/tiles';
import { FULL_HIT, MIN_HIT, env, reportImpact, type Impact, type WaterDef, type Controls, type VehicleState } from './vehicles';
import { DRIVE_WEATHER } from './car';
import { clamp } from '../util/math';

/** Sounding (docs/underwater.html): slower than this (tiles a second) to go down; seconds down and up; Space held to rise; clearance over the seabed. */
const SOUND_SPEED = 0.35, SOUND_DOWN = 2.6, SOUND_UP = 2.0, RISE_HOLD = 0.4, FLOOR_CLEAR = 0.16;


/** One hull sample point floats: deep enough, and no waterfall between it and the boat. */
function boatPointOk(w: World, def: WaterDef, px: number, pz: number, level: number): boolean {
  const { w: o, i } = tileAt(w, Math.floor(px), Math.floor(pz));
  return o.water[i] >= 0 && waterDepth(o, i) >= def.minDepth && Math.abs(o.water[i] - level) <= 1;
}

/** The whole hull outline fits at this pose. */
export function boatFits(w: World, def: WaterDef, px: number, pz: number, heading: number, level: number): boolean {
  const fx = Math.sin(heading), fz = Math.cos(heading);
  const rx = fz, rz = -fx;
  const L = def.halfLen, W = def.halfWid;
  const pts = [[0, 0], [L, 0], [-L, 0], [L * 0.5, W], [L * 0.5, -W], [-L * 0.5, W], [-L * 0.5, -W]];
  for (const [a, b] of pts) {
    if (!boatPointOk(w, def, px + fx * a + rx * b, pz + fz * a + rz * b, level)) return false;
  }
  return true;
}

/** Tile (tx, tz) can host this boat at any heading, with pad tiles of open water to spare. */
export function boatTileOk(w: World, def: WaterDef, tx: number, tz: number, pad = 0): boolean {
  if (!inB(tx, tz)) return false;
  const level = w.water[idx(tx, tz)];
  if (level < 0) return false;
  const R = Math.ceil(def.halfLen) + pad;
  for (let dz = -R; dz <= R; dz++) {
    for (let dx = -R; dx <= R; dx++) {
      const { w: o, i: j } = tileAt(w, tx + dx, tz + dz);
      if (waterDepth(o, j) < def.minDepth || o.water[j] !== level) return false;
    }
  }
  return true;
}

/** Sail efficiency by angle off the wind (0 = pointing straight into it). */
function sailPolar(offWind: number): number {
  const deg = (offWind * 180) / Math.PI;
  if (deg < 35) return 0.05;
  if (deg < 55) return 0.05 + ((deg - 35) / 20) * 0.75;
  if (deg < 100) return 0.8 + ((deg - 55) / 45) * 0.2;
  if (deg < 140) return 1.0;
  return 1.0 - ((deg - 140) / 40) * 0.3;
}

function pointOfSail(offWind: number): string {
  const deg = (offWind * 180) / Math.PI;
  if (deg < 35) return 'in irons';
  if (deg < 60) return 'close-hauled';
  if (deg < 110) return 'beam reach';
  if (deg < 150) return 'broad reach';
  return 'running';
}

export class BoatState implements VehicleState {
  y: number;
  v = 0;
  vx = 0;
  vz = 0;
  pitch = 0;
  roll = 0;
  bob = 0;
  lean = 0;
  wheelSpin = 0;
  steerVis = 0;
  power = 0;
  blocked = 0;
  impact: Impact | null = null;
  trailerHeading = 0;
  sailAngle = 0;
  surfaceY = NaN;
  level: number;
  private yawRate = 0;
  private t = 0;
  private windEff = 0;
  private windLabel = '';
  /** A submarine's helm: down (Shift) or up (Space). */
  diving = false;
  /** How far under it is, 0 on the surface to 1 at its dived depth. */
  submerged = 0;
  /** It wanted to go down and the water was too shallow. */
  private shoal = 0;
  /**
   * Sounding (docs/underwater.html): dived and stopped, Shift again takes a submarine down to just over the
   * seabed, where goods on the bottom are loaded and set down. It can't be steered while it is down, and Space
   * held (a tap is the load key) brings it back up to its dived depth.
   */
  sounding = false;
  /** How far down to the bottom it has gone, 0 at its dived depth to 1 just over the seabed. */
  sounded = 0;
  /** The seabed's height where it sounded, world units. */
  private floorY = 0;
  /** The helm last frame (a fresh Shift starts a sounding), and how long Space has been held while down. */
  private liftWas = 0;
  private riseHeld = 0;
  /** Over ground too shallow or too steep to go down to. */
  private noBottom = 0;

  constructor(public def: WaterDef, public x: number, public z: number, public heading: number, w: World) {
    const at = tileAt(w, Math.floor(x), Math.floor(z));
    const wl = at.w.water[at.i];
    this.level = wl >= 0 ? wl : 2;
    this.y = this.level * STEP - 0.035;
  }

  step(w: World, c: Controls, dt: number): void {
    const s = this.def;
    this.t += dt;
    const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
    let fwd = this.vx * fx + this.vz * fz;
    let lat = this.vx * fz - this.vz * fx;

    // propulsion
    let capMul = 1, accMul = 1;
    let drive = c.throttle;
    if (s.sail) {
      const wx = Math.sin(env.windHeading), wz = Math.cos(env.windHeading);
      const offWind = Math.acos(clamp(-(fx * wx + fz * wz), -1, 1));
      const eff = sailPolar(offWind);
      this.windEff = eff;
      this.windLabel = pointOfSail(offWind);
      // a biome's wind (the Whitewash's summer, the Moors) fills the sail harder than still air
      const gust = 1 + 0.4 * DRIVE_WEATHER.wind;
      capMul = eff * gust;
      accMul = Math.max(0.1, eff) * gust;
      if (drive === 0) drive = 0.4; // loose sails still draw a little
      // boom swings to leeward; the hull heels away from the wind
      const localWindX = wx * fz - wz * fx;
      const side = Math.sign(localWindX) || 1;
      const out = clamp(offWind * 0.5 - 0.1, 0.12, 1.35);
      const luff = eff < 0.2 ? Math.sin(this.t * 14) * 0.12 : 0;
      this.sailAngle += (-side * out + luff - this.sailAngle) * Math.min(1, dt * 3);
      const heel = -side * eff * 0.2 * Math.min(1, Math.max(0, fwd) / s.topSpeed + 0.2) * Math.max(0, drive);
      this.lean += (heel - this.lean) * Math.min(1, dt * 2);
    }
    let cap = s.topSpeed * capMul * (s.sail ? Math.max(0, drive) : 1);
    // a submarine: Shift takes it down, Space brings it up, and it can only go down where the water is deep
    const dive = s.dive;
    if (dive) {
      const fresh = c.lift < 0 && this.liftWas >= 0;
      if (this.sounding) {
        // down on the bottom: a tap of Space loads (main.ts), only holding it brings the boat up
        this.riseHeld = c.lift > 0 ? this.riseHeld + dt : 0;
        if (this.riseHeld > RISE_HOLD) { this.sounding = false; this.riseHeld = 0; }
      } else if (fresh && this.diving && this.submerged > 0.95) {
        // dived already: a fresh Shift, stopped, goes down to the bottom if there is room for the hull there
        const floor = this.floorUnder(w);
        if (Math.abs(fwd) > SOUND_SPEED) this.noBottom = 2;
        else if (floor !== null) { this.sounding = true; this.floorY = floor; this.riseHeld = 0; }
        else this.noBottom = 2;
      } else if (c.lift < 0) this.diving = true;
      else if (c.lift > 0 && this.sounded < 0.05) this.diving = false;
      this.liftWas = c.lift;
      const here = tileAt(w, Math.floor(this.x), Math.floor(this.z));
      if (this.diving && waterDepth(here.w, here.i) < dive.need) { this.diving = false; this.sounding = false; this.shoal = 2; }
      const want = this.diving ? 1 : 0;
      this.submerged += Math.max(-dt * 0.55, Math.min(dt * 0.45, want - this.submerged));
      this.sounded += this.sounding ? Math.min(dt / SOUND_DOWN, 1 - this.sounded) : -Math.min(dt / SOUND_UP, this.sounded);
      cap *= 1 + (dive.speed - 1) * this.submerged;
      this.shoal = Math.max(0, this.shoal - dt);
      this.noBottom = Math.max(0, this.noBottom - dt);
      // going down or coming up from the bottom, the helm is dead: it holds where it is
      if (this.sounding || this.sounded > 0.02) { drive = 0; cap = 0; }
    }
    // an auxiliary outboard: under power the boat makes its motor speed whatever the wind says
    if (s.sail && s.motor && c.throttle > 0 && cap < s.motor) { cap = s.motor; accMul = Math.max(accMul, 0.8); }
    // a turbo: more speed and a harder shove while it burns
    const boost = c.boost && drive > 0 ? c.boost : 0;
    if (boost) { cap *= 1 + boost; accMul *= 2.2; }
    let a = 0;
    if (drive > 0) {
      a = fwd < cap ? s.accel * accMul : -s.coast;
    } else if (drive < 0) {
      a = fwd > 0.05 ? -s.brake : fwd > -s.reverseCap ? -s.accel * 0.6 : 0;
    } else {
      a = -Math.sign(fwd) * s.coast;
      if (Math.abs(fwd) < s.coast * dt) { a = 0; fwd = 0; }
    }
    const before = fwd;
    fwd += a * dt;
    if (a > 0 && before <= cap && fwd > cap) fwd = cap;
    if (fwd < -s.reverseCap) fwd = -s.reverseCap;
    lat *= Math.exp(-s.grip * dt);
    this.v = fwd;

    // rudder (dead while a submarine is down on the bottom)
    const steer = this.sounding || this.sounded > 0.02 ? 0 : c.steer;
    if (steer !== c.steer) { fwd *= Math.exp(-4 * dt); lat *= Math.exp(-4 * dt); }
    const authority = Math.min(1, 0.3 + Math.abs(fwd) / s.turnRef);
    const targetYaw = s.steerRate * steer * authority * (fwd < -0.05 ? -1 : 1);
    this.yawRate += (targetYaw - this.yawRate) * Math.min(1, dt / s.yawLag);
    this.steerVis += (steer * 0.5 - this.steerVis) * Math.min(1, dt * 6);

    // world velocity on the current heading; turning afterwards leaves some sideways drift
    this.vx = fx * fwd + fz * lat;
    this.vz = fz * fwd - fx * lat;

    const fitsNow = boatFits(w, s, this.x, this.z, this.heading, this.level);
    const ok = (px: number, pz: number, h: number) =>
      fitsNow ? boatFits(w, s, px, pz, h, this.level) : boatPointOk(w, s, px, pz, this.level);

    const nh = this.heading + this.yawRate * dt;
    if (ok(this.x, this.z, nh)) this.heading = nh;
    else this.yawRate *= -0.3;

    // running aground: a soft knock, as hard as the speed into the shore
    const vx0 = this.vx, vz0 = this.vz;
    let hitX = false, hitZ = false;
    const nx = this.x + this.vx * dt;
    if (ok(nx, this.z, this.heading)) this.x = nx; else { this.vx *= -0.2; hitX = true; }
    const nz = this.z + this.vz * dt;
    if (ok(this.x, nz, this.heading)) this.z = nz; else { this.vz *= -0.2; hitZ = true; }
    if (hitX || hitZ) {
      const into = Math.hypot(hitX ? vx0 : 0, hitZ ? vz0 : 0);
      if (this.blocked <= 0 && into > MIN_HIT) {
        const nxn = hitX ? -Math.sign(vx0) : 0, nzn = hitZ ? -Math.sign(vz0) : 0, l = Math.hypot(nxn, nzn) || 1;
        reportImpact(this, { kind: 'soft', strength: Math.min(1, into / FULL_HIT), nx: nxn / l, nz: nzn / l, px: this.x - (nxn / l) * s.halfLen, pz: this.z - (nzn / l) * s.halfLen });
      }
      this.blocked = 0.25;
    }
    this.blocked = Math.max(0, this.blocked - dt);

    // float on the local surface
    const here = tileAt(w, Math.floor(this.x), Math.floor(this.z));
    if (here.w.water[here.i] >= 0) this.level = here.w.water[here.i];
    const surf = this.level * STEP - 0.035;
    const under = dive ? dive.depth * this.submerged : 0;
    // sounding: eased from its dived depth down to just over the seabed
    const e = this.sounded * this.sounded * (3 - 2 * this.sounded);
    const target = surf - under + (this.floorY + FLOOR_CLEAR - (surf - under)) * e;
    this.y += (target - this.y) * Math.min(1, dt * 4);
    // dived, nothing breaks the surface but the sail: no wake to speak of
    this.surfaceY = Math.abs(fwd) > 0.4 && this.submerged < 0.6 ? surf : NaN;

    const speedFrac = clamp(fwd / s.topSpeed, -1, 1);
    const calm = 1 - this.submerged * 0.85;
    this.bob = Math.sin(this.t * 1.8 + this.x * 0.7) * s.wave * calm;
    // going down the bow dips, coming up it lifts
    const trim = dive ? ((this.diving ? 1 : 0) - this.submerged) * 0.22 * (this.diving ? 1 : 0.8) : 0;
    const targetPitch = (Math.sin(this.t * 1.3 + this.z * 0.5) * s.wave * 1.5 - s.planing * Math.max(0, speedFrac)) * calm + trim;
    const targetRoll = Math.sin(this.t * 1.1 + 2) * s.wave * 2 - this.yawRate * Math.abs(speedFrac) * (s.planing > 0 ? 0.15 : 0.03);
    const k = Math.min(1, dt * 4);
    this.pitch += (targetPitch - this.pitch) * k;
    this.roll += (targetRoll - this.roll) * k;

    this.power = Math.min(1, 0.2 + Math.abs(fwd) / s.topSpeed + Math.abs(c.throttle) * 0.3);
  }

  /** On the bottom (docs/underwater.html): what a seabed load's ring asks for. */
  get onBottom(): boolean { return this.sounding && this.sounded > 0.97; }

  /**
   * The seabed under the hull, if a submarine can go down to it here: the highest of the ground under its bow,
   * middle and stern, in water at least its dive.need deep all along. Null over a bank or a slope too steep.
   */
  private floorUnder(w: World): number | null {
    const s = this.def, need = s.dive?.need ?? 0;
    const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
    let top = -Infinity, low = Infinity;
    for (const k of [-1, 0, 1]) {
      const px = this.x + fx * s.halfLen * k, pz = this.z + fz * s.halfLen * k;
      const here = tileAt(w, Math.floor(px), Math.floor(pz));
      if (waterDepth(here.w, here.i) < need) return null;
      const g = heightAt(w, px, pz);
      top = Math.max(top, g); low = Math.min(low, g);
    }
    return top - low > STEP * 2 ? null : top;
  }

  status(): string {
    if (this.blocked > 0) return '⚠ too shallow';
    if (this.def.dive) {
      if (this.sounding) return this.sounded > 0.97 ? '⚓ on the bottom · hold Space to rise' : '🫧 going down…';
      if (this.sounded > 0.03) return '🫧 rising from the bottom…';
      if (this.noBottom > 0) return Math.abs(this.v) > SOUND_SPEED ? '⚠ stop to go down to the bottom' : '⚠ no room to go down here';
      if (this.shoal > 0) return '⚠ too shallow to dive';
      if (this.diving) return this.submerged > 0.97 ? '🫧 dived · Shift stopped to go to the bottom · Space to surface' : '🫧 diving…';
      if (this.submerged > 0.03) return '🫧 surfacing…';
    }
    if (this.def.sail) return `⛵ ${this.windLabel} · ${Math.round(this.windEff * 100)}% wind`;
    if (Math.abs(this.v) < 0.2) return '⚓ idling';
    if (this.def.planing > 0 && this.v / this.def.topSpeed > 0.6) return '≈ planing';
    return '≈ cruising';
  }
}
