import * as THREE from 'three';
import { N, type World } from '../../world/tiles';
import { KIND_OF } from './kinds';
import type { Happening } from './calendar';
import { mid, type MarketSite, type Place, type Pt } from './venues';
import { Bulbs, Crowd, Rig, dressed, flat } from './props';
import { Show, clamp01, u01, type ShowCtx } from './shows';

/**
 * The markets (0.7.0, NEXT_WORLD; docs/events.html "Markets"): a farmers' market every Saturday morning but in
 * winter, a Christmas market all through every winter's day, each in the towns that keep one. They take over a
 * street, a crossroads or a square: the stage (stage.ts) shuts the road there from setting up to packing away, and
 * here are the stalls going up one by one, the shoppers along the aisle, the barriers and "Road closed" signs at
 * each way in. Like every show, worked out from the clock alone.
 */

/** A market's middle, in its county's frame: its square, its crossroads, or halfway along its street. */
export function marketMid(m: MarketSite): Pt {
  if (m.lot) return mid(m.lot);
  const L = m.lines[0];
  if (!L?.length) { const t = m.tiles[0] ?? 0; return { x: (t % N) + 0.5, z: Math.floor(t / N) + 0.5 }; }
  return m.kind === 'junction' ? L[0] : L[Math.floor(L.length / 2)];
}

/** Many little boxes in one draw: a market's stalls, huts and barriers, shown the first `count` of them. */
class Boxes {
  readonly mesh: THREE.InstancedMesh;
  private n = 0;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private e = new THREE.Euler();
  private p = new THREE.Vector3();
  private s = new THREE.Vector3();
  private c = new THREE.Color();
  constructor(parent: THREE.Object3D, max: number) {
    this.mesh = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.75, flatShading: true }), Math.max(1, max));
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = true;
    this.mesh.frustumCulled = false;
    this.mesh.count = 0;
    parent.add(this.mesh);
  }
  get size(): number { return this.n; }
  /** A box standing on y (world units) at (x, z), `w` across and `d` along `yaw`, tipped `tilt` about its length. Its index. */
  add(x: number, y: number, z: number, w: number, h: number, d: number, colour: number, yaw = 0, tilt = 0): number {
    if (this.n >= this.mesh.instanceMatrix.count) return -1;
    this.q.setFromEuler(this.e.set(0, yaw, tilt, 'YZX'));
    this.m.compose(this.p.set(x, y + h / 2, z), this.q, this.s.set(w, h, d));
    this.mesh.setMatrixAt(this.n, this.m);
    this.mesh.setColorAt(this.n, this.c.setHex(colour));
    return this.n++;
  }
  recolour(i: number, colour: number): void { this.mesh.setColorAt(i, this.c.setHex(colour)); if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true; }
  show(n: number): void {
    const k = Math.max(0, Math.min(this.n, n));
    if (k === this.mesh.count) return;
    this.mesh.count = k;
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }
}

/** The "Road closed" board, drawn once. */
let SIGN: THREE.CanvasTexture | null = null;
function signTexture(): THREE.CanvasTexture {
  if (SIGN) return SIGN;
  const c = document.createElement('canvas');
  c.width = 256; c.height = 128;
  const g = c.getContext('2d')!;
  g.fillStyle = '#f8f6ee'; g.fillRect(0, 0, 256, 128);
  g.strokeStyle = '#c8102e'; g.lineWidth = 14; g.strokeRect(7, 7, 242, 114);
  g.fillStyle = '#1d1d1f'; g.textAlign = 'center'; g.textBaseline = 'middle';
  g.font = 'bold 44px system-ui, sans-serif';
  g.fillText('ROAD', 128, 46); g.fillText('CLOSED', 128, 88);
  SIGN = new THREE.CanvasTexture(c);
  SIGN.colorSpace = THREE.SRGBColorSpace;
  SIGN.anisotropy = 4;
  return SIGN;
}

/** A spot for a stall or a hut: where it stands (world tiles), along `yaw`, its front `u` turned to the aisle. */
interface Slot { x: number; z: number; yaw: number; ux: number; uz: number; tile: number }

/** Spots along the market's ways: both kerbs of every shut tile, two a side, a side street's mouth left open. */
function streetSlots(w: World, m: MarketSite, keep: Set<number>): Slot[] {
  const out: Slot[] = [];
  for (const L of m.lines) {
    for (let k = 0; k < L.length; k++) {
      if (m.kind === 'junction' && k === 0) continue;
      const a = L[Math.max(0, k - 1)], b = L[Math.min(L.length - 1, k + 1)];
      let dx = b.x - a.x, dz = b.z - a.z;
      const d = Math.hypot(dx, dz) || 1;
      dx /= d; dz /= d;
      const P = L[k], tile = Math.floor(P.x) + Math.floor(P.z) * N;
      if (keep.has(tile)) continue;
      for (const side of [1, -1]) {
        const nx = -dz * side, nz = dx * side;
        const ox = Math.floor(P.x + nx * 0.9), oz = Math.floor(P.z + nz * 0.9);
        if (ox >= 0 && oz >= 0 && ox < N && oz < N && w.road[ox + oz * N]) continue;
        for (const along of [-0.25, 0.25]) out.push({ x: w.ox + P.x + nx * 0.3 + dx * along, z: w.oz + P.z + nz * 0.3 + dz * along, yaw: Math.atan2(dx, dz), ux: -nx, uz: -nz, tile });
      }
    }
  }
  // two ways through one tile (a square's corner): one stall to a spot
  const kept: Slot[] = [];
  for (const s of out) if (!kept.some((q) => Math.hypot(q.x - s.x, q.z - s.z) < 0.32)) kept.push(s);
  return kept;
}

/** Spots round the inside of a square, facing in, clear of what stands in its middle (`clear`: point and radius). */
function lotSlots(w: World, lot: NonNullable<MarketSite['lot']>, clear: (Pt & { r: number })[]): Slot[] {
  const out: Slot[] = [];
  const x0 = w.ox + lot.x, z0 = w.oz + lot.z, x1 = x0 + lot.w, z1 = z0 + lot.d;
  const edge = (ax: number, az: number, bx: number, bz: number, ux: number, uz: number) => {
    const L = Math.hypot(bx - ax, bz - az), n = Math.floor((L - 0.5) / 0.48);
    for (let k = 0; k < n; k++) {
      const t = (0.25 + 0.24 + k * 0.48) / L;
      const x = ax + (bx - ax) * t + ux * 0.32, z = az + (bz - az) * t + uz * 0.32;
      if (clear.some((c) => Math.hypot(c.x - x, c.z - z) < c.r)) continue;
      out.push({ x, z, yaw: Math.atan2(bx - ax, bz - az), ux, uz, tile: -1 });
    }
  };
  edge(x0, z0, x1, z0, 0, 1); edge(x0, z1, x1, z1, 0, -1);
  edge(x0, z0 + 0.5, x0, z1 - 0.5, 1, 0); edge(x1, z0 + 0.5, x1, z1 - 0.5, -1, 0);
  return out;
}

/** The ways a shopper walks: the market's aisles, and a ring round a square's middle. */
interface Walk { pts: Pt[]; at: number[]; len: number }
function walkOf(pts: Pt[]): Walk {
  const at = [0];
  for (let k = 1; k < pts.length; k++) at.push(at[k - 1] + Math.hypot(pts[k].x - pts[k - 1].x, pts[k].z - pts[k - 1].z));
  return { pts, at, len: at[at.length - 1] };
}
function along(w: Walk, s: number): Pt & { hx: number; hz: number } {
  let k = 1;
  while (k < w.pts.length - 1 && w.at[k] < s) k++;
  const a = w.pts[k - 1], b = w.pts[k], seg = (w.at[k] - w.at[k - 1]) || 1, t = clamp01((s - w.at[k - 1]) / seg);
  return { x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t, hx: (b.x - a.x) / seg, hz: (b.z - a.z) / seg };
}

const COLD = new Set<string>(['icefield', 'fjords', 'heights', 'bigtimber', 'moors']);
const STRIPES = [0xc8102e, 0x2f7a3a, 0x1f4e9e, 0xe86a17, 0x6a2c91, 0x2bb3a3];
/** What a farmers' stall sells, in the colours of its crates. */
const WARES: number[][] = [
  [0xef8a1a, 0x3f9b4a, 0xc0392b], // vegetables: carrots, greens, tomatoes
  [0xe2412f, 0xf2c14e, 0x8bc34a], // fruit
  [0xf49ab5, 0x8e5cc7, 0xf2d64e], // flowers
  [0xd9a35f, 0xb5803f, 0xe3c48a], // bread
  [0xf2c14e, 0xf5e3a1, 0xe0a83a], // cheese
  [0x6b3a8a, 0xc0392b, 0x2a5a2a], // jams and pickles
];
const CLOTHS = [0xf4f2ec, 0xe9e2cf, 0xd4e6d0, 0xf0d9d9];
const WOODS = [0x8a5a34, 0x7a4a2a, 0x9c6b3e, 0x6e4426];
const AWNINGS = [0xc8102e, 0x2f7a3a, 0xf4f2ec, 0xc8102e];
const ROOFS = [0x5a3a22, 0x8a3324, 0x3e5a3a];
const SNOW = 0xf2f5fa;
const WARM = [0xffd27a, 0xffb347, 0xfff1c9, 0xff8c5a];
const BAGS = [0xc9a26b, 0xf4f2ec, 0x3f9b4a, 0x8a5a34];
/** The farms' pickups behind the stalls. */
const FARM_TRUCKS = [0x2f7a3a, 0xc8102e, 0x1f4e9e, 0xe9e2cf];

/**
 * What both markets share: the stalls in order from the middle out (setting up shows them one by one, packing away
 * takes them down in turn), the barriers and signs at each way in, the shoppers on the aisles with their bags.
 */
abstract class MarketShow extends Show {
  protected m: MarketSite;
  protected stalls: Boxes;
  /** Boxes in `stalls` after each stall, to show the first k. */
  protected marks: number[] = [];
  protected fences: Boxes;
  private signs: THREE.InstancedMesh;
  protected crowd: Crowd;
  private bags: THREE.InstancedMesh;
  private walks: Walk[] = [];
  /** How many of the crowd stand at a stall (first in the crowd), and where. */
  protected holders: Pt[] = [];
  private shoppers = 0;
  protected rigs: { rig: Rig; x: number; z: number; h: number }[] = [];
  private placed = false;
  protected c: Pt;
  private t = 0;
  private bm = new THREE.Matrix4();

  constructor(e: Happening, ctx: ShowCtx, protected w: World, protected place: Place, shoppers: number) {
    super(e, ctx);
    const spec = KIND_OF[e.kind];
    this.until = e.end + (spec.pack ?? 0.5) + 0.3;
    this.m = place.market!;
    this.c = { x: w.ox + marketMid(this.m).x, z: w.oz + marketMid(this.m).z };
    this.stalls = new Boxes(this.g, 600);
    this.fences = new Boxes(this.g, this.m.ends.length * 7);
    this.signs = new THREE.InstancedMesh(new THREE.PlaneGeometry(0.3, 0.15), new THREE.MeshStandardMaterial({ map: signTexture(), roughness: 0.6, side: THREE.DoubleSide }), Math.max(1, this.m.ends.length));
    this.signs.frustumCulled = false;
    this.g.add(this.signs);
    this.barriers();
    // the shoppers' ways: each aisle, in world tiles
    for (const L of this.m.lines) if (L.length >= 2) this.walks.push(walkOf(L.map((p) => ({ x: w.ox + p.x, z: w.oz + p.z }))));
    if (this.m.lot) {
      const lot = this.m.lot, r = Math.max(0.5, Math.min(lot.w, lot.d) / 2 - 0.75), cx = w.ox + lot.x + lot.w / 2, cz = w.oz + lot.z + lot.d / 2;
      const ring = Array.from({ length: 17 }, (_, k) => ({ x: cx + Math.cos((k / 16) * Math.PI * 2) * r * (lot.w / Math.min(lot.w, lot.d)), z: cz + Math.sin((k / 16) * Math.PI * 2) * r * (lot.d / Math.min(lot.w, lot.d)) }));
      this.walks.push(walkOf(ring), walkOf(ring));
    }
    this.shoppers = this.walks.length ? shoppers : 0;
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    this.crowd.manual = true;
    this.bags = new THREE.InstancedMesh(new THREE.BoxGeometry(0.035, 0.04, 0.02), new THREE.MeshStandardMaterial({ roughness: 0.8 }), Math.max(1, shoppers));
    this.bags.frustumCulled = false;
    this.bags.count = 0;
    const col = new THREE.Color();
    for (let i = 0; i < shoppers; i++) this.bags.setColorAt(i, col.setHex(BAGS[i % BAGS.length]));
    this.g.add(this.bags);
  }

  centre(): Pt | null { return this.c; }

  /** A striped barrier across the road at each way in, a "Road closed" board on a post beside it, facing out. */
  private barriers(): void {
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler(), p = new THREE.Vector3(), one = new THREE.Vector3(1, 1, 1);
    this.m.ends.forEach((end, i) => {
      const x = this.w.ox + end.x, z = this.w.oz + end.z, y = this.ctx.ground(x, z);
      const yaw = Math.atan2(end.dx, end.dz), ax = Math.cos(yaw), az = -Math.sin(yaw);
      for (let s = 0; s < 4; s++) { const o = -0.3 + s * 0.2; this.fences.add(x + ax * o, y + 0.12, z + az * o, 0.2, 0.05, 0.025, s % 2 ? 0xf4f2ec : 0xc8102e, yaw); }
      for (const o of [-0.36, 0.36]) this.fences.add(x + ax * o, y, z + az * o, 0.02, 0.17, 0.09, 0x3a3f45, yaw);
      const sx = x + ax * 0.44, sz = z + az * 0.44;
      this.fences.add(sx, y, sz, 0.018, 0.3, 0.018, 0x9aa0a6, yaw);
      m.compose(p.set(sx + end.dx * 0.012, y + 0.36, sz + end.dz * 0.012), q.setFromEuler(e.set(0, yaw, 0)), one);
      this.signs.setMatrixAt(i, m);
    });
    this.signs.count = this.m.ends.length;
    this.fences.show(this.fences.size);
  }

  /** End of a stall: the first k stalls show. */
  protected mark(): void { this.marks.push(this.stalls.size); }

  /** Set out once: the vehicles parked. */
  private setOut(): void {
    this.placed = true;
    for (const r of this.rigs) r.rig.place(this.ctx.worldAt, r.x, r.z, r.h, 0, 0);
  }

  /** How much of it stands, 0..1, and how busy it is with shoppers. */
  protected update0(now: number, dt: number): { on: boolean; built: number; busy: number } {
    const e = this.e, spec = KIND_OF[e.kind], lead = spec.lead || 1, pack = spec.pack ?? 0.5;
    const on = now >= e.start - lead && now < e.end + pack;
    this.g.visible = on;
    if (!on) { for (const r of this.rigs) r.rig.hide(); return { on, built: 0, busy: 0 }; }
    if (!this.placed) this.setOut();
    for (const r of this.rigs) if (!r.rig.shown) r.rig.mesh.holder.visible = r.rig.shown = true;
    const built = now < e.start ? clamp01((now - (e.start - lead)) / (lead * 0.85)) : now > e.end ? 1 - clamp01((now - e.end) / (pack * 0.85)) : 1;
    const k = Math.ceil(built * this.marks.length);
    this.stalls.show(k ? this.marks[k - 1] : 0);
    const busy = clamp01((now - e.start) / 0.5) * (1 - clamp01((now - (e.end - 0.4)) / 0.4));
    this.people(dt, built, busy);
    return { on, built, busy };
  }

  /** The stallholders at their stalls while any stand, the shoppers walking the aisles, a bag in most hands. */
  private people(dt: number, built: number, busy: number): void {
    this.t += dt;
    const H = this.holders.length, cr = this.crowd;
    while (cr.size < Math.min(64, H + this.shoppers)) cr.add(this.c.x, this.c.z);
    const holders = Math.min(H, Math.ceil(built * H));
    for (let i = 0; i < Math.min(H, cr.size); i++) cr.setAt(i, this.holders[i].x, this.holders[i].z, 0);
    const n = Math.min(cr.size - H, Math.round(this.shoppers * busy));
    let b = 0;
    for (let j = 0; j < n; j++) {
      const wk = this.walks[j % this.walks.length];
      const sp = 0.07 + u01(this.e.h, j * 7) * 0.06, ph = u01(this.e.h, j * 7 + 1) * wk.len * 2;
      // to and fro along the aisle, a pause now and then at a stall
      let s = (ph + this.t * sp) % (wk.len * 2);
      s = s > wk.len ? wk.len * 2 - s : s;
      const stop = Math.sin(this.t * 0.7 + j * 1.9);
      if (stop > 0.6) s -= (stop - 0.6) * 0.25;
      const p = along(wk, Math.max(0, Math.min(wk.len, s)));
      const off = (u01(this.e.h, j * 7 + 2) - 0.5) * 0.18;
      const x = p.x - p.hz * off, z = p.z + p.hx * off;
      cr.setAt(H + j, x, z, stop > 0.6 ? 0 : dt);
      if (j % 3 !== 2 && b < this.bags.instanceMatrix.count) {
        this.bm.makeTranslation(x + p.hz * 0.05, this.ctx.ground(x, z) + 0.035, z - p.hx * 0.05);
        this.bags.setMatrixAt(b++, this.bm);
      }
    }
    this.bags.count = b;
    if (b) this.bags.instanceMatrix.needsUpdate = true;
    cr.shown = holders === H ? H + n : holders;
    cr.update(dt);
  }

  dispose(): void {
    for (const r of this.rigs) r.rig.dispose();
    this.crowd.dispose();
    super.dispose();
  }
}

// ---- the farmers' market ---------------------------------------------------------------------------------------

/**
 * A Saturday morning's farmers' market: canopy stalls down the shut street (or round the square, or out along the
 * crossroads' arms) with crates of vegetables, fruit, flowers, bread and cheese, a stallholder at each, a coffee
 * truck in the middle, the farms' pickups parked at the ends behind the last stalls, and shoppers with their bags.
 */
export class FarmersMarketShow extends MarketShow {
  constructor(e: Happening, ctx: ShowCtx, w: World, place: Place) {
    super(e, ctx, w, place, 40);
    const m = this.m, keep = new Set<number>();
    const mc = marketMid(m), midTile = Math.floor(mc.x) + Math.floor(mc.z) * N;
    // the coffee truck: in the crossroads, halfway down the street, or on the square by one of its long sides (its
    // middle may hold a fountain or a statue)
    let coffee: Pt & { h: number };
    if (m.lot) {
      const lot = m.lot, wide = lot.w >= lot.d;
      coffee = { x: w.ox + lot.x + (wide ? lot.w / 2 : 0.75), z: w.oz + lot.z + (wide ? 0.75 : lot.d / 2), h: wide ? Math.PI / 2 : 0 };
    } else {
      keep.add(midTile);
      const L = m.lines[0], k = m.kind === 'junction' ? 0 : Math.floor(L.length / 2);
      const a = L[Math.max(0, k - 1)], b = L[Math.min(L.length - 1, k + 1)];
      coffee = { x: w.ox + mc.x, z: w.oz + mc.z, h: Math.atan2(b.x - a.x, b.z - a.z) };
    }
    this.rigs.push({ rig: new Rig(this.g, dressed('sundae', 0x6b4a32, 0xf4f2ec)), ...coffee });
    // the farms' pickups: in from up to three of the ways in, nose out, tailgate to the stalls
    m.ends.slice(0, 3).forEach((end, i) => {
      const tx = Math.floor(end.x), tz = Math.floor(end.z), tile = tx + tz * N;
      if (keep.has(tile) || tile === midTile) return;
      keep.add(tile);
      this.rigs.push({ rig: new Rig(this.g, dressed('mule', FARM_TRUCKS[(e.h + i) % FARM_TRUCKS.length])), x: w.ox + tx + 0.5, z: w.oz + tz + 0.5, h: Math.atan2(end.dx, end.dz) });
    });
    let slots = streetSlots(w, m, keep);
    if (m.lot) slots.push(...lotSlots(w, m.lot, [{ x: coffee.x, z: coffee.z, r: 0.95 }]));
    slots = slots.sort((a, b) => Math.hypot(a.x - this.c.x, a.z - this.c.z) - Math.hypot(b.x - this.c.x, b.z - this.c.z)).slice(0, 44);
    slots.forEach((s, i) => this.stall(s, i));
  }

  /** A trestle under a striped canopy, three crates of its wares, its stallholder behind. */
  private stall(s: Slot, i: number): void {
    const B = this.stalls, h = this.e.h, ax = Math.sin(s.yaw), az = Math.cos(s.yaw);
    const at = (du: number, da: number): [number, number] => [s.x + s.ux * du + ax * da, s.z + s.uz * du + az * da];
    const [x0, z0] = at(0, 0), y = this.ctx.ground(x0, z0);
    const wares = WARES[Math.floor(u01(h, i * 5) * WARES.length)], stripe = STRIPES[Math.floor(u01(h, i * 5 + 1) * STRIPES.length)];
    B.add(x0, y, z0, 0.2, 0.12, 0.36, CLOTHS[i % CLOTHS.length], s.yaw);
    [-0.12, 0, 0.12].forEach((da, k) => { const [x, z] = at(0.03, da); B.add(x, y + 0.12, z, 0.1, wares === WARES[2] ? 0.06 : 0.035, 0.1, wares[k], s.yaw); });
    for (const [du, da] of [[-0.11, -0.19], [-0.11, 0.19], [0.11, -0.19], [0.11, 0.19]]) { const [x, z] = at(du, da); B.add(x, y, z, 0.012, du < 0 ? 0.36 : 0.32, 0.012, 0xdddddd, s.yaw); }
    [-0.14, 0, 0.14].forEach((da, k) => { const [x, z] = at(0, da); B.add(x, y + 0.33, z, 0.28, 0.012, 0.14, k % 2 ? 0xf8f6ee : stripe, s.yaw, 0.14 * Math.sign(s.ux * Math.cos(s.yaw) - s.uz * Math.sin(s.yaw) || 1)); });
    this.mark();
    if (i % 2 === 0 && this.holders.length < 22) { const [x, z] = at(-0.17, 0); this.holders.push({ x, z }); }
  }

  update(now: number, dt: number): void {
    const { on } = this.update0(now, dt);
    if (!on) return;
    // a cup's steam off the coffee truck
    const c = this.rigs[0];
    if (c && Math.random() < dt * 2) this.ctx.particles.puff({ x: c.x, y: c.rig.state.y + 0.45, z: c.z, vx: 0, vy: 0.12, vz: 0, life: 2.2, colour: 0xf2f2f2, size: 0.14, alpha: 0.28, drag: 0.5 });
  }
}

// ---- the Christmas market ---------------------------------------------------------------------------------------

/**
 * A winter's Christmas market: wooden huts with lit garlands round a great lit tree in the main square and down the
 * streets off it, a carousel in a city's (a big wheel in a metropolis's), steam off the mulled-wine huts, lanterns
 * strung across the way after dark, and white roofs where it's cold.
 */
export class ChristmasMarketShow extends MarketShow {
  private roofs: number[] = [];
  private snowy = false;
  private garland: Bulbs;
  private strings: Bulbs;
  private treeBulbs: Bulbs;
  private eaves: (Pt & { y: number })[] = [];
  private lanterns: (Pt & { y: number })[] = [];
  private steam: (Pt & { y: number })[] = [];
  private tree: Pt & { y: number; s: number };
  private ride: { g: THREE.Group; spin: THREE.Object3D; kind: 'carousel' | 'wheel'; cabins: THREE.Object3D[]; r: number } | null = null;
  private rideBulbs: Bulbs | null = null;

  constructor(e: Happening, ctx: ShowCtx, w: World, place: Place) {
    super(e, ctx, w, place, 52);
    const m = this.m, keep = new Set<number>(), t = place.town!;
    const mc = marketMid(m);
    // the tree: in the square (off to one side if a ride shares it), in the crossroads, or halfway down the street
    let tree: Pt = { x: w.ox + mc.x, z: w.oz + mc.z };
    let rideAt: Pt | null = null, rideR = 0;
    const rank = ({ rural: 0, suburb: 1, city: 2, metro: 3, mega: 4 } as Record<string, number>)[t.kind] ?? 0;
    if (m.lot) {
      const lot = m.lot, long = Math.max(lot.w, lot.d), ux = lot.w >= lot.d ? 1 : 0, uz = 1 - ux;
      if (rank >= 2 && long >= 4) {
        rideR = rank >= 3 ? Math.min(1.05, Math.min(lot.w, lot.d) * 0.42, long / 4) : Math.min(0.55, long / 5);
        rideAt = { x: tree.x + ux * long / 4, z: tree.z + uz * long / 4 };
        tree = { x: tree.x - ux * long / 4, z: tree.z - uz * long / 4 };
      }
    } else keep.add(Math.floor(mc.x) + Math.floor(mc.z) * N);
    const scale = m.lot ? 0.85 : 0.65;
    this.tree = { ...tree, y: ctx.ground(tree.x, tree.z), s: scale };
    this.snowy = this.cold();
    this.buildTree();
    let slots = streetSlots(w, m, keep);
    if (m.lot) slots.push(...lotSlots(w, m.lot, [{ ...tree, r: 0.9 * scale + 0.2 }, ...(rideAt ? [{ ...rideAt, r: rideR + 0.4 }] : [])]));
    slots = slots.sort((a, b) => Math.hypot(a.x - this.c.x, a.z - this.c.z) - Math.hypot(b.x - this.c.x, b.z - this.c.z)).slice(0, 56);
    slots.forEach((s, i) => this.hut(s, i));
    this.garland = new Bulbs(this.g, Math.max(1, this.eaves.length), WARM, 0.016);
    // lanterns strung across the way after dark: a sagging string over every shut tile
    for (const L of m.lines) for (let k = m.kind === 'junction' ? 1 : 0; k < L.length; k++) {
      const a = L[Math.max(0, k - 1)], b = L[Math.min(L.length - 1, k + 1)], d = Math.hypot(b.x - a.x, b.z - a.z) || 1;
      const nx = -(b.z - a.z) / d, nz = (b.x - a.x) / d, x = w.ox + L[k].x, z = w.oz + L[k].z, y = ctx.ground(x, z);
      for (let j = 0; j <= 6; j++) { const u = j / 6 - 0.5; this.lanterns.push({ x: x + nx * u * 0.62, z: z + nz * u * 0.62, y: y + 0.36 - 0.06 * Math.cos(u * Math.PI) }); }
    }
    this.strings = new Bulbs(this.g, Math.max(1, this.lanterns.length), WARM, 0.022);
    this.treeBulbs = new Bulbs(this.g, 70, [0xff3b3b, 0xffd166, 0x3dff8a, 0x5ad1ff, 0xffffff, 0xff6ad5], 0.028);
    if (rideAt) this.buildRide(rideAt, rideR, rank >= 3 ? 'wheel' : 'carousel');
  }

  private cold(): boolean { return !!this.ctx.snowing?.() || COLD.has(this.place.town?.region ?? ''); }

  private buildTree(): void {
    const { x, z, y, s } = this.tree, green = this.snowy ? 0x2c5e3c : 0x1f5a2e;
    [[0.8, 1.0, 0], [0.62, 0.85, 0.62], [0.42, 0.7, 1.2]].forEach(([r, h, at]) => {
      const cone = new THREE.Mesh(new THREE.ConeGeometry(r * s, h * s, 9), flat(green));
      cone.position.set(x, y + (0.2 + at + h / 2) * s, z);
      cone.castShadow = true;
      this.g.add(cone);
    });
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.08 * s, 0.1 * s, 0.24 * s, 6), flat(0x5a3a22));
    trunk.position.set(x, y + 0.12 * s, z);
    this.g.add(trunk);
    const star = new THREE.Mesh(new THREE.OctahedronGeometry(0.13 * s), flat(0xffd166, 2.2));
    star.position.set(x, y + 2.18 * s, z);
    this.g.add(star);
  }

  private buildRide(at: Pt, r: number, kind: 'carousel' | 'wheel'): void {
    const g = new THREE.Group(), y = this.ctx.ground(at.x, at.z);
    g.position.set(at.x, y, at.z);
    this.g.add(g);
    const cabins: THREE.Object3D[] = [];
    let spin: THREE.Object3D;
    if (kind === 'carousel') {
      const base = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 0.07, 18), flat(0xf4f2ec));
      base.position.y = 0.035; g.add(base);
      spin = new THREE.Group(); g.add(spin);
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.62, 8), flat(0xd4a017)); pole.position.y = 0.38; spin.add(pole);
      const top = new THREE.Mesh(new THREE.ConeGeometry(r * 1.08, 0.32, 18), flat(0xc8102e)); top.position.y = 0.85; spin.add(top);
      const band = new THREE.Mesh(new THREE.CylinderGeometry(r * 1.08, r * 1.08, 0.07, 18), flat(0xf4f2ec)); band.position.y = 0.66; spin.add(band);
      for (let k = 0; k < 8; k++) {
        const a = (k / 8) * Math.PI * 2, horse = new THREE.Group();
        horse.position.set(Math.cos(a) * r * 0.72, 0.2, Math.sin(a) * r * 0.72);
        horse.rotation.y = -a;
        const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 0.5, 4), flat(0xd4a017)); rod.position.y = 0.2; horse.add(rod);
        const body = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.07, 0.16), flat([0xf4f2ec, 0x8a5a34, 0x2a2a2e, 0xd4a017][k % 4])); body.position.y = 0.12; horse.add(body);
        spin.add(horse); cabins.push(horse);
      }
    } else {
      const H = r + 0.25;
      for (const side of [-1, 1]) for (const lean of [-1, 1]) {
        const leg = new THREE.Mesh(new THREE.BoxGeometry(0.05, H * 1.05, 0.05), flat(0xe8e8ee));
        leg.position.set(lean * 0.22, H / 2, side * 0.14); leg.rotation.z = -lean * 0.24; g.add(leg);
      }
      spin = new THREE.Group(); spin.position.y = H; g.add(spin);
      for (const side of [-0.1, 0.1]) {
        const rim = new THREE.Mesh(new THREE.TorusGeometry(r, 0.022, 5, 36), flat(0xe8e8ee)); rim.position.z = side; spin.add(rim);
      }
      for (let k = 0; k < 8; k++) {
        const spoke = new THREE.Mesh(new THREE.BoxGeometry(0.02, r * 2, 0.02), flat(0xe8e8ee)); spoke.rotation.z = (k / 8) * Math.PI; spin.add(spoke);
      }
      for (let k = 0; k < 10; k++) {
        const cab = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.13, 0.13), flat(STRIPES[k % STRIPES.length]));
        g.add(cab); cabins.push(cab);
      }
    }
    // the ride turns side-on to the long way of the square
    const lot = this.m.lot!;
    g.rotation.y = lot.w >= lot.d ? 0 : Math.PI / 2;
    this.ride = { g, spin, kind, cabins, r };
    this.rideBulbs = new Bulbs(this.g, 24, WARM, 0.025);
  }

  /** A wooden hut: its counter and awning to the aisle, a pitched roof (white where it's cold), a garland on the eave. */
  private hut(s: Slot, i: number): void {
    const B = this.stalls, h = this.e.h, ax = Math.sin(s.yaw), az = Math.cos(s.yaw);
    const at = (du: number, da: number): [number, number] => [s.x + s.ux * du + ax * da, s.z + s.uz * du + az * da];
    const [x0, z0] = at(-0.02, 0), y = this.ctx.ground(x0, z0);
    // which way the aisle is in the box's own frame (its x axis is (cos yaw, −sin yaw))
    const sgn = Math.sign(s.ux * Math.cos(s.yaw) - s.uz * Math.sin(s.yaw)) || 1;
    B.add(x0, y, z0, 0.22, 0.2, 0.34, WOODS[Math.floor(u01(h, i * 3) * WOODS.length)], s.yaw);
    { const [x, z] = at(0.1, 0); B.add(x, y + 0.09, z, 0.05, 0.02, 0.3, 0xc9a26b, s.yaw); }
    { const [x, z] = at(0.12, 0); B.add(x, y + 0.19, z, 0.08, 0.012, 0.32, AWNINGS[Math.floor(u01(h, i * 3 + 1) * AWNINGS.length)], s.yaw, -0.35 * sgn); }
    const roof = this.snowy ? SNOW : ROOFS[i % ROOFS.length];
    for (const du of [-0.06, 0.06]) {
      const [x, z] = at(du - 0.02, 0);
      this.roofs.push(B.add(x, y + 0.205, z, 0.15, 0.016, 0.38, roof, s.yaw, -0.6 * sgn * Math.sign(du)));
    }
    this.mark();
    for (let j = 0; j < 6; j++) { const [x, z] = at(0.1, -0.16 + j * 0.064); this.eaves.push({ x, z, y: y + 0.205 }); }
    if (i % 3 === 0 && this.steam.length < 8) { const [x, z] = at(0.12, 0); this.steam.push({ x, z, y: y + 0.16 }); }
  }

  update(now: number, dt: number): void {
    const { on, built, busy } = this.update0(now, dt);
    if (!on) return;
    // snow coming on (or off) whitens the roofs
    const cold = this.cold();
    if (cold !== this.snowy) { this.snowy = cold; for (let k = 0; k < this.roofs.length; k++) if (this.roofs[k] >= 0) this.stalls.recolour(this.roofs[k], cold ? SNOW : ROOFS[Math.floor(k / 2) % ROOFS.length]); }
    const night = this.ctx.night(), tt = performance.now() / 1000;
    // the huts standing so far keep their garlands lit
    const huts = Math.ceil(built * this.marks.length);
    this.garland.begin();
    for (let k = 0; k < Math.min(this.eaves.length, huts * 6); k++) { if ((k + Math.floor(tt * 1.5)) % 7 === 0) continue; const p = this.eaves[k]; this.garland.at(p.x, p.y, p.z); }
    this.garland.end();
    this.strings.begin();
    if (night > 0.2 && built > 0.5) for (const p of this.lanterns) this.strings.at(p.x, p.y, p.z);
    this.strings.end();
    // the tree, lit from the morning's opening to packing away
    const T = this.tree;
    this.treeBulbs.begin();
    if (built > 0.3) for (let k = 0; k < 70; k++) {
      const u = k / 70, a = u * Math.PI * 11, r = (0.82 * (1 - u) + 0.06) * T.s;
      if ((k + Math.floor(tt * 2)) % 6 === 0) continue;
      this.treeBulbs.at(T.x + Math.cos(a) * r, T.y + (0.25 + u * 1.85) * T.s, T.z + Math.sin(a) * r);
    }
    this.treeBulbs.end();
    // mulled wine
    for (const p of this.steam) if (busy > 0 && Math.random() < dt * 1.2) this.ctx.particles.puff({ x: p.x, y: p.y, z: p.z, vx: 0, vy: 0.1, vz: 0, life: 2.4, colour: 0xf4f4f4, size: 0.15, alpha: 0.3, drag: 0.5 });
    this.turn(dt, busy);
  }

  /** The carousel goes round, its horses rising and falling; the wheel turns, its cabins hanging true. */
  private turn(dt: number, busy: number): void {
    const R = this.ride;
    if (!R) return;
    const sp = busy > 0 ? 1 : 0;
    if (R.kind === 'carousel') {
      R.spin.rotation.y += dt * 0.9 * sp;
      R.cabins.forEach((c, k) => { c.position.y = 0.2 + Math.sin(R.spin.rotation.y * 3 + k * 1.6) * 0.05 * sp; });
    } else {
      R.spin.rotation.z += dt * 0.18 * sp;
      R.cabins.forEach((c, k) => {
        const a = R.spin.rotation.z + (k / R.cabins.length) * Math.PI * 2;
        c.position.set(Math.cos(a) * R.r, R.spin.position.y + Math.sin(a) * R.r - 0.09, 0);
      });
    }
    // bulbs round its rim after dark
    const b = this.rideBulbs!, g = R.g;
    b.begin();
    if (this.ctx.night() > 0.2) {
      const v = new THREE.Vector3();
      for (let k = 0; k < 24; k++) {
        const a = (k / 24) * Math.PI * 2 + (R.kind === 'wheel' ? R.spin.rotation.z : R.spin.rotation.y);
        if (R.kind === 'carousel') v.set(Math.cos(a) * R.r * 1.08, 0.7, Math.sin(a) * R.r * 1.08);
        else v.set(Math.cos(a) * R.r, R.spin.position.y + Math.sin(a) * R.r, 0.11);
        v.applyAxisAngle(new THREE.Vector3(0, 1, 0), g.rotation.y).add(g.position);
        b.at(v.x, v.y, v.z);
      }
    }
    b.end();
  }
}
