import * as THREE from 'three';
import { discoParts, NEON } from './specialTrains';

/**
 * The Wonder Ball (game/passportRewards.ts, every wonder stamped): the rave train's mirror ball (render/specialTrains.ts,
 * the same geometry and material) on a short chrome mast, turning on a vehicle's roof, with the disco car's spots of
 * coloured light wheeling round it on the ground after dark. Where it stands is measured off the built body
 * (render/treats.ts); here are the pieces and the clock.
 *
 * Nothing needs a per-frame list: the ball and its ring of spots turn themselves as they are drawn (onBeforeRender,
 * from the shared clock), so a ball on a parked unit, a hired van, another player's car or a garage thumbnail all
 * turn without being told, and one off screen costs nothing. The night's part is a single shared material whose
 * visibility `treatsTick` sets each frame: the spots (and the lantern's beams, render/treats.ts) are off by day and
 * at the lowest quality. Every material here is one of the programs the shader zoo already builds
 * (flat standard; additive vertex-alpha basic), so a ball turning up compiles nothing.
 */

/** The ball's own radius in its shared geometry (specialTrains' disco ball). */
const BALL_R = 0.07;
/** Turns a second. */
const SPIN = 1.6;

const clock = (): number => performance.now() / 1000;

/** A mesh that turns about its own y by the clock as it is drawn: the ball, and the spots it throws. */
class Turning extends THREE.Mesh {
  phase = Math.random() * Math.PI * 2;
  rate = SPIN;
  override onBeforeRender(): void {
    this.rotation.y = clock() * this.rate + this.phase;
    this.updateMatrix();
    if (this.parent) this.matrixWorld.multiplyMatrices(this.parent.matrixWorld, this.matrix);
    else this.matrixWorld.copy(this.matrix);
  }
}

let fx: {
  ball: THREE.BufferGeometry; ballMat: THREE.MeshStandardMaterial;
  ring: THREE.BufferGeometry; ringMat: THREE.MeshBasicMaterial;
  chrome: THREE.MeshStandardMaterial;
  beam: THREE.BufferGeometry; pool: THREE.BufferGeometry; beamMat: THREE.MeshBasicMaterial;
} | null = null;

/** An RGBA colour on every vertex of g, from a function of its position. */
function paintRGBA(g: THREE.BufferGeometry, f: (x: number, y: number, z: number) => [number, number, number, number]): void {
  const pos = g.getAttribute('position');
  const out = new Float32Array(pos.count * 4);
  for (let i = 0; i < pos.count; i++) out.set(f(pos.getX(i), pos.getY(i), pos.getZ(i)), i * 4);
  g.setAttribute('color', new THREE.BufferAttribute(out, 4));
}

/** The shared pieces, built once. */
export function treatFx(): NonNullable<typeof fx> {
  if (fx) return fx;
  const additive = (): THREE.MeshBasicMaterial => new THREE.MeshBasicMaterial({
    vertexColors: true, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false,
  });
  // the spots: fourteen discs round a unit ring, each a neon colour, soft at the rim, in one mesh (one draw)
  const discs: THREE.BufferGeometry[] = [];
  const c = new THREE.Color();
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2 + (i % 2) * 0.2, r = 0.45 + (i % 3) * 0.27, s = 0.085 + (i % 2) * 0.03;
    const d = new THREE.CircleGeometry(s, 10).rotateX(-Math.PI / 2).translate(Math.cos(a) * r, 0, Math.sin(a) * r);
    c.setHex(NEON[i % NEON.length]);
    const cx = Math.cos(a) * r, cz = Math.sin(a) * r;
    paintRGBA(d, (x, _y, z) => [c.r, c.g, c.b, Math.hypot(x - cx, z - cz) < s * 0.5 ? 0.9 : 0.25]);
    discs.push(d.toNonIndexed());
  }
  const ring = mergeAll(discs);
  const ringMat = additive();
  ringMat.visible = false;
  // the ball: the disco car's, its facets tiled in mirror greys so each catches the light its own way as it turns
  const ball = discoParts().ball.clone();
  const tiles = ball.index ? ball.toNonIndexed() : ball;
  {
    const n = tiles.getAttribute('position').count, col = new Float32Array(n * 3);
    for (let f = 0; f < n / 3; f++) {
      const h = Math.sin(f * 12.9898) * 43758.5453;
      const s = 0.62 + 0.38 * (h - Math.floor(h));
      for (let v = 0; v < 3; v++) col.set([s, s, s * 1.02], (f * 3 + v) * 3);
    }
    tiles.setAttribute('color', new THREE.BufferAttribute(col, 3));
  }
  const ballMat = new THREE.MeshStandardMaterial({ color: 0xf4f7fb, vertexColors: true, metalness: 0.45, roughness: 0.12, flatShading: true, emissive: 0xffffff, emissiveIntensity: 0.12 });
  const chrome = new THREE.MeshStandardMaterial({ color: 0xd9dde2, roughness: 0.35, metalness: 0.5, flatShading: true });
  // the lantern's beam: a unit cone out along +y from the lamp, brightest at the lens; and its pool on the ground
  const beam = new THREE.CylinderGeometry(1, 0.08, 1, 14, 1, true).translate(0, 0.5, 0);
  paintRGBA(beam, (_x, y) => [1, 0.8, 0.55, 0.3 * (1 - y) * (1 - y) + 0.015]);
  const pool = new THREE.CircleGeometry(1, 20).rotateX(-Math.PI / 2);
  paintRGBA(pool, (x, _y, z) => [1, 0.78, 0.5, 0.3 * (1 - Math.min(1, Math.hypot(x, z)))]);
  const beamMat = additive();
  beamMat.visible = false;
  fx = { ball: tiles, ballMat, ring, ringMat, chrome, beam, pool, beamMat };
  // kept when a vehicle wearing them goes (render/vehicleMeshes.ts disposeVehicleMesh)
  for (const m of [ballMat, ringMat, chrome, beamMat]) m.userData.shared = true;
  return fx;
}

function mergeAll(list: THREE.BufferGeometry[]): THREE.BufferGeometry {
  let n = 0;
  for (const g of list) n += g.getAttribute('position').count;
  const pos = new Float32Array(n * 3), nor = new Float32Array(n * 3), col = new Float32Array(n * 4);
  let o = 0;
  for (const g of list) {
    const p = g.getAttribute('position'), q = g.getAttribute('normal'), cc = g.getAttribute('color');
    for (let i = 0; i < p.count; i++, o++) {
      pos.set([p.getX(i), p.getY(i), p.getZ(i)], o * 3);
      nor.set([q.getX(i), q.getY(i), q.getZ(i)], o * 3);
      col.set([cc.getX(i), cc.getY(i), cc.getZ(i), cc.getW(i)], o * 4);
    }
    g.dispose();
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  g.setAttribute('color', new THREE.BufferAttribute(col, 4));
  g.computeBoundingSphere();
  return g;
}

/** Marks a mesh of shared geometry: disposeVehicleMesh leaves it alone; and it casts no shadow unless asked. */
export function sharedPiece<T extends THREE.Object3D>(o: T, shadow = false): T {
  o.userData.shared = true;
  o.userData.noShadow = !shadow;
  o.castShadow = shadow;
  return o;
}

/** How much bigger the ball is than the `r` its mast is sized by. */
const BALL_GROW = 4;

/**
 * Put the Wonder Ball on: a mast standing on (`up` 1) or hanging from (`up` −1) the point (x, y, z) of `body`, the ball
 * of radius r at its end, and (when `ground` is given) its spots on the ground under it, `spread` across. Returns what
 * must not be merged into the body (the ball, which turns; the ring is see-through and is never merged).
 */
export function addWonderBall(body: THREE.Object3D, x: number, y: number, z: number, r: number, up: 1 | -1, ground: THREE.Object3D | null, spread: number, gy = 0.03): THREE.Object3D[] {
  const f = treatFx();
  const h = r * 1.5, w = Math.max(0.006, r * 0.11);
  // the mast is its own rod (it merges into the body like any other part), in the shared chrome
  const mast = new THREE.Mesh(new THREE.CylinderGeometry(w, w * 1.3, h, 8).translate(0, h / 2, 0), f.chrome);
  mast.position.set(x, y, z);
  if (up < 0) mast.rotation.x = Math.PI;
  mast.castShadow = true;
  body.add(mast);
  // the ball four times the size it was against its mast (the user, 5 Nov 2026), still sitting on the mast's tip
  const br = r * BALL_GROW;
  const ball = new Turning(f.ball, f.ballMat);
  ball.scale.setScalar(br / BALL_R);
  ball.position.set(x, y + up * (h + br * 0.9), z);
  ball.castShadow = true;
  ball.userData.shared = true;
  body.add(ball);
  if (ground) {
    const ring = sharedPiece(new Turning(f.ring, f.ringMat));
    ring.rate = SPIN * 0.8;
    ring.scale.set(spread, 1, spread);
    ring.position.set(x, gy, z);
    ring.renderOrder = 4;
    ground.add(ring);
  }
  return [ball];
}

/**
 * Each frame (main.ts, and any page that shows vehicles at night): how dark it is, and whether the quality is at its
 * lowest. The spots show after dark above the lowest quality; the lantern's beams after dark at any.
 */
export function treatsTick(night: number, lowest: boolean): void {
  const f = fx;
  if (!f) return;
  f.ringMat.visible = night > 0.2 && !lowest;
  f.ringMat.opacity = Math.min(1, (night - 0.2) * 2.5);
  f.beamMat.visible = night > 0.3;
  f.beamMat.opacity = Math.min(1, (night - 0.3) * 2.5);
}
