interface Row {
  kind: BuildingKind;
  /** The smallest town that may be asked for it. */
  from: TownKind;
  /** The biggest: a city has no barns, and no village hall. */
  upto?: TownKind;
  /** How many the town will have at most; none for the streets' filler. */
  cap?: number;
  /** A building that must stand first. */
  needs?: BuildingKind;
  /** What the land round the town must offer. */
  where?: 'forest' | 'warm';
  /** Only in this biome's towns. */
  biome?: RegionKind;
  /** The spec, for the older kinds KIND_SPEC doesn't know. */
  spec?: Omit<Spec, 'kind'>;
  /** Kinds that count against one cap together (a town has one great house of worship). */
  share?: string;
}

