const RANK: Record<TownKind, number> = { rural: 0, suburb: 1, city: 2, metro: 3, mega: 4 };
const HOMES = new Set<string>(['house', 'cottage', 'bungalow', 'duplex', 'townhouse', 'terraceRow', 'apartment', 'towerBlock', 'courtyardBlock', 'condoTower', 'mansion', 'retirementHome', 'trailerPark', 'stiltHouse', 'croft', 'resortVillas', 'skyscraper', 'office', 'shop', 'store']);
const SHIPS = new Set<string>(CARGO.flatMap((c) => c.from as string[]));
const TAKES = new Set<string>(CARGO.flatMap((c) => c.to as string[]));

/** "bigBox" → "Big box". */
export function kindLabel(kind: string): string {
  // the cargo labels call the comms tower a radio mast; beside a real radio mast the menu needs them apart
  if (kind === 'commsTower') return 'Comms tower';
  const own = SITE_LABEL[kind as SiteKind];
  if (own) return own;
  const words = kind.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  return words[0].toUpperCase() + words.slice(1);
}

/** What a kind would add to the town's cargo, as icons: what it sends out, and what it takes. */
export function cargoLine(kind: string): { out: string[]; in: string[] } {
  const out = CARGO.filter((c) => (c.from as string[]).includes(kind)).map((c) => `${c.icon} ${c.name.toLowerCase()}`);
  const inn = CARGO.filter((c) => (c.to as string[]).includes(kind)).map((c) => `${c.icon} ${c.name.toLowerCase()}`);
  return { out: out.slice(0, 3), in: inn.slice(0, 3) };
}

function groupOf(kind: string, s: Spec): Group {
  // homes send commuters and take groceries, but a fleet wants them for being homes
  if (HOMES.has(kind)) return 'homes';
  if (SHIPS.has(kind)) return 'ships';
  if (TAKES.has(kind)) return 'takes';
  if (s.solid === false) return 'open';
  return 'civic';
}

