// preferences

/** A building a fleet has asked for: the spec in the town's dress, where its ghost stands, and its model's seed. */
interface BuildAsk {
  what: 'building';
  /** The roster's kind (the spec's kind is the town's own version of it). */
  row: BuildingKind;
  s: Spec;
  x: number; z: number; wx: number; wz: number; facing: number;
  seed: number;
  /** A style the town imported (docs/passport.html) that this one is to be drawn in, rather than the town's own. */
  style?: Arch;
}
interface TerritoryAsk { what: 'territory' }

export type Pref = (BuildAsk | TerritoryAsk) & {
  who: string;
  /** The game day it was set. */
  day: number;
  /** Building steps the town has taken without it since. */
  waited: number;
  /** The ghost's site is no longer good (built over, or the ground changed); for territory, no ground was left. */
  blocked: boolean;
};

/** One entry on the menu: a kind the town could be asked for, and if it can't be just now, why not. */
export interface Option {
  row: Row;
  /** In the town's dress: a church in the Sands is a mosque. */
  spec: Spec;
  label: string;
  group: Group;
  has: number;
  cap?: number;
  /** Null when it can be asked for; else a few words. */
  why: string | null;
  /** An imported style this entry is drawn in (and the menu key that tells it from the town's own version). */
  style?: Arch;
  /** What the menu and the ghost know it by: the roster's kind, with the style for an imported one. */
  id: string;
}

interface LobbyHost {
  carriage: Carriage;
  /** The game clock, in hours. */
  hours(): number;
  announce(title: string, body: string): void;
  /** The styles native to a town beyond its own: Influenced and up (docs/culturegate.html), with their names; none without culture. */
  styles?(key: string): { style: Arch; label: string }[];
  /** The Visitors' rung in a town (game/culture.ts): once Influenced its menu offers their buildings, whatever its size. */
  visitors?(key: string): number;
}

/** Saved: per town key, per fleet, its queue first to last (a save from before the queue holds one ask, not a list). */
export type SavedLobby = Record<string, Record<string, SavedPref | SavedPref[]>>;
type SavedPref = { a: 't'; d: number; n: number; b: 0 | 1 }
  | { a: 'b'; k: BuildingKind; s: Spec; p: [number, number, number, number, number, number]; d: number; n: number; b: 0 | 1; y?: Arch };

/**
 * Asks one fleet may stand in one town at once (the user, 7 Oct 2026): a queue, first to last in the order the
 * player wants them. A roll the fleet wins builds the first one that can be done there and then.
 */
export const QUEUE_MAX = 5;

export class Lobby {
  /** town key → fleet → what it asked for, first wanted first. */
  private prefs = new Map<string, Map<string, Pref[]>>();
  /** Something about a town's preferences changed: the ghosts and the card look again. */
  onChange: ((key: string) => void) | null = null;
  /** The last few rolls, for the console. */
  readonly log: string[] = [];
  /** Who won the last roll step() made ('' the town), whether or not their ask could then be done. */
  lastWinner = '';

  constructor(private host: LobbyHost) {}

  /** The fleet's say in the town: a probability, 0 when the town doesn't know it or has seen too little trade. */
  influence(key: string, who = YOU): number { return this.host.carriage.influence(key, who); }

  /** The fleet's first ask in the town (the one a won roll tries first), or null. */
  get(key: string, who = YOU): Pref | null { return this.prefs.get(key)?.get(who)?.[0] ?? null; }

  /** The fleet's asks in the town, first wanted first. */
  queue(key: string, who = YOU): readonly Pref[] { return this.prefs.get(key)?.get(who) ?? []; }

  /** Every preference standing, with its town key and its place in its fleet's queue, for the ghosts. */
  all(): { key: string; p: Pref; rank: number; of: number }[] {
    const out: { key: string; p: Pref; rank: number; of: number }[] = [];
    for (const [key, m] of this.prefs) for (const q of m.values()) q.forEach((p, rank) => out.push({ key, p, rank, of: q.length }));
    return out;
  }

  /** Take down every ask the fleet has in the town. */
  clear(key: string, who = YOU): void {
    const m = this.prefs.get(key);
    if (!m?.delete(who)) return;
    if (!m.size) this.prefs.delete(key);
    this.onChange?.(key);
  }

  /** Take down one ask, by its place in the queue. */
  remove(key: string, at: number, who = YOU): void {
    const q = this.prefs.get(key)?.get(who);
    if (!q || at < 0 || at >= q.length) return;
    q.splice(at, 1);
    if (!q.length) { this.clear(key, who); return; }
    this.onChange?.(key);
  }

  /** Move one ask up (-1) or down (+1) the queue: the town tries the first first. */
  move(key: string, at: number, dir: -1 | 1, who = YOU): void {
    const q = this.prefs.get(key)?.get(who);
    const to = at + dir;
    if (!q || at < 0 || at >= q.length || to < 0 || to >= q.length) return;
    [q[at], q[to]] = [q[to], q[at]];
    this.onChange?.(key);
  }

  /** Add an ask at the end of the fleet's queue, or put it in place of the one at `at`. */
  private put(key: string, p: Pref, at = -1): void {
    let m = this.prefs.get(key);
    if (!m) this.prefs.set(key, (m = new Map()));
    let q = m.get(p.who);
    if (!q) m.set(p.who, (q = []));
    if (at >= 0 && at < q.length) q[at] = p;
    else q.push(p);
    this.onChange?.(key);
  }

  private day(): number { return Math.floor(this.host.hours() / 24); }

  // ---- what may be asked for ----

  /** A layout over the town as it stands, guarded as growth guards it: the rules a ghost is judged by. */
  layout(w: World, t: Town, rng: Rng = mulberry32(1)): Layout {
    const c = Layout.over(w, t, rng);
    c.guard = growable(w, t);
    c.dry = true;
    return c;
  }

  /** The row's spec before the town dresses it, its sizes and storeys rolled from a seed of the town's and the kind's. */
  private rawSpec(row: Row, rng: Rng): Spec | null {
    const roll = (v: number | [number, number] | undefined) =>
      (v === undefined ? undefined : typeof v === 'number' ? v : v[0] + Math.floor(rng() * (v[1] - v[0] + 1)));
    if (row.spec) return { kind: row.kind, ...row.spec };
    const k = KIND_SPEC[row.kind];
    if (!k) return null;
    return {
      kind: row.kind, w: roll(k.w)!, d: roll(k.d)!, floors: roll(k.floors), zone: k.zone, lot: k.lot, solid: k.solid,
      frontage: k.frontage, gap: k.gap, allow: k.allow, along: k.along, waterside: k.waterside, apart: k.apart,
      // a hand-placed lot faces whatever street it is put on: the through-road rule is the town's taste, not a rule
      roadside: undefined, highest: undefined,
    };
  }

  /**
   * The menu for a town: every kind a town of its size, style and biome could build for itself, in its
   * own dress, with the reason it can't be asked for just now (it has its share, it needs something
   * first, the land has none of what it wants, or there is nowhere it fits). `room` false skips the
   * last check, which walks the whole town once per kind.
   */
  options(w: World, t: Town, room = true): Option[] {
    const key = townKey(w, t);
    const counts = new Map<string, number>();
    for (const b of t.buildings) if (!b.gone) counts.set(b.kind, (counts.get(b.kind) ?? 0) + 1);
    const shared = new Map<string, number>();
    for (const row of LOBBY) if (row.share) shared.set(row.share, (shared.get(row.share) ?? 0) + (counts.get(row.kind) ?? 0));
    const warm = meanOver(w, t, w.temp) > 0.58;
    const forest = forestShare(w, t) > 0.04;
    const out: Option[] = [];
    const seen = new Set<string>();
    for (const row of LOBBY) {
      if (RANK[row.from] > RANK[t.kind] || (row.upto && RANK[row.upto] < RANK[t.kind])) continue;
      // a satellite never becomes a big city, so it is never asked for one's buildings
      if (t.parent !== undefined && RANK[row.from] >= RANK.metro) continue;
      if (row.biome && row.biome !== t.region) continue;
      if (seen.has(row.kind)) continue;
      const rng = mulberry32(hashString(`${key}|${row.kind}|lobby-spec`));
      const raw = this.rawSpec(row, rng);
      if (!raw) continue;
      const c = this.layout(w, t, rng);
      const spec = c.dress(raw);
      if (!spec) continue; // the style or the biome has no such thing
      seen.add(row.kind);
      const has = (counts.get(spec.kind) ?? 0) + (spec.kind !== row.kind ? counts.get(row.kind) ?? 0 : 0);
      let why: string | null = null;
      if (row.share && (shared.get(row.share) ?? 0) >= (row.cap ?? 1)) why = 'has its great house of worship';
      else if (row.cap !== undefined && has >= row.cap) why = row.cap === 1 ? 'has one' : `has its ${row.cap}`;
      else if (row.needs && !counts.get(row.needs)) why = `needs a ${kindLabel(row.needs).toLowerCase()} first`;
      else if (row.where === 'forest' && !forest) why = 'no woods round here';
      else if (row.where === 'warm' && !warm) why = 'too cold here';
      else if (room && !this.anyFit(c, spec)) why = spec.waterside === true ? 'nowhere on the water here' : spec.along === 'wide' ? 'no four-lane road to face' : 'no room right now';
      out.push({ row, spec, label: kindLabel(spec.kind), group: groupOf(spec.kind, spec), has, cap: row.cap, why, id: row.kind });
    }
    // the styles the town has imported (docs/passport.html): each ordinary kind again, drawn in the style, and the
    // style's own signature buildings where it swaps one in. A kind's room is the native entry's unless the swap resized it.
    const styles = this.host.styles?.(key) ?? [];
    if (styles.length) {
      const full = foreignShare(t) >= FOREIGN_CAP;
      const native = new Map(out.map((o) => [o.row.kind, o]));
      for (const { style, label } of styles) {
        const done = new Set<string>();
        for (const row of LOBBY) {
          const base = native.get(row.kind);
          if (!base || base.row !== row || base.spec.solid === false) continue;
          const rng = mulberry32(hashString(`${key}|${row.kind}|lobby-spec`));
          const raw = this.rawSpec(row, rng);
          if (!raw) continue;
          const c = this.layout(w, t, rng);
          const spec = c.dressAs(raw, style);
          if (!spec || done.has(spec.kind)) continue;
          done.add(spec.kind);
          const swapped = spec.kind !== base.spec.kind;
          let why = full ? `${Math.round(FOREIGN_CAP * 100)}% of the town is imported already` : swapped ? null : base.why;
          if (!why && swapped) {
            if ((counts.get(spec.kind) ?? 0) >= (row.cap ?? 1)) why = 'has one';
            else if (room && !this.anyFit(c, spec)) why = 'no room right now';
          }
          out.push({ row, spec, label: `${label} · ${kindLabel(spec.kind)}`, group: 'culture', has: counts.get(spec.kind) ?? 0, cap: swapped ? row.cap ?? 1 : row.cap, why, style, id: `${row.kind}@${style}` });
        }
      }
    }
    // the Visitors' culture at a Quarter (meteorites carried home): their dome and an observatory, in a town of any size
    if ((this.host.visitors?.(key) ?? 0) >= 2) {
      for (const row of VISITOR_ROWS) {
        if (out.some((o) => o.id === row.kind)) continue; // a city's own menu has it already
        const rng = mulberry32(hashString(`${key}|${row.kind}|lobby-spec`));
        const raw = this.rawSpec(row, rng);
        if (!raw) continue;
        const c = this.layout(w, t, rng);
        const spec = c.dress(raw);
        if (!spec) continue;
        const has = counts.get(spec.kind) ?? 0;
        const why = has >= (row.cap ?? 1) ? 'has one' : room && !this.anyFit(c, spec) ? 'no room right now' : null;
        out.push({ row, spec, label: `Visitors · ${kindLabel(spec.kind)}`, group: 'culture', has, cap: row.cap, why, id: `${row.kind}@visitor` });
      }
    }
    return out;
  }

  /** Every corner the spec stands at, each turn tried; stops at the first when `first`. */
  anchors(c: Layout, spec: Spec, first = false): { x: number; z: number; wx: number; wz: number; facing: number }[] {
    const out: { x: number; z: number; wx: number; wz: number; facing: number }[] = [];
    for (const o of c.turns(spec)) {
      for (let z = c.z0; z <= c.z0 + c.S - o.wz; z++) {
        for (let x = c.x0; x <= c.x0 + c.S - o.wx; x++) {
          const f = c.fitAt(spec, x, z, o.wx, o.wz);
          if (f < 0) continue;
          out.push({ x, z, wx: o.wx, wz: o.wz, facing: f });
          if (first) return out;
        }
      }
    }
    return out;
  }

  private anyFit(c: Layout, spec: Spec): boolean { return this.anchors(c, spec, true).length > 0; }

  // ---- asking ----

  /**
   * Stand a ghost of this option at (x, z), turned to (wx, wz): added to the end of the fleet's queue in the
   * town, or in place of the ask at `replace` (moving a ghost). The reason it can't, or null when it is set.
   */
  /** Told when the player's own ask for a building is put to a town (the teaching missions, game/coach.ts). */
  onAsked: (() => void) | null = null;

  askBuilding(w: World, t: Town, opt: Option, x: number, z: number, wx: number, wz: number, who = YOU, replace = -1): string | null {
    const key = townKey(w, t);
    if (this.influence(key, who) <= 0) return 'No say here yet: carry something for this town';
    if (opt.why) return opt.why;
    const q = this.queue(key, who);
    if (replace < 0 && q.length >= QUEUE_MAX) return `${QUEUE_MAX} asks is the most a town takes: take one down first`;
    const c = this.layout(w, t);
    const facing = c.fitAt(opt.spec, x, z, wx, wz);
    if (facing < 0) return c.whyNot(opt.spec, x, z, wx, wz) ?? 'it doesn’t fit there';
    // not on top of another of your ghosts in the queue
    const over = q.find((o, k) => k !== replace && o.what === 'building' && x < o.x + o.wx && o.x < x + wx && z < o.z + o.wz && o.z < z + wz);
    if (over) return `it would stand on your ${kindLabel((over as BuildAsk).s.kind).toLowerCase()}`;
    const seed = hashString(`${key}|${opt.spec.kind}|${x},${z}|${this.host.hours()}`) & 0x7fffffff;
    this.put(key, { what: 'building', row: opt.row.kind, s: opt.spec, x, z, wx, wz, facing, seed, style: opt.style, who, day: this.day(), waited: 0, blocked: false }, replace);
    if (who === YOU) this.onAsked?.();
    return null;
  }

  /** Ask the town to take in more ground: one such ask in the queue at a time. */
  askTerritory(w: World, t: Town, who = YOU): string | null {
    const key = townKey(w, t);
    if (this.influence(key, who) <= 0) return 'No say here yet: carry something for this town';
    const q = this.queue(key, who);
    if (q.some((p) => p.what === 'territory')) return 'More ground is in your list already';
    if (q.length >= QUEUE_MAX) return `${QUEUE_MAX} asks is the most a town takes: take one down first`;
    this.put(key, { what: 'territory', who, day: this.day(), waited: 0, blocked: false });
    return null;
  }

  /** The tiles the town would take in if a call for territory won right now. */
  claimPreview(w: World, t: Town): number[] {
    return chooseClaim(w, t, insideOf(w, t), mulberry32(hashString(`${townKey(w, t)}|claim-preview`)));
  }

  // ---- the roll ----

  /**
   * One growth step's chance for whoever has asked. Returns the edits when a fleet's ask wins and can be
   * done, else null — and the town does what it would have done. `fresh` makes a copy of the step's own
   * growth rng, from which the step's table row is read before anything is decided.
   */
  step(w: World, t: Town, step: number, hour: number, fresh: () => Rng): GrowthEdit[] | null {
    const key = townKey(w, t);
    const m = this.prefs.get(key);
    if (!m?.size) return null;
    this.lastWinner = '';
    if (plannedRow(w, t, fresh(), step) !== 'build') return null;
    const u = mulberry32(hashString(`${w.seed}|${w.cx},${w.cz}|${t.id}|${step}|lobby`))();
    // biggest say first, so the order is the same on every machine; nobody's chance depends on anyone else's
    const hands = [...m.entries()]
      .filter(([, q]) => q.length)
      .map(([who, q]) => ({ who, q, share: this.influence(key, who) }))
      .filter((h) => h.share > 0)
      .sort((a, b) => b.share - a.share || (a.who < b.who ? -1 : 1));
    let acc = 0, winner: (typeof hands)[number] | null = null;
    for (const h of hands) {
      acc += h.share;
      if (u < acc) { winner = h; break; }
    }
    this.note(`${t.name} step ${step}: u ${u.toFixed(3)} · ${hands.map((h) => `${h.who} ${(h.share * 100).toFixed(0)}%`).join(', ') || 'no say'} → ${winner ? winner.who : 'the town'}`);
    this.lastWinner = winner?.who ?? '';
    for (const [who, q] of m) if (who !== winner?.who) for (const p of q) p.waited++;
    if (!winner) { this.onChange?.(key); return null; }
    const mine = winner.who === YOU;

    // the winner's queue, first wanted first: the first ask that can be done now is done; the rest wait on
    let c: Layout | null = null;
    for (const win of [...winner.q]) {
      if (win.what === 'territory') {
        const tiles = chooseClaim(w, t, insideOf(w, t), mulberry32(hashString(`${w.seed}|${w.cx},${w.cz}|${t.id}|${step}|claim`)));
        if (!tiles.length) {
          if (!win.blocked && mine) this.host.announce(t.name, 'There is no ground left beside the town to take in');
          win.blocked = true;
          continue;
        }
        this.drop(key, win);
        for (const p of winner.q) if (p !== win) p.waited++;
        if (mine) {
          deeds.add('annexed', tiles.length);
          this.host.announce(t.name, `has taken in ${tiles.length} tiles of new ground, as your fleet asked`);
          press.write({ k: 'annexed', who: 'you', town: keyOf(w, t), at: townAt(w, t), f: { town: t.name, tiles: tiles.length } });
        }
        return [{ k: 'claim', t: t.id, n: tiles }];
      }
      c ??= this.layout(w, t);
      const facing = c.fitAt(win.s, win.x, win.z, win.wx, win.wz);
      if (facing < 0) {
        if (!win.blocked && mine) this.host.announce(t.name, `Your ${kindLabel(win.s.kind).toLowerCase()} site is taken: move it from the town card`);
        win.blocked = true;
        continue;
      }
      this.drop(key, win);
      for (const p of winner.q) if (p !== win) p.waited++;
      if (mine) this.host.announce(t.name, `is putting up the ${kindLabel(win.s.kind).toLowerCase()} your fleet asked for${winner.q.length > 1 ? `: ${winner.q.length - 1} more in your list` : ''}`);
      return this.buildEdit(t, win, facing, hour);
    }
    // nothing in the queue can be done here now: the town does what it would have done
    for (const p of winner.q) p.waited++;
    this.onChange?.(key);
    return null;
  }

  /** Take one ask out of its fleet's queue (it was done). */
  private drop(key: string, p: Pref): void {
    const q = this.prefs.get(key)?.get(p.who);
    const at = q ? q.indexOf(p) : -1;
    if (at >= 0) this.remove(key, at, p.who);
  }

  /** The build edit for an ask that won and fits. */
  private buildEdit(t: Town, win: BuildAsk & Pref, facing: number, hour: number): GrowthEdit[] {
    const s = win.s;
    const b: BuildTuple = [s.kind, win.x, win.z, win.wx, win.wz, facing, s.floors ?? 1, win.seed, s.lot ?? -1, (s.solid ?? true) ? 1 : 0, Math.floor(hour)];
    // an imported style, while the town still has room for more of it
    if (win.style && win.style !== t.style && foreignShare(t) < FOREIGN_CAP) b.push(win.style);
    return [{ k: 'build', t: t.id, b }];
  }

  /** After a growth step: is each ghost's site still good? One that the town built over turns red, once. */
  after(w: World, t: Town): void {
    const key = townKey(w, t);
    const m = this.prefs.get(key);
    if (!m) return;
    let changed = false;
    let c: Layout | null = null;
    for (const p of [...m.values()].flat()) {
      if (p.what !== 'building') continue;
      c ??= this.layout(w, t);
      const ok = c.fitAt(p.s, p.x, p.z, p.wx, p.wz) >= 0;
      if (ok === !p.blocked) continue;
      p.blocked = !ok;
      changed = true;
      if (!ok && p.who === YOU) this.host.announce(t.name, `has built over your ${kindLabel(p.s.kind).toLowerCase()} site: move it from the town card`);
    }
    if (changed) this.onChange?.(key);
  }

  private note(s: string): void {
    this.log.push(s);
    if (this.log.length > 40) this.log.shift();
  }

  // ---- saving ----

  toSave(): SavedLobby {
    const out: SavedLobby = {};
    for (const [key, m] of this.prefs) {
      const row: Record<string, SavedPref[]> = {};
      for (const [who, q] of m) {
        row[who] = q.map((p): SavedPref => (p.what === 'territory'
          ? { a: 't', d: p.day, n: p.waited, b: p.blocked ? 1 : 0 }
          : { a: 'b', k: p.row, s: p.s, p: [p.x, p.z, p.wx, p.wz, p.facing, p.seed], d: p.day, n: p.waited, b: p.blocked ? 1 : 0, ...(p.style ? { y: p.style } : {}) }));
      }
      out[key] = row;
    }
    return out;
  }

  fromSave(s: SavedLobby | undefined): void {
    this.prefs.clear();
    for (const [key, row] of Object.entries(s ?? {})) {
      for (const [who, list] of Object.entries(row ?? {})) {
        for (const q of (Array.isArray(list) ? list : [list]).slice(0, QUEUE_MAX)) {
          if (!q || typeof q !== 'object') continue;
          const base = { who, day: Number(q.d) || 0, waited: Number(q.n) || 0, blocked: q.b === 1 };
          // a building ask from before they were retired (3 Nov 2026) is let go of: the fleet builds for itself now
          if (q.a === 't') this.put(key, { what: 'territory', ...base });
        }
      }
    }
  }

  // ---- the console (pr.lobby) ----

  console(find: (key: string) => { w: World; t: Town } | null) {
    return {
      /** Every preference standing. */
      list: () => this.all().map(({ key, p, rank }) => `${key} ${p.who} #${rank + 1}: ${p.what === 'territory' ? 'territory' : `${p.s.kind} at ${p.x},${p.z} ${p.wx}×${p.wz}`} · waited ${p.waited}${p.blocked ? ' · BLOCKED' : ''} · say ${(this.influence(key, p.who) * 100).toFixed(0)}%`),
      /** The menu for a town, as text. */
      options: (key: string) => { const f = find(key); return f ? this.options(f.w, f.t).map((o) => `${o.group} ${o.label}${o.why ? ` — ${o.why}` : ''}`) : 'not in memory'; },
      /** Ask for a kind at its first spot that fits (or at x, z). */
      set: (key: string, kind: BuildingKind, x?: number, z?: number) => {
        const f = find(key);
        if (!f) return 'not in memory';
        const o = this.options(f.w, f.t).find((q) => q.row.kind === kind || q.spec.kind === kind);
        if (!o) return 'not on the menu';
        const at = x !== undefined && z !== undefined ? { x, z, ...this.layout(f.w, f.t).turns(o.spec)[0] } : this.anchors(this.layout(f.w, f.t), o.spec, true)[0];
        return at ? this.askBuilding(f.w, f.t, o, at.x, at.z, at.wx, at.wz) ?? 'set' : 'nowhere fits';
      },
      /** Where a kind could stand in a town, as [x, z, wx, wz] corners in the cell's tiles. */
      spots: (key: string, kind: BuildingKind, n = 5) => {
        const f = find(key);
        const o = f && this.options(f.w, f.t, false).find((q) => q.row.kind === kind || q.spec.kind === kind);
        if (!f || !o) return [];
        const all = this.anchors(this.layout(f.w, f.t), o.spec);
        return all.filter((_, k) => k % Math.max(1, Math.floor(all.length / n)) === 0).slice(0, n).map((a) => [a.x, a.z, a.wx, a.wz]);
      },
      territory: (key: string) => { const f = find(key); return f ? this.askTerritory(f.w, f.t) ?? 'set' : 'not in memory'; },
      clear: (key: string) => this.clear(key),
      log: () => this.log.slice(),
    };
  }
}

// ---------------------------------------------------------------------------------------------

/** Is a tile inside the town as its border is drawn (townShape.ts)? */
function insideOf(w: World, t: Town): (i: number) => boolean {
  const s = shapeOf(w, t);
  return (i: number) => {
    const x = (i % N) - s.x0, z = Math.floor(i / N) - s.z0;
    return x >= 0 && z >= 0 && x < s.bw && z < s.bh && s.mask[z * s.bw + x] === 1;
  };
}

function meanOver(w: World, t: Town, values: ArrayLike<number>): number {
  let sum = 0, n = 0;
  for (let z = t.z0; z < t.z0 + t.size; z++) for (let x = t.x0; x < t.x0 + t.size; x++) { sum += values[idx(x, z)]; n++; }
  return n ? sum / n : 0;
}

/** Woods in a band round the town: the town itself long since cleared its own. */
function forestShare(w: World, t: Town): number {
  let n = 0, all = 0;
  for (let z = Math.max(0, t.z0 - 8); z < Math.min(N, t.z0 + t.size + 8); z++) {
    for (let x = Math.max(0, t.x0 - 8); x < Math.min(N, t.x0 + t.size + 8); x++) {
      all++;
      if (w.biome[idx(x, z)] === Biome.Forest) n++;
    }
  }
  return all ? n / all : 0;
}

export { CLAIM_TILES };
