/**
 * The convoys (the user, 27 Oct 2026): three missions each offered once, in order, when the fleet first has
 * 2, 4 and 6 vehicles out (the one driven and the crewed road vehicles out of the garage). Each takes the fleet
 * along in Follow mode: the meeting waits for that many of the player's vehicles formed up behind them, the
 * load is more than one hold carries (the formation lends its holds, game/formation.ts), and it is set down
 * only with them all still in line (`deliver.with`, Missions.heldBack). Missions.nearConvoy offers them.
 *
 * Moving Day: a family's house moved to another town. The Circus Comes to Town: the fair's big top taken to
 * the next town's fairground, then a parade round its square. Relief Convoy: supplies from a big town's depot
 * to a village out on its own, against the clock.
 */
import { N, type Town, type World } from '../../world/tiles';
import { cargoById, type CargoType } from '../cargoTypes';
import type { Site } from '../cargo';
import { defOf } from '../fleet';
import type { MissionCtx, Missions } from './missions';
import type { Obj, Reward } from './model';
import { siteRef, squareOf, townRef, townsNear, type Template } from './templates';

/** Vehicles out a convoy asks for, and the ones in Follow mode behind the player that means. */
const SIZE: Record<string, number> = { 'convoy:move': 2, 'convoy:circus': 4, 'convoy:relief': 6 };
/** Each waits for the one before it to be done: none is skipped by a fleet that grew past it. */
const BEFORE: Record<string, string | null> = { 'convoy:move': null, 'convoy:circus': 'convoy:move', 'convoy:relief': 'convoy:circus' };
const CARGO: Record<string, string> = { 'convoy:move': 'movingHouse', 'convoy:circus': 'bigTop', 'convoy:relief': 'reliefConvoy' };

const r10 = (v: number) => Math.round(v / 10) * 10;
const pick = <T>(h: number, xs: T[]): T => xs[h % xs.length];

/** The vehicles out: the one driven and every crewed road vehicle not in the garage (MissionCtx.units' crew). */
export function vehiclesOut(c: MissionCtx): number {
  return 1 + c.units.filter((u) => u.crew && u.land).length;
}

/**
 * Could the player and the biggest `n - 1` of their crewed road vehicles carry it between them: room enough,
 * and one hold at least that takes its kind of goods?
 */
function canPool(c: MissionCtx, n: number, type: CargoType): boolean {
  const lent = c.units.filter((u) => u.crew && u.land).map((u) => defOf(u.model)).sort((a, b) => b.capacity - a.capacity).slice(0, n - 1);
  const all = [c.def, ...lent];
  return all.reduce((s, d) => s + d.capacity, 0) >= type.units && all.some((d) => d.holds.includes(type.cls));
}

/** Why a convoy can't be offered now, or null: done before, the one before it not yet, the fleet too small. */
function convoyGate(id: string) {
  return (c: MissionCtx, ms: Missions): string | null => {
    if (c.done.get(id)) return 'done';
    const before = BEFORE[id];
    if (before && !c.done.get(before)) return 'the convoy before it first';
    if (c.def.kind !== 'land') return 'in a road vehicle';
    const n = SIZE[id];
    if (vehiclesOut(c) < n) return `${n} vehicles out`;
    const type = cargoById(CARGO[id]);
    if (!type || !canPool(c, n, type)) return 'room in the fleet for the load';
    void ms;
    return null;
  };
}

/** The town a site stands in, if any. */
function townAt(s: Site): Town | null {
  const id = s.w.townId[Math.floor(s.lz) * N + Math.floor(s.lx)];
  return s.w.towns.find((t) => t.id === id) ?? null;
}
const midOf = (w: World, t: Town) => ({ x: w.ox + t.x0 + t.size / 2, z: w.oz + t.z0 + t.size / 2 });
const apart = (a: { x: number; z: number }, b: { x: number; z: number }) => Math.hypot(a.x - b.x, a.z - b.z);
/** A site of one of these kinds in that town, picked by the hash. */
function siteIn(c: MissionCtx, kinds: string[], w: World, t: Town, h: number): Site | null {
  const all = c.sites(kinds).filter((s) => s.w === w && townAt(s) === t && !s.quay);
  return all.length ? all[h % all.length] : null;
}
const at = (s: Site, name: string) => ({ x: s.x, z: s.z, cell: [s.w.cx, s.w.cz] as [number, number], name });
const standing = (w: World, t: Town, n = 1): Reward => ({ r: 'standing', town: townRef(w, t), n });

const HOMES = ['house', 'townhouse', 'cottage', 'bungalow', 'duplex', 'terraceRow'];
const FAIRS = ['fairground', 'park', 'greatPark', 'lakePark', 'plaza'];
const DEPOTS = ['logisticsDepot', 'hospital', 'bigBox', 'departmentStore', 'marketHall', 'postOffice'];
const VILLAGE = ['villageHall', 'church', 'chapel', 'pub', 'clinic', 'postOffice', 'school', 'cityHall'];
/** Failing those, somewhere in the village to unload at all: a shop, a house. */
const VILLAGE_ANY = ['shop', 'store', 'diner', 'cafe', 'bakery', 'garage', ...HOMES];

/** Moving Day: a family's house, the lot, moved to a town some way off with one of the fleet in tow. */
const moving: Template = {
  id: 'convoy:move', thread: 'fleet', kind: 'job', cooldown: 2,
  gate: convoyGate('convoy:move'),
  bind(c, h) {
    const type = cargoById(CARGO['convoy:move'])!;
    const towns = townsNear(c, 160);
    for (const [k, a] of towns.slice(0, 4).entries()) {
      const from = siteIn(c, HOMES, a.w, a.t, h + k);
      if (!from) continue;
      const far = towns.filter((b) => b.t !== a.t && apart(midOf(a.w, a.t), midOf(b.w, b.t)) >= 80 && apart(midOf(a.w, a.t), midOf(b.w, b.t)) <= 150);
      for (const b of far.slice(0, 4)) {
        const to = siteIn(c, HOMES, b.w, b.t, h >>> 2);
        if (!to) continue;
        const span = apart(from, to);
        const objs: Obj[] = [
          { t: 'reach', label: 'Meet the family', icon: '👪', at: at(from, 'their old house'), r: 3, stop: true, with: 1 },
          { t: 'deliver', label: 'Bring the furniture', icon: type.icon, cargo: type.id, from: siteRef(from), to: { ...siteRef(to), name: 'the new house' }, n: 1, value: r10(120 + span * 1.2), with: 1 },
        ];
        return {
          title: pick(h >>> 3, ['Moving Day', 'A New Home', 'House Move']),
          why: `A family is moving to ${b.t.name}, and their whole house won't fit in one vehicle. Bring one of yours along to share the load.`,
          details: 'A driver in Follow mode falls in behind you, and their hold counts as yours.',
          giver: { who: 'family', name: 'The movers', at: at(from, 'their old house'), town: townRef(a.w, a.t) },
          hero: { kind: 'vehicle', model: 'mule' }, caption: 'Two vehicles, one move',
          objs, reward: [{ r: 'cash', n: r10(400 + span * 3) }, { r: 'gems', n: 2 }, standing(b.w, b.t)],
        };
      }
    }
    return null;
  },
};

/** The Circus Comes to Town: the big top to the next town's fairground with three in line, then a parade. */
const circus: Template = {
  id: 'convoy:circus', thread: 'fleet', kind: 'job', cooldown: 2,
  gate: convoyGate('convoy:circus'),
  bind(c, h) {
    const type = cargoById(CARGO['convoy:circus'])!;
    const towns = townsNear(c, 180);
    for (const [k, a] of towns.slice(0, 5).entries()) {
      const from = siteIn(c, FAIRS, a.w, a.t, h + k);
      if (!from) continue;
      const next = towns.filter((b) => b.t !== a.t && apart(midOf(a.w, a.t), midOf(b.w, b.t)) >= 60 && apart(midOf(a.w, a.t), midOf(b.w, b.t)) <= 170);
      for (const b of next.slice(0, 5)) {
        const to = siteIn(c, FAIRS, b.w, b.t, h >>> 2);
        if (!to) continue;
        const span = apart(from, to);
        const objs: Obj[] = [
          { t: 'reach', label: 'Meet the ringmaster', icon: '🎩', at: at(from, `the ${siteRef(from).name.toLowerCase()}`), r: 4, stop: true, with: 3 },
          { t: 'deliver', label: 'Bring the big top', icon: type.icon, cargo: type.id, from: siteRef(from), to: siteRef(to), n: 1, value: r10(200 + span * 1.5), with: 3 },
          { t: 'reach', label: 'Lead the parade', icon: '🎪', at: squareOf(b.w, b.t, `${b.t.name}'s square`), r: 6, stop: true, hold: 10, after: 10, before: 18, with: 3 },
        ];
        return {
          title: pick(h >>> 3, ['The Circus Is Coming', 'Roll Up, Roll Up', 'The Big Top']),
          why: `The circus is moving on to ${b.t.name}. Carry the big top there in a line of four, then parade it round the square.`,
          details: 'Too big for one hold: the three behind lend theirs.',
          giver: { who: 'organiser', name: 'The ringmaster', at: at(from, `the ${siteRef(from).name.toLowerCase()}`), town: townRef(a.w, a.t) },
          hero: { kind: 'vehicle', model: 'mule' }, caption: 'The greatest show on the road',
          objs, reward: [{ r: 'cash', n: r10(900 + span * 4) }, { r: 'gems', n: 3 }, standing(a.w, a.t), standing(b.w, b.t)],
        };
      }
    }
    return null;
  },
};

/**
 * A relief run's village this far from the depot's town, at least: a real haul, but one a county can hold on its
 * own (only counties that trade with the player's have sites to unload at).
 */
const RELIEF_MIN = 70;

/** Relief Convoy: six vehicles out of a big town's depot to a village out on its own, before time runs out. */
const relief: Template = {
  id: 'convoy:relief', thread: 'fleet', kind: 'job', cooldown: 2,
  gate: convoyGate('convoy:relief'),
  bind(c, h) {
    const type = cargoById(CARGO['convoy:relief'])!;
    const towns = townsNear(c, 200);
    // out of the biggest towns near, to the smallest well out
    const big = towns.slice(0, 8).sort((p, q) => q.t.size - p.t.size);
    for (const a of big.slice(0, 3)) {
      const from = siteIn(c, DEPOTS, a.w, a.t, h);
      if (!from) continue;
      const out = towns.filter((b) => b.t !== a.t && b.t.size < a.t.size && apart(midOf(a.w, a.t), midOf(b.w, b.t)) >= RELIEF_MIN && apart(midOf(a.w, a.t), midOf(b.w, b.t)) <= 300)
        // a village on a mountain or a ledge first (the ones a storm cuts off), then the farthest out
        .sort((p, q) => +!!q.t.perch - +!!p.t.perch || apart(midOf(q.w, q.t), midOf(a.w, a.t)) - apart(midOf(p.w, p.t), midOf(a.w, a.t)));
      for (const b of out.slice(0, 8)) {
        const to = siteIn(c, VILLAGE, b.w, b.t, h >>> 2) ?? siteIn(c, VILLAGE_ANY, b.w, b.t, h >>> 2);
        if (!to) continue;
        const span = apart(from, to);
        const objs: Obj[] = [
          { t: 'reach', label: 'Meet at the depot', icon: '🚚', at: at(from, `the ${siteRef(from).name.toLowerCase()}`), r: 4, stop: true, with: 5 },
          { t: 'deliver', label: 'Bring the supplies in', icon: type.icon, cargo: type.id, from: siteRef(from), to: siteRef(to), n: 1, value: r10(400 + span * 2), with: 5 },
        ];
        return {
          title: pick(h >>> 3, ['Relief Convoy', 'Supplies Run', 'The Long Haul']),
          why: `${b.t.name} has been cut off and is running short. Lead six of your vehicles there with the supplies, before the day is out.`,
          details: 'The supplies take every hold in the line. They are wanted within twelve hours.',
          giver: { who: 'mayor', name: `The relief committee`, at: at(from, `the ${siteRef(from).name.toLowerCase()}`), town: townRef(a.w, a.t) },
          hero: { kind: 'vehicle', model: 'mule' }, caption: 'Six in line',
          objs, reward: [{ r: 'cash', n: r10(2000 + span * 6) }, { r: 'gems', n: 5 }, standing(b.w, b.t, 2)],
          hours: 12,
        };
      }
    }
    return null;
  },
};

/** In the order they are offered. */
export const CONVOY_TEMPLATES: Template[] = [moving, circus, relief];
export const CONVOY_SIZE = SIZE;
