import { hex, scale, type RGB } from '../../../world/biomes';
import type { Rng } from '../../../world/rng';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, GLASS_LIGHT, METAL, SHOP_GLOW, WARM_GLOW, WHITE, type Draw, type Kit } from '../kit';

/**
 * The Red Rock: an outback roadhouse under rusty tin, a stepped adobe pueblo, a fossil dig with its bones
 * half out of the ground, and the three great buttes. Red sandstone, dust, faded paint.
 */

const ROCK = hex(0xa63c1c), ROCK_LIGHT = hex(0xc0552a), ROCK_DARK = hex(0x7a2c16), TALUS = hex(0x9a4a2a);
const EARTH = hex(0xb05a32), DUST = hex(0xd08a58), PIT = hex(0x7e3820);
const RUST = hex(0x8a4526), RUST_DARK = hex(0x6a3420), FADED = hex(0xdcc9a2), TIMBER = hex(0x6e4a2e);
const ADOBE = hex(0xc98a58), ADOBE_LIGHT = hex(0xd9a06c), ADOBE_DARK = hex(0xae7442), TURQUOISE = hex(0x2fa5a0);
const BONE = hex(0xf0e6cc), CANVAS = hex(0xe6dcc0);
const EVENING: Sched = [18, 23.5, 1.4], SIGN: Sched = [17.5, 30.5, 1.4];

/** Draw with the frame turned `yaw` about the local point (x, z): `draw` is handed that point in the turned frame. */
function about(k: Kit, x: number, z: number, yaw: number, draw: (lx: number, lz: number) => void): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  k.turned(yaw, () => draw(x * c - z * s, x * s + z * c));
}

/** A ute: a cab up front (+x), an open tray behind. */
function ute(k: Kit, x: number, z: number, col: RGB): void {
  k.box(x, 0.02, z, 0.36, 0.04, 0.19, DARK);
  k.box(x, 0.06, z, 0.42, 0.07, 0.18, col);
  k.box(x + 0.05, 0.13, z, 0.13, 0.08, 0.16, GLASS_LIGHT, col);
  k.box(x - 0.12, 0.13, z, 0.17, 0.03, 0.18, scale(col, 0.8), DARK);
}

// ---- the roadhouse (3 × 2) ----------------------------------------------------------------------------

/** An outback roadhouse: a long low house under rusty tin with a deep veranda, two pumps, a tall sign, a tank. */
const roadhouse: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  const bx = -0.3, bz = -hd + 0.55, bw = W - 1.0, bd = 0.7;
  k.box(bx, 0.02, bz, bw, 0.4, bd, FADED);
  k.gable(bx, 0.42, bz, bw + 0.1, 0.16, bd + 0.1, RUST, FADED);
  // ribs of the tin, a shade darker
  for (let i = 0; i < 6; i++) {
    const rx = bx - bw / 2 + 0.2 + (i * (bw - 0.4)) / 5;
    k.bar([rx, 0.435, bz + bd / 2 + 0.05], [rx, 0.595, bz], 0.012, RUST_DARK);
  }
  // the veranda: a skillion of tin on posts along the front, a boardwalk under it
  const fz = bz + bd / 2, vd = 0.42;
  k.box(bx, 0.02, fz + vd / 2, bw, 0.03, vd, TIMBER);
  k.quad([bx - bw / 2 - 0.05, 0.43, fz], [bx + bw / 2 + 0.05, 0.43, fz], [bx + bw / 2 + 0.05, 0.33, fz + vd + 0.04], [bx - bw / 2 - 0.05, 0.33, fz + vd + 0.04], RUST_DARK, [bx, 0, fz + vd / 2]);
  k.quad([bx - bw / 2 - 0.05, 0.42, fz], [bx + bw / 2 + 0.05, 0.42, fz], [bx + bw / 2 + 0.05, 0.32, fz + vd + 0.04], [bx - bw / 2 - 0.05, 0.32, fz + vd + 0.04], scale(RUST_DARK, 0.7), [bx, 1, fz + vd / 2]);
  for (let i = 0; i < 5; i++) k.box(bx - bw / 2 + 0.04 + (i * (bw - 0.08)) / 4, 0.05, fz + vd - 0.03, 0.035, 0.28, 0.035, TIMBER);
  k.box(bx, 0.05, fz + 0.006, 0.16, 0.26, 0.012, hex(0x4a6a5a));
  for (const wx of [-0.7, -0.35, 0.35, 0.7]) k.pane(bx + wx, 0.17, fz, 0.16, 0.13, 1, DARK, EVENING, WARM_GLOW);
  // two old pumps under a small canopy on the forecourt
  const px = -0.55, pz = hd - 0.35;
  k.box(px, 0.02, pz, 0.6, 0.03, 0.2, hex(0xb0a898));
  for (const sx of [-1, 1]) {
    k.box(px + sx * 0.3, 0.02, pz, 0.035, 0.42, 0.035, WHITE);
    k.box(px + sx * 0.12, 0.05, pz, 0.08, 0.17, 0.06, sx < 0 ? hex(0xc2412f) : hex(0xe8dcc0), WHITE);
    k.cyl(px + sx * 0.12, 0.22, pz, 0.03, 0.04, WHITE, 6);
  }
  k.box(px, 0.44, pz, 0.85, 0.04, 0.42, WHITE, RUST);
  // the sign on its pole, lit all night
  const sx = hw - 0.3, sz = hd - 0.3;
  k.box(sx, 0.02, sz, 0.04, 1.0, 0.04, METAL);
  k.glowBox(sx, 0.85, sz, 0.42, 0.24, 0.05, hex(0xf2b52a), SIGN, SHOP_GLOW);
  k.box(sx, 0.78, sz, 0.3, 0.06, 0.06, hex(0xc2412f));
  // the water tank on its stand
  const tx = hw - 0.35, tz = -hd + 0.4;
  for (const [ax, az] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) k.bar([tx + ax * 0.14, 0.02, tz + az * 0.14], [tx + ax * 0.11, 0.5, tz + az * 0.11], 0.015, TIMBER);
  k.box(tx, 0.5, tz, 0.32, 0.02, 0.32, TIMBER);
  k.cyl(tx, 0.52, tz, 0.17, 0.26, METAL, 10, scale(METAL, 0.85));
  // a ute pulled up by the pumps
  ute(k, 0.45, hd - 0.32, r() < 0.5 ? hex(0xe8e2d0) : hex(0x3f7a9a));
};

// ---- a pueblo (2 × 2) ---------------------------------------------------------------------------------

/** A small adobe pueblo: mud-brick cubes stepping back, beam ends under the parapets, ladders, a bread oven. */
const pueblo: Draw = (k, W, D) => {
  const hd = D / 2;
  // one cube: a wall, a parapet round a slightly sunk roof, beam ends along the front
  const cube = (x: number, y: number, z: number, w: number, h: number, d: number, col: RGB) => {
    k.box(x, y, z, w, h, d, col, ADOBE_DARK);
    for (const s of [-1, 1]) {
      k.box(x, y + h, z + s * (d / 2 - 0.025), w, 0.04, 0.05, col);
      k.box(x + s * (w / 2 - 0.025), y + h, z, 0.05, 0.04, d - 0.1, col);
    }
    const n = Math.max(2, Math.round(w / 0.17));
    for (let i = 0; i < n; i++) k.box(x - w / 2 + ((i + 0.5) * w) / n, y + h - 0.09, z + d / 2 + 0.03, 0.03, 0.03, 0.07, TIMBER);
  };
  const ladder = (x: number, y0: number, y1: number, z: number) => {
    for (const s of [-1, 1]) k.bar([x + s * 0.035, y0, z + 0.12], [x + s * 0.035, y1 + 0.1, z], 0.009, TIMBER);
    for (let i = 1; i <= 3; i++) {
      const f = i / 4;
      k.bar([x - 0.035, y0 + (y1 - y0) * f, z + 0.12 * (1 - f)], [x + 0.035, y0 + (y1 - y0) * f, z + 0.12 * (1 - f)], 0.007, TIMBER);
    }
  };
  const z0 = -hd + 0.2;
  cube(-0.05, 0.02, z0 + 0.6, W - 0.5, 0.36, 1.2, ADOBE);
  cube(-0.22, 0.38, z0 + 0.42, 1.0, 0.32, 0.8, ADOBE_LIGHT);
  cube(-0.36, 0.7, z0 + 0.3, 0.55, 0.28, 0.5, ADOBE);
  const f1 = z0 + 1.2, f2 = z0 + 0.82, f3 = z0 + 0.55;
  // the turquoise door and the small deep windows
  k.box(-0.3, 0.02, f1 + 0.006, 0.13, 0.24, 0.012, TURQUOISE);
  k.pane(-0.62, 0.15, f1, 0.09, 0.09, 1, DARK, EVENING, WARM_GLOW);
  k.pane(0.25, 0.15, f1, 0.09, 0.09, 1, DARK, EVENING, WARM_GLOW);
  k.pane(-0.45, 0.5, f2, 0.09, 0.09, 1, DARK, EVENING, WARM_GLOW);
  k.box(-0.05, 0.4, f2 + 0.006, 0.1, 0.2, 0.012, TURQUOISE);
  k.pane(-0.36, 0.8, f3, 0.08, 0.08, 1, DARK, EVENING, WARM_GLOW);
  ladder(0.45, 0.02, 0.4, f1 + 0.02);
  ladder(0.12, 0.4, 0.72, f2 + 0.02);
  // the horno, and a few pots by the door
  const hx = W / 2 - 0.42, hz = hd - 0.3;
  k.dome(hx, 0.02, hz, 0.15, ADOBE_LIGHT, 8, 3);
  k.box(hx, 0.02, hz + 0.145, 0.07, 0.07, 0.02, DARK);
  k.cyl(-0.72, 0.02, hd - 0.22, 0.04, 0.08, hex(0xb5543f), 6, DARK);
  k.cyl(-0.6, 0.02, hd - 0.18, 0.03, 0.06, hex(0xd9c8a0), 6, DARK);
};

// ---- the fossil dig (3 × 3) ---------------------------------------------------------------------------

/** A fossil dig: a staked pit with a dinosaur half out of the red earth, a canvas shade, crates and a 4×4. */
const dinosaurDig: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, EARTH);
  // the pit: a dark floor inside a rim of spoil
  const px = 0.15, pz = 0.1, pw = 2.0, pd = 1.3;
  k.box(px, 0.02, pz, pw, 0.012, pd, PIT);
  for (const s of [-1, 1]) {
    k.box(px, 0.02, pz + s * (pd / 2 + 0.06), pw + 0.24, 0.09, 0.12, DUST);
    k.box(px + s * (pw / 2 + 0.06), 0.02, pz, 0.12, 0.09, pd, DUST);
  }
  // the skeleton: a curved spine from tail tip to neck, ribs, leg bones, a long skull
  const n = 14;
  const spine = (i: number): [number, number] => {
    const t = i / (n - 1);
    return [px - 0.85 + 1.3 * t, pz - 0.05 - 0.36 * Math.sin(t * Math.PI * 0.9) + 0.3 * t * t];
  };
  for (let i = 0; i < n; i++) {
    const [x, z] = spine(i), f = Math.sin((i / (n - 1)) * Math.PI), s = 0.05 + 0.06 * f;
    k.box(x, 0.032, z, 0.075, 0.04 + 0.04 * f, s, BONE);
    if (i >= 5 && i <= 10) {
      const len = 0.26 + 0.16 * Math.sin(((i - 5) / 5) * Math.PI);
      k.bar([x, 0.09, z], [x + 0.04, 0.06, z + len * 0.6], 0.02, BONE);
      k.bar([x + 0.04, 0.06, z + len * 0.6], [x - 0.02, 0.05, z + len], 0.018, BONE);
      k.bar([x, 0.09, z], [x + 0.03, 0.05, z - len * 0.35], 0.018, BONE);
    }
  }
  const [hx, hz] = spine(n - 1);
  k.box(hx + 0.24, 0.032, hz + 0.08, 0.36, 0.11, 0.2, BONE);
  k.box(hx + 0.5, 0.032, hz + 0.08, 0.2, 0.07, 0.15, scale(BONE, 0.92));
  k.box(hx + 0.2, 0.143, hz + 0.13, 0.08, 0.004, 0.06, DARK);
  k.box(hx + 0.2, 0.143, hz + 0.03, 0.08, 0.004, 0.06, DARK);
  const [lx, lz] = spine(5), [mx, mz] = spine(10);
  k.bar([lx, 0.05, lz + 0.05], [lx - 0.16, 0.05, lz + 0.45], 0.028, BONE);
  k.bar([lx - 0.16, 0.05, lz + 0.45], [lx + 0.1, 0.05, lz + 0.66], 0.022, BONE);
  k.bar([mx, 0.05, mz + 0.4], [mx + 0.2, 0.05, mz + 0.62], 0.022, BONE);
  // the string grid on its stakes
  const gy = 0.15;
  for (let i = 0; i <= 4; i++) {
    const x = px - pw / 2 + (i * pw) / 4;
    k.bar([x, gy, pz - pd / 2 - 0.06], [x, gy, pz + pd / 2 + 0.06], 0.006, WHITE);
    for (const s of [-1, 1]) k.box(x, 0.02, pz + s * (pd / 2 + 0.06), 0.025, gy, 0.025, TIMBER);
  }
  for (let j = 0; j <= 3; j++) {
    const z = pz - pd / 2 + (j * pd) / 3;
    k.bar([px - pw / 2 - 0.06, gy, z], [px + pw / 2 + 0.06, gy, z], 0.006, WHITE);
    for (const s of [-1, 1]) k.box(px + s * (pw / 2 + 0.06), 0.02, z, 0.025, gy, 0.025, TIMBER);
  }
  // the shade tent along the back, a trestle table and crates under and beside it
  const tx = -0.45, tz = -hd + 0.45, tw = 1.3, td = 0.6;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(tx + sx * (tw / 2 - 0.03), 0.02, tz + sz * (td / 2 - 0.03), 0.03, 0.4, 0.03, TIMBER);
  k.gable(tx, 0.42, tz, tw + 0.08, 0.16, td + 0.08, CANVAS, CANVAS);
  k.box(tx - 0.2, 0.02, tz, 0.5, 0.13, 0.2, TIMBER, hex(0xd9c8a0));
  k.glowBox(tx + 0.3, 0.36, tz, 0.05, 0.05, 0.05, hex(0xe8dcc0), EVENING, WARM_GLOW);
  for (let i = 0; i < 4; i++) {
    const s = 0.13 + r() * 0.05;
    k.box(tx + tw / 2 + 0.2 + (i % 2) * 0.22, 0.02 + (i > 2 ? 0.15 : 0), tz - 0.1 + (i === 1 ? 0.22 : 0) + r() * 0.04, s, s, s, hex(0xa98458), hex(0x8d6d48));
  }
  // wheelbarrow of spoil, and the 4×4 by the road
  k.dome(-hw + 0.3, 0.02, 0.95, 0.2, DUST, 7, 2);
  ute(k, hw - 0.55, hd - 0.28, hex(0xe8e2d0));
  k.box(hw - 0.6, 0.165, hd - 0.28, 0.2, 0.02, 0.15, DARK);
};

// ---- the buttes (the wonder, 14 × 14) -----------------------------------------------------------------

/**
 * One butte: a vertical-walled tower of banded sandstone on a talus skirt, with a thin thumb beside it on
 * the side `thumb` points to (0 for none).
 */
function butte(k: Kit, r: Rng, x: number, z: number, R: number, H: number, yaw: number, thumb: number): void {
  about(k, x, z, yaw, (lx, lz) => {
    const ty = H * 0.28;
    // the skirt, in two slopes, with a few fallen blocks on it
    k.band(lx, lz, 0.02, R * 2.05, ty * 0.55, R * 1.5, 11, TALUS);
    k.band(lx, lz, ty * 0.55, R * 1.5, ty, R * 1.12, 9, scale(TALUS, 0.92));
    k.cyl(lx, ty - 0.02, lz, R * 1.13, 0.02, TALUS, 9);
    for (let i = 0; i < 7; i++) {
      const a = r() * Math.PI * 2, d = R * (1.35 + r() * 0.6), s = 0.18 + r() * 0.22;
      const f = Math.max(0, Math.min(1, (R * 2.05 - d) / (R * 0.93)));
      k.box(lx + Math.cos(a) * d, ty * f - 0.08, lz + Math.sin(a) * d, s, s, s * 1.2, i % 2 ? ROCK : ROCK_DARK);
    }
    // the tower: a cluster of many-sided columns standing shoulder to shoulder, banded at the same heights
    // right across, so it reads as one jointed block of bedded rock
    const BANDS: [number, RGB][] = [[0.16, ROCK], [0.21, ROCK_DARK], [0.5, ROCK_LIGHT], [0.56, ROCK_DARK], [0.8, ROCK], [0.84, ROCK_DARK], [1.2, ROCK_LIGHT]];
    const column = (cx: number, cz: number, rx: number, rz: number, y0: number, top: number, seg: number) => {
      let y = y0;
      for (const [f, col] of BANDS) {
        const y1 = Math.min(top, ty + (H - ty) * f);
        if (y1 <= y) continue;
        const thin = col === ROCK_DARK ? 0.96 : 1;
        k.cyl(cx, y, cz, rx * thin, y1 - y, col, seg, y1 >= top ? ROCK_LIGHT : col, rz * thin);
        y = y1;
        if (y >= top) break;
      }
    };
    const n = 5;
    for (let i = 0; i < n; i++) {
      const u = i - (n - 1) / 2, edge = Math.abs(u) / ((n - 1) / 2);
      const cx = lx + u * R * 0.42 + (r() - 0.5) * R * 0.06, cz = lz + (r() - 0.5) * R * 0.14;
      column(cx, cz, R * (0.36 + r() * 0.06), R * (0.66 - edge * 0.16 + r() * 0.06), ty - 0.05, H * (1 - edge * 0.07 - (edge > 0 ? r() * 0.05 : 0)), 5 + ((i * 3) % 3));
    }
    // lower shoulders leaning on the front and back of it
    for (let i = 0; i < 4; i++) {
      const sx = (i % 2 ? 1 : -1) * R * (0.25 + r() * 0.45), sz = (i < 2 ? 1 : -1) * R * (0.5 + r() * 0.1);
      column(lx + sx, lz + sz, R * (0.26 + r() * 0.08), R * (0.24 + r() * 0.06), ty - 0.05, H * (0.5 + r() * 0.3), 5 + (i % 2));
    }
    if (thumb) {
      const tx = lx + thumb * R * 1.5;
      k.band(tx, lz, ty * 0.6, R * 0.6, ty * 1.2, R * 0.3, 7, TALUS);
      column(tx, lz + R * 0.05, R * 0.24, R * 0.2, ty * 1.15, H * 0.86, 5);
      column(tx - thumb * R * 0.22, lz - R * 0.05, R * 0.2, R * 0.2, ty * 1.0, H * 0.55, 6);
    }
  });
}

/** Three great sandstone buttes on their talus skirts, the Mittens with their thumbs, and a dirt loop between them. */
const monumentButtes: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.3, 0.02, D - 0.3, EARTH);
  butte(k, r, -hw + 3.0, -1.6, 1.35, 6.6, 0.35, 1);
  butte(k, r, hw - 3.0, -0.9, 1.3, 7.4, -0.4 + Math.PI, 1);
  butte(k, r, 0.4, -hd + 2.9, 1.4, 5.6, 0.1, 0);
  // the dirt loop on the open ground between them, and the track in from the road
  k.band(0, 2.6, 0.022, 2.5, 0.034, 2.1, 20, DUST);
  k.box(0, 0.02, hd - 1.0, 0.4, 0.012, 1.7, DUST);
  // the visitor shelter by the front edge: a tin roof on posts, a bench, a sign
  const sx = 2.4, sz = hd - 0.8;
  for (const ax of [-1, 1]) for (const az of [-1, 1]) k.box(sx + ax * 0.5, 0.02, sz + az * 0.3, 0.05, 0.42, 0.05, TIMBER);
  k.box(sx, 0.02, sz, 1.15, 0.025, 0.75, hex(0xb0a898));
  k.gable(sx, 0.44, sz, 1.25, 0.16, 0.85, RUST, RUST_DARK);
  k.box(sx, 0.045, sz - 0.15, 0.7, 0.09, 0.12, TIMBER);
  k.box(sx - 1.0, 0.02, sz + 0.2, 0.04, 0.3, 0.04, TIMBER);
  k.box(sx - 1.0, 0.22, sz + 0.2, 0.3, 0.18, 0.04, hex(0xe8dcc0));
  ute(k, 1.0, hd - 0.75, hex(0x5f7f8a));
  // scrub and loose boulders about the floor
  for (let i = 0; i < 14; i++) {
    const x = (r() - 0.5) * (W - 1.2), z = hd - 0.6 - r() * 5.2;
    if (Math.hypot(x, z - 2.6) > 1.9 && Math.hypot(x, z - 2.6) < 2.7) continue;
    if (i % 3 === 0) k.box(x, 0.02, z, 0.16 + r() * 0.14, 0.1 + r() * 0.1, 0.16 + r() * 0.12, ROCK_DARK);
    else k.dome(x, 0.02, z, 0.09 + r() * 0.06, hex(0x8a9460), 6, 2);
  }
};

export const REDROCK_DRAW: Partial<Record<RegionBuildingKind, Draw>> = { roadhouse, pueblo, dinosaurDig, monumentButtes };
