  k.cone(0, 1.55, 0.06, 0.06, 0.07, GOLD, 6);
  k.box(0, 1.58, 0.06, 0.015, 0.03, 0.015, GOLD);
  // the barrier, down across the lane
  k.box(0.46, 0.02, 0.28, 0.07, 0.16, 0.07, WHITE);
  for (let i = 0; i < 5; i++) k.box(0.36 - i * 0.18, 0.15, 0.28, 0.18, 0.035, 0.035, i % 2 ? WHITE : PINK);
  k.box(-0.52, 0.02, 0.28, 0.03, 0.14, 0.03, METAL);
  // the guard's booth, its window on the lane
