  k.detail(() => {
    for (let i = 1; i < 9; i++) k.box(0, 0.02 + i * 0.088, z, w + 0.006, 0.01, d + 0.006, scale(TAR, 1.6));
  });
  k.gable(0, 0.82, z, w + 0.08, 0.3, d + 0.08, hex(0x34363a), TAR, true);
  const f = z + d / 2;
  k.box(0, 0.08, f + 0.008, 0.26, 0.42, 0.016, SEA);
  k.box(0, 0.08, f + 0.018, 0.012, 0.42, 0.008, SEA_DEEP);
  k.box(0, 0.56, f + 0.008, 0.2, 0.2, 0.016, SEA);
  k.box(0, 0.98, f + 0.06, 0.04, 0.04, 0.2, WOOD);
