/**
 * The online world's date for the sign-in card, from the server's day (1 on the first): "Year 251, Winter", a season
 * a day as the game's own calendar turns (render/season.ts), in place of "day 1004" (the user, 4 Nov 2026).
 */
function worldDate(day: number): string {
  const d = Math.max(0, Math.floor(day) - 1);
  const season = ['Spring', 'Summer', 'Autumn', 'Winter'][d % DAYS_PER_YEAR % 4];
  return `Year ${Math.floor(d / DAYS_PER_YEAR) + 1}, ${season}`;
}

/**
 * The title screen's menus (docs/title.html, "The screens"): the title panel over the reel, the
 * new-game panel, saved games with its players and slot cards, and the pause card. Plain DOM in the
 * chip look of the V and O menus. Everything is reachable from the keyboard: up and down move
 * through the panel's controls (a row of cards counts as one stop; left and right move along it),
 * Enter activates, Escape goes back a level. While a panel is open no key reaches the game.
 */

