/**
 * The sign-in title's layout (the user, 23 Oct 2026). 'panel': the card down the left, as it has been.
 * 'centre': the wordmark large and centred over the world with no card behind it, the sign-in card centred
 * under it, Settings as a wheel in the corner (no Passport), and the week in the world as a newspaper, one pick at a time. `?login=centre`
 * or `?login=panel` picks one, and this device keeps it. 'centre' is the default since 23 Oct 2026 (the user).
 */
type TitleLayout = 'panel' | 'centre';
const LAYOUT_KEY = 'tinyfleet-login-layout';
function titleLayout(): TitleLayout {
  try {
    const q = new URLSearchParams(location.search).get('login');
    if (q === 'centre' || q === 'center' || q === 'panel') {
      const v: TitleLayout = q === 'panel' ? 'panel' : 'centre';
      localStorage.setItem(LAYOUT_KEY, v);
      return v;
    }
    return localStorage.getItem(LAYOUT_KEY) === 'panel' ? 'panel' : 'centre';
  } catch { return 'centre'; }
}
const TITLE_LAYOUT: TitleLayout = titleLayout();
