const PICK_SECS = 6, PICK_FADE = 350;
/** A tagline at random, never the one just shown. */
/**
 * Offer to keep a name and PIN in the browser's password manager once they have signed in. Chrome and Edge
 * ask through the Credential Management API; the others notice the sign-in form being sent and ask themselves.
 */
function rememberLogin(name: string, pin: string): void {
  const W = window as unknown as { PasswordCredential?: new (d: { id: string; password: string; name?: string }) => Credential };
  if (!name || !pin || !W.PasswordCredential || !navigator.credentials?.store) return;
  try { void navigator.credentials.store(new W.PasswordCredential({ id: name, password: pin, name })).catch(() => { /* declined or unsupported */ }); } catch { /* not here */ }
}

function nextTagline(was: string | null, rand: () => number = Math.random): string {
  const pool = TAGLINES.filter((t) => t !== was);
  return pool[Math.floor(rand() * pool.length)] ?? TAGLINES[0] ?? '';
}
