function clock(hour: number): string {
  const h = ((hour % 24) + 24) % 24;
  return `${String(Math.floor(h)).padStart(2, '0')}:${String(Math.floor((h % 1) * 60)).padStart(2, '0')}`;
}

function played(s = 0): string {
  const m = Math.floor(s / 60);
  if (m < 1) return 'under a minute played';
  if (m < 60) return `${m} min played`;
  return `${Math.floor(m / 60)} h ${m % 60} min played`;
}

function ago(t?: number): string {
  if (!t) return 'not saved yet';
  const s = (Date.now() - t) / 1000;
  if (s < 45) return 'saved just now';
  if (s < 90) return 'saved a minute ago';
  if (s < 3600) return `saved ${Math.round(s / 60)} min ago`;
  if (s < 5400) return 'saved an hour ago';
  if (s < 86400) return `saved ${Math.round(s / 3600)} h ago`;
  if (s < 172800) return 'saved yesterday';
  if (s < 30 * 86400) return `saved ${Math.round(s / 86400)} days ago`;
  return `saved ${new Date(t).toLocaleDateString()}`;
}

const plural = (n: number, one: string, many = `${one}s`): string => `${n.toLocaleString('en-US')} ${n === 1 ? one : many}`;

const modeOf = (s: SaveGame): WorldMode => s.mode ?? parseSeed(s.seed).mode;

/**
 * How a saved game is named on the title screens: the fleet's badge and name, never the world's seed
 * (a game from before fleets had names shows its label, or just "Your fleet").
 */
function fleetTag(s: SaveGame, cls: string, size = 18): HTMLElement {
  const el = h('div', `${cls} tm-fleettag`);
  const b = readBrand(s.brand);
  if (b) el.innerHTML = badgeHtml(b, size);
  el.append(b ? ` ${b.name}` : s.label || 'Your fleet');
  return el;
}

function h<K extends keyof HTMLElementTagNameMap>(tag: K, cls = '', text = ''): HTMLElementTagNameMap[K] {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text) e.textContent = text;
  return e;
}

/** Perceived lightness, 0 to 1. */
/** WCAG relative luminance of a 0xRRGGBB colour, and the contrast ratio of two (1 to 21). */
const lumOf = (c: number): number => {
  const ch = (v: number) => { const s = v / 255; return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * ch((c >> 16) & 255) + 0.7152 * ch((c >> 8) & 255) + 0.0722 * ch(c & 255);
};
const contrast = (a: number, b: number): number => { const x = lumOf(a), y = lumOf(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
/** Text for a button in the fleet's colours: its accent where that reads on its body colour, else white or ink, whichever reads better. */
function fleetInk(primary: number, accent: number): number {
  if (contrast(primary, accent) >= 4.5) return accent;
  return contrast(primary, 0xffffff) >= contrast(primary, 0x1f2b33) ? 0xffffff : 0x1f2b33;
}
const lightOf = (c: number): number => (0.299 * ((c >> 16) & 255) + 0.587 * ((c >> 8) & 255) + 0.114 * (c & 255)) / 255;

/** A colour as hue (0–360), saturation and value (0–1). */
function toHsv(c: number): [number, number, number] {
  const r = ((c >> 16) & 255) / 255, g = ((c >> 8) & 255) / 255, b = (c & 255) / 255;
  const max = Math.max(r, g, b), d = max - Math.min(r, g, b);
  let hue = 0;
  if (d) hue = max === r ? ((g - b) / d + 6) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return [hue * 60, max ? d / max : 0, max];
}

function fromHsv([hue, s, v]: [number, number, number]): number {
  const f = (n: number): number => {
    const k = (n + hue / 60) % 6;
    return Math.round(255 * (v - v * s * Math.max(0, Math.min(k, 4 - k, 1))));
  };
  return (f(5) << 16) | (f(3) << 8) | f(1);
}

function dot(colour: number): HTMLElement {
  const d = h('i', 'tm-dot');
  d.style.background = hex(colour);
  return d;
}

/** The explored map of a save, drawn into a small canvas. */
function thumb(save: SaveGame, cls = 'tm-thumb'): HTMLCanvasElement {
  const c = h('canvas', cls);
  c.width = 128;
  c.height = 128;
  try { drawExplored(c, save.explored ?? {}, 4, save.cell); } catch { /* an unreadable map stays black */ }
  return c;
}

/**
 * Local play (New Local Game, Continue and Saved games on this computer): off while every player is
 * sent through Play Online, where the player is made with a name and a PIN. Turn back on to offer it.
 */
const LOCAL_PLAY = false;

/** "Last saved 12 s ago", for the online pause card: when the career last reached the server. */
function savedAgo(at: number): string {
  if (!at) return 'Saves to the server every 40 s as you play';
  const s = Math.max(0, Math.round((Date.now() - at) / 1000));
  if (s < 5) return 'Last saved just now';
  if (s < 90) return `Last saved ${s} s ago`;
  return `Last saved ${Math.round(s / 60)} min ago`;
}

