  private buildPause(): void {
    const online = this.host.online.active();
    const head = h('h2', '', online ? 'Online' : 'Paused');
    head.append(h('span', '', '.'));
    this.panel.append(head);
    if (online) this.panel.append(h('div', 'tm-note', 'The world carries on while this is open: everyone else is still playing.'));
    // a fleet made in one click from a postcard: kept only in this browser until it has a name and a PIN
    if (online && this.host.online.auto()) {
      this.panel.append(h('div', 'tm-err', 'This fleet lives in this browser only. Give it a name and a PIN to keep it, and to play it anywhere.'));
      this.panel.append(this.button('Save your fleet', 'primary', 'p-keep', () => { this.kp = { name: '', pin: '', pin2: '', error: '', busy: false }; this.keepFrom = 'pause'; this.go('keep'); }));
    }
    else if (conflicted()) this.panel.append(h('div', 'tm-err', 'Another tab saved this slot later, so autosave is off here.'));
    this.panel.append(this.button('Resume', 'primary', 'p-resume', () => this.resume()));
    // online the career goes to the server on its own every 40 s, on signing out and on closing the tab: no
    // button for it, only when it last went (at the foot of the card, below)
    if (!online) {
      this.panel.append(this.button('Save now', '', 'p-save', () => {
        this.saveLine = this.host.saveNow();
        this.rerender('p-save');
      }));
      if (this.saveLine) this.panel.append(h('div', 'tm-note saved', this.saveLine));
    }
    // the fleet's own button, in its colours; its players and invites are inside it (docs/sharedfleets.html)
    const fleetBtn = this.button('Your fleet', 'tm-fleetbtn', 'p-fleet', () => this.showFleet());
    const fb = this.host.fleetBrand();
    if (fb) {
      const ink = fleetInk(fb.primary, fb.accent);
      fleetBtn.style.setProperty('--fleet', hex(fb.primary));
      fleetBtn.style.setProperty('--fleet-ink', hex(ink));
    }
    this.panel.append(fleetBtn);
    this.panel.append(
      this.button('Passport', '', 'p-deeds', () => this.showDeeds('pause')),
      this.button('Settings', '', 'p-settings', () => this.host.openSettings()),
      this.button('Feedback', '', 'p-feedback', () => { this.fb.error = ''; this.fb.sent = false; this.go('feedback'); }),
      this.button(online ? 'Sign out' : 'Back to title', '', 'p-title', () => { this.hide(); this.host.backToTitle(); }),
      this.keys([['Esc', 'resume']]),
    );
    clearInterval(this.savedTimer);
    if (online) {
      const line = h('div', 'tm-note tm-lastsaved', savedAgo(this.host.online.lastSaved()));
      this.panel.append(line);
      this.savedTimer = window.setInterval(() => { line.textContent = savedAgo(this.host.online.lastSaved()); }, 1000);
    }
  }

