  private kp = { name: '', pin: '', pin2: '', error: '', busy: false };
  /** Where the keep card was opened from: the pause card, or the guest's red tile over the missions (back to driving). */
  private keepFrom: 'pause' | 'tile' = 'pause';

  /** The guest's red tile (main.ts): the keep card straight over the game. */
