  private buildKeep(): void {
    const head = h('header', 'tm-head');
    const h2 = h('h2', '', 'Save your fleet');
    h2.append(h('span', '', '.'));
    head.append(h2, this.button('← Back', 'link', 'back', () => this.keepBack()));
    this.panel.append(head);
    this.panel.append(h('div', 'tm-note', 'Pick a name to sign in with and a PIN, and the fleet is yours for good, on any computer. Everything you have stays as it is.'));
    const kp = this.kp;
    // a real form, named for password managers: the browser offers to keep the new name and PIN
    const form = h('form', 'tm-form');
    form.method = 'post';
    form.action = '#';
    form.autocomplete = 'on';
    const field = (label: string, value: string, key: string, type: string, max: number, set: (v: string) => void, hint: string, name: string, auto: AutoFill) => {
      const input = h('input', 'tm-nameinput');
      input.type = type; input.maxLength = max; input.value = value; input.placeholder = hint;
      input.spellcheck = false; input.autocomplete = auto; input.name = name; input.id = `tm-k-${name}`; input.dataset.k = key; input.disabled = kp.busy;
      input.addEventListener('input', () => set(input.value));
      const lab = h('label', '', label);
      lab.htmlFor = input.id;
      form.append(lab, input);
    };
    field('Name', kp.name, 'k-name', 'text', 16, (v) => { kp.name = v; }, '3–16 letters, digits, - or _', 'username', 'username');
    field('PIN', kp.pin, 'k-pin', 'password', 32, (v) => { kp.pin = v; }, '4 or more characters', 'password', 'new-password');
    field('PIN again', kp.pin2, 'k-pin2', 'password', 32, (v) => { kp.pin2 = v; }, 'the same PIN, to be sure', 'password2', 'new-password');
    if (kp.error) form.append(h('div', 'tm-err', kp.error));
    form.addEventListener('submit', (e) => { e.preventDefault(); void this.keepFleet(); });
    const go = this.button(kp.busy ? 'Saving…' : 'Save my fleet', 'small primary', 'k-ok', () => { /* the form's submit */ }, 'form');
    go.type = 'submit';
    go.disabled = kp.busy;
    const row = h('div', 'tm-row');
    row.append(go);
    form.append(row);
    this.panel.append(form, this.keys([['Enter', 'keep'], ['Esc', 'back']]));
  }

  private async keepFleet(): Promise<void> {
    const kp = this.kp;
    const name = kp.name.trim();
    if (!/^[A-Za-z0-9_-]{3,16}$/.test(name)) { kp.error = 'A name is 3 to 16 letters, digits, - or _.'; this.rerender('k-name'); return; }
    if (kp.pin.length < 4) { kp.error = 'A PIN is 4 or more characters.'; this.rerender('k-pin'); return; }
    if (kp.pin !== kp.pin2) { kp.error = 'The two PINs aren’t the same: type it again.'; kp.pin2 = ''; this.rerender('k-pin2'); return; }
    kp.busy = true; kp.error = '';
    this.rerender('k-ok');
    const r = await this.host.online.keep(name, kp.pin);
    kp.busy = false;
    if (!r.ok) { kp.error = r.why; this.rerender('k-name'); return; }
    rememberLogin(name, kp.pin);
    this.kp = { name: '', pin: '', pin2: '', error: '', busy: false };
    if (this.keepFrom === 'tile') { this.resume(); return; }
    this.go('pause');
    this.saveLine = `Saved: sign in as ${name} with your PIN from any computer.`;
    this.rerender('p-resume');
  }

