import { hex, scale, type RGB } from '../../world/biomes';
import type { Sched } from '../nightLights';
import { DARK, TAU, type Draw, type Kit, type P3 } from './kit';
import { frontText } from './neon';

/**
 * Rome's own buildings, for a city built in the `roman` style (world/towns.ts: STYLE_SWAPS and STYLE_CORE put
 * them in a city or bigger; a village keeps its little temple and its forum). Each stands on its lot centred on
 * the origin, its front to +z:
 *
 * - **The Colosseum** (for an arena or a stadium, and one in every Roman city): three storeys of arches and the
 *   blind attic over them round an oval, the outer ring fallen on one side down to the inner one with a brick
 *   buttress at each broken end, the cavea stepping down inside to the arena, half of it floored again in timber
 *   and half open on the brick walls of the hypogeum. Its arches are lit amber after dark.
 * - **The Circus Maximus** (one in every Roman city): the long chariot course, stands round three sides on an
 *   arcaded wall, the twelve starting gates across the straight end between their towers, the spina down the
 *   middle with its turning posts, obelisks and lap counters, the emperor's box over the course, the arch at the
 *   round end; and four quadrigas, red, white, green and blue, racing round it through the day.
 * - **The Pantheon** (for a temple, and one in every Roman city): the brick drum and its shallow stepped dome with
 *   the oculus open to the sky, the granite portico with Agrippa's name on the frieze, its piazza and fountain.
 * - **St Peter's** (for a cathedral, and one in every Roman city): the basilica's front with the dome over the
 *   crossing, and Bernini's colonnade embracing the square in front with the obelisk in the middle.
 * - **The Vittoriano** (for a skyscraper, and one in every Roman city): the white marble wedding cake, its stair,
 *   the curved colonnade, the gilded quadrigas over the propylaea, the king on his horse and the flame.
 * - **The Trevi Fountain** (for a fountain square): the palace front as a triumphal arch, Oceanus in his niche,
 *   the sea horses and the rocks, the basin glowing turquoise at night.
 * - **The Spanish Steps** (for plaza steps): the butterfly stair up to the twin-towered church and its obelisk,
 *   the half-sunk boat of the Barcaccia at their foot.
 */

const TRAV = hex(0xe8dec8), TRAV_SHADE = hex(0xcfc2a6), TRAV_LIGHT = hex(0xf2ebdc), BRICK = hex(0xa8624a);
const BRICK_DARK = hex(0x8a4e3a), DEPTH = hex(0x4a3c30), MARBLE = hex(0xf4f1e8), MARBLE_SHADE = hex(0xdcd8cc);
const PIT = hex(0x7a6650), DECK = hex(0x9a7a52), SAND = hex(0xdcc69a), GILT = hex(0xc8a040), BRONZE = hex(0x6a5a3a);
const LEAD = hex(0x8a9096), LEAD_BLUE = hex(0x8a9ea6), GRANITE = hex(0x9a948c), STUCCO = hex(0xd8c4a4), PAVE = hex(0xd8d0c0);
const OCHRE = hex(0xd89a5a), TERRACOTTA = hex(0xb5603a), WATER_DAY = hex(0x4ab8c8), WATER_GLOW = hex(0x6ae8f0);
const HORSE = hex(0x6a4a32), HORSE_DARK = hex(0x4a3424), SKIN = hex(0xd8a882), AZALEA = hex(0xe86a9a), FOLIAGE = hex(0x4f8a46);
const ARCH_GLOW = hex(0xffbe6a);
/** Arches and windows lit from dusk; the water from dusk too, but softer. */
const LIT: Sched = [18, 29.5, 1.6], WATER_LIT: Sched = [18, 30, 1.2], FLAME: Sched = [0, 36, 2];

/** Draw in a frame turned so local +z points along (nx, nz) at the point (x, z): `draw` is given that point in the turned frame. */
function facing(k: Kit, x: number, z: number, nx: number, nz: number, draw: (u: number, v: number) => void): void {
  const yaw = Math.atan2(nx, nz), c = Math.cos(yaw), s = Math.sin(yaw);
  k.turned(yaw, () => draw(x * c - z * s, x * s + z * c));
}

/** A box running in plan from (ax, az) to (bx, bz), t thick across it, standing on y and h tall. */
function span(k: Kit, ax: number, az: number, bx: number, bz: number, y: number, h: number, t: number, col: RGB, top: RGB = col): void {
  const dx = bx - ax, dz = bz - az, L = Math.hypot(dx, dz);
  if (L < 1e-4) return;
  facing(k, (ax + bx) / 2, (az + bz) / 2, dz, -dx, (u, v) => k.box(u, y, v, L, h, t, col, top));
}

/** A tapering obelisk on its plinth, the pyramidion gilded. */
function obelisk(k: Kit, x: number, z: number, h: number, y = 0): void {
  k.box(x, y, z, h * 0.16, h * 0.1, h * 0.16, TRAV_SHADE);
  k.box(x, y + h * 0.1, z, h * 0.09, h * 0.55, h * 0.09, GRANITE);
  k.box(x, y + h * 0.65, z, h * 0.075, h * 0.27, h * 0.075, GRANITE);
  k.hip(x, y + h * 0.92, z, h * 0.075, h * 0.08, h * 0.075, GILT);
}

/** A white figure on a little plinth: the statues along every Roman skyline. */
function statue(k: Kit, x: number, y: number, z: number, s: number, col: RGB = MARBLE): void {
  k.box(x, y, z, s * 0.5, s * 0.25, s * 0.5, col);
  k.box(x, y + s * 0.25, z, s * 0.3, s * 0.6, s * 0.25, col);
  k.box(x, y + s * 0.85, z, s * 0.18, s * 0.18, s * 0.18, col);
}

/** A quadriga facing +z: four horses abreast, the car behind them and the driver in it. */
function quadriga(k: Kit, x: number, y: number, z: number, s: number, horse: RGB, car: RGB, driver: RGB): void {
  for (let i = 0; i < 4; i++) {
    const hx = x + (i - 1.5) * 0.04 * s;
    k.box(hx, y, z + 0.12 * s, 0.022 * s, 0.05 * s, 0.08 * s, scale(horse, 0.8));
    k.box(hx, y + 0.05 * s, z + 0.12 * s, 0.028 * s, 0.045 * s, 0.11 * s, horse);
    k.box(hx, y + 0.08 * s, z + 0.19 * s, 0.022 * s, 0.055 * s, 0.035 * s, horse);
  }
  k.box(x, y + 0.035 * s, z - 0.03 * s, 0.11 * s, 0.06 * s, 0.07 * s, car);
  for (const sx of [-1, 1]) k.box(x + sx * 0.065 * s, y, z - 0.035 * s, 0.014 * s, 0.065 * s, 0.065 * s, scale(car, 0.6));
  k.box(x, y + 0.06 * s, z - 0.035 * s, 0.035 * s, 0.09 * s, 0.03 * s, driver);
  k.box(x, y + 0.15 * s, z - 0.035 * s, 0.025 * s, 0.025 * s, 0.025 * s, driver === GILT ? GILT : SKIN);
}

// ---- the Colosseum ----------------------------------------------------------------------------------

/** One bay of an arcade round an ellipse (semi-axes ax, az scaled by f), from angle a0 to a1, `storeys` high. */
function arcadeBay(
  k: Kit, ax: number, az: number, f: number, a0: number, a1: number, storeys: number, h: number, t: number,
  stone: RGB, columns: boolean,
): void {
  const x0 = Math.cos(a0) * ax * f, z0 = Math.sin(a0) * az * f, x1 = Math.cos(a1) * ax * f, z1 = Math.sin(a1) * az * f;
  const L = Math.hypot(x1 - x0, z1 - z0) + 0.02, open = L - 0.14;
  facing(k, (x0 + x1) / 2, (z0 + z1) / 2, z1 - z0, -(x1 - x0), (u, v) => {
    for (let s = 0; s < storeys; s++) {
      const y = s * h, oc = u + 0.07;
      // the pier, the wall over the arch, its haunches rounding the opening's top corners
      k.box(u - L / 2 + 0.07, y, v, 0.14, h, t, stone);
      k.box(oc, y + h * 0.64, v, open, h * 0.36, t, stone);
      for (const sx of [-1, 1]) k.box(oc + sx * (open / 2 - 0.03), y + h * 0.54, v + t * 0.2, 0.06, h * 0.1, t * 0.6, stone);
      // the engaged half-column against the pier, and the deep of the arch, lit amber after dark
      if (columns) k.box(u - L / 2 + 0.07, y, v + t / 2 + 0.012, 0.06, h - 0.04, 0.024, TRAV_LIGHT);
      k.glowBox(oc, y, v - t * 0.25, open - 0.02, h * 0.62, 0.05, DEPTH, LIT, ARCH_GLOW);
    }
  });
}

/** A band of quads round an ellipse from (f0, y0) to (f1, y1), facing away from the point (fi, yi) beside its middle. */
function ellBand(k: Kit, ax: number, az: number, f0: number, y0: number, f1: number, y1: number, seg: number, col: RGB, fi: number, yi: number, from = 0, to = TAU): void {
  for (let s = 0; s < seg; s++) {
    const a0 = from + ((to - from) * s) / seg, a1 = from + ((to - from) * (s + 1)) / seg, am = (a0 + a1) / 2;
    const p = (a: number, f: number, y: number): P3 => [Math.cos(a) * ax * f, y, Math.sin(a) * az * f];
    k.quad(p(a0, f0, y0), p(a1, f0, y0), p(a1, f1, y1), p(a0, f1, y1), col, p(am, fi, yi));
  }
}

const colosseum: Draw = (k, W, D) => {
  const ax = W / 2 - 0.3, az = D / 2 - 0.3, n = 20, h = 0.4, attic = 0.34, t = 0.2, top = 3 * h + attic;
  // the outer ring is fallen on one side, down to the inner one: storeys standing at angle a
  const RUIN = -Math.PI / 2 + 0.6;
  const standing = (a: number) => {
    const d = Math.abs((((a - RUIN) % TAU) + TAU + Math.PI) % TAU - Math.PI);
    return d > 1.0 ? 4 : d > 0.8 ? 3 : d > 0.6 ? 2 : d > 0.42 ? 1 : 0;
  };
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * TAU, a1 = ((i + 1) / n) * TAU, am = (a0 + a1) / 2, s = standing(am);
    arcadeBay(k, ax, az, 1, a0, a1, Math.min(3, s), h, t, TRAV, true);
    if (s === 4) {
      // the attic: blind wall between pilasters, a window every other bay, corbels and the awning masts
      const x0 = Math.cos(a0) * ax, z0 = Math.sin(a0) * az, x1 = Math.cos(a1) * ax, z1 = Math.sin(a1) * az;
      const L = Math.hypot(x1 - x0, z1 - z0) + 0.02;
      facing(k, (x0 + x1) / 2, (z0 + z1) / 2, z1 - z0, -(x1 - x0), (u, v) => {
        k.box(u, 3 * h, v, L, attic, t, TRAV);
        k.box(u - L / 2 + 0.07, 3 * h + 0.02, v + t / 2 + 0.01, 0.045, attic - 0.07, 0.022, TRAV_LIGHT);
        if (i % 2 === 0) k.box(u, 3 * h + attic * 0.42, v + t / 2 + 0.002, 0.11, 0.08, 0.012, DEPTH);
        k.box(u, top - 0.035, v + 0.012, L + 0.01, 0.035, t + 0.03, TRAV_SHADE);
        if (i % 2 === 1) k.box(u, top, v + t / 2 - 0.03, 0.022, 0.2, 0.022, hex(0x6e4a2a));
      });
    } else {
      // where it has fallen, the inner ring stands bare behind, plainer and a little lower
      arcadeBay(k, ax, az, 0.87, a0, a1, 3, h * 0.94, t * 0.8, TRAV_SHADE, false);
      // and where the break begins, the brick buttress the restorers built against the broken end
      for (const [a, other] of [[a0, standing(a0 - 0.01)], [a1, standing(a1 + 0.01)]] as const) {
        if (other !== 4) continue;
        facing(k, Math.cos(a) * ax * 0.94, Math.sin(a) * az * 0.94, -Math.sin(a) * az, Math.cos(a) * ax, (u, v) => {
          k.box(u, 0, v, 0.3, top * 0.92, 0.2, BRICK);
          k.box(u, top * 0.92, v, 0.24, 0.05, 0.16, BRICK_DARK);
        });
      }
    }
  }
  // the cornice over each storey of the standing ring (a band round the whole oval reads as one building)
  for (let s = 1; s <= 3; s++) ellBand(k, ax + 0.02, az + 0.02, 1, s * h - 0.04, 1, s * h, n, TRAV_SHADE, 0.9, s * h - 0.02);
  // the cavea: four bands of seating stepping down to the podium, marble for the senators at the bottom,
  // weathered travertine, then the bare brick of the vaults where the upper seats have gone
  const F = [0.46, 0.56, 0.66, 0.76, 0.86], Y = [0.24, 0.46, 0.68, 0.9, 1.12];
  const SEATS = [TRAV_SHADE, hex(0xd8ccb0), hex(0xc4b090), hex(0xb08060)];
  for (let j = 0; j < 4; j++) {
    const f0 = F[j], f1 = F[j + 1], y0 = Y[j], y1 = Y[j + 1] - 0.05;
    ellBand(k, ax, az, f0, y0, f1, y1, 24, SEATS[j], (f0 + f1) / 2, (y0 + y1) / 2 - 0.2);
    ellBand(k, ax, az, f1, y1, f1, Y[j + 1], 24, scale(SEATS[j], 0.82), f1 + 0.05, y1);
  }
  // the podium wall round the arena, and the arena: its timber floor at one end and the hypogeum open at the other
  ellBand(k, ax, az, F[0], 0, F[0], Y[0], 24, MARBLE, F[0] + 0.05, 0.12);
  const rx = ax * F[0], rz = az * F[0];
  k.cyl(0, 0, 0, rx, 0.012, PIT, 20, PIT, rz);
  const deckFrom = rx * 0.25, half = (x: number) => rz * 0.97 * Math.sqrt(Math.max(0, 1 - (x / rx) ** 2));
  for (const fz of [-0.6, -0.3, 0, 0.3, 0.6]) {
    const zz = fz * rz, ext = rx * 0.95 * Math.sqrt(1 - fz * fz);
    k.box((-ext + deckFrom) / 2, 0, zz, deckFrom + ext, 0.15, 0.035, BRICK);
  }
  for (let x = -rx * 0.8; x < deckFrom; x += 0.22) k.box(x, 0, 0, 0.03, 0.12, half(x) * 2 * 0.95, BRICK_DARK);
  for (let x = deckFrom; x < rx - 0.04; x += 0.12) {
    const xm = Math.min(x + 0.06, rx - 0.02);
    k.box(xm, 0, 0, 0.115, 0.17, half(xm) * 2, DECK);
  }
};

// ---- the Circus Maximus -----------------------------------------------------------------------------

/** The four factions of the circus: the reds, the whites, the greens and the blues. */
const FACTIONS = [0xc8282a, 0xf2f0e8, 0x2f8a3a, 0x2f5fb8];

const circusMaximus: Draw = (k, W, D, _b, r) => {
  const hx = W / 2 - 0.08, R = D / 2 - 0.08, stand = Math.min(0.55, D * 0.19), gates = 0.5, wall = 0.72, seatTop = 0.62, seatFoot = 0.16;
  const xc = hx - R, x0 = -hx + gates;
  // the outline of the stands round the long U, outer face first: each node with its outward normal
  const nodes: [number, number, number, number][] = [];
  const nS = Math.max(4, Math.round((xc - x0) / 0.8)), nC = 12;
  for (let i = 0; i <= nS; i++) nodes.push([x0 + ((xc - x0) * i) / nS, R, 0, 1]);
  for (let i = 1; i < nC; i++) {
    const th = Math.PI / 2 - (Math.PI * i) / nC;
    nodes.push([xc + R * Math.cos(th), R * Math.sin(th), Math.cos(th), Math.sin(th)]);
  }
  for (let i = 0; i <= nS; i++) nodes.push([xc - ((xc - x0) * i) / nS, -R, 0, -1]);
  const at = (j: number, e: number, y: number): P3 => [nodes[j][0] - nodes[j][2] * e, y, nodes[j][1] - nodes[j][3] * e];
  const mid = (j: number, e: number, y: number): P3 => {
    const a = at(j, e, y), b = at(j + 1, e, y);
    return [(a[0] + b[0]) / 2, y, (a[2] + b[2]) / 2];
  };
  const rows = [TRAV, TRAV_SHADE, TRAV];
  // the emperor's box over the far straight (drawn below): the arches it stands in front of are left out
  const px = (x0 + xc) / 2, pz = -R + stand * 0.45, boxHalf = 0.35;
  for (let j = 0; j + 1 < nodes.length; j++) {
    const q = (e0: number, y0: number, e1: number, y1: number, col: RGB, ins: P3) => k.quad(at(j, e0, y0), at(j + 1, e0, y0), at(j + 1, e1, y1), at(j, e1, y1), col, ins);
    // the outer wall and its top, the step down to the seats, three bands of seats, the podium over the sand
    q(0, 0, 0, wall, OCHRE, mid(j, 0.1, wall / 2));
    q(0, wall, 0.1, wall, TRAV_LIGHT, mid(j, 0.05, wall - 0.1));
    q(0.1, wall, 0.1, seatTop, TRAV_SHADE, mid(j, 0.05, seatTop));
    for (let s = 0; s < 3; s++) {
      const e0 = 0.1 + ((stand - 0.1) * s) / 3, e1 = 0.1 + ((stand - 0.1) * (s + 1)) / 3;
      const y0 = seatTop - ((seatTop - seatFoot) * s) / 3, y1 = seatTop - ((seatTop - seatFoot) * (s + 1)) / 3;
      q(e0, y0, e1, y1, rows[s], mid(j, (e0 + e1) / 2, (y0 + y1) / 2 - 0.15));
    }
    q(stand, seatFoot, stand, 0, MARBLE_SHADE, mid(j, stand - 0.06, 0.08));
    // two storeys of arches round the outside, lit after dark
    const a = at(j, 0, 0), b = at(j + 1, 0, 0), L = Math.hypot(b[0] - a[0], b[2] - a[2]);
    const m = Math.max(1, Math.round(L / 0.3)), aw = Math.min(0.17, (L / m) * 0.6);
    const nx = (nodes[j][2] + nodes[j + 1][2]) / 2, nz = (nodes[j][3] + nodes[j + 1][3]) / 2;
    facing(k, (a[0] + b[0]) / 2, (a[2] + b[2]) / 2, nx, nz, (u, v) => {
      for (let i = 0; i < m; i++) {
        const ux = u - L / 2 + (L / m) * (i + 0.5);
        // behind the emperor's box: its glow 0.004 off a wall the box's back stood flush with flickered (19 Oct 2026)
        const wx = a[0] + (b[0] - a[0]) * ((i + 0.5) / m);
        if (nz < -0.9 && Math.abs(wx - px) < boxHalf + aw / 2 + 0.02) continue;
        for (const y of [0.06, 0.38]) {
          k.glowQuad([ux - aw / 2, y, v + 0.004], [ux + aw / 2, y, v + 0.004], [ux + aw / 2, y + 0.24, v + 0.004], [ux - aw / 2, y + 0.24, v + 0.004], [ux, y + 0.1, v - 0.1], DEPTH, LIT, ARCH_GLOW);
        }
      }
    });
  }
  // the crowd: a scatter of colour along the seats
  for (let i = 0; i < 36; i++) {
    const j = Math.floor(r() * (nodes.length - 1)), e = 0.16 + r() * (stand - 0.24);
    const p = mid(j, e, 0), y = seatTop - ((seatTop - seatFoot) * (e - 0.1)) / (stand - 0.1);
    k.box(p[0] + (r() - 0.5) * 0.3, y - 0.02, p[2], 0.035, 0.07, 0.035, hex([0xe2412f, 0xf2f0e8, 0x2f5fb8, 0x3f9b4a, 0xe8c040, 0x8e5cc7][Math.floor(r() * 6)]));
  }
  // the sand of the course, and the white line the teams start from
  k.box((x0 + xc) / 2, 0, 0, xc - x0, 0.015, (R - stand) * 2, SAND);
  k.cyl(xc, 0, 0, R - stand, 0.015, SAND, 14);
  k.box(x0 + 0.34, 0.015, 0, 0.025, 0.004, (R - stand) * 2, MARBLE);
  // the starting gates across the straight end: twelve stalls between two towers, the stand's ends against them
  k.box(-hx + gates / 2, 0, 0, gates, 0.46, R * 2, TRAV, TRAV_SHADE);
  facing(k, x0, 0, 1, 0, (u, v) => {
    for (let g = 0; g < 12; g++) {
      const gu = u - R + 0.24 + ((2 * R - 0.48) * (g + 0.5)) / 12, gw = Math.min(0.14, ((2 * R - 0.48) / 12) * 0.7);
      k.box(gu, 0, v + 0.01, gw, 0.22, 0.02, hex(0x7a2a22));
      k.box(gu, 0.22, v + 0.01, gw * 0.7, 0.05, 0.02, DEPTH);
      k.box(gu - gw / 2 - 0.012, 0, v + 0.02, 0.025, 0.32, 0.035, TRAV_LIGHT);
    }
  });
  for (const sz of [-1, 1]) {
    const tz = sz * (R - 0.15);
    k.box(-hx + gates / 2, 0, tz, gates + 0.04, 0.85, 0.3, TRAV, TRAV_SHADE);
    for (const [cx, cz] of [[-0.18, -0.1], [-0.18, 0.1], [0.18, -0.1], [0.18, 0.1], [0, -0.1], [0, 0.1]]) {
      k.box(-hx + gates / 2 + cx * (gates / 0.5), 0.85, tz + cz, 0.06, 0.07, 0.06, TRAV_SHADE);
    }
  }
  // the spina down the middle: a long low wall with its channel of water on top
  const xa = x0 + 0.85, xb = xc - 0.05;
  k.box((xa + xb) / 2, 0, 0, xb - xa, 0.11, 0.14, TRAV_SHADE, TRAV);
  k.box((xa + xb) / 2, 0.11, 0, xb - xa - 0.12, 0.01, 0.07, WATER_DAY);
  // the metae: three gilt cones on a half-round base at each end
  for (const mx of [xa, xb]) {
    k.cyl(mx, 0, 0, 0.1, 0.13, TRAV, 10);
    for (const oz of [-0.05, 0, 0.05]) {
      k.cyl(mx, 0.13, oz, 0.032, 0.05, BRONZE, 6);
      k.cone(mx, 0.18, oz, 0.032, 0.26, GILT, 6);
    }
  }
  // the obelisks, the great one in the middle
  obelisk(k, (xa + xb) / 2, 0, 1.15, 0.11);
  obelisk(k, xa + (xb - xa) * 0.27, 0, 0.7, 0.11);
  // the lap counters: seven eggs at one end, seven dolphins at the other, on their frames
  for (const [f, col] of [[0.14, MARBLE], [0.82, GILT]] as const) {
    const cx = xa + (xb - xa) * f;
    for (const sx of [-1, 1]) k.box(cx + sx * 0.13, 0.11, 0, 0.018, 0.24, 0.018, TRAV_LIGHT);
    k.box(cx, 0.35, 0, 0.3, 0.025, 0.03, TRAV_LIGHT);
    for (let i = 0; i < 7; i++) k.box(cx - 0.11 + i * 0.0367, 0.375, 0, 0.022, 0.035, 0.022, col);
  }
  // shrines and statues on columns between them
  for (const f of [0.4, 0.62]) {
    const cx = xa + (xb - xa) * f;
    k.box(cx, 0.11, 0, 0.14, 0.14, 0.1, MARBLE);
    k.gable(cx, 0.25, 0, 0.16, 0.06, 0.12, TERRACOTTA, MARBLE);
  }
  for (const f of [0.07, 0.34, 0.7, 0.93]) {
    const cx = xa + (xb - xa) * f;
    k.cyl(cx, 0.11, 0, 0.018, 0.28, MARBLE, 6);
    statue(k, cx, 0.39, 0, 0.1, GILT);
  }
  // the emperor's box over the far straight, a little temple front looking down on the course
  // standing a little proud of the outer wall, so its back is never flush with it
  k.box(px, 0, pz - 0.015, boxHalf * 2, wall + 0.06, stand * 0.9 + 0.03, MARBLE, MARBLE_SHADE);
  for (let i = 0; i < 4; i++) k.cyl(px - 0.24 + i * 0.16, wall + 0.06, pz + stand * 0.4, 0.022, 0.26, MARBLE, 6);
  k.box(px, wall + 0.32, pz + 0.05, 0.62, 0.04, stand * 0.75, MARBLE_SHADE);
  k.gable(px, wall + 0.36, pz + 0.05, 0.62, 0.13, stand * 0.75, TERRACOTTA, MARBLE, true);
  k.glowBox(px, wall + 0.1, pz + stand * 0.2, 0.4, 0.14, 0.02, DEPTH, LIT, ARCH_GLOW);
  // the arch at the round end, the triumphal way into the circus
  facing(k, hx - stand / 2 + 0.02, 0, 1, 0, (u, v) => {
    for (const s of [-1, 1]) k.box(u + s * 0.27, 0, v, 0.16, 0.92, stand + 0.06, TRAV_LIGHT);
    k.box(u, 0.62, v, 0.7, 0.3, stand + 0.06, TRAV_LIGHT);
    k.box(u, 0.92, v, 0.76, 0.12, stand + 0.1, TRAV);
    frontText(k, 'SPQR', u, 0.95, v + stand / 2 + 0.05, 0.07, BRONZE);
    quadriga(k, u, 1.04, v, 1.6, GILT, GILT, GILT);
  });
  // and the racing: four quadrigas, one a faction, round the spina through the day, each in its own lane
  // (the inner lanes are shorter, so they pass and are passed); out of hours they wait at the gates
  const room = R - stand, laneMid = 0.07 + (room - 0.07) / 2, gap = Math.min(0.11, (room - 0.2) / 4);
  const lanes = FACTIONS.map((_, i) => laneMid + (i - 1.5) * gap);
  const lap = (p: number, rho: number): [number, number, number, number] => {
    const S = xb - xa, C = Math.PI * rho, P = 2 * S + 2 * C;
    let q = ((p % P) + P) % P;
    if (q < S) return [xa + q, rho, 1, 0];
    q -= S;
    if (q < C) { const f = q / rho; return [xb + rho * Math.sin(f), rho * Math.cos(f), Math.cos(f), -Math.sin(f)]; }
    q -= C;
    if (q < S) return [xb - q, -rho, -1, 0];
    q -= S;
    const f = q / rho;
    return [xa - rho * Math.sin(f), -rho * Math.cos(f), -Math.cos(f), Math.sin(f)];
  };
  const pos = FACTIONS.map(() => 0);
  let clock = 0, was = false;
  k.rig(0, 0.015, 0, FACTIONS.map((c) => (s: Kit) => quadriga(s, 0, 0, 0, 1, HORSE, hex(c), hex(c))), (objs, dt, hour) => {
    const racing = hour >= 9 && hour < 18.5;
    clock += dt;
    if (racing && !was) pos.fill(0);
    was = racing;
    objs.forEach((o, i) => {
      if (!racing) { o.position.set(x0 + 0.2, 0, (i - 1.5) * 0.2); o.rotation.y = Math.PI / 2; return; }
      pos[i] += (1.2 + 0.2 * Math.sin(clock * 0.23 + i * 1.9) + 0.05 * i) * dt;
      const [x, z, dx, dz] = lap(pos[i], lanes[i]);
      o.position.set(x, 0, z);
      o.rotation.y = Math.atan2(dx, dz);
    });
  });
  void HORSE_DARK;
};

// ---- the Pantheon -----------------------------------------------------------------------------------

const pantheon: Draw = (k, W, D) => {
  const R = Math.min(W / 2 - 0.1, 0.85), cz = -D / 2 + R + 0.08, H = 0.6, y0 = 0.03;
  k.box(0, 0, 0, W - 0.04, y0, D - 0.04, PAVE);
  // the drum: brick under the last of its stucco, two cornices round it
  k.cyl(0, y0, cz, R, H, STUCCO, 22, STUCCO);
  // (the top one rises well clear of the drum's top: 0.005 over it, the two flashed at a distance)
  k.cyl(0, y0 + H * 0.48, cz, R + 0.025, 0.035, TRAV_LIGHT, 22);
  k.cyl(0, y0 + H - 0.03, cz, R + 0.025, 0.05, TRAV_LIGHT, 22);
  // the dome: stepped rings round its foot, then the shallow lead shell up to the open oculus
  let yb = y0 + H;
  for (let i = 0; i < 3; i++) { k.cyl(0, yb, cz, R * (0.97 - i * 0.05), 0.045, TRAV_SHADE, 22); yb += 0.045; }
  const R0 = R * 0.85, HD = R * 0.5, steps = 6, open = 0.15;
  // (a quarter ellipse: the radius falls as the cosine, the height rises as the sine, up to the oculus)
  const pTop = Math.acos(open);
  for (let i = 0; i < steps; i++) {
    const p0 = (pTop * i) / steps, p1 = (pTop * (i + 1)) / steps;
    k.band(0, cz, yb + HD * Math.sin(p0), R0 * Math.cos(p0), yb + HD * Math.sin(p1), R0 * Math.cos(p1), 22, LEAD);
  }
  const yTop = yb + HD * Math.sin(pTop);
  k.cyl(0, yTop - 0.02, cz, R0 * open, 0.025, TRAV_SHADE, 14);
  k.cyl(0, yTop + 0.005, cz, R0 * open * 0.82, 0.012, hex(0x1e1a16), 14);
  // the block between the drum and the portico, its own pediment ghosted on it
  const pw = Math.min(W - 0.12, R * 1.7), bz = cz + R - 0.1;
  k.box(0, y0, bz + 0.1, pw * 0.94, H + 0.12, 0.3, STUCCO, TRAV_SHADE);
  k.gable(0, y0 + H + 0.12, bz + 0.1, pw * 0.94, 0.2, 0.3, LEAD, TRAV_SHADE, true);
  // the portico: sixteen granite columns, eight across the front, under the pediment and Agrippa's name
  const pz0 = bz + 0.25, pz1 = Math.min(D / 2 - 0.38, pz0 + 0.75), pd = pz1 - pz0, colH = 0.5;
  k.box(0, y0, (pz0 + pz1) / 2, pw, 0.04, pd + 0.06, TRAV_SHADE);
  for (let i = 0; i < 8; i++) {
    const x = -pw / 2 + 0.07 + ((pw - 0.14) * i) / 7;
    k.cyl(x, y0 + 0.04, pz1 - 0.04, 0.035, colH, GRANITE, 8);
    k.box(x, y0 + 0.04 + colH, pz1 - 0.04, 0.08, 0.03, 0.08, MARBLE);
    if (i === 1 || i === 2 || i === 5 || i === 6) {
      k.cyl(x, y0 + 0.04, pz0 + pd * 0.45, 0.035, colH, GRANITE, 8);
      k.cyl(x, y0 + 0.04, pz0 + 0.05, 0.035, colH, GRANITE, 8);
    }
  }
  const ey = y0 + 0.04 + colH + 0.03;
  k.box(0, ey, (pz0 + pz1) / 2, pw + 0.04, 0.1, pd + 0.02, MARBLE, MARBLE_SHADE);
  frontText(k, 'M AGRIPPA', 0, ey + 0.025, pz1 + 0.02, 0.05, BRONZE);
  k.gable(0, ey + 0.1, (pz0 + pz1) / 2, pw + 0.06, 0.22, pd + 0.04, LEAD, MARBLE, true);
  k.glowBox(0, y0 + 0.04, pz0 + 0.004, 0.2, 0.36, 0.02, hex(0x5a4430), LIT, ARCH_GLOW);
  // the fountain and its little obelisk out on the piazza
  const fz = D / 2 - 0.2;
  if (fz - pz1 > 0.15) {
    k.cyl(0, y0, fz, 0.16, 0.06, TRAV_SHADE, 12);
    k.cyl(0, y0 + 0.05, fz, 0.13, 0.02, WATER_DAY, 12);
    obelisk(k, 0, fz, 0.42, y0 + 0.03);
  }
};

// ---- St Peter's -------------------------------------------------------------------------------------

const stPeters: Draw = (k, W, D) => {
  const back = -D / 2 + 0.05, fz = -D / 2 + Math.min(2.4, D * 0.44), navW = Math.min(1.3, W * 0.34);
  // the basilica: the nave running back from the front, the transepts across it, and its great front
  k.box(0, 0, (back + fz - 0.2) / 2, navW, 0.8, fz - 0.2 - back, TRAV, LEAD);
  const cz = back + (fz - back) * 0.42;
  k.box(0, 0, cz, W * 0.62, 0.78, 0.95, TRAV, LEAD);
  for (const sx of [-1, 1]) k.cyl(sx * W * 0.31, 0, cz, 0.47, 0.78, TRAV, 12, LEAD);
  const fw = Math.min(W * 0.72, 2.9);
  k.box(0, 0, fz - 0.13, fw, 0.92, 0.26, TRAV_LIGHT, TRAV_SHADE);
  k.box(0, 0.92, fz - 0.13, fw, 0.13, 0.24, TRAV_LIGHT, TRAV_SHADE);
  for (let i = 0; i < 8; i++) {
    const x = -fw * 0.36 + (fw * 0.72 * i) / 7;
    k.cyl(x, 0, fz + 0.02, 0.04, 0.8, TRAV_LIGHT, 8);
  }
  k.box(0, 0.8, fz + 0.01, fw, 0.1, 0.06, TRAV_LIGHT);
  k.gable(0, 0.8, fz - 0.02, 0.62, 0.14, 0.1, TRAV_SHADE, TRAV_LIGHT, true);
  for (let i = 0; i < 13; i++) statue(k, -fw * 0.42 + (fw * 0.84 * i) / 12, 1.05, fz - 0.04, 0.12);
  // the doors and the loggia over the middle one, lit at night; clocks under little cupolas at the corners
  for (let i = -2; i <= 2; i++) k.box(i * 0.24, 0, fz + 0.002, 0.1, 0.22, 0.01, DEPTH);
  k.glowBox(0, 0.42, fz + 0.004, 0.16, 0.2, 0.01, DEPTH, LIT, ARCH_GLOW);
  for (const sx of [-1, 1]) {
    k.box(sx * (fw / 2 + 0.12), 0, fz - 0.15, 0.26, 0.98, 0.26, TRAV_LIGHT);
    k.face(sx * (fw / 2 + 0.12), 0.85, fz - 0.019, 0.07, MARBLE);
    k.dome(sx * (fw / 2 + 0.12), 0.98, fz - 0.15, 0.1, LEAD_BLUE, 8, 3);
  }
  // the dome over the crossing: its drum of paired columns and windows, the tall ribbed shell, the lantern
  const dy = 0.78, dr = Math.min(0.55, W * 0.14);
  k.cyl(0, dy, cz, dr, 0.34, TRAV_LIGHT, 16);
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * TAU;
    k.box(Math.cos(a) * (dr + 0.015), dy, cz + Math.sin(a) * (dr + 0.015), 0.045, 0.32, 0.045, MARBLE);
    const b2 = a + TAU / 32;
    k.glowBox(Math.cos(b2) * (dr - 0.005), dy + 0.1, cz + Math.sin(b2) * (dr - 0.005), 0.05, 0.12, 0.05, DEPTH, LIT, ARCH_GLOW);
  }
  k.cyl(0, dy + 0.34, cz, dr + 0.04, 0.04, TRAV_SHADE, 16);
  const base = dy + 0.38, rings = 6, tall = dr * 1.3;
  const prof = (i: number): [number, number] => { const p = (i / rings) * 1.4; return [dr * Math.cos(p), base + tall * Math.sin(p)]; };
  for (let i = 0; i < rings; i++) {
    const [r0, y0] = prof(i), [r1, y1] = prof(i + 1);
    k.band(0, cz, y0, r0, y1, r1, 16, LEAD_BLUE);
  }
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + TAU / 32;
    for (let j = 0; j < 3; j++) {
      const [r0, y0] = prof(j * 2), [r1, y1] = prof(j * 2 + 2);
      k.bar([Math.cos(a) * (r0 + 0.01), y0, cz + Math.sin(a) * (r0 + 0.01)], [Math.cos(a) * (r1 + 0.01), y1, cz + Math.sin(a) * (r1 + 0.01)], 0.012, MARBLE);
    }
  }
  const [, yt] = prof(rings);
  k.cyl(0, yt, cz, 0.09, 0.17, TRAV_LIGHT, 10);
  k.cone(0, yt + 0.17, cz, 0.1, 0.13, LEAD_BLUE, 10);
  k.box(0, yt + 0.3, cz, 0.04, 0.04, 0.04, GILT);
  k.box(0, yt + 0.34, cz, 0.012, 0.1, 0.012, GILT);
  k.box(0, yt + 0.38, cz, 0.06, 0.012, 0.012, GILT);
  // the two little domes beside it
  for (const sx of [-1, 1]) {
    k.cyl(sx * W * 0.26, 0.78, cz + 0.42, 0.13, 0.12, TRAV_LIGHT, 10);
    k.dome(sx * W * 0.26, 0.9, cz + 0.42, 0.13, LEAD_BLUE, 10, 3);
  }
  // the square: Bernini's colonnade in two arms round an oval, joined to the front by straight wings
  const sq0 = fz + 0.05, sq1 = D / 2 - 0.05, pz = sq0 + (sq1 - sq0) * 0.56;
  const rx = W / 2 - 0.2, rz = Math.min((sq1 - sq0) * 0.42, 1.4);
  k.box(0, 0, (sq0 + sq1) / 2, W - 0.1, 0.02, sq1 - sq0, PAVE);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI;
    k.box(Math.cos(a) * rx * 0.45, 0.02, pz + Math.sin(a) * rz * 0.45, 0.02, 0.003, 0.02, TRAV_SHADE);
  }
  const SPREAD = 0.95, segs = 8;
  for (const side of [-1, 1]) {
    const c0 = side > 0 ? 0 : Math.PI;
    const p = (a: number, f = 1): [number, number] => [Math.cos(a) * rx * f, pz + Math.sin(a) * rz * f];
    for (let i = 0; i < segs; i++) {
      const a0 = c0 - SPREAD + (2 * SPREAD * i) / segs, a1 = c0 - SPREAD + (2 * SPREAD * (i + 1)) / segs;
      const [x0, z0] = p(a0), [x1, z1] = p(a1);
      span(k, x0, z0, x1, z1, 0.3, 0.08, 0.3, TRAV_LIGHT);
      span(k, x0, z0, x1, z1, 0.38, 0.04, 0.26, TRAV_SHADE);
      for (const f of [0.94, 1.06]) {
        for (const t of [0.25, 0.75]) {
          const a = a0 + (a1 - a0) * t, [cx, cz2] = p(a, f);
          k.box(cx, 0.02, cz2, 0.035, 0.28, 0.035, TRAV_LIGHT);
        }
      }
      const [sx, sz] = p((a0 + a1) / 2, 1.05);
      statue(k, sx, 0.42, sz, 0.09);
    }
    // the straight wing from the arm's inner end to the corner of the front
    const [ex, ez] = p(side > 0 ? -SPREAD : Math.PI + SPREAD);
    span(k, ex, ez, side * fw * 0.5, fz + 0.05, 0.02, 0.4, 0.26, TRAV_LIGHT, TRAV_SHADE);
  }
  obelisk(k, 0, pz, 1.0, 0.02);
  for (const sx of [-1, 1]) {
    k.cyl(sx * rx * 0.5, 0.02, pz, 0.12, 0.05, TRAV_SHADE, 10);
    k.cyl(sx * rx * 0.5, 0.07, pz, 0.1, 0.004, WATER_DAY, 10);
    k.cyl(sx * rx * 0.5, 0.07, pz, 0.025, 0.2, TRAV_LIGHT, 6);
    k.cyl(sx * rx * 0.5, 0.25, pz, 0.07, 0.02, TRAV_LIGHT, 8);
  }
};

// ---- the Vittoriano ---------------------------------------------------------------------------------

const vittoriano: Draw = (k, W, D) => {
  const w = W - 0.1, d = D - 0.1, front = d / 2, baseZ = -d / 2 + 0.45, baseFront = baseZ + 0.42, top = 0.82;
  // the terraces stepping up from the street, and the high base under the colonnade
  k.box(0, 0, -0.05, w, 0.16, d - 0.1, MARBLE, MARBLE_SHADE);
  k.box(0, 0.16, (baseFront - 0.2 + -d / 2) / 2 + 0.1, w * 0.88, 0.24, baseFront - 0.2 + d / 2, MARBLE, MARBLE_SHADE);
  k.box(0, 0.4, baseZ, w * 0.94, top - 0.4, 0.84, MARBLE, MARBLE_SHADE);
  // the great stair up the middle, ten flights' worth of steps
  const n = 10, run = (front - 0.05 - baseFront) / n;
  for (let i = 0; i < n; i++) {
    const z = front - 0.05 - run * (i + 0.5), sw = w * 0.36 - i * 0.03;
    k.box(0, 0, z, sw, (top * (i + 1)) / n, run + 0.005, i % 2 ? MARBLE : MARBLE_SHADE);
  }
  // the Altare della Patria half-way up, its flame burning day and night under the guard
  const az = front - 0.05 - run * 5.5;
  k.box(0, top * 0.55, az - run * 0.6, 0.5, 0.18, 0.06, MARBLE_SHADE);
  for (const sx of [-1, 1]) k.glowBox(sx * 0.32, top * 0.55, az, 0.05, 0.08, 0.05, hex(0xe87a2a), FLAME, hex(0xffa040));
  // the king on his horse, gilded, on his plinth on the upper terrace
  const kz = baseFront + 0.22;
  k.box(0, top, kz, 0.32, 0.24, 0.28, MARBLE);
  const ky = top + 0.24;
  k.box(0, ky + 0.12, kz, 0.08, 0.1, 0.26, GILT);
  for (const [ox, oz] of [[-0.025, -0.09], [0.025, -0.09], [-0.025, 0.09], [0.025, 0.09]]) k.box(ox, ky, kz + oz, 0.022, 0.13, 0.022, GILT);
  k.box(0, ky + 0.2, kz + 0.14, 0.05, 0.1, 0.07, GILT);
  k.box(0, ky + 0.22, kz, 0.05, 0.14, 0.06, GILT);
  k.box(0, ky + 0.36, kz, 0.035, 0.035, 0.035, GILT);
  // the colonnade: sixteen columns along a curve hollowed to the front, entablature and attic over them,
  // the portico's shade behind
  const Rc = 1.6, zc = baseZ - 0.3 + Rc, colH = 0.55, n2 = 16, th = 0.62;
  const pt = (t: number, rr = Rc): [number, number] => [rr * Math.sin(t), zc - rr * Math.cos(t)];
  for (let i = 0; i < n2; i++) {
    const t = -th + (2 * th * i) / (n2 - 1), [x, z] = pt(t);
    k.cyl(x, top, z, 0.045, colH, MARBLE, 6);
    if (i + 1 < n2) {
      const t1 = -th + (2 * th * (i + 1)) / (n2 - 1), [x1, z1] = pt(t1);
      span(k, x, z, x1, z1, top + colH, 0.1, 0.16, MARBLE, MARBLE_SHADE);
      span(k, x, z, x1, z1, top + colH + 0.1, 0.07, 0.12, MARBLE_SHADE);
      const [bx, bz] = pt(t, Rc + 0.2), [bx1, bz1] = pt(t1, Rc + 0.2);
      span(k, bx, bz, bx1, bz1, top, colH, 0.08, MARBLE_SHADE);
    }
  }
  // the propylaea at each end, temple fronts with the gilded quadrigas and Victories over them
  for (const s of [-1, 1]) {
    const px = s * (w * 0.47 - 0.28), pz = baseZ;
    k.box(px, top, pz, 0.5, 0.65, 0.6, MARBLE, MARBLE_SHADE);
    for (let i = 0; i < 4; i++) k.cyl(px - 0.18 + i * 0.12, top, pz + 0.32, 0.03, 0.58, MARBLE, 6);
    k.box(px, top + 0.58, pz + 0.04, 0.54, 0.1, 0.62, MARBLE);
    k.glowBox(px, top + 0.04, pz + 0.301, 0.24, 0.36, 0.01, MARBLE_SHADE, LIT, hex(0xfff0d0));
    quadriga(k, px, top + 0.68, pz, 2.2, GILT, GILT, GILT);
  }
};

// ---- the Trevi Fountain -----------------------------------------------------------------------------

const treviFountain: Draw = (k, W, D, _b, r) => {
  const fz = -D / 2 + 0.75, w = W - 0.08, ph = 1.05;
  // Palazzo Poli behind: four storeys of windows in its wings, its middle a triumphal arch
  k.box(0, 0, (fz + -D / 2 + 0.04) / 2, w, ph, fz + D / 2 - 0.04, hex(0xe8dcc4), TERRACOTTA);
  for (let f = 0; f < 4; f++) {
    for (const sx of [-1, 1]) {
      for (let i = 0; i < 3; i++) {
        const x = sx * (0.62 + i * ((w / 2 - 0.72) / 2.5));
        k.box(x, 0.12 + f * 0.23, fz + 0.002, 0.08, 0.13, 0.01, DEPTH);
        k.box(x, 0.26 + f * 0.23, fz + 0.006, 0.11, 0.02, 0.012, TRAV_LIGHT);
      }
    }
  }
  k.box(0, 0, fz + 0.04, 1.12, ph + 0.05, 0.08, TRAV_LIGHT);
  for (const x of [-0.42, -0.18, 0.18, 0.42]) {
    k.cyl(x, 0.12, fz + 0.1, 0.035, 0.78, TRAV_LIGHT, 8);
    k.box(x, 0.9, fz + 0.1, 0.09, 0.04, 0.09, TRAV_LIGHT);
  }
  k.box(0, 0.94, fz + 0.06, 1.16, 0.08, 0.14, TRAV_LIGHT);
  k.box(0, 1.02, fz + 0.03, 1.0, 0.18, 0.1, TRAV_LIGHT);
  for (const x of [-0.42, -0.18, 0.18, 0.42]) statue(k, x, 1.2, fz + 0.04, 0.13);
  k.box(0, 1.2, fz + 0.03, 0.22, 0.16, 0.06, TRAV_LIGHT);
  k.box(0, 1.36, fz + 0.03, 0.08, 0.06, 0.05, GILT);
  // the niche and Oceanus in it on his shell, a side niche each side with its statue
  k.box(0, 0.2, fz + 0.085, 0.26, 0.56, 0.01, hex(0xbcb09a));
  k.cyl(0, 0.2, fz + 0.18, 0.13, 0.04, TRAV_LIGHT, 10);
  statue(k, 0, 0.24, fz + 0.18, 0.34);
  for (const sx of [-1, 1]) {
    k.box(sx * 0.3, 0.3, fz + 0.085, 0.13, 0.3, 0.01, hex(0xbcb09a));
    statue(k, sx * 0.3, 0.32, fz + 0.12, 0.22);
  }
  // the rocks spilling out into the basin, and the sea horses led by their tritons
  for (let i = 0; i < 16; i++) {
    const x = -0.85 + i * 0.113 + (r() - 0.5) * 0.05, z = fz + 0.08 + r() * 0.22;
    k.box(x, 0, z, 0.1 + r() * 0.08, 0.06 + r() * 0.16, 0.1 + r() * 0.06, r() < 0.5 ? TRAV_SHADE : scale(TRAV_SHADE, 0.9));
  }
  for (const sx of [-1, 1]) {
    const hx = sx * 0.3, hz = fz + 0.42;
    k.box(hx, 0.08, hz, 0.07, 0.08, 0.16, MARBLE);
    k.bar([hx, 0.14, hz + 0.06], [hx, 0.27, hz + 0.13], 0.03, MARBLE);
    k.box(hx, 0.25, hz + 0.15, 0.05, 0.05, 0.08, MARBLE);
    statue(k, hx + sx * 0.12, 0.06, hz - 0.02, 0.2);
  }
  // the basin and its water, glowing turquoise after dark
  const bz = fz + 0.15, rx = w * 0.42, rz = Math.max(0.4, D / 2 - 0.5 - bz);
  k.cyl(0, 0, bz, rx + 0.06, 0.08, TRAV_LIGHT, 20, TRAV_LIGHT, rz + 0.06);
  for (let i = 0; i < 16; i++) {
    const a0 = (i / 16) * Math.PI, a1 = ((i + 1) / 16) * Math.PI;
    k.glowTri([0, 0.083, bz], [Math.cos(a0) * rx, 0.083, bz + Math.sin(a0) * rz], [Math.cos(a1) * rx, 0.083, bz + Math.sin(a1) * rz], [0, 0, bz + rz * 0.3], WATER_DAY, WATER_LIT, WATER_GLOW);
  }
  // the little square in front, its steps down to the water
  k.box(0, 0, D / 2 - 0.2, w, 0.02, 0.36, PAVE);
};

// ---- the Spanish Steps ------------------------------------------------------------------------------

const spanishSteps: Draw = (k, W, D) => {
  const top = 0.62, zT = -D / 2 + 1.05, zF = D / 2 - 0.5, w = W - 0.1;
  // the terrace up the hill, its walls washed ochre like the houses round the piazza
  k.box(0, 0, (-D / 2 + 0.04 + zT) / 2, w, top, zT + D / 2 - 0.04, OCHRE, PAVE);
  // the steps: wide at the foot and the head, drawn in round the landing in the middle where the azaleas are
  const n = 12, run = (zF - zT) / n;
  for (let i = 0; i < n; i++) {
    const z = zF - run * (i + 0.5), sw = w * (0.74 - 0.26 * Math.sin((Math.PI * i) / (n - 1)));
    k.box(0, 0, z, sw, (top * (i + 1)) / n, run + 0.004, i % 2 ? TRAV : TRAV_LIGHT);
    // the balustrade stepping up each side with the stair
    for (const sx of [-1, 1]) k.box(sx * (sw / 2 - 0.015), (top * (i + 1)) / n, z, 0.03, 0.07, run + 0.004, TRAV_SHADE);
  }
  const lz = zF - run * 6;
  k.box(0, (top * 6.5) / n, lz, 0.32, 0.06, run * 1.6, AZALEA);
  // and the flower boxes at the foot
  for (const sx of [-1, 1]) k.box(sx * w * 0.3, 0, zF + 0.1, 0.18, 0.08, 0.1, FOLIAGE);
  // Trinità dei Monti at the top: the church front with its two bell towers, the obelisk before it
  const cz = -D / 2 + 0.35;
  k.box(0, top, cz, Math.min(1.5, w * 0.6), 0.55, 0.5, hex(0xf0e6d4), TRAV_SHADE);
  k.gable(0, top + 0.55, cz + 0.05, 0.4, 0.12, 0.4, TERRACOTTA, hex(0xf0e6d4), true);
  for (const sx of [-1, 1]) {
    const tx = sx * Math.min(0.6, w * 0.24);
    k.box(tx, top + 0.55, cz + 0.08, 0.26, 0.42, 0.26, hex(0xf0e6d4));
    k.glowBox(tx, top + 0.7, cz + 0.211, 0.1, 0.16, 0.01, DEPTH, LIT, ARCH_GLOW);
    k.box(tx, top + 0.97, cz + 0.08, 0.3, 0.04, 0.3, TRAV_SHADE);
    k.hip(tx, top + 1.01, cz + 0.08, 0.26, 0.16, 0.26, LEAD);
  }
  k.glowBox(0, top + 0.06, cz + 0.252, 0.14, 0.22, 0.01, DEPTH, LIT, ARCH_GLOW);
  obelisk(k, 0, zT - 0.22, 0.75, top);
  // the Barcaccia: a stone boat half sunk in its basin at the foot of the steps
  const bz = D / 2 - 0.22;
  k.cyl(0, 0, bz, 0.34, 0.04, TRAV_SHADE, 14, TRAV_SHADE, 0.16);
  k.cyl(0, 0.04, bz, 0.3, 0.004, WATER_DAY, 14, WATER_DAY, 0.13);
  k.box(0, 0.02, bz, 0.34, 0.07, 0.13, TRAV);
  for (const sx of [-1, 1]) k.box(sx * 0.18, 0.02, bz, 0.06, 0.11, 0.1, TRAV);
  k.box(0, 0.09, bz, 0.26, 0.004, 0.08, WATER_DAY);
  void DARK;
};

export const ROME_DRAW = {
  colosseum, circusMaximus, pantheon, stPeters, vittoriano, treviFountain, spanishSteps,
} satisfies Record<string, Draw>;
