/**
 * Whose rows the social window's boards show (docs/social.html, "Three scopes on every board"): everyone, your
 * friends, or your neighbours (the fleets you have most dealings with, from the dealings ledger). A filter on
 * rows the game already has, so it costs the server nothing; the board modules (net/explorers.ts, game/challenges,
 * game/rushes) call inScope on each row's player, and number places within the scope.
 *
 * The server sends each board's top rows only, so among friends a board shows the friends who made its top rows,
 * each with their place overall beside it.
 */

export type ScopeMode = 'everyone' | 'friends' | 'neighbours';

const state = { mode: 'everyone' as ScopeMode, friends: new Set<string>(), near: new Set<string>() };

export const scopeMode = (): ScopeMode => state.mode;
export function setScope(mode: ScopeMode): void { state.mode = mode; }
/** The players in each scope: friends, and every player of the fleets you have most dealings with (top 20). */
export function setScopePeople(friends: Iterable<string>, near: Iterable<string>): void {
  state.friends = new Set(friends);
  state.near = new Set(near);
}
export const scopeFriends = (): Set<string> => state.friends;

/** Is this player's row shown in the scope in force? */
export function inScope(pid: string | undefined): boolean {
  if (state.mode === 'everyone') return true;
  if (!pid) return false;
  return state.mode === 'friends' ? state.friends.has(pid) : state.near.has(pid);
}

/** The scope chips, for a board's head. */
export function scopeChips(): string {
  const chip = (m: ScopeMode, label: string, n?: number) => `<button type="button" data-bscope="${m}" class="${state.mode === m ? 'on' : ''}">${label}${n !== undefined ? ` <small>${n}</small>` : ''}</button>`;
  return `<div class="scope bscope">${chip('everyone', 'Everyone')}${chip('friends', 'Friends', state.friends.size)}${chip('neighbours', 'Neighbours', state.near.size)}</div>`;
}

/** A press on one of the chips: true if it was one. */
export function scopePress(t: HTMLElement): boolean {
  const b = t.closest('[data-bscope]') as HTMLElement | null;
  if (!b) return false;
  state.mode = b.dataset.bscope as ScopeMode;
  return true;
}
