import * as THREE from 'three';
import { STEP, heightAt, idx, inB, type Building, type Work, type World } from '../world/tiles';
import { VEHICLES } from '../game/vehicles';
import { buildVehicleMesh, type VehicleMesh } from './vehicleMeshes';

/**
 * The quarries and mines at work (0.7.0, run time only: nothing is generated). At every quarry or mine in memory:
 * an excavator on the pit floor swinging between the face and the truck; a haul truck (the Tipper's body, bigger)
 * driving down to it, loaded, back up to the crusher and tipping; a bulldozer pushing spoil along a bench; a wheel
 * loader shuttling at the stockpile; a conveyor from the crusher running lumps up onto the stockpile. They work the
 * day shift, and on some nights a night shift under floodlights; now and then, about midday, a blast lifts a puff
 * of dust off a bench. Off shift the machines stand parked on the apron.
 *
 * A mine (world/mines.ts) lays out the same rigs: its pit and its plant come from the work as a quarry's do; a
 * bigger mine gets bigger trucks and a second one.
 */

/** Seconds a truck takes to be loaded and to tip, the tiles a second it drives, the shift's hours. */
const LOAD = 7, TIP = 5, DRIVE = 0.9, DAY: [number, number] = [7, 17], NIGHT: [number, number] = [19, 29];
/** Out of every hundred nights, how many a pit works through under its lights. */
const NIGHT_SHIFT = 0.35;

interface Pt { x: number; z: number }
interface Truck { mesh: VehicleMesh; t: number; phase: 'in' | 'load' | 'out' | 'tip'; wait: number; offset: number }
interface Site {
  w: World; g: Work; rev: number;
  /** Island tiles: the crusher's tipping point, the pit floor where the excavator stands, the stockpile. */
  tip: Pt; dig: Pt; pile: Pt; path: Pt[]; len: number;
  root: THREE.Group; trucks: Truck[];
  excavator: { root: THREE.Group; house: THREE.Group; boom: THREE.Group };
  dozer: { mesh: VehicleMesh; a: Pt; b: Pt; t: number };
  loader: { root: THREE.Group; arm: THREE.Group; a: Pt; b: Pt; t: number };
  lumps: THREE.InstancedMesh; belt: { from: THREE.Vector3; to: THREE.Vector3 };
  lights: THREE.MeshStandardMaterial; dust: THREE.Mesh; dustT: number; blastDay: number;
  /** A gravel pit's dredge on the river, bobbing as it works. */
  dredge: THREE.Group | null;
}

const YELLOW = 0xf2b21e, STEEL = 0x6d7176, DARK = 0x2e3236, GRAVEL = 0xa59a88;
const mat = (c: number, e = 0) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.75, metalness: 0.05, emissive: e ? new THREE.Color(e) : undefined });
const box = (w: number, h: number, d: number, m: THREE.Material, x = 0, y = 0, z = 0): THREE.Mesh => {
  const o = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
  o.position.set(x, y + h / 2, z);
  o.castShadow = true;
  return o;
};

export class QuarryRigs {
  readonly root = new THREE.Group();
  private sites = new Map<Work, Site>();
  private yellow = mat(YELLOW); private steel = mat(STEEL); private dark = mat(DARK); private gravel = mat(GRAVEL);
  private dustMat = new THREE.MeshStandardMaterial({ color: 0xd8cdb8, roughness: 1, transparent: true, opacity: 0.6, depthWrite: false });
  /** Truck loads tipped since the start (the gate and the console). */
  loads = 0;
  blasts = 0;

  constructor() { this.root.name = 'quarry rigs'; }

  /** Every quarry and mine in memory, at the hour of the day `hour` on day `day`. */
  update(dt: number, worlds: World[], hour: number, day: number): void {
    const live = new Set<Work>();
    for (const w of worlds) {
      for (const g of w.works) {
        if (g.kind !== 'quarry' && g.kind !== 'mine') continue;
        live.add(g);
        let s = this.sites.get(g);
        if (s && s.rev !== w.revision) { this.root.remove(s.root); s = undefined; this.sites.delete(g); }
        if (!s) {
          const made = this.make(w, g);
          if (!made) continue;
          s = made;
          this.sites.set(g, s);
          this.root.add(s.root);
        }
        this.step(s, dt, hour, day);
      }
    }
    for (const [g, s] of this.sites) if (!live.has(g)) { this.root.remove(s.root); this.sites.delete(g); }
  }

  /** How many sites are running, and how many machines are moving there now (the console and the gate). */
  get counts(): { sites: number; trucks: number; loads: number; blasts: number } {
    let trucks = 0;
    for (const s of this.sites.values()) trucks += s.trucks.length;
    return { sites: this.sites.size, trucks, loads: this.loads, blasts: this.blasts };
  }

  /** Is the site at work at this hour of this day: the day shift, or a night shift some nights. */
  static working(g: Work, hour: number, day: number): { on: boolean; night: boolean } {
    const h = ((hour % 24) + 24) % 24;
    if (h >= DAY[0] && h < DAY[1]) return { on: true, night: false };
    const d = h < 12 ? day - 1 : day;
    const roll = (Math.abs(Math.sin(g.x * 12.9898 + g.z * 78.233 + d * 37.719)) * 43758.5453) % 1;
    const on = roll < NIGHT_SHIFT && (h >= NIGHT[0] || h + 24 < NIGHT[1]);
    return { on, night: on };
  }

  private make(w: World, g: Work): Site | null {
    const crusher = g.buildings.find((b) => b.kind === 'crusher' || b.kind === 'oreMill' || b.kind === 'gravelPlant' || b.kind === 'coalTipple');
    const spot = w.spots.find((p) => p.name === g.name);
    if (!crusher || !spot) return null;
    const c = centre(crusher);
    // the tipping point on the crusher's pit side, the dig on the pit floor toward it, the stockpile off to one side
    const vx = spot.x - c.x, vz = spot.z - c.z, vl = Math.hypot(vx, vz) || 1, ux = vx / vl, uz = vz / vl;
    const reach = Math.max(crusher.w, crusher.d) / 2 + 0.8;
    const tip = { x: c.x + ux * reach, z: c.z + uz * reach };
    const dig = { x: spot.x - ux * Math.min(2, spot.r * 0.25), z: spot.z - uz * Math.min(2, spot.r * 0.25) };
    let pile = { x: c.x - uz * (reach + 2.2), z: c.z + ux * (reach + 2.2) };
    if (!dry(w, pile)) pile = { x: c.x + uz * (reach + 2.2), z: c.z - ux * (reach + 2.2) };
    // the haul road: down from the tipping point to the dig, swinging out round the benches (a gentle S)
    const path: Pt[] = [];
    const steps = Math.max(8, Math.ceil(Math.hypot(dig.x - tip.x, dig.z - tip.z) * 2));
    for (let k = 0; k <= steps; k++) {
      const t = k / steps, s = Math.sin(t * Math.PI) * Math.min(2.5, spot.r * 0.2);
      path.push({ x: tip.x + (dig.x - tip.x) * t - uz * s, z: tip.z + (dig.z - tip.z) * t + ux * s });
    }
    let len = 0;
    for (let k = 1; k < path.length; k++) len += Math.hypot(path[k].x - path[k - 1].x, path[k].z - path[k - 1].z);

    const root = new THREE.Group();
    root.position.set(w.ox, 0, w.oz);
    const big = g.kind === 'mine' && g.major;
    // the haul trucks: the Tipper's body, half again as big (twice at a big mine), one more at a big mine
    const dump = VEHICLES.find((d) => d.id === 'dump')!, dozerDef = VEHICLES.find((d) => d.id === 'bulldozer')!;
    const trucks: Truck[] = [];
    for (let k = 0; k < (big ? 2 : 1); k++) {
      const mesh = buildVehicleMesh(dump);
      mesh.root.scale.multiplyScalar(big ? 2 : 1.5);
      root.add(mesh.holder);
      trucks.push({ mesh, t: k * 0.5, phase: k ? 'out' : 'in', wait: 0, offset: k * 0.5 });
    }
    const dozerMesh = buildVehicleMesh(dozerDef);
    dozerMesh.root.scale.multiplyScalar(1.3);
    root.add(dozerMesh.holder);
    // the dozer works a bench part way up the pit side, back and forth along it
    const br = spot.r * 0.65, ba = Math.atan2(uz, ux) + Math.PI * 0.6;
    const bc = { x: spot.x + Math.cos(ba) * br, z: spot.z + Math.sin(ba) * br };
    const dozer = { mesh: dozerMesh, a: { x: bc.x + Math.sin(ba) * 1.6, z: bc.z - Math.cos(ba) * 1.6 }, b: { x: bc.x - Math.sin(ba) * 1.6, z: bc.z + Math.cos(ba) * 1.6 }, t: 0 };
    const excavator = this.excavator(big ? 1.6 : 1.15);
    root.add(excavator.root);
    const loader = this.loader();
    root.add(loader.root);
    const lpA = { x: pile.x + (tip.x - pile.x) * 0.25, z: pile.z + (tip.z - pile.z) * 0.25 }, lpB = { x: pile.x + (tip.x - pile.x) * 0.6, z: pile.z + (tip.z - pile.z) * 0.6 };
    // the stockpile and the conveyor up onto it from the crusher, its lumps riding the belt
    const pileY = groundAt(w, pile), cy = crusher.level * STEP;
    const heap = new THREE.Mesh(new THREE.ConeGeometry(1.3, 1.1, 10), this.gravel);
    heap.position.set(pile.x, pileY + 0.5, pile.z);
    heap.castShadow = true;
    root.add(heap);
    const from = new THREE.Vector3(c.x, cy + 0.75, c.z), to = new THREE.Vector3(pile.x, pileY + 1.15, pile.z);
    const beltLen = from.distanceTo(to);
    const belt = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.05, beltLen), this.dark);
    belt.position.copy(from).add(to).multiplyScalar(0.5);
    belt.lookAt(to);
    root.add(belt);
    for (const f of [0.35, 0.7]) {
      const p = from.clone().lerp(to, f), gy = groundAt(w, { x: p.x, z: p.z });
      const leg = box(0.06, Math.max(0.05, p.y - gy), 0.06, this.steel, p.x, gy, p.z);
      root.add(leg);
    }
    const lumps = new THREE.InstancedMesh(new THREE.DodecahedronGeometry(0.05, 0), this.gravel, 12);
    root.add(lumps);
    // floodlights on two masts over the apron, lit for a night shift
    const lights = mat(0x666666);
    for (const s of [-1, 1]) {
      const m = { x: c.x - uz * s * (reach + 1) - ux * 1.2, z: c.z + ux * s * (reach + 1) - uz * 1.2 };
      const y = groundAt(w, m);
      root.add(box(0.05, 1.4, 0.05, this.steel, m.x, y, m.z));
      const head = box(0.3, 0.12, 0.12, lights, m.x, y + 1.4, m.z);
      head.lookAt(spot.x, y, spot.z);
      root.add(head);
    }
    // a gravel pit's dredge: a pontoon out on the nearest water, its ladder down and a floating pipe toward the bank
    let dredge: THREE.Group | null = null;
    if (g.mine === 'gravelPit') {
      let best: Pt | null = null, bd = Infinity;
      for (let dz = -14; dz <= 14; dz++) for (let dx = -14; dx <= 14; dx++) {
        const x = Math.floor(spot.x) + dx, z = Math.floor(spot.z) + dz;
        if (!inB(x, z) || w.water[idx(x, z)] < 0) continue;
        const dd = Math.hypot(dx, dz);
        if (dd < bd) { bd = dd; best = { x: x + 0.5, z: z + 0.5 }; }
      }
      if (best) {
        dredge = new THREE.Group();
        dredge.add(box(0.9, 0.14, 0.5, this.steel, 0, -0.06, 0));
        dredge.add(box(0.36, 0.26, 0.3, this.yellow, -0.2, 0.08, 0));
        const ladder = box(0.08, 0.06, 0.7, this.dark, 0.35, 0, 0);
        ladder.rotation.x = 0.4;
        dredge.add(ladder);
        dredge.position.set(best.x, w.water[idx(Math.floor(best.x), Math.floor(best.z))] * STEP, best.z);
        dredge.rotation.y = Math.atan2(spot.x - best.x, spot.z - best.z);
        root.add(dredge);
      }
    }
    const dust = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 1), this.dustMat.clone());
    dust.visible = false;
    root.add(dust);
    return {
      w, g, rev: w.revision, tip, dig, pile, path, len, root, trucks, excavator, dozer,
      loader: { ...loader, a: lpA, b: lpB, t: 0 }, lumps, belt: { from, to }, lights, dust, dustT: 0, blastDay: -1, dredge,
    };
  }

  /** An excavator: tracks, a turning house with its cab, and a boom and dipper that reach out and curl in. */
  private excavator(s: number): Site['excavator'] {
    const root = new THREE.Group(), house = new THREE.Group(), boom = new THREE.Group();
    root.scale.setScalar(s);
    for (const side of [-1, 1]) root.add(box(0.12, 0.1, 0.62, this.dark, side * 0.2, 0, 0));
    root.add(house);
    house.position.y = 0.1;
    house.add(box(0.5, 0.18, 0.5, this.yellow, 0, 0, -0.05));
    house.add(box(0.18, 0.16, 0.18, this.dark, 0.12, 0.18, 0.12));
    house.add(boom);
    boom.position.set(-0.08, 0.2, 0.15);
    const arm = box(0.07, 0.07, 0.62, this.yellow, 0, 0, 0.31);
    boom.add(arm);
    const dipper = new THREE.Group();
    dipper.position.set(0, 0.03, 0.6);
    dipper.add(box(0.06, 0.4, 0.06, this.yellow, 0, -0.4, 0));
    dipper.add(box(0.16, 0.1, 0.12, this.steel, 0, -0.48, 0.04));
    boom.add(dipper);
    return { root, house, boom };
  }

  /** A wheel loader: a yellow body on four big wheels and a bucket on lifting arms in front. */
  private loader(): { root: THREE.Group; arm: THREE.Group } {
    const root = new THREE.Group(), arm = new THREE.Group();
    root.scale.setScalar(1.2);
    root.add(box(0.32, 0.16, 0.56, this.yellow, 0, 0.08, -0.04));
    root.add(box(0.2, 0.16, 0.18, this.dark, 0, 0.24, -0.1));
    for (const sx of [-1, 1]) for (const sz of [-0.18, 0.18]) {
      const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.07, 10), this.dark);
      wheel.rotation.z = Math.PI / 2;
      wheel.position.set(sx * 0.19, 0.1, sz);
      root.add(wheel);
    }
    arm.position.set(0, 0.18, 0.2);
    arm.add(box(0.04, 0.04, 0.26, this.yellow, 0, 0, 0.13));
    arm.add(box(0.36, 0.12, 0.1, this.steel, 0, -0.06, 0.28));
    root.add(arm);
    return { root, arm };
  }

  private step(s: Site, dt: number, hour: number, day: number): void {
    const w = s.w;
    const { on, night } = QuarryRigs.working(s.g, hour, day);
    s.lights.emissive.setHex(night ? 0xfff2c0 : 0x000000);
    s.lights.emissiveIntensity = night ? 2.2 : 0;
    // the trucks: down the haul road, loaded, back up, tipped; parked by the crusher off shift
    for (const t of s.trucks) {
      if (!on) { this.pose(t.mesh, w, s.path, 0.05 + t.offset * 0.3, false); continue; }
      if (t.wait > 0) {
        t.wait -= dt;
        if (t.wait <= 0) {
          if (t.phase === 'load') t.phase = 'out';
          else if (t.phase === 'tip') { t.phase = 'in'; this.loads++; }
        }
      } else {
        t.t += ((t.phase === 'in' ? 1 : -1) * DRIVE * dt) / s.len;
        if (t.phase === 'in' && t.t >= 1) { t.t = 1; t.phase = 'load'; t.wait = LOAD; }
        if (t.phase === 'out' && t.t <= 0) { t.t = 0; t.phase = 'tip'; t.wait = TIP; }
      }
      this.pose(t.mesh, w, s.path, t.t, t.phase === 'out' || t.phase === 'tip');
    }
    // the excavator: turns to the face, digs, swings back over the truck bed and lets go
    const ex = s.excavator, d = s.dig, dy = groundAt(w, d);
    ex.root.position.set(d.x, dy, d.z);
    const toTip = Math.atan2(s.tip.x - d.x, s.tip.z - d.z);
    const cyc = on ? (performance.now() / 1000) % 8 / 8 : 0;
    const swing = Math.sin(cyc * Math.PI * 2) * 0.5 + 0.5;
    ex.root.rotation.y = toTip;
    ex.house.rotation.y = Math.PI + swing * 1.4;
    ex.boom.rotation.x = -0.25 + (on ? Math.sin(cyc * Math.PI * 4) * 0.25 : 0.3);
    // the dozer pushes along its bench and backs up
    const dz = s.dozer;
    if (on) dz.t = (dz.t + dt / 9) % 1;
    const f = dz.t < 0.6 ? dz.t / 0.6 : 1 - (dz.t - 0.6) / 0.4;
    const dp = { x: dz.a.x + (dz.b.x - dz.a.x) * f, z: dz.a.z + (dz.b.z - dz.a.z) * f };
    dz.mesh.root.position.set(dp.x, groundAt(w, dp), dp.z);
    dz.mesh.root.rotation.set(0, Math.atan2(dz.b.x - dz.a.x, dz.b.z - dz.a.z), 0);
    // the loader shuttles between the stockpile and the crusher's hopper, bucket up when it is full
    const lo = s.loader;
    if (on) lo.t = (lo.t + dt / 7) % 1;
    const lf = lo.t < 0.5 ? lo.t * 2 : 2 - lo.t * 2;
    const lp = { x: lo.a.x + (lo.b.x - lo.a.x) * lf, z: lo.a.z + (lo.b.z - lo.a.z) * lf };
    lo.root.position.set(lp.x, groundAt(w, lp), lp.z);
    lo.root.rotation.y = Math.atan2(lo.b.x - lo.a.x, lo.b.z - lo.a.z);
    lo.arm.rotation.x = lo.t < 0.5 ? -0.5 : 0;
    if (s.dredge) s.dredge.rotation.z = on ? Math.sin(performance.now() / 900) * 0.03 : 0;
    // the belt's lumps, riding up while the plant runs
    const m4 = new THREE.Matrix4(), p = new THREE.Vector3();
    s.lumps.count = on ? 12 : 0;
    for (let k = 0; k < s.lumps.count; k++) {
      p.copy(s.belt.from).lerp(s.belt.to, ((performance.now() / 1000) * 0.12 + k / 12) % 1);
      p.y += 0.06;
      s.lumps.setMatrixAt(k, m4.makeTranslation(p.x, p.y, p.z));
    }
    s.lumps.instanceMatrix.needsUpdate = true;
    // a blast about midday some days: a puff of dust off a bench, swelling and fading
    const h = ((hour % 24) + 24) % 24;
    const roll = (Math.abs(Math.sin(s.g.x * 3.17 + s.g.z * 9.71 + day * 1.93)) * 1e4) % 1;
    if (on && !night && s.blastDay !== day && h >= 12 && h < 12.5 && roll < 0.5) {
      s.blastDay = day;
      s.dustT = 6;
      this.blasts++;
      const a = roll * 20;
      const spot = w.spots.find((q) => q.name === s.g.name)!;
      const bp = { x: spot.x + Math.cos(a) * spot.r * 0.8, z: spot.z + Math.sin(a) * spot.r * 0.8 };
      s.dust.position.set(bp.x, groundAt(w, bp) + 0.5, bp.z);
    }
    if (s.dustT > 0) {
      s.dustT -= dt;
      const t = 1 - s.dustT / 6;
      s.dust.visible = s.dustT > 0;
      s.dust.scale.setScalar(0.5 + t * 2.4);
      (s.dust.material as THREE.MeshStandardMaterial).opacity = 0.6 * (1 - t);
    }
  }

  /** A truck at t along the haul road (0 the crusher, 1 the dig), facing the way it goes, its bed down or up. */
  private pose(m: VehicleMesh, w: World, path: Pt[], t: number, back: boolean): void {
    const f = Math.max(0, Math.min(1, t)) * (path.length - 1), k = Math.min(path.length - 2, Math.floor(f)), u = f - k;
    const a = path[k], b = path[k + 1];
    const x = a.x + (b.x - a.x) * u, z = a.z + (b.z - a.z) * u;
    m.root.position.set(x, groundAt(w, { x, z }), z);
    m.root.rotation.set(0, Math.atan2(b.x - a.x, b.z - a.z) + (back ? Math.PI : 0), 0);
  }
}

function centre(b: Building): Pt { return { x: b.x + b.w / 2, z: b.z + b.d / 2 }; }
function groundAt(w: World, p: Pt): number { return heightAt(w, p.x, p.z); }
function dry(w: World, p: Pt): boolean {
  const x = Math.floor(p.x), z = Math.floor(p.z);
  return inB(x, z) && w.water[idx(x, z)] < 0 && !w.blocked[idx(x, z)] && !w.road[idx(x, z)];
}
