import { hex, scale, type RGB } from '../../world/biomes';
import type { MedievalKind } from '../../world/tiles';
import { MOAT } from '../../world/regionShapesC';
import { DARK, TAU, WARM_GLOW, pennant, pick, styleRoof, styleWall, tree, win, type Draw, type Kit } from './kit';

/**
 * A medieval town's own buildings, and the moated castle: the watchtower (for a water tower), the
 * guildhall (for a store or a bank), the tithe barn (for a barn), and the wonder of an ordinary island,
 * a square castle with a drum tower on every corner and a keep in the middle, ringed by a moat and
 * reached over a drawbridge. The town's three take the town's style; the castle, standing out on its
 * own, is always grey stone and slate.
 */

const OAK = hex(0x5a3f2a), IRON = hex(0x2a2a2e), THATCH = hex(0xa8884c);
const BANNER_HEX = [0xb5302a, 0x2f5fa0, 0xd8a93a, 0x2f6a3e, 0x7a3a8a], BANNERS = BANNER_HEX.map(hex);
/** The castle's colours: royal-blue caps on the corner towers, red on the keep's, gold for the trim. */
const ROYAL = hex(0x2f5a9e), CRIMSON = hex(0xa8322a), GOLD = hex(0xe0b23a), GREEN = hex(0x2f6a4a);

/** A long banner hung flat on a wall facing +z, from its top at y down, with a hem and a charge in a second colour. */
function hanging(k: Kit, x: number, y: number, z: number, w: number, h: number, col: RGB, trim: RGB): void {
  k.box(x, y - h, z, w, h, 0.014, col);
  k.box(x, y - h, z + 0.004, w, h * 0.08, 0.014, trim);
  k.box(x, y - h * 0.5, z + 0.004, w * 0.45, w * 0.45, 0.014, trim);
  k.box(x, y - 0.02, z, w + 0.04, 0.02, 0.03, hex(0x2a2a2e));
}

/** Striped awning over an opening on a front facing +z: alternating strips sloping out and down. */
function awning(k: Kit, x: number, y: number, z: number, w: number, a: RGB, b: RGB): void {
  const n = 6;
  for (let i = 0; i < n; i++) k.bar([x - w / 2 + (w / n) * (i + 0.5), y, z], [x - w / 2 + (w / n) * (i + 0.5), y - 0.08, z + 0.16], w / n / 2, i % 2 ? a : b);
}

/** A ring of merlons round a drum tower's top, every other one of `n` left out. */
function crown(k: Kit, x: number, y: number, z: number, R: number, col: RGB, n = 10): void {
  k.cyl(x, y, z, R * 1.08, 0.06, scale(col, 0.92), n);
  for (let i = 0; i < n; i += 2) {
    const a = (i / n) * TAU;
    k.box(x + Math.cos(a) * R, y + 0.06, z + Math.sin(a) * R, R * 0.36, 0.1, R * 0.36, col);
  }
}

/** A pole with a banner flying off it, pointing +x in the model's frame. */
function banner(k: Kit, x: number, y: number, z: number, h: number, col: RGB): void {
  k.box(x, y, z, 0.025, h, 0.025, IRON);
  k.box(x + 0.13, y + h - 0.16, z, 0.24, 0.15, 0.012, col);
}

/** A crenellated wall run from (ax, az) to (bx, bz), along x or z. */
function wallRun(k: Kit, ax: number, az: number, bx: number, bz: number, h: number, t: number, col: RGB, walk: RGB): void {
  const alongX = az === bz, len = Math.abs(alongX ? bx - ax : bz - az);
  const mx = (ax + bx) / 2, mz = (az + bz) / 2;
  k.box(mx, 0, mz, alongX ? len : t, h, alongX ? t : len, col, walk);
  const n = Math.max(2, Math.round(len / 0.26));
  for (let i = 0; i < n; i += 2) {
    const o = -len / 2 + (len / n) * (i + 0.5);
    for (const s of [-1, 1]) {
      const px = alongX ? mx + o : mx + s * (t / 2 - 0.05), pz = alongX ? mz + s * (t / 2 - 0.05) : mz + o;
      k.box(px, h, pz, alongX ? len / n : 0.1, 0.13, alongX ? 0.1 : len / n, col);
    }
  }
}

/** A gable end stepped like a stair (a crow-stepped gable) on the end wall at x, a roof `d` deep centred on z, rising `h` from y. */
function crowSteps(k: Kit, x: number, y: number, z: number, d: number, h: number, col: RGB): void {
  const steps = 4;
  for (let i = 0; i < steps; i++) k.box(x, y + (i * h) / steps, z, 0.08, h / steps, d * (1 - i / steps), col);
  k.box(x, y + h, z, 0.08, 0.12, 0.08, col);
}

// ---- the watchtower ------------------------------------------------------------------------------

const watchtower: Draw = (k, _W, _D, b, r) => {
  const stone = styleWall(r), top = 1.75, R = 0.27;
  k.box(0, 0, 0, 0.7, 0.08, 0.7, scale(stone, 0.85));
  k.cyl(0, 0.08, 0, R, top - 0.08, stone, 10);
  // the corbelled walk sticks out past the shaft, the battlements round it
  k.cyl(0, top - 0.08, 0, R * 1.18, 0.08, scale(stone, 0.9), 10);
  crown(k, 0, top, 0, R * 1.2, stone, 12);
  k.box(0, 0.08, R - 0.01, 0.13, 0.22, 0.03, OAK);
  // arrow slits up the front and round the side, each on its own storey
  for (let i = 0; i < 3; i++) {
    const y = 0.45 + i * 0.4, a = (i * 0.9 + 0.3) % TAU;
    k.box(Math.sin(a) * (R + 0.002), y, Math.cos(a) * (R + 0.002), 0.03, 0.14, 0.03, IRON);
  }
  win(k, b, r, 0, top - 0.3, R + 0.004, 0.08, 0.1, 1);
  banner(k, 0, top + 0.08, 0, 0.55, pick(r, BANNER_HEX));
  hanging(k, 0, top - 0.12, R + 0.01, 0.12, 0.42, pick(r, BANNER_HEX), GOLD);
  k.glowBox(0.1, top + 0.08, 0.1, 0.05, 0.07, 0.05, hex(0x6a4a22), [18, 6.5, 3], WARM_GLOW);
};

// ---- the guildhall -------------------------------------------------------------------------------

const guildhall: Draw = (k, W, D, b, r) => {
  const stone = styleWall(r), roof = styleRoof(r), trim = scale(stone, 0.8);
  const w = W - 0.35, d = D - 0.5, z = -0.1, g = 0.34, up = 0.46;
  // the open market hall on the ground floor: piers and arches, dark within
  k.box(0, 0, z, w - 0.12, g, d - 0.12, scale(DARK, 1.4));
  const bays = Math.max(3, Math.round(w / 0.4));
  for (let i = 0; i <= bays; i++) {
    const x = -w / 2 + (w * i) / bays;
    k.box(x, 0, z + d / 2 - 0.05, 0.1, g, 0.1, stone);
    k.box(x, 0, z - d / 2 + 0.05, 0.1, g, 0.1, stone);
  }
  k.box(0, g - 0.06, z, w, 0.06, d, trim);
  // market-day awnings over the arches, striped in two of the town's colours
  const ca = pick(r, BANNER_HEX), cb = hex(0xf1ece0);
  for (let i = 0; i < bays; i++) awning(k, -w / 2 + (w / bays) * (i + 0.5), g - 0.07, z + d / 2, (w / bays) * 0.86, ca, cb);
  // the council chamber over it: tall windows along the front
  k.box(0, g, z, w, up, d, stone);
  const n = Math.max(3, Math.round(w / 0.36));
  for (let i = 0; i < n; i++) win(k, b, r, -w / 2 + (w / n) * (i + 0.5), g + 0.1, z + d / 2, 0.12, 0.24, 1);
  for (const sx of [-1, 1]) win(k, b, r, sx * w / 2, g + 0.1, z, 0.12, 0.24, sx > 0 ? 0 : 2);
  // a steep roof with crow-stepped gables at both ends, a lantern on the ridge and a clock on the front
  const ry = g + up, rh = Math.min(0.7, d * 0.55);
  k.gable(0, ry, z, w + 0.04, rh, d + 0.08, roof, stone, false);
  for (const sx of [-1, 1]) crowSteps(k, sx * (w / 2 + 0.03), ry, z, d + 0.1, rh, stone);
  k.box(0, ry + rh - 0.02, z, 0.16, 0.2, 0.16, stone);
  k.box(0, ry + rh + 0.18, z, 0.2, 0.03, 0.2, trim);
  k.cone(0, ry + rh + 0.21, z, 0.14, 0.3, roof, 6);
  k.box(0.03, ry + rh + 0.51, z, 0.012, 0.12, 0.012, hex(0xd8a93a));
  k.cyl(0, g + up - 0.14, z + d / 2 + 0.01, 0.08, 0.02, hex(0xf1ece0), 12);
  k.box(0, g + up - 0.14, z + d / 2 + 0.03, 0.01, 0.05, 0.005, IRON);
  // the guilds' banners either side of the clock
  for (const sx of [-1, 1]) hanging(k, sx * w * 0.3, g + up - 0.02, z + d / 2 + 0.01, 0.12, 0.36, pick(r, BANNER_HEX), GOLD);
  pennant(k, 0, ry + rh + 0.63, z, 0.22, pick(r, BANNER_HEX));
  // steps up from the square
  k.box(0, 0, z + d / 2 + 0.12, w * 0.5, 0.04, 0.16, trim);
};

// ---- the tithe barn ------------------------------------------------------------------------------

const titheBarn: Draw = (k, W, D, _b, r) => {
  const stone = styleWall(r), roof = r() < 0.5 ? THATCH : styleRoof(r);
  const w = W - 0.3, d = D - 0.6, h = 0.42, z = -0.1;
  k.box(0, 0, z, w, h, d, stone);
  // buttresses along both long walls
  const n = Math.max(3, Math.round(w / 0.45));
  for (let i = 0; i <= n; i++) {
    const x = -w / 2 + (w * i) / n;
    for (const s of [-1, 1]) k.box(x, 0, z + s * (d / 2 + 0.05), 0.1, h * 0.85, 0.1, scale(stone, 0.9));
  }
  const rh = Math.min(1.0, d * 0.9);
  k.gable(0, h, z, w + 0.1, rh, d + 0.16, roof, stone, false);
  // the wagon porch: a gabled bay in the middle of the front with the great doors in it
  const pz = z + d / 2 + 0.22;
  k.box(0, 0, pz, 0.6, h + 0.1, 0.44, stone);
  k.gable(0, h + 0.1, pz, 0.68, 0.36, 0.48, roof, stone, true);
  k.box(0, 0, pz + 0.225, 0.36, 0.4, 0.02, OAK);
  k.box(0, 0.2, pz + 0.235, 0.012, 0.38, 0.01, scale(OAK, 0.7));
  // hay on the ground and a cart by the door
  k.box(-0.55, 0, pz + 0.3, 0.26, 0.12, 0.2, hex(0xd8b35a));
  k.box(0.6, 0.06, pz + 0.3, 0.3, 0.06, 0.18, OAK);
  for (const s of [-1, 1]) k.cyl(0.6 + s * 0.1, 0.06, pz + 0.3 + 0.1, 0.06, 0.02, IRON, 8);
};

// ---- the moated castle (wonder) ------------------------------------------------------------------

const moatedCastle: Draw = (k, _W, _D, b, r) => {
  const stone = hex(0x8f8a80), stoneLt = hex(0xa39d92), walk = hex(0x7a766c), water = hex(0x3f7f9a), bank = hex(0x6e6a60);
  const { outer: O, inner: I, wall: e, thick: t } = MOAT;
  // the moat: water in a ring, kerbed in stone on both banks; the drawbridge crosses it at the front
  const ring = (a: number, bb: number, y: number, h: number, col: RGB) => {
    const m = (a + bb) / 2, s = bb - a;
    k.box(0, y, m, 2 * bb, h, s, col);
    k.box(0, y, -m, 2 * bb, h, s, col);
    k.box(m, y, 0, s, h, 2 * a, col);
    k.box(-m, y, 0, s, h, 2 * a, col);
  };
  ring(I, O, -0.05, 0.075, water);
  ring(O, O + 0.14, 0, 0.07, bank);
  ring(I - 0.14, I, 0, 0.07, bank);
  // reeds and lily pads here and there
  for (let i = 0; i < 18; i++) {
    const side = i % 4, u = (r() - 0.5) * 2 * (O - 0.4), v = I + 0.2 + r() * (O - I - 0.4);
    const [x, z] = side === 0 ? [u, v] : side === 1 ? [v, u] : side === 2 ? [u, -v] : [-v, u];
    if (z > 0 && Math.abs(x) < 1.2) continue;
    if (r() < 0.5) k.box(x, 0.02, z, 0.1, 0.012, 0.1, hex(0x4f8a3e));
    else k.box(x, 0, z, 0.04, 0.2, 0.04, hex(0x6f8a3a));
  }

  // the curtain wall, open at the gate
  const g = 1.35;
  wallRun(k, -e, -e, e, -e, 1.25, t, stone, walk);
  wallRun(k, -e, -e, -e, e, 1.25, t, stone, walk);
  wallRun(k, e, -e, e, e, 1.25, t, stone, walk);
  wallRun(k, -e, e, -g, e, 1.25, t, stone, walk);
  wallRun(k, g, e, e, e, 1.25, t, stone, walk);
  // a drum tower on every corner, taller than the walls, under a slate cone with a banner
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    const x = sx * e, z = sz * e, R = 0.78, h = 2.1;
    k.cyl(x, 0, z, R, h, stone, 12, walk);
    for (let i = 0; i < 3; i++) {
      const a = Math.atan2(sz, sx) + (i - 1) * 0.5;
      k.box(x + Math.cos(a) * (R + 0.003), 0.6 + i * 0.45, z + Math.sin(a) * (R + 0.003), 0.04, 0.16, 0.04, IRON);
    }
    k.cyl(x, h, z, R * 1.1, 0.08, GOLD, 12);
    k.cone(x, h + 0.08, z, R * 1.15, 1.35, ROYAL, 12);
    banner(k, x, h + 1.4, z, 0.5, pick(r, BANNER_HEX));
    win(k, b, r, x + sx * 0.001, 1.45, z + sz * (R + 0.004), 0.09, 0.12, sz > 0 ? 1 : 3);
  }
  // a square tower half-way along each side and the back
  for (const [x, z] of [[-e, 0], [e, 0], [0, -e]]) {
    k.box(x, 0, z, 0.9, 1.7, 0.9, stone, walk);
    for (let i = 0; i < 4; i++) {
      const o = -0.33 + i * 0.22;
      for (const s of [-1, 1]) {
        k.box(x + o, 1.7, z + s * 0.4, 0.11, 0.12, 0.1, stone);
        k.box(x + s * 0.4, 1.7, z + o, 0.1, 0.12, 0.11, stone);
      }
    }
  }

  // the gatehouse: two drum towers, the arch between them, the portcullis half up, the bridge down
  for (const sx of [-1, 1]) {
    const x = sx * 0.95, z = e + 0.15;
    k.cyl(x, 0, z, 0.6, 1.95, stone, 12, walk);
    crown(k, x, 1.95, z, 0.6, stone, 12);
    k.cone(x, 2.05, z, 0.5, 0.8, CRIMSON, 12);
    pennant(k, x, 2.85, z, 0.3, sx > 0 ? GOLD : ROYAL);
    k.box(x, 0.8, z + 0.6, 0.04, 0.16, 0.02, IRON);
  }
  // the lord's shield over the arch, and banners down the curtain wall either side of the gate
  k.box(0, 1.12, e + 0.48, 0.32, 0.34, 0.03, ROYAL);
  k.box(0, 1.12, e + 0.495, 0.08, 0.34, 0.02, GOLD);
  k.box(0, 1.25, e + 0.495, 0.32, 0.08, 0.02, GOLD);
  for (const [x, col] of [[-3.2, ROYAL], [-2.2, CRIMSON], [2.2, CRIMSON], [3.2, ROYAL]] as [number, RGB][]) hanging(k, x, 1.2, e + t / 2 + 0.01, 0.26, 0.8, col, GOLD);
  for (const x of [-2.6, 2.6]) hanging(k, x, 1.2, -e - t / 2 - 0.02, 0.26, 0.7, GREEN, GOLD);
  // the gate itself: a passage a car can drive through, between two piers under the gatehouse's upper floor
  const pw = 0.2, open = MOAT.gate * 2, ph = 0.95;
  for (const sx of [-1, 1]) {
    k.box(sx * (open / 2 + pw / 2), 0, e, pw, ph, 0.95, stoneLt, walk);
    k.box(sx * (open / 2 + 0.005), 0, e, 0.01, ph, 0.93, scale(DARK, 1.6));
  }
  k.box(0, ph, e, open + 2 * pw, 1.6 - ph, 0.95, stoneLt, walk);
  k.box(0, ph - 0.012, e, open, 0.012, 0.93, scale(DARK, 1.3));
  k.box(0, ph, e + 0.476, open, 0.06, 0.03, stone);
  // the portcullis, wound up into the arch
  for (let i = 0; i < 5; i++) k.box(-0.32 + i * 0.16, ph - 0.14, e + 0.49, 0.025, 0.14, 0.025, IRON);
  k.box(0, ph - 0.14, e + 0.49, open, 0.025, 0.025, IRON);
  for (let i = 0; i < 4; i++) k.box(-0.45 + i * 0.3, 1.6, e + 0.38, 0.14, 0.12, 0.12, stone);
  banner(k, 0, 1.6, e, 0.8, BANNERS[0]);
  // the drawbridge: planks from the gate out over the moat to the bank, the chains up to the gatehouse
  const z0 = e + 0.48, z1 = O + 0.5, bw = MOAT.bridge * 2;
  k.box(0, 0.06, (z0 + z1) / 2, bw, 0.06, z1 - z0, OAK, hex(0x7a5a3a));
  for (let i = 0; i < 8; i++) k.box(0, 0.121, z0 + ((z1 - z0) * (i + 0.5)) / 8, bw, 0.004, 0.02, scale(OAK, 0.75));
  for (const s of [-1, 1]) {
    k.box(s * (bw / 2 - 0.03), 0.12, (z0 + z1) / 2, 0.05, 0.08, z1 - z0, scale(OAK, 0.85));
    k.bar([s * (bw / 2 - 0.05), 1.3, e + 0.48], [s * (bw / 2 - 0.05), 0.16, z1 - 0.1], 0.012, IRON);
  }
  // torches either side of the gate after dark
  for (const s of [-1, 1]) k.glowBox(s * 0.55, 1.05, e + 0.5, 0.05, 0.08, 0.05, hex(0x6a4a22), [18, 6.5, 3], WARM_GLOW);

  // the keep at the back of the bailey: a tall square tower, turrets on its corners, battlements round
  const kz = -1.4, ks = 2.6, kh = 3.3;
  k.box(0, 0, kz, ks, kh, ks, stoneLt, walk);
  k.box(0, 0, kz, ks + 0.2, 0.3, ks + 0.2, stone);
  for (let f = 0; f < 3; f++) {
    for (const o of [-0.6, 0, 0.6]) {
      win(k, b, r, o, 0.9 + f * 0.8, kz + ks / 2, 0.14, 0.22, 1);
      win(k, b, r, ks / 2, 0.9 + f * 0.8, kz + o, 0.14, 0.22, 0);
      win(k, b, r, -ks / 2, 0.9 + f * 0.8, kz + o, 0.14, 0.22, 2);
    }
  }
  for (let i = 0; i < 10; i += 2) {
    const o = -ks / 2 + (ks / 10) * (i + 0.5);
    for (const s of [-1, 1]) {
      k.box(o, kh, kz + s * (ks / 2 - 0.06), ks / 10, 0.16, 0.12, stoneLt);
      k.box(s * (ks / 2 - 0.06), kh, kz + o, 0.12, 0.16, ks / 10, stoneLt);
    }
  }
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    const x = sx * ks / 2, z = kz + sz * ks / 2;
    k.cyl(x, kh - 0.6, z, 0.32, 1.1, stoneLt, 10);
    k.cone(x, kh + 0.5, z, 0.38, 0.8, CRIMSON, 10);
    pennant(k, x, kh + 1.3, z, 0.28, pick(r, BANNER_HEX));
  }
  k.box(0, kh, kz, 0.9, 0.5, 0.9, stoneLt);
  k.cone(0, kh + 0.5, kz, 0.72, 1.1, ROYAL, 4);
  banner(k, 0, kh + 1.6, kz, 0.7, BANNERS[1]);
  // great banners down the keep's front and sides
  hanging(k, -0.7, kh - 0.2, kz + ks / 2 + 0.01, 0.34, 1.3, CRIMSON, GOLD);
  hanging(k, 0.7, kh - 0.2, kz + ks / 2 + 0.01, 0.34, 1.3, ROYAL, GOLD);
  // the steps up to the keep's door
  k.box(0, 0, kz + ks / 2 + 0.3, 0.5, 0.3, 0.6, stone);
  k.box(0, 0.3, kz + ks / 2 + 0.01, 0.3, 0.45, 0.02, OAK);

  // the great hall along the west wall and the chapel on the east, the well between
  k.box(-2.9, 0, 1.5, 1.4, 1.0, 2.6, stone);
  k.gable(-2.9, 1.0, 1.5, 1.5, 0.75, 2.7, hex(0x8a4a34), stone, true);
  for (const o of [-0.8, 0, 0.8]) win(k, b, r, -2.2, 0.35, 1.5 + o, 0.12, 0.4, 0);
  k.box(2.9, 0, 1.9, 1.2, 0.9, 1.9, stoneLt);
  k.gable(2.9, 0.9, 1.9, 1.3, 0.8, 2.0, GREEN, stoneLt, true);
  k.box(2.9, 1.3, 2.95, 0.3, 0.6, 0.3, stoneLt);
  k.cone(2.9, 1.9, 2.95, 0.24, 0.5, GREEN, 4);
  k.box(2.9, 2.4, 2.95, 0.02, 0.14, 0.02, GOLD);
  k.box(2.9, 2.49, 2.95, 0.08, 0.02, 0.02, GOLD);
  win(k, b, r, 2.9, 0.3, 2.85, 0.2, 0.4, 1);
  k.cyl(0.9, 0, 1.6, 0.28, 0.22, stone, 10, hex(0x2a4a5a));
  for (const s of [-1, 1]) k.box(0.9 + s * 0.25, 0.22, 1.6, 0.04, 0.4, 0.04, OAK);
  k.box(0.9, 0.62, 1.6, 0.6, 0.04, 0.08, OAK);
  // a couple of trees in the bailey and outside the moat
  tree(k, -1.6, 0, 3.2, 0.9, false);
  tree(k, 2.2, 0, -3.3, 0.8, false);
  for (const [x, z] of [[-6.8, -6.8], [6.8, -6.6], [-6.7, 6.6]]) tree(k, x, 0, z, 1, r() < 0.4);
};

export const MEDIEVAL_DRAW: Record<MedievalKind, Draw> = { watchtower, guildhall, titheBarn, moatedCastle };
