/**
 * The things missions are about, as meshes: the loads a tow drags (docs/missions.html, Tows), and the
 * few props a mission card's hero turns on its plinth that the game has no model of already — a trophy,
 * the car ferry, a Passport stamp, a crate, a part out of the workshop. Built from primitives in the
 * game's flat-shaded style, about a tile across, sitting on y = 0.
 */
import * as THREE from 'three';
import type { HaulKind } from '../game/missions/model';
import type { SlotId } from '../game/parts';

const mats = new Map<number, THREE.MeshStandardMaterial>();
function mat(c: number, metal = 0, rough = 0.7): THREE.MeshStandardMaterial {
  const k = c * 7 + Math.round(metal * 3) * 1e9 + Math.round(rough * 5) * 1e10;
  let m = mats.get(k);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: c, metalness: metal, roughness: rough, flatShading: true }); mats.set(k, m); }
  return m;
}

function box(g: THREE.Object3D, w: number, h: number, d: number, c: number, x = 0, y = 0, z = 0, metal = 0): THREE.Mesh {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(c, metal));
  m.position.set(x, y + h / 2, z);
  m.castShadow = true;
  g.add(m);
  return m;
}
function cyl(g: THREE.Object3D, r: number, h: number, c: number, x = 0, y = 0, z = 0, axis: 'x' | 'y' | 'z' = 'y', seg = 14, metal = 0, r2 = r): THREE.Mesh {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r2, r, h, seg), mat(c, metal, metal ? 0.35 : 0.7));
  if (axis === 'x') m.rotation.z = Math.PI / 2;
  if (axis === 'z') m.rotation.x = Math.PI / 2;
  m.position.set(x, y + (axis === 'y' ? h / 2 : 0), z);
  m.castShadow = true;
  g.add(m);
  return m;
}

const WOOD = 0x8d6d48, WOOD_DARK = 0x6b5033, IRON = 0x3a3f45, BRONZE = 0xb8863b, STONE = 0xcfc6b0, RUST = 0xa0523d, WHITE = 0xf4f2ec;

/** A sledge: two runners and a deck of planks, what everything heavy is dragged on. */
function sledge(g: THREE.Group, len = 1.3, wide = 0.8): number {
  for (const s of [-1, 1]) box(g, 0.08, 0.08, len, WOOD_DARK, s * (wide / 2 - 0.06), 0, 0);
  box(g, wide, 0.06, len * 0.92, WOOD, 0, 0.08, 0);
  return 0.14;
}

/** A load, on its sledge (or its own keel), facing +z. */
export function buildHaul(kind: HaulKind): THREE.Group {
  const g = new THREE.Group();
  g.name = `haul:${kind}`;
  switch (kind) {
    case 'bell': {
      const y = sledge(g, 1.1, 0.9);
      // a timber frame and the bell hanging in it
      for (const s of [-1, 1]) box(g, 0.1, 0.95, 0.1, WOOD_DARK, s * 0.38, y, 0);
      box(g, 0.9, 0.1, 0.12, WOOD_DARK, 0, y + 0.95, 0);
      const pts = [[0.02, 0], [0.34, 0.02], [0.32, 0.08], [0.26, 0.22], [0.2, 0.5], [0.17, 0.62], [0.08, 0.68], [0, 0.68]].map(([r, h]) => new THREE.Vector2(r, h));
      const bell = new THREE.Mesh(new THREE.LatheGeometry(pts, 18), mat(BRONZE, 0.7, 0.35));
      bell.position.y = y + 0.22;
      bell.castShadow = true;
      g.add(bell);
      break;
    }
    case 'boiler': {
      const y = sledge(g, 1.5, 0.9);
      cyl(g, 0.36, 1.3, IRON, 0, y + 0.38, 0, 'z', 16, 0.4);
      for (const z of [-0.45, 0, 0.45]) cyl(g, 0.375, 0.05, 0x2a2e33, 0, y + 0.38, z, 'z', 16, 0.5);
      cyl(g, 0.1, 0.4, IRON, 0, y + 0.66, 0.35, 'y', 10, 0.4);
      cyl(g, 0.12, 0.08, 0xc9ced4, 0, y + 0.38, -0.68, 'z', 16, 0.8);
      break;
    }
    case 'propeller': {
      const y = sledge(g, 1.1, 1.0);
      box(g, 0.5, 0.25, 0.3, WOOD_DARK, 0, y, 0);
      const hub = cyl(g, 0.14, 0.25, BRONZE, 0, y + 0.62, 0, 'z', 14, 0.7);
      for (let k = 0; k < 4; k++) {
        const blade = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.5, 0.05), mat(BRONZE, 0.7, 0.35));
        const a = (k * Math.PI) / 2 + 0.3;
        blade.position.set(Math.sin(a) * 0.3, y + 0.62 + Math.cos(a) * 0.3, 0);
        blade.rotation.set(0.35, 0, -a);
        blade.castShadow = true;
        g.add(blade);
      }
      void hub;
      break;
    }
    case 'statue': {
      const y = sledge(g, 1.0, 0.8);
      box(g, 0.55, 0.22, 0.55, STONE, 0, y, 0);
      // a figure in a cloak, one arm raised: stacked stone
      box(g, 0.3, 0.55, 0.22, STONE, 0, y + 0.22, 0);
      box(g, 0.34, 0.18, 0.26, STONE, 0, y + 0.72, 0);
      const head = new THREE.Mesh(new THREE.SphereGeometry(0.1, 10, 8), mat(STONE));
      head.position.set(0, y + 0.98, 0);
      g.add(head);
      const arm = box(g, 0.07, 0.36, 0.07, STONE, 0.18, y + 0.8, 0);
      arm.rotation.z = -0.5;
      break;
    }
    case 'yacht': {
      // a cradle, the hull on it, the mast
      for (const z of [-0.35, 0.35]) box(g, 0.7, 0.18, 0.1, WOOD_DARK, 0, 0, z);
      const shape = new THREE.Shape();
      shape.moveTo(0, -0.75); shape.quadraticCurveTo(0.34, -0.3, 0.3, 0.55); shape.lineTo(-0.3, 0.55); shape.quadraticCurveTo(-0.34, -0.3, 0, -0.75);
      const hull = new THREE.Mesh(new THREE.ExtrudeGeometry(shape, { depth: 0.32, bevelEnabled: false }), mat(WHITE));
      hull.rotation.x = Math.PI / 2;
      hull.position.y = 0.52;
      hull.castShadow = true;
      g.add(hull);
      box(g, 0.64, 0.04, 1.28, 0x2f4d7a, 0, 0.2, 0.05);
      cyl(g, 0.025, 1.3, WHITE, 0, 0.52, 0.05);
      box(g, 0.25, 0.14, 0.35, 0xe8e2d4, 0, 0.52, 0.2);
      break;
    }
    case 'wreck': {
      const y = sledge(g, 1.3, 0.8);
      // a van that has seen better days: rust, a caved roof, no wheels
      const body = box(g, 0.66, 0.42, 1.12, RUST, 0, y, 0);
      body.rotation.z = 0.06;
      const cab = box(g, 0.62, 0.22, 0.4, 0x8a4a3a, 0, y + 0.42, 0.28);
      cab.rotation.x = 0.12;
      box(g, 0.5, 0.14, 0.02, 0x5d87a6, 0, y + 0.47, 0.49);
      for (const s of [-1, 1]) for (const z of [-0.35, 0.35]) cyl(g, 0.1, 0.06, 0x2a2a2e, s * 0.34, y + 0.06, z, 'x', 10);
      break;
    }
    case 'loco': {
      // a small tank engine on a low dolly
      box(g, 0.8, 0.12, 1.6, 0x55575b, 0, 0.08, 0);
      for (const s of [-1, 1]) for (const z of [-0.6, 0, 0.6]) cyl(g, 0.1, 0.06, IRON, s * 0.42, 0.1, z, 'x', 10);
      cyl(g, 0.28, 0.9, 0x2f6f4a, 0, 0.5, 0.25, 'z', 16, 0.3);
      box(g, 0.66, 0.6, 0.45, 0x2f6f4a, 0, 0.2, -0.45);
      box(g, 0.72, 0.06, 0.52, IRON, 0, 0.8, -0.45);
      cyl(g, 0.08, 0.35, IRON, 0, 0.72, 0.6);
      cyl(g, 0.11, 0.06, BRONZE, 0, 1.05, 0.6, 'y', 10, 0.6);
      for (const s of [-1, 1]) for (const z of [-0.2, 0.25, 0.6]) cyl(g, 0.16, 0.06, 0xb5543f, s * 0.3, 0.36, z, 'x', 12);
      break;
    }
    case 'dish': {
      // the observatory's radio dish on a low trailer: the bowl tipped up, its feed on three legs
      box(g, 0.9, 0.1, 1.4, 0x55575b, 0, 0.08, 0);
      for (const s of [-1, 1]) for (const z of [-0.5, 0.5]) cyl(g, 0.09, 0.06, IRON, s * 0.46, 0.09, z, 'x', 10);
      box(g, 0.2, 0.3, 0.2, 0x8a8f96, 0, 0.18, 0);
      const pts = [[0.04, 0], [0.2, 0.02], [0.4, 0.08], [0.56, 0.18], [0.66, 0.3]].map(([r, h]) => new THREE.Vector2(r, h));
      const bowl = new THREE.Mesh(new THREE.LatheGeometry(pts, 20), mat(0xeef0f2, 0.2, 0.5));
      (bowl.material as THREE.MeshStandardMaterial).side = THREE.DoubleSide;
      bowl.position.set(0, 0.5, 0);
      bowl.rotation.x = -0.7;
      bowl.castShadow = true;
      g.add(bowl);
      for (let k = 0; k < 3; k++) {
        const a = (k / 3) * Math.PI * 2;
        const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.62, 5), mat(0x3a3f45));
        leg.position.set(Math.cos(a) * 0.22, 0.88, 0.12 + Math.sin(a) * 0.22);
        leg.lookAt(0, 1.12, 0.32);
        leg.rotateX(Math.PI / 2);
        g.add(leg);
      }
      box(g, 0.1, 0.1, 0.1, 0x3a3f45, 0, 1.08, 0.3);
      break;
    }
    case 'sphere': {
      // a submarine's pressure sphere in its cradle on a sledge: thick steel, a hatch and a ring of viewports
      const y = sledge(g, 1.4, 1.0);
      for (const z of [-0.35, 0.35]) box(g, 0.9, 0.22, 0.12, WOOD_DARK, 0, y, z);
      const ball = new THREE.Mesh(new THREE.SphereGeometry(0.5, 18, 12), mat(0xb9bdc2, 0.6, 0.35));
      ball.position.set(0, y + 0.62, 0);
      ball.castShadow = true;
      g.add(ball);
      const band = new THREE.Mesh(new THREE.TorusGeometry(0.505, 0.03, 6, 24), mat(0x6b6f75, 0.6, 0.4));
      band.position.copy(ball.position);
      band.rotation.x = Math.PI / 2;
      g.add(band);
      cyl(g, 0.14, 0.08, 0x3a3f45, 0, y + 1.08, 0, 'y', 12, 0.5);
      for (let k = 0; k < 4; k++) {
        const a = (k / 4) * Math.PI * 2 + 0.4;
        const port = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.04, 12), mat(0x9fd3ea, 0.1, 0.2));
        port.position.set(Math.cos(a) * 0.49, y + 0.72, Math.sin(a) * 0.49);
        port.lookAt(ball.position);
        port.rotateX(Math.PI / 2);
        g.add(port);
      }
      break;
    }
  }
  return g;
}

/** The trophy a race win is. */
export function buildTrophy(): THREE.Group {
  const g = new THREE.Group();
  box(g, 0.4, 0.14, 0.4, 0x2a2a2e, 0, 0, 0);
  box(g, 0.3, 0.1, 0.3, 0x3a3f45, 0, 0.14, 0);
  cyl(g, 0.05, 0.3, 0xd9b34a, 0, 0.24, 0, 'y', 10, 0.8);
  // closed at the foot and carried over the lip down to an inner floor, so it never shows its back faces
  const pts = [[0, 0], [0.06, 0], [0.2, 0.05], [0.26, 0.2], [0.28, 0.4], [0.26, 0.42], [0.245, 0.39], [0.23, 0.22], [0.12, 0.12], [0, 0.11]].map(([r, h]) => new THREE.Vector2(r, h));
  const cup = new THREE.Mesh(new THREE.LatheGeometry(pts, 20), mat(0xd9b34a, 0.8, 0.3));
  cup.position.y = 0.52;
  g.add(cup);
  for (const s of [-1, 1]) {
    const handle = new THREE.Mesh(new THREE.TorusGeometry(0.1, 0.025, 6, 12, Math.PI), mat(0xd9b34a, 0.8, 0.3));
    handle.position.set(s * 0.3, 0.72, 0);
    handle.rotation.z = s > 0 ? -Math.PI / 2 : Math.PI / 2;
    g.add(handle);
  }
  return g;
}

/** The car ferry, with a car on its deck. */
export function buildFerry(): THREE.Group {
  const g = new THREE.Group();
  box(g, 1.1, 0.28, 2.4, WHITE, 0, 0, 0);
  box(g, 1.14, 0.08, 2.44, 0x2f4d7a, 0, 0, 0);
  box(g, 0.9, 0.3, 0.6, WHITE, 0, 0.28, -0.8);
  box(g, 0.92, 0.08, 0.62, 0xe2412f, 0, 0.58, -0.8);
  cyl(g, 0.09, 0.3, 0xe2412f, 0, 0.66, -0.8);
  box(g, 0.4, 0.2, 0.6, 0xe2412f, 0, 0.28, 0.5);
  box(g, 0.34, 0.12, 0.3, 0x9cc6d9, 0, 0.48, 0.45);
  return g;
}

/** A Passport stamp: a round inked seal on a page. */
export function buildStamp(colour = 0x2f7fb5): THREE.Group {
  const g = new THREE.Group();
  box(g, 1.2, 0.04, 0.85, 0xf6ecc9, 0, 0, 0);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.035, 6, 32), mat(colour));
  ring.rotation.x = Math.PI / 2;
  ring.position.set(0.1, 0.06, 0);
  g.add(ring);
  cyl(g, 0.2, 0.02, colour, 0.1, 0.04, 0, 'y', 24);
  box(g, 0.3, 0.3, 0.06, WOOD, -0.38, 0.04, 0.1).rotation.y = 0.4;
  cyl(g, 0.12, 0.35, WOOD_DARK, -0.38, 0.1, 0.1);
  return g;
}

/** A crate of goods, in the cargo's own colour. */
export function buildCrate(colour: number): THREE.Group {
  const g = new THREE.Group();
  box(g, 0.7, 0.55, 0.7, WOOD, 0, 0, 0);
  for (const y of [0.05, 0.45]) box(g, 0.72, 0.06, 0.72, WOOD_DARK, 0, y, 0);
  box(g, 0.4, 0.2, 0.02, colour, 0, 0.18, 0.36);
  return g;
}

/** A part out of the workshop, on its own: an engine block, a tyre, a bottle… Tiers shine brighter. */
export function buildPart(slot: SlotId, tier: number): THREE.Group {
  const g = new THREE.Group();
  const trim = [0x9aa7b0, 0xb07a4a, 0xc9ced4, 0xd9b34a][Math.max(0, Math.min(3, tier))];
  switch (slot) {
    case 'engine': {
      box(g, 0.7, 0.45, 0.9, 0x3a3f45, 0, 0.05, 0, 0.4);
      for (const z of [-0.3, -0.1, 0.1, 0.3]) cyl(g, 0.09, 0.2, trim, 0, 0.5, z, 'y', 10, 0.8);
      box(g, 0.76, 0.06, 0.95, trim, 0, 0.46, 0, 0.8);
      cyl(g, 0.16, 0.18, 0x2a2a2e, 0.42, 0.25, 0, 'x', 14);
      if (tier >= 2) cyl(g, 0.14, 0.25, trim, -0.35, 0.55, 0.2, 'y', 14, 0.9, 0.2);
      break;
    }
    case 'tyres': {
      const t = new THREE.Mesh(new THREE.TorusGeometry(0.34, 0.14 + tier * 0.02, 10, 24), mat(0x2a2a2e));
      t.position.y = 0.5;
      g.add(t);
      cyl(g, 0.2, 0.16, trim, 0, 0.5, 0, 'z', 16, 0.8);
      break;
    }
    case 'nitrous': {
      cyl(g, 0.16, 0.8, 0x2f7fd8, 0, 0, 0, 'y', 16, 0.5);
      cyl(g, 0.07, 0.14, trim, 0, 0.8, 0, 'y', 10, 0.8);
      box(g, 0.2, 0.05, 0.05, 0xe2412f, 0, 0.94, 0);
      if (tier >= 3) cyl(g, 0.16, 0.8, 0x2f7fd8, 0.36, 0, 0, 'y', 16, 0.5);
      break;
    }
    case 'bullbar': {
      for (const x of [-0.35, 0.35]) cyl(g, 0.04, 0.6, trim, x, 0, 0, 'y', 8, 0.8);
      for (const y of [0.2, 0.55]) cyl(g, 0.04, 0.8, trim, 0, y, 0, 'x', 8, 0.8);
      break;
    }
    case 'paint': {
      cyl(g, 0.16, 0.6, 0xe2412f, 0, 0, 0, 'y', 16, 0.3);
      cyl(g, 0.1, 0.1, 0x3a3f45, 0, 0.6, 0);
      box(g, 0.05, 0.05, 0.12, 0x3a3f45, 0, 0.7, 0.06);
      break;
    }
    default: {
      // a gearbox: a housing and a gear on its face
      box(g, 0.6, 0.45, 0.5, 0x55575b, 0, 0, 0, 0.4);
      const gear = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.06, 6, 12), mat(trim, 0.8, 0.3));
      gear.position.set(0, 0.25, 0.28);
      g.add(gear);
      cyl(g, 0.06, 0.4, trim, 0, 0.25, 0.3, 'z', 8, 0.8);
    }
  }
  return g;
}

export function disposeGroup(g: THREE.Object3D): void {
  g.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) m.geometry.dispose(); });
}
