import { hashString } from '../../world/rng';
import { DAY_H, SEASONS, YEAR_H, type Fields, type Kind, type PressEvent } from './types';

/**
 * The paper's words (docs/newspaper.html, The copy): for each kind of event, three headlines, two bodies of one
 * or two short paragraphs and a brief, filled from the event's own fields and nothing else.
 *
 * `{name}` is a field (or one of the few derived from the event: its day, season and year, the fleet's name);
 * a headline or body whose field is missing is passed over for the next. `[ … ]` is an optional group: it is
 * dropped whole when a field inside it is missing. Numbers in a money field print as money; `{nTh}` is a
 * number's ordinal ("4th") and `{nW}` the number in words up to twelve; `{xS}` is a name's possessive
 * ("Ferrow’s", "Reno Flats’") and `{xA}` a word with its article ("an Otter").
 *
 * Copy is keyed by kind, then by kind and who did it (`:you`, `:firm`, `:world`), then by kind and the event's
 * variant (`:storm`, `:won`): the most particular key whose words fill wins. Within a key, the headline and the
 * body are chosen apart, turned by a hash of the event and away from those used in the last few issues.
 */

interface Tpl { id: string; head: string[]; body: string[][]; brief: string[] }

/** Field names printed as money. */
const MONEY = new Set(['price', 'pay', 'fee', 'worth', 'mark', 'fine']);
const WORDS = ['no', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve'];

export const moneyText = (n: number): string => `${n < 0 ? '−' : ''}$${Math.abs(Math.round(n)).toLocaleString('en-US')}`;
export const ordinal = (n: number): string => `${n}${n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] ?? 'th'}`;

/** The context a template is filled from: the event's fields, formatted, and what is derived from it. */
export type Ctx = Record<string, string>;

export function ctxOf(e: PressEvent, fleet: string): Ctx {
  const c: Ctx = {};
  for (const [k, v] of Object.entries(e.f)) {
    if (typeof v === 'number') {
      if (!Number.isFinite(v)) continue;
      const n = Math.round(v);
      c[k] = MONEY.has(k) ? moneyText(n) : n.toLocaleString('en-US');
      c[`${k}Th`] = ordinal(n);
      c[`${k}W`] = n >= 0 && n < WORDS.length ? WORDS[n] : n.toLocaleString('en-US');
    } else if (v) {
      c[k] = v;
      // with its article: "an Otter", "a Mule"
      c[`${k}A`] = `${/^[aeiou]/i.test(v) ? 'an' : 'a'} ${v}`;
    }
  }
  if (fleet) c.fleet = fleet;
  if (e.who && e.who !== 'you' && !c.firm) c.firm = e.who;
  // possessives: "Ferrow’s", "Reno Flats’"
  for (const k of ['town', 'fleet', 'firm', 'county', 'champion', 'by', 'member', 'friend', 'ride']) if (c[k]) c[`${k}S`] = /s$/i.test(c[k]) ? `${c[k]}’` : `${c[k]}’s`;
  c.day = String(Math.floor(e.t / DAY_H) + 1);
  c.season = c.season ?? SEASONS[Math.floor(e.t / DAY_H) % 4];
  c.year = String(Math.floor(e.t / YEAR_H) + 1);
  return c;
}

/** Fill one template string; null when a field it must have is missing. */
export function fill(s: string, c: Ctx): string | null {
  let missing = false;
  const sub = (x: string, opt: boolean): string | null => {
    let gone = false;
    const r = x.replace(/\{(\w+)\}/g, (_, k: string) => {
      const v = c[k];
      if (v === undefined || v === '') { gone = true; return ''; }
      return v;
    });
    if (gone && !opt) missing = true;
    return gone ? null : r;
  };
  const withOpt = s.replace(/\[([^\]]*)\]/g, (_, g: string) => sub(g, true) ?? '');
  const out = sub(withOpt, false);
  if (missing || out === null) return null;
  const t = out.replace(/\s+/g, ' ').replace(/\s+([,.;:])/g, '$1').trim();
  return t ? t[0].toUpperCase() + t.slice(1) : t;
}

/** Who did it, as the copy is keyed: the player, a rival firm, or the world. */
export const whoClass = (e: PressEvent): 'you' | 'firm' | 'world' => (e.who === 'you' ? 'you' : e.who ? 'firm' : 'world');

/** The templates that could tell this event, most particular first. */
export function tplsFor(e: PressEvent): Tpl[] {
  const keys = [e.v ? `${e.k}:${e.v}` : '', `${e.k}:${whoClass(e)}`, e.k].filter(Boolean);
  const out: Tpl[] = [];
  for (const k of keys) out.push(...(COPY[k] ?? []));
  return out;
}

export interface Told { tpl: Tpl; hid: string; bid: string; head: string; body: string[]; brief: string }

/**
 * How recently each headline and body was used: missing for never, higher for more recent. A choice goes to the
 * unused first, then the longest unused.
 */
export type Recent = Map<string, number>;

/** Indices 0..n-1 turned by `r`, the least recently used first. */
function order(n: number, r: number, id: (i: number) => string, recent: Recent): number[] {
  const out = Array.from({ length: n }, (_, i) => (i + r) % n);
  return out.sort((a, b) => (recent.get(id(a)) ?? 0) - (recent.get(id(b)) ?? 0));
}

/** The event told: a headline, a body and a brief, and which of each. Null when nothing fills. */
export function compose(e: PressEvent, fleet: string, avoid: Recent = new Map()): Told | null {
  const c = ctxOf(e, fleet);
  const r = hashString(`${e.k}|${e.t}|${JSON.stringify(e.f)}`);
  for (const tpl of tplsFor(e)) {
    const brief = tpl.brief.map((b) => fill(b, c)).find((b) => b);
    if (!brief) continue;
    for (const h of order(tpl.head.length, r, (i) => `${tpl.id}.h${i}`, avoid)) {
      const head = fill(tpl.head[h], c);
      if (!head) continue;
      for (const b of order(tpl.body.length, r >>> 5, (i) => `${tpl.id}.b${i}`, avoid)) {
        const body = tpl.body[b].map((p) => fill(p, c));
        if (body.some((p) => p === null)) continue;
        return { tpl, hid: `${tpl.id}.h${h}`, bid: `${tpl.id}.b${b}`, head, body: (body as string[]).filter((p) => p.length > 0), brief };
      }
    }
  }
  return null;
}

/** The literal words of a template, outside its fields: what the gate allows besides the fields' own words. */
export function literalWords(t: Tpl): string[] {
  return [...t.head, ...t.body.flat(), ...t.brief].join(' ').replace(/\{\w+\}/g, ' ').replace(/[[\]]/g, ' ').split(/[^\p{L}\p{N}$’'-]+/u).filter(Boolean);
}

/** A plain check the gate also uses: the words an event's fields allow. */
export function fieldWords(f: Fields, c: Ctx): string[] {
  return [...Object.values(f).map(String), ...Object.values(c)].join(' ').split(/[^\p{L}\p{N}$’'-]+/u).filter(Boolean);
}

// ---- the Press's tone (docs/newspaper.html, Rules 8) --------------------------------------------------

/**
 * How the paper names the player's fleet the first time in its headline story, by the Press's standing with them
 * (factions.ts RUNG: 0 Outcast … 3 Neutral … 6 Sworn). The facts never change, only the words round the name.
 */
export const TONE: ((fleet: string, city: string) => string)[] = [
  (f) => `the much-complained-about ${f}`,
  (f) => `the haulage outfit ${f}`,
  (f) => `the haulage firm ${f}`,
  (f) => f,
  (f, c) => (c ? `${f}, a firm well known in ${c},` : f),
  (f) => `the well-regarded ${f}`,
  (f, c) => (c ? `${/s$/i.test(c) ? `${c}’` : `${c}’s`} own ${f}` : `the trusted ${f}`),
];
/** Every word the tone may add, for the gate. */
export const TONE_WORDS = ['the', 'much-complained-about', 'haulage', 'outfit', 'firm', 'a', 'well', 'known', 'in', 'well-regarded', 'own', 'trusted'];

/** The headline story's first naming of the fleet, in the paper's tone. */
export function toned(paras: string[], fleet: string, rung: number, city: string): string[] {
  const say = TONE[rung];
  if (!say || rung === 3 || !fleet || !paras.length) return paras;
  const out = [...paras];
  // the first plain mention: "Ashby Haulage’s" can't take the words round it ("…, a firm well known in X,’s")
  const plain = (p: string): number => { let k = p.indexOf(fleet); while (k >= 0 && p[k + fleet.length] === '’') k = p.indexOf(fleet, k + 1); return k; };
  const i = out.findIndex((p) => plain(p) >= 0);
  if (i < 0) return paras;
  const p = out[i], at = plain(p);
  let words = say(fleet, city);
  // the start of a sentence takes a capital: "The haulage firm …"
  if (at === 0 || /[.!?]\s$/.test(p.slice(0, at))) words = words[0].toUpperCase() + words.slice(1);
  out[i] = (p.slice(0, at) + words + p.slice(at + fleet.length)).replace(/,\s*,/g, ',').replace(/,\s*([.:;])/g, '$1');
  return out;
}

