const tpl = (id: string, head: string[], body: string[][], brief: string[]): Tpl => ({ id, head, body, brief });

/** A weather: three headlines and two bodies. */
const wx = (id: string, heads: string[], a: string, b: string, brief: string): Tpl[] => [tpl(`weather.${id}`, heads, [[a], [b]], [brief])];

