/**
 * The town economy. Every town, city and megalopolis keeps a small ledger: how much trade has come
 * through it lately (by the player and the CPU alike), a development meter that trade pushes up and
 * neglect pulls down, and what the player has been paid there. At the top of the meter the town
 * grows a step; at the bottom it wears a step; a town that keeps growing graduates to the next kind;
 * a town that has paid the player well sends its mayor round with a tax bill. See docs/economy.html.
 *
 * Only resident time counts: a town's clock runs while its cell is in the 3 × 3 around the player.
 * Every constant the feel depends on is in the table below, and the console can read them all.
 */
/** The Ministry's hand on the player's levy (docs/factions.html), set by game/factions as the bar moves. */
export const LEVY_FAC = { add: 0, halfUnheld: false };

export const ECONOMY = {
  /**
   * What a town of each kind expects, in dollars of goods a game hour: 1.1 × what CPU traffic alone
   * credits once an island has settled, measured 16 Sep 2026 over hours 24–96 of simulated traffic on
   * 8 islands (32 towns), net of expiry: rural 8.3, suburb 15.7, small city 9.0, big city 19.6,
   * megalopolis 83. Small cities had only 6 samples, 2 of them with no CPU trade at all, so they share
   * the suburb figure rather than rank below it. About one town in five gets no CPU trade and will
   * slowly wear unless the player trades there. Re-measure with pr.economy.norms() after changing
   * traffic or cargo.
   */
  norm: { rural: 9, suburb: 17, city: 17, metro: 22, mega: 91 } as Record<TownKind, number>,
  /** Half-life of the activity rate, and of what the player has earned in a town, in game hours. */
  rateHalfLife: 48,
  earnedHalfLife: 72,
  /** Thriving above this prosperity, struggling below that; nothing happens in between. */
  thrive: 1.2,
  struggle: 0.8,
  /** Meter drift per hour: up to +0.09 thriving, down to −0.015 struggling. */
  up: 0.06, upCap: 1.5,
  down: 0.025, downCap: -0.6,
  /** Shares of a delivery credited to each end. */
  toShare: 1, fromShare: 0.5,
  /** Harbours and country sites credit their town at half. */
  indirect: 0.5,
  /** How far a country site looks for a town to credit, in tiles. */
  countryReach: 60,
  /**
   * Goods left to expire on a town's kerb count against it. The scope had −0.25, but only a quarter of
   * the traffic hauls and most waiting loads expire, so at that rate expiry outweighed every delivery
   * and no town could hold level without the player; at −0.05 it is the small signal it was meant to be.
   */
  expired: -0.05,
  /** What a town gets of its neighbours' trade: anywhere in the cell, and between a megalopolis and its satellites. */
  halo: 0.04, haloSatellite: 0.12,
  /** Earned in a town before its mayor asks for 4%, and 4% more for each multiple of it. */
  threshold: { rural: 1200, suburb: 2500, city: 5000, metro: 10000, mega: 25000 } as Record<TownKind, number>,
  taxStep: 4, taxCap: 40,
  /** A fresh ledger starts the town where the CPU alone would keep it. */
  startAt: 0.9,
  /**
   * One building's own trade, for the inspector: a building's rate settles at the dollars an hour
   * flowing through its door, so an ordinary $120 load a day holds it near $5/h. Each such $5/h lifts
   * the building a quarter above its town, up to four of them (double).
   */
  lotUnit: 5, lotLift: 0.25, lotLiftCap: 4,
};

/** One municipality's books. `touched` is not saved: a record is only written down once something happened. */
export interface TownLedger {
  rate: number;
  meter: number;
  hours: number;
  grown: number;
  blight: number;
  kind?: TownKind;
  earned: number;
  tax: number;
  touched?: boolean;
  /**
   * The town's last HIST_DAYS days (docs/townregister.html): its trade rate at each of its own midnights (every 24
   * hours its clock has run), newest first, and how many buildings it had grown by then, in step.
   */
  hist?: number[];
  histGrown?: number[];
}

/** Days of a town's trade history kept. */
export const HIST_DAYS = 30;

/** A saved or shared history, made safe: numbers only, HIST_DAYS at most. */
function cleanHist(v: unknown): number[] | undefined {
  if (!Array.isArray(v)) return undefined;
  const out = v.map(Number).filter((n) => Number.isFinite(n) && n >= 0).slice(0, HIST_DAYS);
  return out.length ? out : undefined;
}

/** A saved or shared ledger's history, cleaned, as fields to spread onto the kept one (none when it has none). */
function cleanHists(r: TownLedger): Pick<TownLedger, 'hist' | 'histGrown'> {
  const hist = cleanHist(r.hist);
  if (!hist) return {};
  const grown = cleanHist(r.histGrown) ?? [];
  return { hist, histGrown: grown.slice(0, hist.length) };
}

/** The history fields of a ledger, to copy onto a saved or shared one. */
function histOf(r: TownLedger): Pick<TownLedger, 'hist' | 'histGrown'> {
  return r.hist?.length ? { hist: r.hist.slice(0, HIST_DAYS), histGrown: (r.histGrown ?? []).slice(0, HIST_DAYS) } : {};
}

type Mood = 'Thriving' | 'Growing' | 'Steady' | 'Struggling';

/**
 * What the player's company has done in one town, for the town card (docs/towns.html): never decays,
 * only ever added to. Written at each delivery of the player's or a hired driver's.
 */
export interface TownBook {
  /** Deliveries dropped here, and picked up here. */
  ins: number; outs: number;
  /** Dollars paid for loads dropped here, split by who drove: the player's own hand, and the fleet's. */
  mine: number; fleet: number;
  /** The levy this town took off those deliveries. */
  tax: number;
  /** What was earned here on each of the last BOOK_DAYS game days, newest first, the first being day `d0`. */
  days: number[]; d0: number;
  /** Deliveries here by driver name; '' is the player. */
  by: Record<string, number>;
  /** The first delivery: the game day, who drove ('' the player) and what it was. */
  first?: [number, string, string];
  /** The biggest single payout. */
  best?: number;
}

/** Days of earnings a town's book keeps, for the card's sparkline. */
const BOOK_DAYS = 14;

/**
 * One building's own trade (or one harbour's): goods delivered to it and sent out from it, by anyone.
 * `rate` is dollars a game hour decaying at the town's half-life, last brought up to date at hour `at`.
 */
export interface LotLedger { rate: number; at: number; ins: number; outs: number; value: number; mine: number; lost: number }

/** Every building kind goods come from or go to. */
const TRADE_KINDS = new Set<string>(CARGO.flatMap((t) => [...t.from, ...t.to]));

/** What the inspector shows for a building: the town it trades through, and its own trade on top. */
interface LotReport {
  /** The town whose books it is on, and how: a building in the town, a harbour serving it, or a country place near it. */
  town: Town | null;
  via: 'town' | 'harbour' | 'country' | null;
  mood: Mood | null;
  prosperity: number;
  townRate: number;
  townNorm: number;
  tax: number;
  /** Whether goods ever come from or go to a building of this kind. */
  trades: boolean;
  lot: LotLedger | null;
  /** Its own trade now, in dollars an hour, and the rate that lifts it one step (about a load a day). */
  lotRate: number;
  lotNorm: number;
  /** The town's share of the index, the building's own lift on top, and the two multiplied. */
  townFactor: number;
  ownFactor: number;
  index: number;
  verdict: string;
}

/** Where a site's trade counts: the town, and the share it gets. */
interface Credit { w: World; t: Town; share: number; direct: boolean }

export const townKey = (w: World, t: Town): string => `${w.cx},${w.cz}#${t.id}`;

/** Whose books a cargo site's trade goes on: its building's, or its harbour's. */
function siteLotKey(s: Site): string | null {
  if (s.port >= 0) return `${s.w.cx},${s.w.cz}#p${s.port}`;
  return s.b && s.b.uid >= 0 ? `${s.w.cx},${s.w.cz}#b${s.b.uid}` : null;
}

/** The deed book (game/estate.ts), told about trade at every door and every building boarded up. */
export interface EstateHook {
  trade(key: string, amount: number, dir: 'in' | 'out', player: boolean, s: Site, by?: Who): void;
  worn(w: World, uid: number): void;
}

/** What the ledger needs from the game around it. */
interface EconomyHost {
  /** Islands in memory, for the console. */
  resident(): World[];
  /**
   * Islands whose towns' clocks run: the one the player is on. Its neighbours run a third of the
   * traffic, so their towns would read as struggling by construction; they keep time when you get there.
   */
  ticking(): World[];
  /** The edit list of a cell, to write growth into. */
  delta(w: World): CellDelta;
  /** Tiles of an island changed: rebuild drivability, meshes, sites and traffic. `redraw` only repaints. */
  changed(w: World, tiles: number[], redraw?: boolean): void;
  /** A title card. */
  announce(title: string, body: string): void;
  /** The mayor's letter. */
  levy(l: Levy): void;
  /** A town's kind or name has changed, so labels must be built again. */
  relabel(): void;
}

export class Economy {
  readonly towns = new Map<string, TownLedger>();
  /** Everything credited while no player was involved, and town-hours resident, by kind: the calibration run's numbers. */
  private calib = new Map<TownKind, { dollars: number; hours: number }>();
  private lastHour = -1;
  /** True while booking a delivery the player had nothing to do with, so the calibration counts it. */
  private cpu = false;
  /** Per-building (and per-harbour) trade, keyed `cx,cz#b<uid>` or `cx,cz#p<port id>`. */
  readonly lots = new Map<string, LotLedger>();
  /** The game clock in hours, to the fraction, for decaying a building's rate. */
  private clock = 0;
  /** What the company has done in each town it ever delivered to or from, keyed like `towns`. */
  readonly books = new Map<string, TownBook>();
  /** The player's deeds: paid out of the same two calls that credit a building's own books. */
  estate: EstateHook | null = null;
  /** The player's plants (docs/supplychains.html, game/chains/plants.ts): told of every delivery, to fill bins and pay makers. */
  plants: { delivered(it: CargoItem, player: boolean): void } | null = null;
  /** Who has been carrying each town's trade lately, and who it prefers (docs/rivals.html). */
  readonly carriage = new Carriage(() => this.clock);
  /** Fleets' asks for what a town builds next (docs/lobbying.html), set by main. */
  lobby: Lobby | null = null;
  /**
   * A town twinned with a culture it imported (docs/passport.html) builds some of its own growth in that style:
   * the style for the building this step puts up, or null for the town's own. Set by main.
   */
  styleFor: ((w: World, t: Town, step: number) => Arch | null) | null = null;
  /** Told once per game hour that has passed, after the towns' own tick: territory's tally (docs/territory.html). */
  onHour: ((hour: number) => void) | null = null;
  /**
   * Online (src/net): told what each delivery of the player's company put on a town's books and on a
   * door's, so trade in a county another player's game is running can be sent to that game to book.
   */
  onBooked: ((b: { town: string; amount: number; lot: string | null; lotAmount: number; dir: 'in' | 'out' }) => void) | null = null;
  /** Online: the player's rent counted on a town's carriage, for the game running that town (net/online.ts). */
  onRentBooked: ((town: string, amount: number) => void) | null = null;

  constructor(private host: EconomyHost) {}

  /** The game clock in hours, as last seen by `update`. */
  get hours(): number { return this.clock; }

  // ---- the books ----

  ensure(w: World, t: Town): TownLedger {
    const key = townKey(w, t);
    let r = this.towns.get(key);
    if (!r) {
      r = { rate: ECONOMY.norm[t.kind] * ECONOMY.startAt, meter: 0, hours: 0, grown: 0, blight: 0, earned: 0, tax: 0 };
      this.towns.set(key, r);
    }
    return r;
  }

  /** How the town is doing against what a place its size expects; boarded-up buildings lower the bar. */
  prosperity(w: World, t: Town): number {
    const r = this.ensure(w, t);
    const built = Math.max(1, builtCount(t));
    const down = t.buildings.filter((b) => b.derelict && !b.gone && b.solid).length;
    return r.rate / (ECONOMY.norm[t.kind] * Math.max(0.3, 1 - down / built));
  }

  mood(w: World, t: Town): Mood {
    const p = this.prosperity(w, t);
    return p >= 1.6 ? 'Thriving' : p > ECONOMY.thrive ? 'Growing' : p < ECONOMY.struggle ? 'Struggling' : 'Steady';
  }

  /** Put money on a town's books, and a little on its neighbours'. */
  credit(w: World, t: Town, amount: number, halo = true): void {
    const r = this.ensure(w, t);
    r.rate = Math.max(0, r.rate + (amount * Math.LN2) / ECONOMY.rateHalfLife);
    r.touched = true;
    if (this.cpu) {
      const k = this.calib.get(t.kind) ?? { dollars: 0, hours: 0 };
      k.dollars += amount;
      this.calib.set(t.kind, k);
    }
    if (!halo || amount <= 0) return;
    for (const o of w.towns) {
      if (o === t) continue;
      const share = o.parent === t.id || t.parent === o.id ? ECONOMY.haloSatellite : ECONOMY.halo;
      this.credit(w, o, amount * share, false);
    }
  }

  /** The town a site's trade counts for, if any. */
  private creditFor(s: Site | null): Credit | null {
    if (!s) return null;
    const w = s.w;
    if (s.port >= 0) {
      const p = w.ports.find((q) => q.id === s.port);
      const t = p && p.town >= 0 ? w.towns[p.town] : undefined;
      return t ? { w, t, share: ECONOMY.indirect, direct: false } : null;
    }
    const x = Math.floor(s.lx), z = Math.floor(s.lz);
    if (inB(x, z)) {
      // a kerb in town, or the tile beside it
      for (const [dx, dz] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
        if (!inB(x + dx, z + dz)) continue;
        const id = w.townId[idx(x + dx, z + dz)];
        if (id >= 0 && w.towns[id]) return { w, t: w.towns[id], share: 1, direct: true };
      }
    }
    // out in the country: the nearest town on the same island, if there is one close enough
    let best: Town | null = null, bestD = ECONOMY.countryReach;
    for (const t of w.towns) {
      const d = Math.hypot(t.x0 + t.size / 2 - s.lx, t.z0 + t.size / 2 - s.lz) - t.size / 2;
      if (d < bestD) { bestD = d; best = t; }
    }
    return best ? { w, t: best, share: ECONOMY.indirect, direct: false } : null;
  }

  /**
   * The levy on a delivery, as a fraction: the destination town's rate, and half the origin's. A town's
   * territory holder pays half its rate there, and none when it is strong (docs/standing.html); `who` is the
   * carrier, the player's company unless a rival firm's id is given.
   */
  taxOf(it: CargoItem, who: string = YOU): number {
    const to = this.creditFor(it.to), from = this.creditFor(it.from);
    let pct = 0;
    if (to?.direct) pct += this.facLevy(this.ensure(to.w, to.t).tax * this.carriage.levyMul(townKey(to.w, to.t), who), townKey(to.w, to.t), who);
    if (from?.direct) pct += this.facLevy((this.ensure(from.w, from.t).tax / 2) * this.carriage.levyMul(townKey(from.w, from.t), who), townKey(from.w, from.t), who, 0.5);
    return pct / 100;
  }

  /**
   * The Ministry's say in a town's levy on the player (docs/factions.html): Hostile, LEVY_FAC.add more
   * percent everywhere; Sworn, half in every town the player doesn't already hold.
   */
  private facLevy(pct: number, key: string, who: string, share = 1): number {
    if (who !== YOU) return pct;
    if (LEVY_FAC.halfUnheld && this.carriage.preferred(key) !== YOU) pct *= 0.5;
    return pct > 0 ? pct + LEVY_FAC.add * share : pct;
  }

  /** The key of the town whose books a site's trade goes on, or '' for none. */
  townKeyOf(s: Site | null): string {
    const c = this.creditFor(s);
    return c ? townKey(c.w, c.t) : '';
  }

  /**
   * Goods have arrived. `paid` is what the player was actually paid, after tax; 0 for the CPU. `firm` is
   * the rival firm that carried them, if one did: the towns count who carried their trade.
   */
  delivered(it: CargoItem, player: boolean, paid: number, by?: string, firm?: string): void {
    const to = this.creditFor(it.to), from = this.creditFor(it.from);
    const who = player ? YOU : firm ?? '';
    // the anonymous haulers are every town's background trade already (carriage.ts, CARRIAGE.momentum),
    // near the player or far: their real vans would count it twice, and only where somebody is watching
    const counts = (_c: Credit) => who !== '';
    if (to && counts(to)) this.carriage.credit(townKey(to.w, to.t), who, it.value0 * ECONOMY.toShare * to.share, true);
    if (from && counts(from)) this.carriage.credit(townKey(from.w, from.t), who, it.value0 * ECONOMY.fromShare * from.share, true);
    if (player && this.onBooked) {
      if (to) this.onBooked({ town: townKey(to.w, to.t), amount: it.value0 * ECONOMY.toShare * to.share, lot: it.to ? siteLotKey(it.to) : null, lotAmount: it.value0 * ECONOMY.toShare, dir: 'in' });
      if (from) this.onBooked({ town: townKey(from.w, from.t), amount: it.value0 * ECONOMY.fromShare * from.share, lot: it.from ? siteLotKey(it.from) : null, lotAmount: it.value0 * ECONOMY.fromShare, dir: 'out' });
    }
    if (player) this.bookDelivery(it, to, from, paid, by ?? '');
    // the towns the company deals with publish its paper (docs/newspaper.html)
    if (player) { if (to) press.dealt(townKey(to.w, to.t)); if (from) press.dealt(townKey(from.w, from.t)); }
    // who drove it, for the books' rent by who (docs/hqwindow.html): a hired driver's load names its driver
    const rentBy = player ? (by ? 'crew' : 'you') : 'other';
    this.lotCredit(it.to, it.value0 * ECONOMY.toShare, 'in', player, rentBy);
    this.lotCredit(it.from, it.value0 * ECONOMY.fromShare, 'out', player, rentBy);
    this.plants?.delivered(it, player);
    this.cpu = !player;
    if (to) this.credit(to.w, to.t, it.value0 * ECONOMY.toShare * to.share);
    if (from) this.credit(from.w, from.t, it.value0 * ECONOMY.fromShare * from.share);
    this.cpu = false;
    if (!player || paid <= 0) return;
    this.by = by;
    if (to?.direct) this.earn(to, paid);
    if (from?.direct) this.earn(from, paid / 2);
    this.by = undefined;
  }

  /** The company driver whose delivery is being booked, for the mayor's letter. */
  private by: string | undefined;

  // ---- the company's books in each town ----

  /** A town's book, rolled forward to today; made when `make` is set. */
  book(key: string, make = false): TownBook | null {
    let b = this.books.get(key);
    if (!b) {
      if (!make) return null;
      b = { ins: 0, outs: 0, mine: 0, fleet: 0, tax: 0, days: [], d0: this.day(), by: {} };
      this.books.set(key, b);
    }
    const today = this.day();
    if (today > b.d0) {
      const shift = Math.min(BOOK_DAYS, today - b.d0);
      for (let k = 0; k < shift; k++) b.days.unshift(0);
      b.days.length = Math.min(b.days.length, BOOK_DAYS);
      b.d0 = today;
    }
    return b;
  }

  private day(): number { return Math.floor(this.clock / 24); }

  /**
   * One delivery of the company's on the towns' books: the drop counted where it was dropped and the
   * pickup where it was picked up (a harbour's to the town it serves), the money where it was paid
   * (the drop), and each town's share of the levy where that town took it.
   */
  private bookDelivery(it: CargoItem, to: Credit | null, from: Credit | null, paid: number, by: string): void {
    if (to) {
      const b = this.book(townKey(to.w, to.t), true)!;
      b.ins++;
      if (by) b.fleet += paid; else b.mine += paid;
      if (!b.days.length) b.days.push(0);
      b.days[0] += paid;
      b.by[by] = (b.by[by] ?? 0) + 1;
      b.first ??= [this.day(), by, it.type.name];
      b.best = Math.max(b.best ?? 0, Math.round(paid));
      if (to.direct) b.tax += Math.round(it.value * this.ensure(to.w, to.t).tax / 100);
    }
    if (from) {
      // picked up and dropped in the same town, both ends go on its book
      const b = this.book(townKey(from.w, from.t), true)!;
      b.outs++;
      b.first ??= [this.day(), by, it.type.name];
      if (from.direct) b.tax += Math.round(it.value * this.ensure(from.w, from.t).tax / 200);
    }
  }

  /** The books as they are written down: whole dollars, only towns with something in them. */
  booksToSave(): Record<string, TownBook> {
    const out: Record<string, TownBook> = {};
    for (const [k, b] of this.books) {
      if (!b.ins && !b.outs) continue;
      out[k] = { ...b, mine: Math.round(b.mine), fleet: Math.round(b.fleet), days: b.days.map((v) => Math.round(v)) };
    }
    return out;
  }

  booksFromSave(saved: Record<string, TownBook> | undefined): void {
    this.books.clear();
    for (const [k, b] of Object.entries(saved ?? {})) {
      if (!b || typeof b.ins !== 'number') continue;
      this.books.set(k, { ...b, days: Array.isArray(b.days) ? b.days.slice(0, BOOK_DAYS) : [], d0: b.d0 ?? 0, by: b.by ?? {} });
    }
  }

  /** A fleet unit on the books has earned in a town: credited straight to it, as the player's trade. */
  creditKey(key: string, dollars: number): void {
    const [cell, id] = key.split('#');
    const [cx, cz] = cell.split(',').map(Number);
    const w = this.host.resident().find((q) => q.cx === cx && q.cz === cz);
    const t = w?.towns[Number(id)];
    if (w && t && dollars > 0) this.credit(w, t, dollars);
  }

  /**
   * Rent a door's owner took from a delivery there (before the levy, within the door's ceiling) counts on
   * the town's carriage as the owner's: holding the doors a town's trade passes through is a share of it.
   * Not new trade, so the town's own figures are left alone. `who` is YOU or a rival firm's id.
   */
  rentShare(key: string, who: string, amount: number): void {
    if (!key || !(amount > 0)) return;
    this.carriage.credit(key, who, amount);
    if (who === YOU) this.onRentBooked?.(key, amount);
  }

  /**
   * Online: trade another player's company did in a town this game is running, booked here as that
   * company's: on the town's carriage, on its rate, and on the door's own books. Their rent and their
   * levy are their own game's business.
   */
  creditRemote(key: string, who: string, amount: number, lot: string | null, lotAmount: number, dir: 'in' | 'out', rent = false): void {
    if (!(amount > 0)) return;
    // rent another company took at its doors here: its carriage only, as rentShare books it
    if (rent) { this.carriage.credit(key, who, amount); return; }
    this.carriage.credit(key, who, amount);
    this.creditKey(key, amount);
    if (!lot || !(lotAmount > 0)) return;
    const l = this.lot(lot, true)!;
    l.rate += (lotAmount * Math.LN2) / ECONOMY.rateHalfLife;
    l.value += lotAmount;
    if (dir === 'in') l.ins++; else l.outs++;
  }

  /**
   * Online: a town's books as the game running it has them. What the town has paid this player, and
   * the levy it takes from them, are this player's own and are kept.
   */
  importTown(key: string, r: TownLedger): void {
    if (!r || typeof r.rate !== 'number') return;
    const mine = this.towns.get(key);
    this.towns.set(key, {
      rate: r.rate, meter: Number(r.meter) || 0, hours: Number(r.hours) || 0, grown: Number(r.grown) || 0, blight: Number(r.blight) || 0,
      ...(r.kind ? { kind: r.kind } : {}), earned: mine?.earned ?? 0, tax: mine?.tax ?? 0, touched: true,
      ...cleanHists(r),
    });
  }

  /** Online: one town's books as they are written down, or null when nothing has happened there. */
  exportTown(key: string): TownLedger | null {
    const r = this.towns.get(key);
    if (!r || !r.touched) return null;
    const s: TownLedger = { rate: Math.round(r.rate * 10) / 10, meter: Math.round(r.meter * 1000) / 1000, hours: r.hours, grown: r.grown, blight: r.blight, earned: 0, tax: 0, ...histOf(r) };
    if (r.kind) s.kind = r.kind;
    return s;
  }

  /** The player has been paid in a town: once that passes the town's threshold, the mayor writes. */
  private earn(c: Credit, amount: number): void {
    const r = this.ensure(c.w, c.t);
    r.earned += amount;
    r.touched = true;
    const want = Math.min(ECONOMY.taxCap, ECONOMY.taxStep * Math.floor(r.earned / ECONOMY.threshold[c.t.kind]));
    if (want > r.tax) {
      r.tax = want;
      deeds.mark('mayors', `${c.w.seed}|${townKey(c.w, c.t)}`);
      this.host.levy({ town: plainName(c.t), rate: want, earned: Math.round(r.earned), by: this.by });
    }
  }

  /** Goods left to rot on a town's kerb. */
  expired(it: CargoItem): void {
    const key = it.from ? siteLotKey(it.from) : null;
    if (key) { const l = this.lot(key, true)!; l.lost++; l.rate = Math.max(0, l.rate + (it.value0 * ECONOMY.expired * Math.LN2) / ECONOMY.rateHalfLife); }
    const from = this.creditFor(it.from);
    if (!from?.direct) return;
    this.cpu = true;
    this.credit(from.w, from.t, it.value0 * ECONOMY.expired, false);
    this.cpu = false;
  }

  // ---- one building's trade ----

  /** A building's (or harbour's) books, brought up to the hour; made when `make` is set. */
  private lot(key: string, make = false): LotLedger | null {
    let l = this.lots.get(key);
    if (!l) {
      if (!make) return null;
      l = { rate: 0, at: this.clock, ins: 0, outs: 0, value: 0, mine: 0, lost: 0 };
      this.lots.set(key, l);
    }
    if (this.clock > l.at) {
      l.rate *= 0.5 ** ((this.clock - l.at) / ECONOMY.rateHalfLife);
      l.at = this.clock;
    }
    return l;
  }

  private lotCredit(s: Site | null, amount: number, dir: 'in' | 'out', player: boolean, by: Who = player ? 'you' : 'other'): void {
    const key = s ? siteLotKey(s) : null;
    if (!key) return;
    const l = this.lot(key, true)!;
    l.rate += (amount * Math.LN2) / ECONOMY.rateHalfLife;
    l.value += amount;
    if (dir === 'in') l.ins++; else l.outs++;
    if (player) l.mine++;
    // a deed on this door takes its share (docs/property.html); it reads the books and never writes them
    this.estate?.trade(key, amount, dir, player, s!, by);
  }

  /** The levy, in percent, a town takes on trade at this site: only a site in the town itself pays it. */
  levyAt(s: Site, who: string = YOU): number {
    const c = this.creditFor(s);
    return c?.direct ? this.facLevy(this.ensure(c.w, c.t).tax * this.carriage.levyMul(townKey(c.w, c.t), who), townKey(c.w, c.t), who) : 0;
  }

  /** Take the boards off one building of the player's, now: the same edit growth mends with. */
  mendLot(w: World, b: Building): boolean {
    if (!b.derelict || b.gone || b.uid < 0) return false;
    const edit: Parameters<typeof applyEdit>[1] = { k: 'wear', u: b.uid, on: 0 };
    this.host.delta(w).edits.push(edit);
    const t = w.towns.find((q) => q.buildings.includes(b));
    const tiles = applyEdit(w, edit);
    if (t) {
      const r = this.ensure(w, t);
      r.blight = t.buildings.filter((q) => q.derelict && !q.gone).length;
      r.touched = true;
    }
    this.host.changed(w, tiles);
    return true;
  }

  /** How a building is doing: its town's economy, lifted by whatever trade comes to and from its own door. */
  report(w: World, b: Building): LotReport {
    // a harbour's sheds share the harbour's books; anything else keeps its own
    const port = w.ports.find((p) => p.buildings.includes(b));
    const lot = this.lot(port ? `${w.cx},${w.cz}#p${port.id}` : `${w.cx},${w.cz}#b${b.uid}`);
    const trades = !!port || TRADE_KINDS.has(b.kind);
    let town: Town | null = null, via: LotReport['via'] = null, share = 1;
    if (port) {
      town = port.town >= 0 ? w.towns[port.town] ?? null : null;
      via = town ? 'harbour' : null;
      share = ECONOMY.indirect;
    } else {
      town = w.towns.find((t) => t.buildings.includes(b)) ?? null;
      if (town) via = 'town';
      else if (trades) {
        // out in the country: on the books of the nearest town close enough, as goods from here are
        let bestD = ECONOMY.countryReach;
        for (const t of w.towns) {
          const d = Math.hypot(t.x0 + t.size / 2 - (b.x + b.w / 2), t.z0 + t.size / 2 - (b.z + b.d / 2)) - t.size / 2;
          if (d < bestD) { bestD = d; town = t; }
        }
        if (town) { via = 'country'; share = ECONOMY.indirect; }
      }
    }
    const books = town ? this.ensure(w, town) : null;
    const prosperity = town ? this.prosperity(w, town) : 1;
    const townNorm = town ? ECONOMY.norm[town.kind] : 0;
    const lotNorm = ECONOMY.lotUnit;
    const lotRate = lot?.rate ?? 0;
    const townFactor = town ? 1 + (prosperity - 1) * share : 1;
    const ownFactor = 1 + ECONOMY.lotLift * Math.min(ECONOMY.lotLiftCap, Math.max(0, lotRate) / lotNorm);
    const index = b.derelict ? 0 : Math.max(0, townFactor * ownFactor);
    const verdict = b.derelict ? 'Boarded up' : index < 0.8 ? 'Struggling' : index < 1.1 ? 'Getting by' : index < 1.6 ? 'Doing well' : 'Booming';
    return {
      town, via, mood: town ? this.mood(w, town) : null, prosperity, townRate: books?.rate ?? 0, townNorm, tax: books?.tax ?? 0,
      trades, lot, lotRate, lotNorm, townFactor, ownFactor, index, verdict,
    };
  }

  // ---- time ----

  /** Called every frame with the game clock in hours; runs one tick per whole game hour that has passed. */
  update(hours: number): void {
    this.clock = hours;
    const h = Math.floor(hours);
    if (this.lastHour < 0 || h < this.lastHour || h - this.lastHour > 48) { this.lastHour = h; return; }
    let n = 0;
    while (this.lastHour < h && n++ < 6) {
      this.lastHour++;
      this.hourly(this.lastHour);
      this.onHour?.(this.lastHour);
    }
  }

  /** Forget where the clock was, so loading a save does not run the hours in between. */
  resetClock(): void { this.lastHour = -1; }

  private hourly(hour: number): void {
    const rateDecay = 0.5 ** (1 / ECONOMY.rateHalfLife), earnDecay = 0.5 ** (1 / ECONOMY.earnedHalfLife);
    for (const w of this.host.ticking()) {
      for (const t of w.towns) {
        const r = this.ensure(w, t);
        r.hours++;
        r.rate *= rateDecay;
        r.earned *= earnDecay;
        // the town's midnight, by its own clock: a day of its history
        if (r.hours % 24 === 0) {
          (r.hist ??= []).unshift(Math.round(r.rate * 10) / 10);
          (r.histGrown ??= []).unshift(r.grown);
          r.hist.length = Math.min(r.hist.length, HIST_DAYS);
          r.histGrown.length = Math.min(r.histGrown.length, HIST_DAYS);
          r.touched = true;
        }
        const k = this.calib.get(t.kind) ?? { dollars: 0, hours: 0 };
        k.hours++;
        this.calib.set(t.kind, k);
        const p = this.prosperity(w, t);
        const drift = p > ECONOMY.thrive ? ECONOMY.up * Math.min(ECONOMY.upCap, p - 1)
          : p < ECONOMY.struggle ? ECONOMY.down * Math.max(ECONOMY.downCap, p - 1) : 0;
        r.meter = Math.max(-1, Math.min(1, r.meter + drift));
        if (Math.abs(drift) > 0) r.touched = true;
        if (r.meter >= 1 && this.grow(w, t, hour)) r.meter = 0;
        else if (r.meter <= -1) { this.wear(w, t); r.meter = 0; }
      }
    }
  }

  /** A growth step: mend the newest blight if there is any, else grow. False when nothing fitted. */
  private grow(w: World, t: Town, hour: number): boolean {
    const r = this.ensure(w, t);
    const d = this.host.delta(w);
    const rng = mulberry32(hashString(`${w.seed}|${w.cx},${w.cz}|${t.id}|${r.grown}|grow`));
    const down = new Set(t.buildings.filter((b) => b.derelict && !b.gone).map((b) => b.uid));
    let edits: Parameters<typeof applyEdit>[1][] | null = null;
    if (down.size) {
      // the boards come down in the order they went up, newest first
      for (let k = d.edits.length - 1; k >= 0 && !edits; k--) {
        const e = d.edits[k];
        if (e.k === 'wear' && e.on === 1 && down.has(e.u)) edits = [{ k: 'wear', u: e.u, on: 0 }];
      }
      edits ??= [{ k: 'wear', u: [...down][0], on: 0 }];
    } else {
      // a fleet's ask gets its chance first (docs/lobbying.html); on its own branch the town is untouched
      const seed = `${w.seed}|${w.cx},${w.cz}|${t.id}|${r.grown}|grow`;
      edits = this.lobby?.step(w, t, r.grown, hour, () => mulberry32(hashString(seed))) ?? null;
      if (!edits) {
        edits = chooseGrowth(w, t, rng, r.grown, hour);
        for (const e of edits ?? []) {
          if (e.k !== 'build' || e.b.length > 11) continue;
          const style = this.styleFor?.(w, t, r.grown);
          if (style && style !== t.style) e.b.push(style);
        }
      }
    }
    if (!edits) return false;
    const tiles: number[] = [];
    for (const e of edits) {
      d.edits.push(e);
      tiles.push(...applyEdit(w, e));
    }
    r.grown++;
    r.touched = true;
    r.blight = t.buildings.filter((b) => b.derelict && !b.gone).length;
    this.graduate(w, t);
    this.host.changed(w, tiles);
    this.lobby?.after(w, t);
    return true;
  }

  /** A blight step: one building boarded up. */
  private wear(w: World, t: Town): boolean {
    const r = this.ensure(w, t);
    const rng = mulberry32(hashString(`${w.seed}|${w.cx},${w.cz}|${t.id}|${r.hours}|wear`));
    const e = chooseBlight(t, rng);
    if (!e) return false;
    this.host.delta(w).edits.push(e);
    const tiles = applyEdit(w, e);
    r.blight = t.buildings.filter((b) => b.derelict && !b.gone).length;
    r.touched = true;
    this.host.changed(w, tiles);
    if (e.k === 'wear') this.estate?.worn(w, e.u);
    return true;
  }

  /** A town that has grown enough becomes the next kind up. */
  private graduate(w: World, t: Town): void {
    const to = readyToGraduate(t);
    if (!to) return;
    const r = this.ensure(w, t);
    // the books carry over at the same prosperity: a new suburb is as busy, for a suburb, as the town was
    r.rate *= ECONOMY.norm[to] / ECONOMY.norm[t.kind];
    r.kind = to;
    setKind(t, to);
    deeds.add('graduations');
    this.host.announce(t.name, `is now a ${TOWN_INFO[to].label.toLowerCase()}`);
    graduated(w, t, TOWN_INFO[to].label.toLowerCase());
    this.host.relabel();
  }

  // ---- what a finished town request does (game/requests.ts) --------------------------------------

  /**
   * The town a cargo site's trade counts for. A request uses it to know whose errand a step is.
   */
  townFor(s: Site | null): { w: World; t: Town } | null {
    const c = this.creditFor(s);
    return c ? { w: c.w, t: c.t } : null;
  }

  /**
   * A chain's reward, in the town's own books: the same credit a delivery makes, so the meter moves
   * by the town's own rules rather than by anything the chain invented.
   */
  creditChain(w: World, t: Town, dollars: number): void {
    this.credit(w, t, dollars);
    this.ensure(w, t).touched = true;
  }

  /** Mend the newest boarded-up building now, ahead of the growth queue. False when there is none. */
  mendOne(w: World, t: Town): boolean {
    const down = t.buildings.filter((b) => b.derelict && !b.gone);
    if (!down.length) return false;
    const d = this.host.delta(w);
    const uids = new Set(down.map((b) => b.uid));
    let edit: Parameters<typeof applyEdit>[1] | null = null;
    for (let k = d.edits.length - 1; k >= 0 && !edit; k--) {
      const e = d.edits[k];
      if (e.k === 'wear' && e.on === 1 && uids.has(e.u)) edit = { k: 'wear', u: e.u, on: 0 };
    }
    edit ??= { k: 'wear', u: down[0].uid, on: 0 };
    d.edits.push(edit);
    const r = this.ensure(w, t);
    r.blight = Math.max(0, down.length - 1);
    r.touched = true;
    this.host.changed(w, applyEdit(w, edit));
    return true;
  }

  /** One growth step now: whatever the town wanted next is built today instead of in a few days. */
  growNow(w: World, t: Town): boolean {
    return this.grow(w, t, Math.floor(this.clock));
  }

  /** The levy down a rung, for good: 4% off every delivery into this town. */
  easeLevy(w: World, t: Town): boolean {
    const r = this.ensure(w, t);
    if (r.tax <= 0) return false;
    r.tax = Math.max(0, r.tax - ECONOMY.taxStep);
    r.touched = true;
    return true;
  }

  /** Graduate it now, wherever its meter stands. False when it is already as big as it gets. */
  graduateNow(w: World, t: Town): boolean {
    const g = GRADUATION[t.kind];
    if (!g || (t.parent !== undefined && g.to === 'metro')) return false;
    const r = this.ensure(w, t);
    r.rate *= ECONOMY.norm[g.to] / ECONOMY.norm[t.kind];
    r.kind = g.to;
    r.touched = true;
    setKind(t, g.to);
    deeds.add('graduations');
    this.host.announce(t.name, `is now a ${TOWN_INFO[g.to].label.toLowerCase()}`);
    graduated(w, t, TOWN_INFO[g.to].label.toLowerCase());
    this.host.relabel();
    return true;
  }

  /** An island has just been generated: give its towns the kinds they graduated to, before its edits replay. */
  applyKinds(w: World): void {
    for (const t of w.towns) {
      const r = this.towns.get(townKey(w, t));
      if (r?.kind && r.kind !== t.kind) setKind(t, r.kind);
    }
  }

  // ---- saving ----

  toSave(): Record<string, TownLedger> {
    const out: Record<string, TownLedger> = {};
    for (const [k, r] of this.towns) {
      if (!r.touched) continue;
      const s: TownLedger = {
        rate: Math.round(r.rate * 10) / 10, meter: Math.round(r.meter * 1000) / 1000, hours: r.hours,
        grown: r.grown, blight: r.blight, earned: Math.round(r.earned), tax: r.tax, ...histOf(r),
      };
      if (r.kind) s.kind = r.kind;
      out[k] = s;
    }
    return out;
  }

  /** Buildings' own trade, as [rate, hour, in, out, value, yours, lost]: only those that ever traded. */
  lotsToSave(): Record<string, number[]> {
    const out: Record<string, number[]> = {};
    for (const [k, l] of this.lots) {
      if (!l.ins && !l.outs && !l.lost) continue;
      out[k] = [Math.round(l.rate * 100) / 100, Math.round(l.at * 10) / 10, l.ins, l.outs, Math.round(l.value), l.mine, l.lost];
    }
    return out;
  }

  lotsFromSave(saved: Record<string, number[]> | undefined): void {
    this.lots.clear();
    for (const [k, v] of Object.entries(saved ?? {})) {
      if (!Array.isArray(v) || v.length < 7) continue;
      const [rate, at, ins, outs, value, mine, lost] = v;
      this.lots.set(k, { rate, at, ins, outs, value, mine, lost });
    }
  }

  fromSave(saved: Record<string, TownLedger> | undefined): void {
    this.towns.clear();
    this.calib.clear();
    this.resetClock();
    for (const [k, r] of Object.entries(saved ?? {})) {
      const { hist: _h, histGrown: _g, ...rest } = r;
      this.towns.set(k, { ...rest, touched: true, ...cleanHists(r) });
    }
  }

  // ---- console ----

  /** Every resident town, one line each. */
  list(): string[] {
    const out: string[] = [];
    for (const w of this.host.resident()) {
      for (const t of w.towns) {
        const r = this.ensure(w, t);
        const p = this.prosperity(w, t);
        out.push(`${t.name} (${t.kind}, ${w.name}) P ${p.toFixed(2)} meter ${r.meter.toFixed(2)} · rate $${r.rate.toFixed(1)}/h · grown ${r.grown} · blight ${r.blight} · built ${builtCount(t)} · earned $${Math.round(r.earned)} · tax ${r.tax}%`);
      }
    }
    return out;
  }

  find(name: string): { w: World; t: Town } | null {
    const want = name.toLowerCase();
    for (const w of this.host.resident()) for (const t of w.towns) if (t.name.toLowerCase().startsWith(want)) return { w, t };
    return null;
  }

  /** Force one growth step now; returns what changed. */
  step(name: string, hours = 0): string {
    const f = this.find(name);
    if (!f) return 'no such town';
    const before = f.t.buildings.length, roads = f.t.roads, size = f.t.size;
    const ok = this.grow(f.w, f.t, hours || this.lastHour);
    return ok ? `${f.t.name}: ${f.t.buildings.length - before} buildings, ${f.t.roads - roads} roads, size ${size}→${f.t.size}` : `${f.t.name}: no room`;
  }

  blightStep(name: string): string {
    const f = this.find(name);
    if (!f) return 'no such town';
    return this.wear(f.w, f.t) ? `${f.t.name}: ${this.ensure(f.w, f.t).blight} boarded up` : `${f.t.name}: nothing left to fall`;
  }

  creditTown(name: string, dollars: number): string {
    const f = this.find(name);
    if (!f) return 'no such town';
    this.credit(f.w, f.t, dollars);
    return `${f.t.name}: P ${this.prosperity(f.w, f.t).toFixed(2)}`;
  }

  /** What trade without the player has credited per town-hour, by kind, and the norm it suggests (×1.1). */
  norms(): Record<string, { cpuPerHour: number; suggested: number; townHours: number; current: number }> {
    const out: Record<string, { cpuPerHour: number; suggested: number; townHours: number; current: number }> = {};
    for (const [kind, k] of this.calib) {
      const per = k.hours ? k.dollars / k.hours : 0;
      out[kind] = { cpuPerHour: Math.round(per * 10) / 10, suggested: Math.round(per * 1.1), townHours: k.hours, current: ECONOMY.norm[kind] };
    }
    return out;
  }
}

/** A town's name without the " City" a big city wears, for the mayor it has always had. */
export const plainName = (t: Town): string => t.name.replace(/ City$/, '');

function setKind(t: Town, kind: TownKind): void {
  t.kind = kind;
  if (kind === 'metro' && !t.name.endsWith(' City')) t.name = `${t.name} City`;
}

/** The overview's line under a town: its mood and its levy. */
export function moodLine(mood: Mood, tax: number): string {
  const arrow = mood === 'Thriving' || mood === 'Growing' ? ' ↑' : mood === 'Struggling' ? ' ↓' : '';
  return `${mood}${arrow}${tax ? ` · tax ${tax}%` : ''}`;
}


/** A town has grown a size: front-page news, its hall on the plinth (docs/newspaper.html). */
function graduated(w: World, t: Town, size: string): void {
  const hall = t.buildings.find((b) => !b.gone && (b.kind === 'cityHall' || b.kind === 'villageHall' || b.kind === 'communityCentre'));
  press.write({ k: 'graduated', town: keyOf(w, t), at: townAt(w, t), f: { town: t.name, size }, ...(hall ? { pic: buildingPic(w, hall, t.style) } : {}) });
}
