import * as THREE from 'three';
import { N, STEP, World, heightAt, idx, type Arch, type Building, type BuildingKind, type Town } from '../world/tiles';
import { buildTownChunk } from './townMesh';

/**
 * Ghosts (docs/lobbying.html): the building a fleet has asked a town for, stood where it would go,
 * drawn by the town mesher in the town's own style and then washed over in the fleet's colours at
 * forty per cent, with a pennant in its accent on the roof. Red when its site has been taken. Ground a
 * fleet has asked a town to take in is shown the same way, as tinted tiles.
 */

export interface GhostModel {
  kind: BuildingKind; wx: number; wz: number; facing: number; floors: number; seed: number; style: Arch;
}

/** The scratch island the mesher draws a lone building on, as the hero stage does. */
let scratch: World | null = null;
const S0 = 4;

/**
 * A wild thing drawn alone for its curio (render/toppers.ts), to be shrunk onto a roof: out in the country, as the
 * mesher draws them, not inside a town's lines.
 */
export function loneBuilding(m: GhostModel): THREE.Group {
  if (!scratch) {
    scratch = new World();
    scratch.corners.fill(4);
  }
  const w = scratch;
  const b: Building = { kind: m.kind, x: S0, z: S0, w: m.wx, d: m.wz, facing: m.facing, floors: m.floors, seed: m.seed, solid: true, level: 4, uid: 0 };
  const was = w.countryside;
  w.countryside = [b];
  w.allBuildings = [b];
  const g = buildTownChunk(w, 0, 0) ?? new THREE.Group();
  w.countryside = was;
  w.allBuildings = [];
  return g;
}

/** A building in a style, on flat ground at level 4, its corner at (S0, S0): the mesher's own geometry. */
function drawLone(m: GhostModel): THREE.Group {
  if (!scratch) {
    scratch = new World();
    scratch.corners.fill(4);
  }
  const w = scratch;
  const b: Building = { kind: m.kind, x: S0, z: S0, w: m.wx, d: m.wz, facing: m.facing, floors: m.floors, seed: m.seed, solid: true, level: 4, uid: 0 };
  const t: Town = { id: 0, kind: 'city', name: 'Ghost', x0: 0, z0: 0, size: S0 + Math.max(m.wx, m.wz) + 2, level: 4, style: m.style, buildings: [b], roads: 0, entry: [] };
  w.towns = [t];
  w.allBuildings = [b];
  const g = buildTownChunk(w, 0, 0) ?? new THREE.Group();
  w.towns = [];
  w.allBuildings = [];
  return g;
}

const mats = new Map<string, THREE.Material>();
/** Lit, so a ghost keeps its roofs and walls; flat quads on the ground are left unlit. */
function ghostMat(colour: number, opacity: number, lit = false): THREE.Material {
  const k = `${colour}|${opacity}|${lit}`;
  let m = mats.get(k);
  if (!m) {
    m = lit
      ? new THREE.MeshStandardMaterial({ color: colour, transparent: true, opacity, depthWrite: false, flatShading: true, roughness: 0.8, emissive: colour, emissiveIntensity: 0.25 })
      : new THREE.MeshBasicMaterial({ color: colour, transparent: true, opacity, depthWrite: false, side: THREE.DoubleSide });
    mats.set(k, m);
  }
  return m;
}

export const GHOST_RED = 0xd2564f;
export const GHOST_OK = 0x4cc47e;

/** One ghost: its model, washed in a colour, with an optional pennant. Dispose with disposeGhost(). */
export function buildGhost(m: GhostModel, colour: number, accent: number | null): THREE.Group {
  const g = drawLone(m);
  const box = new THREE.Box3().setFromObject(g);
  g.traverse((o) => {
    const mesh = o as THREE.Mesh;
    if (!mesh.isMesh) return;
    mesh.material = ghostMat(colour, 0.55, true);
    mesh.renderOrder = 3;
    mesh.castShadow = mesh.receiveShadow = false;
  });
  // lift the footprint's corner to the origin, so the caller places it by its corner tile
  g.position.set(-S0, -4 * STEP, -S0);
  const out = new THREE.Group();
  out.add(g);
  if (accent !== null && Number.isFinite(box.max.y)) {
    const top = box.max.y - 4 * STEP;
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.9, 5), ghostMat(0x3a3f45, 0.85));
    pole.position.set(m.wx - 0.2, top + 0.45, 0.2);
    const flag = new THREE.Mesh(new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0, 0, 0), new THREE.Vector3(0.5, -0.14, 0), new THREE.Vector3(0, -0.3, 0),
    ]), ghostMat(accent, 0.95));
    flag.position.set(m.wx - 0.2, top + 0.88, 0.2);
    pole.renderOrder = flag.renderOrder = 4;
    out.add(pole, flag);
  }
  return out;
}

export function disposeGhost(g: THREE.Object3D): void {
  g.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) m.geometry.dispose(); });
}

/** The ground level a lot at (x, z) of (wx, wz) would be cut to, as applyBuild cuts it. */
export function lotLevel(w: World, x: number, z: number, wx: number, wz: number): number {
  let sum = 0, n = 0;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
    if (xx < 0 || zz < 0 || xx >= N || zz >= N) continue;
    for (let q = 0; q < 4; q++) sum += w.corners[idx(xx, zz) * 4 + q];
    n += 4;
  }
  return n ? Math.round(sum / n) : 0;
}

/** Flat tinted quads over these tiles, a hair above the ground: a claim's preview, or where a ghost may stand. */
export function buildTiles(w: World, tiles: Iterable<number>, colour: number, opacity: number): THREE.Mesh {
  const pos: number[] = [];
  for (const i of tiles) {
    const x = i % N, z = (i - x) / N;
    const y = (u: number, v: number) => heightAt(w, Math.min(N - 0.001, x + u), Math.min(N - 0.001, z + v)) + 0.06;
    const a = [x + 0.06, y(0.06, 0.06), z + 0.06], b = [x + 0.94, y(0.94, 0.06), z + 0.06];
    const c = [x + 0.94, y(0.94, 0.94), z + 0.94], d = [x + 0.06, y(0.06, 0.94), z + 0.94];
    pos.push(...a, ...c, ...b, ...a, ...d, ...c);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  const mesh = new THREE.Mesh(geo, ghostMat(colour, opacity));
  mesh.renderOrder = 2;
  return mesh;
}
