import * as THREE from 'three';
import { hero } from './heroStage';

/**
 * The pictures on the road builder's dock: a single tile of each road surface seen from low down, drawn
 * once in a little scene of its own through the mission card's renderer and handed back as a PNG.
 */

/** Pixels each picture is drawn at: twice the button, for sharp edges on a high-density screen. */
const SIZE = 92;

function lit(scene: THREE.Scene): void {
  scene.add(new THREE.HemisphereLight(0xfff4dc, 0x7a6a50, 1.4));
  const sun = new THREE.DirectionalLight(0xfff1d6, 2.4);
  sun.position.set(-3, 5, 4);
  scene.add(sun);
}

/** What each road surface looks like on its square in the road builder's dock. */
export type RoadLook = 'dirt' | 'gravel' | 'brick' | 'cobble' | 'paved' | 'two' | 'four' | 'interstate' | 'ramp';

/** One tile of built track in a period's colours (render/railMesh.ts BALLAST and SLEEPER), for the Rails side's squares. */
export function railTileIcon(era: 'steam' | 'streamline' | 'modern'): string {
  const scene = new THREE.Scene();
  lit(scene);
  const mat = (color: number, metal = 0) => new THREE.MeshStandardMaterial({ color, roughness: metal ? 0.4 : 0.9, metalness: metal, flatShading: true });
  const box = (w: number, h: number, d: number, color: number, x: number, y: number, z: number, metal = 0) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(color, metal));
    m.position.set(x, y, z);
    scene.add(m);
    return m;
  };
  const ballast = { steam: 0x857a6e, streamline: 0x8f8980, modern: 0x9c9890 }[era];
  const sleeper = { steam: 0x5b4332, streamline: 0x66513e, modern: 0xb9b5ac }[era];
  box(1.5, 0.1, 1.2, 0x6fb04a, 0, -0.05, 0);                 // the verges
  box(0.62, 0.05, 1.2, ballast, 0, 0.025, 0);                // the ballast bed
  box(0.78, 0.03, 1.2, ballast, 0, 0.015, 0);
  for (let z = -0.52; z < 0.6; z += 0.17) box(0.5, 0.03, 0.07, sleeper, 0, 0.06, z);   // sleepers
  for (const sx of [-1, 1]) box(0.035, 0.05, 1.2, 0xc9ccd0, sx * 0.14, 0.1, 0, 0.3);  // the rails
  const cam = new THREE.PerspectiveCamera(34, 1, 0.01, 20);
  cam.position.set(0.55, 0.42, 1.25);
  cam.lookAt(0, 0, -0.1);
  const url = hero.render(scene, cam, SIZE, SIZE);
  scene.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { m.geometry.dispose(); (m.material as THREE.Material).dispose(); } });
  return url;
}


/** One tile of this road, seen from low down: the builder's dock draws a square of each. */
export function roadTileIcon(look: RoadLook): string {

  const scene = new THREE.Scene();
  lit(scene);
  const mat = (color: number) => new THREE.MeshStandardMaterial({ color, roughness: 0.9, flatShading: true });
  const box = (w: number, h: number, d: number, color: number, x: number, y: number, z: number) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(color));
    m.position.set(x, y, z);
    scene.add(m);
    return m;
  };
  box(1.5, 0.1, 1.2, 0x6fb04a, 0, -0.05, 0);                 // the verges
  if (look === 'interstate') {
    // two carriageways of two lanes, the grass median between, white edges and dashes, yellow by the median
    for (const sx of [-1, 1]) {
      box(0.6, 0.04, 1.2, 0x44484e, sx * 0.45, 0.02, 0);
      box(0.025, 0.005, 1.2, 0xf4f2ec, sx * 0.72, 0.043, 0);
      box(0.025, 0.005, 1.2, 0xf2c12e, sx * 0.19, 0.043, 0);
      for (const z of [-0.45, -0.1, 0.25]) box(0.025, 0.005, 0.18, 0xf4f2ec, sx * 0.45, 0.043, z);
    }
    box(0.3, 0.06, 1.2, 0xcfc9bc, 0, 0.03, 0);
    box(0.24, 0.062, 1.2, 0x77b457, 0, 0.032, 0);
  } else if (look === 'ramp') {
    // one lane, slanting off across the square the way a slip road leaves
    const lane = box(0.42, 0.04, 1.5, 0x5b5f64, 0, 0.02, 0);
    lane.rotation.y = 0.32;
    for (const sx of [-1, 1]) { const e = box(0.025, 0.005, 1.5, 0xf4f2ec, 0, 0.043, 0); e.rotation.y = 0.32; e.position.x = sx * 0.17 * Math.cos(0.32); e.position.z = -sx * 0.17 * Math.sin(0.32); }
  }
  const wide = look === 'four' ? 1.2 : look === 'dirt' || look === 'gravel' ? 0.62 : 0.8, half = wide / 2;
  const SURF: Record<RoadLook, number> = { dirt: 0xb08658, gravel: 0x9c8f78, brick: 0xa8604a, cobble: 0x8d8375, paved: 0x5b5f64, two: 0x4a4e54, four: 0x44484e, interstate: 0x44484e, ramp: 0x5b5f64 };
  if (look !== 'interstate' && look !== 'ramp') box(wide, 0.04, 1.2, SURF[look], 0, 0.02, 0);                // the surface
  if (look === 'brick' || look === 'cobble') {
    // courses of setts across it
    for (let z = -0.55; z < 0.6; z += look === 'brick' ? 0.1 : 0.08) box(wide, 0.004, 0.012, look === 'brick' ? 0x8a4a38 : 0x6e665a, 0, 0.041, z);
  }
  if (look === 'gravel') for (let i = 0; i < 18; i++) box(0.04, 0.01, 0.04, i % 2 ? 0xb3a88f : 0x857a66, ((i * 37) % 11 / 11 - 0.5) * wide * 0.85, 0.042, ((i * 53) % 13 / 13 - 0.5) * 1.1);
  if (look !== 'dirt' && look !== 'gravel' && look !== 'interstate' && look !== 'ramp') for (const sx of [-1, 1]) box(0.05, 0.06, 1.2, 0xd8d4cc, sx * (half + 0.025), 0.03, 0); // the kerbs
  if (look === 'two' || look === 'four') {
    for (const sx of [-1, 1]) box(0.03, 0.005, 1.2, 0xf4f2ec, sx * (half - 0.05), 0.043, 0); // the edge lines
    if (look === 'four') for (const sx of [-1, 1]) box(0.025, 0.005, 1.2, 0xf2c12e, sx * 0.03, 0.043, 0); // the double centre line
    else for (const z of [-0.45, -0.1, 0.25]) box(0.035, 0.005, 0.2, 0xf2c12e, 0, 0.043, z); // the centre dashes
    if (look === 'four') for (const sx of [-1, 1]) for (const z of [-0.45, -0.1, 0.25]) box(0.025, 0.005, 0.18, 0xf4f2ec, sx * half * 0.5, 0.043, z);
  }
  const cam = new THREE.PerspectiveCamera(34, 1, 0.01, 20);
  cam.position.set(0.55, 0.42, 1.25);
  cam.lookAt(0, 0, -0.1);
  const url = hero.render(scene, cam, SIZE, SIZE);
  scene.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { m.geometry.dispose(); (m.material as THREE.Material).dispose(); } });
  return url;
}
