import type { World } from '../world/tiles';
import type { Kit } from './buildings/kit';
import { PART_SLOTS, setParts, type PartBox } from './xray';

/**
 * Cutting a big building into the pieces that fade on their own when the car drives behind them.
 *
 * Nothing in the models says which primitive belongs to which piece, so the pieces are found from
 * the geometry: triangles whose bounds touch are one piece, found with a union-find over a coarse
 * grid. Paving, kerbs and anything else lying flat on the ground joins nothing (it would tie every
 * obelisk to the avenue it stands on) and never fades, since it can't hide the car anyway.
 */

/** Buildings with a side at least this many tiles long are cut up; smaller ones fade whole. */
export const SPLIT_MIN = 3;
/** Anything lower than this above the building's foot is paving. */
const GROUND = 0.08;
/** Triangles closer than this touch. */
const TOUCH = 0.02;
/** Grid cell for finding neighbours, in tiles. */
const CELL = 1;

/** Triangles of one cell already known to be one piece, and the box round them. */
interface Group { tris: number[]; lo: number[]; hi: number[] }

/**
 * Re-tag the triangles drawn for building `uid` since solid triangle `t0` and glow triangle `g0`
 * with one id per piece, and record each piece's box for the x-ray.
 */
export function splitParts(k: Kit, w: World, uid: number, foot: number, t0: number, g0: number): void {
  const nt = k.pos.length / 9 - t0, n = nt + k.glow.pos.length / 9 - g0;
  if (n <= 0) { setParts(w, uid, null); return; }
  const lo = new Float32Array(n * 3), hi = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    const src = i < nt ? k.pos : k.glow.pos, o = (i < nt ? t0 + i : g0 + i - nt) * 9;
    for (let a = 0; a < 3; a++) {
      lo[i * 3 + a] = Math.min(src[o + a], src[o + 3 + a], src[o + 6 + a]);
      hi[i * 3 + a] = Math.max(src[o + a], src[o + 3 + a], src[o + 6 + a]);
    }
  }
  const ground = (i: number) => hi[i * 3 + 1] - foot < GROUND;

  const up = new Int32Array(n);
  for (let i = 0; i < n; i++) up[i] = i;
  const find = (i: number): number => {
    while (up[i] !== i) { up[i] = up[up[i]]; i = up[i]; }
    return i;
  };
  const touch = (i: number, j: number) => {
    for (let a = 0; a < 3; a++) if (lo[i * 3 + a] > hi[j * 3 + a] + TOUCH || lo[j * 3 + a] > hi[i * 3 + a] + TOUCH) return false;
    return true;
  };
  // Each grid cell keeps its triangles in groups, each group one piece as far as the cell knew when
  // the group began, with the box round all of it. A triangle skips any group already joined to it
  // (and any whose box it misses) without testing a member, so a wall of a thousand triangles in one
  // cell costs a few tests each rather than a thousand: testing every earlier triangle made a big
  // block's split quadratic, hundreds of milliseconds a chunk.
  const grid = new Map<number, Group[]>();
  const hitsBox = (i: number, g: Group) => {
    for (let a = 0; a < 3; a++) if (lo[i * 3 + a] > g.hi[a] + TOUCH || g.lo[a] > hi[i * 3 + a] + TOUCH) return false;
    return true;
  };
  for (let i = 0; i < n; i++) {
    if (ground(i)) continue;
    const x0 = Math.floor((lo[i * 3] - TOUCH) / CELL), x1 = Math.floor((hi[i * 3] + TOUCH) / CELL);
    const z0 = Math.floor((lo[i * 3 + 2] - TOUCH) / CELL), z1 = Math.floor((hi[i * 3 + 2] + TOUCH) / CELL);
    for (let gx = x0; gx <= x1; gx++) for (let gz = z0; gz <= z1; gz++) {
      const key = gx * 100003 + gz; // a clash only costs a few extra tests
      let groups = grid.get(key);
      if (!groups) grid.set(key, (groups = []));
      let home: Group | null = null;
      for (const g of groups) {
        const rg = find(g.tris[0]);
        if (rg !== find(i)) {
          if (!hitsBox(i, g)) continue;
          let hit = false;
          for (const j of g.tris) if (touch(i, j)) { hit = true; break; }
          if (!hit) continue;
          up[find(i)] = rg;
        }
        home ??= g;
      }
      if (!home) groups.push((home = { tris: [], lo: [Infinity, Infinity, Infinity], hi: [-Infinity, -Infinity, -Infinity] }));
      home.tris.push(i);
      for (let a = 0; a < 3; a++) { home.lo[a] = Math.min(home.lo[a], lo[i * 3 + a]); home.hi[a] = Math.max(home.hi[a], hi[i * 3 + a]); }
    }
  }

  // the biggest pieces get their own id; past the last slot the smallest share one
  const count = new Map<number, number>();
  for (let i = 0; i < n; i++) if (!ground(i)) { const r = find(i); count.set(r, (count.get(r) ?? 0) + 1); }
  const roots = [...count.keys()].sort((a, b) => count.get(b)! - count.get(a)!);
  const slot = new Map<number, number>();
  roots.forEach((r, s) => slot.set(r, Math.min(s + 1, PART_SLOTS - 1)));

  const boxes = new Map<number, PartBox>();
  for (let i = 0; i < n; i++) {
    const part = ground(i) ? 0 : slot.get(find(i))!;
    const id = uid * PART_SLOTS + part;
    const ids = i < nt ? k.ids : k.glow.ids, v = (i < nt ? t0 + i : g0 + i - nt) * 3;
    ids[v] = ids[v + 1] = ids[v + 2] = id;
    if (!part) continue;
    // the shared last slot keeps a box per piece, so its far-flung bits aren't one big box
    const key = part === PART_SLOTS - 1 ? -1 - find(i) : part;
    const b = boxes.get(key);
    if (!b) boxes.set(key, { id, x0: lo[i * 3], y0: lo[i * 3 + 1], z0: lo[i * 3 + 2], x1: hi[i * 3], y1: hi[i * 3 + 1], z1: hi[i * 3 + 2] });
    else {
      b.x0 = Math.min(b.x0, lo[i * 3]); b.y0 = Math.min(b.y0, lo[i * 3 + 1]); b.z0 = Math.min(b.z0, lo[i * 3 + 2]);
      b.x1 = Math.max(b.x1, hi[i * 3]); b.y1 = Math.max(b.y1, hi[i * 3 + 1]); b.z1 = Math.max(b.z1, hi[i * 3 + 2]);
    }
  }
  setParts(w, uid, [...boxes.values()]);
}
