import { DIRS, N, idx, inB, minCorner, type Building, type Town, type World } from '../../world/tiles';
import { NEXT_WORLD } from '../../world/nextWorld';
import { crossingAt } from '../../world/macro';
import { buildingHeight } from '../../world/towns';
import { seedHash, type Happening } from './calendar';
import { hashString } from '../../world/rng';
import { runwaysOf, type Runway } from '../../world/runways';
import { stadiumDesignOf } from '../../world/stadiums';

/**
 * Where an event happens in its county (docs/events.html): the town, the street, the square, the tower, found
 * in the generated world from the event's own hash, so every player finds the same. Pure and headless, so the
 * gate (`npm run events`) asks it too. Null when the county has nowhere fit: the event stays quiet.
 */

export type Pt = { x: number; z: number };

export interface Place {
  /** For the log and the gate: "Fort Langley, down Market Street". */
  label: string;
  town: Town | null;
  /** A procession's way through the streets, tile middles in the county's frame. */
  path?: Pt[];
  /** A gathering's ground: an open lot, and the bays on it, in the county's frame, each facing `yaw`. */
  lot?: Building;
  bays?: (Pt & { yaw: number })[];
  /** Road tiles closed while it is on, in the county's frame (tile indices). */
  closes?: number[];
  /** The tallest building near, lit up, with a ball dropping or paper falling from it. */
  tower?: Building;
  /** Other tall buildings along the way, for paper from their windows. */
  towers?: Building[];
  /** A moving event's way in and out of this county: border points in the county's frame (or a town's door at the ends). */
  from?: Pt; to?: Pt;
  /** Open water it is held on: a rectangle of tiles, deep enough for small boats all over. */
  water?: { x0: number; z0: number; x1: number; z1: number };
  /** A course's marks in order (the first is the start), and the committee boat at the line. */
  course?: Pt[]; committee?: Pt;
  /** Where people watch from the shore, the quay or the fence. */
  shore?: Pt[];
  /** Berths at a harbour, and the open water a fleet comes in from. */
  berths?: Pt[]; offing?: Pt;
  /** An airfield's strip (world tiles). */
  runway?: Runway;
  /** A market's street, crossroads or square, and its barriers (0.7.0). */
  market?: MarketSite;
  /** Doorsteps (pumpkins), each with the way the door faces. */
  doors?: (Pt & { yaw: number })[];
}

const TOWN_RANK = { rural: 0, suburb: 1, city: 2, metro: 3, mega: 4 } as const;
const u01 = (h: number): number => (h >>> 0) / 4294967296;
const rehash = (h: number, k: number): number => {
  let x = Math.imul(h ^ (k * 0x9e3779b1), 0x85ebca6b);
  x ^= x >>> 13;
  x = Math.imul(x, 0xc2b2ae35);
  return (x ^ (x >>> 16)) >>> 0;
};

/** The building's middle. */
export const mid = (b: Building): Pt => ({ x: b.x + b.w / 2, z: b.z + b.d / 2 });
/** A building still standing. */
const up = (b: Building) => !b.gone;

/** The town an event of this size wants: the biggest of at least `min`, or null. */
function bigTown(w: World, min: keyof typeof TOWN_RANK): Town | null {
  let best: Town | null = null;
  for (const t of w.towns) {
    if (TOWN_RANK[t.kind] < TOWN_RANK[min]) continue;
    if (!best || TOWN_RANK[t.kind] > TOWN_RANK[best.kind] || (t.kind === best.kind && t.buildings.length > best.buildings.length)) best = t;
  }
  return best;
}

/** Tall things that are not buildings a city lights up or drops a ball from: masts, silos, water towers, turbines. */
const NOT_TOWERS = new Set<string>(['radioTower', 'radioMast', 'commsTower', 'airshipMast', 'beaconTower', 'controlTower', 'coolingTowers', 'grainElevator', 'silo',
  'waterTower', 'windTower', 'windTurbine', 'watchtower', 'lookoutTower', 'mineHeadframe', 'launchPad', 'lighthouse', 'oilRig']);

/** The tallest building standing in a town (a wonder's pieces, open lots and masts aside). */
export function tallest(t: Town): Building | null {
  let best: Building | null = null, bh = 0;
  for (const b of t.buildings) {
    if (!up(b) || !b.solid || NOT_TOWERS.has(b.kind)) continue;
    const h = buildingHeight(b);
    if (h > bh) { bh = h; best = b; }
  }
  return best;
}

/** The road tile at a building's front door, or -1. */
function kerbTile(w: World, b: Building): number {
  const [dx, dz] = DIRS[b.facing];
  const c = mid(b);
  for (let k = 0.5; k < 3; k += 1) {
    const x = Math.floor(c.x + dx * (b.w / 2 + k)), z = Math.floor(c.z + dz * (b.d / 2 + k));
    if (inB(x, z) && w.road[idx(x, z)] && !w.deckAxis[idx(x, z)]) return idx(x, z);
  }
  return -1;
}

/**
 * A way along a town's streets from `start`: of the road tiles between `min` and `max` steps away, the one
 * reached with fewest turns (a parade wants an avenue, not a maze), the event's hash breaking ties.
 */
function avenue(w: World, t: Town, start: number, min: number, max: number, h: number): Pt[] | null {
  const prev = new Map<number, number>([[start, -1]]);
  const dist = new Map<number, number>([[start, 0]]);
  const queue = [start];
  const far: number[] = [];
  const pad = 4;
  for (let q = 0; q < queue.length; q++) {
    const i = queue[q], d = dist.get(i)!;
    if (d >= min) far.push(i);
    if (d >= max) continue;
    const x = i % N, z = (i - x) / N;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (nx < t.x0 - pad || nz < t.z0 - pad || nx >= t.x0 + t.size + pad || nz >= t.z0 + t.size + pad || !inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (prev.has(j) || !w.road[j] || w.deckAxis[j] || w.water[j] >= 0) continue;
      prev.set(j, i);
      dist.set(j, d + 1);
      queue.push(j);
    }
  }
  if (!far.length) return null;
  const turns = (end: number): number => {
    let n = 0, last = -2;
    for (let i = end, p = prev.get(i)!; p >= 0; i = p, p = prev.get(i)!) {
      const dir = i - p;
      if (last !== -2 && dir !== last) n++;
      last = dir;
    }
    return n;
  };
  // a town laid out to a city plan (GEN 53) walks its signature street: the Mall, the axis, the Champs
  const axis = t.axis?.length ? new Set(t.axis) : null;
  const onAxis = (end: number): number => {
    if (!axis) return 0;
    let n = 0;
    for (let i = end; i >= 0; i = prev.get(i)!) if (axis.has(i)) n++;
    return n;
  };
  let best = -1, bestScore = Infinity;
  for (const f of far) {
    const s = turns(f) * 10 - dist.get(f)! * 0.5 + u01(rehash(h, f)) * 3 - onAxis(f) * 2;
    if (s < bestScore) { bestScore = s; best = f; }
  }
  const tiles: number[] = [];
  for (let i = best; i >= 0; i = prev.get(i)!) tiles.push(i);
  tiles.reverse();
  return tiles.map((i) => ({ x: (i % N) + 0.5, z: Math.floor(i / N) + 0.5 }));
}

/** Tall buildings within `r` tiles of a way, tallest first. */
function towersAlong(t: Town, path: Pt[], r: number, minH: number): Building[] {
  const out: [Building, number][] = [];
  for (const b of t.buildings) {
    if (!up(b) || !b.solid) continue;
    const h = buildingHeight(b);
    if (h < minH) continue;
    const c = mid(b);
    if (path.some((p) => Math.abs(p.x - c.x) <= r + b.w / 2 && Math.abs(p.z - c.z) <= r + b.d / 2)) out.push([b, h]);
  }
  return out.sort((a, b) => b[1] - a[1]).map(([b]) => b);
}

const PARADE_FROM = new Set<Building['kind']>(['stadium', 'cityHall', 'statehouse', 'parliament', 'capitolBuilding', 'courthouse', 'villageHall']);
/** Where a show can be laid out, in order of preference: paved ground, then an open lawn (a park has its trees and ponds). */
const SHOW_LOTS: Building['kind'][] = ['parking', 'civicSquare', 'plaza', 'marketSquare', 'meadow', 'pitch'];
/** Where a city's crowd gathers for a midnight: any open ground near the tower. */
const CROWD_LOTS: Building['kind'][] = [...SHOW_LOTS, 'park', 'fountainSquare', 'plazaSteps'];

/** Where this event happens in its county, or null for nowhere fit. */
export function placeOf(w: World, e: Happening): Place | null {
  switch (e.kind) {
    case 'parade': return paradePlace(w, e);
    case 'carShow': return showPlace(w, e);
    case 'newYear': return newYearPlace(w, e);
    case 'motorcade': return motorcadePlace(w, e);
    case 'regatta': return regattaPlace(w, e);
    case 'boatParade': return waterfrontPlace(w, e);
    case 'tallShips': return harbourPlace(w, e);
    case 'militaryParade': return avenuePlace(w, e, bigTown(w, 'city'), 24, 40, 'the avenue');
    case 'pride': return avenuePlace(w, e, bigTown(w, 'city'), 18, 34, 'the main street');
    case 'airShow': return airfieldPlace(w, e);
    case 'lightShow': return landmarkPlace(w, e);
    case 'winterLights': case 'spookyNight': return townNightPlace(w, e);
    case 'offroadRace': return rallyPlace(w, e);
    case 'powerboatRace': return powerboatPlace(w, e);
    case 'driftMeet': return driftPlace(w, e);
    case 'dragonBoats': return dragonPlace(w, e);
    case 'gondolaRegatta': return gondolaPlace(w, e);
    case 'truckConvoy': return motorcadePlace(w, e);
    case 'farmersMarket': case 'christmasMarket': return marketPlace(w, e);
    default: return phase4Place(w, e);
  }
}

/** The champions' town (the one with the stadium, else the biggest), and an avenue from its stadium or hall. */
function paradePlace(w: World, e: Happening): Place | null {
  const towns = w.towns.filter((t) => TOWN_RANK[t.kind] >= 1);
  if (!towns.length) return null;
  const home = towns.find((t) => t.buildings.some((b) => b.kind === 'stadium' && up(b))) ?? bigTown(w, 'suburb');
  if (!home) return null;
  const starts = home.buildings.filter((b) => up(b) && PARADE_FROM.has(b.kind)).sort((a, b) => (a.kind === 'stadium' ? 0 : 1) - (b.kind === 'stadium' ? 0 : 1));
  for (const b of starts.length ? starts : home.buildings.filter(up)) {
    const k = kerbTile(w, b);
    if (k < 0) continue;
    const path = avenue(w, home, k, 18, 34, e.h);
    if (!path || path.length < 14) continue;
    const towers = towersAlong(home, path, 3, 1.4);
    return { label: `${home.name}, from the ${b.kind === 'stadium' ? 'stadium' : 'town hall'}`, town: home, path, tower: tallest(home) ?? undefined, towers };
  }
  return null;
}

/** Bays in rows across a lot, a tile and a half deep and a tile apart, kept off its edges. */
function bays(lot: Building, h: number): (Pt & { yaw: number })[] {
  const long = lot.w >= lot.d;
  const W = long ? lot.w : lot.d, D = long ? lot.d : lot.w;
  const cols = Math.max(1, Math.floor((W - 0.6) / 0.95)), rows = Math.max(1, Math.floor((D - 0.4) / 1.5));
  const out: (Pt & { yaw: number })[] = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const u = (c + 0.5) * ((W - 0.3) / cols) + 0.15, v = (r + 0.5) * (D / rows);
      // the rows face each other in pairs, as a show's do
      const face = r % 2 ? Math.PI : 0;
      out.push(long ? { x: lot.x + u, z: lot.z + v, yaw: face } : { x: lot.x + v, z: lot.z + u, yaw: face + Math.PI / 2 });
    }
  }
  // a show in the round about a fountain leaves the middle free
  if (lot.kind === 'fountainSquare') return out.filter((p) => Math.hypot(p.x - (lot.x + lot.w / 2), p.z - (lot.z + lot.d / 2)) > 1);
  void h;
  return out;
}

/** Bays on the road round a lot's edge: two a tile, one each side of the middle, nose to tail along the street. */
function streetBays(w: World, lot: Building): { bays: (Pt & { yaw: number })[]; tiles: number[] } {
  const out: (Pt & { yaw: number })[] = [], tiles: number[] = [];
  const edge = (x: number, z: number, alongX: boolean) => {
    if (!inB(x, z)) return;
    const i = idx(x, z);
    if (!w.road[i] || w.deckAxis[i] || w.water[i] >= 0 || tiles.includes(i)) return;
    tiles.push(i);
    const yaw = alongX ? Math.PI / 2 : 0;
    for (const s of [-0.24, 0.24]) out.push(alongX ? { x: x + 0.5, z: z + 0.5 + s, yaw } : { x: x + 0.5 + s, z: z + 0.5, yaw });
  };
  for (let x = lot.x; x < lot.x + lot.w; x++) { edge(x, lot.z - 1, true); edge(x, lot.z + lot.d, true); }
  for (let z = lot.z; z < lot.z + lot.d; z++) { edge(lot.x - 1, z, false); edge(lot.x + lot.w, z, false); }
  return { bays: out, tiles };
}

/** The biggest open lot in a town of some size, paved before grass. */
function showPlace(w: World, e: Happening): Place | null {
  const towns = w.towns.filter((t) => TOWN_RANK[t.kind] >= 1).sort((a, b) => u01(rehash(e.h, a.id)) - u01(rehash(e.h, b.id)));
  for (const t of towns) {
    let best: Building | null = null, bestScore = 0;
    for (const b of t.buildings) {
      const pref = SHOW_LOTS.indexOf(b.kind);
      if (pref < 0 || !up(b) || b.w * b.d < 6) continue;
      // paved first whatever its size, then the biggest
      const score = (SHOW_LOTS.length - pref) * 1000 + b.w * b.d;
      if (score > bestScore) { bestScore = score; best = b; }
    }
    if (!best) continue;
    // and the street along its edge, closed for the day, a line of cars down each side of it
    const kerb = streetBays(w, best);
    const spots = [...bays(best, e.h), ...kerb.bays];
    if (spots.length < 10) continue;
    return { label: `${t.name}, on the ${best.kind.replace(/([A-Z])/g, ' $1').toLowerCase()}`, town: t, lot: best, bays: spots, closes: kerb.tiles };
  }
  return null;
}

/** The county's biggest city, its tallest tower and the open ground nearest it for the crowd. */
function newYearPlace(w: World, e: Happening): Place | null {
  void e;
  const t = bigTown(w, 'city');
  if (!t) return null;
  const tower = tallest(t);
  if (!tower) return null;
  const c = mid(tower);
  let lot: Building | null = null, bd = Infinity;
  for (const b of t.buildings) {
    if (!up(b) || !CROWD_LOTS.includes(b.kind)) continue;
    const d = Math.hypot(mid(b).x - c.x, mid(b).z - c.z);
    if (d < bd) { bd = d; lot = b; }
  }
  return { label: `${t.name}, under the ${tower.kind.replace(/([A-Z])/g, ' $1').toLowerCase()}`, town: t, tower, lot: lot && bd < 24 ? lot : undefined };
}

/** A border point of the county on side d (its crossing's road), in the county's frame. */
function borderPoint(w: World, d: number): Pt | null {
  const st = w.straits.find((s) => s.dir === d);
  const at = st ? st.at : crossingAt(seedHash(w.seed), w.cx, w.cz, d)[0]?.at;
  if (at === undefined) return null;
  const x = d === 0 ? N - 0.5 : d === 2 ? 0.5 : at + 0.5;
  const z = d === 1 ? N - 0.5 : d === 3 ? 0.5 : at + 0.5;
  return { x, z };
}

/** The town hall's door of the county's megalopolis (or its biggest town). */
function hallDoor(w: World): { pt: Pt; town: Town } | null {
  const t = bigTown(w, 'suburb');
  if (!t) return null;
  const hall = t.buildings.find((b) => up(b) && (b.kind === 'cityHall' || b.kind === 'capitolBuilding' || b.kind === 'statehouse' || b.kind === 'parliament'))
    ?? t.buildings.find((b) => up(b) && b.solid);
  if (!hall) return null;
  const k = kerbTile(w, hall);
  const pt = k >= 0 ? { x: (k % N) + 0.5, z: Math.floor(k / N) + 0.5 } : mid(hall);
  return { pt, town: t };
}

/** A motorcade's way through this county: in at the border from the last county, out at the next one's (a hall's door at either end). */
function motorcadePlace(w: World, e: Happening): Place | null {
  const r = e.route;
  if (!r) return null;
  const k = r.findIndex(([x, z]) => x === w.cx && z === w.cz);
  if (k < 0) return null;
  const side = (a: [number, number], b: [number, number]) => DIRS.findIndex(([dx, dz]) => a[0] + dx === b[0] && a[1] + dz === b[1]);
  let from: Pt | null, to: Pt | null, town: Town | null = null;
  if (k === 0) { const h = hallDoor(w); from = h?.pt ?? null; town = h?.town ?? null; } else from = borderPoint(w, side(r[k], r[k - 1]));
  if (k === r.length - 1) { const h = hallDoor(w); to = h?.pt ?? null; town = h?.town ?? town; } else to = borderPoint(w, side(r[k], r[k + 1]));
  if (!from || !to) return null;
  return { label: k === 0 ? `setting out from ${town?.name ?? w.name}` : k === r.length - 1 ? `arriving in ${town?.name ?? w.name}` : `through ${w.name}`, town, from, to };
}

// ---- phase 2 ------------------------------------------------------------------------------------------------------

/** A town's procession: an avenue of `min`–`max` tiles from its hall (or any front door), with the towers along it. */
function avenuePlace(w: World, e: Happening, t: Town | null, min: number, max: number, what: string): Place | null {
  if (!t) return null;
  const starts = t.buildings.filter((b) => up(b) && PARADE_FROM.has(b.kind) && b.kind !== 'stadium');
  for (const b of [...starts, ...t.buildings.filter((q) => up(q) && q.solid)].slice(0, 40)) {
    const k = kerbTile(w, b);
    if (k < 0) continue;
    const path = avenue(w, t, k, min, max, e.h);
    if (!path || path.length < min - 2) continue;
    return { label: `${t.name}, down ${what}`, town: t, path, tower: tallest(t) ?? undefined, towers: towersAlong(t, path, 3, 1.4) };
  }
  return null;
}

/** Deep-enough open water, counted up from the corner, so any rectangle of it is asked in four reads (per world, per depth). */
const SATS = new WeakMap<World, Map<number, { rev: number; s: Int32Array }>>();
function waterSat(w: World, depth: number): Int32Array {
  let m = SATS.get(w);
  if (!m) SATS.set(w, (m = new Map()));
  const hit = m.get(depth);
  if (hit && hit.rev === w.revision) return hit.s;
  const S = new Int32Array((N + 1) * (N + 1));
  for (let z = 0; z < N; z++) {
    let row = 0;
    for (let x = 0; x < N; x++) {
      const i = idx(x, z);
      const wl = w.water[i];
      if (wl >= 0 && wl - minCorner(w, i) >= depth && !w.blocked[i] && !w.deckAxis[i]) row++;
      S[(z + 1) * (N + 1) + x + 1] = S[z * (N + 1) + x + 1] + row;
    }
  }
  m.set(depth, { rev: w.revision, s: S });
  return S;
}
const satCount = (S: Int32Array, x0: number, z0: number, x1: number, z1: number) => S[z1 * (N + 1) + x1] - S[z0 * (N + 1) + x1] - S[z1 * (N + 1) + x0] + S[z0 * (N + 1) + x0];

type Rect = { x0: number; z0: number; x1: number; z1: number };

/** Rectangles of open water W × D (either way round) all deep enough, nearest `to` first (a few of them). */
function openWater(w: World, W: number, D: number, to: Pt, depth = 1, reach = 70): Rect[] {
  const S = waterSat(w, depth);
  const out: { r: Rect; d: number }[] = [];
  for (const [a, b] of [[W, D], [D, W]]) {
    for (let z0 = 1; z0 + b < N - 1; z0 += 2) for (let x0 = 1; x0 + a < N - 1; x0 += 2) {
      const d = Math.hypot(x0 + a / 2 - to.x, z0 + b / 2 - to.z);
      if (d > reach) continue;
      if (satCount(S, x0, z0, x0 + a, z0 + b) !== a * b) continue;
      out.push({ r: { x0, z0, x1: x0 + a, z1: z0 + b }, d });
    }
  }
  return out.sort((p, q) => p.d - q.d).slice(0, 8).map((p) => p.r);
}

/** Dry ground beside the water round a rectangle: where people stand and watch (at most `n`, spread round). */
function shoreOf(w: World, r: Rect, pad: number, n: number, h: number): Pt[] {
  const spots: Pt[] = [];
  for (let z = Math.max(0, r.z0 - pad); z < Math.min(N, r.z1 + pad); z++) {
    for (let x = Math.max(0, r.x0 - pad); x < Math.min(N, r.x1 + pad); x++) {
      const i = idx(x, z);
      if (w.water[i] >= 0 || w.blocked[i] || w.road[i]) continue;
      // beside the water: a neighbour of it wet
      if (!DIRS.some(([dx, dz]) => inB(x + dx, z + dz) && w.water[idx(x + dx, z + dz)] >= 0)) continue;
      spots.push({ x: x + 0.3 + u01(rehash(h, i)) * 0.4, z: z + 0.3 + u01(rehash(h, i + 7)) * 0.4 });
    }
  }
  const step = Math.max(1, spots.length / n);
  const out: Pt[] = [];
  for (let k = 0; k < spots.length && out.length < n; k += step) out.push(spots[Math.floor(k)]);
  return out;
}

/** Towns of some size, biggest first: a regatta's or a boat parade's crowd comes from one. */
function townsBySize(w: World, min: keyof typeof TOWN_RANK): Town[] {
  return w.towns.filter((t) => TOWN_RANK[t.kind] >= TOWN_RANK[min]).sort((a, b) => TOWN_RANK[b.kind] - TOWN_RANK[a.kind] || b.buildings.length - a.buildings.length);
}

/** A bay off a town with room for a triangle course: start line, windward mark, wing mark; spectators on the shore. */
function regattaPlace(w: World, e: Happening): Place | null {
  for (const t of townsBySize(w, 'suburb')) {
    const c = { x: t.x0 + t.size / 2, z: t.z0 + t.size / 2 };
    const rects = openWater(w, 22, 12, c, 1, t.size / 2 + 40);
    if (!rects.length) continue;
    const r = rects[Math.floor(u01(rehash(e.h, 3)) * Math.min(2, rects.length))];
    const long = r.x1 - r.x0 >= r.z1 - r.z0;
    // the course along the long side: the line at one end, the windward mark at the other, the wing mark off to one side
    const at = (u: number, v: number): Pt => (long ? { x: r.x0 + u * (r.x1 - r.x0), z: r.z0 + v * (r.z1 - r.z0) } : { x: r.x0 + v * (r.x1 - r.x0), z: r.z0 + u * (r.z1 - r.z0) });
    const flip = rehash(e.h, 9) & 1;
    const U = (u: number) => (flip ? 1 - u : u);
    const course = [at(U(0.14), 0.5), at(U(0.88), 0.5), at(U(0.5), 0.15)];
    return { label: `${t.name}, out in the bay`, town: t, water: r, course, committee: at(U(0.14), 0.22), shore: shoreOf(w, r, 6, 44, e.h) };
  }
  return null;
}

/** A run of water along a town's shore for the boats to file down, close in, with people on the quay. */
function waterfrontPlace(w: World, e: Happening): Place | null {
  for (const t of townsBySize(w, 'suburb')) {
    const c = { x: t.x0 + t.size / 2, z: t.z0 + t.size / 2 };
    for (const r of openWater(w, 26, 5, c, 1, t.size / 2 + 24)) {
      // the shore along one long side, close by
      const long = r.x1 - r.x0 >= r.z1 - r.z0, len = long ? r.x1 - r.x0 : r.z1 - r.z0;
      const land = (side: number) => {
        let n = 0;
        for (let k = 0; k < len; k += 2) {
          for (let o = 1; o <= 3; o++) {
            const x = long ? r.x0 + k : side ? r.x1 - 1 + o : r.x0 - o, z = long ? (side ? r.z1 - 1 + o : r.z0 - o) : r.z0 + k;
            if (inB(x, z) && w.water[idx(x, z)] < 0) { n++; break; }
          }
        }
        return n;
      };
      const a = land(0), b = land(1), side = b > a ? 1 : 0;
      if (Math.max(a, b) < len / 8) continue;
      // the line a tile and a half out from that shore
      const off = side ? (long ? r.z1 - 1.5 : r.x1 - 1.5) : (long ? r.z0 + 1.5 : r.x0 + 1.5);
      const path: Pt[] = [];
      for (let k = 0.5; k <= len - 0.5; k += 1) path.push(long ? { x: r.x0 + k, z: off } : { x: off, z: r.z0 + k });
      if (rehash(e.h, 5) & 1) path.reverse();
      return { label: `${t.name}, along the waterfront`, town: t, water: r, path, shore: shoreOf(w, r, 4, 48, e.h) };
    }
  }
  return null;
}

/** A harbour (a major port before a small one): berths in the water off its pier, and open water a way out to come in from. */
function harbourPlace(w: World, e: Happening): Place | null {
  const ports = [...w.ports].sort((a, b) => (b.major ? 1 : 0) - (a.major ? 1 : 0) || u01(rehash(e.h, a.id)) - u01(rehash(e.h, b.id)));
  const S = waterSat(w, 2);
  const deep = (x: number, z: number) => inB(Math.floor(x), Math.floor(z)) && satCount(S, Math.floor(x), Math.floor(z), Math.floor(x) + 1, Math.floor(z) + 1) === 1;
  for (const p of ports) {
    const rx = p.root % N, rz = Math.floor(p.root / N);
    const [dx, dz] = DIRS[p.dir];
    // berths beside the pier, either side, a few tiles out, each with room round it
    const berths: Pt[] = [];
    for (let k = 3; k <= 20 && berths.length < 5; k += 1) {
      for (const side of [4, -4, 7, -7]) {
        const x = rx + dx * k + dz * side + 0.5, z = rz + dz * k + dx * side + 0.5;
        if (!deep(x, z) || !deep(x + dx, z + dz) || !deep(x - dx, z - dz)) continue;
        // a galleon is four tiles long: room for one alongside another
        if (berths.some((q) => Math.hypot(q.x - x, q.z - z) < 5)) continue;
        berths.push({ x, z });
        if (berths.length >= 5) break;
      }
    }
    if (berths.length < 3) continue;
    // the offing: as far out along the pier's line as the water goes, up to forty tiles
    let offing: Pt | null = null;
    for (let k = 40; k >= 14; k -= 2) {
      const x = rx + dx * k + 0.5, z = rz + dz * k + 0.5;
      if (deep(x, z)) { offing = { x, z }; break; }
    }
    if (!offing) continue;
    const town = p.town >= 0 ? w.towns[p.town] ?? null : null;
    return { label: p.name, town, berths, offing, shore: shoreOf(w, { x0: rx - 4, z0: rz - 4, x1: rx + 5, z1: rz + 5 }, 4, 36, e.h) };
  }
  return null;
}

/** An airfield's strip, and the crowd along the fence on the far side of its apron. */
function airfieldPlace(w: World, e: Happening): Place | null {
  const r = runwaysOf(w).filter((q) => !q.deck).sort((a, b) => (b.major ? 1 : 0) - (a.major ? 1 : 0))[0];
  if (!r) return null;
  const shore: Pt[] = [];
  const across = r.half + (r.major ? 13 : 7);
  for (let k = 0; k < 44; k++) {
    const along = r.len * (0.15 + 0.7 * (k / 44)) + (u01(rehash(e.h, k)) - 0.5) * 0.4;
    const out = across + u01(rehash(e.h, k + 99)) * 0.8;
    shore.push({ x: r.ax + r.ux * along + r.sx * out - w.ox, z: r.az + r.uz * along + r.sz * out - w.oz });
  }
  return { label: r.name, town: null, runway: r, shore };
}

/** The tallest building of the county's biggest city: washed in colour, searchlights round it. */
function landmarkPlace(w: World, e: Happening): Place | null {
  void e;
  const t = bigTown(w, 'city');
  const tower = t ? tallest(t) : null;
  if (!t || !tower) return null;
  return { label: `${t.name}, the ${tower.kind.replace(/([A-Z])/g, ' $1').toLowerCase()}`, town: t, tower };
}

/** A town's night: its square for a great tree, its doorsteps for pumpkins. */
function townNightPlace(w: World, e: Happening): Place | null {
  const t = bigTown(w, 'suburb');
  if (!t) return null;
  const lots = t.buildings.filter((b) => up(b) && CROWD_LOTS.includes(b.kind)).sort((a, b) => CROWD_LOTS.indexOf(a.kind) - CROWD_LOTS.indexOf(b.kind) || b.w * b.d - a.w * a.d);
  const doors: (Pt & { yaw: number })[] = [];
  for (const b of t.buildings) {
    if (!up(b) || !b.solid || b.w * b.d > 9 || u01(rehash(e.h, b.uid)) < 0.45) continue;
    const [dx, dz] = DIRS[b.facing];
    const c = mid(b);
    doors.push({ x: c.x + dx * (b.w / 2 + 0.16) + (dz ? 0.18 : 0), z: c.z + dz * (b.d / 2 + 0.16) + (dx ? 0.18 : 0), yaw: Math.atan2(dx, dz) });
    if (doors.length >= 48) break;
  }
  return { label: t.name, town: t, lot: lots[0], tower: tallest(t) ?? undefined, doors };
}

// ---- phase 3: races ------------------------------------------------------------------------------------------------------

/** Country road tiles with nothing built near: where a rally starts or finishes. */
function openRoads(w: World, h: number): Pt[] {
  const out: Pt[] = [];
  for (let z = 8; z < N - 8; z += 3) {
    for (let x = 8; x < N - 8; x += 3) {
      const i = idx(x, z);
      if (!w.road[i] || w.deckAxis[i] || w.townId[i] >= 0 || w.water[i] >= 0) continue;
      let built = false;
      for (let dz = -3; dz <= 3 && !built; dz++) for (let dx = -3; dx <= 3; dx++) if (w.blocked[idx(x + dx, z + dz)]) { built = true; break; }
      if (!built) out.push({ x: x + 0.5, z: z + 0.5 });
    }
  }
  return out.sort((a, b) => u01(rehash(h, a.x * 977 + a.z)) - u01(rehash(h, b.x * 977 + b.z)));
}

/** Dry, open ground at a point or the nearest such within a few tiles (a checkpoint's flags stand on it). */
function dryNear(w: World, p: Pt): Pt | null {
  for (let r = 0; r <= 6; r++) {
    for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
      if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
      const x = Math.floor(p.x) + dx, z = Math.floor(p.z) + dz;
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (w.water[i] < 0 && !w.blocked[i] && w.townId[i] < 0) return { x: x + 0.5, z: z + 0.5 };
    }
  }
  return null;
}

/** A rally: a start on an open country road, a finish 50–90 tiles off, three checkpoints between, flagged on dry ground. */
function rallyPlace(w: World, e: Happening): Place | null {
  const roads = openRoads(w, e.h);
  for (const a of roads.slice(0, 12)) {
    const b = roads.find((q) => { const d = Math.hypot(q.x - a.x, q.z - a.z); return d >= 50 && d <= 90; });
    if (!b) continue;
    const course: Pt[] = [a];
    for (const f of [0.28, 0.52, 0.76]) {
      // off the straight line a little, so the field fans out
      const nx = -(b.z - a.z), nz = b.x - a.x, l = Math.hypot(nx, nz) || 1;
      const off = (u01(rehash(e.h, Math.round(f * 100))) - 0.5) * 18;
      const p = dryNear(w, { x: a.x + (b.x - a.x) * f + (nx / l) * off, z: a.z + (b.z - a.z) * f + (nz / l) * off });
      if (!p) break;
      course.push(p);
    }
    if (course.length < 4) continue;
    course.push(b);
    return { label: `${w.name}, across the open country`, town: null, course, shore: [] };
  }
  return null;
}

/** A powerboat course: an oval of four buoys in open water off a town, spectators on the shore. */
function powerboatPlace(w: World, e: Happening): Place | null {
  for (const t of townsBySize(w, 'suburb')) {
    const c = { x: t.x0 + t.size / 2, z: t.z0 + t.size / 2 };
    const r = openWater(w, 30, 14, c, 1, t.size / 2 + 45)[0];
    if (!r) continue;
    const long = r.x1 - r.x0 >= r.z1 - r.z0;
    const at = (u: number, v: number): Pt => (long ? { x: r.x0 + u * (r.x1 - r.x0), z: r.z0 + v * (r.z1 - r.z0) } : { x: r.x0 + v * (r.x1 - r.x0), z: r.z0 + u * (r.z1 - r.z0) });
    return { label: `${t.name}, off the shore`, town: t, water: r, course: [at(0.12, 0.25), at(0.88, 0.25), at(0.88, 0.75), at(0.12, 0.75)], shore: shoreOf(w, r, 6, 44, e.h) };
  }
  return null;
}

/** A drift meet: the biggest paved lot of a city, after dark, its cone course laid round two marks. */
function driftPlace(w: World, e: Happening): Place | null {
  void e;
  for (const t of townsBySize(w, 'city')) {
    const lots = t.buildings.filter((b) => up(b) && ['parking', 'civicSquare', 'plaza', 'marketSquare'].includes(b.kind) && b.w * b.d >= 12)
      .sort((a, b) => b.w * b.d - a.w * a.d);
    if (lots[0]) return { label: `${t.name}, on the ${lots[0].kind.replace(/([A-Z])/g, ' $1').toLowerCase()}`, town: t, lot: lots[0] };
  }
  return null;
}

/** Styles whose towns race dragon boats. */
const DRAGON_STYLES = new Set<string>(['chinese', 'seasia', 'osaka', 'japanese', 'hongkong', 'tokyo']);

/** Dragon boats: a straight course on the water by a Chinese, Southeast Asian or Japanese town. */
function dragonPlace(w: World, e: Happening): Place | null {
  for (const t of townsBySize(w, 'rural').filter((q) => DRAGON_STYLES.has(q.style))) {
    const c = { x: t.x0 + t.size / 2, z: t.z0 + t.size / 2 };
    const r = openWater(w, 24, 6, c, 1, t.size / 2 + 30)[0];
    if (!r) continue;
    const long = r.x1 - r.x0 >= r.z1 - r.z0;
    // four lanes down the long side, start to finish
    const lane = (k: number, u: number): Pt => (long ? { x: r.x0 + u * (r.x1 - r.x0), z: r.z0 + (k + 1) * ((r.z1 - r.z0) / 5) } : { x: r.x0 + (k + 1) * ((r.x1 - r.x0) / 5), z: r.z0 + u * (r.z1 - r.z0) });
    const flip = rehash(e.h, 4) & 1;
    const course = [0, 1, 2, 3].flatMap((k) => [lane(k, flip ? 0.94 : 0.06), lane(k, flip ? 0.06 : 0.94)]);
    return { label: `${t.name}, on the water`, town: t, water: r, course, shore: shoreOf(w, r, 5, 44, e.h) };
  }
  return null;
}

/** A gondola regatta: the longest straight-ish run of a Venice's canals, crowds along the banks. */
function gondolaPlace(w: World, e: Happening): Place | null {
  for (const t of w.towns.filter((q) => q.canals)) {
    // canal water inside the town, from the tile of it nearest the middle
    const wet = (i: number) => w.water[i] >= 0 && !w.blocked[i];
    let start = -1, bd = Infinity;
    const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
    for (let z = t.z0; z < t.z0 + t.size; z++) for (let x = t.x0; x < t.x0 + t.size; x++) {
      if (!inB(x, z) || !wet(idx(x, z))) continue;
      const d = Math.hypot(x - cx, z - cz);
      if (d < bd) { bd = d; start = idx(x, z); }
    }
    if (start < 0) continue;
    const path = channel(w, t, start, 20, 40, e.h, wet);
    if (!path) continue;
    // the banks: dry tiles beside the canal along the way
    const shore: Pt[] = [];
    for (const p of path) for (const [dx, dz] of DIRS) {
      const x = Math.floor(p.x) + dx, z = Math.floor(p.z) + dz;
      if (inB(x, z) && w.water[idx(x, z)] < 0 && !w.blocked[idx(x, z)] && shore.length < 60 && u01(rehash(e.h, idx(x, z))) < 0.6) shore.push({ x: x + 0.2 + u01(rehash(e.h, x)) * 0.6, z: z + 0.2 + u01(rehash(e.h, z)) * 0.6 });
    }
    return { label: `${t.name}, on the canals`, town: t, path, shore };
  }
  return null;
}

/** A way along tiles that pass `ok` from `start`, as avenue() finds one along streets: far enough, with fewest turns. */
function channel(w: World, t: Town, start: number, min: number, max: number, h: number, ok: (i: number) => boolean): Pt[] | null {
  const prev = new Map<number, number>([[start, -1]]);
  const dist = new Map<number, number>([[start, 0]]);
  const queue = [start];
  const far: number[] = [];
  for (let q = 0; q < queue.length; q++) {
    const i = queue[q], d = dist.get(i)!;
    if (d >= min) far.push(i);
    if (d >= max) continue;
    const x = i % N, z = (i - x) / N;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (nx < t.x0 - 6 || nz < t.z0 - 6 || nx >= t.x0 + t.size + 6 || nz >= t.z0 + t.size + 6 || !inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (prev.has(j) || !ok(j)) continue;
      prev.set(j, i);
      dist.set(j, d + 1);
      queue.push(j);
    }
  }
  if (!far.length) return null;
  const turns = (end: number): number => {
    let n = 0, last = -2;
    for (let i = end, p = prev.get(i)!; p >= 0; i = p, p = prev.get(i)!) { const dir = i - p; if (last !== -2 && dir !== last) n++; last = dir; }
    return n;
  };
  let best = far[0], bs = Infinity;
  for (const f of far) { const s = turns(f) * 6 - dist.get(f)! + u01(rehash(h, f)) * 3; if (s < bs) { bs = s; best = f; } }
  const tiles: number[] = [];
  for (let i = best; i >= 0; i = prev.get(i)!) tiles.push(i);
  return tiles.reverse().map((i) => ({ x: (i % N) + 0.5, z: Math.floor(i / N) + 0.5 }));
}

// ---- phase 4 ------------------------------------------------------------------------------------------------------

/** The road tile nearest a town's middle: where a run from town to town starts or ends. */
function squareKerb(w: World, t: Town): Pt | null {
  const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
  let best: Pt | null = null, bd = Infinity;
  for (let z = t.z0; z < t.z0 + t.size; z++) for (let x = t.x0; x < t.x0 + t.size; x++) {
    if (!inB(x, z)) continue;
    const i = idx(x, z);
    if (!w.road[i] || w.deckAxis[i] || w.water[i] >= 0) continue;
    const d = Math.hypot(x + 0.5 - cx, z + 0.5 - cz);
    if (d < bd) { bd = d; best = { x: x + 0.5, z: z + 0.5 }; }
  }
  return best;
}

/** Two towns of the county `min`–`max` tiles apart (by kind, `kinds`), as a run's start and finish at their squares. */
function townToTown(w: World, e: Happening, min: number, max: number, kinds: Town['kind'][]): Place | null {
  const ts = w.towns.filter((t) => kinds.includes(t.kind)).sort((a, b) => u01(rehash(e.h, a.id)) - u01(rehash(e.h, b.id)));
  for (const a of ts) for (const b of ts) {
    if (a === b) continue;
    const d = Math.hypot(a.x0 + a.size / 2 - b.x0 - b.size / 2, a.z0 + a.size / 2 - b.z0 - b.size / 2);
    if (d < min || d > max) continue;
    const from = squareKerb(w, a), to = squareKerb(w, b);
    if (from && to) return { label: `${a.name} to ${b.name}`, town: a, from, to, tower: undefined };
  }
  return null;
}

/** Buildings a wedding party comes out of. */
const CHAPELS = new Set<string>(['church', 'chapel', 'cathedral', 'temple', 'mosque', 'westerkerk', 'notreDame', 'stPeters', 'sacreCoeur', 'orthodoxChurch', 'staveChurch', 'synagogue', 'wat', 'meetingHouse']);
/** Big buildings that open with a ribbon. */
const OPENINGS = new Set<string>(['mall', 'departmentStore', 'museum', 'arena', 'concertHall', 'hotel', 'library', 'aquarium', 'casino', 'exchange', 'operaHouse', 'stadium', 'university', 'marketHall', 'bigBox']);
const SCREENS = new Set<string>(['cinema', 'theatre', 'operaHouse', 'chicagoTheatre']);
/** Works whose gates a picket line stands at. */
const WORKS = new Set<string>(['factory', 'brewery', 'canalWarehouse', 'cannery', 'lumberYard', 'steelworks', 'mill', 'sawmill', 'warehouse', 'depot', 'refinery', 'powerStation', 'chemicalWorks', 'textileMill', 'recyclingCentre', 'bottlingPlant', 'printWorks']);
const PARKS: Building['kind'][] = ['meadow', 'greatPark', 'park', 'bandstandGreen', 'amphitheatre', 'pitch', 'picnicGround', 'botanicalGarden', 'formalGarden'];

/** A town's procession, from a building of these kinds (else its hall), `min`–`max` tiles of its streets. */
function avenueFrom(w: World, e: Happening, t: Town | null, kinds: Set<string>, min: number, max: number, what: string): Place | null {
  if (!t) return null;
  for (const b of t.buildings.filter((q) => up(q) && kinds.has(q.kind))) {
    const k = kerbTile(w, b);
    if (k < 0) continue;
    const path = avenue(w, t, k, min, max, e.h);
    if (!path || path.length < min - 2) continue;
    return { label: `${t.name}, ${what}`, town: t, path, tower: b, towers: towersAlong(t, path, 3, 1.4) };
  }
  return null;
}

/** The biggest lot of these kinds in a town of at least `min`, the kinds in order of preference. */
function lotIn(w: World, min: keyof typeof TOWN_RANK, kinds: Building['kind'][], area: number): Place | null {
  for (const t of townsBySize(w, min)) {
    const lots = t.buildings.filter((b) => up(b) && kinds.includes(b.kind) && b.w * b.d >= area).sort((a, b) => kinds.indexOf(a.kind) - kinds.indexOf(b.kind) || b.w * b.d - a.w * a.d);
    if (lots[0]) return { label: `${t.name}, the ${lots[0].kind.replace(/([A-Z])/g, ' $1').toLowerCase()}`, town: t, lot: lots[0] };
  }
  return null;
}

/** A town of one of these styles, biggest first. */
const styled = (w: World, styles: string[]): Town | null => townsBySize(w, 'rural').find((t) => styles.includes(t.style)) ?? null;

/** A stadium in a city (an oval or a gridiron for the trucks, any for the blimp). */
function stadiumIn(w: World, designs: string[] | null): Place | null {
  for (const t of townsBySize(w, 'suburb')) {
    const b = t.buildings.find((q) => up(q) && q.kind === 'stadium' && (!designs || designs.includes(stadiumDesignOf(q))));
    if (b) return { label: `${t.name}, the stadium`, town: t, lot: b, tower: b };
  }
  return null;
}

/** Somewhere open in the county: dry, unbuilt ground near the middle of a town (or of the county), for a sky event. */
function openGround(w: World, e: Happening, near: Town | null): Pt | null {
  const c = near ? { x: near.x0 + near.size / 2 + (u01(rehash(e.h, 1)) - 0.5) * near.size * 1.6, z: near.z0 + near.size / 2 + (u01(rehash(e.h, 2)) - 0.5) * near.size * 1.6 } : { x: N / 2, z: N / 2 };
  return dryNear(w, { x: Math.max(8, Math.min(N - 8, c.x)), z: Math.max(8, Math.min(N - 8, c.z)) }) ?? dryNear(w, { x: N / 2, z: N / 2 });
}

/** Where each of phase 4's kinds is held. */
function phase4Place(w: World, e: Happening): Place | null {
  switch (e.kind) {
    case 'vintageRally': return townToTown(w, e, 30, 140, ['rural', 'suburb', 'city', 'metro', 'mega']);
    case 'cycleRace': return townToTown(w, e, 50, 170, ['rural', 'suburb', 'city', 'metro', 'mega']);
    case 'tractorRun': return townToTown(w, e, 22, 110, ['rural', 'suburb']);
    case 'weddingConvoy': return avenueFrom(w, e, townsBySize(w, 'rural').find((t) => t.buildings.some((b) => CHAPELS.has(b.kind))) ?? null, CHAPELS, 12, 24, 'from the church door');
    case 'royalProcession': return avenuePlace(w, e, styled(w, ['tudor', 'london', 'medieval']), 18, 32, 'the royal route');
    case 'mardiGras': return avenuePlace(w, e, styled(w, ['neworleans']), 18, 32, 'the parade route');
    case 'lunarNewYear': return avenuePlace(w, e, styled(w, ['chinese', 'hongkong', 'seasia']), 16, 30, 'the main street');
    case 'marathon': return avenuePlace(w, e, bigTown(w, 'city'), 30, 44, 'the marathon course');
    case 'climateMarch': return avenuePlace(w, e, bigTown(w, 'city'), 22, 36, 'the march route');
    case 'streetMarket': return avenuePlace(w, e, bigTown(w, 'suburb'), 12, 20, 'the market street');
    case 'monsterTrucks': return stadiumIn(w, ['bowl', 'gridiron']);
    case 'sponsorBlimp': return stadiumIn(w, null);
    case 'circusCaravan': return lotIn(w, 'suburb', ['meadow', 'greatPark', 'park', 'pitch'], 16);
    case 'foodTrucks': return lotIn(w, 'city', ['civicSquare', 'plaza', 'marketSquare', 'parking', 'pitch'], 12);
    case 'parkConcert': return lotIn(w, 'suburb', PARKS, 12);
    case 'harvestFair': return lotIn(w, 'rural', ['meadow', 'pitch', 'marketSquare', 'park', 'civicSquare', 'plaza'], 12);
    case 'balloonFestival': return lotIn(w, 'rural', ['meadow', 'greatPark', 'pitch', 'park'], 16);
    case 'lanternFestival': {
      // 0.7.0's onsen towns are Japanese too, and take many of the spots a Japanese town would have had: one holds it
      // in its park or square, or failing those (a village of lanes) on the car park below the inns
      const styles = NEXT_WORLD ? ['japanese', 'tokyo', 'osaka', 'onsen'] : ['japanese', 'tokyo', 'osaka'];
      // (before 0.7.0 only the biggest such town was asked; now each in turn)
      const towns = NEXT_WORLD ? townsBySize(w, 'rural').filter((q) => styles.includes(q.style)) : [styled(w, styles)].filter((q): q is Town => !!q);
      for (const t of towns) {
        const lot = t.buildings.find((b) => up(b) && PARKS.includes(b.kind)) ?? t.buildings.find((b) => up(b) && ['plaza', 'civicSquare', 'marketSquare'].includes(b.kind))
          ?? (t.style === 'onsen' ? t.buildings.filter((b) => up(b) && b.kind === 'parking' && b.w * b.d >= 4).sort((a, b) => b.w * b.d - a.w * a.d)[0] : undefined);
        if (lot) return { label: `${t.name}, under the blossom`, town: t, lot };
      }
      return null;
    }
    case 'veniceCarnival': { const t = w.towns.find((q) => q.canals); if (!t) return null; const lot = t.buildings.find((b) => up(b) && ['plaza', 'civicSquare', 'marketSquare', 'fountainSquare', 'plazaSteps'].includes(b.kind)); return lot ? { label: `${t.name}, the squares`, town: t, lot } : null; }
    case 'fireboatSalute': return harbourPlace(w, e);
    case 'blessingFleet': return harbourPlace(w, e);
    case 'strikePickets': {
      for (const t of townsBySize(w, 'rural')) for (const b of t.buildings) {
        if (!up(b) || !WORKS.has(b.kind)) continue;
        const k = kerbTile(w, b);
        if (k >= 0) return { label: `${t.name}, the ${b.kind.replace(/([A-Z])/g, ' $1').toLowerCase()} gates`, town: t, tower: b, from: { x: (k % N) + 0.5, z: Math.floor(k / N) + 0.5 } };
      }
      return null;
    }
    case 'grandOpening': case 'premiereNight': {
      const set = e.kind === 'premiereNight' ? SCREENS : OPENINGS;
      for (const t of townsBySize(w, 'suburb')) {
        const bs = t.buildings.filter((b) => up(b) && set.has(b.kind)).sort((a, b) => u01(rehash(e.h, a.uid)) - u01(rehash(e.h, b.uid)));
        for (const b of bs) {
          const k = kerbTile(w, b);
          if (k >= 0) return { label: `${t.name}, the ${b.kind.replace(/([A-Z])/g, ' $1').toLowerCase()}`, town: t, tower: b, from: { x: (k % N) + 0.5, z: Math.floor(k / N) + 0.5 } };
        }
      }
      return null;
    }
    case 'blackout': { const t = bigTown(w, 'city'); return t ? { label: t.name, town: t } : null; }
    case 'launchWatch': {
      const pad = w.allBuildings.find((b) => b.kind === 'launchPad' && up(b));
      if (!pad) return null;
      const shore: Pt[] = [];
      for (let k = 0; k < 48; k++) {
        const a = (k / 48) * Math.PI * 2 + u01(rehash(e.h, k)) * 0.3, r = 14 + u01(rehash(e.h, k + 50)) * 10;
        const p = dryNear(w, { x: pad.x + pad.w / 2 + Math.cos(a) * r, z: pad.z + pad.d / 2 + Math.sin(a) * r });
        if (p) shore.push(p);
      }
      return { label: 'the launch pad', town: null, tower: pad, shore };
    }
    case 'whalePod': {
      for (const t of townsBySize(w, 'rural')) {
        const r = openWater(w, 26, 12, { x: t.x0 + t.size / 2, z: t.z0 + t.size / 2 }, 2, t.size / 2 + 60)[0];
        if (r) return { label: `off ${t.name}`, town: t, water: r, shore: shoreOf(w, r, 6, 30, e.h) };
      }
      return null;
    }
    case 'swimMeet': {
      // the biggest town's lido (a town with two: the event's own pick)
      for (const t of townsBySize(w, 'rural')) {
        const pools = t.buildings.filter((b) => up(b) && b.kind === 'lido');
        if (pools.length) return { label: `${t.name}, the lido`, town: t, lot: pools[Math.floor(u01(rehash(e.h, 9)) * pools.length)] };
      }
      return null;
    }
    case 'murmuration': case 'superbloom': case 'meteorShower': case 'eclipse': case 'aurora': {
      const t = e.kind === 'murmuration' ? townsBySize(w, 'rural').reverse()[0] ?? null : bigTown(w, 'rural');
      const p = openGround(w, e, t);
      return p ? { label: t ? `over ${t.name}` : w.name, town: t, from: p } : null;
    }
    default: return null;
  }
}

// ---- the markets (0.7.0, NEXT_WORLD) -------------------------------------------------------------------------------------

/** What a market takes over: a straight run of street, a crossroads and its arms, or a square and the road round it. */
export interface MarketSite {
  kind: 'street' | 'junction' | 'plaza';
  /** Road tiles shut while it is on (setting up, open, packing away), in the county's frame. */
  tiles: number[];
  /** The ways the stalls stand along: each a straight line of tile middles (a street, a crossroads' arms). */
  lines: Pt[][];
  /** A square's lot, for the plaza kind. */
  lot?: Building;
  /** Where a barrier and a "Road closed" sign stand: at the edge of a shut tile, `dx, dz` pointing out of the market. */
  ends: (Pt & { dx: number; dz: number })[];
}

/** Old-town styles, where a market is likelier; the Germanic and old-world ones a Christmas market likelier still. */
const OLD_TOWN = new Set<string>(['tudor', 'medieval', 'budapest', 'dutch', 'paris', 'timber', 'chalet', 'gothic', 'russian', 'london', 'venice', 'roman', 'adriatic', 'granite']);
const GERMANIC = new Set<string>(['tudor', 'medieval', 'budapest', 'timber', 'chalet', 'gothic', 'dutch', 'granite']);
/** Farm biomes, where farmers' markets are thicker on the ground. */
const FARM_REGIONS = new Set<string>(['goldhills', 'lavender', 'veldt', 'moors', 'terraces', 'fens']);
/** Lots a market can fill: the market square first. */
const MARKET_LOTS: Building['kind'][] = ['marketSquare', 'civicSquare', 'plaza', 'fountainSquare', 'plazaSteps', 'parking'];

/**
 * Does this town keep a market of this kind? The same answer every week, for every player. A farmers' market in about
 * a third of towns from the suburbs up, more in farm country and old towns; a Christmas market in a fifth of towns
 * and two cities in five, far more in the Tudor, walled, Budapest and Germanic ones.
 */
export function keepsMarket(w: World, t: Town, kind: 'farmersMarket' | 'christmasMarket'): boolean {
  if (TOWN_RANK[t.kind] < 1) return false;
  let p: number;
  if (kind === 'farmersMarket') {
    p = 0.3;
    if (t.region && FARM_REGIONS.has(t.region)) p *= 1.6;
    if (OLD_TOWN.has(t.style)) p *= 1.5;
  } else {
    p = TOWN_RANK[t.kind] >= 2 ? 0.4 : 0.2;
    if (GERMANIC.has(t.style)) p *= 2.2;
    else if (OLD_TOWN.has(t.style)) p *= 1.4;
  }
  return u01(hashString(`${w.seed}|${w.cx},${w.cz}|${t.id}|${kind}`)) < Math.min(0.92, p);
}

const roadOk = (w: World, x: number, z: number): boolean => {
  if (!inB(x, z)) return false;
  const i = idx(x, z);
  return !!w.road[i] && !w.deckAxis[i] && w.water[i] < 0 && !w.rail[i];
};
const inTown = (t: Town, x: number, z: number, pad = 2) => x >= t.x0 - pad && z >= t.z0 - pad && x < t.x0 + t.size + pad && z < t.z0 + t.size + pad;

/** Road tiles of a town nearest its middle first. */
function centralRoads(w: World, t: Town): number[] {
  const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2, out: [number, number][] = [];
  for (let z = t.z0; z < t.z0 + t.size; z++) for (let x = t.x0; x < t.x0 + t.size; x++) if (roadOk(w, x, z)) out.push([idx(x, z), Math.hypot(x + 0.5 - cx, z + 0.5 - cz)]);
  return out.sort((a, b) => a[1] - b[1]).map((q) => q[0]);
}

/** The ways out of a set of shut tiles: a barrier at each edge where an open road carries on. */
function endsOf(w: World, tiles: number[]): MarketSite['ends'] {
  const set = new Set(tiles), out: MarketSite['ends'] = [];
  for (const i of tiles) {
    const x = i % N, z = (i - x) / N;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (!inB(nx, nz) || set.has(idx(nx, nz)) || !w.road[idx(nx, nz)]) continue;
      out.push({ x: x + 0.5 + dx * 0.44, z: z + 0.5 + dz * 0.44, dx, dz });
    }
  }
  return out;
}

/** A straight run of street through the middle of town, `min`–`max` tiles, its ends where it stops being straight. */
function streetSite(w: World, t: Town, min: number, max: number): MarketSite | null {
  for (const s of centralRoads(w, t).slice(0, 60)) {
    const x0 = s % N, z0 = (s - x0) / N;
    for (const [dx, dz] of [[1, 0], [0, 1]]) {
      // as far each way along the axis as the street goes, while it stays in town
      let a = 0, b = 0;
      while (a < max && roadOk(w, x0 - dx * (a + 1), z0 - dz * (a + 1)) && inTown(t, x0 - dx * (a + 1), z0 - dz * (a + 1))) a++;
      while (a + b < max - 1 && roadOk(w, x0 + dx * (b + 1), z0 + dz * (b + 1)) && inTown(t, x0 + dx * (b + 1), z0 + dz * (b + 1))) b++;
      if (a + b + 1 < min) continue;
      const tiles: number[] = [], line: Pt[] = [];
      for (let k = -a; k <= b; k++) { const x = x0 + dx * k, z = z0 + dz * k; tiles.push(idx(x, z)); line.push({ x: x + 0.5, z: z + 0.5 }); }
      return { kind: 'street', tiles, lines: [line], ends: endsOf(w, tiles) };
    }
  }
  return null;
}

/** A crossroads (or a T) near the middle of town, and up to `arm` tiles of each road off it. */
function junctionSite(w: World, t: Town, arm: number): MarketSite | null {
  for (const s of centralRoads(w, t).slice(0, 80)) {
    const x0 = s % N, z0 = (s - x0) / N;
    const ways = DIRS.filter(([dx, dz]) => roadOk(w, x0 + dx, z0 + dz));
    if (ways.length < 3) continue;
    const tiles = [s], lines: Pt[][] = [];
    for (const [dx, dz] of ways) {
      const line: Pt[] = [{ x: x0 + 0.5, z: z0 + 0.5 }];
      for (let k = 1; k <= arm && roadOk(w, x0 + dx * k, z0 + dz * k) && inTown(t, x0 + dx * k, z0 + dz * k); k++) {
        tiles.push(idx(x0 + dx * k, z0 + dz * k));
        line.push({ x: x0 + dx * k + 0.5, z: z0 + dz * k + 0.5 });
      }
      if (line.length > 1) lines.push(line);
    }
    if (tiles.length < 6) continue;
    return { kind: 'junction', tiles, lines, ends: endsOf(w, tiles) };
  }
  return null;
}

/** A square near the middle of town, the road round it shut, and (`spill`) the streets off it for a few tiles. */
function plazaSite(w: World, t: Town, biggest: boolean, spill: number): MarketSite | null {
  const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
  const lots = t.buildings.filter((b) => up(b) && MARKET_LOTS.includes(b.kind) && b.w * b.d >= 9)
    .sort((a, b) => (biggest ? b.w * b.d - a.w * a.d : 0) || Math.hypot(mid(a).x - cx, mid(a).z - cz) - Math.hypot(mid(b).x - cx, mid(b).z - cz));
  for (const lot of lots.slice(0, 4)) {
    const ring = new Set<number>();
    for (let x = lot.x - 1; x <= lot.x + lot.w; x++) for (const z of [lot.z - 1, lot.z + lot.d]) if (roadOk(w, x, z)) ring.add(idx(x, z));
    for (let z = lot.z; z < lot.z + lot.d; z++) for (const x of [lot.x - 1, lot.x + lot.w]) if (roadOk(w, x, z)) ring.add(idx(x, z));
    if (ring.size < 3) continue;
    // the streets off it: a few tiles out along each road that leaves the ring
    const tiles = new Set(ring);
    let edge = [...ring];
    for (let k = 0; k < spill && tiles.size < 44; k++) {
      const next: number[] = [];
      for (const i of edge) {
        const x = i % N, z = (i - x) / N;
        for (const [dx, dz] of DIRS) {
          const nx = x + dx, nz = z + dz;
          if (!roadOk(w, nx, nz) || tiles.has(idx(nx, nz)) || !inTown(t, nx, nz)) continue;
          // not back along the lot's own side
          if (nx >= lot.x - 1 && nx <= lot.x + lot.w && nz >= lot.z - 1 && nz <= lot.z + lot.d) continue;
          tiles.add(idx(nx, nz));
          next.push(idx(nx, nz));
        }
      }
      edge = next;
    }
    const list = [...tiles];
    const lines: Pt[][] = [];
    // the stalls along the road round the square: one line a side
    const side = (pts: Pt[]) => { if (pts.length >= 2) lines.push(pts); };
    side(Array.from({ length: lot.w }, (_, k) => ({ x: lot.x + k + 0.5, z: lot.z - 0.5 })).filter((p) => ring.has(idx(Math.floor(p.x), Math.floor(p.z)))));
    side(Array.from({ length: lot.w }, (_, k) => ({ x: lot.x + k + 0.5, z: lot.z + lot.d + 0.5 })).filter((p) => ring.has(idx(Math.floor(p.x), Math.floor(p.z)))));
    side(Array.from({ length: lot.d }, (_, k) => ({ x: lot.x - 0.5, z: lot.z + k + 0.5 })).filter((p) => ring.has(idx(Math.floor(p.x), Math.floor(p.z)))));
    side(Array.from({ length: lot.d }, (_, k) => ({ x: lot.x + lot.w + 0.5, z: lot.z + k + 0.5 })).filter((p) => ring.has(idx(Math.floor(p.x), Math.floor(p.z)))));
    return { kind: 'plaza', tiles: list, lines, lot, ends: endsOf(w, list) };
  }
  return null;
}

/**
 * A market's place: the `site`-th town of the county that keeps one of this kind (biggest first), and what of it the
 * market takes. A farmers' market keeps to the same spot every week, a square, a crossroads or a street as the town's
 * own roll has it; a Christmas market fills the main square and the streets off it, or a crossroads where there is none.
 */
function marketPlace(w: World, e: Happening): Place | null {
  const kind = e.kind as 'farmersMarket' | 'christmasMarket';
  const towns = townsBySize(w, 'suburb').filter((t) => keepsMarket(w, t, kind));
  const t = towns[e.site ?? 0];
  if (!t) return null;
  const roll = u01(hashString(`${w.seed}|${w.cx},${w.cz}|${t.id}|${kind}|where`));
  const order: (() => MarketSite | null)[] = kind === 'christmasMarket'
    ? [() => plazaSite(w, t, true, TOWN_RANK[t.kind] >= 2 ? 3 : 2), () => junctionSite(w, t, 3), () => streetSite(w, t, 6, 11)]
    : roll < 0.4 ? [() => plazaSite(w, t, false, 1), () => junctionSite(w, t, 2), () => streetSite(w, t, 5, 9)]
    : roll < 0.7 ? [() => junctionSite(w, t, 2), () => streetSite(w, t, 5, 9), () => plazaSite(w, t, false, 1)]
    : [() => streetSite(w, t, 5, 9), () => junctionSite(w, t, 2), () => plazaSite(w, t, false, 1)];
  for (const f of order) {
    const m = f();
    if (!m) continue;
    const what = m.kind === 'plaza' ? `the ${m.lot!.kind.replace(/([A-Z])/g, ' $1').toLowerCase()}` : m.kind === 'junction' ? 'the crossroads' : 'the high street';
    return { label: `${t.name}, ${what}`, town: t, market: m, closes: m.tiles, lot: m.lot };
  }
  return null;
}
