import type { Building, Town, World } from '../../world/tiles';
import type { Pic } from './types';

/**
 * Small helpers the desk's hooks share (docs/newspaper.html, The news desk): each hook is one `press.write`
 * beside an announcement the game already makes, in the file that makes it. These turn what the hook has to
 * hand (a world, a town, a building) into what the desk keeps. Types only from the world, so nothing here
 * pulls the game in after it.
 */

/** A town's key, as the ledger writes it (ledger.ts townKey). */
export const keyOf = (w: World, t: Town): string => `${w.cx},${w.cz}#${t.id}`;

/** A town's middle in world tiles. */
export const townAt = (w: World, t: Town): { x: number; z: number } => ({ x: w.ox + t.x0 + t.size / 2, z: w.oz + t.z0 + t.size / 2 });

/** A building's middle in world tiles. */
export const buildingAt = (w: World, b: Building): { x: number; z: number } => ({ x: w.ox + b.x + b.w / 2, z: w.oz + b.z + b.d / 2 });

/** The town a key names, while its cell is the one given. */
export function townOf(w: World, key: string): Town | null {
  const [cell, id] = key.split('#');
  if (cell !== `${w.cx},${w.cz}`) return null;
  return w.towns[Number(id)] ?? null;
}

/** A building as the hero stage draws it, the real one (its variant, facing, style): its picture in the paper. */
export function buildingPic(w: World, b: Building, style?: string): Pic {
  return {
    kind: 'building', b: b.kind, arch: b.style ?? style ?? 'classic', w: b.w, d: b.d, floors: b.floors,
    real: { cx: w.cx, cz: w.cz, uid: b.uid, seed: b.seed, facing: b.facing, ...(b.style ? { style: b.style } : {}), ...(b.derelict ? { derelict: true } : {}) },
  };
}

export const vehiclePic = (model: string): Pic => ({ kind: 'vehicle', model });

/**
 * A name as the copy writes it after "the": "The Grand Hotel" is "Grand Hotel", and a lot with no name of its
 * own, called by its kind ("Bowling alley", "Drive-thru"), is a common noun: "bowling alley".
 */
export function plain(name: string): string {
  const n = name.replace(/^the\s+/i, '').trim();
  const words = n.split(/\s+/);
  const generic = words.length <= 3 && words.slice(1).every((w) => !/^[A-Z]/.test(w));
  return generic ? n.replace(/^./, (c) => c.toLowerCase()) : n;
}

/** An HQ grade as the copy says it: "an institution". */
export function gradeWords(name: string): string {
  const n = name.toLowerCase();
  if (n === 'lodging') return 'lodgings';
  return `${/^[aeiou]/.test(n) ? 'an' : 'a'} ${n}`;
}

/** Channel 6's uppercase headline as a newspaper sets it: "LIGHTS ON THE MOON?" is "Lights on the moon?". */
export const sentence = (s: string): string => {
  const t = s.toLowerCase().trim();
  return t ? t[0].toUpperCase() + t.slice(1) : t;
};

/** A tavern story's first sentence, when it is short enough to print as a rumour. */
export function firstSentence(text: string, maxWords = 20): string | null {
  const m = /^[^.!?]+[.!?]/.exec(text.trim());
  const s = (m ? m[0] : text).trim();
  return s.split(/\s+/).length <= maxWords ? s : null;
}
