// ---- 4. a rival haulier: a competitor's van to its depot -----------------------------------------

const rival = carTemplate({
  id: 'tail:rival', thread: 'fleet', title: 'Follow the Van', caption: 'A rival’s van', label: 'Tail the rival van', end: 'depot',
  who: 'rival', giver: (salt) => `${personName(salt)}, haulier`,
  why: () => 'Their vans keep beating us to every load. Tail one back to its depot and we’ll know where they work from.',
  details: () => 'Their drivers are jumpy: a van that thinks it’s followed goes the long way round. Find the depot and its beacon will show you the yard.',
  // the van in the firm's own colours
  car: (_p, s) => ({ model: 'mule', colour: s.firm?.colour ?? 0x7d8a92, name: `the ${s.firm?.name ?? 'rival'} van` }),
  acts: [['check', 'go'], ['go', 'check'], ['dash', 'go']],
  ends: (c, w, pick) => {
    const me = { x: c.at.x - w.ox, z: c.at.z - w.oz };
    const deps = (c.depots ?? []).filter((d) => d.cell[0] === w.cx && d.cell[1] === w.cz && crow({ x: d.x - w.ox, z: d.z - w.oz }, me) < 220);
    if (!deps.length) return null;
    const dep = deps[pick(deps.length)];
    const to = kerbNear(w, dep.x - w.ox, dep.z - w.oz, 6);
    if (!to) return null;
    const froms = buildingsOf(w, ['shop', 'store', 'grocery', 'warehouse', 'factory', 'mall', 'bakery', 'farmShop'], to, 50, 160);
    if (!froms.length) return null;
    const b = froms[pick(froms.length)];
    const from = kerbOf(w, b);
    if (!from) return null;
    const ti = idx(Math.floor(to.x), Math.floor(to.z));
    const there = w.townId[ti] >= 0 ? w.towns[w.townId[ti]] ?? null : null;
    return { w, b, from, fromName: 'the loading bay', to, toName: `the ${dep.name} depot`, town: townOf(w, b), firm: dep, there };
  },
  reward: (s) => [
    { r: 'cash', n: 500 },
    ...(s.firm ? [{ r: 'reveal' as const, what: 'depot' as const, at: at(s.w, s.to, s.toName), line: `${s.firm.name} run their vans out of ${s.firm.town}: their depot is lit`, key: s.firm.id }] : []),
    ...standing(s),
    // knowing where they load, you can call on their customers: the depot's own town hears of you too
    ...(s.there && s.there !== s.town ? [{ r: 'standing' as const, town: townRef(s.w, s.there), n: 1 }] : []),
  ],
});

// ---- 5. an undercover detective: a getaway car, swapped at a garage, to the hideout -------------

const getaway = carTemplate({
  id: 'tail:getaway', thread: 'town', title: 'Getaway Car', caption: 'The getaway car', label: 'Tail the green Wasabi', end: 'hideout',
  who: 'police', giver: (salt) => `Detective ${surname(salt)}`,
  why: () => 'A getaway driver is about to leave the bank. Tail him to the gang’s hideout. He changes cars on the way, so watch closely.',
  details: () => 'We can’t use a patrol car, he knows them all. He’ll stop at a garage and come out in something else: be near enough to see what, or he’s gone.',
  car: () => carOf('wasabi', 0x9bd13a),
  swap: carOf('mule', 0x7d8a92),
  acts: [['dash', 'swap', 'check'], ['swap', 'back', 'go'], ['check', 'swap', 'dash']],
  ends: (c, w, pick) => {
    const me = { x: c.at.x - w.ox, z: c.at.z - w.oz };
    const banks = buildingsOf(w, ['bank', 'exchange', 'postOffice', 'departmentStore'], me, 0, 170);
    for (let k = 0; k < 3 && banks.length; k++) {
      const b = banks.splice(pick(banks.length), 1)[0];
      const from = kerbOf(w, b);
      if (!from) continue;
      const h = hideoutNear(w, from, 60, 170, pick);
      if (!h) continue;
      return { w, b, from, fromName: 'the bank', to: h.p, toName: h.name, town: townOf(w, b) };
    }
    return null;
  },
  reward: (s) => [{ r: 'cash', n: 800 }, { r: 'reveal', what: 'hideout', at: at(s.w, s.to, s.toName), line: `The gang’s hideout: ${s.toName}, out past ${s.town ? s.town.name.replace(/ City$/, '') : 'the town'}` }, ...standing(s)],
});

// ---- 6. a tavern regular: the courier who leads to a hidden vehicle ----------------------------

const TAVERN_KINDS = ['pub', 'saloon', 'teaHouse', 'taverna', 'tikiBar', 'bar', 'diveBar', 'inn'];
const tavernStart = (c: MissionCtx, w: World, pick: (n: number) => number): Building | null => {
  const me = { x: c.at.x - w.ox, z: c.at.z - w.oz };
  const list = w.allBuildings.filter((b) => !b.gone && (b.storefront === 'tavern' || TAVERN_KINDS.includes(b.kind)) && crow(mid(b), me) < 200);
  return list.length ? list[pick(list.length)] : null;
};

const courier = carTemplate({
  id: 'tail:courier', thread: 'car', title: 'The Courier', caption: 'The courier’s runabout', label: 'Tail the yellow Pip', end: 'stash',
  who: 'tavern', giver: (salt) => `${personName(salt)} at the bar`,
  why: () => 'The courier who drinks here checks on something hidden out of town. Tail his yellow Pip and see what he’s been keeping.',
  details: () => 'He’s careful: he parks up and watches the road before he goes anywhere near it. Whatever is out there, nobody has claimed it yet.',
  car: () => carOf('pip', 0xf5cf3a),
  acts: [['wait', 'go'], ['check', 'dash'], ['go', 'check']],
  ends: (c, _home, pick) => {
    // a hidden vehicle in any cell in memory not too far off, and a tavern in that cell to start from
    const st = (c.stashes ?? []).filter((s) => Math.hypot(s.cx * N + s.x - c.at.x, s.cz * N + s.z - c.at.z) < 260);
    if (!st.length) return null;
    const s = st[pick(st.length)];
    const w = c.worlds.find((q) => q.cx === s.cx && q.cz === s.cz);
    if (!w) return null;
    const to = kerbNear(w, s.x, s.z, 10);
    const b = tavernStart(c, w, pick);
    const from = b ? kerbOf(w, b) : null;
    if (!to || !b || !from || crow(from, to) < 40) return null;
    return { w, b, from, fromName: 'the tavern', to, toName: s.place, town: townOf(w, b), stash: s };
  },
  reward: (s) => {
    const what = s.stash ? vehicleNoun(defOf(s.stash.model)) : 'a vehicle';
    return [{ r: 'cash', n: 250 }, { r: 'reveal', what: 'stash', at: at(s.w, s.to, s.toName), line: `${what.charAt(0).toUpperCase()}${what.slice(1)} nobody has claimed, at ${s.toName}: drive up and press Tab`, key: s.stash?.key }];
  },
});

