// ---- 8 & 9. the railway: a freight train, followed from the road -------------------------------

/** A station's platform middle, in its cell's tiles. */
function stationAt(w: World, st: RailStation): Pt | null {
  const p = w.rails[st.path];
  if (!p) return null;
  const s = (st.s0 + st.s1) / 2;
  let i = 0;
  while (i < p.s.length - 2 && p.s[i + 1] < s) i++;
  const f = Math.max(0, Math.min(1, (s - p.s[i]) / ((p.s[i + 1] - p.s[i]) || 1)));
  return { x: p.xz[i * 2] + (p.xz[i * 2 + 2] - p.xz[i * 2]) * f, z: p.xz[i * 2 + 1] + (p.xz[i * 2 + 3] - p.xz[i * 2 + 1]) * f };
}

interface TrainSpec {
  id: string; thread: Thread; title: string; why: string; details: string; label: string; who: string;
  giver: (salt: string) => string; reward: (w: World, town: Town | null, yard: PlaceRef) => Reward[];
}

function trainTemplate(spec: TrainSpec): Template {
  return {
    id: spec.id, thread: spec.thread, kind: 'tail', side: true, cooldown: 30,
    gate: (c, ms) => tailGate(c, ms),
    bind: (c, h) => {
      const pick = picker(h);
      const w = c.home;
      if (!w.rails.length) return null;
      // somewhere for a freight to call: a goods yard or a harbour depot in memory
      const yards: PlaceRef[] = [];
      for (const v of c.worlds) for (const st of v.stations) {
        if (st.kind !== 'goodsYard' && st.kind !== 'harbourDepot') continue;
        const p = stationAt(v, st);
        if (p) yards.push(at(v, p, st.name));
      }
      if (!yards.length) return null;
      const me = { x: c.at.x - w.ox, z: c.at.z - w.oz };
      const meets = w.stations.map((st) => ({ st, p: stationAt(w, st) })).filter((q) => q.p && crow(q.p, me) < 190);
      for (let k = 0; k < 4 && meets.length; k++) {
        const { st, p } = meets.splice(pick(meets.length), 1)[0];
        const road = p ? kerbNear(w, p.x, p.z, 8) : null;
        if (!road) continue;
        const g = giverSpot(w, road, pick);
        if (!g) continue;
        const town = st.town >= 0 ? w.towns[st.town] ?? null : null;
        const meet = at(w, road, `the ${st.kind === 'goodsYard' ? 'goods yard' : 'station'} road`);
        const yard = yards.filter((y) => Math.hypot(y.x - meet.x, y.z - meet.z) > 20).sort((a, b) => Math.hypot(a.x - meet.x, a.z - meet.z) - Math.hypot(b.x - meet.x, b.z - meet.z))[0] ?? yards[0];
        return {
          title: spec.title, why: spec.why, details: spec.details,
          giver: { who: spec.who, name: spec.giver(`${spec.id}|${w.cx},${w.cz}|${st.name}`), at: at(w, g, 'by the line'), town: town ? townRef(w, town) : null },
          hero: { kind: 'load', load: 'loco' }, caption: 'A freight on the line',
          objs: [{ t: 'tail', label: spec.label, icon: '🚂', at: meet, to: yard, legs: [], car: { model: 'tomato', colour: 0, name: 'the freight' }, train: true, end: 'yard' }],
          reward: spec.reward(w, town, yard),
        };
      }
      return null;
    },
  };
}

