import type { World } from '../world/tiles';
import { digestOf, type TownDigest } from '../world/townDigest';

/**
 * Every town the game knows of (docs/townregister.html), as digests: the towns on the islands in memory, digested
 * live once a game hour each (or at once after a `poke`), and every town in a county surveyed from afar (the survey
 * worker digests them as it surveys, `adopt`). Kept per world seed in IndexedDB, so a town seen once stays known.
 * The town card's Overview ranks a town among them, and the town register lists them.
 */
export class TownIndex {
  private digests = new Map<string, TownDigest>();
  /** The game hour each island in memory was last digested at. */
  private done = new WeakMap<World, number>();
  /** Keys of the towns on the islands in memory at the last refresh: the register's Near me. */
  private nearKeys = new Set<string>();
  /** A town's works in memory as [count, hearts, crossings] (net/community.ts townWorks), set by main; null when none known. */
  worksOf: ((key: string) => [number, number, number] | null) | null = null;
  /** Bumped when anything in the index changes, so views drawn from it know to redraw. */
  version = 0;
  private dirty = false;
  private seed = '';
  private saveT = 0;
  /** False from a load until its read is back: no write may overwrite the kept list with a few live towns first. */
  private ready = false;
  /** Each load's number, so an older load's read that comes back late is thrown away. */
  private loads = 0;

  /** Digest the islands in memory that are due. Cheap to call often: an island is redone once an hour. */
  refresh(worlds: Iterable<World>, hours: number): void {
    const h = Math.floor(hours);
    const near = new Set<string>();
    for (const w of worlds) {
      for (const t of w.towns) near.add(`${w.cx},${w.cz}#${t.id}`);
      if (this.done.get(w) === h) continue;
      this.done.set(w, h);
      for (const t of w.towns) {
        const d = digestOf(w, t, hours);
        const wk = this.worksOf?.(d.key);
        if (wk && wk[0]) d.works = wk;
        this.set(d);
      }
    }
    if (near.size !== this.nearKeys.size || [...near].some((k) => !this.nearKeys.has(k))) { this.nearKeys = near; this.version++; }
  }

  /** Something changed on this island: digest it again at the next refresh. */
  poke(w: World): void { this.done.delete(w); }

  /**
   * Digests from a survey. A town digested live keeps its own unless the survey's copy is of the same island as it
   * stands now (a survey of an island in memory comes with its edits): a worker's copy never knows the clock.
   */
  adopt(list: readonly TownDigest[]): void {
    for (const d of list) {
      const was = this.digests.get(d.key);
      if (was && was.day >= 0 && d.day < 0) continue;
      this.set(d);
    }
  }

  private set(d: TownDigest): void {
    const was = this.digests.get(d.key);
    // a digest that knows nothing of works (a survey's, or works not loaded yet) keeps the last count
    if (!d.works && was?.works && !this.worksOf?.(d.key)) d.works = was.works;
    this.digests.set(d.key, d);
    if (!was || JSON.stringify(was) !== JSON.stringify(d)) { this.dirty = true; this.version++; }
  }

  get(key: string): TownDigest | null { return this.digests.get(key) ?? null; }

  all(): TownDigest[] { return [...this.digests.values()]; }

  /** Is this town on an island in memory? */
  near(key: string): boolean { return this.nearKeys.has(key); }

  get size(): number { return this.digests.size; }

  /**
   * Where a town stands among every town known, by a measure (bigger first; ties by name): its place, how many were
   * ranked, and its value. `among` narrows who it is ranked against. Null for a town not in the index.
   */
  rank(key: string, measure: (d: TownDigest) => number, among?: (d: TownDigest) => boolean): { place: number; of: number; value: number } | null {
    const me = this.digests.get(key);
    if (!me) return null;
    const list = this.all().filter((d) => !among || among(d) || d.key === key);
    const value = measure(me);
    let place = 1;
    for (const d of list) {
      if (d.key === key) continue;
      const v = measure(d);
      if (v > value || (v === value && d.name.localeCompare(me.name) < 0)) place++;
    }
    return { place, of: list.length, value };
  }

  // ---- kept between sessions ----

  /** Start on a world: forget the last one's towns and read this one's back. */
  async load(seed: string): Promise<void> {
    this.digests.clear();
    this.nearKeys.clear();
    this.done = new WeakMap();
    this.seed = seed;
    this.ready = false;
    this.version++;
    const n = ++this.loads;
    const saved = await readTowns(seed);
    if (n !== this.loads) return;
    // what was digested while the read was out is newer than the kept copy: it stays, and is written with the rest
    for (const d of saved ?? []) if (d && typeof d.key === 'string' && !this.digests.has(d.key)) this.digests.set(d.key, d);
    this.ready = true;
    this.version++;
  }

  /** Written out at most once a minute while anything has changed (call every frame). */
  tick(dt: number): void {
    this.saveT -= dt;
    if (this.saveT > 0 || !this.dirty || !this.seed || !this.ready) return;
    this.saveT = 60;
    this.flush();
  }

  /** Written out now, if anything changed (the page going away). */
  flush(): void {
    if (!this.dirty || !this.seed || !this.ready) return;
    this.dirty = false;
    void writeTowns(this.seed, this.all());
  }
}

// ---- IndexedDB: one record per world seed, the whole list ----

const DB = 'tinyfleet-towns', STORE = 'digests';
/** At most this many towns kept per world: the nearest-seen go last. */
const KEEP = 4000;

function openDb(): Promise<IDBDatabase | null> {
  return new Promise((resolve) => {
    try {
      if (typeof indexedDB === 'undefined') { resolve(null); return; }
      const req = indexedDB.open(DB, 1);
      req.onupgradeneeded = () => { req.result.createObjectStore(STORE); };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
      req.onblocked = () => resolve(null);
    } catch { resolve(null); }
  });
}

async function readTowns(seed: string): Promise<TownDigest[] | null> {
  const db = await openDb();
  if (!db) return null;
  return new Promise((resolve) => {
    try {
      const req = db.transaction(STORE, 'readonly').objectStore(STORE).get(seed);
      req.onsuccess = () => { db.close(); resolve(Array.isArray(req.result) ? req.result as TownDigest[] : null); };
      req.onerror = () => { db.close(); resolve(null); };
    } catch { db.close(); resolve(null); }
  });
}

async function writeTowns(seed: string, list: TownDigest[]): Promise<void> {
  const db = await openDb();
  if (!db) return;
  try {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).put(list.slice(-KEEP), seed);
    tx.oncomplete = () => db.close();
    tx.onerror = () => db.close();
  } catch { db.close(); }
}
