import type { TownKind } from '../world/tiles';
import { CATS, CAT_COLOUR, CAT_LABEL, type TownDigest } from '../world/townDigest';
import { TOWN_INFO } from '../world/towns';
import type { TownIndex } from './townIndex';
import { ECONOMY, type TownLedger } from './ledger';

/** A town's prosperity from its rate and kind: its trade against the norm for a town its size. */
const prosperityOf = (rate: number, kind: TownKind): number => rate / ECONOMY.norm[kind];
import { esc } from './cargoHud';
import type { TownQuery, TownReport, TownsPage } from '../../shared/towns';
import { cap, pretty } from './townTabs/common';
import {
  NO_FILTERS, SORTS, SORT_BY, SPECIAL_LABEL, filterWords, passes, ranked,
  type Filters, type RegisterRow, type SortId,
} from './registerSorts';

/**
 * The town register (docs/townregister.html, phase 2): every town the game knows of in one centred window, ranked
 * on the left by any of the measures in registerSorts.ts and narrowed by filter chips, with the picked town's digest
 * on the right (Open card, Show on map, the bookmark star). Shift-click a second row to compare the two.
 * Scopes: Near me (the islands in memory) and Known (everything digested, here or surveyed from afar).
 */

export type Scope = 'near' | 'known' | 'world';

export interface RegisterHost {
  index: TownIndex;
  /** The player's own carrier id (carriage.ts YOU). */
  you: string;
  ledger(key: string): TownLedger | null;
  /** Your books there: your earnings, and whether you have ever traded there. */
  book(key: string): { mine: number; visited: boolean };
  /** Its imported cultures: style id, label, points, rung. */
  culture(key: string): { style: string; label: string; pts: number; rung: number }[];
  /** Its property's worth. */
  property(key: string): number;
  /** Your share of its carriage, your rung of its ladder, and whose territory it is. */
  share(key: string): number;
  rung(key: string): number;
  holder(key: string): { who: string; contested: boolean };
  /** A carrier's name. */
  carrierName(who: string): string;
  /** A building kind's label. */
  label(kind: string): string;
  starred(key: string): boolean;
  star(key: string, name: string, at: { x: number; z: number }): void;
  /** Your vehicle, in world tiles. */
  player(): { x: number; z: number } | null;
  /** Called on open, so the other windows can step aside. */
  opened(): void;
  /** The town's own card (the window closes). */
  openCard(key: string): void;
  /** The world map on the town (the window closes). */
  showOnMap(key: string): void;
  /**
   * Online, the World scope (phase 4, server/gazetteer.ts): ask for a page, the newest page, and the player's own id
   * (holders the server names by player id).
   */
  world?: { online(): boolean; ask(q: TownQuery): boolean; page(): TownsPage['page'] | null; me(): string };
}

/** Sorts on what is only the player's own: the server cannot rank the World scope by them. */
const OWN_SORTS: SortId[] = ['mine', 'share'];

const N = 256;
const KEY = 'tinyfleet-register';
/** Rows drawn at once; "Show more" adds as many again. */
const PAGE = 150;
/** Seconds between rebuilding the rows from the books while open. */
const REBUILD = 2;

const KINDS: TownKind[] = ['rural', 'suburb', 'city', 'metro', 'mega'];
const kindLabel = (k: TownKind): string => TOWN_INFO[k].label;
const styleLabel = (s: string): string => cap(pretty(s));

interface Saved { scope: Scope; sort: SortId; flip: boolean; f: Filters; open: boolean }

export class TownRegister {
  readonly el = document.createElement('div');
  isOpen = false;
  private scope: Scope = 'known';
  private sort: SortId = 'built';
  private flip = false;
  private f: Filters = NO_FILTERS();
  private filtersOpen = false;
  private search = '';
  private picked = '';
  private other = '';
  private shown = PAGE;
  private rows: RegisterRow[] = [];
  private rowsAt = -1;
  private rowsVer = -1;
  private t = 0;
  private searchEl = document.createElement('input');
  private bar = document.createElement('div');
  private chips = document.createElement('div');
  private words = document.createElement('p');
  private left = document.createElement('div');
  private right = document.createElement('div');
  private htmls = { bar: '', chips: '', words: '', left: '', right: '' };

  constructor(private host: RegisterHost) {
    this.el.id = 'townreg';
    this.el.hidden = true;
    const panel = document.createElement('div');
    panel.className = 'panel';
    const header = document.createElement('header');
    const title = document.createElement('h2');
    title.innerHTML = 'Towns<span>.</span>';
    const find = document.createElement('label');
    find.className = 'tr-find';
    this.searchEl.type = 'text';
    this.searchEl.placeholder = 'Find a town, county or style';
    this.searchEl.maxLength = 40;
    this.searchEl.spellcheck = false;
    this.searchEl.autocomplete = 'off';
    this.searchEl.addEventListener('input', () => { this.search = this.searchEl.value.trim().toLowerCase(); this.shown = PAGE; this.render(); });
    find.append('🔍', this.searchEl);
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'tr-x';
    close.title = 'Close (Esc)';
    close.textContent = '×';
    close.addEventListener('click', () => this.close());
    header.append(title, find, close);
    this.bar.className = 'tr-bar';
    this.chips.className = 'tr-chips';
    this.words.className = 'tr-words';
    const body = document.createElement('div');
    body.className = 'tr-body';
    this.left.className = 'tr-col tr-left';
    this.right.className = 'tr-col tr-right';
    body.append(this.left, this.right);
    panel.append(header, this.bar, this.chips, this.words, body);
    this.el.append(panel);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    // on pointerdown, as the social window does: a redraw between press and release would lose a click
    panel.addEventListener('pointerdown', (e) => {
      const t = e.target as HTMLElement;
      if (t.tagName === 'INPUT' || t.tagName === 'SELECT' || t.tagName === 'OPTION') return;
      if (this.press(t, e.shiftKey)) { e.preventDefault(); this.render(); }
    });
    panel.addEventListener('change', (e) => {
      const t = e.target as HTMLSelectElement;
      this.changed(t.name, t.value);
      t.blur();
      this.render();
    });
    try {
      const s = JSON.parse(localStorage.getItem(KEY) ?? 'null') as Saved | null;
      if (s) {
        if (s.scope === 'near' || s.scope === 'known' || s.scope === 'world') this.scope = s.scope;
        if (s.sort in SORT_BY) this.sort = s.sort;
        this.flip = !!s.flip;
        this.f = { ...NO_FILTERS(), ...s.f };
        this.filtersOpen = !!s.open;
      }
    } catch { /* not remembered */ }
    document.body.append(this.el);
  }

  /** Open, on a town if given. */
  open(key?: string): void {
    if (!this.isOpen) {
      this.isOpen = true;
      this.el.hidden = false;
      this.host.opened();
      this.shown = PAGE;
      this.rowsAt = -1;
    }
    if (key) { this.picked = key; this.other = ''; this.search = ''; this.searchEl.value = ''; }
    this.render(true);
    if (key) this.scrollToPicked();
  }

  toggle(key?: string): void { if (this.isOpen && !key) this.close(); else this.open(key); }

  close(): void {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.el.hidden = true;
    this.searchEl.blur();
  }

  tick(dt: number): void {
    if (!this.isOpen) return;
    this.t -= dt;
    if (this.t > 0) return;
    this.t = 0.5;
    this.render();
  }

  /** Esc inside the search box clears it first; true when the press was spent. */
  takeEscape(): boolean {
    if (document.activeElement === this.searchEl && this.searchEl.value) {
      this.searchEl.value = ''; this.search = ''; this.render(); return true;
    }
    return false;
  }

  // ---- the rows ----

  /** Every known town with its books, rebuilt every couple of seconds (and whenever the index changes). */
  private allRows(): RegisterRow[] {
    const now = performance.now() / 1000;
    if (this.rowsAt >= 0 && now - this.rowsAt < REBUILD && this.rowsVer === this.host.index.version) return this.rows;
    this.rowsAt = now;
    this.rowsVer = this.host.index.version;
    const h = this.host, p = h.player();
    this.rows = h.index.all().map((d) => {
      const l = h.ledger(d.key);
      const rate = l?.rate ?? 0;
      const hist = l?.histGrown ?? [];
      const strands = h.culture(d.key);
      const styles: RegisterRow['styles'] = {};
      for (const s of strands) styles[s.style] = { pts: s.pts, rung: s.rung, label: s.label };
      const hold = h.holder(d.key);
      const b = h.book(d.key);
      const mid = { x: d.at[0] * N + d.at[2], z: d.at[1] * N + d.at[3] };
      return {
        d, near: h.index.near(d.key), rate, prosperity: l ? prosperityOf(rate, l.kind ?? d.kind) : 0,
        grown30: hist.length ? Math.max(0, (l?.grown ?? 0) - hist[hist.length - 1]) : 0,
        blight: l?.blight ?? d.derelict,
        culture: strands.reduce((s, x) => s + x.pts, 0), cultures: strands.filter((x) => x.rung >= 2).length, styles,
        value: h.property(d.key), mine: b.mine, share: h.share(d.key), holder: hold.who, contested: hold.contested,
        rung: h.rung(d.key), starred: h.starred(d.key), visited: b.visited,
        dist: p ? Math.hypot(mid.x - p.x, mid.z - p.z) : null,
      };
    });
    return this.rows;
  }

  // ---- the World scope (phase 4) ----

  /** The World scope's rows so far: the server's pages for the current ask, in its order. */
  private worldRows: RegisterRow[] = [];
  private worldBase = '';
  private worldSeen: TownsPage['page'] | null = null;
  private worldTotal = 0;
  private worldKnown = 0;

  private worldOn(): boolean { return !!this.host.world?.online(); }

  /** The ask for the current sort, filters and search, from row `at`. Your own sorts and filters stay with you. */
  private worldAsk(at: number): TownQuery {
    const p = this.host.player();
    const sort = OWN_SORTS.includes(this.sort) ? 'built' : this.sort;
    return { sort, flip: this.flip, style: this.f.culture || undefined, f: { ...this.f, starred: false, visited: '' }, q: this.search || undefined, at, me: p ? [Math.round(p.x), Math.round(p.z)] : undefined };
  }

  /** A server row with your own numbers joined: your books, your share, your bookmarks. */
  private worldRow(r: TownReport): RegisterRow {
    const h = this.host, d = r.d, s = r.s, p = h.player();
    const styles: RegisterRow['styles'] = {};
    for (const [st, v] of Object.entries(s.styles)) styles[st] = { pts: v[0], rung: v[1], label: v[2] };
    const b = h.book(d.key);
    const me = h.world?.me() ?? '';
    return {
      d, near: h.index.near(d.key), rate: s.rate, prosperity: s.prosperity, grown30: s.grown30, blight: s.blight, culture: s.culture, cultures: s.cultures,
      styles, value: s.value, mine: b.mine, share: h.share(d.key), holder: me && s.holder === me ? h.you : s.holder, contested: s.contested,
      rung: h.rung(d.key), starred: h.starred(d.key), visited: b.visited,
      dist: p ? Math.hypot(d.at[0] * N + d.at[2] - p.x, d.at[1] * N + d.at[3] - p.z) : null,
    };
  }

  /** Ask for what the World scope needs, and take in any page that has come for the current ask. */
  private worldSync(): void {
    const w = this.host.world;
    if (!w) return;
    const ask = this.worldAsk(0);
    const base = JSON.stringify({ ...ask, at: 0, me: undefined });
    if (base !== this.worldBase) { this.worldBase = base; this.worldRows = []; this.worldTotal = 0; this.worldSeen = null; }
    const page = w.page();
    if (page && page !== this.worldSeen) {
      this.worldSeen = page;
      // a page for an older ask (the sort or the search has moved on since) is let go
      const same = page.ask.sort === ask.sort && !!page.ask.flip === !!ask.flip && (page.ask.q ?? '') === (ask.q ?? '') && (page.ask.style ?? '') === (ask.style ?? '');
      if (same) {
        const rows = page.rows.map((r) => this.worldRow(r));
        if (page.ask.at === 0) this.worldRows = rows;
        else if (page.ask.at === this.worldRows.length) this.worldRows = [...this.worldRows, ...rows];
        this.worldTotal = page.total;
        this.worldKnown = page.known;
      }
    }
    // the first page (asked again now and then, so it stays fresh), or the next when more are shown
    const at = this.worldRows.length && this.shown > this.worldRows.length && this.worldRows.length < this.worldTotal ? this.worldRows.length : 0;
    w.ask(this.worldAsk(at));
  }

  /** The rows in scope, through the search and the filters, ranked. */
  private list(): RegisterRow[] {
    if (this.scope === 'world') {
      // the server has ranked and filtered them; bookmarked and visited are yours, looked at here on what came
      return this.worldRows.filter((r) => (!this.f.starred || r.starred) && (this.f.visited !== 'yes' || r.visited) && (this.f.visited !== 'no' || !r.visited));
    }
    const q = this.search;
    const rows = this.allRows().filter((r) => (this.scope === 'known' || r.near)
      && (!q || r.d.name.toLowerCase().includes(q) || r.d.county.toLowerCase().includes(q) || styleLabel(r.d.style).toLowerCase().includes(q))
      && passes(r, this.f, this.host.you));
    return ranked(rows, this.sort, this.f.culture, this.flip);
  }

  // ---- drawing ----

  private render(force = false): void {
    if (!this.isOpen) return;
    if (this.scope === 'world' && !this.worldOn()) this.scope = 'known';
    if (this.scope === 'world') this.worldSync();
    const known = this.allRows();
    const all = this.scope === 'world' ? this.worldRows : known;
    const list = this.list();
    if (this.picked && !all.some((r) => r.d.key === this.picked)) this.picked = '';
    if (!this.picked && list.length) this.picked = list[0].d.key;

    this.put('bar', this.barHtml(known), this.bar, force);
    this.put('chips', this.filtersOpen ? this.chipsHtml(this.scope === 'world' ? [...known, ...this.worldRows] : known) : '', this.chips, force);
    this.chips.hidden = !this.filtersOpen;
    const fw = filterWords(this.f, kindLabel, styleLabel, (s) => all.find((r) => r.styles[s])?.styles[s].label ?? styleLabel(s));
    const world = this.scope === 'world';
    const sentence = `${this.scope === 'near' ? 'Towns near you' : world ? 'Every town anyone has seen' : 'Every town known'} · ${(world ? this.worldTotal : list.length).toLocaleString('en-US')} of ${(this.scope === 'near' ? all.filter((r) => r.near).length : world ? this.worldKnown : all.length).toLocaleString('en-US')}`
      + `${world && !this.worldSeen ? ' · asking the server…' : ''}${world && OWN_SORTS.includes(this.sort) ? ' · your own sorts rank only Near me and Known, so by most buildings' : ''}`
      + ` · by ${SORT_BY[world && OWN_SORTS.includes(this.sort) ? 'built' : this.sort].label.toLowerCase()}${this.sort === 'oneCulture' && !this.f.culture ? ' (pick a culture under Filters)' : ''}${this.flip ? ', reversed' : ''}${fw ? ` · ${fw}` : ''}${this.search ? ` · “${this.search}”` : ''}`;
    this.put('words', esc(sentence), this.words, force);
    this.put('left', this.leftHtml(list), this.left, force);
    const a = all.find((r) => r.d.key === this.picked), b = this.other ? all.find((r) => r.d.key === this.other) : undefined;
    this.put('right', a ? (b ? this.compareHtml(a, b, list) : this.pickedHtml(a, list)) : '<p class="tr-none">No town is known yet: drive about, or open the region map (M, then Y) to survey the counties round you.</p>', this.right, force);
  }

  /** A part's markup, swapped only when it has changed, and never while a select in it is open. */
  private put(k: keyof TownRegister['htmls'], html: string, el: HTMLElement, force: boolean): void {
    if (!force && this.htmls[k] === html) return;
    const a = document.activeElement;
    if (!force && a && el.contains(a) && a.tagName === 'SELECT') return;
    this.htmls[k] = html;
    el.innerHTML = html;
  }

  private barHtml(all: RegisterRow[]): string {
    const near = all.filter((r) => r.near).length;
    const scope = (s: Scope, label: string, n: number) => `<button type="button" data-scope="${s}" class="${this.scope === s ? 'on' : ''}">${label} <small>${n}</small></button>`;
    let groups = '', g = '';
    for (const s of SORTS) {
      if (s.group !== g) { if (g) groups += '</optgroup>'; g = s.group; groups += `<optgroup label="${esc(g)}">`; }
      groups += `<option value="${s.id}"${s.id === this.sort ? ' selected' : ''}>${esc(s.label)}</option>`;
    }
    groups += '</optgroup>';
    const n = this.filterCount();
    return `<div class="tr-scopes">${scope('near', 'Near me', near)}${scope('known', 'Known', all.length)}${this.worldOn() ? scope('world', 'World', this.worldKnown || all.length) : ''}</div>`
      + `<label class="tr-sort">Sort <select name="sort">${groups}</select></label>`
      + `<button type="button" data-act="flip" class="tr-flip${this.flip ? ' on' : ''}" title="Reverse the order">${this.flip ? '↑' : '↓'}</button>`
      + `<button type="button" data-act="filters" class="tr-ftoggle${this.filtersOpen ? ' on' : ''}">Filters${n ? ` <em>${n}</em>` : ''}</button>`
      + (n ? '<button type="button" data-act="clear" class="link">clear</button>' : '');
  }

  private filterCount(): number {
    const f = this.f;
    return (f.kinds.length ? 1 : 0) + (f.style ? 1 : 0) + (f.culture ? 1 : 0) + (f.within ? 1 : 0) + (f.county ? 1 : 0) + (f.ports || f.stations || f.airports ? 1 : 0)
      + (f.holder ? 1 : 0) + f.specials.length + (f.starred ? 1 : 0) + (f.visited ? 1 : 0) + (f.satellites ? 0 : 1);
  }

  private chipsHtml(all: RegisterRow[]): string {
    const f = this.f;
    const chip = (act: string, on: boolean, label: string) => `<button type="button" data-f="${esc(act)}" class="${on ? 'on' : ''}">${label}</button>`;
    const counts = <T extends string>(of: (r: RegisterRow) => T[]): Map<T, number> => {
      const m = new Map<T, number>();
      for (const r of all) for (const v of of(r)) m.set(v, (m.get(v) ?? 0) + 1);
      return m;
    };
    const styles = [...counts((r) => [r.d.style])].sort((a, b) => b[1] - a[1]);
    const cultures = new Map<string, { label: string; n: number }>();
    for (const r of all) for (const [s, v] of Object.entries(r.styles)) { const c = cultures.get(s) ?? { label: v.label, n: 0 }; c.n++; cultures.set(s, c); }
    const counties = [...counts((r) => [r.d.county])].sort((a, b) => a[0].localeCompare(b[0]));
    const opt = (v: string, label: string, on: boolean) => `<option value="${esc(v)}"${on ? ' selected' : ''}>${esc(label)}</option>`;
    const row = (title: string, inner: string) => `<div class="tr-frow"><span>${title}</span><div>${inner}</div></div>`;
    return row('Size', KINDS.map((k) => chip(`kind:${k}`, f.kinds.includes(k), esc(kindLabel(k)))).join('') + chip('sats', !f.satellites, 'No satellites'))
      + row('Style', `<select name="style">${opt('', 'Any style', !f.style)}${styles.map(([s, n]) => opt(s, `${styleLabel(s)} (${n})`, f.style === s)).join('')}</select>`)
      + row('Culture', `<select name="culture">${opt('', cultures.size ? 'Any culture' : 'No town has imported any culture yet', !f.culture)}${[...cultures].sort((a, b) => a[1].label.localeCompare(b[1].label)).map(([s, c]) => opt(s, `${c.label} (${c.n})`, f.culture === s)).join('')}</select>`
        + (f.culture ? [1, 2, 3].map((k) => chip(`rung:${k}`, f.rung === k, ['', 'Curiosity+', 'Influenced+', 'Infatuated'][k])).join('') : ''))
      + row('Where', [0, 1, 2, 3, 5].map((k) => chip(`within:${k}`, f.within === k, k ? `≤ ${k} ${k === 1 ? 'county' : 'counties'}` : 'Anywhere')).join('')
        + `<select name="county">${opt('', 'Any county', !f.county)}${counties.map(([c, n]) => opt(c, `${c} (${n})`, f.county === c)).join('')}</select>`)
      + row('Has', chip('ports', f.ports, '⚓ Harbour') + chip('stations', f.stations, '🚉 Station') + chip('airports', f.airports, '✈️ Airport'))
      + row('Held', (['', 'you', 'rival', 'none', 'contested'] as const).map((h) => chip(`holder:${h}`, f.holder === h, { '': 'Anyone', you: 'Yours', rival: 'Another fleet’s', none: 'Nobody’s', contested: 'Contested' }[h])).join(''))
      + row('Special', (Object.keys(SPECIAL_LABEL) as Filters['specials']).map((s) => chip(`special:${s}`, f.specials.includes(s), esc(cap(SPECIAL_LABEL[s].replace(/^an? /, ''))))).join(''))
      + row('Mine', chip('starred', f.starred, '★ Bookmarked') + chip('visited:yes', f.visited === 'yes', 'Visited') + chip('visited:no', f.visited === 'no', 'Never visited'));
  }

  private leftHtml(list: RegisterRow[]): string {
    if (!list.length) return `<p class="tr-none">${this.allRows().length ? 'No town matches. Try fewer filters.' : 'No town is known yet.'}</p>`;
    const s = SORT_BY[this.sort];
    const vals = list.map((r) => s.of(r, this.f.culture));
    const finite = vals.filter((v) => Number.isFinite(v));
    const top = s.low ? 0 : Math.max(1e-9, ...finite);
    const out = list.slice(0, this.shown).map((r, k) => {
      const d = r.d, v = vals[k];
      const w = s.low || !top ? 0 : Math.max(0, Math.min(100, (v / top) * 100));
      const cls = [r.d.key === this.picked ? 'on' : '', r.d.key === this.other ? 'other' : '', r.holder === this.host.you ? 'yours' : ''].filter(Boolean).join(' ');
      const tags = `${r.starred ? '<i class="star">★</i>' : ''}${r.holder ? `<i class="hold${r.holder === this.host.you ? ' you' : ''}" title="${esc(r.holder === this.host.you ? 'Your territory' : `${this.host.carrierName(r.holder)}’s territory`)}"></i>` : ''}`;
      return `<li class="${cls}" data-key="${esc(d.key)}"><span class="n">${k + 1}</span>`
        + `<span class="nm"><b>${esc(d.name)}</b>${tags}<small>${esc(kindLabel(d.kind))} · ${esc(styleLabel(d.style))} · ${esc(d.county)}${r.near ? '' : ' · far'}</small></span>`
        + `<span class="v">${esc(s.show(r, this.f.culture))}</span>${w ? `<span class="bar"><i style="width:${w.toFixed(1)}%"></i></span>` : ''}</li>`;
    }).join('');
    // in the World scope the server has more than came: as many as it says pass
    const total = this.scope === 'world' ? Math.max(this.worldTotal, list.length) : list.length;
    const more = total > this.shown ? `<button type="button" data-act="more" class="tr-more">Show ${Math.min(PAGE, total - this.shown)} more of ${total - this.shown}</button>` : '';
    return `<ol class="tr-list">${out}</ol>${more}<p class="tr-tip">Shift-click a second town to compare the two.</p>`;
  }

  /** Its places among the towns listed now, by a few measures. */
  private ranksIn(r: RegisterRow, list: RegisterRow[]): string {
    if (list.length < 3 || !list.includes(r)) return '';
    const ids: SortId[] = ['built', 'area', 'trade', 'cultured', 'hearts', 'sights', 'connected'];
    const chips = ids.map((id) => {
      const place = ranked(list, id, this.f.culture).indexOf(r) + 1;
      return { id, place };
    }).filter((x) => x.place > 0 && SORT_BY[x.id].of(r, this.f.culture) > 0).sort((a, b) => a.place - b.place).slice(0, 4);
    if (!chips.length) return '';
    return `<p class="tr-ranks">${chips.map((c) => `<button type="button" data-sort="${c.id}" class="rk${c.place === 1 ? ' top' : ''}"><b>#${c.place}</b> ${esc(SORT_BY[c.id].label.toLowerCase())}</button>`).join('')}<small>of ${list.length} listed</small></p>`;
  }

  private pickedHtml(r: RegisterRow, list: RegisterRow[]): string {
    const d = r.d;
    const sub = [kindLabel(d.kind), d.region ? cap(d.region) : '', `${styleLabel(d.style)} style`, d.county].filter(Boolean).join(' · ');
    const total = CATS.reduce((s, c) => s + d.cats[c], 0) || 1;
    const bar = `<div class="tr-cats">${CATS.filter((c) => d.cats[c]).map((c) => `<i style="width:${((d.cats[c] / total) * 100).toFixed(2)}%;background:${CAT_COLOUR[c]}" title="${esc(`${CAT_LABEL[c]}: ${d.cats[c]}`)}"></i>`).join('')}</div>`;
    const facts: [string, string][] = [
      ['Buildings', d.built.toLocaleString('en-US')],
      ['Tiles', d.area.toLocaleString('en-US')],
      ['Trade', r.rate ? `$${Math.round(r.rate).toLocaleString('en-US')}/h` : '—'],
      ['Prosperity', r.rate ? `${r.prosperity.toFixed(2)}×` : '—'],
      ['Culture', r.culture ? `${Math.round(r.culture).toLocaleString('en-US')} pts` : '—'],
      ['Your share', `${Math.round(r.share * 100)}%`],
    ];
    if (d.works?.[0]) facts.splice(5, 1, ['Works', `${d.works[0]} · ♥ ${d.works[1]}`]);
    const cultures = Object.values(r.styles).sort((a, b) => b.pts - a.pts).slice(0, 5)
      .map((s) => `<span class="cu r${s.rung}">${esc(s.label)} · ${s.rung ? ['', 'Curiosity', 'Influenced', 'Infatuated'][s.rung] : Math.round(s.pts)}</span>`).join(' ');
    const sights = d.notable.slice(0, 8).map(([k, n]) => `<span class="cg">${esc(this.host.label(k))}${n > 1 ? ` ×${n}` : ''}</span>`).join('');
    const links = [d.roadsTo ? `${d.roadsTo} road${d.roadsTo === 1 ? '' : 's'} to other towns` : 'no roads to other towns', d.ports ? `${d.ports} harbour${d.ports === 1 ? '' : 's'}${d.majorPort ? ' (major)' : ''}` : '', d.stations ? `${d.stations} station${d.stations === 1 ? '' : 's'}` : '', d.airports ? `${d.airports} airport${d.airports === 1 ? '' : 's'}` : ''].filter(Boolean).join(' · ');
    const special = [d.plan ? `Plan · ${styleLabel(d.plan)}` : '', d.onsen ? `Onsen town, after ${d.onsen}` : '', d.lake ? `Lake town, after ${d.lake}` : '', d.canals ? 'Canals' : '', d.strip ? 'The Strip' : '', d.perch ? `Perched · ${d.perch}` : '', d.parent ? 'Satellite' : ''].filter(Boolean);
    const hold = r.holder ? (r.holder === this.host.you ? `<b>Your territory</b>${r.contested ? ', contested' : ''}` : `${esc(this.host.carrierName(r.holder))}’s territory${r.contested ? ', contested' : ''}`) : 'Nobody’s territory';
    return `<div class="tr-pick"><header><h3>${esc(d.name)} <button type="button" data-act="star" class="tr-star${r.starred ? ' on' : ''}" title="Bookmark in your Passport">${r.starred ? '★' : '☆'}</button></h3><small>${esc(sub)}</small></header>`
      + this.ranksIn(r, list) + bar
      + `<dl class="tr-facts">${facts.map(([k, v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`
      + `<p class="tr-line">${hold}${r.visited ? ' · you have traded here' : ' · you have never traded here'}${r.near ? '' : ` · ${d.day < 0 ? 'surveyed from afar' : `seen on day ${d.day + 1}`}`}</p>`
      + (special.length ? `<p class="tr-line">${esc(special.join(' · '))}</p>` : '')
      + `<p class="tr-line">${esc(links)}</p>`
      + (cultures ? `<h4>Culture</h4><p class="tr-cul">${cultures}</p>` : '')
      + (sights ? `<h4>Known for</h4><p class="tr-sights">${sights}${d.notable.length > 8 ? ` <small>+${d.notable.length - 8} more</small>` : ''}</p>` : '')
      + `<div class="tr-acts"><button type="button" data-act="card" class="go">Open its card</button><button type="button" data-act="map">🗺 Show on map</button></div></div>`;
  }

  private compareHtml(a: RegisterRow, b: RegisterRow, list: RegisterRow[]): string {
    const rows: [string, (r: RegisterRow) => number, (r: RegisterRow) => string, boolean?][] = [
      ['Size', (r) => KINDS.indexOf(r.d.kind), (r) => kindLabel(r.d.kind)],
      ['Buildings', (r) => r.d.built, (r) => r.d.built.toLocaleString('en-US')],
      ['Tiles', (r) => r.d.area, (r) => r.d.area.toLocaleString('en-US')],
      ['Trade', (r) => r.rate, (r) => (r.rate ? `$${Math.round(r.rate)}/h` : '—')],
      ['Prosperity', (r) => r.prosperity, (r) => (r.rate ? `${r.prosperity.toFixed(2)}×` : '—')],
      ['Grown, 30 days', (r) => r.grown30, (r) => `+${r.grown30}`],
      ['Boarded up', (r) => r.blight, (r) => String(r.blight), true],
      ['Culture points', (r) => r.culture, (r) => Math.round(r.culture).toLocaleString('en-US')],
      ['Cultures influenced', (r) => r.cultures, (r) => String(r.cultures)],
      ['Sights', (r) => r.d.notable.reduce((s, [, n]) => s + n, 0), (r) => String(r.d.notable.reduce((s, [, n]) => s + n, 0))],
      ['Connections', (r) => r.d.roadsTo + r.d.stations + r.d.ports * 2 + r.d.airports * 3, (r) => `${r.d.roadsTo}r · ${r.d.stations}s · ${r.d.ports}h · ${r.d.airports}a`],
      ['Works', (r) => r.d.works?.[0] ?? 0, (r) => String(r.d.works?.[0] ?? 0)],
      ['Hearts on works', (r) => r.d.works?.[1] ?? 0, (r) => `♥ ${r.d.works?.[1] ?? 0}`],
      ['Fleet-built', (r) => r.d.playerBuilt, (r) => String(r.d.playerBuilt)],
      ['Property', (r) => r.value, (r) => (r.value ? `$${Math.round(r.value).toLocaleString('en-US')}` : '—')],
      ['Your trade', (r) => r.mine, (r) => (r.mine ? `$${Math.round(r.mine).toLocaleString('en-US')}` : '—')],
      ['Your share', (r) => r.share, (r) => `${Math.round(r.share * 100)}%`],
      ['From you', (r) => -(r.dist ?? Infinity), (r) => (r.dist === null ? '—' : `${(r.dist / 256).toFixed(1)} counties`)],
    ];
    const cell = (r: RegisterRow, o: RegisterRow, of: (r: RegisterRow) => number, low?: boolean) => {
      const x = of(r), y = of(o);
      return x !== y && (low ? x < y : x > y) ? ' class="best"' : '';
    };
    void list;
    return `<div class="tr-cmp"><table><thead><tr><th></th><th>${esc(a.d.name)}</th><th>${esc(b.d.name)}</th></tr></thead><tbody>`
      + rows.map(([k, of, show, low]) => `<tr><th>${k}</th><td${cell(a, b, of, low)}>${esc(show(a))}</td><td${cell(b, a, of, low)}>${esc(show(b))}</td></tr>`).join('')
      + `</tbody></table><div class="tr-acts"><button type="button" data-act="uncompare">Stop comparing</button><button type="button" data-act="card" class="go">Open ${esc(a.d.name)}’s card</button></div></div>`;
  }

  // ---- presses ----

  private press(t: HTMLElement, shift: boolean): boolean {
    const li = t.closest('li[data-key]') as HTMLElement | null;
    if (li?.dataset.key) {
      const k = li.dataset.key;
      if (shift && this.picked && k !== this.picked) this.other = this.other === k ? '' : k;
      else { this.picked = k; this.other = ''; }
      return true;
    }
    const b = t.closest('button') as HTMLButtonElement | null;
    if (!b) return false;
    if (b.dataset.scope) { this.scope = b.dataset.scope as Scope; this.shown = PAGE; this.save(); return true; }
    if (b.dataset.sort) { this.sort = b.dataset.sort as SortId; this.flip = false; this.save(); return true; }
    if (b.dataset.f) { this.filter(b.dataset.f); this.shown = PAGE; this.save(); return true; }
    const r = this.allRows().find((x) => x.d.key === this.picked);
    switch (b.dataset.act) {
      case 'flip': this.flip = !this.flip; this.save(); return true;
      case 'filters': this.filtersOpen = !this.filtersOpen; this.save(); return true;
      case 'clear': this.f = NO_FILTERS(); this.save(); return true;
      case 'more': this.shown += PAGE; return true;
      case 'uncompare': this.other = ''; return true;
      case 'star': if (r) { this.host.star(r.d.key, r.d.name, { x: r.d.at[0] * N + r.d.at[2], z: r.d.at[1] * N + r.d.at[3] }); this.rowsAt = -1; } return true;
      case 'card': if (r) { this.close(); this.host.openCard(r.d.key); } return true;
      case 'map': if (r) { this.close(); this.host.showOnMap(r.d.key); } return true;
    }
    return false;
  }

  /** A filter chip pressed: "kind:city", "within:2", "ports"… */
  private filter(what: string): void {
    const f = this.f;
    const [k, v] = what.split(':');
    switch (k) {
      case 'kind': { const kind = v as TownKind; f.kinds = f.kinds.includes(kind) ? f.kinds.filter((x) => x !== kind) : [...f.kinds, kind]; break; }
      case 'sats': f.satellites = !f.satellites; break;
      case 'rung': f.rung = Number(v); break;
      case 'within': f.within = Number(v); break;
      case 'ports': f.ports = !f.ports; break;
      case 'stations': f.stations = !f.stations; break;
      case 'airports': f.airports = !f.airports; break;
      case 'holder': f.holder = v as Filters['holder']; break;
      case 'special': { const s = v as Filters['specials'][number]; f.specials = f.specials.includes(s) ? f.specials.filter((x) => x !== s) : [...f.specials, s]; break; }
      case 'starred': f.starred = !f.starred; break;
      case 'visited': f.visited = f.visited === v ? '' : (v as Filters['visited']); break;
    }
  }

  /** A select changed. */
  private changed(name: string, value: string): void {
    if (name === 'sort' && value in SORT_BY) { this.sort = value as SortId; this.flip = false; }
    else if (name === 'style') this.f.style = value as Filters['style'];
    else if (name === 'culture') { this.f.culture = value; if (value && this.sort !== 'oneCulture') this.sort = 'oneCulture'; if (!value && this.sort === 'oneCulture') this.sort = 'cultured'; }
    else if (name === 'county') this.f.county = value;
    else return;
    this.shown = PAGE;
    this.save();
  }

  private save(): void {
    try { localStorage.setItem(KEY, JSON.stringify({ scope: this.scope, sort: this.sort, flip: this.flip, f: this.f, open: this.filtersOpen } satisfies Saved)); } catch { /* not remembered */ }
  }

  private scrollToPicked(): void {
    const li = this.left.querySelector('li.on') as HTMLElement | null;
    li?.scrollIntoView({ block: 'center' });
  }
}

export type { TownDigest };
