import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { Building, TownKind, World } from '../world/tiles';
import { VIS, Vis } from '../render/nightLights';
import { variantOf } from '../render/buildings/variants';
import { RIM_Y, lidoDims, lidoFrame, lidoPlan, lidoToIsland, type LidoPlan, type P3, type Pool, type Pt } from '../render/buildings/lidoPlan';
import { clamp01, rand } from '../util/math';

/**
 * Public swim time at the lidos: townsfolk coming out of the changing rooms in their swimsuits, swimming lengths,
 * lying on the loungers, sitting on the rim with their feet in, queueing at the diving boards and the slides,
 * diving, jumping, sliding down with a splash at the bottom, and a lifeguard up on the high chair. Busy on summer
 * afternoons, quieter in spring and autumn, nobody in winter (the water's out) or after closing. In the hall
 * (an aquatic centre) they are only seen while its roof is open, in summer.
 *
 * Like the herds (herds.ts): no pathfinding, each bather drifts to where it is going round the pool's corners,
 * and everything is worked out in the model's own frame (render/buildings/lidoPlan.ts) and turned onto the
 * island to draw. A swim meet (events/swimMeet.ts) empties the pool while it is on (MEETS).
 */

/** Pools with a swim meet on: the public are out of the water till it is over. */
export const MEETS = new Set<Building>();

const PLANS = new WeakMap<Building, LidoPlan>();
/** Where everything is at this lido, for the model it draws. */
export function lidoPlanOf(b: Building): LidoPlan {
  let p = PLANS.get(b);
  if (!p) {
    const { W, D } = lidoDims(b);
    PLANS.set(b, (p = lidoPlan(W, D, variantOf(b))));
  }
  return p;
}

/** Somewhere on a lido's deck, on the island: where a passer-by stops for a while (pedestrians.ts). */
export function lidoDeckSpot(b: Building): Pt {
  const p = lidoPlanOf(b);
  const r = p.deck[Math.floor(Math.random() * p.deck.length)];
  return lidoToIsland(b, r.x0 + Math.random() * (r.x1 - r.x0), r.z0 + Math.random() * (r.z1 - r.z0));
}

// ---- the bather -------------------------------------------------------------------------------------------------

const SKIN = [0xe0b48a, 0xc68e62, 0x8d5a3b, 0xf0caa4, 0xa86e48];
export const SUITS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0xf49ab5, 0x1f2329, 0xf4f2ec];

function paint(g: THREE.BufferGeometry, hex: number): THREE.BufferGeometry {
  const out = g.index ? g.toNonIndexed() : g;
  out.deleteAttribute('uv');
  const n = out.attributes.position.count, c = new THREE.Color(hex), a = new Float32Array(n * 3);
  for (let k = 0; k < n; k++) { a[k * 3] = c.r; a[k * 3 + 1] = c.g; a[k * 3 + 2] = c.b; }
  out.setAttribute('color', new THREE.BufferAttribute(a, 3));
  return out;
}

/**
 * A bather standing with its feet at the origin, facing +z, about a person high (0.12): the skin (head, arms,
 * legs) and the swimsuit (coloured per bather). Shared with the swim meet's racers.
 */
let BODY: { skin: THREE.BufferGeometry; suit: THREE.BufferGeometry } | null = null;
function batherBody(): { skin: THREE.BufferGeometry; suit: THREE.BufferGeometry } {
  if (BODY) return BODY;
  // painted white: each bather's skin tone is its instance colour
  const skin = 0xffffff;
  const box = (w: number, h: number, d: number, x: number, y: number, z: number) => paint(new THREE.BoxGeometry(w, h, d).translate(x, y, z), skin);
  BODY = {
    skin: mergeGeometries([
      paint(new THREE.IcosahedronGeometry(0.016, 1).translate(0, 0.103, 0.002), skin),
      box(0.011, 0.046, 0.012, 0.008, 0.023, 0), box(0.011, 0.046, 0.012, -0.008, 0.023, 0),
      box(0.009, 0.04, 0.009, 0.025, 0.064, 0), box(0.009, 0.04, 0.009, -0.025, 0.064, 0),
    ])!,
    suit: paint(new THREE.CapsuleGeometry(0.018, 0.026, 2, 6).translate(0, 0.064, 0), 0xffffff),
  };
  return BODY;
}
const MAT = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.75, metalness: 0 });

/** A pair of instanced meshes drawing bathers: the skin in its own colours, the suit in each one's. */
export class BatherMesh {
  readonly skin: THREE.InstancedMesh;
  readonly suit: THREE.InstancedMesh;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private e = new THREE.Euler(0, 0, 0, 'YXZ');
  private p = new THREE.Vector3();
  private s = new THREE.Vector3(1, 1, 1);
  private c = new THREE.Color();
  private cols: number[] = [];
  private tones: number[] = [];
  n = 0;

  constructor(parent: THREE.Object3D, readonly max: number) {
    const b = batherBody();
    this.skin = new THREE.InstancedMesh(b.skin, MAT, max);
    this.suit = new THREE.InstancedMesh(b.suit, MAT, max);
    for (const im of [this.skin, this.suit]) { im.count = 0; im.frustumCulled = false; parent.add(im); }
    for (let i = 0; i < max; i++) {
      this.skin.setColorAt(i, this.c.setHex(0xffffff));
      this.suit.setColorAt(i, this.c.setHex(0xffffff));
    }
  }

  begin(): void { this.n = 0; }
  /** One bather: feet at (x, y, z), turned `yaw` (0 faces +z), tipped forward `pitch`, in these colours. */
  put(x: number, y: number, z: number, yaw: number, pitch: number, suit: number, skin: number, roll = 0): void {
    if (this.n >= this.max) return;
    const i = this.n++;
    this.q.setFromEuler(this.e.set(pitch, yaw, roll, 'YXZ'));
    this.m.compose(this.p.set(x, y, z), this.q, this.s);
    this.skin.setMatrixAt(i, this.m);
    this.suit.setMatrixAt(i, this.m);
    if (this.cols[i] !== suit) { this.cols[i] = suit; this.suit.setColorAt(i, this.c.setHex(suit)); this.suit.instanceColor!.needsUpdate = true; }
    if (this.tones[i] !== skin) { this.tones[i] = skin; this.skin.setColorAt(i, this.c.setHex(skin)); this.skin.instanceColor!.needsUpdate = true; }
  }
  end(): void {
    for (const im of [this.skin, this.suit]) { im.count = this.n; im.instanceMatrix.needsUpdate = true; }
  }
  dispose(): void { for (const im of [this.skin, this.suit]) { im.removeFromParent(); im.dispose(); } }
}

/** Splashes: little white bursts where someone hits the water, growing and sinking away. */
export class Splashes {
  readonly mesh: THREE.InstancedMesh;
  private list: { x: number; y: number; z: number; t: number; big: number }[] = [];
  private m = new THREE.Matrix4();
  constructor(parent: THREE.Object3D, private max = 24) {
    const g = new THREE.IcosahedronGeometry(0.05, 1);
    this.mesh = new THREE.InstancedMesh(g, new THREE.MeshStandardMaterial({ color: 0xf4fbfc, roughness: 0.3, transparent: true, opacity: 0.85, depthWrite: false }), max);
    this.mesh.count = 0;
    this.mesh.frustumCulled = false;
    parent.add(this.mesh);
  }
  add(x: number, y: number, z: number, big = 1): void {
    if (this.list.length >= this.max) this.list.shift();
    this.list.push({ x, y, z, t: 0, big });
  }
  update(dt: number): void {
    this.list = this.list.filter((s) => (s.t += dt) < 0.7);
    this.list.forEach((s, i) => {
      const k = s.t / 0.7, r = (0.4 + k * 1.1) * s.big;
      this.m.makeScale(r, (1 - k) * 1.3 * s.big + 0.05, r).setPosition(s.x, s.y + (0.02 - k * 0.04) * s.big, s.z);
      this.mesh.setMatrixAt(i, this.m);
    });
    this.mesh.count = this.list.length;
    if (this.list.length) this.mesh.instanceMatrix.needsUpdate = true;
  }
  dispose(): void { this.mesh.removeFromParent(); this.mesh.dispose(); }
}

// ---- getting about a pool ----------------------------------------------------------------------------------------

const grow = (r: Pool, e: number): Pool => ({ x0: r.x0 - e, z0: r.z0 - e, x1: r.x1 + e, z1: r.z1 + e });
const inside = (r: Pool, p: Pt) => p.x > r.x0 && p.x < r.x1 && p.z > r.z0 && p.z < r.z1;

/** Does the segment a–b pass through rectangle r (Liang–Barsky)? */
function crosses(r: Pool, a: Pt, b: Pt): boolean {
  let t0 = 0, t1 = 1;
  const dx = b.x - a.x, dz = b.z - a.z;
  const edge = (p: number, q: number): boolean => {
    if (Math.abs(p) < 1e-9) return q >= 0;
    const t = q / p;
    if (p < 0) { if (t > t1) return false; if (t > t0) t0 = t; } else { if (t < t0) return false; if (t < t1) t1 = t; }
    return true;
  };
  return edge(-dx, a.x - r.x0) && edge(dx, r.x1 - a.x) && edge(-dz, a.z - r.z0) && edge(dz, r.z1 - a.z) && t1 - t0 > 1e-6;
}

/** A way along the deck from a to b, round the pool's corners when the straight line would be wet. */
function deckWay(plan: LidoPlan, a: Pt, b: Pt): Pt[] {
  const E = grow(plan.pool, 0.075);
  if (!crosses(E, a, b)) return [b];
  const C: Pt[] = [{ x: E.x0, z: E.z0 }, { x: E.x1, z: E.z0 }, { x: E.x1, z: E.z1 }, { x: E.x0, z: E.z1 }];
  const near = (p: Pt) => C.reduce((best, c, i) => (Math.hypot(c.x - p.x, c.z - p.z) < Math.hypot(C[best].x - p.x, C[best].z - p.z) ? i : best), 0);
  const ia = near(a), ib = near(b);
  const ring = (dir: number) => { const out: Pt[] = []; for (let i = ia; ; i = (i + dir + 4) % 4) { out.push(C[i]); if (i === ib) break; } return out; };
  const len = (pts: Pt[]) => pts.reduce((s, p, i) => s + Math.hypot(p.x - (i ? pts[i - 1].x : a.x), p.z - (i ? pts[i - 1].z : a.z)), 0);
  const cw = ring(1), ccw = ring(-1);
  return [...(len(cw) <= len(ccw) ? cw : ccw), b];
}

/** The nearest place on the main pool's edge to p: a step out on the rim, and a stroke in in the water. */
function edgeNear(plan: LidoPlan, p: Pt): { rim: Pt; water: Pt; yaw: number } {
  const r = plan.pool;
  const x = Math.min(r.x1 - 0.05, Math.max(r.x0 + 0.05, p.x)), z = Math.min(r.z1 - 0.05, Math.max(r.z0 + 0.05, p.z));
  const d = [p.x - r.x0, r.x1 - p.x, p.z - r.z0, r.z1 - p.z].map((v) => Math.abs(v));
  // whichever side p is beyond (or nearest to)
  const out = [r.x0 - p.x, p.x - r.x1, r.z0 - p.z, p.z - r.z1];
  let s = out.indexOf(Math.max(...out));
  if (Math.max(...out) <= 0) s = d.indexOf(Math.min(...d));
  switch (s) {
    case 0: return { rim: { x: r.x0 - 0.035, z }, water: { x: r.x0 + 0.06, z }, yaw: Math.PI / 2 };
    case 1: return { rim: { x: r.x1 + 0.035, z }, water: { x: r.x1 - 0.06, z }, yaw: -Math.PI / 2 };
    case 2: return { rim: { x, z: r.z0 - 0.035 }, water: { x, z: r.z0 + 0.06 }, yaw: 0 };
    default: return { rim: { x, z: r.z1 + 0.035 }, water: { x, z: r.z1 - 0.06 }, yaw: Math.PI };
  }
}

function deckPoint(plan: LidoPlan): Pt {
  const r = plan.deck[Math.floor(Math.random() * plan.deck.length)];
  return { x: rand(r.x0, r.x1), z: rand(r.z0, r.z1) };
}

// ---- a lido's day ---------------------------------------------------------------------------------------------------

type Act = 'walk' | 'lie' | 'sit' | 'swim' | 'tread' | 'queue' | 'climb' | 'board' | 'fly' | 'slide' | 'gone';
type Then = 'lie' | 'sit' | 'swim' | 'queue' | 'gone' | 'choose';

/** A board or the slides' stair: where a line forms, and whose turn it is. */
interface Station {
  kind: 'board' | 'slide';
  /** Which board, or which of the slides (they take turns off the one stair). */
  i: number;
  foot: Pt; top: P3;
  back: Pt;
  line: Bather[];
  /** The clock time the next one may go up; Infinity while someone is up there. */
  next: number;
  max: number;
}

interface Bather {
  act: Act;
  x: number; y: number; z: number; yaw: number; pitch: number; roll: number;
  path: Pt[]; then: Then;
  timer: number;
  /** Lengths still to swim; where it is swimming to. */
  laps: number; goal: Pt | null; inRound: number;
  station: Station | null;
  /** Climbing, on a board, sliding: from where, how far through, how fast. */
  from: P3; s: number; v: number; vx: number; vz: number; vy: number;
  dive: number; spin: number;
  lounger: number;
  stay: number;
  suit: number; skin: number;
  speed: number; phase: number;
  leaving: boolean;
}

interface Lido {
  b: Building;
  plan: LidoPlan;
  f: { ox: number; oy: number; oz: number; c: number; s: number; yaw: number };
  cap: number;
  want: number;
  bathers: Bather[];
  stations: Station[];
  taken: boolean[];
  spawn: number;
  slideTurn: number;
}

const CAP: Record<TownKind, number> = { rural: 7, suburb: 12, city: 16, metro: 20, mega: 24 };
/** Most bathers an island draws. */
const MAX_BATHERS = 220;
/** Game hours the pools are open, and the gravity a diver falls by (world units a second², the scale's own). */
const OPEN = 9, CLOSE = 19.5, G = 0.7;
const SWIM = 0.11;

export class PoolLife {
  private lidos: Lido[] = [];
  private mesh: BatherMesh;
  private splash: Splashes;
  private time = 0;
  private check = 0;
  private warm = 0;
  budget = 1;

  constructor(parent: THREE.Object3D) {
    this.mesh = new BatherMesh(parent, MAX_BATHERS + 8);
    this.splash = new Splashes(parent);
  }

  setSeason(warm: number): void { this.warm = warm; }

  setWorld(w: World | null): void {
    this.lidos = [];
    if (!w) return;
    for (const t of w.towns) for (const b of t.buildings) {
      if (b.kind !== 'lido' || b.gone) continue;
      const plan = lidoPlanOf(b), f = lidoFrame(b);
      const stations: Station[] = [];
      plan.boards.forEach((bd, i) => stations.push({ kind: 'board', i, foot: bd.foot, top: bd.top, back: away(bd.foot, bd.top), line: [], next: 0, max: 3 }));
      if (plan.slides.length) {
        const s = plan.slides[0];
        stations.push({ kind: 'slide', i: 0, foot: s.foot, top: s.top, back: away(s.foot, s.top), line: [], next: 0, max: 5 });
      }
      this.lidos.push({
        b, plan, f: { ox: f.ox, oy: f.oy, oz: f.oz, c: Math.cos(f.yaw), s: Math.sin(f.yaw), yaw: f.yaw },
        cap: CAP[t.kind], want: 0, bathers: [], stations, taken: plan.loungers.map(() => false), spawn: 0, slideTurn: 0,
      });
    }
  }

  /** How many are about, for the console. */
  get counts(): { lidos: number; bathers: number } { return { lidos: this.lidos.length, bathers: this.lidos.reduce((s, l) => s + l.bathers.length, 0) }; }
  /** Where the lidos are, for looking at them from the console. */
  get where(): { x: number; z: number; model: number; want: number; n: number }[] {
    return this.lidos.map((l) => ({ x: l.f.ox, z: l.f.oz, model: l.plan.model, want: l.want, n: l.bathers.length }));
  }

  update(dt: number, hour: number): void {
    if (!this.lidos.length) return;
    this.time += dt;
    this.check -= dt;
    // the water is in from spring to autumn; the hall's roof is open in summer
    const water = VIS.uVis.value[Vis.NotWinter] > 0.5, open = VIS.uVis.value[Vis.Summer] > 0.5;
    if (this.check <= 0) {
      this.check = 2;
      const day = clamp01((hour - OPEN) / 1.5) * clamp01((CLOSE - hour) / 1.5) * (0.55 + 0.45 * clamp01((hour - 11) / 2.5));
      const season = 0.3 + 0.7 * this.warm;
      for (const l of this.lidos) {
        const seen = l.plan.roofed ? open : water;
        l.want = MEETS.has(l.b) || !seen ? 0 : Math.round(l.cap * this.budget * day * season);
        // the water gone (the season turned) or the roof shut: nobody is left standing in an empty pool
        if (!seen) { this.clear(l); continue; }
        let over = l.bathers.filter((p) => !p.leaving).length - l.want;
        for (let i = l.bathers.length - 1; i >= 0 && over > 0; i--) if (!l.bathers[i].leaving) { l.bathers[i].leaving = true; over--; }
      }
    }
    this.mesh.begin();
    let total = 0;
    for (const l of this.lidos) {
      const n = l.bathers.filter((p) => !p.leaving).length;
      l.spawn -= dt;
      if (n < l.want && l.spawn <= 0 && total + l.bathers.length < MAX_BATHERS) { l.spawn = rand(0.8, 2.2); this.arrive(l); }
      for (const p of l.bathers) this.step(l, p, dt, hour);
      l.bathers = l.bathers.filter((p) => p.act !== 'gone');
      total += l.bathers.length;
      for (const p of l.bathers) this.draw(l, p);
      // the lifeguard, up on the chair while it is open
      const g = l.plan.guard;
      if (g && l.want > 0) {
        const yaw = Math.atan2((l.plan.pool.x0 + l.plan.pool.x1) / 2 - g[0], (l.plan.pool.z0 + l.plan.pool.z1) / 2 - g[2]);
        this.put(l, g[0], g[1] - 0.035, g[2], yaw, -0.1, 0xe2412f, SKIN[l.b.seed % SKIN.length]);
      }
    }
    this.mesh.end();
    this.splash.update(dt);
  }

  private clear(l: Lido): void {
    l.bathers = [];
    for (const s of l.stations) { s.line = []; s.next = 0; }
    l.taken.fill(false);
  }

  /** Someone out of the changing rooms for the afternoon. */
  private arrive(l: Lido): void {
    const d = l.plan.door;
    const p: Bather = {
      act: 'walk', x: d.x, y: 0, z: d.z, yaw: -Math.PI / 2, pitch: 0, roll: 0, path: [], then: 'choose', timer: 0,
      laps: 0, goal: null, inRound: -1, station: null, from: [0, 0, 0], s: 0, v: 0, vx: 0, vz: 0, vy: 0, dive: 0, spin: 0,
      lounger: -1, stay: rand(70, 240), suit: SUITS[Math.floor(Math.random() * SUITS.length)], skin: SKIN[Math.floor(Math.random() * SKIN.length)],
      speed: rand(0.22, 0.32), phase: Math.random() * 6, leaving: false,
    };
    this.choose(l, p);
    l.bathers.push(p);
  }

  /** What next: a swim, a lounger, the rim, the boards, the slides; or home. */
  private choose(l: Lido, p: Bather): void {
    const plan = l.plan;
    if (p.lounger >= 0) { l.taken[p.lounger] = false; p.lounger = -1; }
    if (p.leaving || p.stay <= 0) { p.leaving = true; this.walkTo(l, p, plan.door, 'gone'); return; }
    const free = l.taken.map((t, i) => (t ? -1 : i)).filter((i) => i >= 0);
    const stations = l.stations.filter((s) => s.line.length < s.max);
    const w = { swim: 4, lie: free.length ? 2.5 : 0, sit: 1.5, queue: stations.length ? (stations.some((s) => s.kind === 'slide') ? 4 : 3) : 0 };
    let r = Math.random() * (w.swim + w.lie + w.sit + w.queue);
    if ((r -= w.swim) < 0) {
      const e = edgeNear(plan, { x: rand(plan.pool.x0, plan.pool.x1), z: rand(plan.pool.z0, plan.pool.z1) });
      p.goal = e.water;
      this.walkTo(l, p, e.rim, 'swim');
    } else if ((r -= w.lie) < 0) {
      p.lounger = free[Math.floor(Math.random() * free.length)];
      l.taken[p.lounger] = true;
      const lo = plan.loungers[p.lounger];
      this.walkTo(l, p, { x: lo.x, z: lo.z }, 'lie');
    } else if ((r -= w.sit) < 0) {
      const e = edgeNear(plan, deckPoint(plan));
      this.walkTo(l, p, e.rim, 'sit');
      p.goal = e.water;
      p.timer = e.yaw;
    } else {
      const s = stations[Math.floor(Math.random() * stations.length)];
      p.station = s;
      s.line.push(p);
      this.walkTo(l, p, this.linePlace(s, s.line.length - 1), 'queue');
    }
  }

  private linePlace(s: Station, k: number): Pt { return { x: s.foot.x + s.back.x * k * 0.065, z: s.foot.z + s.back.z * k * 0.065 }; }

  private walkTo(l: Lido, p: Bather, to: Pt, then: Then): void {
    p.act = 'walk';
    p.then = then;
    p.path = deckWay(l.plan, p, to);
    p.y = 0;
    p.pitch = 0;
  }

  private step(l: Lido, p: Bather, dt: number, hour: number): void {
    const plan = l.plan;
    p.stay -= dt;
    p.phase += dt;
    // closing time, or a meet: out of the water and home (the ones up a ladder come down the way they went)
    const hurry = p.leaving && (hour >= CLOSE || MEETS.has(l.b)) ? 1.8 : 1;
    switch (p.act) {
      case 'walk': {
        const t = p.path[0];
        if (!t) { this.arrived(l, p); break; }
        const dx = t.x - p.x, dz = t.z - p.z, d = Math.hypot(dx, dz), step = p.speed * hurry * dt;
        if (d <= step) { p.x = t.x; p.z = t.z; p.path.shift(); if (!p.path.length) this.arrived(l, p); break; }
        p.x += (dx / d) * step; p.z += (dz / d) * step;
        p.yaw = Math.atan2(dx, dz);
        p.y = Math.abs(Math.sin(p.phase * 9)) * 0.008 + (inside(grow(plan.pool, 0.065), p) ? RIM_Y : 0);
        break;
      }
      case 'lie':
        if ((p.timer -= dt) <= 0 || p.leaving) this.choose(l, p);
        break;
      case 'sit':
        if ((p.s -= dt) <= 0 || p.leaving) {
          // most slip in off the rim
          if (!p.leaving && Math.random() < 0.6 && p.goal) { this.enter(l, p, p.goal); break; }
          this.choose(l, p);
        }
        break;
      case 'tread':
        p.y = plan.wy - 0.085 + Math.sin(p.phase * 2) * 0.004;
        if ((p.timer -= dt) <= 0 || p.leaving) p.act = 'swim';
        break;
      case 'swim': this.swim(l, p, dt * hurry); break;
      case 'queue': {
        const s = p.station!;
        const k = s.line.indexOf(p);
        const at = this.linePlace(s, Math.max(0, k));
        p.x += (at.x - p.x) * Math.min(1, dt * 3); p.z += (at.z - p.z) * Math.min(1, dt * 3);
        p.yaw = Math.atan2(s.foot.x - p.x - s.back.x * 0.01, s.foot.z - p.z - s.back.z * 0.01);
        if (p.leaving) { s.line.splice(k, 1); p.station = null; this.choose(l, p); break; }
        if (k === 0 && this.time >= s.next && Math.hypot(at.x - p.x, at.z - p.z) < 0.02) {
          s.line.shift();
          s.next = Infinity;
          p.act = 'climb';
          p.from = [p.x, 0, p.z];
          p.s = 0;
          p.v = 1 / (s.kind === 'slide' ? 2.6 : 0.8 + s.top[1] * 2.2);
        }
        break;
      }
      case 'climb': {
        const s = p.station!;
        p.s = Math.min(1, p.s + p.v * dt);
        p.x = p.from[0] + (s.top[0] - p.from[0]) * p.s;
        p.z = p.from[2] + (s.top[2] - p.from[2]) * p.s;
        p.y = s.top[1] * p.s;
        p.yaw = Math.atan2(s.top[0] - p.from[0], s.top[2] - p.from[2]);
        if (p.s >= 1) {
          if (s.kind === 'slide') {
            const which = plan.slides.length > 1 ? (l.slideTurn++ % plan.slides.length) : 0;
            p.act = 'slide';
            p.s = 0; p.v = 0.15; p.dive = which;
            s.next = this.time + 1.6;
          } else {
            p.act = 'board';
            p.s = 0;
            p.timer = plan.boards[s.i].spring ? 1.6 : 0.6;
          }
        }
        break;
      }
      case 'board': {
        const s = p.station!, bd = plan.boards[s.i];
        const walk = 0.55;
        p.s += dt;
        const k = Math.min(1, p.s / walk);
        p.x = bd.top[0] + (bd.tip[0] - bd.top[0]) * k;
        p.z = bd.top[2] + (bd.tip[2] - bd.top[2]) * k;
        p.yaw = Math.atan2(bd.tip[0] - bd.top[0], bd.tip[2] - bd.top[2]);
        // a springboard: two bounces on the end
        p.y = bd.tip[1] + (bd.spring && p.s > walk ? Math.abs(Math.sin((p.s - walk) * Math.PI * 2.4)) * 0.04 : 0);
        if (p.s >= walk + p.timer) {
          const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw), push = bd.spring ? 0.16 : 0.1;
          p.act = 'fly';
          p.vx = fx * push; p.vz = fz * push; p.vy = bd.spring ? 0.42 : 0.18;
          // a dive, a pencil jump, or (off the platform, now and then) a somersault
          const r = Math.random();
          p.dive = r < 0.55 ? 1 : 0;
          p.spin = !bd.spring && r > 0.85 ? 1 : 0;
          p.pitch = 0;
          s.next = this.time + 0.9;
        }
        break;
      }
      case 'fly': {
        p.vy -= G * dt;
        p.x += p.vx * dt; p.z += p.vz * dt; p.y += p.vy * dt;
        // head first by the time it goes in, or feet first; a somersault turns all the way round as well
        const fall = clamp01(-p.vy / 0.9);
        p.pitch = p.spin ? Math.min(Math.PI * 2 + 0.2, p.pitch + dt * 7) : p.dive ? fall * 2.8 : 0.15;
        if (p.y <= plan.wy) {
          this.splashAt(l, p.x, p.z, p.dive ? 0.7 : 1);
          this.enter(l, p, { x: p.x, z: p.z }, 0);
        }
        break;
      }
      case 'slide': {
        const path = plan.slides[p.dive].path;
        // gathering speed down the drops, a little friction
        const seg = segAt(path, p.s);
        const drop = (path[seg.i][1] - path[seg.i + 1][1]) / Math.max(1e-3, seg.len);
        p.v = Math.max(0.12, Math.min(0.9, p.v + (drop * 2.2 - 0.12) * dt));
        p.s += p.v * dt;
        const at = pointAt(path, p.s);
        p.x = at.p[0]; p.y = at.p[1] + 0.03; p.z = at.p[2];
        p.yaw = Math.atan2(at.d[0], at.d[2]);
        p.pitch = -Math.PI / 2 + Math.atan2(-at.d[1], Math.hypot(at.d[0], at.d[2]));
        if (at.end) {
          this.splashAt(l, p.x, p.z, 0.8);
          const round = plan.rounds.findIndex((c) => Math.hypot(c.x - p.x, c.z - p.z) < c.r + 0.02);
          this.enter(l, p, { x: p.x, z: p.z }, 0, round);
        }
        break;
      }
    }
  }

  /** In off the rim (or the board, or the slide): a few lengths, or straight to the side again. */
  private enter(l: Lido, p: Bather, at: Pt, laps = Math.floor(rand(1, 5)), round = -1): void {
    p.act = 'swim';
    p.x = at.x; p.z = at.z;
    p.station = null;
    p.inRound = round;
    p.laps = round >= 0 ? 0 : laps;
    p.goal = null;
    p.v = SWIM * rand(0.8, 1.3);
    this.nextGoal(l, p);
  }

  private nextGoal(l: Lido, p: Bather): void {
    const plan = l.plan, r = plan.pool;
    if (p.inRound >= 0) {
      // out of the splash pool by the nearest side
      const c = plan.rounds[p.inRound], a = Math.atan2(p.z - c.z, p.x - c.x) || Math.random() * 6;
      p.goal = { x: c.x + Math.cos(a) * (c.r - 0.04), z: c.z + Math.sin(a) * (c.r - 0.04) };
      p.laps = -1;
      return;
    }
    if (p.laps <= 0 || p.leaving) { p.goal = edgeNear(plan, p).water; p.laps = -1; return; }
    p.laps--;
    // a length: to the far end along the pool's long side, staying in about the same lane
    if (plan.along === 'x') p.goal = { x: p.x < (r.x0 + r.x1) / 2 ? r.x1 - 0.07 : r.x0 + 0.07, z: Math.min(r.z1 - 0.05, Math.max(r.z0 + 0.05, p.z + rand(-0.06, 0.06))) };
    else p.goal = { z: p.z < (r.z0 + r.z1) / 2 ? r.z1 - 0.07 : r.z0 + 0.07, x: Math.min(r.x1 - 0.05, Math.max(r.x0 + 0.05, p.x + rand(-0.06, 0.06))) };
  }

  private swim(l: Lido, p: Bather, dt: number): void {
    const plan = l.plan, g = p.goal!;
    const dx = g.x - p.x, dz = g.z - p.z, d = Math.hypot(dx, dz);
    const step = p.v * dt;
    p.y = plan.wy - 0.014 + Math.sin(p.phase * 7) * 0.003;
    p.pitch = Math.PI / 2 - 0.12;
    p.roll = Math.sin(p.phase * 5) * 0.35;
    if (d > step) {
      p.x += (dx / d) * step; p.z += (dz / d) * step;
      p.yaw = Math.atan2(dx, dz);
      // now and then a breather, treading water
      if (Math.random() < dt * 0.04 && p.laps >= 0) { p.act = 'tread'; p.timer = rand(2, 6); p.pitch = 0; p.roll = 0; }
      return;
    }
    p.x = g.x; p.z = g.z;
    if (p.laps >= 0) { this.nextGoal(l, p); return; }
    // at the side: climb out onto the rim, and on to whatever is next
    p.roll = 0;
    p.pitch = 0;
    const out = p.inRound >= 0 ? (() => { const c = plan.rounds[p.inRound], a = Math.atan2(p.z - c.z, p.x - c.x); return { x: c.x + Math.cos(a) * (c.r + 0.09), z: c.z + Math.sin(a) * (c.r + 0.09) }; })() : edgeNear(plan, p).rim;
    p.x = out.x; p.z = out.z;
    p.inRound = -1;
    this.choose(l, p);
  }

  private arrived(l: Lido, p: Bather): void {
    switch (p.then) {
      case 'gone': p.act = 'gone'; if (p.station) { p.station.line.splice(p.station.line.indexOf(p), 1); p.station = null; } break;
      case 'lie': {
        const lo = l.plan.loungers[p.lounger];
        p.act = 'lie'; p.timer = rand(20, 70);
        if (lo) { p.yaw = lo.yaw + (Math.random() < 0.5 ? Math.PI : 0); p.x = lo.x + Math.sin(p.yaw) * 0.065; p.z = lo.z + Math.cos(p.yaw) * 0.065; }
        p.pitch = -Math.PI / 2; p.y = 0.058;
        break;
      }
      case 'sit': p.act = 'sit'; p.yaw = p.timer; p.s = rand(12, 40); p.y = RIM_Y - 0.045; p.pitch = -0.12; break;
      case 'swim': this.enter(l, p, p.goal ?? edgeNear(l.plan, p).water); break;
      case 'queue': p.act = 'queue'; break;
      default: this.choose(l, p);
    }
  }

  private splashAt(l: Lido, x: number, z: number, big: number): void {
    const q = this.island(l, x, z);
    this.splash.add(q.x, l.f.oy + l.plan.wy, q.z, big);
  }

  private island(l: Lido, x: number, z: number): Pt { return { x: l.f.ox + x * l.f.c + z * l.f.s, z: l.f.oz - x * l.f.s + z * l.f.c }; }

  private put(l: Lido, x: number, y: number, z: number, yaw: number, pitch: number, suit: number, skin: number, roll = 0): void {
    const q = this.island(l, x, z);
    this.mesh.put(q.x, l.f.oy + y, q.z, yaw + l.f.yaw, pitch, suit, skin, roll);
  }

  private draw(l: Lido, p: Bather): void {
    let { x, z } = p;
    const y = p.y;
    // lying down (swimming, sunbathing, sliding) the body runs from the feet along its length: put its middle here
    if (p.act === 'swim' || p.act === 'lie') {
      const back = p.act === 'swim' ? -0.055 : 0;
      x += Math.sin(p.yaw) * back; z += Math.cos(p.yaw) * back;
    }
    this.put(l, x, y, z, p.yaw, p.pitch, p.suit, p.skin, p.roll);
  }

  dispose(): void { this.lidos = []; this.mesh.dispose(); this.splash.dispose(); }
}

/** The way back along a line from the foot of a ladder, away from what it climbs. */
function away(foot: Pt, top: P3): Pt {
  const dx = foot.x - top[0], dz = foot.z - top[2], d = Math.hypot(dx, dz);
  return d > 1e-3 ? { x: dx / d, z: dz / d } : { x: 0, z: 1 };
}

/** The segment of a path s along it, and that segment's length. */
function segAt(path: P3[], s: number): { i: number; len: number } {
  for (let i = 0; i < path.length - 1; i++) {
    const a = path[i], b = path[i + 1], len = Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
    if (s <= len || i === path.length - 2) return { i, len };
    s -= len;
  }
  return { i: 0, len: 1 };
}

/** The point s along a path, its direction, and whether that is the end. */
function pointAt(path: P3[], s: number): { p: P3; d: P3; end: boolean } {
  for (let i = 0; i < path.length - 1; i++) {
    const a = path[i], b = path[i + 1], len = Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2]) || 1e-3;
    const d: P3 = [(b[0] - a[0]) / len, (b[1] - a[1]) / len, (b[2] - a[2]) / len];
    if (s <= len) { const t = s / len; return { p: [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t], d, end: false }; }
    s -= len;
    if (i === path.length - 2) return { p: b, d, end: true };
  }
  return { p: path[path.length - 1], d: [0, -1, 0], end: true };
}
