/** A blocky crow perched on (x, y, z), looking toward `yaw`. */
function crow(k: Kit, x: number, y: number, z: number, yaw: number): void {
  const f = frame([x, y, z], yaw);
  fbox(k, f, 0, 0.0, 0, 0.04, 0.045, 0.08, BLACK);
  fbox(k, f, 0, 0.035, 0.045, 0.035, 0.035, 0.035, BLACK);
  fbox(k, f, 0, 0.045, 0.072, 0.012, 0.012, 0.025, hex(0x6a6a62));
  fbox(k, f, 0, 0.015, -0.055, 0.03, 0.012, 0.05, BLACK);
}

