/** Beehives: two rows of painted stacked boxes on their stands, wildflowers round them, a shed and a honey table at the gate. */
const apiary: Draw = (k, _W, _D, _b, r) => {
  const HIVES = [WHITE, hex(0xf2e2a0), hex(0xbcd8e8), hex(0xe8c2c8), hex(0xc8e0b8), hex(0xf0d0a0)];
  const spots: [number, number][] = [];
  for (const hz of [-0.38, 0.08]) for (const hx of [-0.7, -0.35, 0.0]) spots.push([hx, hz]);
  for (const [hx, hz] of spots) {
    k.box(hx, 0, hz, 0.2, 0.045, 0.18, DARK_WOOD);
    const n = 2 + Math.floor(r() * 2), col = HIVES[Math.floor(r() * HIVES.length)];
    let y = 0.045;
    for (let i = 0; i < n; i++) {
      const c = i % 2 ? scale(col, 0.93) : col, h = i === 0 ? 0.075 : 0.06;
      k.box(hx, y, hz, 0.16 + (i % 2) * 0.008, h, 0.14 + (i % 2) * 0.008, c);
      y += h;
    }
    k.box(hx, y, hz, 0.19, 0.025, 0.17, hex(0x8a8e92), hex(0xa8acb0));
    k.box(hx, 0.05, hz + 0.074, 0.08, 0.012, 0.012, GAP);
    k.box(hx, 0.045, hz + 0.1, 0.1, 0.008, 0.04, PLANK3);
  }
  // the shed at the back, and the honey table by the gate with its jars and sign
  const sx = 0.62, sz = -0.55;
  k.box(sx, 0, sz, 0.36, 0.22, 0.3, hex(0x7a8a5a));
  k.gable(sx, 0.22, sz, 0.42, 0.1, 0.36, hex(0x6a4a3a), hex(0x7a8a5a));
  k.box(sx - 0.05, 0, sz + 0.154, 0.1, 0.17, 0.012, DARK_WOOD);
  k.pane(sx + 0.1, 0.1, sz + 0.15, 0.07, 0.06, 1, hex(0x3a4650), EVENING, WARM_GLOW);
  const tx = 0.55, tz = 0.55;
  k.box(tx, 0.1, tz, 0.4, 0.02, 0.16, PLANK, PLANK3);
  for (const [lx, lz] of [[-1, -1], [1, -1], [1, 1], [-1, 1]] as const) k.box(tx + lx * 0.18, 0, tz + lz * 0.06, 0.02, 0.1, 0.02, DARK_WOOD);
  for (let i = 0; i < 6; i++) {
    const jx = tx - 0.15 + i * 0.06, jz = tz + (i % 2 ? 0.03 : -0.03);
    k.cyl(jx, 0.12, jz, 0.018, 0.035, hex(0xe0961c), 6);
    k.cyl(jx, 0.155, jz, 0.019, 0.008, [RED, CREAM, YELLOW][i % 3], 6);
  }
  for (const s of [-1, 1]) k.box(tx + s * 0.12, 0, tz + 0.12, 0.018, 0.24, 0.018, DARK_WOOD);
  k.box(tx, 0.17, tz + 0.12, 0.3, 0.07, 0.016, YELLOW);
  k.box(tx, 0.19, tz + 0.13, 0.2, 0.03, 0.006, DARK);
  // the wildflowers, anywhere the hives, the shed and the table leave room
  const FLOWERS = [PURPLE, YELLOW, WHITE, PINK, BLUE, ORANGE, hex(0xd84a4a)];
  const clear = (x: number, z: number) =>
    spots.some(([hx, hz]) => Math.abs(x - hx) < 0.15 && Math.abs(z - hz) < 0.17) ||
    (Math.abs(x - sx) < 0.26 && Math.abs(z - sz) < 0.24) || (Math.abs(x - tx) < 0.27 && Math.abs(z - tz) < 0.2);
  let drawn = 0;
  for (let i = 0; i < 160 && drawn < 70; i++) {
    const x = (r() - 0.5) * 1.86, z = (r() - 0.5) * 1.86;
    if (clear(x, z)) continue;
    drawn++;
    const h = 0.02 + r() * 0.035;
    k.box(x, 0, z, 0.035, h, 0.035, scale(LEAF2, 0.9 + r() * 0.2));
    k.box(x, h, z, 0.03, 0.014, 0.03, FLOWERS[Math.floor(r() * FLOWERS.length)]);
  }
};

