/**
 * Blueprints (docs/blueprints.html): the rules the game and the server both hold a construction to. A fleet that
 * owns a building holds its plans, and may pay to put up a copy — an `erect` edit on the county's log (world/erect.ts).
 * The server can't price a lot or judge a town's lines, but it can check a lot's shape and that the hours a fleet
 * claims for it are the formula's.
 */

/** The biggest lot a blueprint takes, tiles a side. */
export const ERECT_MAX_SIDE = 8;
/**
 * The most storeys a copy may claim: past every building the world makes (the tallest towers have 108), so any
 * blueprint can be built (the user, 6 Nov 2026: a 58-storey tower was refused at 40); only a sanity bound for the server.
 */
export const ERECT_MAX_FLOORS = 400;
/** Constructions one island takes, standing or razed: each is a real building with a site of its own. */
export const ERECT_MAX = 48;
/** How many `erect` edits a county's log holds online, across every fleet, before the server refuses more. */
export const ERECT_LOG_MAX = 200;
/** What a new building costs over what buying the same one in the county would (the user, 3 Nov 2026: +50%). */
export const ERECT_MARKUP = 1.5;
/** Real seconds after breaking ground in which cancelling pays everything back; after that, half; once built, nothing. */
export const ERECT_GRACE_S = 10;

/**
 * How long a copy takes to go up, in game hours (25 s each): three for a cottage, up to ten for a tower.
 * The town's own buildings keep their two (render/townMesh.ts BUILD_HOURS).
 */
export function erectHours(w: number, d: number, floors: number): number {
  const h = 2 + 0.5 * Math.max(1, floors) + (w * d) / 6;
  return Math.round(Math.min(10, Math.max(3, h)) * 10) / 10;
}

/**
 * Why an `erect` edit is malformed, or null when it is well made: a kind of letters, an integer lot inside a cell, a
 * facing, storeys, a seed, a style of letters, solid or not, and the hours the formula gives that lot. The server's
 * check, shared so the gate can run it.
 */
export function erectShapeProblem(e: unknown): string | null {
  if (!e || typeof e !== 'object') return 'not an edit';
  const { kind, x, z, w, d, f, fl, seed, st, solid, hrs } = e as Record<string, unknown>;
  if (typeof kind !== 'string' || !/^[a-zA-Z]{1,32}$/.test(kind)) return 'kind';
  if (![x, z, w, d, f, fl].every((v) => Number.isInteger(v))) return 'lot';
  const X = x as number, Z = z as number, W = w as number, D = d as number;
  if (X < 0 || Z < 0 || W < 1 || D < 1 || W > ERECT_MAX_SIDE || D > ERECT_MAX_SIDE || X + W > 256 || Z + D > 256) return 'lot';
  if ((f as number) < 0 || (f as number) > 3) return 'facing';
  if ((fl as number) < 1 || (fl as number) > ERECT_MAX_FLOORS) return 'storeys';
  if (!Number.isInteger(seed)) return 'seed';
  if (st !== undefined && (typeof st !== 'string' || !/^[a-zA-Z]{1,20}$/.test(st))) return 'style';
  if (solid !== 0 && solid !== 1) return 'solid';
  if (typeof hrs !== 'number' || Math.abs(hrs - erectHours(W, D, fl as number)) > 0.051) return 'hours';
  return null;
}
