import { hex, mix, scale, type RGB } from '../../world/biomes';
import { FLOOR } from '../../world/towns';
import type { ThemeKind } from '../../world/tiles';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { DARK, GLASS_LIGHT, METAL, NEON_HOURS, TAU, TRUNK, WARM_GLOW, WATER, WOOD, type Draw, type Kit, type P3 } from './kit';

/**
 * The signature buildings of three genre towns, each in a fixed palette of its own (the town styles
 * they stand in are free to be anything):
 *
 * - **Steampunk**: the clockwork tower with its turning brass gears, the boiler works under a forest of
 *   chimneys, and the sky dock with an airship riding at its mooring mast.
 * - **Solarpunk**: the garden tower, planted on every balcony; the solar plaza under its photovoltaic
 *   trees; and the glass domes of the biome conservatory.
 * - **Cyberpunk**: the megablock, a whole district in one slab; the corporate spire with a hologram
 *   turning near its top; and the night market, dull by day and all neon after dark.
 */

// ---- palettes ----
const BRICK_D = hex(0x5a2e28), BRICK_M = hex(0x7a3e30), IRON = hex(0x3e3c3e), IRON_L = hex(0x5a5658), BRASS = hex(0xc9a040), BRASS_D = hex(0x8a6a2a);
const COPPER = hex(0xb5673a), COPPER_D = hex(0x8a4a2a), VERDIGRIS = hex(0x5fae9a), SLATE = hex(0x4a4c54), CINDER = hex(0x5e5850), COAL = hex(0x26262a);
const STEAM = hex(0xf0f0ee), SMOKE = hex(0xb8b4b0), AMBER = hex(0xffa63c), FURNACE = hex(0xff7a22), OCHRE = hex(0xc99a3e), FIN = hex(0x9a3e2e), ROPE = hex(0xb8a070);
const SOL_WHITE = hex(0xf2f1ea), TIMBER = hex(0xb98a55), SOLAR = hex(0x2f6fb8), SOLAR2 = hex(0x3d86cf), PLAZA = hex(0xd9d4c8), GLASS_PALE = hex(0xcfe8dc), FRAME = hex(0x8fb0a4);
const GREENS = [0x4f9a4a, 0x6bb055, 0x3f8552, 0x86b84a, 0x2f7a4a];
const BLOCK = hex(0x25272d), BLOCK_L = hex(0x32363e), BLOCK_ROOF = hex(0x1c1d22), GLASS_BLACK = hex(0x151a22), WET = hex(0x2c2e33), PUDDLE = hex(0x1b1f26);
const MAGENTA = hex(0xff2e9a), CYAN = hex(0x22e0ff), NEON_AMBER = hex(0xffa020), HOLO = hex(0xa8f0ff), HOLO_PINK = hex(0xff9ae0), HOLO_DAY = hex(0xaebcc4);
const NEONS = [0xff2e9a, 0x22e0ff, 0xffa020, 0x5aff7a, 0x9a5aff, 0xff3040];
const GREY = hex(0x55585c);

const OFF: Sched = [99, 0, 0], EVENING: Sched = [18, 23.5, 1.4], ALL_NIGHT: Sched = [16.5, 31, 1.15], BEACON: Sched = [0, 36, 2.8];

const any = (r: Rng, a: readonly number[]): RGB => hex(a[Math.floor(r() * a.length)]);
/** A neon colour as its tube looks unlit: mostly grey. */
const dull = (c: RGB): RGB => mix(c, GREY, 0.62);

// ---- shared shapes ----

type Axis = 'x' | 'y' | 'z';
/** A point (u, v) across an axis and t along it. */
const onAxis = (axis: Axis, u: number, v: number, t: number): P3 => (axis === 'z' ? [u, v, t] : axis === 'x' ? [t, v, u] : [u, t, v]);

/**
 * A shape turned about any axis through (x, y, z): `prof` is [distance along the axis, radius] from one
 * end to the other. Boilers, airship envelopes and the rims of gears, which the kit's upright cylinders
 * cannot lie down to make.
 */
function lathe(k: Kit, x: number, y: number, z: number, axis: Axis, prof: readonly (readonly [number, number])[], seg: number, col: RGB | ((ring: number, s: number) => RGB)): void {
  const at = (t: number, rad: number, a: number): P3 => { const p = onAxis(axis, Math.cos(a) * rad, Math.sin(a) * rad, t); return [x + p[0], y + p[1], z + p[2]]; };
  const c = (i: number, s: number): RGB => (typeof col === 'function' ? col(i, s) : col);
  for (let i = 0; i < prof.length - 1; i++) {
    const [t0, r0] = prof[i], [t1, r1] = prof[i + 1], I = at((t0 + t1) / 2, 0, 0);
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
      if (r0 < 1e-4) k.tri(at(t0, 0, 0), at(t1, r1, a0), at(t1, r1, a1), c(i, s), I);
      else if (r1 < 1e-4) k.tri(at(t0, r0, a0), at(t0, r0, a1), at(t1, 0, 0), c(i, s), I);
      else k.quad(at(t0, r0, a0), at(t0, r0, a1), at(t1, r1, a1), at(t1, r1, a0), c(i, s), I);
    }
  }
  for (const [i, dir] of [[0, 1], [prof.length - 1, -1]] as const) {
    const [t, rad] = prof[i];
    if (rad < 1e-4) continue;
    for (let s = 0; s < seg; s++) k.tri(at(t, 0, 0), at(t, rad, (s / seg) * TAU), at(t, rad, ((s + 1) / seg) * TAU), c(i, s), at(t + dir * 0.05, 0, 0));
  }
}

/** A brass cog on a face, turning about `axis`: a disc with teeth round its rim, a dark web and a bright hub and spokes. */
function cog(k: Kit, x: number, y: number, z: number, axis: 'x' | 'z', R: number, speed: number, col: RGB = BRASS): void {
  const teeth = Math.max(6, Math.round(R * 34)), t = 0.028;
  k.spin(x, y, z, axis, speed, (s) => {
    lathe(s, 0, 0, 0, axis, [[-t, R * 0.86], [t, R * 0.86]], 12, col);
    for (let i = 0; i < teeth; i++) {
      const a = (i / teeth) * TAU, cx = Math.cos(a), sy = Math.sin(a);
      s.bar(onAxis(axis, cx * R * 0.8, sy * R * 0.8, 0), onAxis(axis, cx * R * 1.08, sy * R * 1.08, 0), t * 0.85, col);
    }
    lathe(s, 0, 0, 0, axis, [[-t - 0.008, R * 0.64], [t + 0.008, R * 0.64]], 10, scale(col, 0.5));
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * Math.PI, cx = Math.cos(a) * R * 0.62, sy = Math.sin(a) * R * 0.62;
      s.bar(onAxis(axis, cx, sy, 0), onAxis(axis, -cx, -sy, 0), Math.min(t + 0.014, R * 0.16), col);
    }
    lathe(s, 0, 0, 0, axis, [[-t - 0.022, R * 0.22], [t + 0.022, R * 0.22]], 8, scale(col, 1.12));
  });
}

/** A standing plume of steam or smoke, drifting slowly round. */
function puffs(k: Kit, x: number, y: number, z: number, s: number, col: RGB = STEAM, n = 3): void {
  k.spin(x, y, z, 'y', 0.22, (p) => {
    for (let i = 0; i < n; i++) p.dome(Math.sin(i * 2.1) * s * 0.55, i * s * 0.95, Math.cos(i * 2.1) * s * 0.45, s * (0.75 + i * 0.22), col, 6, 2);
  });
}

/** A valve that blows off a jet of steam every minute or so. */
function valve(k: Kit, x: number, y: number, z: number, seed: number): void {
  k.cyl(x, y, z, 0.035, 0.1, BRASS, 6);
  k.spin(x, y + 0.1, z, 'y', seed, (p) => {
    p.cone(0, 0, 0, 0.07, 0.3, STEAM, 6);
    p.dome(0, 0.26, 0, 0.12, STEAM, 6, 2);
    p.dome(0.05, 0.4, 0.03, 0.15, STEAM, 6, 2);
  }, 'geyser');
}

/** A round window or dial facing +z, in upright strips of lit glass. */
function roundPane(k: Kit, x: number, y: number, z: number, rad: number, n: number, day: RGB, s: Sched, g: RGB): void {
  for (let i = 0; i < n; i++) {
    const u = -rad + ((i + 0.5) * 2 * rad) / n, h = Math.sqrt(Math.max(0, rad * rad - u * u * 0.9));
    k.pane(x + u, y - h, z, (2 * rad) / n, 2 * h, 1, day, s, g);
  }
}

/** Draw in a frame whose +z points out from (cx, cz) along the angle theta (x = cos, z = sin): `draw` is given where (cx, cz) lies in it. */
function around(k: Kit, cx: number, cz: number, theta: number, draw: (ox: number, oz: number) => void): void {
  const a = Math.PI / 2 - theta, c = Math.cos(a), s = Math.sin(a);
  k.turned(a, () => draw(cx * c - cz * s, cx * s + cz * c));
}

/** A leafy blob: two pyramids base to base. */
function blob(k: Kit, x: number, y: number, z: number, s: number, col: RGB): void {
  k.hip(x, y + s * 0.3, z, s, s * 0.6, s, col);
  k.hip(x, y + s * 0.3, z, s, -s * 0.3, s, scale(col, 0.82));
}

/** A flat plate a hair proud of a wall facing `face` (0 +x, 1 +z, 2 -x, 3 -z), `len` along the wall. */
function plate(k: Kit, face: number, x: number, y: number, z: number, len: number, h: number, col: RGB): void {
  const e = 0.003;
  if (face === 1 || face === 3) {
    const zz = z + (face === 1 ? e : -e);
    k.quad([x - len / 2, y, zz], [x + len / 2, y, zz], [x + len / 2, y + h, zz], [x - len / 2, y + h, zz], col, [x, y, z - (face === 1 ? 0.1 : -0.1)]);
  } else {
    const xx = x + (face === 0 ? e : -e);
    k.quad([xx, y, z - len / 2], [xx, y, z + len / 2], [xx, y + h, z + len / 2], [xx, y + h, z - len / 2], col, [x - (face === 0 ? 0.1 : -0.1), y, z]);
  }
}

/** A vertical neon blade standing out from a front at (x, z): panels of plain light on a dark spine, no lettering. */
function blade(k: Kit, r: Rng, x: number, y0: number, y1: number, z: number, out: number, cols: readonly number[] = NEONS): void {
  k.box(x, y0 - 0.03, z + out / 2, 0.05, y1 - y0 + 0.06, out + 0.02, DARK);
  const n = Math.max(2, Math.round((y1 - y0) / 0.55)), ph = (y1 - y0) / n;
  for (let i = 0; i < n; i++) {
    const c = any(r, cols);
    k.glowBox(x, y0 + i * ph + 0.02, z + out / 2 + 0.006, 0.085, ph - 0.04, out, dull(c), NEON_HOURS, c);
  }
}

// =============================================================================================
// steampunk

/**
 * The clockwork tower: a dark brick and iron shaft with brass gear trains turning on every face, a lit
 * clock on all four sides of its iron top stage, brass pipes up the corners and a green copper dome
 * under a lightning rod.
 */
const clockworkTower: Draw = (k, W, D) => {
  const hw = Math.min(W, D) / 2 - 0.34, base = 0.3, shaftTop = 2.7, stageTop = 3.45, hs = hw + 0.1;
  k.box(0, 0, 0, hw * 2 + 0.36, base, hw * 2 + 0.36, IRON, IRON_L);
  k.box(0, base, 0, hw * 2, shaftTop - base, hw * 2, BRICK_D);
  for (const y of [base, 1.95, shaftTop - 0.1]) k.box(0, y, 0, hw * 2 + 0.05, 0.08, hw * 2 + 0.05, IRON);
  // brass pipes up the corners, collared; the back left one is the exhaust and stands taller
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const px = sx * (hw + 0.03), pz = sz * (hw + 0.03), flue = sx < 0 && sz < 0;
    k.cyl(px, 0, pz, 0.05, flue ? shaftTop + 0.55 : shaftTop, BRASS, 6);
    for (const y of [0.5, 1.4, 2.3]) k.cyl(px, y, pz, 0.068, 0.05, BRASS_D, 6);
    if (flue) puffs(k, px, shaftTop + 0.6, pz, 0.13);
  }
  // each face: a gear train standing off the brick, a porthole or two, and the clock above
  for (let f = 0; f < 4; f++) k.turned((f * Math.PI) / 2, () => {
    const gz = hw + 0.085;
    k.box(0, base + 0.25, hw + 0.02, hw * 1.5, 0.05, 0.04, IRON);
    if (f === 0) {
      cog(k, -0.16, 1.05, gz, 'z', 0.36, 0.4);
      cog(k, 0.28, 1.39, gz, 'z', 0.23, -0.4 * (0.36 / 0.23));
      cog(k, 0.37, 1.05, gz, 'z', 0.14, 0.4 * (0.36 / 0.14));
      cog(k, -0.365, 1.49, gz, 'z', 0.15, -0.4 * (0.36 / 0.15), BRASS_D);
      // the door in the plinth
      k.box(0, 0, hw + 0.18, 0.24, 0.24, 0.02, hex(0x3a2a20));
      k.box(0, 0.24, hw + 0.18, 0.3, 0.04, 0.03, BRASS);
    } else {
      const s = f % 2 ? 1 : -1;
      cog(k, s * 0.14, 1.0, gz, 'z', 0.32, 0.45 * s);
      cog(k, -s * 0.3, 1.32, gz, 'z', 0.17, -0.45 * s * (0.32 / 0.17), f === 2 ? BRASS_D : BRASS);
    }
    for (const [px, py] of f === 0 ? [[0, 2.28]] : [[-0.3, 2.28], [0.3, 2.28]]) {
      k.face(px, py, hw + 0.012, 0.135, BRASS, 8);
      roundPane(k, px, py, hw + 0.016, 0.1, 3, hex(0x5a4228), EVENING, AMBER);
    }
    // the clock: a brass bezel, a lit dial, four marks and the hands
    const cy = (shaftTop + stageTop) / 2 + 0.02, R = 0.29;
    k.face(0, cy, hs + 0.004, R * 1.16, BRASS, 12);
    roundPane(k, 0, cy, hs + 0.008, R, 6, hex(0xe8dcc0), ALL_NIGHT, hex(0xffc070));
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU;
      k.box(Math.cos(a) * R * 0.82, cy + Math.sin(a) * R * 0.82 - 0.02, hs + 0.02, 0.04, 0.04, 0.006, IRON);
    }
    k.spin(0, cy, hs + 0.03, 'z', 0, (h) => h.box(0, 0, 0, 0.034, R * 0.55, 0.006, IRON), 'hour');
    k.spin(0, cy, hs + 0.04, 'z', 0, (h) => h.box(0, 0, 0, 0.022, R * 0.86, 0.006, IRON), 'minute');
  });
  // the iron clock stage between brass cornices
  k.box(0, shaftTop, 0, hs * 2, stageTop - shaftTop, hs * 2, IRON);
  k.box(0, shaftTop - 0.02, 0, hs * 2 + 0.08, 0.06, hs * 2 + 0.08, BRASS);
  k.box(0, stageTop, 0, hs * 2 + 0.1, 0.07, hs * 2 + 0.1, BRASS);
  // the copper dome, gone green, and the lightning rod
  const dy = stageTop + 0.07;
  k.cyl(0, dy, 0, 0.56, 0.12, BRASS_D, 10);
  k.dome(0, dy + 0.12, 0, 0.54, VERDIGRIS, 10, 3);
  k.cyl(0, dy + 0.62, 0, 0.07, 0.1, BRASS, 6);
  k.bar([0, dy + 0.7, 0], [0, dy + 1.25, 0], 0.014, IRON);
  k.box(0, dy + 0.88, 0, 0.08, 0.08, 0.08, BRASS);
  for (const s of [-1, 1]) k.bar([0, dy + 1.0, 0], [s * 0.1, dy + 1.14, 0], 0.01, IRON);
  // safety valves on the plinth, blowing off now and then
  valve(k, hw + 0.12, base, hw + 0.12, 3);
  valve(k, -hw - 0.12, base, hw + 0.12, 21);
  valve(k, hw + 0.12, base, -hw - 0.12, 37);
  valve(k, 0.3, stageTop + 0.07, 0.62, 12);
};

/**
 * The boiler works: a brick engine hall with tall arched windows glowing orange, three copper boilers
 * on cradles in the yard, a pipe bridge, a flywheel and beam engine turning in the open bay, chimneys of
 * every height, a coal heap and a hopper wagon.
 */
const boilerWorks: Draw = (k, W, D, _b, r) => {
  k.box(0, 0, 0, W - 0.1, 0.02, D - 0.1, CINDER);
  // the engine hall along the back
  const hallW = W - 1.4, hallD = 1.0, hx = -W / 2 + 0.15 + hallW / 2, hz = -D / 2 + 0.15 + hallD / 2, hH = 0.85, fz = hz + hallD / 2;
  k.box(hx, 0, hz, hallW, hH, hallD, BRICK_M);
  k.box(hx, hH, hz, hallW + 0.05, 0.05, hallD + 0.05, IRON_L);
  k.gable(hx, hH + 0.05, hz, hallW + 0.05, 0.3, hallD + 0.05, SLATE, BRICK_M);
  k.box(hx, hH + 0.26, hz, hallW * 0.6, 0.12, 0.16, IRON_L, SLATE);
  const arch = (x: number, z: number, face: number) => {
    const along = face === 1 || face === 3;
    k.pane(x, 0.16, z, 0.17, 0.42, face, hex(0x3a3430), ALL_NIGHT, FURNACE);
    k.pane(x, 0.58, z, 0.11, 0.06, face, hex(0x3a3430), ALL_NIGHT, FURNACE);
    const o = face === 1 || face === 0 ? 0.012 : -0.012;
    // the iron glazing bar across each
    if (along) k.box(x, 0.36, z + o, 0.19, 0.025, 0.012, IRON); else k.box(x + o, 0.36, z, 0.012, 0.025, 0.19, IRON);
  };
  const nw = 5;
  for (let i = 0; i < nw; i++) {
    const x = hx - hallW / 2 + (hallW * (i + 0.5)) / nw;
    arch(x, fz, 1);
    arch(x, hz - hallD / 2, 3);
  }
  for (let i = 0; i <= nw; i++) k.box(hx - hallW / 2 + (hallW * i) / nw, 0, fz, 0.06, hH, 0.05, BRICK_D);
  for (const z of [hz - 0.25, hz + 0.25]) arch(hx - hallW / 2, z, 2);
  // the open engine bay beside it: a low brick back wall, an iron gantry, the flywheel and the beam engine
  const bx0 = hx + hallW / 2, bx1 = W / 2 - 0.15, bx = (bx0 + bx1) / 2, bw = bx1 - bx0;
  k.box(bx, 0, hz - hallD / 2 + 0.05, bw, 0.5, 0.1, BRICK_D);
  k.box(bx, 0, hz, bw, 0.06, hallD, IRON_L);
  for (const z of [hz - 0.32, hz + 0.42]) {
    for (const x of [bx0 + 0.06, bx1 - 0.06]) k.box(x, 0, z, 0.05, 0.95, 0.05, IRON);
    k.box(bx, 0.95, z, bw, 0.05, 0.05, IRON);
  }
  const wx = bx - 0.22, wy = 0.46, wz = hz + 0.2, WR = 0.34;
  k.spin(wx, wy, wz, 'z', 1.1, (s) => {
    s.hoop(0, 0, 0, WR, 0.03, IRON, 12, 'xy');
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * Math.PI;
      s.bar([Math.cos(a) * WR, Math.sin(a) * WR, 0], [-Math.cos(a) * WR, -Math.sin(a) * WR, 0], 0.018, hex(0x8a2a22));
    }
    lathe(s, 0, 0, 0, 'z', [[-0.05, 0.07], [0.05, 0.07]], 8, BRASS);
    s.box(WR * 0.5, -0.03, 0.05, 0.06, 0.06, 0.04, BRASS);
  });
  for (const z of [wz - 0.09, wz + 0.09]) k.box(wx, 0.06, z, 0.12, wy - 0.06, 0.04, IRON);
  // the engine: a brass cylinder, the column, the beam rocking over it (stilled) and the rod to the crank
  const ex = bx + 0.28;
  k.cyl(ex, 0.06, wz, 0.1, 0.4, BRASS, 8);
  k.cyl(ex, 0.46, wz, 0.11, 0.04, BRASS_D, 8);
  k.box(bx + 0.04, 0.06, wz, 0.09, 0.72, 0.09, IRON);
  k.bar([wx + 0.02, 0.74, wz], [ex + 0.04, 0.84, wz], 0.03, hex(0x2f5a48));
  k.bar([ex, 0.5, wz], [ex, 0.82, wz], 0.012, METAL);
  k.bar([wx + 0.04, 0.74, wz + 0.06], [wx + WR * 0.5, wy, wz + 0.06], 0.014, METAL);
  k.spin(bx + 0.04, 0.8, wz, 'y', 2.6, (s) => {
    for (const sx of [-1, 1]) { s.bar([0, 0.12, 0], [sx * 0.09, 0.04, 0], 0.008, METAL); s.box(sx * 0.09, 0.0, 0, 0.05, 0.05, 0.05, BRASS); }
    s.box(0, 0, 0, 0.02, 0.14, 0.02, METAL);
  });
  // the chimneys: brick and iron, all heights, crowned and smoking
  const stacks: [number, number, number, number, boolean][] = [
    [hx - hallW * 0.4, hz - 0.3, 2.6, 0.11, true], [hx - hallW * 0.2, hz - 0.34, 1.8, 0.085, false], [hx, hz - 0.3, 2.25, 0.1, true],
    [hx + hallW * 0.2, hz - 0.34, 1.55, 0.075, false], [hx + hallW * 0.38, hz - 0.3, 2.0, 0.09, true], [bx1 - 0.16, hz - 0.28, 2.95, 0.14, true],
  ];
  stacks.forEach(([x, z, h, rad, brick], i) => {
    const col = brick ? (i % 2 ? BRICK_M : BRICK_D) : IRON_L;
    k.band(x, z, 0, rad, h, rad * 0.72, 8, col);
    k.band(x, z, h, rad * 0.72, h + 0.08, rad * 0.98, 8, brick ? BRICK_D : IRON);
    k.cyl(x, h + 0.08, z, rad * 0.98, 0.04, IRON, 8, COAL);
    if (brick) k.cyl(x, h * 0.6, z, rad * 0.86, 0.04, IRON, 8);
    puffs(k, x, h + 0.16, z, rad * 1.3, i % 2 ? SMOKE : STEAM);
  });
  // three copper boilers on cradles, end-on to the road: riveted bands, a steam dome, a gauge, a fire door
  const bl = 1.0, bz0 = D / 2 - 0.3 - bl, by = 0.36, R = 0.2;
  const bxs = [0, 1, 2].map((i) => -W / 2 + 0.42 + i * 0.5);
  for (const x of bxs) {
    lathe(k, x, by, bz0, 'z', [[0, 0.08], [0.07, R], [bl - 0.07, R], [bl, 0.08]], 10, COPPER);
    for (const t of [0.26, 0.5, 0.74]) lathe(k, x, by, bz0 + bl * t, 'z', [[-0.016, R + 0.012], [0.016, R + 0.012]], 10, COPPER_D);
    for (const z of [bz0 + 0.22, bz0 + bl - 0.34]) k.box(x, 0.02, z, 0.32, 0.17, 0.08, IRON);
    k.box(x, 0.02, bz0 + bl - 0.1, 0.3, 0.17, 0.18, BRICK_D);
    k.pane(x, 0.05, bz0 + bl - 0.01, 0.13, 0.09, 1, hex(0x4a2a1a), ALL_NIGHT, FURNACE);
    k.cyl(x, by + R - 0.02, bz0 + 0.36, 0.07, 0.1, BRASS, 8);
    k.dome(x, by + R + 0.08, bz0 + 0.36, 0.07, BRASS, 8, 2);
    k.face(x, by + 0.02, bz0 + bl + 0.006, 0.075, BRASS, 8);
    k.face(x, by + 0.02, bz0 + bl + 0.012, 0.055, hex(0xf0ead8), 8);
    k.box(x, by + 0.02, bz0 + bl + 0.016, 0.012, 0.045, 0.004, IRON);
    // its riser to the pipe bridge, and the feed back to the hall
    k.bar([x, by + R + 0.1, bz0 + 0.36], [x, 0.98, bz0 + 0.36], 0.022, VERDIGRIS);
    k.bar([x, by, bz0 + 0.04], [x, by, fz], 0.03, COPPER_D);
  }
  // the pipe bridge: along over the boilers, across the yard on trestles and up the bay to the engine
  const pz = bz0 + 0.36, px1 = bx - 0.3;
  k.bar([bxs[0], 0.98, pz], [px1, 0.98, pz], 0.04, VERDIGRIS);
  k.bar([px1, 0.98, pz], [px1, 0.98, hz + 0.42], 0.04, VERDIGRIS);
  for (const x of [bxs[2] + 0.42, px1]) for (const s of [-1, 1]) k.bar([x + s * 0.12, 0.02, pz], [x, 0.95, pz], 0.018, IRON);
  valve(k, px1, 1.0, pz, 9);
  valve(k, bxs[1], 1.0, pz, 27);
  // the coal heap, and a hopper wagon on its siding
  const cx = W / 2 - 0.5, cz = D / 2 - 0.5;
  k.cone(cx, 0.02, cz, 0.36, 0.3, COAL, 7);
  k.cone(cx - 0.3, 0.02, cz + 0.1, 0.2, 0.17, scale(COAL, 1.2), 6);
  const rz = cz - 0.62;
  for (const s of [-1, 1]) k.bar([bxs[2] + 0.4, 0.03, rz + s * 0.07], [W / 2 - 0.1, 0.03, rz + s * 0.07], 0.01, METAL);
  const gx = cx - 0.1;
  k.box(gx, 0.08, rz, 0.2, 0.06, 0.13, hex(0x5a4034));
  k.box(gx, 0.14, rz, 0.34, 0.12, 0.2, hex(0x6a4a3a), COAL);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(gx + sx * 0.11, 0.03, rz + sz * 0.075, 0.07, 0.07, 0.02, IRON);
  // a yard lamp
  k.box(W / 2 - 0.2, 0, D / 2 - 0.16, 0.03, 0.6, 0.03, IRON);
  k.glowBox(W / 2 - 0.2, 0.6, D / 2 - 0.16, 0.08, 0.06, 0.08, hex(0xd8c89a), ALL_NIGHT, AMBER);
  void r;
};

/**
 * The sky dock: a riveted iron mooring mast with a stair spiralling up it to a boarding platform, and
 * an airship riding at the masthead, brass-ochre in ribbed panels with a timber gondola and two turning
 * propellers; ropes down to winches, crates and a steam crane on the ground.
 */
const skyDock: Draw = (k, W, D, _b, r) => {
  k.box(0, 0, 0, W - 0.1, 0.02, D - 0.1, hex(0x6e675c));
  const tx = -W / 2 + 0.4, tz = 0, TH = 3.1, half = (y: number) => 0.3 - 0.2 * (y / TH);
  // the mast: four legs leaning in, ringed and cross-braced tier by tier
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([tx + sx * 0.3, 0, tz + sz * 0.3], [tx + sx * 0.1, TH, tz + sz * 0.1], 0.028, IRON);
  const tiers = 6;
  for (let i = 0; i < tiers; i++) {
    const y0 = (i * TH) / tiers, y1 = ((i + 1) * TH) / tiers, h0 = half(y0), h1 = half(y1), s = i % 2 ? 1 : -1;
    const c = (hh: number, y: number, q: number): P3 => [tx + (q === 0 || q === 3 ? -hh : hh), y, tz + (q < 2 ? -hh : hh)];
    for (let q = 0; q < 4; q++) {
      const n = (q + 1) % 4;
      k.bar(c(h1, y1, q), c(h1, y1, n), 0.016, IRON_L);
      k.bar(s > 0 ? c(h0, y0, q) : c(h0, y0, n), s > 0 ? c(h1, y1, n) : c(h1, y1, q), 0.013, IRON_L);
    }
  }
  // the stair winding round it up to the platform
  const py = 2.42, steps = 38;
  for (let i = 0; i < steps; i++) {
    const y = 0.06 + (i / steps) * (py - 0.1), rad = half(y) * 1.25 + 0.12;
    around(k, tx, tz, i * 0.5, (ox, oz) => k.box(ox, y, oz + rad, 0.13, 0.03, 0.17, WOOD));
  }
  // the boarding platform, railed, and the gangway out to the gondola
  k.box(tx + 0.08, py, tz, 0.78, 0.04, 0.62, WOOD, scale(WOOD, 1.15));
  for (const sz of [-1, 1]) {
    k.bar([tx - 0.3, py + 0.16, tz + sz * 0.3], [tx + 0.46, py + 0.16, tz + sz * 0.3], 0.01, BRASS);
    for (const x of [tx - 0.3, tx + 0.08, tx + 0.46]) k.box(x, py + 0.04, tz + sz * 0.3, 0.02, 0.13, 0.02, IRON);
    k.glowBox(tx + 0.46, py + 0.17, tz + sz * 0.3, 0.05, 0.05, 0.05, hex(0xd8c89a), ALL_NIGHT, AMBER);
  }
  // the masthead: the mooring cup, and a beacon on the pole above it
  k.cyl(tx, TH, tz, 0.11, 0.1, BRASS_D, 8);
  k.bar([tx, TH + 0.1, tz], [tx, 3.6, tz], 0.014, IRON);
  k.glowBox(tx, 3.6, tz, 0.06, 0.06, 0.06, hex(0xa02a22), BEACON, hex(0xff4a3a));
  // the airship: nose to the mast, its length out over the lot and beyond
  const ay = 3.2, x0 = tx + 0.16, L = 3.2, RR = 0.55;
  const prof: [number, number][] = [[0, 0], [0.12, 0.2], [0.45, 0.4], [0.95, 0.52], [1.6, RR], [2.2, 0.5], [2.7, 0.36], [3.0, 0.2], [L, 0.03]];
  lathe(k, x0, ay, tz, 'x', prof, 10, (i, s) => ((i + s) % 2 ? OCHRE : scale(OCHRE, 0.86)));
  for (const i of [2, 3, 5, 6]) lathe(k, x0 + prof[i][0], ay, tz, 'x', [[-0.025, prof[i][1] + 0.014], [0.025, prof[i][1] + 0.014]], 10, BRASS_D);
  k.bar([tx + 0.05, TH + 0.06, tz], [x0 + 0.05, ay, tz], 0.02, BRASS_D);
  // the tail: four fins
  const fx = x0 + 2.82;
  k.box(fx, ay + 0.1, tz, 0.5, 0.34, 0.03, FIN);
  k.box(fx, ay - 0.44, tz, 0.5, 0.34, 0.03, FIN);
  for (const s of [-1, 1]) k.box(fx, ay - 0.015, tz + s * 0.27, 0.5, 0.03, 0.34, FIN);
  // the gondola slung beneath, portholes lit, a propeller on an outrigger either side
  const gx = x0 + 1.4, gy = ay - RR - 0.26, gl = 1.0;
  k.box(gx, gy, tz, gl, 0.22, 0.3, hex(0x6e4a2e), WOOD);
  k.box(gx, gy + 0.18, tz, gl + 0.02, 0.03, 0.32, BRASS_D);
  for (let i = 0; i < 5; i++) for (const f of [1, 3]) k.pane(gx - gl / 2 + (gl * (i + 0.5)) / 5, gy + 0.07, tz + (f === 1 ? 0.15 : -0.15), 0.09, 0.08, f, hex(0x7a8a8a), ALL_NIGHT, WARM_GLOW);
  k.pane(gx - gl / 2, gy + 0.07, tz, 0.18, 0.09, 2, hex(0x7a8a8a), ALL_NIGHT, WARM_GLOW);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([gx + sx * 0.4, gy + 0.2, tz + sz * 0.12], [gx + sx * 0.45, ay - RR * 0.8, tz + sz * 0.22], 0.01, ROPE);
  for (const s of [-1, 1]) {
    const ex = gx + 0.3, ez = tz + s * 0.36;
    k.bar([ex, gy + 0.1, tz + s * 0.15], [ex, gy + 0.1, ez], 0.014, IRON);
    k.box(ex, gy + 0.06, ez, 0.14, 0.08, 0.08, BRASS);
    k.spin(ex + 0.09, gy + 0.1, ez, 'x', 13, (p) => { p.box(0, -0.14, 0, 0.014, 0.28, 0.045, WOOD); p.box(0, -0.0225, 0, 0.014, 0.045, 0.28, WOOD); });
  }
  k.box(tx + 0.47 + (gx - gl / 2 - tx - 0.47) / 2, py, tz, gx - gl / 2 - tx - 0.47, 0.03, 0.16, WOOD);
  // mooring ropes down to winches at the corners of the yard
  const moor: [number, number, number, number][] = [[x0 + 0.9, 0.3, -0.35, 1.15], [x0 + 2.2, 0.3, W / 2 - 0.35, 1.15], [x0 + 0.9, -0.3, -0.35, -1.15], [x0 + 2.2, -0.3, W / 2 - 0.35, -1.15]];
  for (const [ex, ez, wx, wz] of moor) {
    k.bar([ex, ay - RR * 0.82, tz + ez], [wx, 0.14, wz], 0.008, ROPE);
    k.box(wx, 0.02, wz, 0.2, 0.08, 0.16, IRON);
    lathe(k, wx - 0.08, 0.16, wz, 'x', [[0, 0.06], [0.16, 0.06]], 6, BRASS_D);
  }
  // crates waiting to go aboard
  const crates: [number, number, number, number][] = [[-0.25, 0.75, 0.2, 0], [-0.02, 0.8, 0.16, 0], [-0.2, 0.78, 0.15, 0.2], [0.25, 0.55, 0.18, 0], [-0.6, -0.8, 0.2, 0], [-0.38, -0.85, 0.15, 0]];
  for (const [x, z, s, y] of crates) k.box(x, 0.02 + y, z, s, s, s, scale(WOOD, 0.85 + r() * 0.3), scale(WOOD, 1.15));
  // the steam crane: cab, boiler and a jib with its hook hanging
  const kx = 0.75, kz = -0.45;
  k.box(kx, 0.02, kz, 0.34, 0.1, 0.3, IRON);
  k.box(kx + 0.04, 0.12, kz, 0.2, 0.24, 0.22, hex(0x7a3a2e), IRON);
  k.cyl(kx + 0.2, 0.12, kz, 0.06, 0.34, IRON_L, 6);
  puffs(k, kx + 0.2, 0.5, kz, 0.07, STEAM, 2);
  k.bar([kx - 0.06, 0.3, kz], [kx - 0.55, 1.05, kz + 0.2], 0.022, IRON);
  k.bar([kx + 0.04, 0.36, kz], [kx - 0.55, 1.05, kz + 0.2], 0.008, ROPE);
  k.bar([kx - 0.55, 1.05, kz + 0.2], [kx - 0.55, 0.55, kz + 0.2], 0.008, ROPE);
  k.box(kx - 0.55, 0.42, kz + 0.2, 0.13, 0.13, 0.13, WOOD);
};

