// solarpunk

/**
 * The garden tower: a white tower with a deep planted balcony on every other floor of every side,
 * staggered left and right as it climbs, timber screens between, a living wall up one corner and a
 * garden on the roof with a glass pavilion and a ring of little wind turbines.
 */
const gardenTower: Draw = (k, W, D, b, r) => {
  const H = Math.max(20, b.floors) * FLOOR, cw = Math.min(W, D) - 0.9, hw = cw / 2, pod = 0.42, step = FLOOR * 2;
  const green = () => any(r, GREENS);
  // the podium: timber and glass under a planted roof
  k.box(0, 0, 0, cw + 0.5, pod, cw + 0.5, SOL_WHITE, hex(0x6bb055));
  k.box(0, pod, 0, cw + 0.56, 0.04, cw + 0.56, TIMBER, hex(0x6bb055));
  k.pane(0, 0.03, hw + 0.25, 0.5, 0.28, 1, GLASS_LIGHT, EVENING, WARM_GLOW);
  for (const s of [-1, 1]) k.box(s * 0.4, 0.03, hw + 0.26, 0.2, 0.3, 0.02, TIMBER);
  for (const s of [-1, 1]) blob(k, s * (hw + 0.14), pod + 0.04, hw + 0.14, 0.2, green());
  // the shaft
  k.box(0, pod, 0, cw, H - pod, cw, SOL_WHITE);
  let lv = 0;
  for (let y = pod + 0.34; y < H - 0.3; y += step, lv++) {
    for (let f = 0; f < 4; f++) k.turned((f * Math.PI) / 2, () => {
      const side = (lv + f) % 2 ? 1 : -1, bw = cw * 0.5, bx = side * cw * 0.22;
      // tall glazing behind the planting, lit warm in the evening
      for (const s of [-1, 1]) {
        const lit: Sched = r() < 0.75 ? [17.5 + r() * 1.5, 22 + r() * 3, 1.3] : OFF;
        k.pane(s * cw * 0.23, y + 0.08, hw, cw * 0.4, step * 0.62, 1, hex(0x7fa6a8), lit, WARM_GLOW);
      }
      // the balcony: a deep white tray, and what grows in it
      k.box(bx, y - 0.02, hw + 0.13, bw, 0.08, 0.26, SOL_WHITE, hex(0x5a4a38));
      const n = 2;
      for (let i = 0; i < n; i++) {
        const px = bx + (i - 0.5) * bw * 0.5, pz = hw + 0.13 + (r() - 0.5) * 0.06;
        if (r() < 0.4) {
          const th = 0.16 + r() * 0.1;
          k.box(px, y + 0.06, pz, 0.03, th, 0.03, TRUNK);
          blob(k, px, y + 0.02 + th, pz, 0.24 + r() * 0.08, green());
        } else blob(k, px, y + 0.03, pz, 0.17 + r() * 0.1, green());
      }
      // a timber slat screen on the other side, every other level
      if (lv % 2 === 0) k.box(-side * (hw - 0.11), y + 0.06, hw + 0.012, 0.16, step * 0.8, 0.024, TIMBER);
    });
  }
  // the living wall up the front right corner
  const lw = 0.2, segs = 7, top = H - 0.16;
  for (let i = 0; i < segs; i++) k.box(hw - 0.04, pod + ((top - pod) * i) / segs, hw - 0.04, lw, (top - pod) / segs, lw, scale(green(), 0.92));
  // the roof: a parapet, a lawn, trees, the glass pavilion under a solar sail, and the turbines
  k.box(0, H, 0, cw + 0.06, 0.06, cw + 0.06, SOL_WHITE, hex(0x6bb055));
  k.box(-0.1, H + 0.06, -0.08, 0.46, 0.24, 0.36, GLASS_LIGHT, SOL_WHITE);
  for (const f of [0, 1, 2, 3]) k.pane(-0.1 + (f === 0 ? 0.23 : f === 2 ? -0.23 : 0), H + 0.09, -0.08 + (f === 1 ? 0.18 : f === 3 ? -0.18 : 0), f % 2 ? 0.38 : 0.28, 0.17, f, GLASS_LIGHT, EVENING, WARM_GLOW);
  k.wedge(-0.1, H + 0.31, -0.08, 0.56, 0.12, 0.46, SOLAR);
  for (const [x, z] of [[0.34, 0.3], [-0.36, 0.34], [0.36, -0.32]] as const) {
    k.box(x, H + 0.06, z, 0.035, 0.16, 0.035, TRUNK);
    blob(k, x, H + 0.16, z, 0.3, green());
  }
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const x = sx * (hw - 0.05), z = sz * (hw - 0.05);
    k.box(x, H + 0.06, z, 0.025, 0.42, 0.025, SOL_WHITE);
    k.spin(x, H + 0.48, z, 'y', 2.5 + r() * 2, (s) => {
      for (const q of [-1, 1]) s.box(q * 0.06, 0, q * 0.02, 0.02, 0.26, 0.09, SOL_WHITE);
      s.box(0, 0.12, 0, 0.14, 0.015, 0.03, METAL);
    });
  }
};

/**
 * The solar plaza: six white solar trees holding tilted blue photovoltaic hexagons at different heights
 * over a paved square with planters, benches, a water rill, a bicycle rack and a little kiosk. At night
 * each canopy drops a pool of soft light. An open lot: only the trunks and the kiosk are solid.
 */
const solarCanopy: Draw = (k, W, D, _b, r) => {
  k.box(0, 0, 0, W - 0.1, 0.02, D - 0.1, PLAZA);
  const POOL: Sched = [17.5, 30.5, 0.55];
  const trees: [number, number, number, number][] = [
    [-0.85, -0.82, 1.6, 0.58], [0.12, -0.9, 1.25, 0.52], [0.95, -0.72, 1.5, 0.5], [-0.88, 0.3, 1.2, 0.52], [0.1, 0.22, 1.68, 0.62], [0.92, 0.22, 1.32, 0.48],
  ];
  for (const [x, z, h, R] of trees) {
    const td = r() * TAU, slope = 0.22, rot = r() * TAU;
    const yAt = (dx: number, dz: number) => h + slope * (dx * Math.cos(td) + dz * Math.sin(td));
    const v = (i: number, f = 1): P3 => { const a = rot + (i / 6) * TAU, dx = Math.cos(a) * R * f, dz = Math.sin(a) * R * f; return [x + dx, yAt(dx, dz), z + dz]; };
    // the trunk, flared at the foot, and three boughs up to the canopy
    k.cyl(x, 0.02, z, 0.07, 0.05, SOL_WHITE, 6);
    k.cyl(x, 0.02, z, 0.04, h - 0.04, SOL_WHITE, 6);
    for (let i = 0; i < 3; i++) { const p = v(i * 2 + 0.5, 0.6); k.bar([x, h * 0.72, z], [p[0], p[1] - 0.02, p[2]], 0.018, SOL_WHITE); }
    // the canopy: six blue petals on a white frame, white beneath
    for (let i = 0; i < 6; i++) {
      k.tri([x, h, z], v(i), v(i + 1), i % 2 ? SOLAR : SOLAR2, [x, h - 1, z]);
      k.tri([x, h - 0.012, z], [v(i)[0], v(i)[1] - 0.012, v(i)[2]], [v(i + 1)[0], v(i + 1)[1] - 0.012, v(i + 1)[2]], SOL_WHITE, [x, h + 1, z]);
      const a = v(i), c = v(i + 1);
      k.bar([x, h + 0.008, z], [a[0], a[1] + 0.008, a[2]], 0.011, SOL_WHITE);
      k.bar([a[0], a[1] + 0.004, a[2]], [c[0], c[1] + 0.004, c[2]], 0.011, SOL_WHITE);
    }
    // the lamp under it, and the light it lays on the paving
    k.glowBox(x, h - 0.16, z, 0.12, 0.05, 0.12, hex(0xe8e6dc), [17.5, 30.5, 1.5], hex(0xfff2d0));
    k.glowBox(x, 0.0205, z, R * 1.5, 0.004, R * 1.5, PLAZA, POOL, hex(0xffe9b8));
  }
  // the rill, running front to back between stone kerbs
  const rx = -0.38;
  k.box(rx, 0.02, 0, 0.18, 0.014, D - 0.5, hex(0xb8b2a4));
  k.box(rx, 0.02, 0, 0.1, 0.02, D - 0.56, WATER);
  // planters with a bench beside each
  const planters: [number, number][] = [[-1.2, -0.3], [0.5, -0.35], [-0.35 + 0.75, 0.85], [1.2, -0.15]];
  for (const [x, z] of planters) {
    k.cyl(x, 0.02, z, 0.17, 0.1, SOL_WHITE, 8, hex(0x5a4a38));
    blob(k, x, 0.1, z, 0.26, any(r, GREENS));
    k.box(x, 0.08, z + 0.27, 0.3, 0.025, 0.09, TIMBER);
    for (const s of [-1, 1]) k.box(x + s * 0.11, 0.02, z + 0.27, 0.025, 0.06, 0.08, SOL_WHITE);
  }
  // the bicycle rack
  const kx = -W / 2 + 0.42, kz = D / 2 - 0.32;
  k.box(kx, 0.13, kz - 0.1, 0.5, 0.02, 0.02, METAL);
  for (const s of [-1, 1]) k.box(kx + s * 0.25, 0.02, kz - 0.1, 0.02, 0.12, 0.02, METAL);
  for (let i = 0; i < 4; i++) {
    const x = kx - 0.18 + i * 0.12, c = any(r, [0xe2412f, 0x2f7fb5, 0xf2a93b, 0x3f9b4a]);
    for (const s of [-1, 1]) k.box(x, 0.02, kz + s * 0.07, 0.014, 0.085, 0.085, DARK);
    k.bar([x, 0.08, kz - 0.07], [x, 0.11, kz + 0.07], 0.009, c);
    k.box(x, 0.11, kz - 0.03, 0.02, 0.035, 0.02, c);
  }
  // the kiosk: white and timber under a green roof, its hatch lit
  const qx = W / 2 - 0.45, qz = D / 2 - 0.4;
  k.box(qx, 0.02, qz, 0.38, 0.3, 0.32, SOL_WHITE);
  k.box(qx, 0.02, qz, 0.39, 0.1, 0.33, TIMBER);
  k.box(qx, 0.32, qz + 0.04, 0.52, 0.035, 0.46, SOL_WHITE, hex(0x6bb055));
  k.pane(qx, 0.14, qz + 0.16, 0.26, 0.13, 1, hex(0x7a8a8a), [17, 24.5, 1.5], WARM_GLOW);
  k.box(qx, 0.125, qz + 0.19, 0.3, 0.02, 0.06, TIMBER);
};

/**
 * A geodesic dome on a low white kerb: triangles ring over ring, each ring half a step round from the
 * last, with a strut along every edge. `trees` is how much of the lower glass shows dark foliage behind.
 */
function geoDome(k: Kit, r: Rng, cx: number, cz: number, R: number, seg: number, rings: number, trees: number): void {
  const y0 = 0.1, C: P3 = [cx, y0, cz];
  const v = (j: number, s: number): P3 => {
    if (j >= rings) return [cx, y0 + R, cz];
    const a = ((s + j * 0.5) / seg) * TAU, p = (j / rings) * (Math.PI / 2);
    return [cx + Math.cos(a) * Math.cos(p) * R, y0 + Math.sin(p) * R, cz + Math.sin(a) * Math.cos(p) * R];
  };
  const glass = (j: number): RGB => (j < 2 && r() < trees ? mix(GLASS_PALE, hex(0x2a6236), 0.6 + r() * 0.25) : scale(GLASS_PALE, 0.95 + r() * 0.07));
  const strut = (a: P3, b: P3) => {
    const m: P3 = [(a[0] + b[0]) / 2 - cx, (a[1] + b[1]) / 2 - y0, (a[2] + b[2]) / 2 - cz], ml = Math.hypot(...m) || 1;
    const n: P3 = [m[0] / ml, m[1] / ml, m[2] / ml], d: P3 = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    let sx = d[1] * n[2] - d[2] * n[1], sy = d[2] * n[0] - d[0] * n[2], sz = d[0] * n[1] - d[1] * n[0];
    const sl = Math.hypot(sx, sy, sz) || 1, w = Math.max(0.014, R * 0.018), e = 0.012;
    sx = (sx / sl) * w; sy = (sy / sl) * w; sz = (sz / sl) * w;
    const o = (p: P3, q: number): P3 => [p[0] + n[0] * e + sx * q, p[1] + n[1] * e + sy * q, p[2] + n[2] * e + sz * q];
    k.quad(o(a, -1), o(a, 1), o(b, 1), o(b, -1), FRAME, C);
  };
  k.cyl(cx, 0, cz, R + 0.035, y0, SOL_WHITE, seg);
  for (let j = 0; j < rings; j++) for (let s = 0; s < seg; s++) {
    k.tri(v(j, s), v(j, s + 1), v(j + 1, s), glass(j), C);
    if (j < rings - 1) k.tri(v(j + 1, s), v(j, s + 1), v(j + 1, s + 1), glass(j), C);
    strut(v(j, s), v(j, s + 1));
    strut(v(j, s), v(j + 1, s));
    if (j < rings - 1) strut(v(j, s + 1), v(j + 1, s));
  }
  // a band of light round the kerb after dark, as if the whole house were lit within
  const mid = (R + 0.035) * Math.cos(Math.PI / seg), len = 2 * (R + 0.035) * Math.sin(Math.PI / seg);
  for (let s = 0; s < seg; s++) around(k, cx, cz, ((s + 0.5) / seg) * TAU, (ox, oz) => k.pane(ox, 0.025, oz + mid, len * 0.8, 0.055, 1, hex(0xdfe8e0), [17.5, 30.5, 1.5], hex(0xd8ffd0)));
}

/**
 * The biome conservatory: three interlocking geodesic glass domes, the jungle dark behind the glass of
 * the largest, with a timber entrance pavilion under a green roof, a pond and reed bed, and raised
 * vegetable beds.
 */
const bioDome: Draw = (k, W, D, _b, r) => {
  const R = Math.min(W, D) / 2 - 0.35, bx = -W / 2 + R + 0.1, bz = -D / 2 + R + 0.1;
  geoDome(k, r, bx, bz, R, 10, 4, 0.5);
  geoDome(k, r, W / 2 - 0.8, -D / 2 + 0.85, 0.68, 8, 3, 0.2);
  geoDome(k, r, W / 2 - 0.68, 0.22, 0.5, 8, 3, 0.12);
  // the entrance pavilion at the big dome's foot: timber, glass doors, a planted roof
  const pz = bz + R - 0.02;
  k.box(bx, 0, pz + 0.12, 0.66, 0.3, 0.46, TIMBER);
  for (let i = 0; i < 5; i++) k.box(bx - 0.26 + i * 0.13, 0.02, pz + 0.355, 0.03, 0.27, 0.012, scale(TIMBER, 0.78));
  k.box(bx, 0.3, pz + 0.14, 0.8, 0.045, 0.56, SOL_WHITE, hex(0x6bb055));
  k.pane(bx, 0.02, pz + 0.362, 0.22, 0.22, 1, GLASS_LIGHT, [17, 24.5, 1.5], WARM_GLOW);
  k.box(bx, 0, pz + 0.55, 0.34, 0.02, 0.4, PLAZA);
  // the pond and its reeds
  const px = W / 2 - 0.62, pzz = D / 2 - 0.42;
  k.cyl(px, 0, pzz, 0.42, 0.022, hex(0xb8b2a4), 10, hex(0xb8b2a4), 0.3);
  k.cyl(px, 0, pzz, 0.36, 0.03, WATER, 10, WATER, 0.24);
  for (let i = 0; i < 9; i++) {
    const x = px - 0.3 + i * 0.075 + (r() - 0.5) * 0.03, z = pzz - 0.17 - r() * 0.08, h = 0.14 + r() * 0.1;
    k.box(x, 0.02, z, 0.022, h, 0.022, hex(0x6a9a4a));
    if (i % 2) k.box(x, 0.02 + h, z, 0.03, 0.05, 0.03, hex(0x6a4a30));
  }
  // raised vegetable beds along the front
  for (let i = 0; i < 3; i++) {
    const x = -W / 2 + 0.34 + i * 0.4 + (i === 2 ? 0.1 : 0), z = D / 2 - 0.3 - (i === 2 ? -0.02 : 0.12 * (1 - i));
    if (Math.abs(x - bx) < 0.4) continue;
    k.box(x, 0, z, 0.3, 0.08, 0.36, TIMBER, hex(0x5a4a38));
    for (let j = 0; j < 3; j++) k.box(x + (j - 1) * 0.09, 0.08, z, 0.05, 0.04 + (j % 2) * 0.025, 0.28, any(r, GREENS));
  }
  // and low lamps along the path
  for (const s of [-1, 1]) {
    k.box(bx + s * 0.26, 0, pz + 0.7, 0.03, 0.12, 0.03, SOL_WHITE);
    k.glowBox(bx + s * 0.26, 0.12, pz + 0.7, 0.05, 0.035, 0.05, hex(0xe8e6dc), [17.5, 30.5, 1.5], hex(0xfff2d0));
  }
};

// =============================================================================================
// cyberpunk

/** What a megablock window burns: mostly amber, some cyan, a little magenta. */
function blockLight(r: Rng): RGB {
  const t = r();
  return t < 0.55 ? hex(0xffb24a) : t < 0.84 ? hex(0x39d8ff) : hex(0xff3aa0);
}

/**
 * The megablock: a colossal dark slab, stepped wider toward its base, with an atrium slot cut down the
 * front showing tiers of lit walkways; windows in ragged lit patches, giant neon blades and a billboard
 * of light, lift shafts and pipes up its sides, vents and a landing pad on the roof and a jumble of
 * little shops round its foot.
 */
const megablock: Draw = (k, W, D, b, r) => {
  const H = Math.max(30, b.floors) * FLOOR, hw0 = Math.min(W, D) / 2 - 0.3, slot = 0.34, sb = -0.15, tiers = 3, th = H / tiers;
  const hwAt = (i: number) => hw0 - i * 0.07;
  /** Rows of windows along one wall: a dim band a floor, and the few that are lit. */
  const lights = (cx: number, cz: number, len: number, face: number, y0: number, y1: number, density: number, band: boolean) => {
    const n = Math.max(1, Math.floor(len / 0.15)), cell = len / n, along = face === 1 || face === 3;
    for (let y = y0; y + 0.2 < y1; y += FLOOR) {
      if (band) plate(k, face, cx, y + 0.06, cz, len - 0.06, 0.13, BLOCK_L);
      for (let c = 0; c < n; c++) {
        if (r() > density) continue;
        const run = Math.min(n - c, r() < 0.3 ? 2 : 1), u = -len / 2 + cell * (c + run / 2);
        const s: Sched = [17 + r() * 2.5, 23 + r() * 7.5, 1.35];
        k.pane(along ? cx + u : cx, y + 0.075, along ? cz : cz + u, cell * run - 0.045, 0.1, face, hex(0x4a5560), s, blockLight(r));
        c += run - 1;
      }
    }
  };
  for (let i = 0; i < tiers; i++) {
    const hw = hwAt(i), y0 = i * th, wing = hw - slot, wx = (slot + hw) / 2, wz = (sb + hw) / 2;
    k.box(0, y0, (sb - hw) / 2, hw * 2, th, sb + hw, BLOCK, BLOCK_ROOF);
    for (const s of [-1, 1]) k.box(s * wx, y0, wz, wing, th, hw - sb, BLOCK, BLOCK_ROOF);
    const w0 = i === 0 ? 0.62 : y0 + 0.08, w1 = y0 + th - 0.05;
    lights(0, -hw, hw * 2, 3, w0, w1, 0.15, true);
    lights(hw, 0, hw * 2, 0, w0, w1, 0.15, true);
    lights(-hw, 0, hw * 2, 2, w0, w1, 0.15, true);
    for (const s of [-1, 1]) lights(s * wx, hw, wing, 1, w0, w1, 0.17, true);
    // the back wall of the atrium, busier and brighter
    lights(0, sb, slot * 2, 1, w0, w1, 0.45, false);
  }
  // walkways across the atrium, tier on tier, each with a rail of light
  for (let y = 0.9, j = 0; y < H - 0.4; y += FLOOR * 4, j++) {
    const z = sb + 0.12 + ((j * 7) % 5) * 0.17;
    k.box(0, y, z, slot * 2, 0.04, 0.1, BLOCK_L);
    const c = j % 3 === 2 ? CYAN : NEON_AMBER;
    k.glowBox(0, y + 0.04, z + 0.04, slot * 2, 0.025, 0.02, dull(c), NEON_HOURS, c);
  }
  // the gate at the atrium's foot
  k.glowBox(0, 0.02, hw0 + 0.01, slot * 2 - 0.1, 0.5, 0.02, hex(0x4a5560), NEON_HOURS, hex(0xff8ad0));
  for (const s of [-1, 1]) k.glowBox(s * (slot - 0.03), 0, hw0 + 0.03, 0.04, 0.62, 0.04, dull(MAGENTA), NEON_HOURS, MAGENTA);
  // giant blades of neon: down the left wing's front, and one on each flank
  blade(k, r, -hw0 + 0.14, 1.3, H * 0.62, hw0, 0.3, [0xff2e9a, 0xff2e9a, 0xffa020]);
  k.turned(Math.PI / 2, () => blade(k, r, 0.5, H * 0.3, H * 0.8, hw0, 0.3, [0x22e0ff, 0x22e0ff, 0x5aff7a]));
  k.turned(-Math.PI / 2, () => blade(k, r, -0.3, H * 0.2, H * 0.55, hw0, 0.26, [0xffa020, 0xff3040]));
  // the billboard high on the right wing: a mosaic of light in a dark frame
  {
    const hw = hwAt(1), bx = (slot + hw) / 2, bw = hw - slot - 0.08, y0 = th + 0.5, bh = th * 0.55, nx = 3, ny = 6;
    k.box(bx, y0 - 0.05, hw + 0.035, bw + 0.08, bh + 0.1, 0.07, DARK);
    for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) {
      const c = any(r, [0xff2e9a, 0x22e0ff, 0xff2e9a, 0xffe08a, 0x9a5aff, 0x22e0ff]);
      k.glowBox(bx - bw / 2 + (bw / nx) * (i + 0.5), y0 + (bh / ny) * j, hw + 0.075, bw / nx, bh / ny, 0.014, mix(c, GREY, 0.45), [7, 30.5, 1.3], c);
    }
  }
  // external lift shafts, a line of light up each, and pipe runs up the back
  for (const [s, z] of [[-1, -0.35], [1, 0.45], [1, -0.7]] as const) {
    k.box(s * (hw0 + 0.04), 0, z, 0.14, H * 0.97, 0.2, hex(0x3a3f48));
    k.glowBox(s * (hw0 + 0.115), 0.5, z, 0.014, H * 0.97 - 0.6, 0.04, dull(CYAN), NEON_HOURS, CYAN);
  }
  for (const [x, f] of [[-0.7, 0.85], [-0.58, 0.6], [0.5, 0.9], [0.8, 0.45]] as const) k.cyl(x, 0, -hw0 - 0.03, 0.04, H * f, hex(0x6a4a3a), 6);
  k.bar([-0.7, H * 0.5, -hw0 - 0.05], [0.8, H * 0.42, -hw0 - 0.05], 0.03, hex(0x5a5048));
  // the roof: a landing pad, vent stacks with red lights, plant
  const ht = hwAt(tiers - 1), padX = 0.25, padZ = (sb - ht) / 2;
  k.cyl(padX, H, padZ, 0.42, 0.08, hex(0x3c4048), 12);
  k.cyl(padX, H + 0.08, padZ, 0.33, 0.008, hex(0xe8c040), 12);
  k.cyl(padX, H + 0.088, padZ, 0.27, 0.008, hex(0x3c4048), 12);
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + 0.4;
    k.glowBox(padX + Math.cos(a) * 0.4, H + 0.08, padZ + Math.sin(a) * 0.4, 0.04, 0.03, 0.04, dull(CYAN), NEON_HOURS, CYAN);
  }
  const vents: [number, number, number][] = [[-ht + 0.2, -ht + 0.2, 0.9], [-ht + 0.45, -ht + 0.25, 0.6], [-ht + 0.22, ht - 0.25, 0.75], [ht - 0.2, ht - 0.22, 1.0], [ht - 0.22, -ht + 0.18, 0.5]];
  for (const [x, z, h] of vents) {
    k.cyl(x, H, z, 0.08, h, hex(0x3a3d44), 6);
    k.glowBox(x, H + h, z, 0.05, 0.05, 0.05, hex(0x8a2a22), BEACON, hex(0xff3b30));
  }
  k.box(-ht + 0.35, H, 0.2, 0.4, 0.2, 0.5, hex(0x3a3d44));
  k.box(ht - 0.3, H, 0.25, 0.3, 0.14, 0.3, hex(0x44484f));
  // the foot: little shops jammed against every wall, awnings and signs
  const walls = [0x5a5048, 0x4a5258, 0x6a5a4a, 0x50584a, 0x5a4a52], tarps = [0x2a6ab0, 0xc04a2a, 0x3a9a5a, 0xd8b030, 0x8a3aa0];
  for (let f = 0; f < 4; f++) k.turned((f * Math.PI) / 2, () => {
    const n = 7, cell = (hw0 * 2) / n;
    for (let i = 0; i < n; i++) {
      const x = -hw0 + cell * (i + 0.5);
      if (f === 0 && Math.abs(x) < slot) continue;
      const d = 0.16 + r() * 0.1, h = 0.22 + r() * 0.2, z = hw0 + d / 2;
      k.box(x, 0, z, cell - 0.02, h, d, any(r, walls), hex(0x3a3d44));
      k.pane(x, 0.03, hw0 + d, cell * 0.6, 0.11, 1, hex(0x6a6458), [17, 25 + r() * 5, 1.4], r() < 0.6 ? hex(0xffd9a0) : hex(0xa0f0ff));
      if (r() < 0.6) k.box(x, 0.16, hw0 + d + 0.04, cell - 0.04, 0.02, 0.09, scale(any(r, tarps), 0.8));
      const c = any(r, NEONS);
      if (r() < 0.7) k.glowBox(x + (r() - 0.5) * 0.1, h + 0.01, hw0 + d - 0.03, cell * (0.3 + r() * 0.4), 0.06 + r() * 0.08, 0.025, dull(c), NEON_HOURS, c);
    }
  });
};

/**
 * The corporate spire: stacked blocks of black glass, the middle one turned a little, the top one set
 * back to leave a terrace where a hologram turns in the air after dark (a pale frame by day); thin
 * lines of cyan up its whole height, a band of magenta every ten floors, twin masts and a sky-bridge stub.
 */
const holoTower: Draw = (k, W, D, b, r) => {
  const H = Math.max(40, b.floors) * FLOOR, a = Math.min(W, D) - 0.5;
  const yA = H * 0.42, yB = H * 0.74, yC = H * 0.93;
  const block = (yaw: number, y0: number, y1: number, w: number, d: number, zc: number) => k.turned(yaw, () => {
    k.box(0, y0, zc, w, y1 - y0, d, GLASS_BLACK, BLOCK_ROOF);
    for (const s of [-1, 1]) {
      for (const q of [-1, 1]) {
        k.glowBox(s * w * 0.3, y0, zc + q * (d / 2 + 0.004), 0.03, y1 - y0, 0.012, dull(CYAN), NEON_HOURS, CYAN);
        k.glowBox(q * (w / 2 + 0.004), y0, zc + s * d * 0.3, 0.012, y1 - y0, 0.03, dull(CYAN), NEON_HOURS, CYAN);
      }
    }
    for (let y = Math.ceil((y0 + 0.2) / (10 * FLOOR)) * 10 * FLOOR; y < y1 - 0.15; y += 10 * FLOOR) {
      k.glowBox(0, y, zc, w + 0.034, 0.07, d + 0.034, dull(MAGENTA), NEON_HOURS, MAGENTA);
    }
    // a few offices working late
    const nx = Math.max(2, Math.floor(w / 0.2)), nz = Math.max(2, Math.floor(d / 0.2));
    for (let y = y0 + 0.4; y < y1 - 0.2; y += FLOOR) for (let f = 0; f < 4; f++) {
      if (r() > 0.3) continue;
      const along = f === 1 || f === 3, n = along ? nx : nz, len = along ? w : d, u = -len / 2 + (len * (Math.floor(r() * n) + 0.5)) / n;
      if (Math.abs(Math.abs(u) - len * 0.3) < 0.09) continue;
      const px = along ? u : (f === 0 ? w / 2 : -w / 2), pz = along ? zc + (f === 1 ? d / 2 : -d / 2) : zc + u;
      k.pane(px, y, pz, 0.13, 0.1, f, hex(0x2a3440), [17, 22 + r() * 8, 1.3], r() < 0.7 ? hex(0xd8f0ff) : CYAN);
    }
  });
  // the podium and its door
  k.box(0, 0, 0, a + 0.2, 0.36, a + 0.2, hex(0x1c1e24), BLOCK_ROOF);
  k.pane(0, 0.03, a / 2 + 0.1, 0.5, 0.26, 1, hex(0x3a4a58), NEON_HOURS, hex(0xd8f0ff));
  k.box(0, 0.3, a / 2 + 0.16, 0.7, 0.03, 0.14, hex(0x2a2d34));
  k.glowBox(0, 0.285, a / 2 + 0.2, 0.66, 0.015, 0.03, dull(CYAN), NEON_HOURS, CYAN);
  block(0, 0.36, yA, a, a, 0);
  block(0.16, yA, yB, a * 0.84, a * 0.84, 0);
  const cd = a * 0.42, cz = -a * 0.42 + cd / 2 + 0.04;
  block(0, yB, yC, a * 0.7, cd, cz);
  block(0, yC, yC + 0.5, a * 0.5, cd * 0.7, cz);
  // twin masts, braced, a red light on each
  const my = yC + 0.5;
  for (const [s, h] of [[-1, 1.7], [1, 1.25]] as const) {
    const x = s * a * 0.14;
    k.cyl(x, my, cz, 0.035, h * 0.55, hex(0x3a3f48), 6);
    k.bar([x, my + h * 0.55, cz], [x, my + h, cz], 0.012, METAL);
    k.glowBox(x, my + h, cz, 0.05, 0.05, 0.05, hex(0x8a2a22), BEACON, hex(0xff3b30));
  }
  k.bar([-a * 0.14, my + 0.45, cz], [a * 0.14, my + 0.45, cz], 0.012, METAL);
  // the hologram on the terrace: a ring and a standing figure drawn in scanlines, turning slowly
  const hy = yB + 1.3, hz = cz + cd / 2 + 0.56, HR = 0.52;
  for (const s of [-1, 1]) {
    k.box(s * 0.3, yB, hz, 0.1, 0.07, 0.1, hex(0x2a2d34));
    k.glowBox(s * 0.3, yB + 0.07, hz, 0.014, hy - HR - yB - 0.1, 0.014, HOLO_DAY, NEON_HOURS, HOLO);
  }
  k.spin(0, hy, hz, 'y', 0.35, (s) => {
    const n = 16;
    for (let i = 0; i < n; i++) {
      const an = (i / n) * TAU;
      s.glowBox(Math.cos(an) * HR, Math.sin(an) * HR - 0.03, 0, 0.09, 0.07, 0.02, HOLO_DAY, NEON_HOURS, HOLO);
    }
    const widths = [0.42, 0.37, 0.31, 0.25, 0.2, 0.25, 0.32, 0.37, 0.09, 0.16, 0.16];
    widths.forEach((w, i) => s.glowBox(0, -0.39 + i * 0.07, 0, w, 0.04, 0.02, HOLO_DAY, NEON_HOURS, HOLO_PINK));
  });
  // the sky-bridge stub, waiting for the tower next door
  const sy = H * 0.3;
  k.box(a / 2 + 0.11, sy, 0.1, 0.22, 0.17, 0.3, hex(0x23262d), BLOCK_ROOF);
  for (const f of [1, 3]) k.pane(a / 2 + 0.11, sy + 0.05, 0.1 + (f === 1 ? 0.15 : -0.15), 0.18, 0.07, f, hex(0x3a4a58), NEON_HOURS, CYAN);
  k.pane(a / 2 + 0.22, sy + 0.04, 0.1, 0.22, 0.1, 0, hex(0x3a4a58), NEON_HOURS, hex(0xd8f0ff));
};

/** A plain glowing sign in one of six shapes (no letters), standing on y facing +z. */
function signShape(k: Kit, kind: number, x: number, y: number, z: number, s: number, c: RGB): void {
  const day = dull(c);
  const g = (dx: number, dy: number, w: number, h: number, dz = 0) => k.glowBox(x + dx, y + dy, z + dz, w, h, 0.025, day, NEON_HOURS, c);
  switch (kind % 6) {
    case 0: g(0, 0, s, s * 0.42); break;
    case 1: g(0, 0, s * 0.36, s * 1.15); break;
    case 2: g(0, s * 0.25, s * 0.9, s * 0.3); g(0, 0, s * 0.3, s * 0.8, 0.004); break;
    case 3: g(0, 0, s * 0.9, s * 0.2); g(0, s * 0.22, s * 0.6, s * 0.2); g(0, s * 0.44, s * 0.3, s * 0.2); break;
    case 4: g(0, 0, s * 0.8, s * 0.12); g(0, s * 0.58, s * 0.8, s * 0.12); g(-s * 0.34, s * 0.12, s * 0.12, s * 0.46); g(s * 0.34, s * 0.12, s * 0.12, s * 0.46); break;
    default: g(-s * 0.12, s * 0.15, s * 0.6, s * 0.22); g(s * 0.3, 0, s * 0.22, s * 0.52); break;
  }
}

/**
 * The night market: a row of hole-in-the-wall shops and food stalls under a tangle of cables, each with
 * its own neon sign, tarps and awnings in clashing colours, paper lanterns on a string, stools, crates,
 * steam off the woks and a vending machine. Dull clutter by day; all colour after dark.
 */
const nightMarket: Draw = (k, W, D, _b, r) => {
  k.box(0, 0, 0, W - 0.06, 0.02, D - 0.06, WET);
  for (const [x, z, s] of [[-0.8, 0.22, 0.2], [0.35, 0.3, 0.26], [1.05, 0.16, 0.16]] as const) k.cyl(x, 0.02, z, s, 0.004, PUDDLE, 8, PUDDLE, s * 0.45);
  const n = Math.max(4, Math.round((W - 0.2) / 0.35)), cell = (W - 0.2) / n, depth = Math.min(0.36, D * 0.36), zc = -D / 2 + 0.08 + depth / 2, fz = zc + depth / 2;
  const walls = [0x5a5048, 0x4a5258, 0x6a5a4a, 0x50584a, 0x5a4a52, 0x605c54], tarps = [0x2a6ab0, 0xc04a2a, 0x3a9a5a, 0xd8b030, 0x8a3aa0, 0xd8d0c0];
  const plastic = [0x2f7fb5, 0xc83a2e, 0x3a9a5a];
  const tops: number[] = [];
  for (let i = 0; i < n; i++) {
    const x = -W / 2 + 0.1 + cell * (i + 0.5), h = 0.36 + r() * 0.2, food = i % 3 === 1;
    tops.push(h);
    k.box(x, 0, zc, cell - 0.03, h, depth, any(r, walls), hex(0x6a6e70));
    // the open front, lit from inside
    const inside = food ? hex(0xffc070) : any(r, [0xfff0c0, 0xa0f0ff, 0xffb0e0, 0xc8ffb0]);
    k.pane(x, 0.04, fz, cell * 0.74, 0.2, 1, hex(0x2a2622), NEON_HOURS, inside);
    // a tarp or awning out over the lane
    const t = scale(any(r, tarps), 0.78), y1 = 0.3 + r() * 0.04, y2 = 0.21 + r() * 0.05, out = 0.16 + r() * 0.08, hwid = cell * 0.47;
    const q: P3[] = [[x - hwid, y1, fz], [x + hwid, y1, fz], [x + hwid, y2, fz + out], [x - hwid, y2, fz + out]];
    k.quad(q[0], q[1], q[2], q[3], t, [x, y1 - 1, fz]);
    k.quad(q[0], q[1], q[2], q[3], scale(t, 0.7), [x, y1 + 1, fz + out]);
    for (const s of [-1, 1]) k.box(x + s * hwid * 0.9, 0.02, fz + out - 0.01, 0.012, y2 - 0.02, 0.012, METAL);
    // the sign on the roof's edge, every one a different shape and colour
    signShape(k, i + Math.floor(r() * 6), x + (r() - 0.5) * 0.06, h + 0.01, fz - 0.04, cell * 0.62, hex(NEONS[(i * 5 + Math.floor(r() * 2)) % NEONS.length]));
    // a vent pipe on some roofs
    if (i % 2 === 0) { k.cyl(x + cell * 0.25, h, zc - 0.06, 0.025, 0.16, hex(0x6a4a3a), 6); k.cyl(x + cell * 0.25, h + 0.16, zc - 0.06, 0.04, 0.025, hex(0x3a3d44), 6); }
    if (food) {
      // a food stall: the counter out front, steam off it, stools
      k.box(x, 0.02, fz + 0.09, cell * 0.7, 0.11, 0.08, hex(0x8a8e90), METAL);
      puffs(k, x, 0.32, fz + 0.1, 0.05, hex(0xd8dcdc), 3);
      for (let j = 0; j < 3; j++) k.cyl(x - cell * 0.3 + j * cell * 0.3, 0.02, fz + 0.22 + (j % 2) * 0.03, 0.028, 0.06, hex(plastic[(i + j) % plastic.length]), 6);
    } else if (i % 3 === 0) {
      // goods stacked outside
      for (let j = 0; j < 2; j++) k.box(x - 0.05 + j * 0.1, 0.02, fz + 0.1, 0.09, 0.07 + j * 0.05, 0.09, hex(j ? 0x8d6d48 : 0x3a7a8a));
    }
  }
  // poles along the lane with a tangle of cables between them and down to the roofs
  const pz = D / 2 - 0.14, poles = [-W / 2 + 0.1, -W / 6, W / 6, W / 2 - 0.1], ph = 0.82;
  for (const x of poles) k.box(x, 0, pz, 0.035, ph, 0.035, hex(0x3a3d44));
  for (let i = 0; i < poles.length - 1; i++) {
    const x0 = poles[i], x1 = poles[i + 1], xm = (x0 + x1) / 2;
    for (const [dy, sag, dz] of [[0, 0.09, 0], [-0.08, 0.05, 0.02], [-0.16, 0.1, -0.02]] as const) {
      k.bar([x0, ph + dy, pz + dz], [xm, ph + dy - sag, pz + dz], 0.006, DARK);
      k.bar([xm, ph + dy - sag, pz + dz], [x1, ph + dy, pz + dz], 0.006, DARK);
    }
  }
  for (let i = 0; i < n; i++) {
    const x = -W / 2 + 0.1 + cell * (i + 0.5), p = poles.reduce((best, q) => (Math.abs(q - x) < Math.abs(best - x) ? q : best));
    k.bar([p, ph - 0.04 - (i % 3) * 0.05, pz], [x + (i % 2 ? 0.08 : -0.08), tops[i], fz - 0.05], 0.006, DARK);
  }
  // pipes along the back of the row
  k.bar([-W / 2 + 0.12, 0.3, -D / 2 + 0.06], [W / 2 - 0.12, 0.34, -D / 2 + 0.06], 0.02, hex(0x6a4a3a));
  k.bar([-W / 2 + 0.12, 0.2, -D / 2 + 0.06], [W / 2 - 0.4, 0.2, -D / 2 + 0.06], 0.014, hex(0x50584a));
  // red paper lanterns strung the length of the lane
  const ly = 0.56, lz = fz + 0.2;
  k.bar([-W / 2 + 0.1, ly + 0.09, lz], [W / 2 - 0.1, ly + 0.09, lz], 0.005, DARK);
  for (const x of [-W / 2 + 0.1, W / 2 - 0.1]) k.bar([x, ly + 0.09, lz], [x, ph - 0.2, pz], 0.005, DARK);
  for (let x = -W / 2 + 0.2; x < W / 2 - 0.15; x += 0.19) k.glowBox(x, ly, lz, 0.055, 0.075, 0.055, hex(0xa83a2a), NEON_HOURS, hex(0xff4a30));
  // the vending machine at one end, crates at the other
  const vx = W / 2 - 0.2;
  k.box(vx, 0.02, 0.22, 0.15, 0.3, 0.12, hex(0x3a5a7a));
  k.glowBox(vx, 0.07, 0.285, 0.115, 0.21, 0.012, hex(0x9ab0b8), [16.5, 31, 1.4], hex(0xb8f4ff));
  const cx = -W / 2 + 0.2;
  k.box(cx, 0.02, 0.2, 0.13, 0.1, 0.13, hex(0x8d6d48));
  k.box(cx + 0.02, 0.12, 0.2, 0.11, 0.09, 0.11, hex(0x3a7a8a));
  k.box(cx + 0.15, 0.02, 0.24, 0.11, 0.08, 0.11, hex(0xc04a2a));
};

